import type { ExtendedExerciseRecord } from './types';

export const EXTENDED_EXERCISE_RECORDS: ExtendedExerciseRecord[] = [{"id":"ex-1-2-kneeling-thoracic-rotation","slug":"1-2-kneeling-thoracic-rotation","name":"1/2 Kneeling Thoracic Rotation","description":"Bodyweight exercise for the core.","instructions":["Begin in a half kneeling position with the","leg away from the wall stabilized against the wall","with a ball.","With both hands directly in front of","you, rotate one arm open attempting to reach","the wall behind you.","Exhale as you rotate, inhale","as you return to neutral and repeat."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["1/2 kneeling thoracic rotation","brustwirbelsäulen-rotation im halben kniestand"],"media":[],"source":"wger","de":{"name":"Brustwirbelsäulen-Rotation im halben Kniestand","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Beginne im halben Kniestand, wobei das von der Wand abgewandte","Bein mit einem Ball an der Wand stabilisiert","wird.","Halte beide Hände direkt vor","dir und drehe einen Arm geöffnet auf, um","die Wand hinter dir zu erreichen.","Atme beim Drehen aus, atme ein,","wenn du in die neutrale Position zurückkehrst, und wiederhole."]}},{"id":"ex-1-leg-box-squat","slug":"1-leg-box-squat","name":"1 Leg Box Squat","description":"Bodyweight exercise for the hamstrings, with quadriceps assisting.","instructions":["This exercise requires a sturdy box or a chair. Simple stand ~6 inches in front of it and balance yourself on one leg. From here, begin squatting down in a smooth controlled motion while keeping your other leg straight out in front of you for balance. Slowly sit down on the box, pause for a 1 count and push back up with the working leg, while never letting your other leg touch the ground."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["QUADRICEPS"],"equipment":"BODYWEIGHT","tags":["1 leg box squat","einbeinige box-kniebeuge"],"media":[],"source":"wger","de":{"name":"Einbeinige Box-Kniebeuge","description":"Übung (Körpergewicht) für die Oberschenkelrückseite, unterstützt von Oberschenkelvorderseite.","instructions":["Für diese Übung benötigst du eine stabile Box oder einen Stuhl. Stelle dich einfach etwa 15 cm davor und balanciere auf einem Bein. Beginne von hier aus in einer gleichmäßigen, kontrollierten Bewegung herunterzugehen, während du dein anderes Bein zur Balance gerade vor dir ausstreckst. Setze dich langsam auf die Box, halte eine Sekunde inne und drücke dich mit dem arbeitenden Bein wieder hoch, ohne dass dein anderes Bein jemals den Boden berührt."]}},{"id":"ex-3-4-sit-up","slug":"3-4-sit-up","name":"3/4 Sit-Up","description":"Bodyweight exercise for the core.","instructions":["Lie down on the floor and secure your feet. Your legs should be bent at the knees.","Place your hands behind or to the side of your head. You will begin with your back on the ground. This will be your starting position.","Flex your hips and spine to raise your torso toward your knees.","At the top of the contraction your torso should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["3/4 sit-up"],"media":[{"id":"3-4-sit-up-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/3_4_Sit-Up/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"3-4-sit-up-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/3_4_Sit-Up/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-4-count-burpees","slug":"4-count-burpees","name":"4-count burpees","description":"Bodyweight exercise for the chest.","instructions":["Starting position:","Stand straight, feet hip-width apart.","Steps:","Squat low and support yourself on the floor with your hands between the knees and in front of your feet, your back straight.","Keeping your hands on the floor, jump your legs backward into high plank position.","Jump your feet forward to return to the squat position.","Repeat."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["4-count burpees","burpees mit 4 zählzeiten"],"media":[],"source":"wger","de":{"name":"Burpees mit 4 Zählzeiten","description":"Übung (Körpergewicht) für die Brust.","instructions":["Ausgangsposition:","Gerade stehen, Füße hüftbreit auseinander.","Schritte:","Gehen Sie in die Hocke und stützen Sie sich mit den Händen zwischen den Knien und vor den Füßen mit geradem Rücken auf dem Boden ab.","Lassen Sie die Hände auf dem Boden und springen Sie mit den Beinen nach hinten in eine hohe Plank-Position.","Springen Sie mit den Füßen nach vorne, um wieder in die Hocke zu gehen.","Wiederholen Sie die Übung."]}},{"id":"ex-ab-roller","slug":"ab-roller","name":"Ab Roller","description":"Accessory exercise for the core, with shoulders assisting.","instructions":["Hold the Ab Roller with both hands and kneel on the floor.","Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.","Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.","After a pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["SHOULDERS"],"equipment":"OTHER","tags":["ab roller"],"media":[{"id":"ab-roller-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ab_Roller/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"ab-roller-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ab_Roller/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rumpf, unterstützt von Schultern.","instructions":null}},{"id":"ex-ab-wheel","slug":"ab-wheel","name":"Ab wheel","description":"Bodyweight exercise for the core, with chest assisting.","instructions":["Starting Position: Kneel on the floor with the ab wheel in front of you.","Grip the Wheel: Hold the handles firmly.","Roll Out: Slowly roll the wheel forward, extending your body while keeping your core tight.","Return: Pull the wheel back towards your knees, maintaining tension in your core."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["CHEST"],"equipment":"BODYWEIGHT","tags":["ab wheel","bauchroller"],"media":[{"id":"ab-wheel-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1573/a9ab402b-61ef-4d60-b91a-df52bf7f41a9.jpg","caption":"Ab wheel","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Bauchroller","description":"Übung (Körpergewicht) für den Rumpf, unterstützt von Brust.","instructions":["Ausgangsposition: Knie dich auf den Boden, mit dem Bauchroller vor dir.","Greife den Roller: Halte die Griffe fest.","Ausrollen: Rolle den Roller langsam nach vorn und strecke deinen Körper aus, während du den Rumpf angespannt hältst.","Zurückkehren: Ziehe den Roller wieder zurück zu deinen Knien und halte die Spannung im Rumpf."]}},{"id":"ex-abdominal-crunch","slug":"abdominal-crunch","name":"Abdominal Crunch","description":"Bodyweight exercise for the core, with chest assisting.","instructions":["The Abdominal Crunch is a classic core isolation exercise performed on the floor or a mat. Unlike a full sit-up, it involves a smaller range of motion where you only lift your shoulders and upper back off the ground, keeping your lower back pressed firmly against the floor."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["CHEST"],"equipment":"BODYWEIGHT","tags":["abdominal crunch","bauchcrunch"],"media":[],"source":"wger","de":{"name":"Bauchcrunch","description":"Übung (Körpergewicht) für den Rumpf, unterstützt von Brust.","instructions":["Der Bauchcrunch ist eine klassische Isolationsübung für den Rumpf, die auf dem Boden oder einer Matte ausgeführt wird. Anders als bei einem vollständigen Sit-up ist der Bewegungsumfang kleiner: Du hebst nur die Schultern und den oberen Rücken vom Boden ab und drückst den unteren Rücken fest gegen den Boden."]}},{"id":"ex-abdominal-draw-in","slug":"abdominal-draw-in","name":"Abdominal Draw-In","description":"Bodyweight exercise for the core.","instructions":["Lie","on your back with knees bent. Gently pull your belly button toward your","spine without moving your hips or holding your breath."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["abdominal draw-in","bauchnabel einziehen"],"media":[],"source":"wger","de":{"name":"Bauchnabel einziehen","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Lege dich auf den Rücken, mit gebeugten Knien. Ziehe deinen Bauchnabel sanft in Richtung Wirbelsäule, ohne deine Hüften zu bewegen oder die Luft anzuhalten."]}},{"id":"ex-abduction-while-standing","slug":"abduction-while-standing","name":"Abduction while standing","description":"Bodyweight exercise for the quadriceps.","instructions":["Training a stable stance, predominantly on one leg, is crucial for both sides. On the one hand, it prevents discomfort and, on the other, it establishes a stable foundation. The practitioner assumes the usual standing position and, with a stable upper body, attempts to repeatedly lift the unloaded leg, bend it at the hip and knee, and then lower it again. The movement is also repeated on the other side. The exercise trains the stability of the hip-surrounding muscles."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["abduction while standing","abduktion im stand"],"media":[],"source":"wger","de":{"name":"Abduktion im Stand","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite.","instructions":["Das Training des stabilen Standes dominat auf einem Bein ist beiseitig entscheidend. Einerseits um Beschwerden vorzubeugen und andererseits um eine stabile Basis zu legen.Die übende Person stellt sich in die gewohnte Standposition und versucht bei stabilem Oberkörper das unbelastete Bein wiederholt zu heben und und in Hüfte und Knie zu beugen und wieder zu senken. Die Bewegung wird jedenfalls auch mit der anderen Seite wiederholt. Die Übung trainiert die Stabilität der hüftumgebenden Muskulatur"]}},{"id":"ex-adductor","slug":"adductor","name":"Adductor","description":"Foam roller exercise for the quadriceps.","instructions":["Lie face down with one leg on a foam roll.","Rotate the leg so that the foam roll contacts against your inner thigh. Shift as much weight onto the foam roll as can be tolerated.","While trying to relax the muscles if the inner thigh, roll over the foam between your hip and knee, holding points of tension for 10-30 seconds. Repeat with the other leg."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"FOAM_ROLLER","tags":["adductor"],"media":[{"id":"adductor-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Adductor/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"adductor-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Adductor/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Faszienrolle) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-adductor-groin","slug":"adductor-groin","name":"Adductor/Groin","description":"Equipment-free exercise for the quadriceps.","instructions":["Lie on your back with your feet raised towards the ceiling.","Have your partner hold your feet or ankles. Abduct your legs as far as you can. This will be your starting position.","Attempt to squeeze your legs together for 10 or more seconds, while your partner prevents you from doing so.","Now, relax the muscles in your legs as your partner pushes your feet apart, stretching as far as is comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"NONE","tags":["adductor/groin"],"media":[{"id":"adductor-groin-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Adductor_Groin/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"adductor-groin-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Adductor_Groin/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-advanced-kettlebell-windmill","slug":"advanced-kettlebell-windmill","name":"Advanced Kettlebell Windmill","description":"Kettlebell exercise for the core, with glutes, hamstrings, shoulders assisting.","instructions":["Clean and press a kettlebell overhead with one arm.","Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Keep the non-working arm behind your back and turn your feet out at a forty-five degree angle from the arm with the kettlebell.","Lower yourself as far as possible.","Pause for a second and reverse the motion back to the starting position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["GLUTES","HAMSTRINGS","SHOULDERS"],"equipment":"KETTLEBELL","tags":["advanced kettlebell windmill"],"media":[{"id":"advanced-kettlebell-windmill-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Advanced_Kettlebell_Windmill/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"advanced-kettlebell-windmill-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Advanced_Kettlebell_Windmill/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für den Rumpf, unterstützt von Po, Oberschenkelrückseite, Schultern.","instructions":null}},{"id":"ex-air-bike","slug":"air-bike","name":"Air Bike","description":"Bodyweight exercise for the core.","instructions":["Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.","Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position.","Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out.","Go back to the initial position as you breathe in.","Crunch to the opposite side as you cycle your legs and bring closer your left elbow to your right knee and exhale.","Continue alternating in this manner until all of the recommended repetitions for each side have been completed."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["air bike"],"media":[{"id":"air-bike-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Air_Bike/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"air-bike-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Air_Bike/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-all-fours-quad-stretch","slug":"all-fours-quad-stretch","name":"All Fours Quad Stretch","description":"Bodyweight exercise for the quadriceps.","instructions":["Start off on your hands and knees, then lift your leg off the floor and hold the foot with your hand.","Use your hand to hold the foot or ankle, keeping the knee fully flexed, stretching the quadriceps and hip flexors.","Focus on extending your hips, thrusting them towards the floor. Hold for 10-20 seconds and then switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["all fours quad stretch"],"media":[{"id":"all-fours-quad-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/All_Fours_Quad_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"all-fours-quad-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/All_Fours_Quad_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-alternate-hammer-curl","slug":"alternate-hammer-curl","name":"Alternate Hammer Curl","description":"Dumbbell exercise for the biceps, with forearms assisting.","instructions":["Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.","The palms of the hands should be facing your torso. This will be your starting position.","While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.","Slowly begin to bring the dumbbells back to starting position as your breathe in.","Repeat the movement with the left hand. This equals one repetition.","Continue alternating in this manner for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"DUMBBELL","tags":["alternate hammer curl"],"media":[{"id":"alternate-hammer-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Hammer_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"alternate-hammer-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Hammer_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps, unterstützt von Unterarme.","instructions":null}},{"id":"ex-alternate-incline-dumbbell-curl","slug":"alternate-incline-dumbbell-curl","name":"Alternate Incline Dumbbell Curl","description":"Dumbbell exercise for the biceps, with forearms assisting.","instructions":["Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position.","While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.","Slowly begin to bring the dumbbell back to starting position as your breathe in.","Repeat the movement with the left hand. This equals one repetition.","Continue alternating in this manner for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"DUMBBELL","tags":["alternate incline dumbbell curl"],"media":[{"id":"alternate-incline-dumbbell-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Incline_Dumbbell_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"alternate-incline-dumbbell-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Incline_Dumbbell_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps, unterstützt von Unterarme.","instructions":null}},{"id":"ex-alternate-leg-diagonal-bound","slug":"alternate-leg-diagonal-bound","name":"Alternate Leg Diagonal Bound","description":"Equipment-free exercise for the quadriceps, with glutes, calves, hamstrings assisting.","instructions":["Assume a comfortable stance with one foot slightly in front of the other.","Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound.","It may help to use a line on the ground to guage distance from side to side.","Repeat the sequence with the other leg."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","CALVES","HAMSTRINGS"],"equipment":"NONE","tags":["alternate leg diagonal bound"],"media":[{"id":"alternate-leg-diagonal-bound-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Leg_Diagonal_Bound/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"alternate-leg-diagonal-bound-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Leg_Diagonal_Bound/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelvorderseite, unterstützt von Po, Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-alternating-bicep-curls","slug":"alternating-bicep-curls","name":"Alternating bicep curls","description":"Dumbbell exercise for the biceps.","instructions":["Starting position:","Start standing up with dumbbells in each hand, your back straight and feet hip-width apart. Your arms should be relaxed, pointing down. Your knees should be slightly bent, your abs contracted, and your shoulders down.","Steps:","Bend one arm at the elbow, bringing the dumbbell up to your shoulder. Your upper arm should remain motionless during this movement.","Bring the dumbbell back down until your arm is in its original relaxed position.","Repeat, switching arms."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["alternating bicep curls","abwechselnde bizepscurls"],"media":[{"id":"alternating-bicep-curls-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1012/8270fdb8-28f1-4eff-b410-af8642085b3f.png","caption":"Alternating bicep curls","attribution":"wger.de · Franpol","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Abwechselnde Bizepscurls","description":"Übung (Kurzhantel) für den Bizeps.","instructions":["Ausgangsposition:","Beginnen Sie im Stehen mit Kurzhanteln in jeder Hand, mit geradem Rücken und hüftbreit auseinander stehenden Füßen. Die Arme sind entspannt und zeigen nach unten. Die Knie sollten leicht gebeugt, die Bauchmuskeln angespannt und die Schultern nach unten gerichtet sein.","Die Schritte:","Beugen Sie einen Arm am Ellenbogen und führen Sie die Hantel bis zur Schulter. Ihr Oberarm sollte während dieser Bewegung unbeweglich bleiben.","Bringen Sie die Hantel wieder nach unten, bis sich Ihr Arm in seiner ursprünglichen, entspannten Position befindet.","Wiederholen Sie die Übung mit dem anderen Arm."]}},{"id":"ex-alternating-cable-shoulder-press","slug":"alternating-cable-shoulder-press","name":"Alternating Cable Shoulder Press","description":"Cable exercise for the shoulders, with triceps assisting.","instructions":["Move the cables to the bottom of the tower and select an appropriate weight.","Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.","Keeping your head and chest up, extend through the elbow to press one side directly over head.","After pausing at the top, return to the starting position and repeat on the opposite side."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"CABLE","tags":["alternating cable shoulder press"],"media":[{"id":"alternating-cable-shoulder-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Cable_Shoulder_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"alternating-cable-shoulder-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Cable_Shoulder_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-alternating-deltoid-raise","slug":"alternating-deltoid-raise","name":"Alternating Deltoid Raise","description":"Dumbbell exercise for the shoulders.","instructions":["In a standing position, hold a pair of dumbbells at your side.","Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating.","Return the weights to your side.","On the next repetition, raise the weights laterally, raising them out to your side to about shoulder height.","Return the weights to the starting position and continue alternating to the front and side."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["alternating deltoid raise"],"media":[{"id":"alternating-deltoid-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Deltoid_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"alternating-deltoid-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Deltoid_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern.","instructions":null}},{"id":"ex-alternating-floor-press","slug":"alternating-floor-press","name":"Alternating Floor Press","description":"Kettlebell exercise for the chest, with core, shoulders, triceps assisting.","instructions":["Lie on the floor with two kettlebells next to your shoulders.","Position one in place on your chest and then the other, gripping the kettlebells on the handle with the palms facing forward.","Extend both arms, so that the kettlebells are being held above your chest. Lower one kettlebell, bringing it to your chest and turn the wrist in the direction of the locked out kettlebell.","Raise the kettlebell and repeat on the opposite side."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["ABS_CORE","SHOULDERS","TRICEPS"],"equipment":"KETTLEBELL","tags":["alternating floor press"],"media":[{"id":"alternating-floor-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Floor_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"alternating-floor-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Floor_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Brust, unterstützt von Rumpf, Schultern, Trizeps.","instructions":null}},{"id":"ex-alternating-hang-clean","slug":"alternating-hang-clean","name":"Alternating Hang Clean","description":"Kettlebell exercise for the hamstrings, with biceps, calves, forearms, glutes, back assisting.","instructions":["Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.","Clean one kettlebell to your shoulder and hold on to the other kettlebell in a hanging position. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so.","Lower the cleaned kettlebell to a hanging position and clean the alternate kettlebell. Repeat."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["BICEPS","CALVES","FOREARMS","GLUTES","BACK"],"equipment":"KETTLEBELL","tags":["alternating hang clean"],"media":[{"id":"alternating-hang-clean-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Hang_Clean/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"alternating-hang-clean-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Hang_Clean/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Oberschenkelrückseite, unterstützt von Bizeps, Waden, Unterarme, Po, Rücken.","instructions":null}},{"id":"ex-alternating-high-cable-row","slug":"alternating-high-cable-row","name":"Alternating High Cable Row","description":"Cable exercise for the back.","instructions":["Start","by putting the attachment in a high position on the cable station and step back about 1m from the attachment. Grab","the cable pulley handle in your left hand at about head height with your elbow slightly bent. Step back with your left foot.","Pull","your elbow joint in toward the torso twisting slightly and perform a","single-arm row. Engage the lats as you twist.","Return","to the starting position with cable pulley and left foot and grab the cable pulley handle in the right"],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["alternating high cable row","abwechselndes hohes kabelrudern"],"media":[],"source":"wger","de":{"name":"Abwechselndes hohes Kabelrudern","description":"Übung (Kabelzug) für den Rücken.","instructions":["Beginne,","indem du den Aufsatz hoch an der Kabelstation positionierst und etwa 1 m vom Aufsatz zurücktrittst. Greife","den Griff des Kabelzugs mit der linken Hand auf etwa Kopfhöhe, mit leicht gebeugtem Ellbogen. Tritt mit dem linken Fuß zurück.","Ziehe","dein Ellbogengelenk zum Oberkörper hin, während du dich leicht drehst, und führe ein","einarmiges Rudern aus. Aktiviere den Latissimus, während du dich drehst.","Kehre","mit Kabelzug und linkem Fuß in die Ausgangsposition zurück und greife den Griff des Kabelzugs mit der"]}},{"id":"ex-alternating-kettlebell-press","slug":"alternating-kettlebell-press","name":"Alternating Kettlebell Press","description":"Kettlebell exercise for the shoulders, with triceps assisting.","instructions":["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.","Press one directly overhead by extending through the elbow, turning it so the palm faces forward while holding the other kettlebell stationary .","Lower the pressed kettlebell to the starting position and immediately press with your other arm."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"KETTLEBELL","tags":["alternating kettlebell press"],"media":[{"id":"alternating-kettlebell-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Kettlebell_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"alternating-kettlebell-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Kettlebell_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-alternating-kettlebell-row","slug":"alternating-kettlebell-row","name":"Alternating Kettlebell Row","description":"Kettlebell exercise for the back, with biceps assisting.","instructions":["Place two kettlebells in front of your feet. Bend your knees slightly and push your butt out as much as possible. As you bend over to get into the starting position grab both kettlebells by the handles.","Pull one kettlebell off of the floor while holding on to the other kettlebell. Retract the shoulder blade of the working side, as you flex the elbow, drawing the kettlebell towards your stomach or rib cage.","Lower the kettlebell in the working arm and repeat with your other arm."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"KETTLEBELL","tags":["alternating kettlebell row"],"media":[{"id":"alternating-kettlebell-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Kettlebell_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"alternating-kettlebell-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Kettlebell_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-alternating-renegade-row","slug":"alternating-renegade-row","name":"Alternating Renegade Row","description":"Kettlebell exercise for the back, with core, biceps, chest, triceps assisting.","instructions":["Place two kettlebells on the floor about shoulder width apart. Position yourself on your toes and your hands as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position your feet wide for support.","Push one kettlebell into the floor and row the other kettlebell, retracting the shoulder blade of the working side as you flex the elbow, pulling it to your side.","Then lower the kettlebell to the floor and begin the kettlebell in the opposite hand. Repeat for several reps."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["ABS_CORE","BICEPS","CHEST","TRICEPS"],"equipment":"KETTLEBELL","tags":["alternating renegade row"],"media":[{"id":"alternating-renegade-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Renegade_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"alternating-renegade-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Renegade_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für den Rücken, unterstützt von Rumpf, Bizeps, Brust, Trizeps.","instructions":null}},{"id":"ex-alternative-db-gorilla-rows","slug":"alternative-db-gorilla-rows","name":"Alternative DB Gorilla rows","description":"Dumbbell exercise for the back.","instructions":["Slightly bent down and knees to mimic a gorilla position and pull/row up the DBs to the chest. DB stay straight (thumbs pointing up)"],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["alternative db gorilla rows","alternatives gorilla-rudern mit kurzhanteln"],"media":[],"source":"wger","de":{"name":"Alternatives Gorilla-Rudern mit Kurzhanteln","description":"Übung (Kurzhantel) für den Rücken.","instructions":["Beuge dich leicht nach vorne und winkle die Knie an, um eine Gorilla-Position nachzuahmen, und ziehe bzw. rudere die Kurzhanteln zur Brust. Die Kurzhanteln bleiben gerade (Daumen zeigen nach oben)."]}},{"id":"ex-ankle-circles","slug":"ankle-circles","name":"Ankle Circles","description":"Equipment-free exercise for the calves.","instructions":["Use a sturdy object like a squat rack to hold yourself.","Lift the right leg in the air (just around 2 inches from the floor) and perform a circular motion with the big toe. Pretend that you are drawing a big circle with it. Tip: One circle equals 1 repetition. Breathe normally as you perform the movement.","When you are done with the right foot, then repeat with the left leg."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"NONE","tags":["ankle circles"],"media":[{"id":"ankle-circles-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ankle_Circles/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"ankle-circles-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ankle_Circles/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Waden.","instructions":null}},{"id":"ex-ankle-dorsiflexion-rocks","slug":"ankle-dorsiflexion-rocks","name":"ankle dorsiflexion rocks","description":"Bodyweight exercise for the calves.","instructions":["Move your knee forward, keeping your heel on the ground. Hold the position for a couple of seconds and return to the starting position."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["ankle dorsiflexion rocks","wippen in die sprunggelenk-dorsalflexion"],"media":[{"id":"ankle-dorsiflexion-rocks-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1804/691c69b8-c3db-4177-8435-dd3a97d88542.webp","caption":"ankle dorsiflexion rocks","attribution":"wger.de · Davidgj32","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Wippen in die Sprunggelenk-Dorsalflexion","description":"Übung (Körpergewicht) für die Waden.","instructions":["Bewege dein Knie nach vorne und halte dabei deine Ferse am Boden. Halte die Position einige Sekunden und kehre in die Ausgangsposition zurück."]}},{"id":"ex-anterior-tibialis-smr","slug":"anterior-tibialis-smr","name":"Anterior Tibialis-SMR","description":"Accessory exercise for the calves.","instructions":["Begin seated on the ground with your legs bent and your feet on the floor.","Using a Muscle Roller or a rolling pin, apply pressure to the muscles on the outside of your shins. Work from just below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat on the other leg."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["anterior tibialis-smr"],"media":[{"id":"anterior-tibialis-smr-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Anterior_Tibialis-SMR/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"anterior-tibialis-smr-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Anterior_Tibialis-SMR/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Waden.","instructions":null}},{"id":"ex-anti-gravity-press","slug":"anti-gravity-press","name":"Anti-Gravity Press","description":"Barbell exercise for the shoulders, with back, triceps assisting.","instructions":["Place a bar on the ground behind the head of an incline bench.","Lay on the bench face down. With a pronated grip, pick the barbell up from the floor. Flex the elbows, performing a reverse curl to bring the bar near your chest. This will be your starting position.","To begin, press the barbell out in front of your head by extending your elbows. Keep your arms parallel to the ground throughout the movement.","Return to the starting position and repeat to complete the set."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK","TRICEPS"],"equipment":"BARBELL","tags":["anti-gravity press"],"media":[{"id":"anti-gravity-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Anti-Gravity_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"anti-gravity-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Anti-Gravity_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Schultern, unterstützt von Rücken, Trizeps.","instructions":null}},{"id":"ex-arabesque","slug":"arabesque","name":"Arabesque","description":"Bodyweight exercise for the hamstrings, with glutes assisting.","instructions":["Take all your weight onto one leg and you're going to maintain that position, keeping your hips and pelvis level the whole time. With your back in a neutral position you want to tilt yourself forward kicking your leg back up and then slowly with your glutes bring yourself back up to neutral."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES"],"equipment":"BODYWEIGHT","tags":["arabesque","arabeske"],"media":[{"id":"arabesque-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1141/c7be1cd1-46c5-4a86-a114-5f0fe861c3e0.jpg","caption":"Arabesque","attribution":"wger.de · cleen","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Arabeske","description":"Übung (Körpergewicht) für die Oberschenkelrückseite, unterstützt von Po.","instructions":["Verlagere dein gesamtes Gewicht auf ein Bein und halte diese Position, wobei Hüfte und Becken die ganze Zeit über waagerecht bleiben. Halte deinen Rücken in einer neutralen Position und neige dich nach vorne, während du das andere Bein nach hinten oben streckst. Anschließend richtest du dich langsam mit der Kraft deiner Gesäßmuskulatur wieder in die neutrale Ausgangsposition auf."]}},{"id":"ex-archer-pull-up","slug":"archer-pull-up","name":"Archer Pull Up","description":"Bodyweight exercise for the back, with biceps assisting.","instructions":["An archer pull-up is an advanced bodyweight exercise that strengthens your back and biceps, serving as a progression towards a one-arm pull-up. It gets its name from the \"bow-drawing\" position your body takes at the top.Here's how to do it:","Grip: Grasp a pull-up bar with a wider-than-shoulder-width overhand grip.","Starting Position: Hang with arms fully extended, engaging your core and keeping your shoulder blades pulled down.","The Pull: Pull your body up towards one hand, similar to a regular pull-up. At the same time, extend the other arm out to the side, keeping it as straight as possible. Your chin should come towards the hand that is pulling.","Hold & Lower: Briefly hold the top position where one arm is bent and pulling, and the other is extended. Slowly lower yourself back to the starting position with control.","Alternate: Repeat the movement, pulling up towards the opposite hand.The key to this exercise is to keep the assisting arm as straight as possible to maximise the load on the working arm. This makes it a challenging but effective exercise for unilateral pulling strength."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"BODYWEIGHT","tags":["archer pull up","archer-klimmzug"],"media":[],"source":"wger","de":{"name":"Archer-Klimmzug","description":"Übung (Körpergewicht) für den Rücken, unterstützt von Bizeps.","instructions":["Der Archer-Klimmzug ist eine fortgeschrittene Körpergewichtsübung, die deinen Rücken und Bizeps kräftigt und als Vorstufe zum einarmigen Klimmzug dient. Seinen Namen verdankt er der „bogenspannenden\" Position, die dein Körper oben einnimmt. So führst du ihn aus:","Griff: Greife eine Klimmzugstange mit einem Obergriff, der breiter als schulterbreit ist.","Startposition: Hänge mit vollständig gestreckten Armen, spanne deine Rumpfmuskulatur an und halte deine Schulterblätter nach unten gezogen.","Der Zug: Ziehe deinen Körper zu einer Hand hoch, ähnlich wie bei einem normalen Klimmzug. Strecke gleichzeitig den anderen Arm zur Seite aus und halte ihn so gerade wie möglich. Dein Kinn sollte sich zur ziehenden Hand bewegen.","Halten & Absenken: Halte kurz die obere Position, in der ein Arm gebeugt ist und zieht und der andere gestreckt ist. Senke dich langsam und kontrolliert zurück in die Startposition.","Wechseln: Wiederhole die Bewegung und ziehe dich zur gegenüberliegenden Hand hoch. Der Schlüssel zu dieser Übung ist, den unterstützenden Arm so gerade wie möglich zu halten, um die Last auf dem arbeitenden Arm zu maximieren. Das macht sie zu einer anspruchsvollen, aber effektiven Übung für die einseitige Zugkraft."]}},{"id":"ex-arm-and-neck-stretch","slug":"arm-and-neck-stretch","name":"Arm and neck stretch","description":"Bodyweight exercise for the shoulders, with back, triceps, chest assisting.","instructions":["Relieves tension in the upper body, especially useful for people with office jobs or prolonged postures."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK","TRICEPS","CHEST"],"equipment":"BODYWEIGHT","tags":["arm and neck stretch","arm- und nackendehnung"],"media":[],"source":"wger","de":{"name":"Arm- und Nackendehnung","description":"Übung (Körpergewicht) für die Schultern, unterstützt von Rücken, Trizeps, Brust.","instructions":["Löst Verspannungen im oberen Körperbereich und ist besonders hilfreich für Menschen mit Bürotätigkeit oder langen, gleichbleibenden Haltungen."]}},{"id":"ex-arm-circles","slug":"arm-circles","name":"Arm Circles","description":"Equipment-free exercise for the shoulders, with back assisting.","instructions":["Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position.","Slowly start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform the movement.","Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"NONE","tags":["arm circles"],"media":[{"id":"arm-circles-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arm_Circles/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"arm-circles-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arm_Circles/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Schultern, unterstützt von Rücken.","instructions":null}},{"id":"ex-arm-raises-t-y-i","slug":"arm-raises-t-y-i","name":"Arm Raises (T/Y/I)","description":"Bodyweight exercise for the shoulders, with back, chest, core assisting.","instructions":["Stand upright with feet hip-width apart, core engaged, and arms relaxed at your sides. From this position, perform three different arm raises to target the shoulders and upper back:","T Raise: Lift your arms straight out to the sides until they are parallel to the floor, forming a “T” shape.","Y Raise: Lift your arms upward at about a 45° angle from your body to form a “Y” shape.","I Raise: Raise your arms straight overhead, close together, forming an “I” shape.","Maintain a neutral spine, avoid arching your lower back, and move slowly with control. Focus on squeezing your shoulder blades together and keeping your shoulders down away from your ears."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK","CHEST","ABS_CORE"],"equipment":"BODYWEIGHT","tags":["arm raises (t/y/i)","armheben (t/y/i)"],"media":[],"source":"wger","de":{"name":"Armheben (T/Y/I)","description":"Übung (Körpergewicht) für die Schultern, unterstützt von Rücken, Brust, Rumpf.","instructions":["Stelle dich aufrecht hin, mit den Füßen hüftbreit auseinander, angespanntem Rumpf und entspannt seitlich hängenden Armen. Führe aus dieser Position drei verschiedene Varianten des Armhebens aus, um Schultern und oberen Rücken zu beanspruchen:","T-Heben: Hebe deine Arme gerade zur Seite an, bis sie parallel zum Boden sind und ein „T“ bilden.","Y-Heben: Hebe deine Arme in einem Winkel von etwa 45° zu deinem Körper nach oben, sodass sie ein „Y“ bilden.","I-Heben: Hebe deine Arme gerade über den Kopf, nah beieinander, sodass sie ein „I“ bilden.","Halte deine Wirbelsäule neutral, vermeide ein Hohlkreuz im unteren Rücken und bewege dich langsam und kontrolliert. Konzentriere dich darauf, deine Schulterblätter zusammenzuziehen und deine Schultern weg von den Ohren nach unten zu halten."]}},{"id":"ex-arnold-shoulder-press","slug":"arnold-shoulder-press","name":"Arnold Shoulder Press","description":"Dumbbell exercise for the shoulders, with back, triceps assisting.","instructions":["Sit on a bench with your back supported. Hold a pair of dumbbells in front of your shoulders, palms facing you and elbows in front of your body.","Press the dumbbells overhead while rotating your hands, so that your palms face forward at the top. Stop just before your elbows lock out.","Reverse the movement under control: lower the dumbbells and turn your palms back towards you until you are in the starting position again.","As shown here: https://www.youtube.com/watch?v=vj2w851ZHRM"],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK","TRICEPS"],"equipment":"DUMBBELL","tags":["arnold shoulder press","arnold press"],"media":[],"source":"wger","de":{"name":"Arnold Press","description":"Übung (Kurzhantel) für die Schultern, unterstützt von Rücken, Trizeps.","instructions":["Zwei Kurzhanteln mit den Handflächen nach innen vor der Brust halten, Ellbogen unterhalb der Handgelenke.","Ellbogen nach außen bringen und Hanteln über den Kopf heben. Drehung kommt aus dem Ellbogen, nicht aus den Armen!","Wenn die Arme durchgestreckt sind, die gleiche Bewegung rückwärts ausführen."]}},{"id":"ex-around-the-worlds","slug":"around-the-worlds","name":"Around The Worlds","description":"Dumbbell exercise for the chest, with shoulders assisting.","instructions":["Lay down on a flat bench holding a dumbbell in each hand with the palms of the hands facing towards the ceiling. Tip: Your arms should be parallel to the floor and next to your thighs. To avoid injury, make sure that you keep your elbows slightly bent. This will be your starting position.","Now move the dumbbells by creating a semi-circle as you displace them from the initial position to over the head. All of the movement should happen with the arms parallel to the floor at all times. Breathe in as you perform this portion of the movement.","Reverse the movement to return the weight to the starting position as you exhale."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS"],"equipment":"DUMBBELL","tags":["around the worlds"],"media":[{"id":"around-the-worlds-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Around_The_Worlds/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"around-the-worlds-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Around_The_Worlds/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Brust, unterstützt von Schultern.","instructions":null}},{"id":"ex-australian-pull-ups","slug":"australian-pull-ups","name":"Australian pull-ups","description":"Bodyweight exercise for the shoulders, with biceps, back assisting.","instructions":["Lie down under a high bar or suspension bar, positioned at an appropriate height.","Position yourself on your back under the bar, gripping the bar with a supinated grip (palms facing you).","Adjust your position so that your body is aligned straight from head to toe. Arms should be fully extended, shoulders stabilized, and legs aligned with the rest of the body.","Bend your elbows and pull your chest towards the bar, contracting your back muscles. Imagine you're trying to bring your shoulder blades together.","Hold the contraction at the top of the movement for a moment to maximize muscle activation.","Slowly return to the starting position, extending your elbows."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BICEPS","BACK"],"equipment":"BODYWEIGHT","tags":["australian pull-ups","australian pull-ups (umgekehrtes rudern)"],"media":[],"source":"wger","de":{"name":"Australian Pull-ups (umgekehrtes Rudern)","description":"Übung (Körpergewicht) für die Schultern, unterstützt von Bizeps, Rücken.","instructions":["Lege dich unter eine hohe Stange oder eine Suspension-Stange, die auf passender Höhe angebracht ist.","Positioniere dich auf dem Rücken unter der Stange und greife sie im Untergriff (Handflächen zeigen zu dir).","Korrigiere deine Position so, dass dein Körper von Kopf bis Fuß eine gerade Linie bildet. Die Arme sollten vollständig gestreckt, die Schultern stabilisiert und die Beine in einer Linie mit dem übrigen Körper sein.","Beuge die Ellbogen und ziehe deine Brust zur Stange, während du die Rückenmuskulatur anspannst. Stelle dir vor, du versuchst, die Schulterblätter zusammenzuführen.","Halte die Kontraktion am höchsten Punkt der Bewegung kurz, um die Muskelaktivierung zu maximieren.","Kehre langsam in die Ausgangsposition zurück, indem du die Ellbogen streckst."]}},{"id":"ex-back-bridge","slug":"back-bridge","name":"Back bridge","description":"Bodyweight exercise for the back, with shoulders, hamstrings, calves, triceps assisting.","instructions":["Lie on the floor with your back resting on the floor and your legs bent, feet flat on the floor, leaving about 20 cm between your feet and your buttocks. Your hands remain flat on the floor, pressed against your ears, with your fingers pointing toward your toes. Your elbows are bent and pointing toward the ceiling. This is the starting position. Now push your hips as high as you can, raising your body off the floor, and continue pushing through your hands, extending your elbows and knees, until your back is fully arched (lumbar bridge). Your head also comes off the floor and should be level with your elbows, looking back. This is the final position. The descent should be slow and controlled. Your spine should be in a convex curve. It's not good to lift your back off the floor; it should remain straight. It should be well rounded. You'll also notice a feeling of increased oxygenation in your back. After lifting off the floor, your hips should be very high, even above the level of your head. Your arms and legs should remain straight. It seems easy, but it requires a good level of flexibility. Breathing should be deep. This posture stretches the rib cage and puts pressure on the diaphragm. If the posture is performed correctly, breathing will be perfect. Never hold your breath during the exercise."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["SHOULDERS","HAMSTRINGS","CALVES","TRICEPS"],"equipment":"BODYWEIGHT","tags":["back bridge","rückenbrücke"],"media":[],"source":"wger","de":{"name":"Rückenbrücke","description":"Übung (Körpergewicht) für den Rücken, unterstützt von Schultern, Oberschenkelrückseite, Waden, Trizeps.","instructions":["Lege dich mit dem Rücken auf den Boden, die Beine gebeugt, die Füße flach auf dem Boden, und lasse etwa 20 cm zwischen deinen Füßen und deinem Gesäß. Deine Hände bleiben flach auf dem Boden, an deine Ohren gedrückt, wobei die Finger zu deinen Zehen zeigen. Deine Ellbogen sind gebeugt und zeigen zur Decke. Das ist die Ausgangsposition. Drücke nun deine Hüfte so hoch wie möglich, hebe deinen Körper vom Boden ab und drücke dich weiter über deine Hände hoch, indem du Ellbogen und Knie streckst, bis dein Rücken vollständig durchgewölbt ist (Lendenbrücke). Auch dein Kopf hebt sich vom Boden und sollte auf Höhe deiner Ellbogen sein, der Blick geht nach hinten. Das ist die Endposition. Das Absenken sollte langsam und kontrolliert erfolgen. Deine Wirbelsäule sollte eine konvexe Kurve bilden. Es ist nicht gut, den Rücken nur vom Boden zu heben; er sollte nicht gerade bleiben. Er sollte gut gerundet sein. Du wirst außerdem ein Gefühl verstärkter Sauerstoffversorgung in deinem Rücken bemerken. Nach dem Abheben vom Boden sollte deine Hüfte sehr hoch sein, sogar über der Höhe deines Kopfes. Deine Arme und Beine sollten gerade bleiben. Es wirkt einfach, erfordert aber ein gutes Maß an Beweglichkeit. Die Atmung sollte tief sein. Diese Haltung dehnt den Brustkorb und übt Druck auf das Zwerchfell aus. Wenn die Haltung korrekt ausgeführt wird, ist die Atmung perfekt. Halte während der Übung niemals die Luft an."]}},{"id":"ex-back-flyes-with-bands","slug":"back-flyes-with-bands","name":"Back Flyes - With Bands","description":"Resistance band exercise for the shoulders, with back, triceps assisting.","instructions":["Run a band around a stationary post like that of a squat rack.","Grab the band by the handles and stand back so that the tension in the band rises.","Extend and lift the arms straight in front of you. Tip: Your arms should be straight and parallel to the floor while perpendicular to your torso. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position.","As you exhale, move your arms to the sides and back. Keep your arms extended and parallel to the floor. Continue the movement until the arms are extended to your sides.","After a pause, go back to the original position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK","TRICEPS"],"equipment":"BAND","tags":["back flyes - with bands"],"media":[{"id":"back-flyes-with-bands-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Back_Flyes_-_With_Bands/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"back-flyes-with-bands-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Back_Flyes_-_With_Bands/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Widerstandsband) für die Schultern, unterstützt von Rücken, Trizeps.","instructions":null}},{"id":"ex-back-neck-stretch","slug":"back-neck-stretch","name":"Back neck stretch","description":"Bodyweight exercise for the back.","instructions":["Starting position:","Sit upright on a chair or a firm pillow.","Steps:","Breathe out and tilt your head forward, chin to chest, putting hands behind your head.","Use your hands to pull your head down lightly and press against your hands with your head to balance out the force.","Hold for a bit.","Relax your arms and head, opening up a bit with your shoulders.","Keep repeating this from step 2 onward."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["back neck stretch","nackendehnung"],"media":[],"source":"wger","de":{"name":"Nackendehnung","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Ausgangsposition:","Setzen Sie sich aufrecht auf einen Stuhl oder ein festes Kissen.","Schritte:","Atmen Sie aus und neigen Sie den Kopf nach vorne, das Kinn zur Brust, und legen Sie die Hände hinter den Kopf.","Ziehen Sie den Kopf mit den Händen leicht nach unten und drücken Sie mit dem Kopf gegen die Hände, um die Kraft auszugleichen.","Halten Sie die Position eine Weile.","Entspanne deine Arme und deinen Kopf und öffne deine Schultern ein wenig.","Wiederhole dies von Schritt 2 an."]}},{"id":"ex-backward-arm-circles","slug":"backward-arm-circles","name":"Backward arm circles","description":"Bodyweight exercise for the biceps.","instructions":["Starting position:","Stand tall with your back straight.","Steps:","Keeping your arms straight, bring them in front of you, raise them over your head, then continue the motion behind your back and down to the initial position.","Keep circling your arms as described in step 1."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["backward arm circles","armkreisen rückwärts"],"media":[],"source":"wger","de":{"name":"Armkreisen rückwärts","description":"Übung (Körpergewicht) für den Bizeps.","instructions":["Ausgangsposition:","Stehen Sie aufrecht mit geradem Rücken.","Schritte:","Halten Sie die Arme gestreckt und führen Sie sie vor sich her, heben Sie sie über den Kopf und setzen Sie die Bewegung hinter dem Rücken fort, bis Sie wieder in die Ausgangsposition gelangen.","Kreisen Sie die Arme weiter wie in Schritt 1 beschrieben."]}},{"id":"ex-backward-medicine-ball-throw","slug":"backward-medicine-ball-throw","name":"Backward Medicine Ball Throw","description":"Accessory exercise for the shoulders.","instructions":["This exercise is best done with a partner. If you lack a partner, the ball can be thrown and retrieved or thrown against a wall.","Begin standing a few meters in front of your partner, both facing the same direction. Begin holding the ball between your legs.","Squat down and then forcefully reverse direction, coming to full extension and you toss the ball over your head to your partner.","Your partner can then roll the ball back to you. Repeat for the desired number of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["backward medicine ball throw"],"media":[{"id":"backward-medicine-ball-throw-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Backward_Medicine_Ball_Throw/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"backward-medicine-ball-throw-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Backward_Medicine_Ball_Throw/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Schultern.","instructions":null}},{"id":"ex-backward-shoulder-rotation","slug":"backward-shoulder-rotation","name":"Backward shoulder rotation","description":"Bodyweight exercise for the back.","instructions":["Starting position:","Sit or stand with your back straight.","Steps:","Place your hands on your shoulders.","Repeatedly rotate both shoulder joints in a circular motion at a moderate pace."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["backward shoulder rotation","rückwärtsdrehung der schulter"],"media":[],"source":"wger","de":{"name":"Rückwärtsdrehung der Schulter","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Ausgangsposition:","Sitze oder stehe mit geradem Rücken.","Schritte:","Lege Deine Hände auf Deine Schultern.","Drehe wiederholt beide Schultergelenke in einer kreisförmigen Bewegung mit mäßigem Tempo."]}},{"id":"ex-balance-board","slug":"balance-board","name":"Balance Board","description":"Accessory exercise for the calves, with hamstrings, quadriceps assisting.","instructions":["Place a balance board in front of you.","Stand up on it and try to balance yourself.","Hold the balance for as long as desired."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":["HAMSTRINGS","QUADRICEPS"],"equipment":"OTHER","tags":["balance board"],"media":[{"id":"balance-board-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Balance_Board/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"balance-board-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Balance_Board/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Waden, unterstützt von Oberschenkelrückseite, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-ball-leg-curl","slug":"ball-leg-curl","name":"Ball Leg Curl","description":"Accessory exercise for the hamstrings, with calves, glutes assisting.","instructions":["Begin on the floor laying on your back with your feet on top of the ball.","Position the ball so that when your legs are extended your ankles are on top of the ball. This will be your starting position.","Raise your hips off of the ground, keeping your weight on the shoulder blades and your feet.","Flex the knees, pulling the ball as close to you as you can, contracting the hamstrings.","After a brief pause, return to the starting position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","GLUTES"],"equipment":"OTHER","tags":["ball leg curl"],"media":[{"id":"ball-leg-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ball_Leg_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"ball-leg-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ball_Leg_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelrückseite, unterstützt von Waden, Po.","instructions":null}},{"id":"ex-band-assisted-pull-up","slug":"band-assisted-pull-up","name":"Band Assisted Pull-Up","description":"Accessory exercise for the back, with core, forearms assisting.","instructions":["Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.","Pull the end of the band down, and place one bent knee into the loop, ensuring it won't slip out. Take a medium to wide grip on the bar. This will be your starting position.","Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.","After a brief pause, return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["ABS_CORE","FOREARMS"],"equipment":"OTHER","tags":["band assisted pull-up"],"media":[{"id":"band-assisted-pull-up-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Assisted_Pull-Up/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"band-assisted-pull-up-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Assisted_Pull-Up/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Rumpf, Unterarme.","instructions":null}},{"id":"ex-band-good-morning","slug":"band-good-morning","name":"Band Good Morning","description":"Resistance band exercise for the hamstrings, with glutes, back assisting.","instructions":["Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position.","Keeping your legs straight, extend through the hips to come to a near vertical position.","Ensure that you do not round your back as you go down back to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","BACK"],"equipment":"BAND","tags":["band good morning"],"media":[{"id":"band-good-morning-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Good_Morning/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"band-good-morning-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Good_Morning/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Widerstandsband) für die Oberschenkelrückseite, unterstützt von Po, Rücken.","instructions":null}},{"id":"ex-band-good-morning-pull-through","slug":"band-good-morning-pull-through","name":"Band Good Morning (Pull Through)","description":"Resistance band exercise for the hamstrings, with glutes, back assisting.","instructions":["Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. Your hands can help hold the band in position.","Begin by bending at the hips, getting your butt back as far as possible. Keep your back flat and bend forward to about 90 degrees. Your knees should be only slightly bent.","Return to the starting position be driving through with the hips to come back to a standing position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","BACK"],"equipment":"BAND","tags":["band good morning (pull through)"],"media":[{"id":"band-good-morning-pull-through-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Good_Morning_Pull_Through/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"band-good-morning-pull-through-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Good_Morning_Pull_Through/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Widerstandsband) für die Oberschenkelrückseite, unterstützt von Po, Rücken.","instructions":null}},{"id":"ex-band-hip-adductions","slug":"band-hip-adductions","name":"Band Hip Adductions","description":"Resistance band exercise for the quadriceps.","instructions":["Anchor a band around a solid post or other object.","Stand with your left side to the post, and put your right foot through the band, getting it around the ankle.","Stand up straight and hold onto the post if needed. This will be your starting position.","Keeping the knee straight, raise your right legs out to the side as far as you can.","Return to the starting position and repeat for the desired rep count.","Switch sides."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"BAND","tags":["band hip adductions"],"media":[{"id":"band-hip-adductions-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Hip_Adductions/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"band-hip-adductions-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Hip_Adductions/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Widerstandsband) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-band-pull-apart","slug":"band-pull-apart","name":"Band Pull Apart","description":"Resistance band exercise for the shoulders, with back assisting.","instructions":["Begin with your arms extended straight out in front of you, holding the band with both hands.","Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.","Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.","Pause as you complete the movement, returning to the starting position under control."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"BAND","tags":["band pull apart"],"media":[{"id":"band-pull-apart-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Pull_Apart/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"band-pull-apart-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Pull_Apart/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Widerstandsband) für die Schultern, unterstützt von Rücken.","instructions":null}},{"id":"ex-band-pull-apart-with-external-rotation","slug":"band-pull-apart-with-external-rotation","name":"Band pull-apart with external rotation","description":"Resistance band exercise for the shoulders.","instructions":["Stand tall with your feet shoulder-width apart, chest out, and shoulders back.","Hold the resistance band with both hands, palms facing up or facing each other, depending on the band type.","Bend your elbows at a 90-degree angle and glue your upper arms to your sides.","The band should have some tension in the starting position, with your hands closer together in front of your stomach.","Rotate Outward: While keeping your elbows tucked into your sides, slowly move your hands away from each other, stretching the band.","Squeeze: Squeeze your shoulder blades together and down as you rotate your hands outward.","Range of Motion: Rotate your hands as far outward as you comfortably can without allowing your elbows to leave your sides.","Hold: Hold the end position for 1–2 seconds to maximize muscle engagement."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"BAND","tags":["band pull-apart with external rotation","band pull-apart mit außenrotation"],"media":[],"source":"wger","de":{"name":"Band Pull-Apart mit Außenrotation","description":"Übung (Widerstandsband) für die Schultern.","instructions":["Stehe aufrecht, die Füße schulterbreit auseinander, die Brust herausgestreckt und die Schultern zurückgezogen.","Halte das Widerstandsband mit beiden Händen, die Handflächen nach oben oder einander zugewandt, je nach Bandtyp.","Beuge deine Ellenbogen im 90-Grad-Winkel und lege deine Oberarme eng an die Seiten an.","Das Band sollte in der Ausgangsposition bereits etwas unter Spannung stehen, mit den Händen näher beieinander vor deinem Bauch.","Nach außen drehen: Während du deine Ellenbogen an den Seiten hältst, bewegst du deine Hände langsam voneinander weg und dehnst das Band.","Zusammenziehen: Ziehe deine Schulterblätter zusammen und nach unten, während du deine Hände nach außen drehst.","Bewegungsumfang: Drehe deine Hände so weit nach außen, wie es bequem möglich ist, ohne dass deine Ellenbogen die Seiten verlassen.","Halten: Halte die Endposition 1–2 Sekunden, um die Muskelbeanspruchung zu maximieren."]}},{"id":"ex-band-pull-aparts","slug":"band-pull-aparts","name":"Band pull-aparts","description":"Resistance band exercise for the back.","instructions":["Hold the band with your arms extended in front of you at shoulder height.","Keep your elbows slightly bent but fixed throughout the movement.","Pull the band apart by spreading your arms until the band touches or comes close to your chest.","Slowly bring your arms back to the starting position, controlling the tension on the band."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BAND","tags":["band pull-aparts"],"media":[],"source":"wger","de":{"name":"Band Pull-Aparts","description":"Übung (Widerstandsband) für den Rücken.","instructions":["Halte das Band mit ausgestreckten Armen auf Schulterhöhe vor dir.","Halte deine Ellbogen während der gesamten Bewegung leicht gebeugt, aber fixiert.","Ziehe das Band auseinander, indem du deine Arme spreizt, bis das Band deine Brust berührt oder ihr nahekommt.","Führe deine Arme langsam zurück in die Ausgangsposition und kontrolliere dabei die Spannung des Bandes."]}},{"id":"ex-band-skull-crusher","slug":"band-skull-crusher","name":"Band Skull Crusher","description":"Resistance band exercise for the triceps.","instructions":["Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head.","Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor. With the elbow flexed, the band should be above your head. This will be your starting position.","Extend through the elbow to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and return to the starting position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"BAND","tags":["band skull crusher"],"media":[{"id":"band-skull-crusher-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Skull_Crusher/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"band-skull-crusher-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Skull_Crusher/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Widerstandsband) für den Trizeps.","instructions":null}},{"id":"ex-banded-clamshell","slug":"banded-clamshell","name":"Banded Clamshell","description":"Resistance band exercise for the glutes, with core, quadriceps assisting.","instructions":["Position","Side plank with the elbow and the forearm on the ground and the legs slightly bent. Stretch a doubled-up resistance band between your thighs, just above the knee.","Execution","Lift","your upper knee while keeping your feet close together, like a “shell","opening,” then slowly return to the starting position. Keep your core","stable and your hips aligned."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["ABS_CORE","QUADRICEPS"],"equipment":"BAND","tags":["banded clamshell","clamshell mit band"],"media":[],"source":"wger","de":{"name":"Clamshell mit Band","description":"Übung (Widerstandsband) für den Po, unterstützt von Rumpf, Oberschenkelvorderseite.","instructions":["Position","Seitlicher Unterarmstütz, mit Ellenbogen und Unterarm auf dem Boden und leicht gebeugten Beinen. Spanne ein doppelt gelegtes Widerstandsband zwischen deinen Oberschenkeln, knapp oberhalb des Knies.","Ausführung","Hebe","dein oberes Knie an, während du deine Füße eng beieinander hältst, wie eine sich","„öffnende Muschel“, und kehre dann langsam in die Ausgangsposition zurück. Halte deinen Rumpf","stabil und deine Hüften ausgerichtet."]}},{"id":"ex-banded-scapular-retraction","slug":"banded-scapular-retraction","name":"Banded Scapular Retraction","description":"Resistance band exercise for the shoulders, with back assisting.","instructions":["Attach one end of resistance band to wall/upright/... at shoulder height. Insert arm into the loop, at the tricep. Step back until band is pulled straight. Pull back elbow and shoulder against the resistance of the band."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"BAND","tags":["banded scapular retraction","schulter-rückzieher"],"media":[],"source":"wger","de":{"name":"Schulter-Rückzieher","description":"Übung (Widerstandsband) für die Schultern, unterstützt von Rücken.","instructions":["Band in Schullterhöhe an Wand/Pfosten/... anbringen. Arm durch die Schlaufe und am Trizeps anlegen. Band straff ziehen. Ellenbogen und Schulter dann nach hinten ziehen."]}},{"id":"ex-banded-shoulder-drills","slug":"banded-shoulder-drills","name":"Banded Shoulder Drills","description":"Resistance band exercise for the shoulders, with chest, back assisting.","instructions":["Attach a resistance band to something solid behind you. Stand away from it, holding it in your hand so it is taut.","Perform the shoulder mobility and rotation drills shown in the video: https://www.youtube.com/watch?v=zdwEWchSjrI"],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CHEST","BACK"],"equipment":"BAND","tags":["banded shoulder drills","schulterübungen mit band"],"media":[],"source":"wger","de":{"name":"Schulterübungen mit Band","description":"Übung (Widerstandsband) für die Schultern, unterstützt von Brust, Rücken.","instructions":["Befestige ein Widerstandsband hinter dir an etwas Stabilem. Stelle dich davon weg und halte es in der Hand, sodass es straff gespannt ist.","Siehe das beigefügte YouTube-Video: https://www.youtube.com/watch?v=zdwEWchSjrI ."]}},{"id":"ex-barbell-ab-rollout","slug":"barbell-ab-rollout","name":"Barbell Ab Rollout","description":"Barbell exercise for the core, with back, shoulders assisting.","instructions":["For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position.","While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don't, you will work out your shoulders and back more than the abs.","After a second contraction at the top, start to roll the barbell back forward to the starting position slowly as you inhale.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["BACK","SHOULDERS"],"equipment":"BARBELL","tags":["barbell ab rollout","rollout mit der langhantel"],"media":[{"id":"barbell-ab-rollout-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Ab_Rollout/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-ab-rollout-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Ab_Rollout/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Rollout mit der Langhantel","description":"Übung (Langhantel) für den Rumpf, unterstützt von Rücken, Schultern.","instructions":["Lege eine Langhantel auf den Boden vor deine Füße.","Beuge dich in der Hüfte und greife die Langhantel schulterbreit im Obergriff.","Rolle die Stange in einer langsamen, kontrollierten Bewegung nach vorne aus, sodass dein Rücken gerade ist.","Rolle wieder zurück und hebe dabei deine Hüfte und dein Gesäß an, während du in die Ausgangsposition zurückkehrst."]}},{"id":"ex-barbell-ab-rollout-on-knees","slug":"barbell-ab-rollout-on-knees","name":"Barbell Ab Rollout - On Knees","description":"Barbell exercise for the core, with back, shoulders assisting.","instructions":["Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.","Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.","Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.","After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["BACK","SHOULDERS"],"equipment":"BARBELL","tags":["barbell ab rollout - on knees"],"media":[{"id":"barbell-ab-rollout-on-knees-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Ab_Rollout_-_On_Knees/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-ab-rollout-on-knees-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Ab_Rollout_-_On_Knees/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rumpf, unterstützt von Rücken, Schultern.","instructions":null}},{"id":"ex-barbell-curls-lying-against-an-incline","slug":"barbell-curls-lying-against-an-incline","name":"Barbell Curls Lying Against An Incline","description":"Barbell exercise for the biceps.","instructions":["Lie against an incline bench, with your arms holding a barbell and hanging down in a horizontal line. This will be your starting position.","While keeping the upper arms stationary, curl the weight up as high as you can while squeezing the biceps. Breathe out as you perform this portion of the movement. Tip: Only the forearms should move. Do not swing the arms.","After a second contraction, slowly go back to the starting position as you inhale. Tip: Make sure that you go all of the way down.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["barbell curls lying against an incline"],"media":[{"id":"barbell-curls-lying-against-an-incline-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curls_Lying_Against_An_Incline/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-curls-lying-against-an-incline-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curls_Lying_Against_An_Incline/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Bizeps.","instructions":null}},{"id":"ex-barbell-full-squat","slug":"barbell-full-squat","name":"Barbell Full Squat","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings, back assisting.","instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out. Keep your head up at all times and maintain a straight back. This will be your starting position.","Begin to slowly lower the bar by bending the knees and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your hamstrings are on your calves. Inhale as you perform this portion of the movement.","Begin to raise the bar as you exhale by pushing the floor with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","BACK"],"equipment":"BARBELL","tags":["barbell full squat","tiefe kniebeuge mit langhantel"],"media":[{"id":"barbell-full-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-full-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Tiefe Kniebeuge mit Langhantel","description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Rücken.","instructions":["Die tiefe Kniebeuge mit Langhantel ist eine Grundübung, die mehrere Muskelgruppen im Unterkörper anspricht, darunter die vordere Oberschenkelmuskulatur, die hintere Oberschenkelmuskulatur und die Gesäßmuskulatur.","Eine korrekte Ausführung ist entscheidend, um die Ergebnisse zu maximieren und Verletzungen während der tiefen Kniebeuge mit Langhantel zu vermeiden. Dazu gehören ein schulterbreiter Stand, eine Ganzkörperspannung, ein kontrolliertes Absenken sowie die richtige Tiefe und Knieposition.","Hilfsübungen wie die Frontkniebeuge, die Goblet-Kniebeuge, die Split-Kniebeuge und die bulgarische Split-Kniebeuge können deine Leistung in der tiefen Kniebeuge mit Langhantel verbessern, indem sie bestimmte Muskelgruppen ansprechen und die Gesamttechnik verbessern.","Um neue persönliche Rekorde in der Kniebeuge zu erreichen, steigere das Gewicht nach und nach, variiere die Wiederholungs- und Satzbereiche, um das Muskelwachstum zu stimulieren, und priorisiere Ruhe und Erholung zwischen den Trainingseinheiten."]}},{"id":"ex-barbell-guillotine-bench-press","slug":"barbell-guillotine-bench-press","name":"Barbell Guillotine Bench Press","description":"Barbell exercise for the chest, with shoulders, triceps assisting.","instructions":["Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.","As you breathe in, bring the bar down slowly until it is about 1 inch from your neck.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["barbell guillotine bench press"],"media":[{"id":"barbell-guillotine-bench-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Guillotine_Bench_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-guillotine-bench-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Guillotine_Bench_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-barbell-hack-squat","slug":"barbell-hack-squat","name":"Barbell Hack Squat","description":"Barbell exercise for the quadriceps, with calves, forearms, hamstrings assisting.","instructions":["Stand up straight while holding a barbell behind you at arms length and your feet at shoulder width. Tip: A shoulder width grip is best with the palms of your hands facing back. You can use wrist wraps for this exercise for a better grip. This will be your starting position.","While keeping your head and eyes up and back straight, squat until your upper thighs are parallel to the floor. Breathe in as you slowly go down.","Pressing mainly with the heel of the foot and squeezing the thighs, go back up as you breathe out.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","FOREARMS","HAMSTRINGS"],"equipment":"BARBELL","tags":["barbell hack squat"],"media":[{"id":"barbell-hack-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hack_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-hack-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hack_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Unterarme, Oberschenkelrückseite.","instructions":null}},{"id":"ex-barbell-incline-shoulder-raise","slug":"barbell-incline-shoulder-raise","name":"Barbell Incline Shoulder Raise","description":"Barbell exercise for the shoulders, with chest assisting.","instructions":["Lie back on an Incline Bench. Using a medium width grip (a grip that is slightly wider than shoulder width), lift the bar from the rack and hold it straight over you with your arms straight. This will be your starting position.","While keeping the arms straight, lift the bar by protracting your shoulder blades, raising the shoulders from the bench as you breathe out.","Bring back the bar to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CHEST"],"equipment":"BARBELL","tags":["barbell incline shoulder raise"],"media":[{"id":"barbell-incline-shoulder-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Shoulder_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-incline-shoulder-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Shoulder_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Schultern, unterstützt von Brust.","instructions":null}},{"id":"ex-barbell-lunges-standing","slug":"barbell-lunges-standing","name":"Barbell Lunges Standing","description":"Barbell exercise for the quadriceps, with glutes assisting.","instructions":["Put barbell on the back of your shoulders. Stand upright, then take the first step forward. Step should bring you forward so that your supporting legs knee can touch the floor. Then stand back up and repeat with the other leg.","Remember to keep good posture."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES"],"equipment":"BARBELL","tags":["barbell lunges standing","stehende ausfallschritte mit langhantel"],"media":[],"source":"wger","de":{"name":"Stehende Ausfallschritte mit Langhantel","description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Po.","instructions":["Lege die Langhantel auf die Rückseite deiner Schultern. Stelle dich aufrecht hin und mache dann den ersten Schritt nach vorne. Der Schritt sollte dich so weit nach vorne bringen, dass das Knie deines stützenden Beins den Boden berühren kann. Richte dich anschließend wieder auf und wiederhole das Ganze mit dem anderen Bein.","Denk daran, eine gute Körperhaltung zu bewahren."]}},{"id":"ex-barbell-rear-delt-row","slug":"barbell-rear-delt-row","name":"Barbell Rear Delt Row","description":"Barbell exercise for the shoulders, with biceps, back assisting.","instructions":["Stand up straight while holding a barbell using a wide (higher than shoulder width) and overhand (palms facing your body) grip.","Bend knees slightly and bend over as you keep the natural arch of your back. Let the arms hang in front of you as they hold the bar. Once your torso is parallel to the floor, flare the elbows out and away from your body. Tip: Your torso and your arms should resemble the letter \"T\". Now you are ready to begin the exercise.","While keeping the upper arms perpendicular to the torso, pull the barbell up towards your upper chest as you squeeze the rear delts and you breathe out. Tip: When performed correctly, this exercise should resemble a bench press in reverse. Also, refrain from using your biceps to do the work. Focus on targeting the rear delts; the arms should only act as hooks.","Slowly go back to the initial position as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BICEPS","BACK"],"equipment":"BARBELL","tags":["barbell rear delt row"],"media":[{"id":"barbell-rear-delt-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Rear_Delt_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-rear-delt-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Rear_Delt_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Schultern, unterstützt von Bizeps, Rücken.","instructions":null}},{"id":"ex-barbell-rollout-from-bench","slug":"barbell-rollout-from-bench","name":"Barbell Rollout from Bench","description":"Barbell exercise for the core, with glutes, hamstrings, back, shoulders assisting.","instructions":["Place a loaded barbell on the ground, near the end of a bench. Kneel with both legs on the bench, and take a medium to narrow grip on the barbell. This will be your starting position.","To begin, extend through the hips to slowly roll the bar forward. As you roll out, flex the shoulder to roll the bar above your head. Ensure that your arms remain extended throughout the movement.","When the bar has been moved as far forward as possible, return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["GLUTES","HAMSTRINGS","BACK","SHOULDERS"],"equipment":"BARBELL","tags":["barbell rollout from bench"],"media":[{"id":"barbell-rollout-from-bench-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Rollout_from_Bench/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-rollout-from-bench-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Rollout_from_Bench/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rumpf, unterstützt von Po, Oberschenkelrückseite, Rücken, Schultern.","instructions":null}},{"id":"ex-barbell-row-overhand","slug":"barbell-row-overhand","name":"Barbell Row (Overhand)","description":"Barbell exercise for the back.","instructions":["Execution","Starting position:","Hold the barbell with arms fully extended toward the floor.","Maintain tension in your lats and back muscles."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["barbell row (overhand)","langhantelrudern (obergriff)"],"media":[],"source":"wger","de":{"name":"Langhantelrudern (Obergriff)","description":"Übung (Langhantel) für den Rücken.","instructions":["Ausführung","Startposition:","Halte die Langhantel mit vollständig zum Boden gestreckten Armen.","Halte die Spannung im Latissimus und in der Rückenmuskulatur."]}},{"id":"ex-barbell-row-underhand","slug":"barbell-row-underhand","name":"Barbell Row (Underhand)","description":"Barbell exercise for the back.","instructions":["Execution","Starting position:","Hold the barbell with arms fully extended toward the floor.","Maintain tension in your lats and back muscles."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["barbell row (underhand)","langhantelrudern (untergriff)"],"media":[],"source":"wger","de":{"name":"Langhantelrudern (Untergriff)","description":"Übung (Langhantel) für den Rücken.","instructions":["Ausführung","Startposition:","Halte die Langhantel mit vollständig zum Boden gestreckten Armen.","Halte die Spannung im Latissimus und in der Rückenmuskulatur."]}},{"id":"ex-barbell-seated-calf-raise","slug":"barbell-seated-calf-raise","name":"Barbell Seated Calf Raise","description":"Barbell exercise for the calves.","instructions":["Place a block about 12 inches in front of a flat bench.","Sit on the bench and place the ball of your feet on the block.","Have someone place a barbell over your upper thighs about 3 inches above your knees and hold it there. This will be your starting position.","Raise up on your toes as high as possible as you squeeze the calves and as you breathe out.","After a second contraction, slowly go back to the starting position. Tip: To get maximum benefit stretch your calves as far as you can.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["barbell seated calf raise"],"media":[{"id":"barbell-seated-calf-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Seated_Calf_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-seated-calf-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Seated_Calf_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Waden.","instructions":null}},{"id":"ex-barbell-shrug-behind-the-back","slug":"barbell-shrug-behind-the-back","name":"Barbell Shrug Behind The Back","description":"Barbell exercise for the back, with forearms assisting.","instructions":["Stand up straight with your feet at shoulder width as you hold a barbell with both hands behind your back using a pronated grip (palms facing back). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for better grip. This will be your starting position.","Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps. The arms should remain stretched out at all times.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["FOREARMS"],"equipment":"BARBELL","tags":["barbell shrug behind the back"],"media":[{"id":"barbell-shrug-behind-the-back-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Shrug_Behind_The_Back/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-shrug-behind-the-back-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Shrug_Behind_The_Back/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Unterarme.","instructions":null}},{"id":"ex-barbell-side-bend","slug":"barbell-side-bend","name":"Barbell Side Bend","description":"Barbell exercise for the core, with back assisting.","instructions":["Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position.","While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.","Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["BACK"],"equipment":"BARBELL","tags":["barbell side bend"],"media":[{"id":"barbell-side-bend-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Side_Bend/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-side-bend-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Side_Bend/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rumpf, unterstützt von Rücken.","instructions":null}},{"id":"ex-barbell-side-split-squat","slug":"barbell-side-split-squat","name":"Barbell Side Split Squat","description":"Barbell exercise for the quadriceps, with calves, hamstrings, back assisting.","instructions":["Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be placed wide apart with the foot of the lead leg angled out to the side. This will be your starting position.","Lower your body towards the side of your angled foot by bending the knee and hip of your lead leg and while keeping the opposite leg only slightly bent. Breathe in as you lower your body.","Return to the starting position by extending the hip and knee of the lead leg. Breathe out as you perform this movement.","After performing the recommended amount of reps, repeat the movement with the opposite leg."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","HAMSTRINGS","BACK"],"equipment":"BARBELL","tags":["barbell side split squat"],"media":[{"id":"barbell-side-split-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Side_Split_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-side-split-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Side_Split_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-barbell-silverback-shrug","slug":"barbell-silverback-shrug","name":"Barbell Silverback Shrug","description":"Barbell exercise for the back.","instructions":["Stand with your feet shoulder width apart holding the barbell with both hands in front just past shoulder width.","Bend forward at the hips with a slight bend in your knees, keeping your back straight.","Engage your shoulder blades, as if you are trying to touch them together.","Release the shrug.","Description taken from MuscleWiki"],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["barbell silverback shrug","langhantel-silverback-shrug"],"media":[],"source":"wger","de":{"name":"Langhantel-Silverback-Shrug","description":"Übung (Langhantel) für den Rücken.","instructions":["Stelle dich schulterbreit hin und halte die Langhantel mit beiden Händen vor dem Körper, etwas weiter als schulterbreit.","Beuge dich in der Hüfte nach vorne, mit einer leichten Beugung in den Knien, und halte deinen Rücken gerade.","Spanne deine Schulterblätter an, als würdest du versuchen, sie zusammenzuführen.","Löse das Schulterziehen wieder.","Beschreibung übernommen von MuscleWiki"]}},{"id":"ex-barbell-squat-to-a-bench","slug":"barbell-squat-to-a-bench","name":"Barbell Squat To A Bench","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings, back assisting.","instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first place a flat bench or a box behind you. The flat bench is used to teach you to set your hips back and to hit depth.","Then, set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to slowly lower the bar by bending the knees and sitting your hips back as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs and extend the hips to go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","BACK"],"equipment":"BARBELL","tags":["barbell squat to a bench"],"media":[{"id":"barbell-squat-to-a-bench-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Squat_To_A_Bench/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-squat-to-a-bench-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Squat_To_A_Bench/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-barbell-step-back-lunge","slug":"barbell-step-back-lunge","name":"Barbell Step Back Lunge","description":"Barbell exercise for the quadriceps.","instructions":["Stand with your feet hip-width apart, holding a barbell on your upper back.","Keep your back straight, chest up, and core engaged.","Take a step back with one leg and lower your body by bending both knees. Ensure that your back knee nearly touches the ground.","Push off your back foot to return to the starting position.","Repeat the movement with the other leg.","Continue alternating between legs for the desired repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["barbell step back lunge","ausfallschritt nach hinten mit langhantel"],"media":[{"id":"barbell-step-back-lunge-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1830/3b6c547c-ab3d-4472-93cf-561710279eab.jpg","caption":"Barbell Step Back Lunge","attribution":"wger.de · hans","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Ausfallschritt nach hinten mit Langhantel","description":"Übung (Langhantel) für die Oberschenkelvorderseite.","instructions":["Stehe mit hüftbreit aufgestellten Füßen und halte eine Langhantel auf deinem oberen Rücken.","Halte deinen Rücken gerade, die Brust aufgerichtet und den Rumpf angespannt.","Mache mit einem Bein einen Schritt nach hinten und senke deinen Körper, indem du beide Knie beugst. Achte darauf, dass dein hinteres Knie den Boden fast berührt.","Drücke dich mit dem hinteren Fuß ab, um in die Ausgangsposition zurückzukehren.","Wiederhole die Bewegung mit dem anderen Bein.","Wechsle weiter zwischen den Beinen für die gewünschte Anzahl an Wiederholungen ab."]}},{"id":"ex-barbell-step-ups","slug":"barbell-step-ups","name":"Barbell Step Ups","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck) and stand upright behind an elevated platform (such as the one used for spotting behind a flat bench). This is your starting position.","Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.","Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.","Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"BARBELL","tags":["barbell step ups"],"media":[{"id":"barbell-step-ups-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Step_Ups/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-step-ups-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Step_Ups/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-barbell-walking-lunge","slug":"barbell-walking-lunge","name":"Barbell Walking Lunge","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Begin standing with your feet shoulder width apart and a barbell across your upper back.","Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.","Drive through the heel of your lead foot and extend both knees to raise yourself back up.","Step forward with your rear foot, repeating the lunge on the opposite leg."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"BARBELL","tags":["barbell walking lunge"],"media":[{"id":"barbell-walking-lunge-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Walking_Lunge/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"barbell-walking-lunge-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Walking_Lunge/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-battling-ropes","slug":"battling-ropes","name":"Battling Ropes","description":"Accessory exercise for the shoulders, with chest, forearms assisting.","instructions":["For this exercise you will need a heavy rope anchored at its center 15-20 feet away. Standing in front of the rope, take an end in each hand with your arms extended at your side. This will be your starting position.","Initiate the movement by rapidly raising one arm to shoulder level as quickly as you can.","As you let that arm drop to the starting position, raise the opposite side.","Continue alternating your left and right arms, whipping the ropes up and down as fast as you can."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CHEST","FOREARMS"],"equipment":"OTHER","tags":["battling ropes"],"media":[{"id":"battling-ropes-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Battling_Ropes/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"battling-ropes-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Battling_Ropes/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Schultern, unterstützt von Brust, Unterarme.","instructions":null}},{"id":"ex-bear-crawl-pull-through","slug":"bear-crawl-pull-through","name":"Bear crawl pull through","description":"Dumbbell exercise for the shoulders, with glutes, quadriceps, core, hamstrings, calves, back assisting.","instructions":["Place a dumbbell at around hip level and assume a bear crawl position. Push the knees off the floor and hold.","With the opposite hand reach for the dumbbell and pull it to the other side. Place your hand back on the floor and repeat with your other hand."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["GLUTES","QUADRICEPS","ABS_CORE","HAMSTRINGS","CALVES","BACK"],"equipment":"DUMBBELL","tags":["bear crawl pull through"],"media":[],"source":"wger","de":{"name":"Bear Crawl Pull Through","description":"Übung (Kurzhantel) für die Schultern, unterstützt von Po, Oberschenkelvorderseite, Rumpf, Oberschenkelrückseite, Waden, Rücken.","instructions":["Lege eine Kurzhantel ungefähr auf Hüfthöhe ab und nimm eine Bear-Crawl-Position ein. Drücke die Knie vom Boden weg und halte die Position.","Greife mit der gegenüberliegenden Hand nach der Kurzhantel und ziehe sie auf die andere Seite. Setze deine Hand wieder auf dem Boden ab und wiederhole die Bewegung mit der anderen Hand."]}},{"id":"ex-bear-walk-2","slug":"bear-walk-2","name":"Bear Walk 2","description":"Bodyweight exercise for the shoulders, with calves, chest, core, triceps, glutes, back, quadriceps assisting.","instructions":["-Rest your weight on your palms and the balls of your feet, not dissimilar to normal pushup position","-Move by stepping with your R palm and L foot, then your L palm and R foot.  Basically, walk like a lumbering bear.","-Move as fast as you can.  Measure your reps/sets in either distance (i.e. 40 yards) or time (i.e. 45 seconds)","-Works your Pecs, Deltoids, Triceps, Traps, Lats, Abs and Lower Back, Hip Flexors, Quads, Glutes and Calves"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CALVES","CHEST","ABS_CORE","TRICEPS","GLUTES","BACK","QUADRICEPS"],"equipment":"BODYWEIGHT","tags":["bear walk 2","bear walk"],"media":[],"source":"wger","de":{"name":"Bear Walk","description":"Übung (Körpergewicht) für die Schultern, unterstützt von Waden, Brust, Rumpf, Trizeps, Po, Rücken, Oberschenkelvorderseite.","instructions":["-Stützen Sie Ihr Gewicht auf Ihren Handflächen und Ihren Füßen, nicht anders als in der normalen Liegestützposition","Bewegen Sie sich, indem Sie mit der R-Handfläche und dem L-Fuß, dann mit der L-Handfläche und dem R-Fuß treten. Gehen Sie im Grunde wie ein trampelnder Bär.","-Bewegen Sie sich so schnell wie möglich. Messen Sie Ihre Wiederholungen / Sätze entweder in der Entfernung (d. H. 40 Meter) oder in der Zeit (d. H. 45 Sekunden).","-Arbeitet an Pecs, Deltamuskeln, Trizeps, Trapezius, Lats, Abs und Lendenwirbelsäule, Hüftbeugern, Quads, Gesäßmuskeln und Waden"]}},{"id":"ex-behind-head-chest-stretch","slug":"behind-head-chest-stretch","name":"Behind Head Chest Stretch","description":"Accessory exercise for the chest, with shoulders assisting.","instructions":["Sit upright on the floor with your partner behind you.","Place your hands behind your hand, and push your elbows back as far as you can. Your partner should hold your elbows. This will be your starting position.","Gently attempt to pull your elbows forward with your hands still behind your head for 10 or more seconds. Your partner should prevent your elbows from moving.","Now, relax your muscles and have your partner gently pull the elbows back as far as it comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS"],"equipment":"OTHER","tags":["behind head chest stretch"],"media":[{"id":"behind-head-chest-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Behind_Head_Chest_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"behind-head-chest-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Behind_Head_Chest_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Brust, unterstützt von Schultern.","instructions":null}},{"id":"ex-behind-the-back-cable-lateral-raise","slug":"behind-the-back-cable-lateral-raise","name":"Behind the Back Cable Lateral Raise","description":"Cable exercise for the shoulders, with back assisting.","instructions":["Lateral raises have long been a staple for building capped delts, and lifters use everything from dumbbells and bands to machines and single-arm variations to make them grow."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"CABLE","tags":["behind the back cable lateral raise","seitheben am kabelzug hinter dem rücken"],"media":[],"source":"wger","de":{"name":"Seitheben am Kabelzug hinter dem Rücken","description":"Übung (Kabelzug) für die Schultern, unterstützt von Rücken.","instructions":["Seitheben ist seit Langem ein Klassiker zum Aufbau ausgeprägter Schultern, und Trainierende nutzen alles von Kurzhanteln und Bändern bis hin zu Maschinen und einarmigen Varianten, um sie wachsen zu lassen."]}},{"id":"ex-bench-dips-on-floor","slug":"bench-dips-on-floor","name":"Bench Dips On Floor","description":"Bodyweight exercise for the biceps, with triceps, shoulders, chest, calves, back assisting.","instructions":["Triceps dips on floor are a compound exercise as they worked multiple muscle groups simultaneously. Although this bodyweight exercise mainly targets the triceps, it also hits your chest and front of your shoulder.","Triceps dips on floor are one of the most effective exercises to increase arm strength and also build lean muscle in your upper arms.","Triceps dips on floor are a closed kinetic chain exercise and express that you do the movements around a fixed point. It increases compression force on your joints thereby improving stability."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["TRICEPS","SHOULDERS","CHEST","CALVES","BACK"],"equipment":"BODYWEIGHT","tags":["bench dips on floor","bench dips am boden"],"media":[],"source":"wger","de":{"name":"Bench Dips am Boden","description":"Übung (Körpergewicht) für den Bizeps, unterstützt von Trizeps, Schultern, Brust, Waden, Rücken.","instructions":["Trizeps-Dips am Boden sind eine Verbundübung, da sie mehrere Muskelgruppen gleichzeitig beanspruchen. Obwohl diese Körpergewichtsübung hauptsächlich den Trizeps trainiert, beansprucht sie auch deine Brust und die Vorderseite deiner Schulter.","Trizeps-Dips am Boden gehören zu den wirksamsten Übungen, um die Armkraft zu steigern und außerdem schlanke Muskeln in deinen Oberarmen aufzubauen.","Trizeps-Dips am Boden sind eine Übung mit geschlossener kinetischer Kette, das heißt, du führst die Bewegungen um einen festen Punkt herum aus. Das erhöht die Druckkraft auf deine Gelenke und verbessert dadurch die Stabilität."]}},{"id":"ex-bench-jump","slug":"bench-jump","name":"Bench Jump","description":"Bodyweight exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Begin with a box or bench 1-2 feet in front of you. Stand with your feet shoulder width apart. This will be your starting position.","Perform a short squat in preparation for the jump; swing your arms behind you.","Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.","Jump over the bench, landing with the knees bent, absorbing the impact through the legs.","Turn around and face the opposite direction, then jump back over the bench."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["bench jump"],"media":[{"id":"bench-jump-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Jump/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bench-jump-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Jump/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-bench-press","slug":"bench-press","name":"Bench Press","description":"Barbell exercise for the chest, with shoulders, triceps assisting.","instructions":["Lay down on a bench, the bar should be directly above your eyes, the knees are somewhat angled and the feet are firmly on the floor. Concentrate, breath deeply and grab the bar more than shoulder wide. Bring it slowly down till it briefly touches your chest at the height of your nipples. Push the bar up.","If you train with a high weight it is advisable to have a spotter that can help you up if you can't lift the weight on your own.","With the width of the grip you can also control which part of the chest is trained more:","wide grip: outer chest muscles","narrow grip: inner chest muscles and triceps"],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["bench press","bankdrücken"],"media":[{"id":"bench-press-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/192/Bench-press-1.png","caption":"Bench Press","attribution":"wger.de · Everkinetic","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Bankdrücken","description":"Übung (Langhantel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":["Lege dich auf die Bank, die Stange direkt über die Augen, die Knie etwas angewinkelt und die Füße fest auf dem Boden. Greife die Stange breit und lasse sie langsam und kontrolliert runter, dabei sollte die Stange kurz auf Brustwarzenhöhe den Körper berühren. Dann das Gewicht wieder hochdrücken bis die Arme durchgestreckt sind.","Bei hohem Gewicht, empfielt sich natürlich einen Spotter zu haben, der einen hilft falls man die Stange nicht alleine hochdrücken kann.","Mit der Breite des Griffs kann außerdem kontrolliert werden, welcher Bereich der Brust stärker belastet wird:","breiter Griff: äußere Brustmuskeln","enger Griff: innere Brustmuskeln und Trizeps"]}},{"id":"ex-bench-press-powerlifting","slug":"bench-press-powerlifting","name":"Bench Press - Powerlifting","description":"Barbell exercise for the triceps, with chest, forearms, back, shoulders assisting.","instructions":["Begin by lying on the bench, getting your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.","However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart.","Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.","Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","FOREARMS","BACK","SHOULDERS"],"equipment":"BARBELL","tags":["bench press - powerlifting"],"media":[{"id":"bench-press-powerlifting-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Press_-_Powerlifting/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bench-press-powerlifting-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Press_-_Powerlifting/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Trizeps, unterstützt von Brust, Unterarme, Rücken, Schultern.","instructions":null}},{"id":"ex-bench-press-with-bands","slug":"bench-press-with-bands","name":"Bench Press - With Bands","description":"Resistance band exercise for the chest, with shoulders, triceps assisting.","instructions":["Using a flat bench secure a band under the leg of the bench that is nearest to your head.","Once the band is secure, grab it by both handles and lie down on the bench.","Extend your arms so that you are holding the band handles in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","Bring down the handles slowly until your elbow forms a 90 degree angle. Keep full control at all times.","As you breathe out, bring the handles up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions of your training program."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BAND","tags":["bench press - with bands"],"media":[{"id":"bench-press-with-bands-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Press_-_With_Bands/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bench-press-with-bands-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Press_-_With_Bands/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Widerstandsband) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-bench-press-with-chains","slug":"bench-press-with-chains","name":"Bench Press with Chains","description":"Barbell exercise for the triceps, with chest, back, shoulders assisting.","instructions":["Adjust the leader chain, shortening it to the desired length.Place the chains on the sleeves of the bar.","Lying on the bench, get your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.","Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.","Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","BACK","SHOULDERS"],"equipment":"BARBELL","tags":["bench press with chains"],"media":[{"id":"bench-press-with-chains-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Press_with_Chains/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bench-press-with-chains-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Press_with_Chains/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Trizeps, unterstützt von Brust, Rücken, Schultern.","instructions":null}},{"id":"ex-bench-sprint","slug":"bench-sprint","name":"Bench Sprint","description":"Accessory exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Stand on the ground with one foot resting on a bench or box with your heel close to the edge.","Push off with your foot on top of the bench, extending through the hip and knee.","Land with the opposite foot on top of the box, returning your other foot back to the start position.","Continue alternating from one foot to another to complete the set."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"OTHER","tags":["bench sprint"],"media":[{"id":"bench-sprint-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Sprint/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bench-sprint-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Sprint/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-benchpress-dumbbells","slug":"benchpress-dumbbells","name":"Benchpress Dumbbells","description":"Dumbbell exercise for the chest, with shoulders, triceps assisting.","instructions":["Setup and Starting Position: Sit at the end of a flat bench with a dumbbell resting vertically against each thigh. Carefully lean back while driving the dumbbells toward your chest with your knees.","The “Leg Drive” and Posture: Plant your feet firmly on the floor. Retract your shoulder blades (press them together against the bench) and maintain a slight natural lumbar curve.","Starting Position: Push the dumbbells toward the ceiling. Your wrists should be aligned with your elbows. Rotate the dumbbells slightly inward (about 45 degrees) so that your elbows do not splay out too far to the sides, thereby protecting your shoulders.","Eccentric Phase (Lowering): Lower the dumbbells in a controlled manner toward the sides of your chest. Your elbows should lower at an angle of about 45–60 degrees relative to your body. Feel the stretch in the lower part of your chest.","Concentric Phase (Lift): Push the weight upward in a slight arc (toward the center), without letting the dumbbells collide at the top or fully locking out your elbows to maintain muscle tension. Exhale as you lift.","Translated with DeepL.com (free version)"],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"DUMBBELL","tags":["benchpress dumbbells","bankdrücken"],"media":[{"id":"benchpress-dumbbells-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/97/Dumbbell-bench-press-1.png","caption":"Benchpress Dumbbells","attribution":"wger.de · Everkinetic","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Bankdrücken","description":"Übung (Kurzhantel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":["Der Bewegungsablauf ist ähnlich zur Übung mit einer Langhantel.","Nehme die Gewichte in die Hände und lege dich auf die Bank. Halte die Hanteln neben der Brust auf Brustwarzenhöhe und drücke sie nun nach oben, bis die Arme ausgestreckt sind. Lasse die Gewichte nun langsam und kontrolliert runter."]}},{"id":"ex-bent-arm-barbell-pullover","slug":"bent-arm-barbell-pullover","name":"Bent-Arm Barbell Pullover","description":"Barbell exercise for the back, with chest, shoulders, triceps assisting.","instructions":["Lie on a flat bench with a barbell using a shoulder grip width.","Hold the bar straight over your chest with a bend in your arms. This will be your starting position.","While keeping your arms in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.","At that point, bring the barbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.","Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["CHEST","SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["bent-arm barbell pullover"],"media":[{"id":"bent-arm-barbell-pullover-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent-Arm_Barbell_Pullover/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bent-arm-barbell-pullover-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent-Arm_Barbell_Pullover/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Brust, Schultern, Trizeps.","instructions":null}},{"id":"ex-bent-arm-dumbbell-pullover","slug":"bent-arm-dumbbell-pullover","name":"Bent-Arm Dumbbell Pullover","description":"Dumbbell exercise for the chest, with back, shoulders, triceps assisting.","instructions":["Place a dumbbell standing up on a flat bench.","Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.","Grasp the dumbbell with both hands and hold it straight over your chest with a bend in your arms. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position. Caution: Always ensure that the dumbbell used for this exercise is secure. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.","While keeping your arms locked in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.","At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.","Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["BACK","SHOULDERS","TRICEPS"],"equipment":"DUMBBELL","tags":["bent-arm dumbbell pullover"],"media":[{"id":"bent-arm-dumbbell-pullover-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent-Arm_Dumbbell_Pullover/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bent-arm-dumbbell-pullover-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent-Arm_Dumbbell_Pullover/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Brust, unterstützt von Rücken, Schultern, Trizeps.","instructions":null}},{"id":"ex-bent-high-pulls","slug":"bent-high-pulls","name":"Bent High Pulls","description":"Dumbbell exercise for the back.","instructions":["Bend over slightly while holding two dumbbells.  Pull the dumbbells up to your chest, keeping your elbows as high as you can."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["bent high pulls","vorgebeugtes high pull"],"media":[{"id":"bent-high-pulls-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/79/da58dfbf-748a-461b-891e-3d6bc9cc4be2.png","caption":"Bent High Pulls","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Vorgebeugtes High Pull","description":"Übung (Kurzhantel) für den Rücken.","instructions":["Beuge dich leicht nach vorne, während du zwei Kurzhanteln hältst. Ziehe die Kurzhanteln zur Brust hinauf und halte dabei deine Ellbogen so hoch wie möglich."]}},{"id":"ex-bent-knee-hip-raise","slug":"bent-knee-hip-raise","name":"Bent-Knee Hip Raise","description":"Bodyweight exercise for the core.","instructions":["Lay flat on the floor with your arms next to your sides.","Now bend your knees at around a 75 degree angle and lift your feet off the floor by around 2 inches.","Using your lower abs, bring your knees in towards you as you maintain the 75 degree angle bend in your legs. Continue this movement until you raise your hips off of the floor by rolling your pelvis backward. Breathe out as you perform this portion of the movement. Tip: At the end of the movement your knees will be over your chest.","Squeeze your abs at the top of the movement for a second and then return to the starting position slowly as you breathe in. Tip: Maintain a controlled motion at all times.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["bent-knee hip raise"],"media":[{"id":"bent-knee-hip-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent-Knee_Hip_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bent-knee-hip-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent-Knee_Hip_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-bent-over-dumbbell-rear-delt-raise-with-head-on-bench","slug":"bent-over-dumbbell-rear-delt-raise-with-head-on-bench","name":"Bent Over Dumbbell Rear Delt Raise With Head On Bench","description":"Dumbbell exercise for the shoulders.","instructions":["Stand up straight while holding a dumbbell in each hand and with an incline bench in front of you.","While keeping your back straight and maintaining the natural arch of your back, lean forward until your forehead touches the bench in front of you. Let the arms hang in front of you perpendicular to the ground. The palms of your hands should be facing each other and your torso should be parallel to the floor. This will be your starting position.","Keeping your torso forward and stationary, and the arms straight with a slight bend at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. Caution: avoid swinging the torso or bringing the arms back as opposed to the side.","After a one second contraction at the top, slowly lower the dumbbells back to the starting position.","Repeat the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["bent over dumbbell rear delt raise with head on bench"],"media":[{"id":"bent-over-dumbbell-rear-delt-raise-with-head-on-bench-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bent-over-dumbbell-rear-delt-raise-with-head-on-bench-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern.","instructions":null}},{"id":"ex-bent-over-dumbbell-rows-single-arm","slug":"bent-over-dumbbell-rows-single-arm","name":"Bent Over Dumbbell Rows (Single Arm)","description":"Dumbbell exercise for the back.","instructions":["With dumbbells in hand, bend at the hip until hands hang just below the knees (similar to straight-legged-deadlift starting position). Keep upper body angle constant while contracting your lats to pull you ellbows back pinching the shoulder blades at the top. Try not to stand up with every rep, check hands go below knees on every rep."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["bent over dumbbell rows (single arm)","rudern einarmig"],"media":[{"id":"bent-over-dumbbell-rows-single-arm-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/81/a751a438-ae2d-4751-8d61-cef0e9292174.png","caption":"Bent Over Dumbbell Rows (Single Arm)","attribution":"wger.de · Franpol","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Rudern Einarmig","description":"Übung (Kurzhantel) für den Rücken.","instructions":["Nehme eine Flachbank und setze das Knie eines Beines auf ein Ende, das andere Bein ist daneben und leicht angewinkelt. Beuge deinen Oberkörper nach vorn und benutze deine Hand um dich abzustützen. Der Rücken macht einen leichten Hohlkreuz. Greife die Hantel mit der freien Hand und hebe sie eng am Körper entlang (achte auf die Ellenbogen). Bringe sie langsam nach unten und wiederhole die Bewegung sobald du unten angekommen bist. Wechsle danach die Seite."]}},{"id":"ex-bent-over-lateral-raises","slug":"bent-over-lateral-raises","name":"Bent-over Lateral Raises","description":"Dumbbell exercise for the shoulders.","instructions":["Sit on bench while holding weights. Bend forward as far as possible, with arms slightly bent at the elbow. Perform a lateral raise while maintaining the bend in your elbow."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["bent-over lateral raises","vorgebeugtes seitheben"],"media":[],"source":"wger","de":{"name":"Vorgebeugtes Seitheben","description":"Übung (Kurzhantel) für die Schultern.","instructions":["Setze dich auf dem Rand einer Flachbank und beuge den Körper so weit nach vorne, dass er parallel zum Boden ist. Nehme nun die Hanteln und hebe sie seitwärts bis etwas über schulterhöhe. Gehe langsam wieder runter.","Es ist wichtig, während der Übung, die Arme nicht nach vorn oder nach hinten zu bewegen, sie sollten stets einen rechten Winkel mit dem Körper haben. Wie beim Seitheben im Stehen, sollten sich die Handflächen nicht drehen, sie zeigen also immer zum Boden oder zum Körper."]}},{"id":"ex-bent-over-low-pulley-side-lateral","slug":"bent-over-low-pulley-side-lateral","name":"Bent Over Low-Pulley Side Lateral","description":"Cable exercise for the shoulders, with back assisting.","instructions":["Select a weight and hold the handle of the low pulley with your right hand.","Bend at the waist until your torso is nearly parallel to the floor. Your legs should be slightly bent with your left hand placed on your lower left thigh. Your right arm should be hanging from your shoulder in front of you and with a slight bend at the elbow. This will be your starting position.","Raise your right arm, elbow slightly bent, to the side until the arm is parallel to the floor and in line with your right ear. Breathe out as you perform this step.","Slowly lower the weight back to the starting position as you breathe in.","Repeat for the recommended amount of repetitions and repeat the movement with the other arm."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"CABLE","tags":["bent over low-pulley side lateral"],"media":[{"id":"bent-over-low-pulley-side-lateral-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Low-Pulley_Side_Lateral/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bent-over-low-pulley-side-lateral-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Low-Pulley_Side_Lateral/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Schultern, unterstützt von Rücken.","instructions":null}},{"id":"ex-bent-over-one-arm-long-bar-row","slug":"bent-over-one-arm-long-bar-row","name":"Bent Over One-Arm Long Bar Row","description":"Barbell exercise for the back, with biceps assisting.","instructions":["Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.","Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.","Now grab the bar with one arm just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.","Pull the bar straight up with your elbow in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Do not allow for any swinging of the torso. Only the arm should move.","Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).","Repeat for the recommended amount of repetitions and switch arms."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"BARBELL","tags":["bent over one-arm long bar row"],"media":[{"id":"bent-over-one-arm-long-bar-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_One-Arm_Long_Bar_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bent-over-one-arm-long-bar-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_One-Arm_Long_Bar_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-bent-over-row-to-external-rotation","slug":"bent-over-row-to-external-rotation","name":"Bent over row to external rotation","description":"Bodyweight exercise for the back.","instructions":["Starting position:","Stand behind a chair or in front of a table. Bend at the waist to put your forehead on the chair's headrest or table, keeping your back straight. Your arms should be hanging straight down, pointed at the floor.","Steps:","Bring your elbows up to shoulder height. Your forearms should be pointing down, perpendicular to your biceps. Your biceps should be at the same height as your back and perpendicular to your spine.","Hold for a bit.","Rotate at your elbows to bring your hands as far up as you can.","Hold for a bit.","Rotate at your elbows back to the previous position."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["bent over row to external rotation","vorgebeugtes rudern mit außenrotation"],"media":[],"source":"wger","de":{"name":"Vorgebeugtes Rudern mit Außenrotation","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Ausgangsposition:","Stelle dich hinter einen Stuhl oder vor einen Tisch. Beuge dich in der Hüfte nach vorne, um deine Stirn auf die Rückenlehne des Stuhls oder den Tisch zu legen, wobei du den Rücken gerade hältst. Deine Arme sollten gerade nach unten hängen und zum Boden zeigen.","Ablauf:","Hebe deine Ellbogen auf Schulterhöhe. Deine Unterarme sollten nach unten zeigen, senkrecht zu deinen Oberarmen. Deine Oberarme sollten sich auf gleicher Höhe wie dein Rücken befinden und senkrecht zu deiner Wirbelsäule stehen.","Halte kurz.","Rotiere in den Ellbogen, um deine Hände so weit wie möglich nach oben zu bringen.","Halte kurz.","Rotiere in den Ellbogen zurück in die vorherige Position."]}},{"id":"ex-bent-over-rowing","slug":"bent-over-rowing","name":"Bent Over Rowing","description":"Barbell exercise for the back, with shoulders, biceps assisting.","instructions":["Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.","Then inhale and slowly lower the barbell back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["SHOULDERS","BICEPS"],"equipment":"BARBELL","tags":["bent over rowing","rudern vorgebeugt"],"media":[{"id":"bent-over-rowing-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/109/Barbell-rear-delt-row-1.png","caption":"Bent Over Rowing","attribution":"wger.de · Everkinetic","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Rudern Vorgebeugt","description":"Übung (Langhantel) für den Rücken, unterstützt von Schultern, Bizeps.","instructions":["Greife die Langhantel mit breitem (etwas mehr als Schulterbreit) Griff und beuge dich nach vorne. Dabei ist der Oberkörper nicht ganz Waagerecht, sonder ein bisschen steiler, der Kopf schaut nach vorn und die Brust is rausgestreckt.","Ziehe nun das Gewicht in richtung Bauchnabel. Schwinge während der Bewegung den Oberkörper nicht und halte die Arme dicht am Körper wenn du sie hochziehst. Bringe die Hantel langsam wieder nach unten."]}},{"id":"ex-bent-over-two-arm-long-bar-row","slug":"bent-over-two-arm-long-bar-row","name":"Bent Over Two-Arm Long Bar Row","description":"Barbell exercise for the back, with biceps assisting.","instructions":["Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.","Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.","Now grab the bar with both arms just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.","Pull the bar straight up with your elbows in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Use a stirrup or double handle cable attachment by hooking it under the end of the bar.","Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"BARBELL","tags":["bent over two-arm long bar row"],"media":[{"id":"bent-over-two-arm-long-bar-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Two-Arm_Long_Bar_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bent-over-two-arm-long-bar-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Two-Arm_Long_Bar_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-bent-over-two-dumbbell-row-with-palms-in","slug":"bent-over-two-dumbbell-row-with-palms-in","name":"Bent Over Two-Dumbbell Row With Palms In","description":"Dumbbell exercise for the back, with biceps assisting.","instructions":["With a dumbbell in each hand (palms facing each other), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","While keeping the torso stationary, lift the dumbbells to your side as you breathe out, squeezing your shoulder blades together. On the top contracted position, squeeze the back muscles and hold for a second.","Slowly lower the weight again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"DUMBBELL","tags":["bent over two-dumbbell row with palms in"],"media":[{"id":"bent-over-two-dumbbell-row-with-palms-in-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Two-Dumbbell_Row_With_Palms_In/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bent-over-two-dumbbell-row-with-palms-in-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Two-Dumbbell_Row_With_Palms_In/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-bent-press","slug":"bent-press","name":"Bent Press","description":"Kettlebell exercise for the core, with glutes, hamstrings, back, quadriceps, shoulders, triceps assisting.","instructions":["Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. This will be your starting position.","Begin my leaning to the side opposite the kettlebell, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebell. As you do so, press the weight vertically be extending through the elbow, keeping your arm perpendicular to the ground.","Return to an upright position, with the kettlebell above your head. Return the kettlebell to the shoulder and repeat for the desired number of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["GLUTES","HAMSTRINGS","BACK","QUADRICEPS","SHOULDERS","TRICEPS"],"equipment":"KETTLEBELL","tags":["bent press"],"media":[{"id":"bent-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bent-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für den Rumpf, unterstützt von Po, Oberschenkelrückseite, Rücken, Oberschenkelvorderseite, Schultern, Trizeps.","instructions":null}},{"id":"ex-biceps-curl-with-cable","slug":"biceps-curl-with-cable","name":"Biceps Curl With Cable","description":"Cable exercise for the biceps.","instructions":["Stand around 30 - 40cm away from the cable, the feet are firmly on the floor. Take the bar and lift the weight with a fast movements. Lower the weight as with the dumbbell curls slowly and controlled."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["biceps curl with cable","bizeps am kabel"],"media":[{"id":"biceps-curl-with-cable-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/129/Standing-biceps-curl-1.png","caption":"Biceps Curl With Cable","attribution":"wger.de · Everkinetic","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Bizeps am Kabel","description":"Übung (Kabelzug) für den Bizeps.","instructions":["Stelle dich gerade etwa 30 - 40 cm. vor dem Kabel hin, die Füße sind fest auf dem Boden. Nehme die Stange in die Hände und hebe das Gewicht mit einer schnellen Bewegung. Lassie die Stange wie bei den KH Curls kontrolliert wieder runter."]}},{"id":"ex-biceps-curls-with-barbell","slug":"biceps-curls-with-barbell","name":"Biceps Curls With Barbell","description":"Barbell exercise for the biceps.","instructions":["Hold the Barbell shoulder-wide, the back is straight, the shoulders slightly back, the arms are streched. Bend the arms, bringing the weight up, with a fast movement. Without pausing, let down the bar with a slow and controlled movement.","Don't allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows)."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["biceps curls with barbell","bizeps lh-curls"],"media":[{"id":"biceps-curls-with-barbell-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/74/Bicep-curls-1.png","caption":"Biceps Curls With Barbell","attribution":"wger.de · Everkinetic","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Bizeps LH-Curls","description":"Übung (Langhantel) für den Bizeps.","instructions":["Halte die Hantel mit etwa schulterbreitem Griff, die Arme sind ausgestreckt. Beuge die Arme und brige die Hantel mit einer schnellen Bewegung nach oben. Ohne Pause wird das Gewicht nun kontrolliert nach unten gebracht. Beachte, dass die Bewegung nach oben schneller ist als nach unten.","Während des Bewegungablaufs sollte der Körper nicht mitschwingen. Die Ellenbogen bleiben dabei immer an der Stelle."]}},{"id":"ex-biceps-with-trx","slug":"biceps-with-trx","name":"Biceps with TRX","description":"Bodyweight exercise for the biceps.","instructions":["Grab the handles of the TRX straps, lean your body back, arms and legs extended, with your body positioned in a single straight line. (This is an arm exercise, not an abdominal one.)"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["biceps with trx","bizeps mit trx"],"media":[{"id":"biceps-with-trx-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/958/947ac249-475d-44ed-bed3-8dc433374f59.png","caption":"Biceps with TRX","attribution":"wger.de · cynomops","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Bizeps mit TRX","description":"Übung (Körpergewicht) für den Bizeps.","instructions":["Greife die Griffe der TRX-Schlaufen, lehne deinen Körper nach hinten, Arme und Beine gestreckt, wobei dein Körper eine einzige gerade Linie bildet. (Dies ist eine Übung für die Arme, nicht für die Bauchmuskulatur.)"]}},{"id":"ex-bicycle-crunches","slug":"bicycle-crunches","name":"bicycle crunches","description":"Bodyweight exercise for the core.","instructions":["Bicycle crunches are a core exercise performed on the floor. Lie on your back with your hands behind your head and legs extended. Lift your shoulders off the ground, bring one knee toward your chest, and twist your torso so your opposite elbow meets the knee. Alternate sides in a pedaling motion, ensuring controlled movements and engaging your core throughout the exercise."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["bicycle crunches"],"media":[],"source":"wger","de":{"name":"Bicycle Crunches","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Bicycle Crunches sind eine Rumpfübung, die auf dem Boden ausgeführt wird. Lege dich auf den Rücken, die Hände hinter dem Kopf und die Beine ausgestreckt. Hebe deine Schultern vom Boden ab, ziehe ein Knie zur Brust und drehe deinen Oberkörper, sodass dein gegenüberliegender Ellbogen das Knie trifft. Wechsle die Seiten in einer tretenden Bewegung ab, achte dabei auf kontrollierte Bewegungen und halte deinen Rumpf während der gesamten Übung angespannt."]}},{"id":"ex-bizeps-curls-trifecta","slug":"bizeps-curls-trifecta","name":"Bizeps Curls Trifecta","description":"Dumbbell exercise for the biceps.","instructions":["This exercise is a mixture of three different curls: the Supinated Cross Body Curl, the Pronated Cross Body Curl and the No Money Curl. You","alternate between three curl variations that each accomplish different goals,","and you’ll keep the set going beyond the usual 8-12 rep range which gives","us that intensity.","For the Supinated Cross Body","Curl, supinate the forearm with palms facing toward the ceiling and","forearms coming across the body. Lift the inner-facing weight of the dumbbell towards your shoulder.","For the Pronated Cross Body"],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["bizeps curls trifecta","bizeps-curls-trifecta"],"media":[],"source":"wger","de":{"name":"Bizeps-Curls-Trifecta","description":"Übung (Kurzhantel) für den Bizeps.","instructions":["Diese Übung ist eine Mischung aus drei verschiedenen Curls: dem Supinated Cross Body Curl, dem Pronated Cross Body Curl und dem No Money Curl. Du","wechselst zwischen drei Curl-Varianten, die jeweils unterschiedliche Ziele erfüllen,","und du führst den Satz über den üblichen Bereich von 8-12 Wiederholungen hinaus fort, was","uns diese Intensität verleiht.","Für den Supinated Cross Body","Curl supinierst du den Unterarm, sodass die Handflächen zur Decke zeigen und","die Unterarme quer über den Körper geführt werden. Hebe das innen liegende Gewicht der Kurzhantel zu deiner Schulter.","Für den Pronated Cross Body"]}},{"id":"ex-board-press","slug":"board-press","name":"Board Press","description":"Barbell exercise for the triceps, with chest, forearms, back, shoulders assisting.","instructions":["Begin by lying on the bench, getting your head beyond the bar if possible. One to five boards, made out of 2x6's, can be screwed together and held in place by a training partner, bands, or just tucked under your shirt.","Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.","You can take a standard bench grip, or shoulder width to focus on the triceps. Pull the bar out of the rack without protracting your shoulders. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.","Lower the bar to the boards, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","FOREARMS","BACK","SHOULDERS"],"equipment":"BARBELL","tags":["board press"],"media":[{"id":"board-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Board_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"board-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Board_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Trizeps, unterstützt von Brust, Unterarme, Rücken, Schultern.","instructions":null}},{"id":"ex-body-tricep-press","slug":"body-tricep-press","name":"Body Tricep Press","description":"Bodyweight exercise for the triceps.","instructions":["Position a bar in a rack at chest height.","Standing, take a shoulder width grip on the bar and step a yard or two back, feet together and arms extended so that you are leaning on the bar. This will be your starting position.","Begin by flexing the elbow, lowering yourself towards the bar.","Pause, and then reverse the motion by extending the elbows.","Progress from bodyweight by adding chains over your shoulders."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["body tricep press"],"media":[{"id":"body-tricep-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Body_Tricep_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"body-tricep-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Body_Tricep_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Trizeps.","instructions":null}},{"id":"ex-body-up","slug":"body-up","name":"Body-Up","description":"Bodyweight exercise for the triceps, with core, forearms assisting.","instructions":["Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position.","Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement.","Slowly lower your forearms back to the ground by allowing the elbows to flex.","Repeat."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["ABS_CORE","FOREARMS"],"equipment":"BODYWEIGHT","tags":["body-up"],"media":[{"id":"body-up-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Body-Up/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"body-up-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Body-Up/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Trizeps, unterstützt von Rumpf, Unterarme.","instructions":null}},{"id":"ex-bodyweight-biceps-curl","slug":"bodyweight-biceps-curl","name":"Bodyweight Biceps Curl","description":"Bodyweight exercise for the biceps.","instructions":["Set up under a straight bar (around waist or chest height). Grip the bar with your palms facing you (supinated grip), hands about shoulder-width apart. Lean back with straight arms so that your body is at an angle to the ground. Keeping your elbows high and close to the bar, pull your upper body toward the bar by flexing your elbows, similar to a biceps curl. Lower yourself back down in a controlled manner. Keep your core tight and movement slow to maximize tension on the biceps."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["bodyweight biceps curl","bizeps-curl mit dem eigenen körpergewicht"],"media":[],"source":"wger","de":{"name":"Bizeps-Curl mit dem eigenen Körpergewicht","description":"Übung (Körpergewicht) für den Bizeps.","instructions":["Positioniere dich unter einer geraden Stange (etwa auf Hüft- oder Brusthöhe). Greife die Stange mit den Handflächen zu dir zeigend (Untergriff), die Hände etwa schulterbreit auseinander. Lehne dich mit gestreckten Armen zurück, sodass dein Körper im Winkel zum Boden steht. Halte deine Ellbogen hoch und nah an der Stange und ziehe deinen Oberkörper zur Stange, indem du die Ellbogen beugst, ähnlich wie bei einem Bizeps-Curl. Senke dich kontrolliert wieder ab. Halte deinen Rumpf angespannt und die Bewegung langsam, um die Spannung auf den Bizeps zu maximieren."]}},{"id":"ex-bodyweight-flyes","slug":"bodyweight-flyes","name":"Bodyweight Flyes","description":"EZ-bar exercise for the chest, with core, shoulders, triceps assisting.","instructions":["Position two equally loaded EZ bars on the ground next to each other. Ensure they are able to roll.","Assume a push-up position over the bars, supporting your weight on your toes and hands with your arms extended and body straight.","Place your hands on the bars. This will be your starting position.","Using a slow and controlled motion, move your hands away from the midline of your body, rolling the bars apart. Inhale during this portion of the motion.","After moving the bars as far apart as you can, return to the starting position by pulling them back together. Exhale as you perform this movement."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["ABS_CORE","SHOULDERS","TRICEPS"],"equipment":"EZ_BAR","tags":["bodyweight flyes"],"media":[{"id":"bodyweight-flyes-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bodyweight_Flyes/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bodyweight-flyes-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bodyweight_Flyes/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (SZ-Stange) für die Brust, unterstützt von Rumpf, Schultern, Trizeps.","instructions":null}},{"id":"ex-bodyweight-lunge","slug":"bodyweight-lunge","name":"Bodyweight lunge","description":"Bodyweight exercise for the quadriceps, with glutes, calves assisting.","instructions":["Bodyweight lunges are an effective calisthenic exercise for","strengthening the lower body, improving balance and stability, and","developing functional strength. They are a popular choice for bodyweight workouts, home workouts, and can also be included as part of a larger strength training routine."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","CALVES"],"equipment":"BODYWEIGHT","tags":["bodyweight lunge","ausfallschritt mit körpergewicht"],"media":[],"source":"wger","de":{"name":"Ausfallschritt mit Körpergewicht","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Po, Waden.","instructions":["Ausfallschritte mit Körpergewicht sind eine wirksame Calisthenics-Übung, um","den Unterkörper zu kräftigen, das Gleichgewicht und die Stabilität zu verbessern und","funktionelle Kraft zu entwickeln. Sie sind eine beliebte Wahl für Körpergewichts-Workouts, Heimtrainings und können auch als Teil eines umfangreicheren Krafttrainings eingebaut werden."]}},{"id":"ex-bodyweight-mid-row","slug":"bodyweight-mid-row","name":"Bodyweight Mid Row","description":"Accessory exercise for the back, with biceps assisting.","instructions":["Begin by taking a medium to wide grip on a pull-up apparatus with your palms facing away from you. From a hanging position, tuck your knees to your chest, leaning back and getting your legs over your side of the pull-up apparatus. This will be your starting position.","Beginning with your arms straight, flex the elbows and retract the shoulder blades to raise your body up until your legs contact the pull-up apparatus.","After a brief pause, return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"OTHER","tags":["bodyweight mid row"],"media":[{"id":"bodyweight-mid-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bodyweight_Mid_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bodyweight-mid-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bodyweight_Mid_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-bodyweight-walking-lunge","slug":"bodyweight-walking-lunge","name":"Bodyweight Walking Lunge","description":"Equipment-free exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Begin standing with your feet shoulder width apart and your hands on your hips.","Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.","Drive through the heel of your lead foot and extend both knees to raise yourself back up.","Step forward with your rear foot, repeating the lunge on the opposite leg."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"NONE","tags":["bodyweight walking lunge"],"media":[{"id":"bodyweight-walking-lunge-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bodyweight_Walking_Lunge/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bodyweight-walking-lunge-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bodyweight_Walking_Lunge/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-bosu-ball-cable-crunch-with-side-bends","slug":"bosu-ball-cable-crunch-with-side-bends","name":"Bosu Ball Cable Crunch With Side Bends","description":"Cable exercise for the core.","instructions":["Connect a standard handle to each arm of a cable machine, and position them in the most downward position.","Grab a Bosu Ball and position it in front and center of the cable machine.","Lie down on the Bosu Ball with the small of your back arched around the ball. Your rear end should be close to the floor without touching it.","With both hands, reach back and grab the handle of each cable.","With your feet positioned in a wide stance, extend your arms straight out in front of you and in between your knees. Your hands should be at knee level.","Keep your arms straight and in-line with the upward angle of the cable. Elevate your torso in a crunching motion without dropping or bending your arms.","Maintain the rigid position with your arms. Slowly descend back to the starting position with your back arched around the Bosu Ball and your abdominals elongated.","Repeat the same series of movements to failure.","Once you reach failure, keep your abs tight and raise your torso into plank position so your back is elevated off the Bosu Ball.","Lower your arms down to your side; keep them straight. Start doing alternating side bends; reach for your heels! This finishing movement will focus on your obliques."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["bosu ball cable crunch with side bends"],"media":[{"id":"bosu-ball-cable-crunch-with-side-bends-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bosu_Ball_Cable_Crunch_With_Side_Bends/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bosu-ball-cable-crunch-with-side-bends-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bosu_Ball_Cable_Crunch_With_Side_Bends/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rumpf.","instructions":null}},{"id":"ex-bottoms-up","slug":"bottoms-up","name":"Bottoms Up","description":"Bodyweight exercise for the core.","instructions":["Begin by lying on your back on the ground. Your legs should be straight and your arms at your side. This will be your starting position.","To perform the movement, tuck the knees toward your chest by flexing the hips and knees. Following this, extend your legs directly above you so that they are perpendicular to the ground. Rotate and elevate your pelvis to raise your glutes from the floor.","After a brief pause, return to the starting position."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["bottoms up"],"media":[{"id":"bottoms-up-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bottoms_Up/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bottoms-up-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bottoms_Up/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-bottoms-up-clean-from-the-hang-position","slug":"bottoms-up-clean-from-the-hang-position","name":"Bottoms-Up Clean From The Hang Position","description":"Kettlebell exercise for the forearms, with biceps, shoulders assisting.","instructions":["Initiate the exercise by standing upright with a kettlebell in one hand.","Swing the kettlebell back forcefully and then reverse the motion forcefully. Crush the kettlebell handle as hard as possible and raise the kettlebell to your shoulder."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":["BICEPS","SHOULDERS"],"equipment":"KETTLEBELL","tags":["bottoms-up clean from the hang position"],"media":[{"id":"bottoms-up-clean-from-the-hang-position-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bottoms-Up_Clean_From_The_Hang_Position/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bottoms-up-clean-from-the-hang-position-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bottoms-Up_Clean_From_The_Hang_Position/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Unterarme, unterstützt von Bizeps, Schultern.","instructions":null}},{"id":"ex-box-jump-multiple-response","slug":"box-jump-multiple-response","name":"Box Jump (Multiple Response)","description":"Accessory exercise for the hamstrings, with glutes, quadriceps, calves assisting.","instructions":["Assume a relaxed stance facing the box or platform approximately an arm's length away. Arms should be down at the sides and legs slightly bent.","Using the arms to aid in the initial burst, jump upward and forward, landing with feet simultaneously on top of the box or platform.","Immediately drop or jump back down to the original starting place; then repeat the sequence."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","QUADRICEPS","CALVES"],"equipment":"OTHER","tags":["box jump (multiple response)"],"media":[{"id":"box-jump-multiple-response-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Jump_Multiple_Response/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"box-jump-multiple-response-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Jump_Multiple_Response/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelrückseite, unterstützt von Po, Oberschenkelvorderseite, Waden.","instructions":null}},{"id":"ex-box-skip","slug":"box-skip","name":"Box Skip","description":"Accessory exercise for the hamstrings, with glutes, quadriceps, calves assisting.","instructions":["You will need several boxes lined up about 8 feet apart.","Begin facing the first box with one leg slightly behind the other.","Drive off the back leg, attempting to gain as much height with the hips as possible.","Immediately upon landing on the box, drive the other leg forward and upward to gain height and distance, leaping from the box. Land between the first two boxes with the same leg that landed on the first box.","Then, step to the next box and repeat."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","QUADRICEPS","CALVES"],"equipment":"OTHER","tags":["box skip"],"media":[{"id":"box-skip-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Skip/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"box-skip-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Skip/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelrückseite, unterstützt von Po, Oberschenkelvorderseite, Waden.","instructions":null}},{"id":"ex-box-squat","slug":"box-squat","name":"Box Squat","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings, back assisting.","instructions":["The box squat allows you to squat to desired depth and develop explosive strength in the squat movement. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.","Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","BACK"],"equipment":"BARBELL","tags":["box squat"],"media":[{"id":"box-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"box-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Box Squat","description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Rücken.","instructions":["Box aufstellen: Positioniere die Box hinter dir, etwa 90 cm von einem Kniebeugenständer entfernt, falls du eine Langhantel verwendest. Wähle eine Höhe, bei der du dich absenken und mit geradem Rücken die Gesäßmuskulatur sanft auf der Box auftippen kannst.","Mit korrekter Haltung stehen: Stehe mit schulterbreit aufgestellten Füßen, die Fußspitzen leicht nach außen gedreht. Spanne deinen Rumpf an und halte den Rücken neutral. Wenn du eine Langhantel verwendest, lege sie auf Schulterhöhe ab.","Absenken: Setze dich nach hinten, als würdest du dich auf einen Stuhl setzen, beuge die Knie und senke die Hüfte zur Box ab. Halte deinen Rumpf angespannt und den Rücken während der gesamten Bewegung gerade.","Kontrolliertes Absenken: Senke dich kontrolliert ab, bis deine Gesäßmuskulatur die Box sanft berührt. Lass dich nicht fallen.","Innehalten und hochdrücken: Halte unten kurz inne, mit geradem Rücken und angespanntem Rumpf. Drücke dich dann über die Fersen wieder in die Ausgangsposition hoch.","Verbesserungen bei Koordination, Gleichgewicht und Ausdauer, Straffung der Bein- und Gesäßmuskulatur sowie eine allgemeine Steigerung der Knochendichte, die das Risiko einer Osteoporose verringert."]}},{"id":"ex-box-squat-with-bands","slug":"box-squat-with-bands","name":"Box Squat with Bands","description":"Barbell exercise for the quadriceps, with glutes, calves, hamstrings, back assisting.","instructions":["Begin in a power rack with a box at the appropriate height behind you. Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension. If dumbbells are used, secure them so that they don't move. Also, ensure that the dumbbells you are using are heavy enough for the bands that you are using. Additional plates can be used to hold the dumbbells down. If more tension is needed, you can either widen the base on the floor or choke the bands. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.","Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barbell to the rack."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","CALVES","HAMSTRINGS","BACK"],"equipment":"BARBELL","tags":["box squat with bands"],"media":[{"id":"box-squat-with-bands-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Squat_with_Bands/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"box-squat-with-bands-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Squat_with_Bands/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Po, Waden, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-box-squat-with-chains","slug":"box-squat-with-chains","name":"Box Squat with Chains","description":"Barbell exercise for the quadriceps, with glutes, calves, hamstrings, back assisting.","instructions":["Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.","To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.","Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","CALVES","HAMSTRINGS","BACK"],"equipment":"BARBELL","tags":["box squat with chains"],"media":[{"id":"box-squat-with-chains-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Squat_with_Chains/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"box-squat-with-chains-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Squat_with_Chains/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Po, Waden, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-braced-squat","slug":"braced-squat","name":"Braced Squat","description":"Bodyweight exercise for the quadriceps, with glutes assisting.","instructions":["Stand with feet slightly wider than shoulder-width apart, while standing as tall as you can.","Grab a weight plate and hold it out in front of your body with arms straight out. Keep your core tight and stand with a natural arch in your back.","Now, push hips back and bend knees down into a squat as far as you can. Hold for a few moments and bring yourself back up to the starting position."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES"],"equipment":"BODYWEIGHT","tags":["braced squat","goblet-kniebeuge mit scheibe"],"media":[],"source":"wger","de":{"name":"Goblet-Kniebeuge mit Scheibe","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Po.","instructions":["Stelle dich mit den Füßen etwas weiter als schulterbreit hin und richte dich dabei so groß wie möglich auf.","Nimm eine Gewichtsscheibe und halte sie mit gestreckten Armen vor deinem Körper. Halte deinen Rumpf angespannt und stehe mit einer natürlichen Wölbung im Rücken.","Schiebe nun die Hüfte nach hinten und beuge die Knie so tief wie möglich in eine Kniebeuge. Halte einige Augenblicke und richte dich dann wieder in die Ausgangsposition auf."]}},{"id":"ex-brachialis-smr","slug":"brachialis-smr","name":"Brachialis-SMR","description":"Foam roller exercise for the biceps.","instructions":["Lie on your side, with your upper arm against the foam roller. The upper arm should be more or less aligned with your body, with the outside of the bicep pressed against the foam roller.","Raise your hips off of the floor, supporting your weight on your arm and on your feet. Hold for 10-30 seconds, and then switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"FOAM_ROLLER","tags":["brachialis-smr"],"media":[{"id":"brachialis-smr-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Brachialis-SMR/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"brachialis-smr-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Brachialis-SMR/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Faszienrolle) für den Bizeps.","instructions":null}},{"id":"ex-bradford-rocky-presses","slug":"bradford-rocky-presses","name":"Bradford/Rocky Presses","description":"Barbell exercise for the shoulders, with triceps assisting.","instructions":["Sit on a Military Press Bench with a bar at shoulder level with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down. This is your starting position.","Once you pick up the barbell with the correct grip, lift the bar up over your head by locking your arms.","Now lower the bar down to the back of the head slowly as you inhale.","Lift the bar back up to the starting position as you exhale.","Lower the bar down to the starting position slowly as you inhale. This is one repetition.","Alternate in this manner until you complete the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"BARBELL","tags":["bradford/rocky presses"],"media":[{"id":"bradford-rocky-presses-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bradford_Rocky_Presses/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"bradford-rocky-presses-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bradford_Rocky_Presses/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-bretzel-stretch","slug":"bretzel-stretch","name":"Bretzel stretch","description":"Bodyweight exercise for the glutes, with hamstrings, back, chest assisting.","instructions":["How to Perform the Bretzel Stretch","Starting Position: Lie on your back on a flat surface, such as a mat. Bend your knees and place your feet flat on the ground.","Leg Positioning: Lift your right leg and cross it over your left leg, placing your right foot on the outside of your left knee. Your left leg should remain flat on the ground.","Arm Positioning: Extend your left arm out to the side at shoulder height, keeping it straight. Use your right hand to gently pull your right knee towards the floor on the left side of your body.","Stretching: As you pull your knee down, try to keep your left shoulder flat on the ground. You should feel a stretch in your hip, lower back, and possibly your chest.","Hold the Position: Maintain this position for 20-30 seconds, breathing deeply and relaxing into the stretch. Switch sides and repeat the process."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["HAMSTRINGS","BACK","CHEST"],"equipment":"BODYWEIGHT","tags":["bretzel stretch","bretzel-dehnung"],"media":[],"source":"wger","de":{"name":"Bretzel-Dehnung","description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelrückseite, Rücken, Brust.","instructions":["So führst du die Bretzel-Dehnung aus","Ausgangsposition: Lege dich auf den Rücken auf eine flache Unterlage, zum Beispiel eine Matte. Beuge die Knie und stelle die Füße flach auf den Boden.","Beinposition: Hebe dein rechtes Bein an und kreuze es über dein linkes Bein, wobei du deinen rechten Fuß an der Außenseite deines linken Knies platzierst. Dein linkes Bein bleibt flach auf dem Boden.","Armposition: Strecke deinen linken Arm auf Schulterhöhe gerade zur Seite aus. Ziehe mit deiner rechten Hand dein rechtes Knie sanft auf die linke Seite deines Körpers in Richtung Boden.","Dehnung: Während du das Knie nach unten ziehst, versuche, deine linke Schulter flach auf dem Boden zu halten. Du solltest eine Dehnung in der Hüfte, im unteren Rücken und möglicherweise im Brustkorb spüren.","Halte die Position: Halte diese Position 20-30 Sekunden, atme tief durch und entspanne dich in die Dehnung hinein. Wechsle die Seite und wiederhole den Ablauf."]}},{"id":"ex-butchers-block-stretch","slug":"butchers-block-stretch","name":"Butchers Block Stretch","description":"Bodyweight exercise for the back.","instructions":["Kneel down with the hands together","Rest the elbows on a bench in front of you and lower the chest down","Keep the elbows bent with good posture and hold"],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["butchers block stretch","butcher's block dehnung"],"media":[],"source":"wger","de":{"name":"Butcher's Block Dehnung","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Knie dich hin und führe die Hände zusammen","Lege die Ellbogen auf einer Bank vor dir ab und senke den Brustkorb nach unten","Halte die Ellbogen gebeugt, achte auf eine gute Haltung und halte die Position"]}},{"id":"ex-butt-ups","slug":"butt-ups","name":"Butt-Ups","description":"Bodyweight exercise for the core.","instructions":["Begin a pushup position but with your elbows on the ground and resting on your forearms. Your arms should be bent at a 90 degree angle.","Arch your back slightly out rather than keeping your back completely straight.","Raise your glutes toward the ceiling, squeezing your abs tightly to close the distance between your ribcage and hips. The end result will be that you'll end up in a high bridge position. Exhale as you perform this portion of the movement.","Lower back down slowly to your starting position as you breathe in. Tip: Don't let your back sag downwards.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["butt-ups"],"media":[{"id":"butt-ups-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butt-Ups/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"butt-ups-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butt-Ups/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-butterfly-narrow-grip","slug":"butterfly-narrow-grip","name":"Butterfly Narrow Grip","description":"Bodyweight exercise for the chest.","instructions":["The movement is the same as with a regular butterfly, only that the grip is narrow:","Sit on the butterfly machine, the feet have a good contact with the floor, the upper arms are parallel to the floor. Press your arms together till the handles are practically together (but aren't!). Go slowly back. The weights should stay all the time in the air."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["butterfly narrow grip","butterfly eng"],"media":[],"source":"wger","de":{"name":"Butterfly Eng","description":"Übung (Körpergewicht) für die Brust.","instructions":["Setzte dich auf den Sitz der Butterflymaschine, die Füße sollen dabei guten Kontakt mit dem Boden machen, die Ellenbogen machen etwa einen Rechten Winkel, die Oberarme sind waagerecht zum Boden. Drücke nun die Gewichte zusammen, wobei die Griffe sich nicht berühren sollen. Gehe nun wieder zurück, das Trainingsgewicht darf dabei nicht abgelegt werden."]}},{"id":"ex-butterfly-sit-up","slug":"butterfly-sit-up","name":"Butterfly Sit Up","description":"Bodyweight exercise for the core.","instructions":["this midrange exercise your arm muscles provide you with a little bit of","momentum to help to get you off the ground. You also open them up in overhead","position which engages the upper back. Start","lying with feet flat on the ground, knees at an angle, arms crossed in towards your chest. Using","your ab muscles, bring your upper body off the ground as you open your arms","into goal post position, then slowly lower yourself back down to return to","starting position."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["butterfly sit up","butterfly sit-up"],"media":[],"source":"wger","de":{"name":"Butterfly Sit-up","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Bei","dieser Übung im mittleren Bewegungsbereich verleihen dir deine Armmuskeln ein wenig","Schwung, der dir hilft, vom Boden hochzukommen. Du öffnest sie außerdem in der Überkopf-Position,","was den oberen Rücken aktiviert. Beginne","liegend mit flach auf dem Boden stehenden Füßen, die Knie angewinkelt, die Arme vor der Brust gekreuzt. Hebe","mit deiner Bauchmuskulatur deinen Oberkörper vom Boden ab, während du deine Arme","in die Goalpost-Position öffnest, und senke dich dann langsam wieder ab, um in die","Ausgangsposition zurückzukehren."]}},{"id":"ex-butterfly-stretch","slug":"butterfly-stretch","name":"Butterfly Stretch","description":"Bodyweight exercise for the quadriceps.","instructions":["Sit in a prayer position with the soles of your feet gently pressed together.","Use your hands to slowly pull your feet inwards towards your groin. Hold for as long as required."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["butterfly stretch","schmetterlingsdehnung"],"media":[],"source":"wger","de":{"name":"Schmetterlingsdehnung","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite.","instructions":["Setze dich in eine betende Haltung, wobei die Fußsohlen sanft aneinandergedrückt sind.","Ziehe deine Füße mit den Händen langsam nach innen in Richtung deines Schritts. Halte so lange, wie nötig."]}},{"id":"ex-cable-chest-press","slug":"cable-chest-press","name":"Cable Chest Press","description":"Cable exercise for the chest, with shoulders, triceps assisting.","instructions":["Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.","Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.","After pausing at full extension, return to th starting position, keeping tension on the cables.","You can also execute this movement with your back off the pad, at an incline or decline, or alternate hands."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"CABLE","tags":["cable chest press"],"media":[{"id":"cable-chest-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Chest_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-chest-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Chest_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-cable-concentration-curl","slug":"cable-concentration-curl","name":"Cable Concentration Curl","description":"Cable exercise for the biceps.","instructions":["The concentration curl is a classic exercise for building the biceps one arm at a time. It can be performed bent over or kneeling, but is more often performed seated on a bench. It's great for emphasizing the biceps peak and is often used to finish a biceps workout"],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable concentration curl","konzentrationscurl am kabelzug"],"media":[{"id":"cable-concentration-curl-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1109/00b0a0bf-c14a-4f13-bb14-62c09030a1aa.png","caption":"Cable Concentration Curl","attribution":"wger.de · Franpol","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Konzentrationscurl am Kabelzug","description":"Übung (Kabelzug) für den Bizeps.","instructions":["Der Konzentrationscurl ist eine klassische Übung, um den Bizeps Arm für Arm aufzubauen. Er kann vorgebeugt oder kniend ausgeführt werden, wird aber häufiger sitzend auf einer Bank gemacht. Er eignet sich hervorragend, um den Bizepsgipfel zu betonen, und wird oft zum Abschluss eines Bizepstrainings eingesetzt."]}},{"id":"ex-cable-cross-over","slug":"cable-cross-over","name":"Cable Cross-over","description":"Cable exercise for the chest, with shoulders assisting.","instructions":["Begin with cables at about shoulder height, one in each hand. Take a step forward so that one foot is in front of the other, for stability, and so that there is tension on the cables. Bring hands together in front of you. Try to make your hands overlap (so that the cables cross) a few inches."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS"],"equipment":"CABLE","tags":["cable cross-over","kabelcross"],"media":[{"id":"cable-cross-over-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/71/Cable-crossover-2.png","caption":"Cable Cross-over","attribution":"wger.de · Everkinetic","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Kabelcross","description":"Übung (Kabelzug) für die Brust, unterstützt von Schultern.","instructions":null}},{"id":"ex-cable-deadlifts","slug":"cable-deadlifts","name":"Cable Deadlifts","description":"Cable exercise for the quadriceps, with forearms, glutes, hamstrings, back assisting.","instructions":["Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights.","To begin, squat down be flexing your hips and knees until you can reach the handles.","After grasping them, begin your ascent. Driving through your heels extend your hips and knees keeping your hands hanging at your side. Keep your head and chest up throughout the movement.","After reaching a full standing position, Return to the starting position and repeat."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["FOREARMS","GLUTES","HAMSTRINGS","BACK"],"equipment":"CABLE","tags":["cable deadlifts"],"media":[{"id":"cable-deadlifts-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Deadlifts/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-deadlifts-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Deadlifts/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Oberschenkelvorderseite, unterstützt von Unterarme, Po, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-cable-front-raise-with-a-small-bar","slug":"cable-front-raise-with-a-small-bar","name":"Cable Front Raise with a small bar","description":"Cable exercise for the shoulders.","instructions":["The Cable Front Raise with a small bar isolates your anterior deltoids (front shoulders) by providing constant tension, requiring you to stand facing away from a low pulley, grab the bar with an overhand grip, and lift it in front of you to shoulder height with slightly bent arms, avoiding swinging and keeping your core tight for controlled movement up and down. Use a light-to-moderate weight, focusing on slow, controlled reps to feel the muscle work, not momentum.","How to Perform the Cable Front Raise (Bar)","Setup: Attach a small straight bar to a low cable pulley. Set the weight to a light or moderate setting.","Starting Position: Stand with your back to the machine, holding the bar with an overhand grip (palms facing down) at hip level, arms extended but not locked. Feet shoulder-width apart, core braced, shoulders back and down.","The Lift: Exhale and slowly raise the bar straight up in front of you, keeping a slight bend in your elbows, until your hands reach shoulder height (or slightly below).","The Hold: Pause briefly at the top, squeezing your front delts.","The Lower: Inhale as you slowly and controllably lower the bar back to the starting position, maintaining tension."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable front raise with a small bar","frontheben am kabelzug mit kurzer stange"],"media":[{"id":"cable-front-raise-with-a-small-bar-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1745/9c92843a-6b90-428b-a868-9af4b11bad38.jpg","caption":"Cable Front Raise with a small bar","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Frontheben am Kabelzug mit kurzer Stange","description":"Übung (Kabelzug) für die Schultern.","instructions":["Das Frontheben am Kabelzug mit kurzer Stange isoliert deinen vorderen Deltamuskel (vordere Schulter) durch konstante Spannung. Dabei stehst du mit dem Rücken zu einem niedrigen Kabelzug, greifst die Stange im Obergriff und hebst sie mit leicht gebeugten Armen vor dir auf Schulterhöhe an, ohne zu schwingen, und hältst deinen Rumpf für eine kontrollierte Aufwärts- und Abwärtsbewegung angespannt. Verwende ein leichtes bis moderates Gewicht und konzentriere dich auf langsame, kontrollierte Wiederholungen, um den Muskel arbeiten zu spüren, nicht den Schwung.","So führst du das Frontheben am Kabelzug (Stange) aus","Aufbau: Befestige eine kurze gerade Stange an einem niedrigen Kabelzug. Stelle das Gewicht leicht bis moderat ein.","Ausgangsposition: Stelle dich mit dem Rücken zur Maschine und halte die Stange im Obergriff (Handflächen nach unten) auf Hüfthöhe, die Arme gestreckt, aber nicht durchgedrückt. Die Füße schulterbreit, der Rumpf angespannt, die Schultern nach hinten und unten.","Das Heben: Atme aus und hebe die Stange langsam gerade vor dir nach oben, wobei du eine leichte Beugung in den Ellbogen beibehältst, bis deine Hände Schulterhöhe (oder etwas darunter) erreichen.","Das Halten: Halte oben kurz inne und spanne deinen vorderen Deltamuskel an.","Das Absenken: Atme ein, während du die Stange langsam und kontrolliert in die Ausgangsposition zurückführst und dabei die Spannung beibehältst."]}},{"id":"ex-cable-glute-extension","slug":"cable-glute-extension","name":"Cable glute extension","description":"Cable exercise for the glutes.","instructions":["This exercise lets you work the upper, or larger, part of the glutes. For that reason, it should never be missing from your routine of isolated exercises for training the glutes.","Stand in front of a cable machine and locate the low pulley. Then attach the ankle strap to work on the low pulley. As for your posture, you should stay upright at all times. Pay special attention to your back to keep it straight and avoid injury.","It is advisable to hold on to the machine for better balance. With the leg that is holding the weight of the cable, perform a slow stretch backward without bending the knee."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable glute extension","gesäßstrecken am kabelzug"],"media":[{"id":"cable-glute-extension-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1131/3bcf3024-2dcc-4995-9694-55aa2c2e4a9a.png","caption":"Cable glute extension","attribution":"wger.de · Franpol","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Gesäßstrecken am Kabelzug","description":"Übung (Kabelzug) für den Po.","instructions":["Diese Übung ermöglicht es dir, den Bereich der oberen bzw. großen Gesäßmuskulatur zu trainieren. Deshalb darf sie in deiner Routine aus isolierten Übungen für die Gesäßmuskulatur nie fehlen.","Stelle dich vor eine Kabelzugmaschine und suche den unteren Haken. Befestige ihn dann an den Fußschlaufen, um am unteren Kabelzug zu arbeiten. Was die Haltung betrifft, musst du jederzeit aufrecht bleiben. Achte besonders auf deinen Rücken, um ihn gerade zu halten und dich nicht zu verletzen.","Es ist empfehlenswert, dich an der Maschine festzuhalten, um mehr Gleichgewicht zu haben. Führe mit dem Bein, das das Gewicht des Kabelzugs trägt, eine langsame Streckung nach hinten aus, ohne das Knie zu beugen."]}},{"id":"ex-cable-hammer-curls-rope-attachment","slug":"cable-hammer-curls-rope-attachment","name":"Cable Hammer Curls - Rope Attachment","description":"Cable exercise for the biceps.","instructions":["Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.","Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary.","Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position.","Using your biceps, pull your arms up as you exhale until your biceps touch your forearms. Tip: Remember to keep the elbows in and your upper arms stationary.","After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable hammer curls - rope attachment"],"media":[{"id":"cable-hammer-curls-rope-attachment-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Hammer_Curls_-_Rope_Attachment/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-hammer-curls-rope-attachment-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Hammer_Curls_-_Rope_Attachment/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Bizeps.","instructions":null}},{"id":"ex-cable-hip-adduction","slug":"cable-hip-adduction","name":"Cable Hip Adduction","description":"Cable exercise for the quadriceps.","instructions":["Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away.","Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley.","Now step out and away from the stack with a wide stance and grasp the bar of the pulley system.","Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley. This will be your starting position.","Now perform the movement by moving the leg with the ankle cuff in front of the far leg by using the inner thighs to abduct the hip. Breathe out during this portion of the movement.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions and then repeat the same movement with the opposite leg."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable hip adduction"],"media":[{"id":"cable-hip-adduction-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Hip_Adduction/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-hip-adduction-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Hip_Adduction/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-cable-incline-pushdown","slug":"cable-incline-pushdown","name":"Cable Incline Pushdown","description":"Cable exercise for the back.","instructions":["Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.","Grasp the straight bar attachment overhead with a pronated (overhand; palms down) shoulder width grip and extend your arms in front of you. The bar should be around 2 inches away from your upper thighs. This will be your starting position.","Keeping the upper arms stationary, lift your arms back in a semi circle until the bar is straight over your head. Breathe in during this portion of the movement.","Slowly go back to the starting position using your lats and hold the contraction once you reach the starting position. Breathe out during the execution of this movement.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable incline pushdown"],"media":[{"id":"cable-incline-pushdown-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Incline_Pushdown/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-incline-pushdown-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Incline_Pushdown/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rücken.","instructions":null}},{"id":"ex-cable-incline-triceps-extension","slug":"cable-incline-triceps-extension","name":"Cable Incline Triceps Extension","description":"Cable exercise for the triceps.","instructions":["Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.","Grasp the straight bar attachment overhead with a pronated (overhand; palms down) narrow grip (less than shoulder width) and keep your elbows tucked in to your sides. Your upper arms should create around a 25 degree angle when measured from the floor.","Keeping the upper arms stationary, extend the arms as you flex the triceps. Breathe out during this portion of the movement and hold the contraction for a second.","Slowly go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable incline triceps extension"],"media":[{"id":"cable-incline-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Incline_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-incline-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Incline_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Trizeps.","instructions":null}},{"id":"ex-cable-internal-rotation","slug":"cable-internal-rotation","name":"Cable Internal Rotation","description":"Cable exercise for the shoulders.","instructions":["Sit next to a low pulley sideways (with legs stretched in front of you or crossed) and grasp the single hand cable attachment with the arm nearest to the cable. Tip: If you can adjust the pulley's height, you can use a flat bench to sit on instead.","Position the elbow against your side with the elbow bent at 90° and the arm pointing towards the pulley. This will be your starting position.","Pull the single hand cable attachment toward your body by internally rotating your shoulder until your forearm is across your abs. You will be creating an imaginary semi-circle. Tip: The forearm should be perpendicular to your torso at all times.","Slowly go back to the initial position.","Repeat for the recommended amount of repetitions and then repeat the movement with the next arm."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable internal rotation"],"media":[{"id":"cable-internal-rotation-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Internal_Rotation/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-internal-rotation-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Internal_Rotation/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Schultern.","instructions":null}},{"id":"ex-cable-iron-cross","slug":"cable-iron-cross","name":"Cable Iron Cross","description":"Cable exercise for the chest.","instructions":["Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.","Stand directly between both pulleys with your arms extended out to your sides. Your head and chest should be up while your arms form a \"T\". This will be your starting position.","Keeping the elbows extended, pull your arms straight to your sides.","Return your arms back to the starting position after a pause at the peak contraction.","Continue the movement for the prescribed number of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable iron cross"],"media":[{"id":"cable-iron-cross-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Iron_Cross/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-iron-cross-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Iron_Cross/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Brust.","instructions":null}},{"id":"ex-cable-judo-flip","slug":"cable-judo-flip","name":"Cable Judo Flip","description":"Cable exercise for the core.","instructions":["Connect a rope attachment to a tower, and move the cable to the lowest pulley position. Stand with your side to the cable with a wide stance, and grab the rope with both hands.","Twist your body away from the pulley as you bring the rope over your shoulder like you're performing a judo flip.","Shift your weight between your feet as you twist and crunch forward, pulling the cable downward.","Return to the starting position and repeat until failure.","Then, reposition and repeat the same series of movements on the opposite side."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable judo flip"],"media":[{"id":"cable-judo-flip-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Judo_Flip/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-judo-flip-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Judo_Flip/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rumpf.","instructions":null}},{"id":"ex-cable-lying-triceps-extension","slug":"cable-lying-triceps-extension","name":"Cable Lying Triceps Extension","description":"Cable exercise for the triceps.","instructions":["Lie on a flat bench and grasp the straight bar attachment of a low pulley with a narrow overhand grip. Tip: The easiest way to do this is to have someone hand you the bar as you lay down.","With your arms extended, position the bar over your torso. Your arms and your torso should create a 90-degree angle. This will be your starting position.","Lower the bar by bending at the elbow while keeping the upper arms stationary and elbows in. Go down until the bar lightly touches your forehead. Breathe in as you perform this portion of the movement.","Flex the triceps as you lift the bar back to its starting position. Exhale as you perform this portion of the movement.","Hold for a second at the contracted position and repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable lying triceps extension"],"media":[{"id":"cable-lying-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Lying_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-lying-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Lying_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Trizeps.","instructions":null}},{"id":"ex-cable-one-arm-tricep-extension","slug":"cable-one-arm-tricep-extension","name":"Cable One Arm Tricep Extension","description":"Cable exercise for the triceps.","instructions":["With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack.","Now pull the handle down so that your upper arm and elbow are locked in to the side of your body. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you can have one leg in front of you and the other one back for better balance. This will be your starting position.","As you contract the triceps, move the single handle attachment down to your side until your arm is straight. Breathe out as you perform this movement. Tip: Only the forearms should move. Your upper arms should remain stationary at all times.","Squeeze the triceps and hold for a second in this contracted position.","Slowly return the handle to the starting position.","Repeat for the recommended amount of repetitions and then perform the same movement with the other arm."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable one arm tricep extension"],"media":[{"id":"cable-one-arm-tricep-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_One_Arm_Tricep_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-one-arm-tricep-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_One_Arm_Tricep_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Trizeps.","instructions":null}},{"id":"ex-cable-preacher-curl","slug":"cable-preacher-curl","name":"Cable Preacher Curl","description":"Cable exercise for the biceps, with forearms assisting.","instructions":["Place a preacher bench about 2 feet in front of a pulley machine.","Attach a straight bar to the low pulley.","Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley.","Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position.","Now start pilling the weight up towards your shoulders and squeeze the biceps hard at the top of the movement. Exhale as you perform this motion. Also, hold for a second at the top.","Now slowly lower the weight to the starting position.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"CABLE","tags":["cable preacher curl"],"media":[{"id":"cable-preacher-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Preacher_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-preacher-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Preacher_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Bizeps, unterstützt von Unterarme.","instructions":null}},{"id":"ex-cable-pull-through","slug":"cable-pull-through","name":"Cable pull through","description":"Cable exercise for the glutes, with hamstrings, calves, quadriceps assisting.","instructions":["The Cable Pull Through is a lower-body exercise that targets the glutes and hamstrings using a \"hip hinge\" motion. To perform it, attach a rope to the lowest pulley setting, face away from the machine with the rope between your legs, and step forward to create tension. Keeping your back flat and knees slightly soft, push your hips backward as if trying to close a door behind you until you feel a deep stretch in your hamstrings.","To finish the rep, explosively drive your hips forward to return to a standing position, squeezing your glutes hard at the top. It is vital to remember that this is not a squat; your knees should not bend deeply, and your arms should remain straight and relaxed, acting only as hooks for the rope. This movement provides constant tension on the glutes while placing less stress on the lower back than a traditional deadlift."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["HAMSTRINGS","CALVES","QUADRICEPS"],"equipment":"CABLE","tags":["cable pull through"],"media":[],"source":"wger","de":{"name":"Cable Pull Through","description":"Übung (Kabelzug) für den Po, unterstützt von Oberschenkelrückseite, Waden, Oberschenkelvorderseite.","instructions":["Der Cable Pull Through ist eine Übung für den Unterkörper, die mit einer „Hüftbeuge\"-Bewegung (Hip Hinge) die Gesäßmuskulatur und die hintere Oberschenkelmuskulatur beansprucht. Um sie auszuführen, befestige ein Seil an der niedrigsten Einstellung des Kabelzugs, wende dich von der Maschine ab, sodass das Seil zwischen deinen Beinen verläuft, und mache einen Schritt nach vorne, um Spannung aufzubauen. Halte deinen Rücken flach und deine Knie leicht gebeugt und schiebe deine Hüften nach hinten, als wolltest du eine Tür hinter dir schließen, bis du eine tiefe Dehnung in deiner hinteren Oberschenkelmuskulatur spürst.","Um die Wiederholung abzuschließen, schiebe deine Hüften explosiv nach vorne, um in die stehende Position zurückzukehren, und spanne dabei oben deine Gesäßmuskulatur kräftig an. Es ist wichtig, sich zu merken, dass dies keine Kniebeuge ist; deine Knie sollten sich nicht tief beugen, und deine Arme sollten gestreckt und entspannt bleiben und nur als Haken für das Seil dienen. Diese Bewegung sorgt für konstante Spannung auf der Gesäßmuskulatur und belastet dabei den unteren Rücken weniger als ein klassisches Kreuzheben."]}},{"id":"ex-cable-rear-delt-fly","slug":"cable-rear-delt-fly","name":"Cable Rear Delt Fly","description":"Cable exercise for the shoulders, with back, triceps assisting.","instructions":["The reverse cable fly, also known as the cable rear delt fly, is a deltoid muscle strengthening and definition exercise. It’s one of the best isolation exercises for your back and posterior deltoid.This workout targets your posterior (back) deltoids while using a range of upper body muscles.","Adjust the weight and the pulleys to the right height. You should be able to see the pulleys because they should be above your head.","With your right hand, grab the left pulley, and with your left hand, grab the right pulley, crossing them in front of you. This is where you’ll begin your journey.","Start the movement by moving your arms back and forth while keeping your arms straight.","Pause at the finish of the move for a brief moment before returning the handles to their starting positions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK","TRICEPS"],"equipment":"CABLE","tags":["cable rear delt fly","reverse butterfly am kabel"],"media":[{"id":"cable-rear-delt-fly-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/822/74affc0d-03b6-4f33-b5f4-a822a2615f68.png","caption":"Cable Rear Delt Fly","attribution":"wger.de · cshep442","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Reverse Butterfly am Kabel","description":"Übung (Kabelzug) für die Schultern, unterstützt von Rücken, Trizeps.","instructions":["Der Reverse Butterfly am Kabel, auch als Cable Rear Delt Fly bekannt, ist eine Übung zur Kräftigung und Definition des Deltamuskels. Sie ist eine der besten Isolationsübungen für deinen Rücken und den hinteren Deltamuskel. Dieses Training beansprucht deine hinteren Deltamuskeln und nutzt dabei eine Reihe von Oberkörpermuskeln.","Stelle das Gewicht und die Umlenkrollen auf die richtige Höhe ein. Du solltest die Rollen sehen können, denn sie sollten sich über deinem Kopf befinden.","Greife mit deiner rechten Hand die linke Rolle und mit deiner linken Hand die rechte Rolle, sodass sie sich vor dir kreuzen. Hier beginnt deine Reise.","Starte die Bewegung, indem du deine Arme vor- und zurückbewegst und dabei die Arme gestreckt hältst.","Halte am Ende der Bewegung einen kurzen Moment inne, bevor du die Griffe in ihre Ausgangsposition zurückführst."]}},{"id":"ex-cable-rear-delt-fly-single-arm","slug":"cable-rear-delt-fly-single-arm","name":"Cable Rear-Delt Fly (single arm)","description":"Cable exercise for the shoulders.","instructions":["Cable rear delt fly (single arm):","Stand sideways to a cable machine with the handle set around shoulder height. With a slight bend in the elbow, pull the handle out and back in a wide arc so the upper arm moves away from the body. Keep your torso still and focus on the rear delt doing the work. Use light to moderate weight and controlled reps."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable rear-delt fly (single arm)","reverse butterfly am kabel (einarmig)"],"media":[],"source":"wger","de":{"name":"Reverse Butterfly am Kabel (einarmig)","description":"Übung (Kabelzug) für die Schultern.","instructions":["Reverse Butterfly am Kabel (einarmig):","Stelle dich seitlich zu einem Kabelzug, mit dem Griff auf etwa Schulterhöhe. Mit einer leichten Beugung im Ellbogen ziehst du den Griff in einem weiten Bogen nach außen und hinten, sodass sich der Oberarm vom Körper wegbewegt. Halte deinen Oberkörper ruhig und konzentriere dich darauf, dass der hintere Deltamuskel die Arbeit verrichtet. Verwende leichtes bis mittleres Gewicht und kontrollierte Wiederholungen."]}},{"id":"ex-cable-reverse-crunch","slug":"cable-reverse-crunch","name":"Cable Reverse Crunch","description":"Cable exercise for the core.","instructions":["Connect an ankle strap attachment to a low pulley cable and position a mat on the floor in front of it.","Sit down with your feet toward the pulley and attach the cable to your ankles.","Lie down, elevate your legs and bend your knees at a 90-degree angle. Your legs and the cable should be aligned. If not, adjust the pulley up or down until they are.","With your hands behind your head, bring your knees inward to your torso and elevate your hips off the floor.","Pause for a moment and in a slow and controlled manner drop your hips and bring your legs back to the starting 90-degree angle. You should still have tension on your abs in the resting position.","Repeat the same movement to failure."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable reverse crunch"],"media":[{"id":"cable-reverse-crunch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Reverse_Crunch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-reverse-crunch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Reverse_Crunch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rumpf.","instructions":null}},{"id":"ex-cable-rope-rear-delt-rows","slug":"cable-rope-rear-delt-rows","name":"Cable Rope Rear-Delt Rows","description":"Cable exercise for the shoulders, with biceps, back assisting.","instructions":["Sit in the same position on a low pulley row station as you would if you were doing seated cable rows for the back.","Attach a rope to the pulley and grasp it with an overhand grip. Your arms should be extended and parallel to the floor with the elbows flared out.","Keep your lower back upright and slide your hips back so that your knees are slightly bent. This will be your starting position.","Pull the cable attachment towards your upper chest, just below the neck, as you keep your elbows up and out to the sides. Continue this motion as you exhale until the elbows travel slightly behind the back. Tip: Keep your upper arms horizontal, perpendicular to the torso and parallel to the floor throughout the motion.","Go back to the initial position where the arms are extended and the shoulders are stretched forward. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BICEPS","BACK"],"equipment":"CABLE","tags":["cable rope rear-delt rows"],"media":[{"id":"cable-rope-rear-delt-rows-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Rear-Delt_Rows/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-rope-rear-delt-rows-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Rear-Delt_Rows/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Schultern, unterstützt von Bizeps, Rücken.","instructions":null}},{"id":"ex-cable-russian-twists","slug":"cable-russian-twists","name":"Cable Russian Twists","description":"Cable exercise for the core.","instructions":["Connect a standard handle attachment, and position the cable to a middle pulley position.","Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable.","Grab the handle with both hands and fully extend your arms above your chest. You hands should be directly in-line with the pulley. If not, adjust the pulley up or down until they are.","Keep your hips elevated and abs engaged. Rotate your torso away from the pulley for a full-quarter rotation. Your body should be flat from head to knees.","Pause for a moment and in a slow and controlled manner reset to the starting position. You should still have side tension on the cable in the resting position.","Repeat the same movement to failure.","Then, reposition and repeat the same series of movements on the opposite side."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable russian twists"],"media":[{"id":"cable-russian-twists-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Russian_Twists/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-russian-twists-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Russian_Twists/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rumpf.","instructions":null}},{"id":"ex-cable-seated-crunch","slug":"cable-seated-crunch","name":"Cable Seated Crunch","description":"Cable exercise for the core.","instructions":["Seat on a flat bench with your back facing a high pulley.","Grasp the cable rope attachment with both hands (with the palms of the hands facing each other) and place your hands securely over both shoulders. Tip: Allow the weight to hyperextend the lower back slightly. This will be your starting position.","With the hips stationary, flex the waist so the elbows travel toward the hips. Breathe out as you perform this step.","As you inhale, go back to the initial position slowly.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable seated crunch"],"media":[{"id":"cable-seated-crunch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Crunch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-seated-crunch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Crunch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rumpf.","instructions":null}},{"id":"ex-cable-shoulder-press","slug":"cable-shoulder-press","name":"Cable Shoulder Press","description":"Cable exercise for the shoulders, with triceps assisting.","instructions":["Move the cables to the bottom of the towers and select an appropriate weight.","Stand directly in between the uprights. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.","Keeping your head and chest up, extend through the elbow to press the handles directly over head.","After pausing at the top, return to the starting position and repeat."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"CABLE","tags":["cable shoulder press"],"media":[{"id":"cable-shoulder-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Shoulder_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-shoulder-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Shoulder_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-cable-tri-extension-internal-rotation","slug":"cable-tri-extension-internal-rotation","name":"Cable Tri Extension - Internal Rotation","description":"Cable exercise for the triceps.","instructions":["single arm exercise with cable held at opposite shoulder with elbow bent. Turn towards the cable, and the straighten the elbow across the body."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable tri extension - internal rotation","trizepsstrecken am kabelzug mit innenrotation"],"media":[],"source":"wger","de":{"name":"Trizepsstrecken am Kabelzug mit Innenrotation","description":"Übung (Kabelzug) für den Trizeps.","instructions":["Einarmige Übung, bei der das Kabel mit gebeugtem Ellbogen an der gegenüberliegenden Schulter gehalten wird. Drehe dich zum Kabel hin und strecke dann den Ellbogen über den Körper hinweg."]}},{"id":"ex-cable-tricep-kickback","slug":"cable-tricep-kickback","name":"Cable Tricep Kickback","description":"Cable exercise for the triceps.","instructions":["Grab onto the handle, and pull your elbow up and back slightly above","your torso. Keep your upper arm to be parallel to the ground for the","duration of the set"],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable tricep kickback","trizeps-kickback am kabelzug"],"media":[],"source":"wger","de":{"name":"Trizeps-Kickback am Kabelzug","description":"Übung (Kabelzug) für den Trizeps.","instructions":["Greife den Griff und ziehe deinen Ellenbogen nach oben und leicht hinter deinen Oberkörper. Halte deinen Oberarm während des gesamten Satzes parallel zum Boden."]}},{"id":"ex-cable-triceps-press","slug":"cable-triceps-press","name":"Cable Triceps Press","description":"Cable exercise for the triceps.","instructions":["A single arm exercise that starts with the hand close to the chest with with the elbows bent, and the elbow flared out. Press forward and down against the cable straightening the elbow."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable triceps press","trizepsdrücken am kabelzug"],"media":[],"source":"wger","de":{"name":"Trizepsdrücken am Kabelzug","description":"Übung (Kabelzug) für den Trizeps.","instructions":["Eine einarmige Übung, die mit der Hand nah an der Brust und gebeugtem, nach außen abgespreiztem Ellbogen beginnt. Drücke nach vorne und unten gegen das Kabel und strecke dabei den Ellbogen."]}},{"id":"ex-cable-woodchoppers","slug":"cable-woodchoppers","name":"Cable Woodchoppers","description":"Cable exercise for the core.","instructions":["Set cable pulley slightly lower than chest height. Keep body facing forward with hips stable.  Grab the pulley handle, fully extend your arms and bring your arms forward and across your body. Hold for 1 second at the end of the movement and slowly return to starting position."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable woodchoppers","holzhacker am kabelzug"],"media":[],"source":"wger","de":{"name":"Holzhacker am Kabelzug","description":"Übung (Kabelzug) für den Rumpf.","instructions":["Stelle die Kabelrolle etwas niedriger als auf Brusthöhe ein. Halte den Körper nach vorne gerichtet und die Hüfte stabil. Greife den Griff der Rolle, strecke deine Arme vollständig und führe sie nach vorne und diagonal über deinen Körper. Halte am Ende der Bewegung 1 Sekunde lang inne und kehre langsam in die Ausgangsposition zurück."]}},{"id":"ex-cable-wrist-curl","slug":"cable-wrist-curl","name":"Cable Wrist Curl","description":"Cable exercise for the forearms.","instructions":["Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment.","Use your arms to grab the cable bar with a narrow to shoulder width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your thighs. Your wrists should be hanging just beyond your knees.","Start out by curling your wrist upwards and exhaling. Keep the contraction for a second.","Slowly lower your wrists back down to the starting position while inhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["cable wrist curl","handgelenk-curl am kabelzug"],"media":[{"id":"cable-wrist-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Wrist_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cable-wrist-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Wrist_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Handgelenk-Curl am Kabelzug","description":"Übung (Kabelzug) für die Unterarme.","instructions":["Strecke deinen Arm nach unten und hebe dann deinen Unterarm leicht an","Strecke dein Handgelenk in supinierter Haltung (Handfläche nach oben)","Stelle die Höhe des Kabelzugs so ein, dass der Griff in deiner supinierten Hand liegt","Führe die Bewegung aus, indem du","deine Handflächen und Handgelenke nach oben rollst","(optional/variabel) Halte oben kurz inne","Kehre langsam in die Ausgangsposition zurück"]}},{"id":"ex-calf-machine-shoulder-shrug","slug":"calf-machine-shoulder-shrug","name":"Calf-Machine Shoulder Shrug","description":"Machine exercise for the back.","instructions":["Position yourself on the calf machine so that the shoulder pads are above your shoulders. Your torso should be straight with the arms extended normally by your side. This will be your starting position.","Raise your shoulders up towards your ears as you exhale and hold the contraction for a full second.","Slowly return to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["calf-machine shoulder shrug"],"media":[{"id":"calf-machine-shoulder-shrug-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf-Machine_Shoulder_Shrug/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"calf-machine-shoulder-shrug-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf-Machine_Shoulder_Shrug/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für den Rücken.","instructions":null}},{"id":"ex-calf-press","slug":"calf-press","name":"Calf Press","description":"Machine exercise for the calves.","instructions":["Adjust the seat so that your legs are only slightly bent in the start position. The balls of your feet should be firmly on the platform.","Select an appropriate weight, and grasp the handles. This will be your starting position.","Straighten the legs by extending the knees, just barely lifting the weight from the stack. Your ankle should be fully flexed, toes pointing up. Execute the movement by pressing downward through the balls of your feet as far as possible.","After a brief pause, reverse the motion and repeat."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["calf press"],"media":[{"id":"calf-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"calf-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Waden.","instructions":null}},{"id":"ex-calf-press-on-the-leg-press-machine","slug":"calf-press-on-the-leg-press-machine","name":"Calf Press On The Leg Press Machine","description":"Machine exercise for the calves.","instructions":["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance.","Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torso and the legs should make perfect 90-degree angle. Now carefully place your toes and balls of your feet on the lower portion of the platform with the heels extending off. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.","Press on the platform by raising your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["calf press on the leg press machine"],"media":[{"id":"calf-press-on-the-leg-press-machine-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Press_On_The_Leg_Press_Machine/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"calf-press-on-the-leg-press-machine-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Press_On_The_Leg_Press_Machine/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Waden.","instructions":null}},{"id":"ex-calf-raise-on-a-dumbbell","slug":"calf-raise-on-a-dumbbell","name":"Calf Raise On A Dumbbell","description":"Dumbbell exercise for the calves.","instructions":["Hang on to a sturdy object for balance and stand on a dumbbell handle, preferably one with round plates so that it rolls as in this manner you have to work harder to stabilize yourself; thus increasing the effectiveness of the exercise.","Now roll your foot slightly forward so that you can get a nice stretch of the calf. This will be your starting position.","Lift the calf as you roll your foot over the top of the handle so that you get a full extension. Exhale during the execution of this movement. Contract the calf hard at the top and hold for a second. Tip: As you come up, roll the dumbbell slightly backward.","Now inhale as you roll the dumbbell slightly forward as you come down to get a better stretch.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["calf raise on a dumbbell"],"media":[{"id":"calf-raise-on-a-dumbbell-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Raise_On_A_Dumbbell/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"calf-raise-on-a-dumbbell-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Raise_On_A_Dumbbell/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Waden.","instructions":null}},{"id":"ex-calf-raises-with-bands","slug":"calf-raises-with-bands","name":"Calf Raises - With Bands","description":"Resistance band exercise for the calves.","instructions":["Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides.","While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a shoulder press. The palms should be facing forward with the elbows bent and to the sides. This movement will create tension on the band. This will be your starting position.","Keeping the hands by your shoulder, stand up on your toes as you exhale and contract the calves hard at the top of the movement.","After a one second contraction, slowly go back down to the starting position.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"BAND","tags":["calf raises - with bands"],"media":[{"id":"calf-raises-with-bands-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Raises_-_With_Bands/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"calf-raises-with-bands-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Raises_-_With_Bands/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Widerstandsband) für die Waden.","instructions":null}},{"id":"ex-calf-stretch-elbows-against-wall","slug":"calf-stretch-elbows-against-wall","name":"Calf Stretch Elbows Against Wall","description":"Equipment-free exercise for the calves.","instructions":["Stand facing a wall from a couple feet away.","Lean against the wall, placing your weight on your forearms.","Attempt to keep your heels on the ground. Hold for 10-20 seconds. You may move further or closer the wall, making it more or less difficult, respectively."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"NONE","tags":["calf stretch elbows against wall"],"media":[{"id":"calf-stretch-elbows-against-wall-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Stretch_Elbows_Against_Wall/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"calf-stretch-elbows-against-wall-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Stretch_Elbows_Against_Wall/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Waden.","instructions":null}},{"id":"ex-calf-stretch-hands-against-wall","slug":"calf-stretch-hands-against-wall","name":"Calf Stretch Hands Against Wall","description":"Equipment-free exercise for the calves.","instructions":["Stand facing a wall from several feet away. Stagger your stance, placing one foot forward.","Lean forward and rest your hands on the wall, keeping your heel, hip and head in a straight line.","Attempt to keep your heel on the ground. Hold for 10-20 seconds and then switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"NONE","tags":["calf stretch hands against wall"],"media":[{"id":"calf-stretch-hands-against-wall-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Stretch_Hands_Against_Wall/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"calf-stretch-hands-against-wall-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Stretch_Hands_Against_Wall/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Waden.","instructions":null}},{"id":"ex-calves-smr","slug":"calves-smr","name":"Calves-SMR","description":"Foam roller exercise for the calves.","instructions":["Begin seated on the floor. Place a foam roller underneath your lower leg. Your other leg can either be crossed over the opposite or be placed on the floor, supporting some of your weight. This will be your starting position.","Place your hands to your side or just behind you, and press down to raise your hips off of the floor, placing much of your weight against your calf muscle. Roll from below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat for the other leg."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"FOAM_ROLLER","tags":["calves-smr"],"media":[{"id":"calves-smr-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calves-SMR/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"calves-smr-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calves-SMR/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Faszienrolle) für die Waden.","instructions":null}},{"id":"ex-car-drivers","slug":"car-drivers","name":"Car Drivers","description":"Barbell exercise for the shoulders, with forearms assisting.","instructions":["While standing upright, hold a barbell plate in both hands at the 3 and 9 o'clock positions. Your palms should be facing each other and your arms should be extended straight out in front of you. This will be your starting position.","Initiate the movement by rotating the plate as far to one side as possible. Use the same type of movement you would use to turn a steering wheel to one side.","Reverse the motion, turning it all the way to the opposite side.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["FOREARMS"],"equipment":"BARBELL","tags":["car drivers"],"media":[{"id":"car-drivers-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Car_Drivers/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"car-drivers-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Car_Drivers/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Schultern, unterstützt von Unterarme.","instructions":null}},{"id":"ex-carioca-quick-step","slug":"carioca-quick-step","name":"Carioca Quick Step","description":"Equipment-free exercise for the quadriceps, with core, glutes, calves, hamstrings assisting.","instructions":["Begin with your feet a few inches apart and your left arm up in a relaxed, athletic position.","With your right foot, quick step behind and pull the knee up.","Fire your arms back up when you pull the right knee, being sure that your knee goes straight up and down. Avoid turning your feet as you move and continue to look forward as you move to the side."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["ABS_CORE","GLUTES","CALVES","HAMSTRINGS"],"equipment":"NONE","tags":["carioca quick step"],"media":[{"id":"carioca-quick-step-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Carioca_Quick_Step/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"carioca-quick-step-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Carioca_Quick_Step/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelvorderseite, unterstützt von Rumpf, Po, Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-cat-plank","slug":"cat-plank","name":"Cat Plank","description":"Bodyweight exercise for the quadriceps, with core, shoulders assisting.","instructions":["On your fours and raise the knees of the floor ever so slightly.","Curl your back out and push back from your shoulders as to resemble a cat making itself look large."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["ABS_CORE","SHOULDERS"],"equipment":"BODYWEIGHT","tags":["cat plank","katzen-plank"],"media":[],"source":"wger","de":{"name":"Katzen-Plank","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Rumpf, Schultern.","instructions":["Gehe in den Vierfüßlerstand und hebe die Knie nur ganz leicht vom Boden ab.","Runde deinen Rücken nach oben und drücke dich aus den Schultern zurück, so wie eine Katze, die sich groß macht."]}},{"id":"ex-catch-and-overhead-throw","slug":"catch-and-overhead-throw","name":"Catch and Overhead Throw","description":"Accessory exercise for the back, with core, chest, shoulders assisting.","instructions":["Begin standing while facing a wall or a partner.","Using both hands, position the ball behind your head, stretching as much as possible, and forcefully throw the ball forward.","Ensure that you follow your throw through, being prepared to receive your rebound from your throw. If you are throwing against the wall, make sure that you stand close enough to the wall to receive the rebound, and aim a little higher than you would with a partner."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["ABS_CORE","CHEST","SHOULDERS"],"equipment":"OTHER","tags":["catch and overhead throw"],"media":[{"id":"catch-and-overhead-throw-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Catch_and_Overhead_Throw/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"catch-and-overhead-throw-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Catch_and_Overhead_Throw/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Rumpf, Brust, Schultern.","instructions":null}},{"id":"ex-chain-handle-extension","slug":"chain-handle-extension","name":"Chain Handle Extension","description":"Accessory exercise for the triceps.","instructions":["You will need two cable handle attachments and a flat bench, as well as chains, for this exercise. Clip the middle of the chains to the handles, and position yourself on the flat bench. Your elbows should be pointing straight up.","Begin by extending through the elbow, keeping your upper arm still, with your wrists pronated.","Pause at the lockout, and reverse the motion to return to the starting position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["chain handle extension"],"media":[{"id":"chain-handle-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chain_Handle_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"chain-handle-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chain_Handle_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Trizeps.","instructions":null}},{"id":"ex-chain-press","slug":"chain-press","name":"Chain Press","description":"Accessory exercise for the chest, with shoulders, triceps assisting.","instructions":["Begin by connecting the chains to the cable handle attachments. Position yourself on the flat bench in the same position as for a dumbbell press. Your wrists should be pronated and arms perpendicular to the floor. This will be your starting position.","Lower the chains by flexing the elbows, unloading some of the chain onto the floor.","Continue until your elbow forms a 90 degree angle, and then reverse the motion by extending through the elbow to lockout."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"OTHER","tags":["chain press"],"media":[{"id":"chain-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chain_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"chain-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chain_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-chair-dips","slug":"chair-dips","name":"Chair dips","description":"Bodyweight exercise for the triceps, with shoulders, chest assisting.","instructions":["Starting position:","Sit down on the front edge of a chair, back straight, hands holding the front edge. Still holding the edge of the chair, arms extended, lift your butt and walk forward slightly so that it is a few inches from the chair.","Steps:","Slowly lower your body, keeping the back straight, until your arms are at a right angle.","Raise your body again to the initial position, arms extended.","Repeat."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["SHOULDERS","CHEST"],"equipment":"BODYWEIGHT","tags":["chair dips","dips am stuhl"],"media":[],"source":"wger","de":{"name":"Dips am Stuhl","description":"Übung (Körpergewicht) für den Trizeps, unterstützt von Schultern, Brust.","instructions":["Ausgangsposition:","Setze dich auf die vordere Kante eines Stuhls, der Rücken gerade, die Hände halten die vordere Kante. Hebe – während du dich weiterhin an der Stuhlkante festhältst und die Arme gestreckt sind – dein Gesäß an und gehe ein kleines Stück nach vorne, sodass es einige Zentimeter vom Stuhl entfernt ist.","Schritte:","Senke deinen Körper langsam ab, wobei du den Rücken gerade hältst, bis deine Arme einen rechten Winkel bilden.","Hebe deinen Körper wieder in die Ausgangsposition an, die Arme gestreckt.","Wiederhole."]}},{"id":"ex-chair-leg-extended-stretch","slug":"chair-leg-extended-stretch","name":"Chair Leg Extended Stretch","description":"Accessory exercise for the hamstrings, with quadriceps assisting.","instructions":["Sit upright in a chair and grip the seat on the sides.","Raise one leg, extending the knee, flexing the ankle as you do so.","Slowly move that leg outward as far as you can, and then back to the center and down.","Repeat for your other leg."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["QUADRICEPS"],"equipment":"OTHER","tags":["chair leg extended stretch"],"media":[{"id":"chair-leg-extended-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chair_Leg_Extended_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"chair-leg-extended-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chair_Leg_Extended_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelrückseite, unterstützt von Oberschenkelvorderseite.","instructions":null}},{"id":"ex-chair-lower-back-stretch","slug":"chair-lower-back-stretch","name":"Chair Lower Back Stretch","description":"Equipment-free exercise for the back.","instructions":["Sit upright on a chair.","Bend to one side with your arm over your head. You can hold onto the chair with your free hand.","Hold for 10 seconds, and repeat for your other side."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"NONE","tags":["chair lower back stretch"],"media":[{"id":"chair-lower-back-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chair_Lower_Back_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"chair-lower-back-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chair_Lower_Back_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Rücken.","instructions":null}},{"id":"ex-chair-squat","slug":"chair-squat","name":"Chair Squat","description":"Machine exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["To begin, first set the bar to a position that best matches your height. Once the bar is loaded, step under it and position it across the back of your shoulders.","Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs.","Move your feet forward about 18 inches in front of the bar. Position your legs using a shoulder width stance with the toes slightly pointed out. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position.","Slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper and lower leg breaks 90 degrees.","Begin to raise the bar as you exhale by pushing the floor with the heels of your feet, extending the knees and returning to the starting position.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"MACHINE","tags":["chair squat"],"media":[{"id":"chair-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chair_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"chair-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chair_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-chair-upper-body-stretch","slug":"chair-upper-body-stretch","name":"Chair Upper Body Stretch","description":"Accessory exercise for the shoulders, with biceps, chest assisting.","instructions":["Sit on the edge of a chair, gripping the back of it.","Straighten your arms, keeping your back straight, and pull your upper body forward so you feel a stretch. Hold for 20-30 seconds."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BICEPS","CHEST"],"equipment":"OTHER","tags":["chair upper body stretch"],"media":[{"id":"chair-upper-body-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chair_Upper_Body_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"chair-upper-body-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chair_Upper_Body_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Schultern, unterstützt von Bizeps, Brust.","instructions":null}},{"id":"ex-chest-press","slug":"chest-press","name":"Chest Press","description":"Bodyweight exercise for the chest.","instructions":["Adjust the seat height so that the grips are parallel to your chest.","Use your legs to push the foot forward pedal.","Bring the handles to the start position.","Keep your back in contact with the back pad, press outwards.","Press the handles away from your chest and exhale.","Allow the handles to come in gently until they reach your chest.","Allow the handles to return to your chest as you inhale."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["chest press","brustpresse"],"media":[{"id":"chest-press-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/129/b263c968-e067-4750-916a-d8758a7df23e.webp","caption":"Chest Press","attribution":"wger.de · roneydya","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Brustpresse","description":"Übung (Körpergewicht) für die Brust.","instructions":["Stelle die Sitzhöhe so ein, dass sich die Griffe auf Höhe deiner Brust befinden.","Drücke mit deinen Beinen das Fußpedal nach vorne.","Bringe die Griffe in die Ausgangsposition.","Halte deinen Rücken in Kontakt mit dem Polster und drücke nach außen.","Drücke die Griffe von deiner Brust weg und atme aus.","Lasse die Griffe sanft zurückkommen, bis sie deine Brust erreichen.","Lasse die Griffe zu deiner Brust zurückkehren, während du einatmest."]}},{"id":"ex-chest-push-from-3-point-stance","slug":"chest-push-from-3-point-stance","name":"Chest Push from 3 point stance","description":"Accessory exercise for the chest, with core, shoulders, triceps assisting.","instructions":["Begin in a three point stance, squatted down with your back flat and one hand on the ground. Place the medicine ball directly in front of you.","To begin, take your first step as you pull the ball to your chest, positioning both hands to prepare for the throw.","As you execute the second step, explosively release the ball forward as hard as possible."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["ABS_CORE","SHOULDERS","TRICEPS"],"equipment":"OTHER","tags":["chest push from 3 point stance"],"media":[{"id":"chest-push-from-3-point-stance-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_Push_from_3_point_stance/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"chest-push-from-3-point-stance-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_Push_from_3_point_stance/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Brust, unterstützt von Rumpf, Schultern, Trizeps.","instructions":null}},{"id":"ex-chest-push-multiple-response","slug":"chest-push-multiple-response","name":"Chest Push (multiple response)","description":"Accessory exercise for the chest, with core, shoulders, triceps assisting.","instructions":["Begin in a kneeling position facing a wall or utilize a partner. Hold the ball with both hands tight into the chest.","Execute the pass by exploding forward and outward with the hips while pushing the ball as hard as possible.","Follow through by falling forward, catching yourself with your hands.","Immediately return to an upright position. Repeat for the desired number of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["ABS_CORE","SHOULDERS","TRICEPS"],"equipment":"OTHER","tags":["chest push (multiple response)"],"media":[{"id":"chest-push-multiple-response-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_Push_multiple_response/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"chest-push-multiple-response-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_Push_multiple_response/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Brust, unterstützt von Rumpf, Schultern, Trizeps.","instructions":null}},{"id":"ex-chest-push-single-response","slug":"chest-push-single-response","name":"Chest Push (single response)","description":"Accessory exercise for the chest, with core, shoulders, triceps assisting.","instructions":["Begin in a kneeling position holding the medicine ball with both hands tightly into the chest.","Execute the pass by exploding forward and outward with the hips while pushing the ball as far as possible.","Follow through by falling forward, catching yourself with your hands."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["ABS_CORE","SHOULDERS","TRICEPS"],"equipment":"OTHER","tags":["chest push (single response)"],"media":[{"id":"chest-push-single-response-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_Push_single_response/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"chest-push-single-response-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_Push_single_response/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Brust, unterstützt von Rumpf, Schultern, Trizeps.","instructions":null}},{"id":"ex-chest-push-with-run-release","slug":"chest-push-with-run-release","name":"Chest Push with Run Release","description":"Accessory exercise for the chest, with core, shoulders, triceps assisting.","instructions":["Begin in an athletic stance with the knees bent, hips back, and back flat. Hold the medicine ball near your legs. This will be your starting position.","While taking your first step draw the medicine ball into your chest.","As you take the second step, explosively push the ball forward, immediately sprinting for 10 yards after the release. If you are really fast, you can catch your own pass!"],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["ABS_CORE","SHOULDERS","TRICEPS"],"equipment":"OTHER","tags":["chest push with run release"],"media":[{"id":"chest-push-with-run-release-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_Push_with_Run_Release/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"chest-push-with-run-release-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_Push_with_Run_Release/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Brust, unterstützt von Rumpf, Schultern, Trizeps.","instructions":null}},{"id":"ex-chest-stretch-on-stability-ball","slug":"chest-stretch-on-stability-ball","name":"Chest Stretch on Stability Ball","description":"Accessory exercise for the chest.","instructions":["Get on your hands and knees next to an exercise ball.","Place your elbows on top of the ball, keeping your arm out to your side. This will be your starting position.","Lower your torso towards the floor, keeping your elbow on top of the ball. Hold the stretch for 20-30 seconds, and repeat with the other arm."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["chest stretch on stability ball"],"media":[{"id":"chest-stretch-on-stability-ball-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_Stretch_on_Stability_Ball/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"chest-stretch-on-stability-ball-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_Stretch_on_Stability_Ball/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Brust.","instructions":null}},{"id":"ex-chest-supported-rear-delt-raise","slug":"chest-supported-rear-delt-raise","name":"Chest-Supported Rear Delt Raise","description":"Dumbbell exercise for the shoulders, with back assisting.","instructions":["\"The Y\"","Position: Set an incline bench to 30-45 degrees. Lie face-down with your chest supported, keeping your head neutral or looking slightly down to avoid neck strain.","Grip: Hold light dumbbells with a neutral or thumbs-up grip (thumb pointing to the ceiling).","Movement: With straight or slightly bent elbows, raise the dumbbells up and out in a \"Y\" shape. Focus on moving the shoulders and shoulder blades rather than just lifting the arms.","Top Position: Squeeze the shoulder blades together and reach high, ensuring the arms are angled to form a \"Y\".","Control: Lower the dumbbells slowly to the starting position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"DUMBBELL","tags":["chest-supported rear delt raise","reverse flys für die hintere schulter mit brustauflage"],"media":[],"source":"wger","de":{"name":"Reverse Flys für die hintere Schulter mit Brustauflage","description":"Übung (Kurzhantel) für die Schultern, unterstützt von Rücken.","instructions":["„Das Y“","Position: Stelle eine Schrägbank auf 30–45 Grad ein. Lege dich mit dem Gesicht nach unten und gestützter Brust hin und halte den Kopf neutral oder schaue leicht nach unten, um die Nackenmuskulatur zu schonen.","Griff: Halte leichte Kurzhanteln mit neutralem Griff oder mit dem Daumen nach oben (Daumen zeigt zur Decke).","Bewegung: Mit gestreckten oder leicht gebeugten Ellenbogen hebst du die Kurzhanteln nach oben und außen in eine „Y“-Form. Konzentriere dich darauf, die Schultern und Schulterblätter zu bewegen, statt nur die Arme anzuheben.","Obere Position: Ziehe die Schulterblätter zusammen und strecke dich weit nach oben, sodass die Arme ein „Y“ bilden.","Kontrolle: Senke die Kurzhanteln langsam in die Ausgangsposition zurück."]}},{"id":"ex-child-s-pose","slug":"child-s-pose","name":"Child's pose","description":"Bodyweight exercise for the back.","instructions":["Starting position:","Start on all fours, knees, toes, and hands touching the ground. Your two big toes should be touching.","Steps:","Move your knees so that they're about hip-width apart.","On an exhale, move your pelvis back to sit on your heels. Your hands should still be touching the ground.","Relax your upper body, lowering your forehead to the floor and letting your hands move forward naturally.","Stay in this pose.","Tips:"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["child's pose","kinderpose"],"media":[{"id":"child-s-pose-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1002/ddf91765-8045-4087-bece-de17f33332ce.png","caption":"Child's pose","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Kinderpose","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Ausgangsposition:","Beginnen Sie auf allen Vieren, wobei Knie, Zehen und Hände den Boden berühren. Ihre beiden großen Zehen sollten sich berühren.","Schritte:","Bewegen Sie Ihre Knie so, dass sie etwa hüftbreit auseinander sind.","Bewegen Sie beim Ausatmen Ihr Becken nach hinten, so dass Sie auf Ihren Fersen sitzen. Ihre Hände sollten noch den Boden berühren.","Entspannen Sie Ihren Oberkörper, indem Sie die Stirn auf den Boden senken und die Hände ganz natürlich nach vorne bewegen.","Bleiben Sie in dieser Haltung.","Tipps:"]}},{"id":"ex-chin-to-chest-stretch","slug":"chin-to-chest-stretch","name":"Chin To Chest Stretch","description":"Equipment-free exercise for the shoulders, with back assisting.","instructions":["Get into a seated position on the floor.","Place both hands at the rear of your head, fingers interlocked, thumbs pointing down and elbows pointing straight ahead. Slowly pull your head down to your chest. Hold for 20-30 seconds."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"NONE","tags":["chin to chest stretch"],"media":[{"id":"chin-to-chest-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chin_To_Chest_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"chin-to-chest-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chin_To_Chest_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Schultern, unterstützt von Rücken.","instructions":null}},{"id":"ex-chin-tuck","slug":"chin-tuck","name":"Chin tuck","description":"Bodyweight exercise for the back.","instructions":["Starting position:","Sit or stand with your back straight.","Steps:","Use fingers on your chin to slowly tuck your chin in, moving your head back to align it with your spine.","Hold for 5 seconds.","Go back to normal head position and repeat."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["chin tuck","schluckübungen"],"media":[],"source":"wger","de":{"name":"Schluckübungen","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Ausgangsposition:","Sitzen oder stehen Sie mit geradem Rücken.","Schritte:","Ziehen Sie mit den Fingern am Kinn langsam das Kinn nach innen und bewegen Sie den Kopf zurück, um ihn mit der Wirbelsäule in Einklang zu bringen.","Halten Sie die Position für 5 Sekunden.","Gehen Sie zurück in die normale Kopfposition und wiederholen Sie den Vorgang."]}},{"id":"ex-clamshell","slug":"clamshell","name":"Clamshell","description":"Bodyweight exercise for the glutes, with core assisting.","instructions":["Position","Side plank with the elbow and the forearm on the ground and the legs slightly bent.","Execution","Lift your upper knee while keeping your feet close together, like a “shell opening,” then slowly return to the starting position. Keep your core stable and your hips aligned."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["ABS_CORE"],"equipment":"BODYWEIGHT","tags":["clamshell","clamshell (muschel)"],"media":[],"source":"wger","de":{"name":"Clamshell (Muschel)","description":"Übung (Körpergewicht) für den Po, unterstützt von Rumpf.","instructions":["Position","Seitlicher Unterarmstütz, mit Ellenbogen und Unterarm auf dem Boden und leicht gebeugten Beinen.","Ausführung","Hebe dein oberes Knie an, während du deine Füße eng beieinander hältst, wie eine sich „öffnende Muschel“, und kehre dann langsam in die Ausgangsposition zurück. Halte deinen Rumpf stabil und deine Hüften ausgerichtet."]}},{"id":"ex-clamshell-to-reverse-clamshell","slug":"clamshell-to-reverse-clamshell","name":"Clamshell to Reverse Clamshell","description":"Bodyweight exercise for the glutes.","instructions":["Lie on your side with your hips and knees bent, keeping your legs stacked. Lift your top knee into a clamshell position and keep the leg elevated throughout the movement. From there, alternate between opening the knee upward and lifting the foot upward, moving through hip external and internal rotation.","Keep the movement slow and controlled. Do not let the top leg rest on the bottom leg between repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["clamshell to reverse clamshell","clamshell zu reverse clamshell"],"media":[],"source":"wger","de":{"name":"Clamshell zu Reverse Clamshell","description":"Übung (Körpergewicht) für den Po.","instructions":["Lege dich auf die Seite, Hüfte und Knie gebeugt, die Beine übereinander. Hebe dein oberes Knie in eine Clamshell-Position und halte das Bein während der gesamten Bewegung angehoben. Wechsle von dort aus zwischen dem Öffnen des Knies nach oben und dem Anheben des Fußes nach oben, indem du durch die Außen- und Innenrotation der Hüfte gehst.","Halte die Bewegung langsam und kontrolliert. Lass das obere Bein zwischen den Wiederholungen nicht auf dem unteren Bein ablegen."]}},{"id":"ex-clap-push-up","slug":"clap-push-up","name":"Clap Push-UP","description":"Bodyweight exercise for the chest, with shoulders, core, triceps assisting.","instructions":["The clap push-up is an explosive upper body movement that builds power and fast-twitch muscle strength. It adds a plyometric challenge to the traditional push-up by requiring the hands to leave the ground mid-rep.","Start in a strong push-up position with your hands slightly wider than shoulder-width and core engaged","Lower your body explosively and push off the ground with enough force to lift your hands.","Quickly clap your hands together at chest level before returning them to the floor.","Land with soft elbows to absorb the impact and immediately move into the next rep"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","ABS_CORE","TRICEPS"],"equipment":"BODYWEIGHT","tags":["clap push-up","liegestütz mit klatschen"],"media":[{"id":"clap-push-up-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1554/49207a62-8799-4b47-8c0b-7bde02926f3d.png","caption":"Clap Push-UP","attribution":"wger.de · Settebello","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Liegestütz mit Klatschen","description":"Übung (Körpergewicht) für die Brust, unterstützt von Schultern, Rumpf, Trizeps.","instructions":["Der Liegestütz mit Klatschen ist eine explosive Oberkörperbewegung, die Schnellkraft und die Stärke der schnellzuckenden Muskelfasern aufbaut. Er fügt dem klassischen Liegestütz eine plyometrische Komponente hinzu, da die Hände während der Wiederholung den Boden verlassen müssen.","Beginne in einer stabilen Liegestützposition mit den Händen etwas weiter als schulterbreit und angespanntem Rumpf","Senke deinen Körper explosiv ab und drücke dich so kraftvoll vom Boden ab, dass deine Hände abheben.","Klatsche schnell auf Brusthöhe in die Hände, bevor du sie wieder auf den Boden setzt.","Lande mit leicht gebeugten Ellbogen, um den Aufprall abzufedern, und gehe sofort in die nächste Wiederholung über"]}},{"id":"ex-clean","slug":"clean","name":"Clean","description":"Barbell exercise for the hamstrings, with calves, forearms, glutes, back, quadriceps, shoulders assisting.","instructions":["With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.","As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","FOREARMS","GLUTES","BACK","QUADRICEPS","SHOULDERS"],"equipment":"BARBELL","tags":["clean"],"media":[{"id":"clean-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"clean-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Waden, Unterarme, Po, Rücken, Oberschenkelvorderseite, Schultern.","instructions":null}},{"id":"ex-clean-and-jerk","slug":"clean-and-jerk","name":"Clean and Jerk","description":"Barbell exercise for the shoulders, with core, glutes, hamstrings, back, quadriceps, triceps assisting.","instructions":["With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.","As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.","The second phase is the jerk, which raises the weight overhead. Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.","Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.","At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be split, with one foot forward, and one foot back. Receive the bar with the arms locked out overhead. Return to a standing position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["ABS_CORE","GLUTES","HAMSTRINGS","BACK","QUADRICEPS","TRICEPS"],"equipment":"BARBELL","tags":["clean and jerk"],"media":[{"id":"clean-and-jerk-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_and_Jerk/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"clean-and-jerk-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_and_Jerk/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Schultern, unterstützt von Rumpf, Po, Oberschenkelrückseite, Rücken, Oberschenkelvorderseite, Trizeps.","instructions":null}},{"id":"ex-clean-and-press","slug":"clean-and-press","name":"Clean and Press","description":"Barbell exercise for the shoulders, with core, calves, glutes, hamstrings, back, quadriceps, triceps assisting.","instructions":["Assume a shoulder-width stance, with knees inside the arms. Now while keeping the back flat, bend at the knees and hips so that you can grab the bar with the arms fully extended and a pronated grip that is slightly wider than shoulder width. Point the elbows out to sides. The bar should be close to the shins. Position the shoulders over or slightly ahead of the bar. Establish a flat back posture. This will be your starting position.","Begin to pull the bar by extending the knees. Move your hips forward and raise the shoulders at the same rate while keeping the angle of the back constant; continue to lift the bar straight up while keeping it close to your body.","As the bar passes the knee, extend at the ankles, knees, and hips forcefully, similar to a jumping motion. As you do so, continue to guide the bar with your hands, shrugging your shoulders and using the momentum from your movement to pull the bar as high as possible. The bar should travel close to your body, and you should keep your elbows out.","At maximum elevation, your feet should clear the floor and you should start to pull yourself under the bar. The mechanics of this could change slightly, depending on the weight used. You should descend into a squatting position as you pull yourself under the bar.","As the bar hits terminal height, rotate your elbows around and under the bar. Rack the bar across the front of the shoulders while keeping the torso erect and flexing the hips and knees to absorb the weight of the bar.","Stand to full height, holding the bar in the clean position.","Without moving your feet, press the bar overhead as you exhale. Lower the bar under control ."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["ABS_CORE","CALVES","GLUTES","HAMSTRINGS","BACK","QUADRICEPS","TRICEPS"],"equipment":"BARBELL","tags":["clean and press","umsetzen und stoßen"],"media":[{"id":"clean-and-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_and_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"clean-and-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_and_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Umsetzen und Stoßen","description":"Übung (Langhantel) für die Schultern, unterstützt von Rumpf, Waden, Po, Oberschenkelrückseite, Rücken, Oberschenkelvorderseite, Trizeps.","instructions":["Der erste Zug: Hebe die Stange vom Boden bis auf Kniehöhe, indem du aus den Beinen arbeitest und den Winkel deines Rückens konstant hältst.","Die \"Power\"-Position: Sobald die Stange die Mitte der Oberschenkel erreicht, ziehe explosiv die Schultern hoch und strecke die Hüfte, um vertikalen Schwung zu erzeugen.","Das schnelle Umsetzen der Ellbogen: In der Fangphase drehst du die Ellbogen rasch unter die Stange, um ein \"Ablagebrett\" auf deinen vorderen Deltamuskeln zu schaffen.","Das senkrechte Drücken: Drücke die Stange in einer geraden Linie nach oben; dein Kopf sollte sich leicht nach vorne schieben, sobald die Stange deine Stirn passiert, um die volle Streckung zu erreichen."]}},{"id":"ex-clean-deadlift","slug":"clean-deadlift","name":"Clean Deadlift","description":"Barbell exercise for the hamstrings, with forearms, glutes, back, quadriceps assisting.","instructions":["Begin standing with a barbell close to your shins. Your feet should be directly under your hips with your feet turned out slightly. Grip the bar with a double overhand grip or hook grip, about shoulder width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your shoulders in front of the bar and your back as vertical as possible.","Begin by driving through the floor through the front of your heels. As the bar travels upward, maintain a constant back angle. Flare your knees out to the side to help keep them out of the bar's path.","After the bar crosses the knees, complete the lift by driving the hips into the bar until your hips and knees are extended."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["FOREARMS","GLUTES","BACK","QUADRICEPS"],"equipment":"BARBELL","tags":["clean deadlift"],"media":[{"id":"clean-deadlift-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_Deadlift/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"clean-deadlift-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_Deadlift/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Unterarme, Po, Rücken, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-clean-from-blocks","slug":"clean-from-blocks","name":"Clean from Blocks","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings, shoulders, back assisting.","instructions":["With a barbell on boxes or stands of the desired height, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight with the elbows pointed out.","As full extension is achieved, transition into the receiving position by aggressively shrugging and flexing the arms with the elbows up and out. Aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position. Return the weight to the boxes for the next rep."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","SHOULDERS","BACK"],"equipment":"BARBELL","tags":["clean from blocks"],"media":[{"id":"clean-from-blocks-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_from_Blocks/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"clean-from-blocks-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_from_Blocks/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Schultern, Rücken.","instructions":null}},{"id":"ex-clean-pull","slug":"clean-pull","name":"Clean Pull","description":"Barbell exercise for the quadriceps, with forearms, glutes, hamstrings, back assisting.","instructions":["With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight and elbows out. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. Full extension should be violent and abrupt, and ensure that you do not prolong the extension for longer than necessary."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["FOREARMS","GLUTES","HAMSTRINGS","BACK"],"equipment":"BARBELL","tags":["clean pull"],"media":[{"id":"clean-pull-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_Pull/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"clean-pull-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_Pull/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Unterarme, Po, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-clean-shrug","slug":"clean-shrug","name":"Clean Shrug","description":"Barbell exercise for the back, with forearms, shoulders assisting.","instructions":["Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.","Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a clean, avoid overloading to the point that the execution slows down."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["FOREARMS","SHOULDERS"],"equipment":"BARBELL","tags":["clean shrug"],"media":[{"id":"clean-shrug-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_Shrug/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"clean-shrug-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_Shrug/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Unterarme, Schultern.","instructions":null}},{"id":"ex-clock-push-up","slug":"clock-push-up","name":"Clock Push-Up","description":"Bodyweight exercise for the chest, with shoulders, triceps assisting.","instructions":["Move into a prone position on the floor, supporting your weight on your hands and toes.","Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.","Descend by flexing at the elbow, lowering your chest toward the ground.","At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible until you are air borne. Aim to \"jump\" 12-18 inches to one side.","As you accelerate up, move your outside foot away from your direction of travel. Leaving the ground, shift your body about 30 degrees for the next repetition.","Return to the starting position and repeat the exercise, working all the way around until you are back where you started."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BODYWEIGHT","tags":["clock push-up"],"media":[{"id":"clock-push-up-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clock_Push-Up/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"clock-push-up-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clock_Push-Up/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-clockwise-neck-circles","slug":"clockwise-neck-circles","name":"Clockwise neck circles","description":"Bodyweight exercise for the back.","instructions":["Starting position:","Start sitting or standing. Drop your head down, bringing your chin toward your chest, but not pushing.","Steps:","In a slower fluid motion and with your head relaxed and not pushing in any direction:","lean toward your right shoulder.","then bring your head back, facing up.","then lean toward your left shoulder.4.and back toward the starting position.","Keep repeating this as part of one slower fluid motion."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["clockwise neck circles","halskreise im uhrzeigersinn"],"media":[],"source":"wger","de":{"name":"Halskreise im Uhrzeigersinn","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Ausgangsposition:","Beginnen Sie im Sitzen oder Stehen. Senken Sie den Kopf nach unten und bringen Sie das Kinn zur Brust, aber drücken Sie nicht.","Schritte:","Führen Sie die Übung in einer langsamen, fließenden Bewegung aus, wobei Ihr Kopf entspannt ist und in keine Richtung drückt:","Lehnen Sie sich zu Ihrer rechten Schulter.","Legen Sie dann den Kopf zurück und schauen Sie nach oben.","dann lehnen Sie sich zur linken Schulter","und zurück in die Ausgangsposition."]}},{"id":"ex-close-grip-dumbbell-press","slug":"close-grip-dumbbell-press","name":"Close-Grip Dumbbell Press","description":"Dumbbell exercise for the triceps, with chest, shoulders assisting.","instructions":["Place a dumbbell standing up on a flat bench.","Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench with only your shoulders lying on the surface. Hips should be below the bench and your legs bent with your feet firmly on the floor.","Grasp the dumbbell with both hands and hold it straight over your chest at arm's length. Both palms should be pressing against the underside of the sides of the dumbbell. This will be your starting position.","Initiate the movement by lowering the dumbbell to your chest.","Return to the starting position by extending the elbows."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"DUMBBELL","tags":["close-grip dumbbell press"],"media":[{"id":"close-grip-dumbbell-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Dumbbell_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"close-grip-dumbbell-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Dumbbell_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-close-grip-ez-bar-curl","slug":"close-grip-ez-bar-curl","name":"Close-Grip EZ Bar Curl","description":"Barbell exercise for the biceps, with forearms assisting.","instructions":["Stand up with your torso upright while holding an E-Z Curl Bar at the closer inner handle. The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar. The elbows should be close to the torso. This will be your starting position.","While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"BARBELL","tags":["close-grip ez bar curl"],"media":[{"id":"close-grip-ez-bar-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_EZ_Bar_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"close-grip-ez-bar-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_EZ_Bar_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Bizeps, unterstützt von Unterarme.","instructions":null}},{"id":"ex-close-grip-ez-bar-curl-with-band","slug":"close-grip-ez-bar-curl-with-band","name":"Close-Grip EZ-Bar Curl with Band","description":"EZ-bar exercise for the biceps, with forearms assisting.","instructions":["Attach a band to each end of the bar. Take the bar, placing a foot on the middle of the band. Stand upright with a narrow, supinated grip on the EZ bar. The elbows should be close to the torso. This will be your starting position.","While keeping the upper arms in place, flex the elbows to execute the curl. Exhale as the weight is lifted.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"EZ_BAR","tags":["close-grip ez-bar curl with band"],"media":[{"id":"close-grip-ez-bar-curl-with-band-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_EZ-Bar_Curl_with_Band/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"close-grip-ez-bar-curl-with-band-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_EZ-Bar_Curl_with_Band/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (SZ-Stange) für den Bizeps, unterstützt von Unterarme.","instructions":null}},{"id":"ex-close-grip-ez-bar-press","slug":"close-grip-ez-bar-press","name":"Close-Grip EZ-Bar Press","description":"EZ-bar exercise for the triceps, with chest, shoulders assisting.","instructions":["Lie on a flat bench with an EZ bar loaded to an appropriate weight.","Using a narrow grip lift the bar and hold it straight over your torso with your elbows in. The arms should be perpendicular to the floor. This will be your starting position.","Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.","Using the triceps to push the bar back up, press it back to the starting position by extending the elbows as you exhale.","Repeat."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"EZ_BAR","tags":["close-grip ez-bar press"],"media":[{"id":"close-grip-ez-bar-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_EZ-Bar_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"close-grip-ez-bar-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_EZ-Bar_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (SZ-Stange) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-close-grip-lat-pull-down","slug":"close-grip-lat-pull-down","name":"Close-grip Lat Pull Down","description":"Bodyweight exercise for the back.","instructions":["Grip the pull-down bar with your hands closer than shoulder width apart, with your palms facing away from you. Lean back slightly. Pull the bar down towards your chest, keeping your elbows close to your sides as you come down. Pull your shoulders back at the end of the motion."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["close-grip lat pull down","latzug eng"],"media":[{"id":"close-grip-lat-pull-down-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/158/0d51a0f2-622f-434b-beb8-1a003c54712a.png","caption":"Close-grip Lat Pull Down","attribution":"wger.de · Franpol","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Latzug Eng","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Körper leicht nach hinten geneigt","kein Hohlkreuz","Rumpfmuskulatur angespannt","schulterbreiter Untergriff","Stange vor dem Kopf auf Brust herunterziehen","Ellenbogen möglichst eng am Körper","Stange soweit zurück, dass Ellenbogen leicht gebeugt"]}},{"id":"ex-close-grip-push-up-off-of-a-dumbbell","slug":"close-grip-push-up-off-of-a-dumbbell","name":"Close-Grip Push-Up off of a Dumbbell","description":"Bodyweight exercise for the triceps, with core, chest, shoulders assisting.","instructions":["Lie on the floor and place your hands on an upright dumbbell. Supporting your weight on your toes and hands, keep your torso rigid and your elbows in with your arms straight. This will be your starting position.","Lower your body, allowing the elbows to flex while you inhale. Keep your body straight, not allowing your hips to rise or sag.","Press yourself back up to the starting position by extending the elbows. Breathe out as you perform this step.","After a pause at the contracted position, repeat the movement for the prescribed amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["ABS_CORE","CHEST","SHOULDERS"],"equipment":"BODYWEIGHT","tags":["close-grip push-up off of a dumbbell"],"media":[{"id":"close-grip-push-up-off-of-a-dumbbell-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Push-Up_off_of_a_Dumbbell/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"close-grip-push-up-off-of-a-dumbbell-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Push-Up_off_of_a_Dumbbell/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Trizeps, unterstützt von Rumpf, Brust, Schultern.","instructions":null}},{"id":"ex-close-grip-standing-barbell-curl","slug":"close-grip-standing-barbell-curl","name":"Close-Grip Standing Barbell Curl","description":"Barbell exercise for the biceps, with forearms assisting.","instructions":["Hold a barbell with both hands, palms up and a few inches apart.","Stand with your torso straight and your head up. Your feet should be about shoulder width and your elbows close to your torso. This will be your starting position. Tip: You will keep your upper arms and elbows stationary throughout the movement.","Curl the bar up in a semicircular motion until the forearms touch your biceps. Exhale as you perform this portion of the movement and contract your biceps hard for a second at the top. Tip: Avoid bending the back or using swinging motions as you lift the weight. Only the forearms should move.","Slowly go back down to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"BARBELL","tags":["close-grip standing barbell curl"],"media":[{"id":"close-grip-standing-barbell-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Standing_Barbell_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"close-grip-standing-barbell-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Standing_Barbell_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Bizeps, unterstützt von Unterarme.","instructions":null}},{"id":"ex-cobra-stretch","slug":"cobra-stretch","name":"Cobra Stretch","description":"Bodyweight exercise for the core, with chest assisting.","instructions":["The Cobra Stretch is a back extension exercise that helps improve spinal flexibility and relieve lower back tension. To perform, lie face down on the floor with your hands placed under your shoulders. Press your palms into the floor and lift your chest while keeping your hips on the ground. Keep your elbows slightly bent and your shoulders relaxed. Hold the stretch for a few seconds, then slowly lower yourself back down. This exercise is beneficial for improving posture and reducing lower back stiffness."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["CHEST"],"equipment":"BODYWEIGHT","tags":["cobra stretch","kobra-dehnung"],"media":[],"source":"wger","de":{"name":"Kobra-Dehnung","description":"Übung (Körpergewicht) für den Rumpf, unterstützt von Brust.","instructions":["Die Kobra-Dehnung ist eine Rückenstreckungsübung, die hilft, die Flexibilität der Wirbelsäule zu verbessern und Verspannungen im unteren Rücken zu lösen. Lege dich dazu mit dem Gesicht nach unten auf den Boden und platziere deine Hände unter den Schultern. Drücke die Handflächen in den Boden und hebe die Brust an, während du die Hüften am Boden lässt. Halte die Ellbogen leicht gebeugt und die Schultern entspannt. Halte die Dehnung für ein paar Sekunden und senke dich dann langsam wieder ab. Diese Übung ist hilfreich, um die Haltung zu verbessern und Steifheit im unteren Rücken zu verringern."]}},{"id":"ex-cocoons","slug":"cocoons","name":"Cocoons","description":"Bodyweight exercise for the core.","instructions":["Begin by lying on your back on the ground. Your legs should be straight and your arms extended behind your head. This will be your starting position.","To perform the movement, tuck the knees toward your chest, rotating your pelvis to lift your glutes from the floor. As you do so, flex the spine, bringing your arms back over your head to perform a simultaneous crunch motion.","After a brief pause, return to the starting position."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["cocoons"],"media":[{"id":"cocoons-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cocoons/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cocoons-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cocoons/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-commando-pull-ups","slug":"commando-pull-ups","name":"commando pull-ups","description":"Bodyweight exercise for the shoulders, with biceps, back assisting.","instructions":["variation of the pull-up exercise, it is performed with a grip of one hand supine and one hand prone, do not twist the torso to get back to the front, the head passes once to one side, once to the other."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BICEPS","BACK"],"equipment":"BODYWEIGHT","tags":["commando pull-ups"],"media":[],"source":"wger","de":{"name":"Commando Pull-ups","description":"Übung (Körpergewicht) für die Schultern, unterstützt von Bizeps, Rücken.","instructions":["Eine Variante des Klimmzugs, die mit einem Griff ausgeführt wird, bei dem eine Hand im Untergriff und eine Hand im Obergriff liegt. Verdrehe den Oberkörper nicht, um wieder nach vorne zu gelangen; der Kopf geht einmal auf die eine Seite, einmal auf die andere."]}},{"id":"ex-concentration-curls","slug":"concentration-curls","name":"Concentration Curls","description":"Dumbbell exercise for the biceps, with forearms assisting.","instructions":["Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.","Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.","While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.","Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"DUMBBELL","tags":["concentration curls"],"media":[{"id":"concentration-curls-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Concentration_Curls/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"concentration-curls-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Concentration_Curls/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps, unterstützt von Unterarme.","instructions":null}},{"id":"ex-copenhagen-adduction-exercise","slug":"copenhagen-adduction-exercise","name":"Copenhagen Adduction Exercise","description":"Bodyweight exercise for the glutes, with quadriceps, core, chest, back assisting.","instructions":["Lie on your side with the elbow placed directly under the shoulder, similar to a side plank position. Place the upper leg on a bench with the inside of the foot or ankle resting on it. Lift your hips and hold your body in a straight line while keeping the lower leg off the floor. The exercise strongly activates the adductors of the upper leg while also challenging the core and hip stabilizers."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["QUADRICEPS","ABS_CORE","CHEST","BACK"],"equipment":"BODYWEIGHT","tags":["copenhagen adduction exercise","copenhagen-adduktion"],"media":[],"source":"wger","de":{"name":"Copenhagen-Adduktion","description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelvorderseite, Rumpf, Brust, Rücken.","instructions":["Lege dich auf die Seite, mit dem Ellbogen direkt unter der Schulter, ähnlich wie bei einem seitlichen Unterarmstütz. Lege das obere Bein auf eine Bank, sodass die Innenseite des Fußes oder Knöchels darauf ruht. Hebe deine Hüften und halte deinen Körper in einer geraden Linie, während du das untere Bein vom Boden abhebst. Die Übung aktiviert die Adduktoren des oberen Beins stark und fordert gleichzeitig den Rumpf und die Hüftstabilisatoren."]}},{"id":"ex-core-rotation","slug":"core-rotation","name":"Core Rotation","description":"Bodyweight exercise for the quadriceps, with core, chest assisting.","instructions":["Sit back, raise feet above the ground with knees bent and start rotating left and right with hands touching the ground every move."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["ABS_CORE","CHEST"],"equipment":"BODYWEIGHT","tags":["core rotation","rumpfrotation"],"media":[],"source":"wger","de":{"name":"Rumpfrotation","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Rumpf, Brust.","instructions":["Setze dich zurück, hebe die Füße mit gebeugten Knien vom Boden ab und beginne, dich nach links und rechts zu drehen, wobei du bei jeder Bewegung mit den Händen den Boden berührst."]}},{"id":"ex-cossack-squat","slug":"cossack-squat","name":"Cossack squat","description":"Bodyweight exercise for the glutes, with quadriceps, calves, core assisting.","instructions":["The Cossack Squat is a multi-joint exercise that works mainly on the legs and buttocks, but also involves stabilizing muscles. It is an excellent exercise for improving strength, mobility and stability in a functional way."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["QUADRICEPS","CALVES","ABS_CORE"],"equipment":"BODYWEIGHT","tags":["cossack squat","kosaken-kniebeuge"],"media":[],"source":"wger","de":{"name":"Kosaken-Kniebeuge","description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelvorderseite, Waden, Rumpf.","instructions":["Die Kosaken-Kniebeuge ist eine mehrgelenkige Übung, die hauptsächlich die Beine und das Gesäß beansprucht, aber auch die stabilisierende Muskulatur einbezieht. Sie ist eine hervorragende Übung, um Kraft, Mobilität und Stabilität auf funktionelle Weise zu verbessern."]}},{"id":"ex-counterclockwise-neck-circles","slug":"counterclockwise-neck-circles","name":"Counterclockwise neck circles","description":"Bodyweight exercise for the back.","instructions":["Starting position:","Start sitting or standing. Drop your head down, bringing your chin toward your chest, but not pushing.","Steps:","In a slower fluid motion and with your head relaxed and not pushing in any direction:","lean toward your left shoulder.","then bring your head back, facing up.","then lean toward your right shoulder.4.and back toward the starting position.","Keep repeating this as part of one slower fluid motion."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["counterclockwise neck circles","nackenkreise gegen den uhrzeigersinn"],"media":[],"source":"wger","de":{"name":"Nackenkreise gegen den Uhrzeigersinn","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Ausgangsposition:","Beginnen Sie im Sitzen oder Stehen. Senken Sie den Kopf nach unten und bringen Sie das Kinn zur Brust, aber drücken Sie nicht.","Schritte:","Führen Sie die Übung in einer langsamen, fließenden Bewegung aus, wobei Ihr Kopf entspannt ist und in keine Richtung drückt:","Lehnen Sie sich zu Ihrer linken Schulter.","Legen Sie dann den Kopf zurück und schauen Sie nach oben.","dann lehnen Sie sich zur rechten Schulter","und zurück in die Ausgangsposition."]}},{"id":"ex-cross-bench-dumbbell-pullovers","slug":"cross-bench-dumbbell-pullovers","name":"Cross-Bench Dumbbell Pullovers","description":"Dumbbell exercise for the back, with chest assisting.","instructions":["Grasp a moderately weighted dumbbell so your palms are flat against the underside of the top plates and your thumbs are around the bar. Lie on your back across a flat bench so only your upper back and shoulders are in contact with the bench. Your feet should be set about shoulder-width apart and your head should hang slightly downward. With the dumbbell supported at arm's length directly about your chest, bend your arms about 15 degrees and keep them bent throughout the movement. Slowly lower the dumbbell backward and downward in a semicircle arc to as low a position as is comfortably possible. Raise it slowly back along the same arc to the starting point, and repeat for the required number of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["CHEST"],"equipment":"DUMBBELL","tags":["cross-bench dumbbell pullovers","pull-over"],"media":[{"id":"cross-bench-dumbbell-pullovers-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/161/b9b1803e-2817-40bf-8ac7-e398ca86d8b4.png","caption":"Cross-Bench Dumbbell Pullovers","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Pull-Over","description":"Übung (Kurzhantel) für den Rücken, unterstützt von Brust.","instructions":["Sie Liegen auf einer Bank, die Füße stehen am Boden, die Arme sind nach oben gesteckt.","Beide Hände halten eine Kurzhantel so, dass die Scheibe auf den Handflächen liegt, Daumen und Zeigefinger umschließen den Griff der Hantel","beim Einatmen die Hantel hinter den Kopf sinken lassen und dabei leicht die Ellbogen beugen","beim Zurückkehren in die Ausgangsposition ausatmen"]}},{"id":"ex-cross-body-hammer-curl","slug":"cross-body-hammer-curl","name":"Cross Body Hammer Curl","description":"Dumbbell exercise for the biceps, with forearms assisting.","instructions":["Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in.","While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second.","Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm.","Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"DUMBBELL","tags":["cross body hammer curl"],"media":[{"id":"cross-body-hammer-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cross_Body_Hammer_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cross-body-hammer-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cross_Body_Hammer_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps, unterstützt von Unterarme.","instructions":null}},{"id":"ex-cross-over-with-bands","slug":"cross-over-with-bands","name":"Cross Over - With Bands","description":"Resistance band exercise for the chest, with biceps, shoulders assisting.","instructions":["Secure an exercise band around a stationary post.","While facing away from the post, grab the handles on both ends of the band and step forward enough to create tension on the band.","Raise your arms to the sides, parallel to the floor, perpendicular to your torso (your torso and the arms should resemble the letter \"T\") and with the palms facing forward. Have them extended with a slight bend at the elbows. This will be your starting position.","While keeping your arms straight, bring them across your chest in a semicircular motion to the front as you exhale and flex your pecs. Hold the contraction for a second.","Slowly return to the starting position as you inhale.","Perform for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["BICEPS","SHOULDERS"],"equipment":"BAND","tags":["cross over - with bands"],"media":[{"id":"cross-over-with-bands-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cross_Over_-_With_Bands/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cross-over-with-bands-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cross_Over_-_With_Bands/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Widerstandsband) für die Brust, unterstützt von Bizeps, Schultern.","instructions":null}},{"id":"ex-crossbody-hamstring-stretch","slug":"crossbody-hamstring-stretch","name":"Crossbody Hamstring Stretch","description":"Bodyweight exercise for the hamstrings.","instructions":["While standing, cross one leg behind the other (keep this leg straight). Reach downward and try to touch the toes of that leg. Slightly bend the other leg so that you can bend down."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["crossbody hamstring stretch","dehnung der hinteren oberschenkelmuskulatur über kreuz"],"media":[],"source":"wger","de":{"name":"Dehnung der hinteren Oberschenkelmuskulatur über Kreuz","description":"Übung (Körpergewicht) für die Oberschenkelrückseite.","instructions":["Kreuze im Stand ein Bein hinter dem anderen (halte dieses Bein gestreckt). Greife nach unten und versuche, die Zehen dieses Beins zu berühren. Beuge das andere Bein leicht, damit du dich nach unten beugen kannst."]}},{"id":"ex-crossbody-leg-swings","slug":"crossbody-leg-swings","name":"Crossbody Leg Swings","description":"Bodyweight exercise for the hamstrings.","instructions":["Hold onto a wall or something near you for support. Swing one leg across the front of your body, then back and out to the side. Repeat while slowly increasing your range of motion."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["crossbody leg swings","beinschwingen über kreuz"],"media":[],"source":"wger","de":{"name":"Beinschwingen über Kreuz","description":"Übung (Körpergewicht) für die Oberschenkelrückseite.","instructions":["Halte dich an einer Wand oder etwas in deiner Nähe fest, um dich abzustützen. Schwinge ein Bein vor deinem Körper über Kreuz, dann zurück und zur Seite hinaus. Wiederhole die Bewegung und vergrößere dabei langsam deinen Bewegungsumfang."]}},{"id":"ex-crossover-reverse-lunge","slug":"crossover-reverse-lunge","name":"Crossover Reverse Lunge","description":"Equipment-free exercise for the back, with core, glutes, hamstrings, quadriceps assisting.","instructions":["Stand with your feet shoulder width apart. This will be your starting position.","Perform a rear lunge by stepping back with one foot and flexing the hips and front knee. As you do so, rotate your torso across the front leg.","After a brief pause, return to the starting position and repeat on the other side, continuing in an alternating fashion."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["ABS_CORE","GLUTES","HAMSTRINGS","QUADRICEPS"],"equipment":"NONE","tags":["crossover reverse lunge"],"media":[{"id":"crossover-reverse-lunge-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crossover_Reverse_Lunge/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"crossover-reverse-lunge-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crossover_Reverse_Lunge/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Rücken, unterstützt von Rumpf, Po, Oberschenkelrückseite, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-crunch-hands-overhead","slug":"crunch-hands-overhead","name":"Crunch - Hands Overhead","description":"Bodyweight exercise for the core.","instructions":["Lie on the floor with your back flat and knees bent with around a 60-degree angle between the hamstrings and the calves.","Keep your feet flat on the floor and stretch your arms overhead with your palms crossed. This will be your starting position.","Curl your upper body forward and bring your shoulder blades just off the floor. At all times, keep your arms aligned with your head, neck and shoulder. Don't move them forward from that position. Exhale as you perform this portion of the movement and hold the contraction for a second.","Slowly lower down to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["crunch - hands overhead"],"media":[{"id":"crunch-hands-overhead-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunch_-_Hands_Overhead/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"crunch-hands-overhead-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunch_-_Hands_Overhead/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-crunch-legs-on-exercise-ball","slug":"crunch-legs-on-exercise-ball","name":"Crunch - Legs On Exercise Ball","description":"Bodyweight exercise for the core.","instructions":["Lie flat on your back with your feet resting on an exercise ball and your knees bent at a 90 degree angle.","Place your feet three to four inches apart and point your toes inward so they touch.","Place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head.","Push the small of your back down in the floor in order to better isolate your abdominal muscles. This will be your starting position.","Begin to roll your shoulders off the floor and continue to push down as hard as you can with your lower back. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. Breathe out as you execute this portion of the movement. Squeeze your abdominals hard at the top of the contraction and hold for a second. Tip: Focus on a slow, controlled movement. Refrain from using momentum at any time.","Slowly go back down to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["crunch - legs on exercise ball"],"media":[{"id":"crunch-legs-on-exercise-ball-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunch_-_Legs_On_Exercise_Ball/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"crunch-legs-on-exercise-ball-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunch_-_Legs_On_Exercise_Ball/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-crunches-on-machine","slug":"crunches-on-machine","name":"Crunches on Machine","description":"Machine exercise for the core.","instructions":["The procedure is very similar as for regular crunches, only with the additional weight of the machine. Sit on the machine, put both feet firmly on the ground. Grab the to the weights, cables, etc. and do a rolling motion forwards (the spine should ideally lose touch vertebra by vertebra). Slowly return to the starting position."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["crunches on machine","crunches an maschine"],"media":[],"source":"wger","de":{"name":"Crunches an Maschine","description":"Übung (Maschine) für den Rumpf.","instructions":["Ablauf wie bei reguläre Crunches, nur mit zusätzlichem Gewicht an der Maschine.","Setzte dich hin, beide Füße stabil auf dem Boden. Nehme die Gewichte, Kabel, etc. fest und führe eine rollende Bewegung nach vorn (die Wirbelsäule sollte sich idealerweise Wirbel für Wirbel von der Lehne lösen). Kehre langsam in die Ausgangsposition zurück."]}},{"id":"ex-crunches-with-cable","slug":"crunches-with-cable","name":"Crunches With Cable","description":"Cable exercise for the core.","instructions":["Take the cable on your hands and hold it next to your temples. Knee down and hold your upper body straight and bend forward. Go down with a fast movement, rolling your back in (your ellbows point to your knees). Once down, go slowly back to the initial position."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["crunches with cable","crunches am seil"],"media":[],"source":"wger","de":{"name":"Crunches am Seil","description":"Übung (Kabelzug) für den Rumpf.","instructions":["Nehme das Kabel in die Hand und halte es neben den Schläfen fest. Knie dich nun vor dem Kabelzug mit geradem aber nach vorne gebeugtem Oberkörper hin. Rolle dich mit einer schnellen Bewegung zusammen, die Ellenbogen zeigen zu den Knien. Gehe langsam wieder zur Anfangsposition zurück."]}},{"id":"ex-crunches-with-legs-up","slug":"crunches-with-legs-up","name":"Crunches With Legs Up","description":"Bodyweight exercise for the core.","instructions":["On your back, legs extended straight up, reach toward your toes with your hands and lift your shoulder blades off the ground and back."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["crunches with legs up","crunches mit gestreckten beinen"],"media":[],"source":"wger","de":{"name":"Crunches mit gestreckten Beinen","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Lege dich auf den Rücken, strecke die Beine gerade nach oben, greife mit den Händen in Richtung deiner Zehen und hebe dabei die Schulterblätter vom Boden ab und nach hinten."]}},{"id":"ex-cuban-press","slug":"cuban-press","name":"Cuban Press","description":"Dumbbell exercise for the shoulders, with back assisting.","instructions":["Take a dumbbell in each hand with a pronated grip in a standing position. Raise your upper arms so that they are parallel to the floor, allowing your lower arms to hang in the \"scarecrow\" position. This will be your starting position.","To initiate the movement, externally rotate the shoulders to move the upper arm 180 degrees. Keep the upper arms in place, rotating the upper arms until the wrists are directly above the elbows, the forearms perpendicular to the floor.","Now press the dumbbells by extending at the elbows, straightening your arms overhead.","Return to the starting position as you breathe in by reversing the steps.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"DUMBBELL","tags":["cuban press"],"media":[{"id":"cuban-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cuban_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"cuban-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cuban_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern, unterstützt von Rücken.","instructions":null}},{"id":"ex-curl-with-kettlebell-two-hands","slug":"curl-with-kettlebell-two-hands","name":"Curl with kettlebell two hands","description":"Kettlebell exercise for the biceps.","instructions":["Stand upright and grip the kettlebell with both hands. Perform the elbow flexion motion, starting from a fully extended position until your hand reaches shoulder height. Spread your legs a little for stability and, to perform the exercise correctly, try not to push with your back or body in general. Change the weight of the kettlebell to adjust the difficulty."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"KETTLEBELL","tags":["curl with kettlebell two hands","curl mit kettlebell beidhändig"],"media":[],"source":"wger","de":{"name":"Curl mit Kettlebell beidhändig","description":"Übung (Kettlebell) für den Bizeps.","instructions":["Stelle dich aufrecht hin und greife die Kettlebell mit beiden Händen. Führe die Ellbogenbeugung aus, beginnend aus der vollständig gestreckten Position, bis deine Hand Schulterhöhe erreicht. Stelle die Beine für mehr Stabilität etwas auseinander und versuche, die Übung korrekt auszuführen, indem du nicht mit dem Rücken oder dem Körper allgemein schwingst. Ändere das Gewicht der Kettlebell, um die Schwierigkeit anzupassen."]}},{"id":"ex-curl-with-shoulder-elevated","slug":"curl-with-shoulder-elevated","name":"Curl - With Shoulder Elevated","description":"Dumbbell exercise for the biceps.","instructions":["Place elbow so that it is about level with the shoulder. Curl the wieght to your shoulder. Focus on the stretch in the eccentric part of the curl"],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["curl - with shoulder elevated","curl mit angehobener schulter"],"media":[],"source":"wger","de":{"name":"Curl mit angehobener Schulter","description":"Übung (Kurzhantel) für den Bizeps.","instructions":["Positioniere den Ellbogen so, dass er etwa auf Höhe der Schulter liegt. Curle das Gewicht zu deiner Schulter. Konzentriere dich auf die Dehnung im exzentrischen Teil des Curls."]}},{"id":"ex-dancers-stretch","slug":"dancers-stretch","name":"Dancer's Stretch","description":"Equipment-free exercise for the back, with glutes assisting.","instructions":["Sit up on the floor.","Cross your right leg over your left, keeping the knee bent. Your left leg is straight and down on the floor.","Place your left arm on your right leg and your right hand on the floor.","Rotate your upper body to the right, and hold for 10-20 seconds. Switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["GLUTES"],"equipment":"NONE","tags":["dancer's stretch"],"media":[{"id":"dancers-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dancers_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dancers-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dancers_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Rücken, unterstützt von Po.","instructions":null}},{"id":"ex-db-upper-chest-variation","slug":"db-upper-chest-variation","name":"DB Upper Chest Variation","description":"Dumbbell exercise for the chest, with shoulders assisting.","instructions":["Dumbbell in hand in a curl fashion, lean body into the arm to help the dumbbell up above the chest, next to the head, to activate chest and delt combo"],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS"],"equipment":"DUMBBELL","tags":["db upper chest variation","kurzhantel-variation für die obere brust"],"media":[],"source":"wger","de":{"name":"Kurzhantel-Variation für die obere Brust","description":"Übung (Kurzhantel) für die Brust, unterstützt von Schultern.","instructions":["Halte die Kurzhantel wie bei einem Curl in der Hand und lehne deinen Körper in den Arm, um die Kurzhantel über die Brust nach oben zu führen, neben den Kopf, um die Brustmuskulatur und den Deltamuskel gemeinsam zu aktivieren."]}},{"id":"ex-db-wrist-extension","slug":"db-wrist-extension","name":"DB Wrist Extension","description":"Dumbbell exercise for the biceps.","instructions":["Grab two dumbbells with an overhand grip and lay your forearms across your knees.","Let your wrists flex fully, then extend your wrists."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["db wrist extension","handgelenkstreckung mit kurzhanteln"],"media":[],"source":"wger","de":{"name":"Handgelenkstreckung mit Kurzhanteln","description":"Übung (Kurzhantel) für den Bizeps.","instructions":["Greife zwei Kurzhanteln im Obergriff und lege deine Unterarme auf deinen Knien ab.","Lasse deine Handgelenke vollständig nach unten beugen und strecke sie dann nach oben."]}},{"id":"ex-dead-bug","slug":"dead-bug","name":"Dead Bug","description":"Bodyweight exercise for the core.","instructions":["Begin lying on your back with your hands extended above you toward the ceiling.","Bring your feet, knees, and hips up to 90 degrees.","Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.","Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.","Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.","Stay tight and return the working leg to the starting position.","Repeat on the opposite side, alternating until the set is complete."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["dead bug"],"media":[{"id":"dead-bug-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dead_Bug/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dead-bug-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dead_Bug/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-deadlift-with-bands","slug":"deadlift-with-bands","name":"Deadlift with Bands","description":"Barbell exercise for the back, with forearms, glutes, hamstrings, quadriceps assisting.","instructions":["To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. For long bands, they will need to be anchored to a secure base, such as heavy dumbbells or a rack.","With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["FOREARMS","GLUTES","HAMSTRINGS","QUADRICEPS"],"equipment":"BARBELL","tags":["deadlift with bands"],"media":[{"id":"deadlift-with-bands-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Deadlift_with_Bands/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"deadlift-with-bands-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Deadlift_with_Bands/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Unterarme, Po, Oberschenkelrückseite, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-deadlift-with-chains","slug":"deadlift-with-chains","name":"Deadlift with Chains","description":"Barbell exercise for the back, with forearms, glutes, hamstrings, quadriceps assisting.","instructions":["You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift.","Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets. With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar.","Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["FOREARMS","GLUTES","HAMSTRINGS","QUADRICEPS"],"equipment":"BARBELL","tags":["deadlift with chains"],"media":[{"id":"deadlift-with-chains-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Deadlift_with_Chains/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"deadlift-with-chains-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Deadlift_with_Chains/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Unterarme, Po, Oberschenkelrückseite, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-deadlifts","slug":"deadlifts","name":"Deadlifts","description":"Barbell exercise for the back, with glutes assisting.","instructions":["Stand firmly, with your feet slightly more than shoulder wide apart. Stand directly behind the bar where it should barely touch your shin, your feet pointing a bit out. Bend down with a straight back, the knees also pointing somewhat out. Grab the bar with a shoulder wide grip, one overhand, one underhand (mixed grip).","Pull the weight up. At the highest point make a slight hollow back and pull the bar back. Hold 1 or 2 seconds that position. Go down, making sure the back is not bent. Once down you can either go back again as soon as the weights touch the floor, or make a pause, depending on the weight."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["GLUTES"],"equipment":"BARBELL","tags":["deadlifts","kreuzheben"],"media":[{"id":"deadlifts-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/184/1709c405-620a-4d07-9658-fade2b66a2df.jpeg","caption":"Deadlifts","attribution":"wger.de · philip","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Kreuzheben","description":"Übung (Langhantel) für den Rücken, unterstützt von Po.","instructions":["Stelle dich mit etwas mehr als schulterbreitem Stand vor der Stange, die Füße zeigen leicht nach außen, die Stange ist direkt darüber und sehr nahe am Schienbein. Beuge die Knie (zeigen ebenfalls etwas nach außen) und neige den Oberkörper (bleibt während der ganzen Übung gerade). Greife die Stange schulterbreit mit einem Unter- und einem Obergriff.","Ziehe nun die Stange nach oben. An der höchsten Stelle mache ein leichtes Hohlkreuz und drücke die Schultern nach hinten. Gehe wieder runter, wobei du darauf achtest, dass der Rücken gerade bleibt und sich nicht krümmt. Du kannst unten angekommen eine kleine Pause einlegen oder sofort weitermachen."]}},{"id":"ex-decline-barbell-bench-press","slug":"decline-barbell-bench-press","name":"Decline Barbell Bench Press","description":"Barbell exercise for the chest, with shoulders, triceps assisting.","instructions":["Secure your legs at the end of the decline bench and slowly lay down on the bench.","Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.","As you breathe in, come down slowly until you feel the bar on your lower chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["decline barbell bench press","negativ bankdrücken"],"media":[{"id":"decline-barbell-bench-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Barbell_Bench_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"decline-barbell-bench-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Barbell_Bench_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Negativ Bankdrücken","description":"Übung (Langhantel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":["Lege dich auf die Negativbank hin, die Oberschenkel und der Rücken legen fest auf der drauf. Greife die Stange breit und lasse sie langsam und kontrolliert runter, dabei sollte die Stange kurz auf Brustwarzenhöhe den Körper berühren. Dann das Gewicht wieder hochdrücken bis die Arme durchgestreckt sind."]}},{"id":"ex-decline-bench-leg-raise","slug":"decline-bench-leg-raise","name":"Decline Bench Leg Raise","description":"Bodyweight exercise for the core.","instructions":["Setup: Lie on a decline bench with your head at the top and grip the handles.","The Start: Extend legs fully, keeping them slightly elevated to engage your core.","The Lift: Raise your legs toward the ceiling using your abs, not momentum.","The Squeeze: Pause and contract your lower abdominals at the top.","The Return: Lower your legs slowly to the starting position with control."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["decline bench leg raise","beinheben auf der schrägbank"],"media":[{"id":"decline-bench-leg-raise-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1889/bc51ef67-0c12-4340-a36c-42ef722778dd.png","caption":"Decline Bench Leg Raise","attribution":"wger.de · nishant0712","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Beinheben auf der Schrägbank","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Aufbau: Lege dich auf eine Schrägbank, mit dem Kopf am oberen Ende, und greife die Griffe.","Der Start: Strecke die Beine vollständig und halte sie leicht angehoben, um deinen Rumpf zu aktivieren.","Das Anheben: Hebe deine Beine in Richtung Decke, indem du die Bauchmuskulatur einsetzt, nicht den Schwung.","Das Anspannen: Halte kurz inne und ziehe oben deine untere Bauchmuskulatur zusammen.","Die Rückführung: Senke deine Beine langsam und kontrolliert in die Ausgangsposition."]}},{"id":"ex-decline-close-grip-bench-to-skull-crusher","slug":"decline-close-grip-bench-to-skull-crusher","name":"Decline Close-Grip Bench To Skull Crusher","description":"Barbell exercise for the triceps, with chest, shoulders assisting.","instructions":["Secure your legs at the end of the decline bench and slowly lay down on the bench.","Using a close grip (a grip that is slightly less than shoulder width), lift the bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.","Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.","Using the triceps to push the bar back up, press it back to the starting position as you exhale.","As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.","Lift the bar back to the starting position by contracting the triceps and exhaling.","Repeat steps 3-6 until the recommended amount of repetitions is performed."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"BARBELL","tags":["decline close-grip bench to skull crusher"],"media":[{"id":"decline-close-grip-bench-to-skull-crusher-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Close-Grip_Bench_To_Skull_Crusher/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"decline-close-grip-bench-to-skull-crusher-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Close-Grip_Bench_To_Skull_Crusher/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-decline-dumbbell-bench-press","slug":"decline-dumbbell-bench-press","name":"Decline Dumbbell Bench Press","description":"Dumbbell exercise for the chest, with shoulders, triceps assisting.","instructions":["Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.","Once you are laying down, move the dumbbells in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","Bring down the weights slowly to your side as you breathe out. Keep full control of the dumbbells at all times. Tip: Throughout the motion, the forearms should always be perpendicular to the floor.","As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up..","Repeat the movement for the prescribed amount of repetitions of your training program."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"DUMBBELL","tags":["decline dumbbell bench press","negativ bankdrücken kh"],"media":[{"id":"decline-dumbbell-bench-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Dumbbell_Bench_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"decline-dumbbell-bench-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Dumbbell_Bench_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Negativ Bankdrücken KH","description":"Übung (Kurzhantel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":["Nehmen Sie zwei Hanteln und setzen Sie sich auf eine Negativ Bank, die Füße stehen fest auf dem Boden, der Kopf ruht auf der Bank. Halten Sie die Gewichte neben die Brust auf Höhe Ihrer Brustwarzen und drücken Sie sie nach oben, bis die Arme gestreckt sind. Lassen Sie das Gewicht langsam und kontrolliert runter."]}},{"id":"ex-decline-dumbbell-flyes","slug":"decline-dumbbell-flyes","name":"Decline Dumbbell Flyes","description":"Dumbbell exercise for the chest.","instructions":["Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.","Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.","Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["decline dumbbell flyes"],"media":[{"id":"decline-dumbbell-flyes-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Dumbbell_Flyes/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"decline-dumbbell-flyes-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Dumbbell_Flyes/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Brust.","instructions":null}},{"id":"ex-decline-dumbbell-triceps-extension","slug":"decline-dumbbell-triceps-extension","name":"Decline Dumbbell Triceps Extension","description":"Dumbbell exercise for the triceps.","instructions":["Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.","Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.","As you breathe in and you keep the upper arms stationary (and elbows in), bring the dumbbells down slowly by moving your forearms in a semicircular motion towards you until your thumbs are next to your ears. Breathe in as you perform this portion of the movement.","Lift the dumbbells back to the starting position by contracting the triceps and exhaling.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["decline dumbbell triceps extension"],"media":[{"id":"decline-dumbbell-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Dumbbell_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"decline-dumbbell-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Dumbbell_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Trizeps.","instructions":null}},{"id":"ex-decline-ez-bar-triceps-extension","slug":"decline-ez-bar-triceps-extension","name":"Decline EZ Bar Triceps Extension","description":"Barbell exercise for the triceps.","instructions":["Secure your legs at the end of the decline bench and slowly lay down on the bench.","Using a close grip (a grip that is slightly less than shoulder width), lift the EZ bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.","As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.","Lift the bar back to the starting position by contracting the triceps and exhaling.","Repeat until the recommended amount of repetitions is performed."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["decline ez bar triceps extension"],"media":[{"id":"decline-ez-bar-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_EZ_Bar_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"decline-ez-bar-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_EZ_Bar_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Trizeps.","instructions":null}},{"id":"ex-decline-oblique-crunch","slug":"decline-oblique-crunch","name":"Decline Oblique Crunch","description":"Bodyweight exercise for the core.","instructions":["Secure your legs at the end of the decline bench and slowly lay down on the bench.","Raise your upper body off the bench until your torso is about 35-45 degrees if measured from the floor.","Put one hand beside your head and the other on your thigh. This will be your starting position.","Raise your upper body slowly from the starting position while turning your torso to the left. Continue crunching up as you exhale until your right elbow touches your left knee. Hold this contracted position for a second. Tip: Focus on keeping your abs tight and keeping the movement slow and controlled.","Lower your body back down slowly to the starting position as you inhale.","After completing one set on the right for the recommended amount of repetitions, switch to your left side. Tip: Focus on really twisting your torso and feeling the contraction when you are in the up position."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["decline oblique crunch"],"media":[{"id":"decline-oblique-crunch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Oblique_Crunch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"decline-oblique-crunch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Oblique_Crunch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-decline-push-up","slug":"decline-push-up","name":"Decline Push-Up","description":"Equipment-free exercise for the chest, with shoulders, triceps assisting.","instructions":["Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Move your feet up to a box or bench. This will be your starting position.","Next, lower yourself downward until your chest almost touches the floor as you inhale.","Now breathe out and press your upper body back up to the starting position while squeezing your chest.","After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"NONE","tags":["decline push-up"],"media":[{"id":"decline-push-up-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Push-Up/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"decline-push-up-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Push-Up/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-decline-reverse-crunch","slug":"decline-reverse-crunch","name":"Decline Reverse Crunch","description":"Bodyweight exercise for the core.","instructions":["Lie on your back on a decline bench and hold on to the top of the bench with both hands. Don't let your body slip down from this position.","Hold your legs parallel to the floor using your abs to hold them there while keeping your knees and feet together. Tip: Your legs should be fully extended with a slight bend on the knee. This will be your starting position.","While exhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the bench. At the end of this movement your knees will be touching your chest.","Hold the contraction for a second and move your legs back to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["decline reverse crunch"],"media":[{"id":"decline-reverse-crunch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Reverse_Crunch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"decline-reverse-crunch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Reverse_Crunch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-decline-smith-press","slug":"decline-smith-press","name":"Decline Smith Press","description":"Smith machine exercise for the chest, with shoulders, triceps assisting.","instructions":["Place a decline bench underneath the Smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms extended. This will be your starting position.","As you inhale, lower the bar under control by allowing the elbows to flex, lightly contacting the torso.","After a brief pause, bring the bar back to the starting position by extending the elbows, exhaling as you do so.","Repeat the movement for the prescribed amount of repetitions.","When the set is complete, lock the bar back in the rack."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"SMITH_MACHINE","tags":["decline smith press"],"media":[{"id":"decline-smith-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Smith_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"decline-smith-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Smith_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Multipresse) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-deficit-deadlift","slug":"deficit-deadlift","name":"Deficit Deadlift","description":"Barbell exercise for the back, with forearms, glutes, hamstrings, quadriceps assisting.","instructions":["Begin by having a platform or weight plates that you can stand on, usually 1-3 inches in height. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.","With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["FOREARMS","GLUTES","HAMSTRINGS","QUADRICEPS"],"equipment":"BARBELL","tags":["deficit deadlift","defizit kreuzheben"],"media":[{"id":"deficit-deadlift-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Deficit_Deadlift/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"deficit-deadlift-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Deficit_Deadlift/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Defizit Kreuzheben","description":"Übung (Langhantel) für den Rücken, unterstützt von Unterarme, Po, Oberschenkelrückseite, Oberschenkelvorderseite.","instructions":["Vorbereitung","Stellen Sie sich auf eine Hantelscheibe, eine Stoßstangenplatte oder eine flache, erhöhte Plattform mit einer geladenen Stange über den Füßen. Hocken Sie sich hin und fassen Sie die Stange mit schulterbreitem oder etwas breiterem Überhand- oder Mischgriff.","Ausführung","Heben Sie die Stange an, indem Sie die Hüften und Knie ganz ausstrecken. Ziehen Sie die Schultern oben am Lift zurück, wenn sie abgerundet sind. Bringen Sie die Gewichte wieder auf den Boden, indem Sie die Hüften nach hinten beugen, während Sie die Knie nach vorne beugen. Halten Sie dabei den Rücken gerade und die Knie in dieselbe Richtung wie die Füße. Wiederholen.","Bemerkungen","Halten Sie beim Heben die Hüften niedrig, die Schultern hoch, die Arme und den Rücken gerade. Die Knie sollten während der gesamten Bewegung in dieselbe Richtung zeigen wie die Füße. Halten Sie die Stange dicht am Körper, um die mechanische Hebelwirkung zu verbessern. Griffkraft und Kraftausdauer schränken häufig die Fähigkeit ein, bei starken Widerständen mehrere Wiederholungen durchzuführen. Gymnastikkreide, Handgelenkbänder, Griffarbeit und gemischter Griff können verwendet werden, um den Griff zu verbessern. Gemischter Griff bedeutet, dass eine Hand mit Überhandgriff und die andere Hand mit Unterhandgriff gehalten wird. Mit dem Hebelhantelheber kann die Hantel vom Boden gehoben werden, um das Be- und Entladen von Hantelscheiben zu erleichtern.","Unterer Rücken"]}},{"id":"ex-depth-jump-leap","slug":"depth-jump-leap","name":"Depth Jump Leap","description":"Accessory exercise for the quadriceps, with glutes, calves, hamstrings assisting.","instructions":["For this drill you will need two boxes or benches, one 12 to 16 inches high and the other 22 to 26 inches high.","Stand on one of the two boxes with arms at the sides; feet should be together and slightly off the edge as in the depth jump. Place the other box approximately two or three feet in front of and facing the performer.","Begin by dropping off the initial box, landing and simultaneously taking off with both feet.","Rebound by driving upward and outward as intensely as possible, using the arms and full extension of the body to jump onto the higher box. Again, allow the legs to absorb the impact."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","CALVES","HAMSTRINGS"],"equipment":"OTHER","tags":["depth jump leap"],"media":[{"id":"depth-jump-leap-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Depth_Jump_Leap/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"depth-jump-leap-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Depth_Jump_Leap/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite, unterstützt von Po, Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-diagonal-shoulder-press","slug":"diagonal-shoulder-press","name":"Diagonal Shoulder Press","description":"Bodyweight exercise for the shoulders.","instructions":["You sit at the bench press device, back slightly tilted to the back. The bar should be about 20 cm in front of you. Then you push the bar and take it back again, as you would with a bench press.","In this position you strain your chest muscles a lot less, which is nice if you want to train, but your chest hasn't recovered yet."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["diagonal shoulder press","diagonales schulterdrücken"],"media":[],"source":"wger","de":{"name":"Diagonales Schulterdrücken","description":"Übung (Körpergewicht) für die Schultern.","instructions":["Du sitzt am Bankdrück-Gerät, den Rücken leicht nach hinten geneigt. Die Stange sollte sich etwa 20 cm vor dir befinden. Dann drückst du die Stange weg und führst sie wieder zurück, so wie du es beim Bankdrücken tun würdest.","In dieser Position belastest du deine Brustmuskulatur deutlich weniger, was praktisch ist, wenn du trainieren möchtest, deine Brust sich aber noch nicht erholt hat."]}},{"id":"ex-diamond-push-ups","slug":"diamond-push-ups","name":"Diamond push ups","description":"Bodyweight exercise for the chest, with triceps assisting.","instructions":["Start: Get into a plank. Place hands close together under your chest so thumbs and index fingers form a diamond shape.","Lower: Bend your elbows to lower your chest toward your hands. Keep your body straight.","Push: Push back up until arms are fully extended.","New note Keep elbows close to your body and core tight."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["TRICEPS"],"equipment":"BODYWEIGHT","tags":["diamond push ups","liegestüzten diamond"],"media":[],"source":"wger","de":{"name":"Liegestüzten Diamond","description":"Übung (Körpergewicht) für die Brust, unterstützt von Trizeps.","instructions":["Liegestütze mit Händen zusammen. Die Hände werden so nebeneinander gelegt, das Daumen und Zeigefinger eine Raute (Diamant) bilden"]}},{"id":"ex-dip-machine","slug":"dip-machine","name":"Dip Machine","description":"Machine exercise for the triceps, with chest, shoulders assisting.","instructions":["Sit securely in a dip machine, select the weight and firmly grasp the handles.","Now keep your elbows in at your sides in order to place emphasis on the triceps. The elbows should be bent at a 90 degree angle.","As you contract the triceps, extend your arms downwards as you exhale. Tip: At the bottom of the movement, focus on keeping a little bend in your arms to keep tension on the triceps muscle.","Now slowly let your arms come back up to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"MACHINE","tags":["dip machine"],"media":[{"id":"dip-machine-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dip_Machine/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dip-machine-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dip_Machine/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-dips-between-two-benches","slug":"dips-between-two-benches","name":"Dips Between Two Benches","description":"Bodyweight exercise for the triceps.","instructions":["Put two benches so far appart, that you can hold onto one with your hands and are just able to reach the other with your feet. The legs stay during the exercise completely stretched. With your elbows facing back, bend them as much as you can. Push yourself up, but don't stretch out the arms."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["dips between two benches","dips zwischen 2 bänke"],"media":[{"id":"dips-between-two-benches-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/83/Bench-dips-1.png","caption":"Dips Between Two Benches","attribution":"wger.de · Everkinetic","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Dips Zwischen 2 Bänke","description":"Übung (Körpergewicht) für den Trizeps.","instructions":["Stelle zwei Bänke so weit ausernander, dass du die Hände am Rand der einen und du die Füße auf der anderen noch knapp draufstellen kannst. Die Beine bleiben während der Übung ausgestreckt. Beuge nun die Arme und gehe so tief wie möglich runter, die Ellenbogen zeigen nach hinten. Hebe den Körper wieder, achte aber darauf, dass du die Arme nicht ganz austreckst."]}},{"id":"ex-dips-chest-version","slug":"dips-chest-version","name":"Dips - Chest Version","description":"Accessory exercise for the chest, with shoulders, triceps assisting.","instructions":["For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.","While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest.","Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of the movement for a second.","Repeat the movement for the prescribed amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"OTHER","tags":["dips - chest version"],"media":[{"id":"dips-chest-version-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dips_-_Chest_Version/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dips-chest-version-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dips_-_Chest_Version/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-donkey-calf-raises","slug":"donkey-calf-raises","name":"Donkey Calf Raises","description":"Accessory exercise for the calves.","instructions":["For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad.","Place both of your arms on the side handles and place the balls of your feet on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to target, and straighten the knees without locking them. This will be your starting position.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["donkey calf raises"],"media":[{"id":"donkey-calf-raises-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Donkey_Calf_Raises/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"donkey-calf-raises-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Donkey_Calf_Raises/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Waden.","instructions":null}},{"id":"ex-doorway-pectoral-stretch","slug":"doorway-pectoral-stretch","name":"Doorway Pectoral Stretch","description":"Bodyweight exercise for the chest.","instructions":["Place the forearm vertically on a door frame or stationary object at head height","Step forward past the arm, keeping it still against the object to stretch the chest"],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["doorway pectoral stretch","brustdehnung im türrahmen"],"media":[],"source":"wger","de":{"name":"Brustdehnung im Türrahmen","description":"Übung (Körpergewicht) für die Brust.","instructions":["Lege den Unterarm senkrecht an einen Türrahmen oder ein feststehendes Objekt auf Kopfhöhe.","Mache einen Schritt nach vorne am Arm vorbei und halte ihn dabei still gegen das Objekt, um die Brust zu dehnen."]}},{"id":"ex-double-kettlebell-alternating-hang-clean","slug":"double-kettlebell-alternating-hang-clean","name":"Double Kettlebell Alternating Hang Clean","description":"Kettlebell exercise for the hamstrings, with biceps, calves, forearms, glutes, back, quadriceps assisting.","instructions":["Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.","Clean one kettlebell to your shoulder and hold on to the other kettlebell.","With a fluid motion, lower the top kettlebell while driving the bottom kettlebell up."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["BICEPS","CALVES","FOREARMS","GLUTES","BACK","QUADRICEPS"],"equipment":"KETTLEBELL","tags":["double kettlebell alternating hang clean"],"media":[{"id":"double-kettlebell-alternating-hang-clean-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Kettlebell_Alternating_Hang_Clean/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"double-kettlebell-alternating-hang-clean-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Kettlebell_Alternating_Hang_Clean/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Oberschenkelrückseite, unterstützt von Bizeps, Waden, Unterarme, Po, Rücken, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-double-kettlebell-clean-and-press","slug":"double-kettlebell-clean-and-press","name":"Double Kettlebell Clean and Press","description":"Kettlebell exercise for the shoulders, with biceps, quadriceps, back, triceps, hamstrings, glutes, core assisting.","instructions":["Full-body muscles building exercise. This exercise provides a huge range of benefits in terms of strength & size and is extremely functional."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BICEPS","QUADRICEPS","BACK","TRICEPS","HAMSTRINGS","GLUTES","ABS_CORE"],"equipment":"KETTLEBELL","tags":["double kettlebell clean and press","doppeltes kettlebell clean and press"],"media":[],"source":"wger","de":{"name":"Doppeltes Kettlebell Clean and Press","description":"Übung (Kettlebell) für die Schultern, unterstützt von Bizeps, Oberschenkelvorderseite, Rücken, Trizeps, Oberschenkelrückseite, Po, Rumpf.","instructions":["Ganzkörper-Übung für den Muskelaufbau. Diese Übung bietet eine enorme Bandbreite an Vorteilen in Bezug auf Kraft und Größe und ist äußerst funktionell."]}},{"id":"ex-double-kettlebell-jerk","slug":"double-kettlebell-jerk","name":"Double Kettlebell Jerk","description":"Kettlebell exercise for the shoulders, with calves, quadriceps, triceps assisting.","instructions":["Hold a kettlebell by the handle in each hand.","Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. This will be your starting position.","Dip your body by bending the knees, keeping your torso upright.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum.","As you do so, press the kettlebells overhead to lockout by extending the arms, using your body's momentum to move the weights.","Return your feet to the ground in a split fashion, with one foot forward and one foot back.","Keeping the weights overhead, return to a standing position, bringing your feet together. Lower the weights to perform the next repetition."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CALVES","QUADRICEPS","TRICEPS"],"equipment":"KETTLEBELL","tags":["double kettlebell jerk"],"media":[{"id":"double-kettlebell-jerk-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Kettlebell_Jerk/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"double-kettlebell-jerk-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Kettlebell_Jerk/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Waden, Oberschenkelvorderseite, Trizeps.","instructions":null}},{"id":"ex-double-kettlebell-push-press","slug":"double-kettlebell-push-press","name":"Double Kettlebell Push Press","description":"Kettlebell exercise for the shoulders, with calves, quadriceps, triceps assisting.","instructions":["Clean two kettlebells to your shoulders.","Squat down a few inches and reverse the motion rapidly. Use the momentum from the legs to drive the kettlebells overhead.","Once the kettlebells are locked out, lower the kettlebells to your shoulders and repeat."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CALVES","QUADRICEPS","TRICEPS"],"equipment":"KETTLEBELL","tags":["double kettlebell push press"],"media":[{"id":"double-kettlebell-push-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Kettlebell_Push_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"double-kettlebell-push-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Kettlebell_Push_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Waden, Oberschenkelvorderseite, Trizeps.","instructions":null}},{"id":"ex-double-kettlebell-snatch","slug":"double-kettlebell-snatch","name":"Double Kettlebell Snatch","description":"Kettlebell exercise for the shoulders, with glutes, hamstrings, quadriceps assisting.","instructions":["Place two kettlebells behind your feet. Bend your knees and sit back to pick up the kettlebells.","Swing the kettlebells between your legs forcefully and reverse the direction.","Drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["GLUTES","HAMSTRINGS","QUADRICEPS"],"equipment":"KETTLEBELL","tags":["double kettlebell snatch"],"media":[{"id":"double-kettlebell-snatch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Kettlebell_Snatch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"double-kettlebell-snatch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Kettlebell_Snatch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Po, Oberschenkelrückseite, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-double-kettlebell-windmill","slug":"double-kettlebell-windmill","name":"Double Kettlebell Windmill","description":"Kettlebell exercise for the core, with glutes, hamstrings, shoulders, triceps assisting.","instructions":["Place a kettlebell in front of your front foot and clean and press a kettlebell overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward.","Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell.","Bending at the hip to one side, sticking your butt out, slowly lean until you can retrieve the kettlebell from the floor. Keep your eyes on the kettlebell that you hold over your head at all times.","Pause for a second after retrieving the kettlebell from the ground and reverse the motion back to the starting position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["GLUTES","HAMSTRINGS","SHOULDERS","TRICEPS"],"equipment":"KETTLEBELL","tags":["double kettlebell windmill"],"media":[{"id":"double-kettlebell-windmill-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Kettlebell_Windmill/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"double-kettlebell-windmill-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Kettlebell_Windmill/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für den Rumpf, unterstützt von Po, Oberschenkelrückseite, Schultern, Trizeps.","instructions":null}},{"id":"ex-double-leg-abdominal-press","slug":"double-leg-abdominal-press","name":"Double-Leg Abdominal Press","description":"Bodyweight exercise for the core.","instructions":["Lie on your back with knees and hips bent at 90 degrees (tabletop).","Place your hands on your thighs just above your knees. Push your hands against your knees as hard as possible while using your abs to pull your knees toward your hands.","Hold for 10 seconds of maximum effort. Your abs should be shaking."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["double-leg abdominal press","bauchpresse mit beiden beinen"],"media":[],"source":"wger","de":{"name":"Bauchpresse mit beiden Beinen","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Lege dich auf den Rücken, mit Knien und Hüften im 90-Grad-Winkel gebeugt (Tabletop-Position).","Lege deine Hände auf deine Oberschenkel, knapp oberhalb der Knie. Drücke deine Hände so fest wie möglich gegen die Knie, während du mit deiner Bauchmuskulatur die Knie zu den Händen ziehst.","Halte 10 Sekunden lang mit maximaler Anstrengung. Deine Bauchmuskeln sollten zittern."]}},{"id":"ex-double-leg-butt-kick","slug":"double-leg-butt-kick","name":"Double Leg Butt Kick","description":"Bodyweight exercise for the quadriceps, with glutes, calves, hamstrings assisting.","instructions":["Begin standing with your knees slightly bent.","Quickly squat a short distance, flexing the hips and knees, and immediately extend to jump for maximum vertical height.","As you go up, tuck your heels by flexing the knees, attempting to touch the buttocks.","Finish the motion by landing with the knees only partially bent, using your legs to absorb the impact."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","CALVES","HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["double leg butt kick"],"media":[{"id":"double-leg-butt-kick-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Leg_Butt_Kick/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"double-leg-butt-kick-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Leg_Butt_Kick/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Po, Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-double-leg-calf-raise","slug":"double-leg-calf-raise","name":"Double Leg Calf Raise","description":"Bodyweight exercise for the calves.","instructions":["The double leg heel raise is important to strengthen and create control and stability around the ankle and knee, and provide balance and control for the hip and pelvis."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["double leg calf raise","beidbeiniges wadenheben"],"media":[{"id":"double-leg-calf-raise-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1243/53d4fabe-c994-4907-873f-8d82813a9832.png","caption":"Double Leg Calf Raise","attribution":"wger.de · erikocobra","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Beidbeiniges Wadenheben","description":"Übung (Körpergewicht) für die Waden.","instructions":["Das beidbeinige Wadenheben ist wichtig, um Kontrolle und Stabilität rund um Sprunggelenk und Knie zu stärken und aufzubauen sowie Gleichgewicht und Kontrolle für Hüfte und Becken zu schaffen."]}},{"id":"ex-downward-facing-balance","slug":"downward-facing-balance","name":"Downward Facing Balance","description":"Accessory exercise for the glutes, with core, hamstrings assisting.","instructions":["Lie facedown on top of an exercise ball.","While resting on your stomach on the ball, walk your hands forward along the floor and lift your legs, extending your elbows and knees."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["ABS_CORE","HAMSTRINGS"],"equipment":"OTHER","tags":["downward facing balance"],"media":[{"id":"downward-facing-balance-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Downward_Facing_Balance/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"downward-facing-balance-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Downward_Facing_Balance/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Po, unterstützt von Rumpf, Oberschenkelrückseite.","instructions":null}},{"id":"ex-drag-curl","slug":"drag-curl","name":"Drag Curl","description":"Barbell exercise for the biceps, with forearms assisting.","instructions":["Grab a barbell with a supinated grip (palms facing forward) and get your elbows close to your torso and back. This will be your starting position.","As you exhale, curl the bar up while keeping the elbows to the back as you \"Drag\" the bar up by keeping it in contact with your torso. Tip: As you can see, you will not be keeping the elbows pinned to your sides, but instead you will be bringing them back. Also, do not lift your shoulders.","Slowly go back to the starting position as you keep the bar in contact with the torso at all times.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"BARBELL","tags":["drag curl"],"media":[{"id":"drag-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Drag_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"drag-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Drag_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Bizeps, unterstützt von Unterarme.","instructions":null}},{"id":"ex-dragon-flag","slug":"dragon-flag","name":"Dragon-flag","description":"Bodyweight exercise for the core, with shoulders, glutes, back, triceps assisting.","instructions":["Keep your body completely rigid throughout the movement, avoiding sagging in your lower back.","Use a firm grip to stabilize your upper body.","Start with simpler versions (such as with bent knees) to build strength and control."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["SHOULDERS","GLUTES","BACK","TRICEPS"],"equipment":"BODYWEIGHT","tags":["dragon-flag","dragon flag"],"media":[],"source":"wger","de":{"name":"Dragon Flag","description":"Übung (Körpergewicht) für den Rumpf, unterstützt von Schultern, Po, Rücken, Trizeps.","instructions":["In Rückenlage, mit den Händen über dem Kopf an etwas festhalten (Kopfpolster der Hantelbank, unterste Sprosse der Sprossenwand...), sodass der Oberkörper möglichst unbeweglich wird. Dann die Beine in Richtung Decke heben, dabei auch das Becken abheben (ähnlich wie die \"Kerze\" aus Gymnastik/Yoga). Die Beine langsam wieder ablassen, möglichst viel Widerstand aus dem Bauch heraus. Beine seitlich drehen ist auch möglich."]}},{"id":"ex-dragon-squat","slug":"dragon-squat","name":"Dragon squat","description":"Bodyweight exercise for the quadriceps, with hamstrings, calves, glutes assisting.","instructions":["Start standing with your feet hip-width apart. Cross your right foot behind you to the left corner and back of the room while bending both knees. Return and repeat, alternating sides. Keep your hips and shoulders forward as you cross your feet and bend your knees."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["HAMSTRINGS","CALVES","GLUTES"],"equipment":"BODYWEIGHT","tags":["dragon squat"],"media":[],"source":"wger","de":{"name":"Dragon Squat","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Oberschenkelrückseite, Waden, Po.","instructions":["Beginne im Stand mit hüftbreit aufgestellten Füßen. Kreuze deinen rechten Fuß hinter dir zur linken hinteren Ecke des Raumes, während du beide Knie beugst. Kehre zurück und wiederhole die Bewegung im Wechsel der Seiten. Halte Hüfte und Schultern nach vorne gerichtet, während du die Füße kreuzt und die Knie beugst."]}},{"id":"ex-drop-push","slug":"drop-push","name":"Drop Push","description":"Accessory exercise for the chest, with shoulders, triceps assisting.","instructions":["Position low boxes or other platforms 2-3 feet apart.","Move to a pushup position between them, supporting yourself by placing your hands on the boxes.","With good posture, drop from the platforms by pressing up and moving your hands to shoulder width, cushioning your landing by absorbing the impact through the arm."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"OTHER","tags":["drop push"],"media":[{"id":"drop-push-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Drop_Push/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"drop-push-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Drop_Push/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-dumbbell-alternate-bicep-curl","slug":"dumbbell-alternate-bicep-curl","name":"Dumbbell Alternate Bicep Curl","description":"Dumbbell exercise for the biceps, with forearms assisting.","instructions":["Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs.","While holding the upper arm stationary, curl the right weight as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you breathe out until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.","Slowly begin to bring the dumbbell back to the starting position as your breathe in. Tip: Remember to twist the palms back to the starting position (facing your thighs) as you come down.","Repeat the movement with the left hand. This equals one repetition.","Continue alternating in this manner for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"DUMBBELL","tags":["dumbbell alternate bicep curl"],"media":[{"id":"dumbbell-alternate-bicep-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Alternate_Bicep_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-alternate-bicep-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Alternate_Bicep_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps, unterstützt von Unterarme.","instructions":null}},{"id":"ex-dumbbell-bench-press-with-neutral-grip","slug":"dumbbell-bench-press-with-neutral-grip","name":"Dumbbell Bench Press with Neutral Grip","description":"Dumbbell exercise for the chest, with shoulders, triceps assisting.","instructions":["Take a dumbbell in each hand and lay back onto a flat bench. Your feet should be flat on the floor and your shoulder blades retracted.","Maintaining a neutral grip, palms facing each other, begin with your arms extended directly above you, perpendicular to the floor. This will be your starting position.","Begin the movement by flexing the elbow, lowering the upper arms to the side. Descend until the dumbbells are to your torso.","Pause, then extend the elbow and return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"DUMBBELL","tags":["dumbbell bench press with neutral grip"],"media":[{"id":"dumbbell-bench-press-with-neutral-grip-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press_with_Neutral_Grip/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-bench-press-with-neutral-grip-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press_with_Neutral_Grip/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-dumbbell-bent-over-face-pull","slug":"dumbbell-bent-over-face-pull","name":"Dumbbell Bent Over Face Pull","description":"Dumbbell exercise for the shoulders, with back assisting.","instructions":["This exercise involves using dumbbells to perform a bent over face pull, which targets the upper back and shoulders. The movement involves pulling the weights towards the face while keeping the elbows high and squeezing the shoulder blades together."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"DUMBBELL","tags":["dumbbell bent over face pull","face pull mit kurzhanteln in vorgebeugter haltung"],"media":[{"id":"dumbbell-bent-over-face-pull-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1639/8927346e-f5ca-4795-bdf1-5ac9309401e7.webp","caption":"Dumbbell Bent Over Face Pull","attribution":"wger.de · AlucardEvil40","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Face Pull mit Kurzhanteln in vorgebeugter Haltung","description":"Übung (Kurzhantel) für die Schultern, unterstützt von Rücken.","instructions":["Bei dieser Übung verwendest du Kurzhanteln, um einen Face Pull in vorgebeugter Haltung auszuführen, der den oberen Rücken und die Schultern beansprucht. Die Bewegung besteht darin, die Gewichte in Richtung des Gesichts zu ziehen, während du die Ellbogen hoch hältst und die Schulterblätter zusammenziehst."]}},{"id":"ex-dumbbell-bicep-curl","slug":"dumbbell-bicep-curl","name":"Dumbbell Bicep Curl","description":"Dumbbell exercise for the biceps, with forearms assisting.","instructions":["Stand up straight with a dumbbell in each hand at arm's length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"DUMBBELL","tags":["dumbbell bicep curl","bizeps kh-curls"],"media":[{"id":"dumbbell-bicep-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bicep_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-bicep-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bicep_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Bizeps KH-Curls","description":"Übung (Kurzhantel) für den Bizeps, unterstützt von Unterarme.","instructions":["Halte zwei Kurzhantel mit ausgestreckten Armen neben dem Körper, die Handflächen zeigen nach innen. Beuge die Arme und brige die Hanteln mit einer schnellen Bewegung nach oben wobei sie gleichzeitig um 90 Grad gedreht werden. Am höchsten Punkt kann man die Hanteln ganz leicht weiter nach außen drehen. Ohne Pause wird das Gewicht nun kontrolliert nach unten gebracht. Beachte, dass die Bewegung nach oben schneller ist als nach unten.","Während des Bewegungablaufs darf der Körper nicht mitschwingen. Die Ellenbogen bleiben dabei immer an der Stelle."]}},{"id":"ex-dumbbell-bicep-curl-to-press","slug":"dumbbell-bicep-curl-to-press","name":"Dumbbell bicep curl to press","description":"Dumbbell exercise for the biceps.","instructions":["Bend your elbows and lift the dumbbells to your shoulders.","Push the dumbbells over your head while rotating your arms to make your palms face forward. Reverse it to lower down. Repeat the exercise."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["dumbbell bicep curl to press","kurzhantel-bizeps-curl mit schulterdrücken"],"media":[{"id":"dumbbell-bicep-curl-to-press-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1226/a6154dbd-67a0-4a36-8748-0f5af3865e83.jpg","caption":"Dumbbell bicep curl to press","attribution":"wger.de · Lynn_McIntyre","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Kurzhantel-Bizeps-Curl mit Schulterdrücken","description":"Übung (Kurzhantel) für den Bizeps.","instructions":["Beuge die Ellbogen und hebe die Kurzhanteln zu den Schultern.","Drücke die Kurzhanteln über deinen Kopf, während du die Arme so drehst, dass die Handflächen nach vorne zeigen. Kehre die Bewegung um, um wieder abzusenken. Wiederhole die Übung."]}},{"id":"ex-dumbbell-bradford-press","slug":"dumbbell-bradford-press","name":"Dumbbell Bradford press","description":"Dumbbell exercise for the shoulders.","instructions":["From a front hold of the DBs in a OHP, press above the head, bring back towards the rear of the shoulders, down, and press back forward."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["dumbbell bradford press","bradford-drücken mit kurzhanteln"],"media":[],"source":"wger","de":{"name":"Bradford-Drücken mit Kurzhanteln","description":"Übung (Kurzhantel) für die Schultern.","instructions":["Halte die Kurzhanteln vorne wie beim Schulterdrücken über dem Kopf, drücke sie über den Kopf, führe sie nach hinten zum Nacken, senke sie ab und drücke sie wieder nach vorne."]}},{"id":"ex-dumbbell-cheat-curl","slug":"dumbbell-cheat-curl","name":"Dumbbell Cheat Curl","description":"Dumbbell exercise for the biceps.","instructions":["Starting position is standing","with feet shoulder width apart.","Hands should take an underhand","or supinated grip on the dumbbells holding them with hands shoulder","width apart.","Keeping elbows tucked into your","sides throughout the entire movement, use momentum to curl the dumbbells,","squeezing your biceps at the top of the movement."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["dumbbell cheat curl","kurzhantel-cheat-curl"],"media":[],"source":"wger","de":{"name":"Kurzhantel-Cheat-Curl","description":"Übung (Kurzhantel) für den Bizeps.","instructions":["Die Ausgangsposition ist stehend","mit den Füßen schulterbreit auseinander.","Die Hände nehmen einen Untergriff","bzw. supinierten Griff an den Kurzhanteln ein und halten sie mit den Händen","schulterbreit auseinander.","Halte die Ellbogen während der gesamten","Bewegung eng am Körper, nutze Schwung, um die Kurzhanteln zu curlen,","und spanne den Bizeps am oberen Ende der Bewegung an."]}},{"id":"ex-dumbbell-clean","slug":"dumbbell-clean","name":"Dumbbell Clean","description":"Dumbbell exercise for the hamstrings, with calves, forearms, glutes, back, quadriceps, shoulders assisting.","instructions":["Begin standing with a dumbbell in each hand with your feet shoulder width apart.","Lower the weights to the floor by flexing at the hips and knees, pushing your hips back until the dumbbells reach the floor. This will be your starting position.","To initiate the movement, violently jump upward by extending the hips, knees, and ankles to acclerate the weights upward. Maintaining a neutral grip on the dumbbells, keep the arms straight until full extension is reached.","After full extension, rebend the hips and knees to receive the weight in a squat position. Allow the arms to bend, guiding the dumbbells to your shoulders.","Upon receiving the weight in the squat position, extend the hips and knees to finish in a standing position with the weights on your shoulders."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","FOREARMS","GLUTES","BACK","QUADRICEPS","SHOULDERS"],"equipment":"DUMBBELL","tags":["dumbbell clean"],"media":[{"id":"dumbbell-clean-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Clean/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-clean-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Clean/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Oberschenkelrückseite, unterstützt von Waden, Unterarme, Po, Rücken, Oberschenkelvorderseite, Schultern.","instructions":null}},{"id":"ex-dumbbell-concentration-curl","slug":"dumbbell-concentration-curl","name":"Dumbbell Concentration Curl","description":"Dumbbell exercise for the biceps.","instructions":["Sit on bench. Grasp dumbbell between feet. Place back of upper arm to inner thigh. Lean into leg to raise elbow slightly."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["dumbbell concentration curl","konzentrations-curls"],"media":[],"source":"wger","de":{"name":"Konzentrations-Curls","description":"Übung (Kurzhantel) für den Bizeps.","instructions":["Setz dich auf die Bank. Fassen Sie die Hantel zwischen den Beinen. Legen Sie den Oberarm an den inneren Oberschenkel. Unterarm anheben."]}},{"id":"ex-dumbbell-crunches","slug":"dumbbell-crunches","name":"Dumbbell Crunches","description":"Dumbbell exercise for the core.","instructions":["Dumbbell crunches are a weighted variation of traditional crunches designed to target the abdominal muscles more intensely. Lie flat on your back with your knees bent and feet flat on the floor. Hold a dumbbell with both hands close to your chest or above your head. Lift your shoulders and upper back off the ground in a crunching motion, engaging your core. Slowly lower yourself back to the starting position. Ensure controlled movements throughout the exercise to prevent strain."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["dumbbell crunches","kurzhantel-crunches"],"media":[],"source":"wger","de":{"name":"Kurzhantel-Crunches","description":"Übung (Kurzhantel) für den Rumpf.","instructions":["Kurzhantel-Crunches sind eine gewichtete Variante der klassischen Crunches, die darauf ausgelegt ist, die Bauchmuskulatur intensiver zu beanspruchen. Lege dich flach auf den Rücken, die Knie gebeugt und die Füße flach auf dem Boden. Halte eine Kurzhantel mit beiden Händen nahe an deiner Brust oder über deinem Kopf. Hebe deine Schultern und deinen oberen Rücken in einer Crunch-Bewegung vom Boden ab und spanne dabei deinen Rumpf an. Senke dich langsam zurück in die Startposition. Achte während der gesamten Übung auf kontrollierte Bewegungen, um Verletzungen zu vermeiden."]}},{"id":"ex-dumbbell-curl","slug":"dumbbell-curl","name":"Dumbbell Curl","description":"Dumbbell exercise for the biceps, with shoulders, core assisting.","instructions":["The Dumbbell Curl is a classic isolation exercise for the arms. Unlike the Hammer Curl, it involves rotating your wrists (supination) as you lift the weights, which allows for a full contraction of the biceps."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["SHOULDERS","ABS_CORE"],"equipment":"DUMBBELL","tags":["dumbbell curl","kurzhantel-curl"],"media":[],"source":"wger","de":{"name":"Kurzhantel-Curl","description":"Übung (Kurzhantel) für den Bizeps, unterstützt von Schultern, Rumpf.","instructions":["Der Kurzhantel-Curl ist eine klassische Isolationsübung für die Arme. Anders als beim Hammer-Curl drehst du beim Anheben der Gewichte deine Handgelenke (Supination), was eine vollständige Kontraktion des Bizeps ermöglicht."]}},{"id":"ex-dumbbell-donkey-kick","slug":"dumbbell-donkey-kick","name":"Dumbbell donkey kick","description":"Dumbbell exercise for the hamstrings, with glutes assisting.","instructions":["The dumbbell donkey kick is an effective exercise for working the glute and hamstring muscles. This exercise is usually performed on all fours, using a dumbbell to add resistance. The steps for performing it correctly are described below.","Starting position: Get on all fours on a mat, with your hands aligned under your shoulders and your knees aligned under your hips.","Placing the dumbbell: Take a dumbbell and place it behind the knee of the leg you are going to lift. Make sure it is held securely to prevent it from falling during the exercise.","Exercise:","Inhale and, as you exhale, lift the leg with the dumbbell upward, keeping the knee bent at a 90-degree angle.","Raise the leg until it is parallel to the floor, feeling the contraction in the glutes.","Hold the position for one second at the top and then slowly lower the leg back to the starting position.","Repetitions: Perform 10 to 15 repetitions per leg, making sure to maintain good form throughout the exercise."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES"],"equipment":"DUMBBELL","tags":["dumbbell donkey kick","eselstritt mit kurzhantel"],"media":[{"id":"dumbbell-donkey-kick-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1616/97e6fd98-2ca6-486f-b9b2-f0499fe38044.jpg","caption":"Dumbbell donkey kick","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Eselstritt mit Kurzhantel","description":"Übung (Kurzhantel) für die Oberschenkelrückseite, unterstützt von Po.","instructions":["Der Eselstritt mit Kurzhantel ist eine effektive Übung, um die Gesäßmuskulatur und die hintere Oberschenkelmuskulatur zu trainieren. Diese Übung wird in der Regel im Vierfüßlerstand ausgeführt, wobei eine Kurzhantel verwendet wird, um den Widerstand zu erhöhen. Im Folgenden werden die Schritte beschrieben, um sie korrekt durchzuführen.","Ausgangsposition: Begib dich auf einer Matte in den Vierfüßlerstand, wobei deine Hände auf einer Linie mit den Schultern und deine Knie auf einer Linie mit den Hüften sind.","Platzierung der Kurzhantel: Nimm eine Kurzhantel und klemme sie hinter dem Knie des Beins ein, das du anheben möchtest. Achte darauf, dass sie gut fixiert ist, damit sie während der Übung nicht herunterfällt.","Übung:","Atme ein und hebe beim Ausatmen das Bein mit der Kurzhantel nach oben, wobei du das Knie in einem 90-Grad-Winkel gebeugt hältst.","Hebe das Bein an, bis es parallel zum Boden ist, und spüre dabei die Kontraktion in der Gesäßmuskulatur.","Halte die Position oben eine Sekunde lang und senke das Bein dann langsam in die Ausgangsposition zurück.","Wiederholungen: Führe 10 bis 15 Wiederholungen pro Bein aus und achte dabei während der gesamten Übung auf eine saubere Ausführung."]}},{"id":"ex-dumbbell-drag-curls","slug":"dumbbell-drag-curls","name":"Dumbbell drag curls","description":"Dumbbell exercise for the biceps.","instructions":["Hold a dumbbell in each hand with your palms facing forward. Pull your elbows back and lift the dumbbells to your chest height. Slowly lower the dumbbell and repeat the exercise."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["dumbbell drag curls","kurzhantel-drag-curls"],"media":[],"source":"wger","de":{"name":"Kurzhantel-Drag-Curls","description":"Übung (Kurzhantel) für den Bizeps.","instructions":["Halte in jeder Hand eine Kurzhantel mit den Handflächen nach vorne. Ziehe deine Ellbogen nach hinten und hebe die Kurzhanteln auf Brusthöhe. Senke die Kurzhanteln langsam ab und wiederhole die Übung."]}},{"id":"ex-dumbbell-floor-press","slug":"dumbbell-floor-press","name":"Dumbbell Floor Press","description":"Dumbbell exercise for the triceps, with chest, shoulders assisting.","instructions":["Lay on the floor holding dumbbells in your hands. Your knees can be bent. Begin with the weights fully extended above you.","Lower the weights until your upper arm comes in contact with the floor. You can tuck your elbows to emphasize triceps size and strength, or to focus on your chest angle your arms to the side.","Pause at the bottom, and then bring the weight together at the top by extending through the elbows."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"DUMBBELL","tags":["dumbbell floor press","kurzhantel-bodendrücken"],"media":[{"id":"dumbbell-floor-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Floor_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-floor-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Floor_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Kurzhantel-Bodendrücken","description":"Übung (Kurzhantel) für den Trizeps, unterstützt von Brust, Schultern.","instructions":["Nimm deine Kurzhanteln und lege dich flach auf den Rücken, die Knie angewinkelt und die Füße flach auf dem Boden (benutze eine Bank, falls du eine hast). Drücke die Gewichte nach oben und strecke die Ellbogen durch (A). Senke sie langsam ab, bis deine Oberarme nah am Körper auf dem Boden ruhen (B). Halte hier kurz inne, bevor du sie explosiv wieder nach oben drückst. Spanne die Brust kräftig an und wiederhole."]}},{"id":"ex-dumbbell-front-squat","slug":"dumbbell-front-squat","name":"Dumbbell Front Squat","description":"Dumbbell exercise for the glutes, with quadriceps, shoulders, core assisting.","instructions":["This exercise involves holding a dumbbell in each hand at shoulder height and performing a squat. It targets the lower body muscles, including the quads, hamstrings, and glutes, while also engaging the core and upper body."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["QUADRICEPS","SHOULDERS","ABS_CORE"],"equipment":"DUMBBELL","tags":["dumbbell front squat","frontkniebeuge mit kurzhanteln"],"media":[{"id":"dumbbell-front-squat-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1640/bdea82f1-15ef-4649-8b5a-1303cfc178e7.webp","caption":"Dumbbell Front Squat","attribution":"wger.de · AlucardEvil40","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Frontkniebeuge mit Kurzhanteln","description":"Übung (Kurzhantel) für den Po, unterstützt von Oberschenkelvorderseite, Schultern, Rumpf.","instructions":["Bei dieser Übung hältst du in jeder Hand eine Kurzhantel auf Schulterhöhe und führst eine Kniebeuge aus. Sie trainiert die Muskulatur des Unterkörpers, einschließlich der vorderen Oberschenkelmuskulatur (Quadrizeps), der hinteren Oberschenkelmuskulatur und der Gesäßmuskulatur, und beansprucht zugleich den Rumpf und den Oberkörper."]}},{"id":"ex-dumbbell-goblet-squat","slug":"dumbbell-goblet-squat","name":"Dumbbell Goblet Squat","description":"Dumbbell exercise for the quadriceps.","instructions":["Grasp dumbbell with both hands at the sides of the upper plates. Hold dumbbell in front of chest, close to torso. Place feet about shoulderwide apart, keep knees slightly bent.","Squat down until thighs are parallel to floor. Keep back straight, bend and move hips backward to keep knees above feet. Return, keep knees slightly flexed. Repeat.","Keep bodyweight on heels and look ahead or slightly above to keep back straight."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["dumbbell goblet squat","goblet squat mit kurzhantel"],"media":[{"id":"dumbbell-goblet-squat-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/203/1c052351-2af0-4227-aeb0-244008e4b0a8.jpeg","caption":"Dumbbell Goblet Squat","attribution":"wger.de · philip","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Goblet Squat mit Kurzhantel","description":"Übung (Kurzhantel) für die Oberschenkelvorderseite.","instructions":["Greife die Kurzhantel mit beiden Händen an den Seiten der oberen Gewichtsscheiben. Halte die Kurzhantel vor der Brust, nah am Oberkörper. Stelle die Füße etwa schulterbreit auseinander und halte die Knie leicht gebeugt.","Gehe in die Hocke, bis die Oberschenkel parallel zum Boden sind. Halte den Rücken gerade, beuge dich und schiebe die Hüfte nach hinten, damit die Knie über den Füßen bleiben. Komme wieder hoch und halte die Knie leicht gebeugt. Wiederhole die Bewegung.","Verlagere dein Körpergewicht auf die Fersen und blicke geradeaus oder leicht nach oben, um den Rücken gerade zu halten."]}},{"id":"ex-dumbbell-hang-power-cleans","slug":"dumbbell-hang-power-cleans","name":"Dumbbell Hang Power Cleans","description":"Dumbbell exercise for the hamstrings, with glutes, calves, quadriceps, back assisting.","instructions":["On your feet, stand tall with your dumbbells, holding them at your sides. Hinge at the hips to lower them to your knees (picture 1). Stand back up with a slight jump, using the momentum to pull the dumbbells up on to your shoulders (picture 2). Stand up straight, then lower under control to your sides and repeat. Keep this fast and explosive; if your heart rate doesn’t hit the roof, you’re doing them wrong."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","CALVES","QUADRICEPS","BACK"],"equipment":"DUMBBELL","tags":["dumbbell hang power cleans","hang power cleans mit kurzhanteln"],"media":[{"id":"dumbbell-hang-power-cleans-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1087/d85f4e02-b20c-457c-bdfb-0b00e2d14150.jpg","caption":"Dumbbell Hang Power Cleans","attribution":"wger.de · philip","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Hang Power Cleans mit Kurzhanteln","description":"Übung (Kurzhantel) für die Oberschenkelrückseite, unterstützt von Po, Waden, Oberschenkelvorderseite, Rücken.","instructions":["Stehe aufrecht auf deinen Füßen mit deinen Kurzhanteln und halte sie an den Seiten. Beuge dich in der Hüfte, um sie bis zu den Knien abzusenken (Bild 1). Richte dich mit einem leichten Sprung wieder auf und nutze den Schwung, um die Kurzhanteln auf deine Schultern zu ziehen (Bild 2). Stelle dich gerade hin, senke sie dann kontrolliert wieder an die Seiten und wiederhole. Halte dies schnell und explosiv; wenn dein Puls nicht in die Höhe schießt, machst du sie falsch."]}},{"id":"ex-dumbbell-hex-press","slug":"dumbbell-hex-press","name":"Dumbbell Hex Press","description":"Dumbbell exercise for the chest, with triceps, shoulders assisting.","instructions":["Engage the muscles","Position your feet wide","Controlled movement","Slow movement","Bring the weights toward your lower chest/stomach"],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["TRICEPS","SHOULDERS"],"equipment":"DUMBBELL","tags":["dumbbell hex press","hex press mit kurzhanteln"],"media":[{"id":"dumbbell-hex-press-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1353/138cb483-7d4d-4519-b029-63e4269810a6.webp","caption":"Dumbbell Hex Press","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Hex Press mit Kurzhanteln","description":"Übung (Kurzhantel) für die Brust, unterstützt von Trizeps, Schultern.","instructions":["Muskulatur anspannen","Füße breit positionieren","Kontrollierte Bewegung","Langsame Bewegung","Gewichte zur unteren Brust/zum Bauch führen"]}},{"id":"ex-dumbbell-hip-thrust","slug":"dumbbell-hip-thrust","name":"Dumbbell Hip Thrust","description":"Dumbbell exercise for the glutes, with quadriceps assisting.","instructions":["This exercise involves sitting on the ground with a dumbbell resting on the hips, then thrusting the hips upward while squeezing the glutes. It is a great exercise for strengthening the glutes and improving hip mobility."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["QUADRICEPS"],"equipment":"DUMBBELL","tags":["dumbbell hip thrust","hip thrust mit kurzhantel"],"media":[{"id":"dumbbell-hip-thrust-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1642/a81ad922-caf5-47f8-99b4-640cb0717436.webp","caption":"Dumbbell Hip Thrust","attribution":"wger.de · AlucardEvil40","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Hip Thrust mit Kurzhantel","description":"Übung (Kurzhantel) für den Po, unterstützt von Oberschenkelvorderseite.","instructions":["Bei dieser Übung sitzt du auf dem Boden, eine Kurzhantel ruht auf deiner Hüfte, und du drückst die Hüfte nach oben, während du die Gesäßmuskulatur anspannst. Es ist eine hervorragende Übung, um die Gesäßmuskulatur zu kräftigen und die Hüftbeweglichkeit zu verbessern."]}},{"id":"ex-dumbbell-incline-shoulder-raise","slug":"dumbbell-incline-shoulder-raise","name":"Dumbbell Incline Shoulder Raise","description":"Dumbbell exercise for the shoulders, with triceps assisting.","instructions":["Sit on an Incline Bench while holding a dumbbell on each hand on top of your thighs.","Lift your legs up to kick the weights to your shoulders and lean back. Position the dumbbells above your shoulders with your arms extended. The arms should be perpendicular to the floor with your palms facing forward and knuckles pointing towards the ceiling. This will be your starting position.","While keeping the arms straight and locked, lift the dumbbells by raising the shoulders from the bench as you breathe out.","Bring back the dumbbells to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"DUMBBELL","tags":["dumbbell incline shoulder raise"],"media":[{"id":"dumbbell-incline-shoulder-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Incline_Shoulder_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-incline-shoulder-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Incline_Shoulder_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-dumbbell-lunges-walking","slug":"dumbbell-lunges-walking","name":"Dumbbell Lunges Walking","description":"Dumbbell exercise for the quadriceps, with glutes assisting.","instructions":["Starting Position: Stand with feet hip-width apart and hands either on your hips or holding dumbbells at your sides.","The Stride: Take a wide step forward with your right leg.","The Descent: Lower your hips until both knees are bent at approximately 90-degree angles.","The Transition: Drive through your front heel to stand up, bringing your back foot forward to step directly into the next lunge."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES"],"equipment":"DUMBBELL","tags":["dumbbell lunges walking","ausfallschritte im gehen"],"media":[{"id":"dumbbell-lunges-walking-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/113/Walking-lunges-1.png","caption":"Dumbbell Lunges Walking","attribution":"wger.de · Everkinetic","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Ausfallschritte im Gehen","description":"Übung (Kurzhantel) für die Oberschenkelvorderseite, unterstützt von Po.","instructions":["Ausgangsposition: Stelle dich hüftbreit hin, die Hände entweder in der Hüfte oder mit Kurzhanteln seitlich am Körper.","Der Schritt: Mache mit deinem rechten Bein einen weiten Schritt nach vorne.","Die Abwärtsbewegung: Senke deine Hüfte, bis beide Knie etwa im 90-Grad-Winkel gebeugt sind.","Der Übergang: Drücke dich über die vordere Ferse nach oben und führe den hinteren Fuß direkt nach vorne in den nächsten Ausfallschritt."]}},{"id":"ex-dumbbell-lying-one-arm-rear-lateral-raise","slug":"dumbbell-lying-one-arm-rear-lateral-raise","name":"Dumbbell Lying One-Arm Rear Lateral Raise","description":"Dumbbell exercise for the shoulders, with back assisting.","instructions":["While holding a dumbbell in one hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench. The other hand can be used to hold to the leg of the bench for stability.","Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position.","Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhale. Tip: Maintain your arm perpendicular to the torso while keeping your arm extended throughout the movement. Also, keep the contraction at the top for a second.","Slowly lower the dumbbell to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"DUMBBELL","tags":["dumbbell lying one-arm rear lateral raise"],"media":[{"id":"dumbbell-lying-one-arm-rear-lateral-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-lying-one-arm-rear-lateral-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern, unterstützt von Rücken.","instructions":null}},{"id":"ex-dumbbell-lying-pronation","slug":"dumbbell-lying-pronation","name":"Dumbbell Lying Pronation","description":"Dumbbell exercise for the forearms.","instructions":["Lie on a flat bench face down with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.","Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.","Now raise the upper arm so that the forearm is perpendicular to the floor and the upper arm is perpendicular to your torso. Tip: The upper arm should be parallel to the floor and also creating a 90-degree angle with your torso. This will be your starting position.","As you breathe out, externally rotate your forearm so that the dumbbell is lifted forward as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is parallel to the floor. At this point you will hold the contraction for a second.","As you breathe in, slowly go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["dumbbell lying pronation"],"media":[{"id":"dumbbell-lying-pronation-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lying_Pronation/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-lying-pronation-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lying_Pronation/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Unterarme.","instructions":null}},{"id":"ex-dumbbell-lying-rear-lateral-raise","slug":"dumbbell-lying-rear-lateral-raise","name":"Dumbbell Lying Rear Lateral Raise","description":"Dumbbell exercise for the shoulders.","instructions":["While holding a dumbbell in each hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench.","Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position.","Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms perpendicular to the torso while keeping them extended throughout the movement. Also, keep the contraction at the top for a second.","Slowly lower the dumbbells to the starting position as you inhale.","Repeat for the recommended amount of repetitions and then switch to the other arm."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["dumbbell lying rear lateral raise"],"media":[{"id":"dumbbell-lying-rear-lateral-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lying_Rear_Lateral_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-lying-rear-lateral-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lying_Rear_Lateral_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern.","instructions":null}},{"id":"ex-dumbbell-lying-supination","slug":"dumbbell-lying-supination","name":"Dumbbell Lying Supination","description":"Dumbbell exercise for the forearms.","instructions":["Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.","Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.","Now raise the upper arm so that the forearm is parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.","As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.","As you breathe in, slowly go back to the starting position.","Repeat for the recommended amount of repetitions and then switch to the other arm."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["dumbbell lying supination"],"media":[{"id":"dumbbell-lying-supination-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lying_Supination/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-lying-supination-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lying_Supination/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Unterarme.","instructions":null}},{"id":"ex-dumbbell-one-arm-shoulder-press","slug":"dumbbell-one-arm-shoulder-press","name":"Dumbbell One-Arm Shoulder Press","description":"Dumbbell exercise for the shoulders, with triceps assisting.","instructions":["Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.","Clean the dumbbell up to bring it to shoulder height. The other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface.","Rotate the wrist so that the palm of your hand is facing forward. This is your starting position.","As you exhale, push the dumbbell up until your arm is fully extended.","After a second pause, slowly come down back to the starting position as you inhale.","Repeat for the recommended amount of repetitions and then switch arms."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"DUMBBELL","tags":["dumbbell one-arm shoulder press"],"media":[{"id":"dumbbell-one-arm-shoulder-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_One-Arm_Shoulder_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-one-arm-shoulder-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_One-Arm_Shoulder_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-dumbbell-one-arm-upright-row","slug":"dumbbell-one-arm-upright-row","name":"Dumbbell One-Arm Upright Row","description":"Dumbbell exercise for the shoulders, with biceps, back assisting.","instructions":["Grab a dumbbell and stand up straight with your arm extended in front of you with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be resting on top of your thigh with the palm of your hands facing your thighs.","Keep the other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface. This will be your starting position.","Use your side shoulders to lift the dumbbell as you exhale. The dumbbell should be close to the body as you move it up. Continue to lift it until the dumbbell is nearly in line with your chin. Tip: Your elbows should drive the motion. As you lift the dumbbell, your elbow should always be higher than your forearm. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the dumbbell back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions and switch arms."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BICEPS","BACK"],"equipment":"DUMBBELL","tags":["dumbbell one-arm upright row"],"media":[{"id":"dumbbell-one-arm-upright-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_One-Arm_Upright_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-one-arm-upright-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_One-Arm_Upright_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern, unterstützt von Bizeps, Rücken.","instructions":null}},{"id":"ex-dumbbell-prone-incline-curl","slug":"dumbbell-prone-incline-curl","name":"Dumbbell Prone Incline Curl","description":"Dumbbell exercise for the biceps.","instructions":["Grab a dumbbell on each hand and lie face down on an incline bench with your shoulders near top of the incline. Your knees can rest on the seat or your legs can be straddled to the sides (my preferred way).","Let your arms extend and hang naturally in front of you so that they are perpendicular to the floor.","Now keep your elbows in by your side and face the palms forward. This will be your starting position.","Raise the dumbbells by contracting the biceps until your arms are fully flexed. Exhale as you perform this portion of the movement and ensure that only the forearms move. The upper arms should remain stationary at all times.","Lower the dumbbells until your arms are fully extended.","Repeat for the recommended amount of times."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["dumbbell prone incline curl"],"media":[{"id":"dumbbell-prone-incline-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Prone_Incline_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-prone-incline-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Prone_Incline_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps.","instructions":null}},{"id":"ex-dumbbell-raise","slug":"dumbbell-raise","name":"Dumbbell Raise","description":"Dumbbell exercise for the shoulders, with biceps assisting.","instructions":["Grab a dumbbell in each arm and stand up straight with your arms extended by your sides with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be next to your thighs with the palm of your hands facing back.","Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be to the side of the body as you move them up. Continue to lift it until the dumbbells are nearly in line with your chin. Tip: Your elbows should drive the motion. As you lift the dumbbell, your elbow should always be higher than your forearm. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the dumbbells back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BICEPS"],"equipment":"DUMBBELL","tags":["dumbbell raise"],"media":[{"id":"dumbbell-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern, unterstützt von Bizeps.","instructions":null}},{"id":"ex-dumbbell-rear-lunge","slug":"dumbbell-rear-lunge","name":"Dumbbell Rear Lunge","description":"Dumbbell exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.","Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Tip: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground. Keep the torso upright during the lunge; flexible hip flexors are important. A long lunge emphasizes the Gluteus Maximus; a short lunge emphasizes Quadriceps.","Push up and go back to the starting position as you exhale. Tip: Use the ball of your feet to push in order to accentuate the quadriceps. To focus on the glutes, press with your heels.","Now repeat with the opposite leg."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"DUMBBELL","tags":["dumbbell rear lunge","rückwärtiger ausfallschritt mit kurzhanteln"],"media":[{"id":"dumbbell-rear-lunge-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Rear_Lunge/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-rear-lunge-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Rear_Lunge/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Rückwärtiger Ausfallschritt mit Kurzhanteln","description":"Übung (Kurzhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":["Bei dieser Übung hältst du in jeder Hand eine Kurzhantel und trittst rückwärts in einen Ausfallschritt, um anschließend wieder in den Stand zurückzukehren. Sie trainiert vor allem die Gesäßmuskulatur, die hintere Oberschenkelmuskulatur und die vordere Oberschenkelmuskulatur (Quadrizeps)."]}},{"id":"ex-dumbbell-romanian-deadlift","slug":"dumbbell-romanian-deadlift","name":"Dumbbell Romanian Deadlift","description":"Dumbbell exercise for the hamstrings, with glutes assisting.","instructions":["This exercise involves holding a dumbbell in each hand and bending forward at the hips while keeping the back straight, then returning to a standing position. It primarily targets the hamstrings and glutes."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES"],"equipment":"DUMBBELL","tags":["dumbbell romanian deadlift","rumänisches kreuzheben mit kurzhanteln"],"media":[{"id":"dumbbell-romanian-deadlift-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1652/0306c8c0-70cc-45d4-92de-6fa72ceaa834.webp","caption":"Dumbbell Romanian Deadlift","attribution":"wger.de · AlucardEvil40","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Rumänisches Kreuzheben mit Kurzhanteln","description":"Übung (Kurzhantel) für die Oberschenkelrückseite, unterstützt von Po.","instructions":["Bei dieser Übung hältst du in jeder Hand eine Kurzhantel und beugst dich aus der Hüfte nach vorne, während du den Rücken gerade hältst, um anschließend wieder in den aufrechten Stand zurückzukehren. Sie trainiert vor allem die hintere Oberschenkelmuskulatur und die Gesäßmuskulatur."]}},{"id":"ex-dumbbell-scaption","slug":"dumbbell-scaption","name":"Dumbbell Scaption","description":"Dumbbell exercise for the shoulders, with back assisting.","instructions":["This corrective exercise strengthens the muscles that stabilize your shoulder blade. Hold a light weight in each hand, hanging at your sides. Your thumbs should pointing up.","Begin the movement raising your arms out in front of you, about 30 degrees off center. Your arms should be fully extended as you perform the movement.","Continue until your arms are parallel to the ground, and then return to the starting position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"DUMBBELL","tags":["dumbbell scaption","kurzhantel-scaption"],"media":[{"id":"dumbbell-scaption-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Scaption/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-scaption-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Scaption/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Kurzhantel-Scaption","description":"Übung (Kurzhantel) für die Schultern, unterstützt von Rücken.","instructions":["Ausgangsposition:","Stelle dich aufrecht hin, mit den Füßen schulterbreit auseinander.","Halte in jeder Hand eine Kurzhantel mit neutralem Griff (Handflächen zeigen zueinander).","Halte die Ellbogen leicht gebeugt, die Schultern entspannt und die Schulterblätter nach hinten gezogen.","Ausführung:","Hebe die Kurzhanteln langsam nach vorn und leicht zur Seite, in einem Winkel von etwa 30–45° zu deinem Körper (zwischen einem Frontheben und einem Seitheben).","Hebe sie an, bis deine Arme etwa auf Schulterhöhe sind (gehe nicht über den Kopf).","Halte am höchsten Punkt eine Sekunde inne und spüre die Aktivierung in deinen Schultern und den Schulterblattstabilisatoren."]}},{"id":"ex-dumbbell-seated-box-jump","slug":"dumbbell-seated-box-jump","name":"Dumbbell Seated Box Jump","description":"Dumbbell exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Position a box a couple feet to the side of a bench. Hold a dumbbell to your chest with both hands and seat yourself on the bench facing the box. This will be your starting position.","Plant your feet firmly on the ground as you lean forward, extending through the hips and knees to jump up and forward.","Land on the box with both feet, absorbing the impact by allowing the hips and knees to bend.","Step down and return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"DUMBBELL","tags":["dumbbell seated box jump"],"media":[{"id":"dumbbell-seated-box-jump-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Seated_Box_Jump/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-seated-box-jump-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Seated_Box_Jump/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-dumbbell-seated-one-leg-calf-raise","slug":"dumbbell-seated-one-leg-calf-raise","name":"Dumbbell Seated One-Leg Calf Raise","description":"Dumbbell exercise for the calves.","instructions":["Place a block on the floor about 12 inches from a flat bench.","Sit on a flat bench and place a dumbbell on your upper left thigh about 3 inches above your knee.","Now place the ball of your left foot on the block. This will be your starting position.","Raise your toes up as high as possible as you exhale and you contract your calf muscle. Hold the contraction for a second.","Slowly return to the starting position, stretching as far down as possible.","Repeat for your prescribed number of repetitions and then repeat with the right leg."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["dumbbell seated one-leg calf raise"],"media":[{"id":"dumbbell-seated-one-leg-calf-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Seated_One-Leg_Calf_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-seated-one-leg-calf-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Seated_One-Leg_Calf_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Waden.","instructions":null}},{"id":"ex-dumbbell-shoulder-rotations","slug":"dumbbell-shoulder-rotations","name":"Dumbbell Shoulder Rotations","description":"Dumbbell exercise for the shoulders.","instructions":["Dumbbell shoulder rotations are designed to strengthen the rotator cuff muscles and improve shoulder stability and mobility.","External Rotation: Hold a dumbbell in one hand, keeping your elbow bent at 90 degrees and close to your body. Rotate your forearm outward, away from your body, keeping your elbow stationary. Slowly return to the starting position.","Internal Rotation: Hold a dumbbell in one hand, keeping your elbow bent at 90 degrees and close to your body. Rotate your forearm inward, toward your body, and slowly return to the starting position. Perform the exercise with controlled movements to avoid strain."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["dumbbell shoulder rotations","schulterrotationen mit kurzhantel"],"media":[],"source":"wger","de":{"name":"Schulterrotationen mit Kurzhantel","description":"Übung (Kurzhantel) für die Schultern.","instructions":["Schulterrotationen mit Kurzhantel sind darauf ausgelegt, die Muskulatur der Rotatorenmanschette zu stärken sowie die Stabilität und Mobilität der Schulter zu verbessern.","Außenrotation: Halte eine Kurzhantel in einer Hand, den Ellbogen im 90-Grad-Winkel gebeugt und nah am Körper. Rotiere deinen Unterarm nach außen, weg von deinem Körper, und halte dabei deinen Ellbogen ruhig. Kehre langsam in die Startposition zurück.","Innenrotation: Halte eine Kurzhantel in einer Hand, den Ellbogen im 90-Grad-Winkel gebeugt und nah am Körper. Rotiere deinen Unterarm nach innen, zu deinem Körper hin, und kehre langsam in die Startposition zurück. Führe die Übung mit kontrollierten Bewegungen aus, um Verletzungen zu vermeiden."]}},{"id":"ex-dumbbell-side-bend","slug":"dumbbell-side-bend","name":"Dumbbell Side Bend","description":"Dumbbell exercise for the core.","instructions":["Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist. Your feet should be placed at shoulder width. This will be your starting position.","While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.","Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.","Repeat for the recommended amount of repetitions and then change hands."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["dumbbell side bend","seitneigung mit kurzhantel"],"media":[{"id":"dumbbell-side-bend-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Side_Bend/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-side-bend-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Side_Bend/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Seitneigung mit Kurzhantel","description":"Übung (Kurzhantel) für den Rumpf.","instructions":["Bei dieser Übung hältst du eine Kurzhantel in einer Hand und neigst dich zur Seite, um die seitliche Bauchmuskulatur (Obliques) zu trainieren. Sie kann im Stehen oder im Sitzen ausgeführt werden und wird häufig zur Kräftigung des Rumpfes eingesetzt."]}},{"id":"ex-dumbbell-side-squat","slug":"dumbbell-side-squat","name":"Dumbbell Side Squat","description":"Bodyweight exercise for the glutes, with quadriceps, hamstrings assisting.","instructions":["This exercise involves holding a dumbbell in one hand and performing a squat while stepping to the side. It targets the legs, glutes, and core muscles."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["QUADRICEPS","HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["dumbbell side squat","seitliche kniebeuge mit kurzhantel"],"media":[{"id":"dumbbell-side-squat-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1653/c10c4e17-1e14-4cf9-930b-cc3a614f15dd.webp","caption":"Dumbbell Side Squat","attribution":"wger.de · AlucardEvil40","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Seitliche Kniebeuge mit Kurzhantel","description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelvorderseite, Oberschenkelrückseite.","instructions":["Bei dieser Übung hältst du eine Kurzhantel in einer Hand und führst eine Kniebeuge aus, während du zur Seite trittst. Sie trainiert die Beine, die Gesäßmuskulatur und die Rumpfmuskulatur."]}},{"id":"ex-dumbbell-single-leg-hip-thrust","slug":"dumbbell-single-leg-hip-thrust","name":"Dumbbell Single-leg Hip Thrust","description":"Dumbbell exercise for the glutes, with hamstrings, quadriceps assisting.","instructions":["The single-leg hip thrust is performed by placing your upper back on a weight bench, raising one leg, and extending the hip of the other leg to achieve an isolated contraction of the glute.","By working each side separately, you can fully isolate your glutes unilaterally, providing maximal training stimulus."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["HAMSTRINGS","QUADRICEPS"],"equipment":"DUMBBELL","tags":["dumbbell single-leg hip thrust","einbeiniger hip thrust mit kurzhantel"],"media":[],"source":"wger","de":{"name":"Einbeiniger Hip Thrust mit Kurzhantel","description":"Übung (Kurzhantel) für den Po, unterstützt von Oberschenkelrückseite, Oberschenkelvorderseite.","instructions":["Der einbeinige Hip Thrust wird ausgeführt, indem du deinen oberen Rücken auf eine Hantelbank legst, ein Bein anhebst und die Hüfte des anderen Beins streckst, um eine isolierte Kontraktion der Gesäßmuskulatur zu erreichen.","Indem du jede Seite einzeln trainierst, kannst du deine Gesäßmuskulatur unilateral vollständig isolieren und so einen maximalen Trainingsreiz setzen."]}},{"id":"ex-dumbbell-snatch","slug":"dumbbell-snatch","name":"dumbbell snatch","description":"Dumbbell exercise for the hamstrings, with glutes, quadriceps assisting.","instructions":["Key Steps to Execute Correctly:","Setup: Place the dumbbell between your feet, with your shoulders above your hips, chest up, and back flat.","The Pull: Explosively extend your hips, knees, and ankles (triple extension) to drive the dumbbell upward, keeping your elbow high and the dumbbell close to your body.","The Catch: Quickly flex your hips and knees to drop under the dumbbell and receive it overhead with your arm locked in position, landing in a half-squat stance.","Common Mistakes: Using your arms too much to lift the weight instead of your legs, having a low elbow during the pull phase, and misaligning your shoulder, elbow, and wrist in the final position. For beginners, it’s recommended to start with light loads, focus on technique, and perform 3 to 5 sets of 3 to 5 reps per arm."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","QUADRICEPS"],"equipment":"DUMBBELL","tags":["dumbbell snatch","kurzhantel-reißen (dumbbell snatch)"],"media":[{"id":"dumbbell-snatch-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1947/4201a9c0-f9e4-48ca-80f1-b46c7ffe5640.webp","caption":"dumbbell snatch","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Kurzhantel-Reißen (Dumbbell Snatch)","description":"Übung (Kurzhantel) für die Oberschenkelrückseite, unterstützt von Po, Oberschenkelvorderseite.","instructions":["Wichtige Schritte zur korrekten Ausführung:","Aufbau: Lege die Kurzhantel zwischen deine Füße, mit den Schultern über den Hüften, der Brust aufgerichtet und flachem Rücken.","Der Zug: Strecke explosiv deine Hüften, Knie und Sprunggelenke (Dreifachstreckung), um die Kurzhantel nach oben zu treiben, wobei du den Ellenbogen hoch und die Kurzhantel nah am Körper hältst.","Das Auffangen: Beuge schnell deine Hüften und Knie, um unter die Kurzhantel zu gehen und sie mit fixiertem Arm über dem Kopf aufzunehmen, wobei du in einer halben Kniebeuge landest.","Häufige Fehler: Das Gewicht zu sehr mit den Armen statt mit den Beinen anzuheben, einen tiefen Ellenbogen in der Zugphase zu haben und Schulter, Ellenbogen und Handgelenk in der Endposition nicht auszurichten. Anfängern wird empfohlen, mit leichten Gewichten zu beginnen, sich auf die Technik zu konzentrieren und 3 bis 5 Sätze mit 3 bis 5 Wiederholungen pro Arm auszuführen."]}},{"id":"ex-dumbbell-squat","slug":"dumbbell-squat","name":"Dumbbell Squat","description":"Dumbbell exercise for the quadriceps, with calves, glutes, hamstrings, back assisting.","instructions":["Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).","Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.","Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until your thighs are parallel to the floor. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise your torso as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","BACK"],"equipment":"DUMBBELL","tags":["dumbbell squat"],"media":[{"id":"dumbbell-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-dumbbell-squat-to-a-bench","slug":"dumbbell-squat-to-a-bench","name":"Dumbbell Squat To A Bench","description":"Dumbbell exercise for the quadriceps, with calves, glutes, hamstrings, back assisting.","instructions":["Stand up straight with a flat bench behind you while holding a dumbbell on each hand (palms facing the side of your legs).","Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.","Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","BACK"],"equipment":"DUMBBELL","tags":["dumbbell squat to a bench"],"media":[{"id":"dumbbell-squat-to-a-bench-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Squat_To_A_Bench/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-squat-to-a-bench-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Squat_To_A_Bench/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-dumbbell-step-ups","slug":"dumbbell-step-ups","name":"Dumbbell Step Ups","description":"Dumbbell exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).","Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.","Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.","Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"DUMBBELL","tags":["dumbbell step ups"],"media":[{"id":"dumbbell-step-ups-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Step_Ups/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-step-ups-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Step_Ups/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-dumbbell-sumo-deadlift","slug":"dumbbell-sumo-deadlift","name":"Dumbbell sumo deadlift","description":"Dumbbell exercise for the hamstrings, with glutes, quadriceps, back assisting.","instructions":["Lower your dumbbell to the ground between your legs. Assume a wide stance and with a straight back squat down. With the dumbbell standing upright, grip it by the top of the ‘head’ (picture 1).Keeping your chest up and core braced, push the floor away, driving back upwards to a standing position (picture 2). Repeat. If you can easily achieve 20-30 reps, use two dumbbells."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","QUADRICEPS","BACK"],"equipment":"DUMBBELL","tags":["dumbbell sumo deadlift","sumo-kreuzheben mit kurzhantel"],"media":[{"id":"dumbbell-sumo-deadlift-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1088/9f66b288-ce8f-4154-ba80-78fee267263c.jpg","caption":"Dumbbell sumo deadlift","attribution":"wger.de · philip","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Sumo-Kreuzheben mit Kurzhantel","description":"Übung (Kurzhantel) für die Oberschenkelrückseite, unterstützt von Po, Oberschenkelvorderseite, Rücken.","instructions":["Senke deine Kurzhantel zwischen deinen Beinen zum Boden. Nimm eine breite Standposition ein und gehe mit geradem Rücken in die Kniebeuge. Greife die aufrecht stehende Kurzhantel an der Oberseite des \"Kopfes\" (Bild 1). Halte deine Brust aufrecht und deinen Rumpf angespannt, drücke dich vom Boden ab und treibe dich wieder nach oben in den Stand (Bild 2). Wiederhole. Wenn du problemlos 20-30 Wiederholungen schaffst, verwende zwei Kurzhanteln."]}},{"id":"ex-dumbbell-thruster","slug":"dumbbell-thruster","name":"Dumbbell Thruster","description":"Dumbbell exercise for the hamstrings, with glutes, quadriceps, shoulders assisting.","instructions":["Start with the dumbbells resting on your shoulders and squat down. Push","into standing and raise the dumbbells into an overhead position. Bring","the dumbbells back to your shoulders and repeat."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","QUADRICEPS","SHOULDERS"],"equipment":"DUMBBELL","tags":["dumbbell thruster","kurzhantel-thruster"],"media":[],"source":"wger","de":{"name":"Kurzhantel-Thruster","description":"Übung (Kurzhantel) für die Oberschenkelrückseite, unterstützt von Po, Oberschenkelvorderseite, Schultern.","instructions":["Beginne mit den Kurzhanteln auf deinen Schultern und gehe in die Kniebeuge. Drücke dich","in den Stand hoch und hebe die Kurzhanteln in eine Position über dem Kopf. Bringe","die Kurzhanteln zurück zu deinen Schultern und wiederhole die Bewegung."]}},{"id":"ex-dumbbell-tricep-extension-pronated-grip","slug":"dumbbell-tricep-extension-pronated-grip","name":"Dumbbell Tricep Extension -Pronated Grip","description":"Dumbbell exercise for the triceps.","instructions":["Lie down on a flat bench holding two dumbbells directly above your shoulders. Your arms should be fully extended and form a 90 degree angle from your torso and the floor.","The palms of your hands should be facing forward, and your elbows should be tucked in. This will be your starting position.","Now, inhale and slowly lower the dumbbells until they are near your ears. Be sure to keep your upper arms stationary and your elbows tucked in.","Then, exhale and use your triceps to return the weight to the starting position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["dumbbell tricep extension -pronated grip"],"media":[{"id":"dumbbell-tricep-extension-pronated-grip-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Tricep_Extension_-Pronated_Grip/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dumbbell-tricep-extension-pronated-grip-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Tricep_Extension_-Pronated_Grip/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Trizeps.","instructions":null}},{"id":"ex-dumbbell-underhand-dead-row","slug":"dumbbell-underhand-dead-row","name":"Dumbbell Underhand Dead Row","description":"Dumbbell exercise for the biceps, with back assisting.","instructions":["The Dumbbell Underhand Dead Row will involve the back, which means you can try a bit heavier weight. The catch is that you need to be able to control the weight for all the reps.","Start by holding a pair of dumbbells with your feet shoulder-wide apart and your knees slightly bent.","Hinge at your hips to lower your torse forward until it's almost parallel to the floor, keeping your back flat and maintaining a slight bend in your knees.","Exhale as you row the dumbbells to your sides up to chest height, leading with your elbows until your upper arms are just past parallel to the floor and the dumbbells are at ribcage level.","Slowly lower to the starting position and repeat. Keep your back flat all the time."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["BACK"],"equipment":"DUMBBELL","tags":["dumbbell underhand dead row","kurzhantel-rudern im untergriff aus dem dead stop"],"media":[],"source":"wger","de":{"name":"Kurzhantel-Rudern im Untergriff aus dem Dead Stop","description":"Übung (Kurzhantel) für den Bizeps, unterstützt von Rücken.","instructions":["Das Kurzhantel-Rudern im Untergriff aus dem Dead Stop beansprucht den Rücken, das heißt, du kannst etwas schwereres Gewicht ausprobieren. Der Haken ist, dass du das Gewicht über alle Wiederholungen kontrollieren können musst.","Beginne, indem du ein Paar Kurzhanteln hältst, die Füße schulterbreit auseinander und die Knie leicht gebeugt.","Beuge dich in der Hüfte nach vorne, um deinen Oberkörper abzusenken, bis er fast parallel zum Boden ist, halte dabei den Rücken gerade und die Knie leicht gebeugt.","Atme aus, während du die Kurzhanteln seitlich bis auf Brusthöhe ruderst, dabei führen die Ellbogen, bis deine Oberarme knapp über parallel zum Boden sind und die Kurzhanteln sich auf Höhe des Brustkorbs befinden.","Senke die Kurzhanteln langsam in die Ausgangsposition ab und wiederhole. Halte den Rücken die ganze Zeit gerade."]}},{"id":"ex-dumbell-tate-press","slug":"dumbell-tate-press","name":"Dumbell Tate Press","description":"Dumbbell exercise for the triceps, with shoulders, chest assisting.","instructions":["Set Up: Lie flat with a dumbbell in each hand. Extend your arms straight up over your chest as if you were at the top of a dumbbell bench press","Starting Position: Position the dumbbells so they are touching or very close together with a pronated grip (palms facing your feet and thumbs facing each other)","Lowering: Without moving your upper arms or shoulders, bend your elbows and flare them outward to the sides. Lower the inner ends of the dumbbells toward the center of your chest","Touch and Pause: Gently touch the dumbbells to your chest. Do not rest the weight on your body; maintain constant tension in your triceps","Press: Forcefully extend your elbows to return the dumbbells to the starting position. Focus on \"pushing your pinkies toward the sky\" to maximize triceps engagement","https://www.youtube.com/watch?v=IgSjoXbpy1M&t=2"],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["SHOULDERS","CHEST"],"equipment":"DUMBBELL","tags":["dumbell tate press","tate press mit kurzhanteln"],"media":[],"source":"wger","de":{"name":"Tate Press mit Kurzhanteln","description":"Übung (Kurzhantel) für den Trizeps, unterstützt von Schultern, Brust.","instructions":["Aufbau: Lege dich flach hin, mit einer Kurzhantel in jeder Hand. Strecke deine Arme gerade über deiner Brust nach oben, als wärst du am obersten Punkt eines Kurzhantel-Bankdrückens.","Ausgangsposition: Positioniere die Kurzhanteln so, dass sie sich berühren oder dicht beieinander sind, mit einem Obergriff (Handflächen zeigen zu deinen Füßen und Daumen zueinander).","Absenken: Ohne deine Oberarme oder Schultern zu bewegen, beugst du die Ellenbogen und spreizt sie seitlich nach außen ab. Senke die inneren Enden der Kurzhanteln zur Mitte deiner Brust.","Berühren und Pause: Berühre mit den Kurzhanteln sanft deine Brust. Lege das Gewicht nicht auf deinem Körper ab; halte die Spannung im Trizeps konstant.","Drücken: Strecke deine Ellenbogen kraftvoll, um die Kurzhanteln in die Ausgangsposition zurückzubringen. Konzentriere dich darauf, „die kleinen Finger zum Himmel zu drücken“, um die Beanspruchung des Trizeps zu maximieren.","https://www.youtube.com/watch?v=IgSjoXbpy1M&t=2"]}},{"id":"ex-dynamic-back-stretch","slug":"dynamic-back-stretch","name":"Dynamic Back Stretch","description":"Equipment-free exercise for the back.","instructions":["Stand with your feet shoulder width apart. This will be your starting position.","Keeping your arms straight, swing them straight up in front of you 5-10 times, increasing the range of motion each time until your arms are above your head."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"NONE","tags":["dynamic back stretch"],"media":[{"id":"dynamic-back-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dynamic_Back_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dynamic-back-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dynamic_Back_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Rücken.","instructions":null}},{"id":"ex-dynamic-chest-stretch","slug":"dynamic-chest-stretch","name":"Dynamic Chest Stretch","description":"Equipment-free exercise for the chest, with back assisting.","instructions":["Stand with your hands together, arms extended directly in front of you. This will be your starting position.","Keeping your arms straight, quickly move your arms back as far as possible and back in again, similar to an exaggerated clapping motion. Repeat 5-10 times, increasing speed as you do so."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["BACK"],"equipment":"NONE","tags":["dynamic chest stretch"],"media":[{"id":"dynamic-chest-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dynamic_Chest_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"dynamic-chest-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dynamic_Chest_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Brust, unterstützt von Rücken.","instructions":null}},{"id":"ex-dynamic-planche","slug":"dynamic-planche","name":"Dynamic Planche","description":"Bodyweight exercise for the core.","instructions":["Start in a plank position, with your hands directly under your shoulders and your feet hip-width apart.","Engage your core to keep your body in a straight line from head to toe.","From this position, bend your knees slightly and jump with both feet inward, bringing them as close to your core as possible","As soon as your feet touch the ground, push off forcefully to jump again and return to the starting plank position.","Continue repeating this jumping motion, maintaining control and core stability throughout the exercise.","Make sure to keep your breathing steady while jumping, breathing deeply and controlling your breathing.","Keep your gaze fixed on the ground to maintain proper spinal alignment.","Repeat the jumps for the desired length of time or the number of repetitions recommended for your workout program."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["dynamic planche","dynamische planche"],"media":[],"source":"wger","de":{"name":"Dynamische Planche","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Beginne in einer Plank-Position, mit deinen Händen direkt unter deinen Schultern und deinen Füßen hüftbreit auseinander.","Spanne deine Rumpfmuskulatur an, um deinen Körper in einer geraden Linie von Kopf bis Fuß zu halten.","Beuge aus dieser Position deine Knie leicht und springe mit beiden Füßen nach innen, sodass du sie so nah wie möglich an deinen Rumpf bringst.","Sobald deine Füße den Boden berühren, drücke dich kraftvoll ab, um erneut zu springen und in die Ausgangs-Plank-Position zurückzukehren.","Wiederhole diese Sprungbewegung weiter und behalte während der gesamten Übung Kontrolle und Rumpfstabilität bei.","Achte darauf, deine Atmung beim Springen gleichmäßig zu halten, atme tief und kontrolliere deine Atmung.","Halte deinen Blick auf den Boden gerichtet, um eine korrekte Ausrichtung der Wirbelsäule zu wahren.","Wiederhole die Sprünge für die gewünschte Dauer oder die für dein Trainingsprogramm empfohlene Anzahl an Wiederholungen."]}},{"id":"ex-dynamic-side-hold","slug":"dynamic-side-hold","name":"Dynamic side hold","description":"Kettlebell exercise for the core.","instructions":["Sling a rubber band on a kettlebell and lift the kettlebell by the rubber band. Let it hang by your side and stand on one leg, switch leg while continuing hold. Repeat with other hand"],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"KETTLEBELL","tags":["dynamic side hold","dynamisches seitliches halten"],"media":[],"source":"wger","de":{"name":"Dynamisches seitliches Halten","description":"Übung (Kettlebell) für den Rumpf.","instructions":["Lege ein Gummiband um eine Kettlebell und hebe die Kettlebell am Gummiband an. Lass sie an deiner Seite hängen und stelle dich auf ein Bein, wechsle dann das Bein, während du sie weiter hältst. Wiederhole das Ganze mit der anderen Hand."]}},{"id":"ex-dynamic-side-plank","slug":"dynamic-side-plank","name":"Dynamic side plank","description":"Bodyweight exercise for the core.","instructions":["The dynamic side plank involves positioning yourself on your side, supported on one elbow and the side of your foot, then dipping your hips up and down while keeping your body in a straight line."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["dynamic side plank","dynamischer seitstütz"],"media":[],"source":"wger","de":{"name":"Dynamischer Seitstütz","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Der dynamische Seitstütz beinhaltet, dich auf die Seite zu legen, gestützt auf einen Ellbogen und die Außenseite des Fußes, und dann die Hüfte auf und ab zu kippen, während du eine gerade Körperlinie hältst."]}},{"id":"ex-elbow-circles","slug":"elbow-circles","name":"Elbow Circles","description":"Equipment-free exercise for the shoulders, with back assisting.","instructions":["Sit or stand with your feet slightly apart.","Place your hands on your shoulders with your elbows at shoulder level and pointing out.","Slowly make a circle with your elbows. Breathe out as you start the circle and breathe in as you complete the circle."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"NONE","tags":["elbow circles"],"media":[{"id":"elbow-circles-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Elbow_Circles/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"elbow-circles-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Elbow_Circles/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Schultern, unterstützt von Rücken.","instructions":null}},{"id":"ex-elbow-to-knee","slug":"elbow-to-knee","name":"Elbow to Knee","description":"Bodyweight exercise for the core.","instructions":["Lie on the floor, crossing your right leg across your bent left knee. Clasp your hands behind your head, beginning with your shoulder blades on the ground. This will be your starting position.","Perform the motion by flexing the spine and rotating your torso to bring the left elbow to the right knee.","Return to the starting position and repeat the movement for the desired number of repetitions before switching sides."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["elbow to knee"],"media":[{"id":"elbow-to-knee-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Elbow_to_Knee/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"elbow-to-knee-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Elbow_to_Knee/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-elbows-back","slug":"elbows-back","name":"Elbows Back","description":"Equipment-free exercise for the chest, with shoulders assisting.","instructions":["Stand up straight.","Place both hands on your lower back, fingers pointing downward and elbows out.","Then gently pull your elbows back aiming to touch them together."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS"],"equipment":"NONE","tags":["elbows back"],"media":[{"id":"elbows-back-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Elbows_Back/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"elbows-back-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Elbows_Back/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Brust, unterstützt von Schultern.","instructions":null}},{"id":"ex-elevated-back-lunge","slug":"elevated-back-lunge","name":"Elevated Back Lunge","description":"Barbell exercise for the quadriceps, with glutes, hamstrings assisting.","instructions":["Position a bar onto a rack at shoulder height loaded to an appropriate weight. Place a short, raised platform behind you.","Rack the bar onto your upper back, keeping your back arched and tight. Step onto your raised platform with both feet. This will be your starting position.","Begin by stepping backwards with one leg. Descend by flexing your hips and knees until your knee touches the floor.","Pause, and extend through the hips and knees to rise up, returning all the way to the starting position before alternating."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","HAMSTRINGS"],"equipment":"BARBELL","tags":["elevated back lunge"],"media":[{"id":"elevated-back-lunge-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Elevated_Back_Lunge/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"elevated-back-lunge-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Elevated_Back_Lunge/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-elevated-cable-rows","slug":"elevated-cable-rows","name":"Elevated Cable Rows","description":"Cable exercise for the back.","instructions":["Get a platform of some sort (it can be an aerobics or calf raise platform) that is around 4-6 inches in height.","Place it on the seat of the cable row machine.","Sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.","Lean over as you keep the natural alignment of your back and grab the V-bar handles.","With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.","Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["elevated cable rows"],"media":[{"id":"elevated-cable-rows-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Elevated_Cable_Rows/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"elevated-cable-rows-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Elevated_Cable_Rows/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rücken.","instructions":null}},{"id":"ex-elevated-prayer-stretch","slug":"elevated-prayer-stretch","name":"Elevated prayer stretch","description":"Bodyweight exercise for the back.","instructions":["Starting position:","Kneel in front of a bench, far enough so that your torso can fit between your knees and the bench. With your back straight, place your elbows on the bench, with palms together, hands pointing up.","Steps:","On exhale, stretch your chest down toward the floor without moving your lower back. At the same time, bring your hands toward your shoulders, keeping palms together and elbows on the bench.","Hold for a few seconds.","On inhale, relax your back to return to the starting position.","Repeat."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["elevated prayer stretch","erhöhte gebets-dehnung"],"media":[],"source":"wger","de":{"name":"Erhöhte Gebets-Dehnung","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Ausgangsposition:","Kniee dich vor eine Bank, weit genug entfernt, sodass dein Oberkörper zwischen deine Knie und die Bank passt. Lege bei geradem Rücken die Ellbogen auf die Bank, die Handflächen aneinander, die Hände nach oben zeigend.","Ablauf:","Dehne beim Ausatmen deine Brust nach unten zum Boden, ohne den unteren Rücken zu bewegen. Führe gleichzeitig deine Hände in Richtung der Schultern, wobei die Handflächen aneinander und die Ellbogen auf der Bank bleiben.","Halte einige Sekunden.","Entspanne beim Einatmen deinen Rücken, um in die Ausgangsposition zurückzukehren.","Wiederhole."]}},{"id":"ex-exercise-ball-pull-in","slug":"exercise-ball-pull-in","name":"Exercise Ball Pull-In","description":"Accessory exercise for the core.","instructions":["Place an exercise ball nearby and lay on the floor in front of it with your hands on the floor shoulder width apart in a push-up position.","Now place your lower shins on top of an exercise ball. Tip: At this point your legs should be fully extended with the shins on top of the ball and the upper body should be in a push-up type of position being supported by your two extended arms in front of you. This will be your starting position.","While keeping your back completely straight and the upper body stationary, pull your knees in towards your chest as you exhale, allowing the ball to roll forward under your ankles. Squeeze your abs and hold that position for a second.","Now slowly straighten your legs, rolling the ball back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["exercise ball pull-in"],"media":[{"id":"exercise-ball-pull-in-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Exercise_Ball_Pull-In/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"exercise-ball-pull-in-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Exercise_Ball_Pull-In/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rumpf.","instructions":null}},{"id":"ex-exercise-band-plantarflexion","slug":"exercise-band-plantarflexion","name":"Exercise Band Plantarflexion","description":"Resistance band exercise for the calves.","instructions":["Banded plantarflexion is a great way to bridge the gap between plantarflexion range of motion and the more strenuous calf raises in weight bearing. This can help strengthen the calf muscles, load the Achilles tendon, and improve plantarflexion range of motion."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"BAND","tags":["exercise band plantarflexion","plantarflexion mit widerstandsband"],"media":[],"source":"wger","de":{"name":"Plantarflexion mit Widerstandsband","description":"Übung (Widerstandsband) für die Waden.","instructions":["Die Plantarflexion mit Band ist eine gute Möglichkeit, die Lücke zwischen dem Bewegungsumfang der Plantarflexion und den anstrengenderen Wadenheben unter Belastung zu überbrücken. Das kann helfen, die Wadenmuskulatur zu stärken, die Achillessehne zu belasten und den Bewegungsumfang der Plantarflexion zu verbessern."]}},{"id":"ex-extended-range-one-arm-kettlebell-floor-press","slug":"extended-range-one-arm-kettlebell-floor-press","name":"Extended Range One-Arm Kettlebell Floor Press","description":"Kettlebell exercise for the chest, with shoulders, triceps assisting.","instructions":["Lie on the floor and position a kettlebell for one arm to press. The kettlebell should be held by the handle. The leg on the same side that you are pressing should be bent, with the knee crossing over the midline of the body.","Press the kettlebell by extending the elbow and adducting the arm, pressing it above your body. Return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"KETTLEBELL","tags":["extended range one-arm kettlebell floor press"],"media":[{"id":"extended-range-one-arm-kettlebell-floor-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Extended_Range_One-Arm_Kettlebell_Floor_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"extended-range-one-arm-kettlebell-floor-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Extended_Range_One-Arm_Kettlebell_Floor_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-external-rotation","slug":"external-rotation","name":"External Rotation","description":"Dumbbell exercise for the shoulders.","instructions":["Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.","Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm. Tip: Keep the arm parallel to your torso.","Now bend the elbow while keeping the upper arm stationary. In this manner, the forearm will be parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.","As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.","As you breathe in, slowly go back to the starting position.","Repeat for the recommended amount of repetitions and then switch to the other arm."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["external rotation"],"media":[{"id":"external-rotation-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/External_Rotation/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"external-rotation-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/External_Rotation/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern.","instructions":null}},{"id":"ex-external-rotation-stretch","slug":"external-rotation-stretch","name":"External Rotation Stretch","description":"Barbell exercise for the shoulders, with back assisting.","instructions":["Sit with your feet pressed against each other, and one knee raised all the way out to the side of your body.","Place your elbow on your raised knee, bend it at 90 degrees, and point your hand directly forward, holding your barbell/dumbbell.","Keep your shoulder depressed and retracted, raise your hand until your forearm is vertical, as if you were about to wave at someone like a robot.","Lower your hand to the original position and repeat."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"BARBELL","tags":["external rotation stretch","dehnung mit außenrotation"],"media":[{"id":"external-rotation-stretch-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1835/ca4a0b7e-9fdd-4173-843a-f0392824abe1.jpg","caption":"External Rotation Stretch","attribution":"wger.de · Nick E","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Dehnung mit Außenrotation","description":"Übung (Langhantel) für die Schultern, unterstützt von Rücken.","instructions":["Setze dich mit aneinandergedrückten Fußsohlen hin und hebe ein Knie ganz zur Seite deines Körpers an.","Lege deinen Ellenbogen auf dein angehobenes Knie, beuge ihn im 90-Grad-Winkel und richte deine Hand direkt nach vorne, während du deine Langhantel/Kurzhantel hältst.","Halte deine Schulter abgesenkt und zurückgezogen und hebe deine Hand an, bis dein Unterarm senkrecht steht, als würdest du jemandem wie ein Roboter zuwinken.","Senke deine Hand in die Ausgangsposition zurück und wiederhole die Bewegung."]}},{"id":"ex-external-rotation-with-band","slug":"external-rotation-with-band","name":"External Rotation with Band","description":"Resistance band exercise for the shoulders.","instructions":["Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away.","Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.","With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.","Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.","Continue as far as you are able, pause, and then return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"BAND","tags":["external rotation with band"],"media":[{"id":"external-rotation-with-band-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/External_Rotation_with_Band/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"external-rotation-with-band-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/External_Rotation_with_Band/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Widerstandsband) für die Schultern.","instructions":null}},{"id":"ex-external-rotation-with-cable","slug":"external-rotation-with-cable","name":"External Rotation with Cable","description":"Cable exercise for the shoulders.","instructions":["Adjust the cable to the same height as your elbow. Stand with your left side to the band a couple of feet away.","Grasp the handle with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.","With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.","Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["external rotation with cable","außenrotation am kabelzug"],"media":[{"id":"external-rotation-with-cable-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/External_Rotation_with_Cable/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"external-rotation-with-cable-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/External_Rotation_with_Cable/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Außenrotation am Kabelzug","description":"Übung (Kabelzug) für die Schultern.","instructions":["Schritte:","Befestige zunächst ein Widerstandsband um einen Pfosten oder an einer sicheren Position, an der es sich nicht löst und auf Ellbogenhöhe liegt.","Stelle dich seitlich zum Band und greife mit der Hand, die dem Band gegenüberliegt, nach dem Griff.","Führe das Band zu deiner Brust, halte deinen Ellbogen in einem 90-Grad-Winkel gebeugt und rotiere dann langsam deinen Arm in einer Rückhandbewegung, sodass das Band nach außen rotiert.","Führe die Bewegung so weit wie möglich nach außen aus, sodass du eine Dehnung in deinen Schultern spürst, halte einen Moment und kehre dann in die Ausgangsposition zurück.","Wiederhole dies für so viele Wiederholungen und Sätze wie gewünscht."]}},{"id":"ex-ez-bar-skullcrusher","slug":"ez-bar-skullcrusher","name":"EZ-Bar Skullcrusher","description":"EZ-bar exercise for the triceps, with forearms assisting.","instructions":["Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.","Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.","Lift the bar back to the starting position by extending the elbow and exhaling.","Repeat."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"EZ_BAR","tags":["ez-bar skullcrusher","frenchpress sz-stange"],"media":[{"id":"ez-bar-skullcrusher-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Skullcrusher/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"ez-bar-skullcrusher-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Skullcrusher/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Frenchpress SZ-Stange","description":"Übung (SZ-Stange) für den Trizeps, unterstützt von Unterarme.","instructions":["Nehme die Hantel, lege dich auf eine Bank und stelle dich so hin, dass ca. 1/4 des Kopfes nicht mehr auf der Bank liegt. Strecke die Arme aus und lasse nun mit einem Bogen das Gewicht runter. Wenn die Stange knapp über die Stirn ist, drücke sie wieder nach oben.","Es ist wichtig die Ellenbogen während der ganzen Übung wenig zu bewegen, damit die Trizeps die Arbeit machen."]}},{"id":"ex-face-pulls-with-yellow-green-band","slug":"face-pulls-with-yellow-green-band","name":"Face pulls with yellow/green band","description":"Resistance band exercise for the back.","instructions":["Face pulls with band – standing horizontal pull. Grab the band at face height, pull elbows high and wide towards your face while squeezing shoulder blades together. Trains upper back, rear shoulders and improves posture."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BAND","tags":["face pulls with yellow/green band","face pulls mit gelbem/grünem band"],"media":[{"id":"face-pulls-with-yellow-green-band-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1732/d13b9adb-968e-4f73-95e6-b16690bcf616.jpg","caption":"Face pulls with yellow/green band","attribution":"wger.de · 54str","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Face Pulls mit gelbem/grünem Band","description":"Übung (Widerstandsband) für den Rücken.","instructions":["Face Pulls mit Band – stehender horizontaler Zug. Greife das Band auf Gesichtshöhe, ziehe die Ellbogen hoch und weit nach außen in Richtung deines Gesichts und ziehe dabei die Schulterblätter zusammen. Trainiert den oberen Rücken und die hintere Schultermuskulatur und verbessert die Haltung."]}},{"id":"ex-facepull","slug":"facepull","name":"Facepull","description":"Cable exercise for the back.","instructions":["Attach a rope to a pulley station set at about chest level.","Step back so you're supporting the weight with arms completely outstretched and assume a staggered (one foot forward) stance. Bend the knees slightly for a stable base.","Retract the scapulae (squeeze your partner's finger with your shoulder blades) and pull the center of the rope slightly up towards the face. A good cue is to think about pulling the ends of the rope apart, not just pulling back.","As you near your face, externally rotate so your knuckles are facing the ceiling.","Hold for one second at the top position and slowly lower."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["facepull","face pulls"],"media":[],"source":"wger","de":{"name":"Face Pulls","description":"Übung (Kabelzug) für den Rücken.","instructions":["Die Übung trainiert die Rückseite der Schulter.","Die Ausführung erfolgt mit dem Seil am Kabelzug. Beide Enden des Seils in jeweils einer Hand halten, dabei die Schultern maximal vorwärts strecken und das Kabel leicht gespannt halten (Ruheposition).","Dann das Seil auf das Gesicht zuziehen. Die Hände bewegen sich dabei so weit wie möglich seitlicht am Kopf vorbei, die Schulter rotiert also nach hinten/außen."]}},{"id":"ex-fast-skipping","slug":"fast-skipping","name":"Fast Skipping","description":"Bodyweight exercise for the quadriceps, with glutes, calves, hamstrings assisting.","instructions":["Start in a relaxed position with one leg slightly forward. This will be your starting position.","Skip by executing a step-hop pattern of right-right-step to left-left-step, and so on, alternating back and forth.","Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","CALVES","HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["fast skipping"],"media":[{"id":"fast-skipping-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Fast_Skipping/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"fast-skipping-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Fast_Skipping/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Po, Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-finger-curls","slug":"finger-curls","name":"Finger Curls","description":"Barbell exercise for the forearms.","instructions":["Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.","Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. This will be your starting position.","Lower the bar as far as possible by extending the fingers. Allowing the bar to roll down the hands, catch the bar with the final joint in the fingers.","Now curl bar up as high as possible by closing your hands while exhaling. Hold the contraction at the top."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["finger curls"],"media":[{"id":"finger-curls-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Finger_Curls/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"finger-curls-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Finger_Curls/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Unterarme.","instructions":null}},{"id":"ex-finger-pushup","slug":"finger-pushup","name":"Finger Pushup","description":"Bodyweight exercise for the chest, with shoulders, core, triceps assisting.","instructions":["Hand Positioning:","Start in a plank position with your hands directly beneath your shoulders.","Spread your fingers wide apart, placing them firmly on the ground.","Finger Placement:","Gradually lift your palms off the ground, shifting the weight onto your fingers.","Focus on distributing the load evenly across your fingertips and thumbs.","Body Alignment:","Maintain a straight line from head to heels to engage your core."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","ABS_CORE","TRICEPS"],"equipment":"BODYWEIGHT","tags":["finger pushup","fingerliegestütz"],"media":[{"id":"finger-pushup-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1217/590e65db-de60-4727-b7eb-55f80af56043.png","caption":"Finger Pushup","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Fingerliegestütz","description":"Übung (Körpergewicht) für die Brust, unterstützt von Schultern, Rumpf, Trizeps.","instructions":["Handhaltung:","Beginne in einer Plank-Position mit deinen Händen direkt unter deinen Schultern.","Spreize deine Finger weit auseinander und setze sie fest auf den Boden.","Fingerposition:","Hebe deine Handflächen allmählich vom Boden ab und verlagere das Gewicht auf deine Finger.","Achte darauf, die Last gleichmäßig auf deine Fingerspitzen und Daumen zu verteilen.","Körperausrichtung:","Halte eine gerade Linie vom Kopf bis zu den Fersen, um deine Rumpfmuskulatur anzuspannen."]}},{"id":"ex-fingerboard-20-mm-edge","slug":"fingerboard-20-mm-edge","name":"Fingerboard 20 mm edge","description":"Bodyweight exercise for the biceps.","instructions":["Hang for 10 seconds on a fingerboard with a 20 mm edge"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["fingerboard 20 mm edge","leisten hängen an 20 mm kante"],"media":[],"source":"wger","de":{"name":"Leisten hängen an 20 mm Kante","description":"Übung (Körpergewicht) für den Bizeps.","instructions":["10 Sekunden an einer 20 mm Leiste des Fingerboards hängen"]}},{"id":"ex-flat-bench-cable-flyes","slug":"flat-bench-cable-flyes","name":"Flat Bench Cable Flyes","description":"Cable exercise for the chest.","instructions":["Position a flat bench between two low pulleys so that when you are laying on it, your chest will be lined up with the cable pulleys.","Lay flat on the bench and keep your feet on the ground.","Have someone hand you the handles on each hand. You will grab each single handle attachment with a palms up grip.","Extend your arms by your side with a slight bend on your elbows. Tip: You will keep this bend constant through the whole movement. Your arms should be parallel to the floor. This is your starting position.","Now start lifting the arms in a semi-circle motion directly in front of you by pulling the cables together until both hands meet at the top of the movement. Squeeze your chest as you perform this motion and breathe out during this movement. Also, hold the contraction for a second at the top. Tip: When performed correctly, at the top position of this movement, your arms should be perpendicular to your torso and the floor touching above your chest.","Slowly come back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["flat bench cable flyes"],"media":[{"id":"flat-bench-cable-flyes-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flat_Bench_Cable_Flyes/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"flat-bench-cable-flyes-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flat_Bench_Cable_Flyes/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Brust.","instructions":null}},{"id":"ex-flat-bench-leg-pull-in","slug":"flat-bench-leg-pull-in","name":"Flat Bench Leg Pull-In","description":"Bodyweight exercise for the core.","instructions":["Lie on an exercise mat or a flat bench with your legs off the end.","Place your hands either under your glutes with your palms down or by the sides holding on to the bench (or with palms down by the side on an exercise mat). Also extend your legs straight out. This will be your starting position.","Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue this movement until your knees are near your chest. Hold the contracted position for a second.","As you breathe in, slowly return to the starting position.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["flat bench leg pull-in"],"media":[{"id":"flat-bench-leg-pull-in-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flat_Bench_Leg_Pull-In/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"flat-bench-leg-pull-in-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flat_Bench_Leg_Pull-In/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-flat-machine-press","slug":"flat-machine-press","name":"Flat Machine Press","description":"Machine exercise for the chest.","instructions":["Execution","Start position:","Elbows bent at roughly 90°, hands just outside your chest.","Keep wrists straight and aligned with your forearms.","Pressing phase (concentric):","Push the handles forward until your arms are almost fully extended — don’t lock out.","Focus on squeezing your chest at the end of the movement.","Returning phase (eccentric):"],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["flat machine press","brustdrücken an der maschine (flach)"],"media":[],"source":"wger","de":{"name":"Brustdrücken an der Maschine (flach)","description":"Übung (Maschine) für die Brust.","instructions":["Ausführung","Startposition:","Die Ellenbogen sind etwa 90° gebeugt, die Hände knapp außerhalb deiner Brust.","Halte die Handgelenke gerade und in einer Linie mit deinen Unterarmen.","Drückphase (konzentrisch):","Drücke die Griffe nach vorne, bis deine Arme fast vollständig gestreckt sind — strecke sie nicht ganz durch.","Konzentriere dich darauf, deine Brustmuskulatur am Ende der Bewegung zusammenzudrücken.","Rückführphase (exzentrisch):"]}},{"id":"ex-flexor-incline-dumbbell-curls","slug":"flexor-incline-dumbbell-curls","name":"Flexor Incline Dumbbell Curls","description":"Dumbbell exercise for the biceps.","instructions":["Hold the dumbbell towards the side farther from you so that you have more weight on the side closest to you. (This can be done for a good effect on all bicep dumbbell exercises). Now do a normal incline dumbbell curl, but keep your wrists as far back as possible so as to neutralize any stress that is placed on them.","Sit on an incline bench that is angled at 45-degrees while holding a dumbbell on each hand.","Let your arms hang down on your sides, with the elbows in, and turn the palms of your hands forward with the thumbs pointing away from the body. Tip: You will keep this hand position throughout the movement as there should not be any twisting of the hands as they come up. This will be your starting position.","Curl up the two dumbbells at the same time until your biceps are fully contracted and exhale. Tip: Do not swing the arms or use momentum. Keep a controlled motion at all times. Hold the contracted position for a second at the top.","As you inhale, slowly go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["flexor incline dumbbell curls"],"media":[{"id":"flexor-incline-dumbbell-curls-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flexor_Incline_Dumbbell_Curls/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"flexor-incline-dumbbell-curls-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flexor_Incline_Dumbbell_Curls/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps.","instructions":null}},{"id":"ex-floor-dips","slug":"floor-dips","name":"Floor dips","description":"Bodyweight exercise for the triceps, with shoulders, chest assisting.","instructions":["Starting position:","Sit with your arms behind you, supporting your back.Your fingers should point forward.Your knees should be bent, feet together.","Steps:","Raise your hips off the ground, straightening your arms.","Bend your elbows, bringing your hips down.","Straighten your arms, returning to the previous position.","Repeat steps 2 and 3.","Notes:"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["SHOULDERS","CHEST"],"equipment":"BODYWEIGHT","tags":["floor dips","bodensenken"],"media":[{"id":"floor-dips-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1000/553266a8-a972-48c5-a014-b12afac66f65.png","caption":"Floor dips","attribution":"wger.de · Franpol","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Bodensenken","description":"Übung (Körpergewicht) für den Trizeps, unterstützt von Schultern, Brust.","instructions":["Ausgangsposition:","Setzen Sie sich mit den Armen hinter den Rücken und stützen Sie ihn ab.Die Finger sollten nach vorne zeigen.Die Knie sind gebeugt, die Füße stehen zusammen.","Die Schritte:","Heben Sie die Hüfte vom Boden ab und strecken Sie die Arme aus.","Beugen Sie die Ellbogen und bringen Sie die Hüfte nach unten.","Strecken Sie die Arme durch und kehren Sie in die vorherige Position zurück.","Wiederholen Sie die Schritte 2 und 3.","Anmerkungen:"]}},{"id":"ex-floor-glider-hamstring-curls","slug":"floor-glider-hamstring-curls","name":"Floor Glider Hamstring Curls","description":"Bodyweight exercise for the hamstrings, with calves, glutes assisting.","instructions":["Lie on back with heels on floor gliders or towels. Lift hips into a bridge, then slide heels toward glutes while keeping hips elevated. Slowly return to the starting position while maintaining the hip bridge."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","GLUTES"],"equipment":"BODYWEIGHT","tags":["floor glider hamstring curls","beinbeuger am boden mit glidern"],"media":[],"source":"wger","de":{"name":"Beinbeuger am Boden mit Glidern","description":"Übung (Körpergewicht) für die Oberschenkelrückseite, unterstützt von Waden, Po.","instructions":["Lege dich auf den Rücken, die Fersen auf Glidern oder Handtüchern. Hebe deine Hüften in eine Brücke an und schiebe dann deine Fersen in Richtung Gesäß, während du die Hüften oben hältst. Kehre langsam in die Ausgangsposition zurück und halte dabei die Hüftbrücke aufrecht."]}},{"id":"ex-floor-glute-ham-raise","slug":"floor-glute-ham-raise","name":"Floor Glute-Ham Raise","description":"Equipment-free exercise for the hamstrings, with calves, glutes assisting.","instructions":["You can use a partner for this exercise or brace your feet under something stable.","Begin on your knees with your upper legs and torso upright. If using a partner, they will firmly hold your feet to keep you in position. This will be your starting position.","Lower yourself by extending at the knee, taking care to NOT flex the hips as you go forward.","Place your hands in front of you as you reach the floor. This movement is very difficult and you may be unable to do it unaided. Use your arms to lightly push off the floor to aid your return to the starting position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","GLUTES"],"equipment":"NONE","tags":["floor glute-ham raise"],"media":[{"id":"floor-glute-ham-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Floor_Glute-Ham_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"floor-glute-ham-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Floor_Glute-Ham_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelrückseite, unterstützt von Waden, Po.","instructions":null}},{"id":"ex-floor-press","slug":"floor-press","name":"Floor Press","description":"Barbell exercise for the triceps, with chest, shoulders assisting.","instructions":["Adjust the j-hooks so they are at the appropriate height to rack the bar. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together; pull the bar off of the hooks.","Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.","Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"BARBELL","tags":["floor press"],"media":[{"id":"floor-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Floor_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"floor-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Floor_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-floor-press-with-chains","slug":"floor-press-with-chains","name":"Floor Press with Chains","description":"Barbell exercise for the triceps, with chest, shoulders assisting.","instructions":["Adjust the j-hooks so they are at the appropriate height to rack the bar. For this exercise, drape the chains directly over the end of the bar, trying to keep the ends away from the plates.","Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together, pull the bar off of the hooks.","Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.","Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"BARBELL","tags":["floor press with chains"],"media":[{"id":"floor-press-with-chains-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Floor_Press_with_Chains/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"floor-press-with-chains-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Floor_Press_with_Chains/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-foot-smr","slug":"foot-smr","name":"Foot-SMR","description":"Accessory exercise for the calves.","instructions":["This exercise stretches the fascia of the muscles in the feet. Start off seated with your shoes removed. Using a foot roller or a similar object, such as a small section of pvc pipe, place your foot against the roller across the arch of your foot. This will be your starting position.","Press down firmly, rolling across the arch of your foot. Hold for 10-30 seconds, and then switch feet."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["foot-smr"],"media":[{"id":"foot-smr-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Foot-SMR/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"foot-smr-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Foot-SMR/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Waden.","instructions":null}},{"id":"ex-forward-arm-circles","slug":"forward-arm-circles","name":"Forward arm circles","description":"Bodyweight exercise for the biceps.","instructions":["Starting position:","Stand tall with your back straight.","Steps:","Keeping your arms straight, bring them in front of you, move them down, behind your back, then over your head, and back to the initial position.","Keep circling your arms as described in step 1."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["forward arm circles","armkreisen vorwärts"],"media":[],"source":"wger","de":{"name":"Armkreisen vorwärts","description":"Übung (Körpergewicht) für den Bizeps.","instructions":["Ausgangsposition:","Stehen Sie aufrecht mit geradem Rücken.","Schritte:","Führen Sie die Arme bei gestrecktem Körper vor sich her, führen Sie sie nach unten, hinter den Rücken, dann über den Kopf und zurück in die Ausgangsposition.","Lassen Sie die Arme wie in Schritt 1 beschrieben kreisen."]}},{"id":"ex-forward-shoulder-rotation","slug":"forward-shoulder-rotation","name":"Forward shoulder rotation","description":"Bodyweight exercise for the back.","instructions":["Starting position:","Sit or stand with your back straight.","Steps:","Place your hands on your shoulders.","Repeatedly rotate both shoulder joints in a circular motion at a moderate pace."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["forward shoulder rotation","vorwärtsdrehung der schulter"],"media":[],"source":"wger","de":{"name":"Vorwärtsdrehung der Schulter","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Ausgangsposition:","Sitze oder stehe mit geradem Rücken.","Schritte:","Lege Deine Hände auf Deine Schultern.","Drehe wiederholt beide Schultergelenke in einer kreisförmigen Bewegung mit mäßigem Tempo."]}},{"id":"ex-frankenstein-squat","slug":"frankenstein-squat","name":"Frankenstein Squat","description":"Barbell exercise for the quadriceps, with core, calves, glutes, hamstrings assisting.","instructions":["This drill teaches you the proper positioning of both the bar and your body during the clean and front squat.","Place the barbell on the front of the shoulders, releasing your grip and extending your arms out in front of you. The shoulders should be pushed forward to create a shelf, and the bar should be in contact with the throat. Ensure that you only move your shoulder blades forward; don't round the thoracic spine.","Squat by flexing the knees and hips, sitting in between your legs. Keep the torso upright, the arms up, and the shoulders forward, and the bar should stay in place. Go to the bottom of the squat, until your hamstrings contact your calves.","Return to the upright position by driving through the front of the heel and extending the knees and hips."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["ABS_CORE","CALVES","GLUTES","HAMSTRINGS"],"equipment":"BARBELL","tags":["frankenstein squat"],"media":[{"id":"frankenstein-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Frankenstein_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"frankenstein-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Frankenstein_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Rumpf, Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-freehand-jump-squat","slug":"freehand-jump-squat","name":"Freehand Jump Squat","description":"Bodyweight exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Cross your arms over your chest.","With your head up and your back straight, position your feet at shoulder width.","Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.","Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement.","When you touch the floor again, immediately squat down and jump again.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["freehand jump squat"],"media":[{"id":"freehand-jump-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Freehand_Jump_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"freehand-jump-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Freehand_Jump_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-frog-hops","slug":"frog-hops","name":"Frog Hops","description":"Equipment-free exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Stand with your hands behind your head, and squat down keeping your torso upright and your head up. This will be your starting position.","Jump forward several feet, avoiding jumping unnecessarily high. As your feet contact the ground, absorb the impact through your legs, and jump again. Repeat this action 5-10 times."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"NONE","tags":["frog hops"],"media":[{"id":"frog-hops-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Frog_Hops/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"frog-hops-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Frog_Hops/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-frog-sit-ups","slug":"frog-sit-ups","name":"Frog Sit-Ups","description":"Bodyweight exercise for the core.","instructions":["Lie with your back flat on the floor (or exercise mat) and your legs extended in front of you.","Now bend at the knees and place your outer thighs by the floor (or mat) as you make the soles of your feet touch each other.","Now try pushing both soles and bringing them up as near you as possible while you keep the outer thighs on the floor (or at least almost touching it). Tip: In this position your legs should create a diamond shape.","Now, cross your arms in front of you by touching the opposite shoulders. This will be your starting position.","As you exhale flatten your lower back to the floor while curling the torso upwards. Tip: This will be like performing the first 1/4 movement of a sit up. Hold at the top position for a second.","As you inhale, slowly lower back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["frog sit-ups"],"media":[{"id":"frog-sit-ups-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Frog_Sit-Ups/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"frog-sit-ups-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Frog_Sit-Ups/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-frog-stand","slug":"frog-stand","name":"Frog stand","description":"Bodyweight exercise for the shoulders, with biceps, core assisting.","instructions":["Starting position:","Stand with your feet shoulder-width apart and your toes pointing forward, facing a wall or bench for support if needed.","Bend your knees into a squat position.","Place your hands on the ground in front of you, shoulder-width apart, with your fingers spread wide.","Make sure your elbows are under your shoulders and your body forms a straight line from your head to your heels.","Upward phase:","Push with your feet and hands to lift your body off the ground.","Straighten your legs and arms, keeping your body aligned."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BICEPS","ABS_CORE"],"equipment":"BODYWEIGHT","tags":["frog stand","froschstand"],"media":[],"source":"wger","de":{"name":"Froschstand","description":"Übung (Körpergewicht) für die Schultern, unterstützt von Bizeps, Rumpf.","instructions":["Ausgangsposition:","Stelle dich mit schulterbreit aufgestellten Füßen hin, die Zehen zeigen nach vorne, und richte dich bei Bedarf zur Unterstützung zu einer Wand oder Bank aus.","Beuge deine Knie in eine Hockposition.","Setze deine Hände schulterbreit vor dir auf den Boden, mit weit gespreizten Fingern.","Achte darauf, dass deine Ellbogen unter deinen Schultern sind und dein Körper eine gerade Linie vom Kopf bis zu den Fersen bildet.","Aufwärtsphase:","Drücke dich mit Füßen und Händen ab, um deinen Körper vom Boden zu heben.","Strecke deine Beine und Arme und halte deinen Körper dabei in einer Linie."]}},{"id":"ex-frog-stretch","slug":"frog-stretch","name":"Frog Stretch","description":"Bodyweight exercise for the glutes.","instructions":["Get on your hands and knees.","Widen your knees outwards, and drop to your elbows.","Without moving your elbows or knees, start to rock forwards and backwards, trying to get your bum closer to your feet."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["frog stretch","froschdehnung"],"media":[],"source":"wger","de":{"name":"Froschdehnung","description":"Übung (Körpergewicht) für den Po.","instructions":["Begib dich in den Vierfüßlerstand.","Spreize deine Knie weit nach außen und senke dich auf deine Ellbogen ab.","Wippe, ohne deine Ellbogen oder Knie zu bewegen, langsam vor und zurück und versuche, dein Gesäß näher an deine Füße zu bringen."]}},{"id":"ex-front-barbell-squat","slug":"front-barbell-squat","name":"Front Barbell Squat","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.","Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).","Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor mainly with the middle of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"BARBELL","tags":["front barbell squat"],"media":[{"id":"front-barbell-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Barbell_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"front-barbell-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Barbell_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-front-barbell-squat-to-a-bench","slug":"front-barbell-squat-to-a-bench","name":"Front Barbell Squat To A Bench","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set a flat bench behind you and set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.","Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).","Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until you touch the bench with your glutes. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor mainly with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"BARBELL","tags":["front barbell squat to a bench"],"media":[{"id":"front-barbell-squat-to-a-bench-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Barbell_Squat_To_A_Bench/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"front-barbell-squat-to-a-bench-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Barbell_Squat_To_A_Bench/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-front-box-jump","slug":"front-box-jump","name":"Front Box Jump","description":"Accessory exercise for the hamstrings, with glutes, quadriceps, calves assisting.","instructions":["Begin with a box of an appropriate height 1-2 feet in front of you. Stand with your feet should width apart. This will be your starting position.","Perform a short squat in preparation for jumping, swinging your arms behind you.","Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.","Land on the box with the knees bent, absorbing the impact through the legs. You can jump from the box back to the ground, or preferably step down one leg at a time."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","QUADRICEPS","CALVES"],"equipment":"OTHER","tags":["front box jump"],"media":[{"id":"front-box-jump-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Box_Jump/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"front-box-jump-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Box_Jump/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelrückseite, unterstützt von Po, Oberschenkelvorderseite, Waden.","instructions":null}},{"id":"ex-front-cable-raise","slug":"front-cable-raise","name":"Front Cable Raise","description":"Cable exercise for the shoulders.","instructions":["Select the weight on a low pulley machine and grasp the single hand cable attachment that is attached to the low pulley with your left hand.","Face away from the pulley and put your arm straight down with the hand cable attachment in front of your thighs at arms' length with the palms of the hand facing your thighs. This will be your starting position.","While maintaining the torso stationary (no swinging), lift the left arm to the front with a slight bend on the elbow and the palms of the hand always faces down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top.","Now as you inhale lower the arm back down slowly to the starting position.","Once all of the recommended amount of repetitions have been performed for this arm, switch arms and perform the exercise with the right one."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["front cable raise"],"media":[{"id":"front-cable-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Cable_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"front-cable-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Cable_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Schultern.","instructions":null}},{"id":"ex-front-cone-hops-or-hurdle-hops","slug":"front-cone-hops-or-hurdle-hops","name":"Front Cone Hops (or hurdle hops)","description":"Accessory exercise for the quadriceps, with glutes, calves, hamstrings assisting.","instructions":["Set up a row of cones or other small barriers, placing them a few feet apart.","Stand in front of the first cone with your feet shoulder width apart. This will be your starting position.","Begin by jumping with both feet over the first cone, swinging both arms as you jump.","Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next cone.","Continue until you have jumped over all of the cones."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","CALVES","HAMSTRINGS"],"equipment":"OTHER","tags":["front cone hops (or hurdle hops)"],"media":[{"id":"front-cone-hops-or-hurdle-hops-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Cone_Hops_or_hurdle_hops/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"front-cone-hops-or-hurdle-hops-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Cone_Hops_or_hurdle_hops/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite, unterstützt von Po, Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-front-incline-dumbbell-raise","slug":"front-incline-dumbbell-raise","name":"Front Incline Dumbbell Raise","description":"Dumbbell exercise for the shoulders.","instructions":["Sit down on an incline bench with the incline set anywhere between 30 to 60 degrees while holding a dumbbell on each hand. Tip: You can change the angle to hit the muscle a little differently each time.","Extend your arms straight in front of you and have your palms facing down with the dumbbells raised about 1 inch above your thighs. This will be your starting position.","Slowly raise the dumbbells straight up until they are slightly above your shoulders, while keeping your elbows locked. Squeeze at the top for a second and make sure you breathe out during this portion of the movement. Tip: Keep your head resting down against the bench and your legs on the floor at all times.","Lower the arms back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["front incline dumbbell raise"],"media":[{"id":"front-incline-dumbbell-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Incline_Dumbbell_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"front-incline-dumbbell-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Incline_Dumbbell_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern.","instructions":null}},{"id":"ex-front-leg-raises","slug":"front-leg-raises","name":"Front Leg Raises","description":"Bodyweight exercise for the hamstrings.","instructions":["Stand next to a chair or other support, holding on with one hand.","Swing your leg forward, keeping the leg straight. Continue with a downward swing, bringing the leg as far back as your flexibility allows. Repeat 5-10 times, and then switch legs."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["front leg raises"],"media":[{"id":"front-leg-raises-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Leg_Raises/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"front-leg-raises-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Leg_Raises/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelrückseite.","instructions":null}},{"id":"ex-front-lever-tuck","slug":"front-lever-tuck","name":"Front lever tuck","description":"Bodyweight exercise for the shoulders, with biceps, back, triceps assisting.","instructions":["The muscles involved in the Front Lever, most subjected to stress, are mainly the extensors such as: the latissimus dorsi, the teres major, the posterior deltoid and the long head of the biceps."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BICEPS","BACK","TRICEPS"],"equipment":"BODYWEIGHT","tags":["front lever tuck"],"media":[],"source":"wger","de":{"name":"Front Lever Tuck","description":"Übung (Körpergewicht) für die Schultern, unterstützt von Bizeps, Rücken, Trizeps.","instructions":["Die beim Front Lever beteiligten Muskeln, die am stärksten beansprucht werden, sind hauptsächlich die Strecker, wie zum Beispiel: der Latissimus, der große Rundmuskel, der hintere Deltamuskel und der lange Kopf des Bizeps."]}},{"id":"ex-front-neck-stretch","slug":"front-neck-stretch","name":"Front neck stretch","description":"Bodyweight exercise for the back.","instructions":["Starting position:","Sit or stand with your back straight.","Steps:","Open mouth wide.","Slowly tilt head back with mouth opened. If you feel the need for support, clasp your hands behind your head.","Very slowly close and open your mouth.","At the end, slowly return to starting position and close mouth."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["front neck stretch","nackenstütze vorne"],"media":[],"source":"wger","de":{"name":"Nackenstütze vorne","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Ausgangsposition:","Sitzen oder stehen Sie mit geradem Rücken.","Schritte:","Öffnen Sie den Mund weit.","Neigen Sie den Kopf bei geöffnetem Mund langsam nach hinten. Wenn Sie das Gefühl haben, dass Sie Unterstützung brauchen, verschränken Sie Ihre Hände hinter dem Kopf.","Schließen und öffnen Sie den Mund ganz langsam.","Am Ende kehren Sie langsam in die Ausgangsposition zurück und schließen den Mund."]}},{"id":"ex-front-plank","slug":"front-plank","name":"Front Plank","description":"Bodyweight exercise for the core, with chest, quadriceps assisting.","instructions":["The plank is a bodyweight exercise. As a multi-functional movement, the plank not only targets your abdominal muscles but also the spine and hip. Plank strengthens and tightens your entire body, improves your posture and balance, reduces body fat, and can help boost your metabolism.","Exercises such as the “plank pose” help strengthen the stamina of stabilizing abdominal muscles. It can also help relieve back pain associated with a weakening of the function of the stabilizing muscles of the body.","Planks are a versatile exercise that targets many of the most important muscle groups in the body, so they can be applied by anyone to improve endurance and overall body strength."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["CHEST","QUADRICEPS"],"equipment":"BODYWEIGHT","tags":["front plank","unterarmstütz (plank)"],"media":[{"id":"front-plank-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1307/321d796a-f394-40b8-a1ea-874bbed6ecee.png","caption":"Front Plank","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Unterarmstütz (Plank)","description":"Übung (Körpergewicht) für den Rumpf, unterstützt von Brust, Oberschenkelvorderseite.","instructions":["Der Plank ist eine Körpergewichtsübung. Als multifunktionale Bewegung beansprucht der Plank nicht nur deine Bauchmuskulatur, sondern auch die Wirbelsäule und die Hüfte. Der Plank kräftigt und strafft deinen gesamten Körper, verbessert deine Haltung und dein Gleichgewicht, reduziert Körperfett und kann dabei helfen, deinen Stoffwechsel anzukurbeln.","Übungen wie die „Plank-Position“ helfen, die Ausdauer der stabilisierenden Bauchmuskulatur zu stärken. Sie können außerdem dabei helfen, Rückenschmerzen zu lindern, die mit einer geschwächten Funktion der stabilisierenden Muskeln des Körpers zusammenhängen.","Planks sind eine vielseitige Übung, die viele der wichtigsten Muskelgruppen des Körpers beansprucht, sodass sie von jedem genutzt werden können, um die Ausdauer und die gesamte Körperkraft zu verbessern."]}},{"id":"ex-front-raise-and-pullover","slug":"front-raise-and-pullover","name":"Front Raise And Pullover","description":"Barbell exercise for the chest, with back, shoulders, triceps assisting.","instructions":["Lie on a flat bench while holding a barbell using a palms down grip that is about 15 inches apart.","Place the bar on your upper thighs, extend your arms and lock them while keeping a slight bend on the elbows. This will be your starting position.","Now raise the weight using a semicircular motion and keeping your arms straight as you inhale. Continue the same movement until the bar is on the other side above your head . (Tip: the bar will travel approximately 180-degrees). At this point your arms should be parallel to the floor with the palms of your hands facing the ceiling.","Now return the barbell to the starting position by reversing the motion as you exhale.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["BACK","SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["front raise and pullover"],"media":[{"id":"front-raise-and-pullover-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Raise_And_Pullover/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"front-raise-and-pullover-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Raise_And_Pullover/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Brust, unterstützt von Rücken, Schultern, Trizeps.","instructions":null}},{"id":"ex-front-raises","slug":"front-raises","name":"Front Raises","description":"Barbell exercise for the shoulders.","instructions":["To execute the exercise, the lifter stands with their feet shoulder width apart and weights or resistance handles held by their side with a pronated (overhand) grip.","The movement is to bring the arms up in front of the body to eye level and with only a slight bend in the elbow. This isolates the anterior deltoid muscle (front of the shoulder) and uses the anterior deltoid to lift the weight.","When lifting it is important to keep the body still so the anterior deltoid is fully utilised; if the weight cannot be lifted by standing still then it is too heavy and a lower weight is needed. It is important to keep a slight bend in the elbow when lifting as keeping the elbow locked will add stress to the elbow joint and could cause injury.","A neutral grip, similar to that used in the hammer curl, can also be used. With this variation the weight is again raised to eye level, but out to a 45 degree angle from the front of the body. This may be beneficial for those with shoulder injuries, particularly those related to the rotator cuff."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["front raises","frontheben am kabel"],"media":[{"id":"front-raises-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/256/b7def5bc-2352-499b-b9e5-fff741003831.png","caption":"Front Raises","attribution":"wger.de · philip","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Frontheben am Kabel","description":"Übung (Langhantel) für die Schultern.","instructions":["Stelle dich mit dem Rücken zum Kabel, halte aber genügend Abstand, dass du es durch die Beine nach oben ziehen kannst. Greife die Stange, strecke die Arme komplett aus und ziehe das Seil hoch, bis sie waagerecht sind. Bringe dann wieder das Gewicht runter."]}},{"id":"ex-front-raises-with-plates","slug":"front-raises-with-plates","name":"Front Raises with Plates","description":"Bodyweight exercise for the shoulders, with back assisting.","instructions":["The plate front raise is a variation of the dumbbell front raise where the lifter holds a weight plate between two hands, rather than using a dumbbell, barbell, or other weight. It can provide variety in a shoulder-focused muscle-building workout, or as part of an upper body or full-body circuit.","While standing straight, hold a barbell plate in both hands at the 3 and 9 o'clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. Tip: The arms will remain in this position throughout the exercise. This will be your starting position.","Slowly raise the plate as you exhale until it is a little above shoulder level. Hold the contraction for a second. As you inhale, slowly lower the plate back down to the starting position.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"BODYWEIGHT","tags":["front raises with plates","frontheben mit scheibe"],"media":[],"source":"wger","de":{"name":"Frontheben Mit Scheibe","description":"Übung (Körpergewicht) für die Schultern, unterstützt von Rücken.","instructions":["Das Frontheben mit Gewichtsscheibe ist eine Variante des Fronthebens mit Kurzhantel, bei der du eine Gewichtsscheibe zwischen beiden Händen hältst, statt eine Kurzhantel, Langhantel oder ein anderes Gewicht zu verwenden. Es kann für Abwechslung in einem schulterbetonten Muskelaufbautraining sorgen oder Teil eines Oberkörper- oder Ganzkörper-Zirkels sein.","Halte im aufrechten Stand eine Hantelscheibe mit beiden Händen auf der 3- und 9-Uhr-Position. Deine Handflächen sollten einander zugewandt sein, deine Arme gestreckt und mit einer leichten Beugung im Ellbogen fixiert, und die Scheibe sollte so weit wie möglich unten vor dir auf Höhe der Taille gehalten werden. Tipp: Die Arme bleiben während der gesamten Übung in dieser Position. Das ist deine Ausgangsposition.","Hebe die Scheibe langsam an, während du ausatmest, bis sie etwas über Schulterhöhe ist. Halte die Kontraktion eine Sekunde lang. Während du einatmest, senke die Scheibe langsam wieder in die Ausgangsposition.","Wiederhole für die empfohlene Anzahl an Wiederholungen."]}},{"id":"ex-front-squat-clean-grip","slug":"front-squat-clean-grip","name":"Front Squat (Clean Grip)","description":"Barbell exercise for the quadriceps, with core, glutes, hamstrings assisting.","instructions":["To begin, first set the bar in a rack slightly below shoulder level. Rest the bar on top of the deltoids, pushing into the clavicles, and lightly touching the throat. Your hands should be in a clean grip, touching the bar only with your fingers to help keep it in position.","Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head and elbows up at all times. This will be your starting position.","Bend at the knees, sitting down between your legs. Continue down until your hamstrings are on your calves. Keep your knees aligned with your feet by consciously using your abductors to push your knees out as you squat.","Begin to raise the bar as you exhale by pushing the floor mainly with the heel or middle of your foot as you straighten the legs again and return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["ABS_CORE","GLUTES","HAMSTRINGS"],"equipment":"BARBELL","tags":["front squat (clean grip)"],"media":[{"id":"front-squat-clean-grip-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Squat_Clean_Grip/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"front-squat-clean-grip-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Squat_Clean_Grip/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Rumpf, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-front-squats","slug":"front-squats","name":"Front Squats","description":"Barbell exercise for the glutes, with core assisting.","instructions":["This variation of the squat trains the hamstrings and gluteus maximus. It also works the back extensors and abductors."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["ABS_CORE"],"equipment":"BARBELL","tags":["front squats","front kniebeuge"],"media":[{"id":"front-squats-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/191/Front-squat-1-857x1024.png","caption":"Front Squats","attribution":"wger.de · Everkinetic","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Front Kniebeuge","description":"Übung (Langhantel) für den Po, unterstützt von Rumpf.","instructions":["Bei dieser Variante des Kniebeugens werden der Beinbizeps und der Große Gesäßmuskel trainiert.","Daneben werden die Rückenstrecker und die Abduktoren beansprucht."]}},{"id":"ex-front-squats-with-two-kettlebells","slug":"front-squats-with-two-kettlebells","name":"Front Squats With Two Kettlebells","description":"Kettlebell exercise for the quadriceps, with calves, glutes assisting.","instructions":["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.","Looking straight ahead at all times, squat as low as you can and pause at the bottom. As you squat down, push your knees out. You should squat between your legs, keeping an upright torso, with your head and chest up.","Rise back up by driving through your heels and repeat."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES"],"equipment":"KETTLEBELL","tags":["front squats with two kettlebells"],"media":[{"id":"front-squats-with-two-kettlebells-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Squats_With_Two_Kettlebells/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"front-squats-with-two-kettlebells-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Squats_With_Two_Kettlebells/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Oberschenkelvorderseite, unterstützt von Waden, Po.","instructions":null}},{"id":"ex-front-two-dumbbell-raise","slug":"front-two-dumbbell-raise","name":"Front Two-Dumbbell Raise","description":"Dumbbell exercise for the shoulders.","instructions":["Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.","While maintaining the torso stationary (no swinging), lift the dumbbells to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arms are slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top.","As you inhale, lower the dumbbells back down slowly to the starting position.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["front two-dumbbell raise"],"media":[{"id":"front-two-dumbbell-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Two-Dumbbell_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"front-two-dumbbell-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Two-Dumbbell_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern.","instructions":null}},{"id":"ex-full-range-of-motion-lat-pulldown","slug":"full-range-of-motion-lat-pulldown","name":"Full Range-Of-Motion Lat Pulldown","description":"Cable exercise for the back, with biceps, shoulders assisting.","instructions":["Either standing or seated on a high bench, grasp two stirrup cables that are attached to the high pulleys. Grab with the opposing hand so your arms are crisscrossed about you and your palms are facing forward.","Keeping your chest up and maintaining a slight arch in your lower back, pull the handles down as if you were doing a regular pulldown. The range of motion will be more of an arc. During the movement, rotate your hands so that in the bottom position your palms face each other rather than forward. Return slowly to the starting position and repeat."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","SHOULDERS"],"equipment":"CABLE","tags":["full range-of-motion lat pulldown"],"media":[{"id":"full-range-of-motion-lat-pulldown-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Full_Range-Of-Motion_Lat_Pulldown/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"full-range-of-motion-lat-pulldown-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Full_Range-Of-Motion_Lat_Pulldown/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rücken, unterstützt von Bizeps, Schultern.","instructions":null}},{"id":"ex-gironda-sternum-chins","slug":"gironda-sternum-chins","name":"Gironda Sternum Chins","description":"Accessory exercise for the back, with biceps assisting.","instructions":["Grasp the pull-up bar with a shoulder width underhand grip.","Now hang with your arms fully extended and stick your chest out and lean back. Tip: You will be leaning back throughout the entire movement. This will be your starting position.","Start pulling yourself towards the bar with your spine arched throughout the movement and your head leaning back as far away from the bar as possible. Exhale as you perform this portion of the movement. Tip: At the upper end of the movement, your hips and legs will be at about a 45-degree angle to the floor.","Keep pulling until your collarbone passes the bar and your lower chest or sternum area touches it. Hold that contraction for a second. Tip: By the time you've completed this portion of the movement; your head will be parallel to the floor.","Slowly start going back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"OTHER","tags":["gironda sternum chins"],"media":[{"id":"gironda-sternum-chins-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Gironda_Sternum_Chins/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"gironda-sternum-chins-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Gironda_Sternum_Chins/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-glute-bridge-single-arm-press","slug":"glute-bridge-single-arm-press","name":"Glute Bridge Single-Arm Press","description":"Dumbbell exercise for the chest, with shoulders, biceps, hamstrings, glutes, triceps assisting.","instructions":["With one dumbbell in hand, perform a glute bridge. Now hold the dumbbell above your chest, this is the rep starting position. Lower the dumbbell so that your elbow touches the floor or is roughly 45 degrees below your shoulder if using a bench. Push the dumbbell back into the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","BICEPS","HAMSTRINGS","GLUTES","TRICEPS"],"equipment":"DUMBBELL","tags":["glute bridge single-arm press","glute bridge mit einarmigem drücken"],"media":[],"source":"wger","de":{"name":"Glute Bridge mit einarmigem Drücken","description":"Übung (Kurzhantel) für die Brust, unterstützt von Schultern, Bizeps, Oberschenkelrückseite, Po, Trizeps.","instructions":["Halte eine Kurzhantel in einer Hand und führe eine Glute Bridge aus. Halte nun die Kurzhantel über deiner Brust, das ist die Startposition der Wiederholung. Senke die Kurzhantel ab, sodass dein Ellbogen den Boden berührt oder sich etwa 45 Grad unterhalb deiner Schulter befindet, wenn du eine Bank verwendest. Drücke die Kurzhantel zurück in die Startposition."]}},{"id":"ex-glute-ham-raise","slug":"glute-ham-raise","name":"Glute Ham Raise","description":"Machine exercise for the hamstrings, with calves, glutes assisting.","instructions":["Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad.","Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright.","Return to the starting position, keeping your descent under control."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","GLUTES"],"equipment":"MACHINE","tags":["glute ham raise"],"media":[{"id":"glute-ham-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Glute_Ham_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"glute-ham-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Glute_Ham_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Oberschenkelrückseite, unterstützt von Waden, Po.","instructions":null}},{"id":"ex-glute-kickback","slug":"glute-kickback","name":"Glute Kickback","description":"Bodyweight exercise for the glutes, with hamstrings assisting.","instructions":["Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.","As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.","Go back to the initial position as you inhale and now repeat with the left leg.","Continue to alternate legs until all of the recommended repetitions have been performed."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["glute kickback"],"media":[{"id":"glute-kickback-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Glute_Kickback/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"glute-kickback-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Glute_Kickback/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelrückseite.","instructions":null}},{"id":"ex-good-morning","slug":"good-morning","name":"Good Morning","description":"Barbell exercise for the hamstrings, with core, glutes, back assisting.","instructions":["Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.","Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.","Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["ABS_CORE","GLUTES","BACK"],"equipment":"BARBELL","tags":["good morning"],"media":[{"id":"good-morning-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Good_Morning/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"good-morning-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Good_Morning/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Good Morning","description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Rumpf, Po, Rücken.","instructions":["Stelle dich mit den Füßen mehr als schulterbreit auseinander hin (breiter Stand) und lege deine Hände auf die Hüften. Beuge dich aus der Hüfte und senke deinen Oberkörper in Richtung Boden, während du den Rücken gerade hältst, und richte dich anschließend wieder auf."]}},{"id":"ex-good-morning-off-pins","slug":"good-morning-off-pins","name":"Good Morning off Pins","description":"Barbell exercise for the hamstrings, with core, glutes, back assisting.","instructions":["Begin with a bar on a rack at about the same height as your stomach. Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.","Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight. Slowly lower the weight back to the pins returning to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["ABS_CORE","GLUTES","BACK"],"equipment":"BARBELL","tags":["good morning off pins"],"media":[{"id":"good-morning-off-pins-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Good_Morning_off_Pins/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"good-morning-off-pins-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Good_Morning_off_Pins/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Rumpf, Po, Rücken.","instructions":null}},{"id":"ex-gorilla-chin-crunch","slug":"gorilla-chin-crunch","name":"Gorilla Chin/Crunch","description":"Bodyweight exercise for the core, with biceps, back assisting.","instructions":["Hang from a chin-up bar using an underhand grip (palms facing you) that is slightly wider than shoulder width.","Now bend your knees at a 90 degree angle so that the calves are parallel to the floor while the thighs remain perpendicular to it. This will be your starting position.","As you exhale, pull yourself up while crunching your knees up at the same time until your knees are at chest level. You will stop going up as soon as your nose is at the same level as the bar. Tip: When you get to this point you should also be finishing the crunch at the same time.","Slowly start to inhale as you return to the starting position.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["BICEPS","BACK"],"equipment":"BODYWEIGHT","tags":["gorilla chin/crunch"],"media":[{"id":"gorilla-chin-crunch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Gorilla_Chin_Crunch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"gorilla-chin-crunch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Gorilla_Chin_Crunch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf, unterstützt von Bizeps, Rücken.","instructions":null}},{"id":"ex-groiners","slug":"groiners","name":"Groiners","description":"Bodyweight exercise for the quadriceps.","instructions":["Begin in a pushup position on the floor. This will be your starting position.","Using both legs, jump forward landing with your feet next to your hands. Keep your head up as you do so.","Return to the starting position and immediately repeat the movement, continuing for 10-20 repetitions."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["groiners"],"media":[{"id":"groiners-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Groiners/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"groiners-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Groiners/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-hack-squat","slug":"hack-squat","name":"Hack Squat","description":"Machine exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.","Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times.","Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).","Now straighten your legs without locking the knees. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).","Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"MACHINE","tags":["hack squat"],"media":[{"id":"hack-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hack_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hack-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hack_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-hammer-curls","slug":"hammer-curls","name":"Hammer Curls","description":"Dumbbell exercise for the biceps.","instructions":["Start: Hold dumbbells at your sides with palms facing your torso.","Curl: Lift the weights toward your shoulders while maintaining the neutral grip (like holding a hammer).","Squeeze: Contract the biceps at the top without moving your elbows forward.","Lower: Slowly return to the starting position with full control."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["hammer curls","hammercurls"],"media":[{"id":"hammer-curls-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/86/Bicep-hammer-curl-1.png","caption":"Hammer Curls","attribution":"wger.de · Everkinetic","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Hammercurls","description":"Übung (Kurzhantel) für den Bizeps.","instructions":["Greife zwei Hanteln, die Handflächen zeigen zum Körper.  Beuge die Arme und brige die Hanteln mit einer schnellen Bewegung nach oben wobei sie im Unterschied zu den normalen KH Curls nicht um 90 Grad gedreht werden, die Handflächen zeigen also die ganze Zeit nach innen. Ohne Pause wird das Gewicht nun kontrolliert nach unten gebracht. Beachte, dass die Bewegung nach oben schneller ist als nach unten.","Während des Bewegungablaufs darf der Körper nicht mitschwingen. Die Ellenbogen bleiben dabei immer an der Stelle."]}},{"id":"ex-hammer-grip-incline-db-bench-press","slug":"hammer-grip-incline-db-bench-press","name":"Hammer Grip Incline DB Bench Press","description":"Dumbbell exercise for the chest, with shoulders, triceps assisting.","instructions":["Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.","By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.","Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.","Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.","As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the dumbbells back in your thighs and then on the floor. This is the safest manner to dispose of the dumbbells."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"DUMBBELL","tags":["hammer grip incline db bench press"],"media":[{"id":"hammer-grip-incline-db-bench-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hammer_Grip_Incline_DB_Bench_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hammer-grip-incline-db-bench-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hammer_Grip_Incline_DB_Bench_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-hammercurls-on-cable","slug":"hammercurls-on-cable","name":"Hammercurls on Cable","description":"Cable exercise for the biceps.","instructions":["Take a cable in your hands (palms parallel, point to each other), the body is straight. Bend the arms and bring the weight up with a fast movement. Without any pause bring it back down with a slow, controlled movement, but don't stretch completely your arms.","Don't swing your body during the exercise, the biceps should do all the work here. The elbows are at your side and don't move."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["hammercurls on cable","hammercurls am seil"],"media":[{"id":"hammercurls-on-cable-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/138/Hammer-curls-with-rope-1.png","caption":"Hammercurls on Cable","attribution":"wger.de · Everkinetic","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Hammercurls am Seil","description":"Übung (Kabelzug) für den Bizeps.","instructions":["Nehme das Kabel in die Hände (Handflächen parallel, zeigen aufeinander), der Körper steht gerade und ist etwas vom Kabelzug entfernt.","Beuge nun die Arme und bringe das Kabel mit einer schnellen Bewegung nach oben. Ohne Pause wird das Gewicht nun kontrolliert nach unten gebracht (Arme aber nicht ganz austrecken). Während des Bewegungablaufs darf der Körper nicht mitschwingen. Die Ellenbogen bleiben dabei immer an der Stelle."]}},{"id":"ex-hamstring-kicks","slug":"hamstring-kicks","name":"Hamstring Kicks","description":"Bodyweight exercise for the hamstrings, with glutes assisting.","instructions":["Stand with your feet hip-width apart and extend one arm in front of you. Swing that leg up in front of you and back down while keeping your leg as straight as possible and your toes pointed up.Repeat with the other leg."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES"],"equipment":"BODYWEIGHT","tags":["hamstring kicks","hamstring-kicks"],"media":[{"id":"hamstring-kicks-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1387/a2cf7eda-5540-4105-b30e-1c2f2679a6c7.png","caption":"Hamstring Kicks","attribution":"wger.de · captive0592","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Hamstring-Kicks","description":"Übung (Körpergewicht) für die Oberschenkelrückseite, unterstützt von Po.","instructions":["Stehen Sie mit hüftbreit geöffneten Füßen. Schwingen Sie ein Bein vor und zurück, wobei Sie es so gerade wie möglich halten und die Zehen nach oben zeigen. Wiederholen Sie dies mit dem anderen Bein."]}},{"id":"ex-hamstring-smr","slug":"hamstring-smr","name":"Hamstring-SMR","description":"Foam roller exercise for the hamstrings.","instructions":["In a seated position, extend your legs over a foam roll so that it is position on the back of the upper legs. Place your hands to the side or behind you to help support your weight. This will be your starting position.","Using your hands, lift your hips off of the floor and shift your weight on the foam roll to one leg. Relax the hamstrings of the leg you are stretching.","Roll over the foam from below the hip to above the back of the knee, pausing at points of tension for 10-30 seconds. Repeat for the other leg."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":[],"equipment":"FOAM_ROLLER","tags":["hamstring-smr"],"media":[{"id":"hamstring-smr-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hamstring-SMR/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hamstring-smr-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hamstring-SMR/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Faszienrolle) für die Oberschenkelrückseite.","instructions":null}},{"id":"ex-hamstring-stretch","slug":"hamstring-stretch","name":"Hamstring Stretch","description":"Equipment-free exercise for the hamstrings.","instructions":["Lie on your back with one leg extended above you, with the hip at ninety degrees. Keep the other leg flat on the floor.","Loop a belt, band, or rope over the ball of your foot. This will be your starting position.","Pull on the belt to create tension in the calves and hamstrings. Hold this stretch for 10-30 seconds, and repeat with the other leg."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":[],"equipment":"NONE","tags":["hamstring stretch","hamstring-dehnung"],"media":[{"id":"hamstring-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hamstring_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hamstring-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hamstring_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Hamstring-Dehnung","description":"Übung (ohne Geräte) für die Oberschenkelrückseite.","instructions":["Setze dich auf den Boden. Strecke das rechte Bein lang vor dir aus. Winkle das linke Bein an und lege die linke Fußsohle an die Innenseite des rechten Oberschenkels (das Knie zeigt zur Seite). Richte deinen Oberkörper ganz aufrecht auf (Brust raus, Schultern zurück). Atme ein, und beuge dich beim Ausatmen aus der Hüfte (nicht aus dem unteren Rücken!) nach vorne über das gestreckte rechte Bein. Greife nach deinem Schienbein, Knöchel oder Fuß – je nachdem, was bei geradem Rücken möglich ist."]}},{"id":"ex-handstand-push-ups","slug":"handstand-push-ups","name":"Handstand Push-Ups","description":"Bodyweight exercise for the shoulders, with triceps assisting.","instructions":["With your back to the wall bend at the waist and place both hands on the floor at shoulder width.","Kick yourself up against the wall with your arms straight. Your body should be upside down with the arms and legs fully extended. Keep your whole body as straight as possible. Tip: If doing this for the first time, have a spotter help you. Also, make sure that you keep facing the wall with your head, rather than looking down.","Slowly lower yourself to the ground as you inhale until your head almost touches the floor. Tip: It is of utmost importance that you come down slow in order to avoid head injury.","Push yourself back up slowly as you exhale until your elbows are nearly locked.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"BODYWEIGHT","tags":["handstand push-ups"],"media":[{"id":"handstand-push-ups-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Handstand_Push-Ups/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"handstand-push-ups-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Handstand_Push-Ups/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-handstand-pushup","slug":"handstand-pushup","name":"Handstand Pushup","description":"Bodyweight exercise for the shoulders, with triceps, back assisting.","instructions":["The handstand push-up (press-up) - also called the vertical push-up (press-up) or the inverted push-up (press-up) also called commandos- is a type of push-up exercise where the body is positioned in a handstand. For a true handstand, the exercise is performed free-standing, held in the air. To prepare the strength until one has built adequate balance, the feet are often placed against a wall, held by a partner, or secured in some other way from falling. Handstand pushups require significant strength, as well as balance and control if performed free-standing."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS","BACK"],"equipment":"BODYWEIGHT","tags":["handstand pushup","handstand-liegestütz"],"media":[{"id":"handstand-pushup-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/282/f6121ac9-330e-4ed7-8219-91ce246bf871.png","caption":"Handstand Pushup","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Handstand-Liegestütz","description":"Übung (Körpergewicht) für die Schultern, unterstützt von Trizeps, Rücken.","instructions":["Der Handstand-Liegestütz, auch vertikaler Liegestütz oder umgekehrter Liegestütz genannt, ist eine Liegestütz-Variante, bei der sich der Körper im Handstand befindet. Bei einem echten Handstand wird die Übung freistehend ausgeführt und in der Luft gehalten. Um die Kraft aufzubauen, bis man genügend Gleichgewicht entwickelt hat, werden die Füße oft an eine Wand gelehnt, von einem Partner gehalten oder auf andere Weise gegen das Umfallen gesichert. Handstand-Liegestütze erfordern erhebliche Kraft sowie Gleichgewicht und Kontrolle, wenn sie freistehend ausgeführt werden."]}},{"id":"ex-hang-clean","slug":"hang-clean","name":"Hang Clean","description":"Barbell exercise for the quadriceps, with calves, forearms, glutes, hamstrings, back, shoulders assisting.","instructions":["Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.","Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","FOREARMS","GLUTES","HAMSTRINGS","BACK","SHOULDERS"],"equipment":"BARBELL","tags":["hang clean"],"media":[{"id":"hang-clean-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hang_Clean/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hang-clean-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hang_Clean/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Unterarme, Po, Oberschenkelrückseite, Rücken, Schultern.","instructions":null}},{"id":"ex-hang-clean-below-the-knees","slug":"hang-clean-below-the-knees","name":"Hang Clean - Below the Knees","description":"Barbell exercise for the quadriceps, with calves, forearms, glutes, hamstrings, back, shoulders assisting.","instructions":["Begin with a shoulder width, double overhand or hook grip, with the bar hanging just below the knees. Your back should be straight and inclined slightly forward.","Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out.","At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","FOREARMS","GLUTES","HAMSTRINGS","BACK","SHOULDERS"],"equipment":"BARBELL","tags":["hang clean - below the knees"],"media":[{"id":"hang-clean-below-the-knees-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hang_Clean_-_Below_the_Knees/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hang-clean-below-the-knees-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hang_Clean_-_Below_the_Knees/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Unterarme, Po, Oberschenkelrückseite, Rücken, Schultern.","instructions":null}},{"id":"ex-hang-snatch","slug":"hang-snatch","name":"Hang Snatch","description":"Barbell exercise for the hamstrings, with core, calves, forearms, glutes, back, quadriceps, shoulders assisting.","instructions":["Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be at the hips. This will be your starting position.","Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead.","Return to a standing position with the weight overhead. Follow by returning the weight to the ground under control."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["ABS_CORE","CALVES","FOREARMS","GLUTES","BACK","QUADRICEPS","SHOULDERS"],"equipment":"BARBELL","tags":["hang snatch"],"media":[{"id":"hang-snatch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hang_Snatch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hang-snatch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hang_Snatch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Rumpf, Waden, Unterarme, Po, Rücken, Oberschenkelvorderseite, Schultern.","instructions":null}},{"id":"ex-hang-snatch-below-knees","slug":"hang-snatch-below-knees","name":"Hang Snatch - Below Knees","description":"Barbell exercise for the hamstrings, with core, calves, forearms, glutes, back, quadriceps, shoulders assisting.","instructions":["Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be just below the knees. This will be your starting position.","Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead.","Return to a standing position with the weight overhead, and then return the weight to the floor under control."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["ABS_CORE","CALVES","FOREARMS","GLUTES","BACK","QUADRICEPS","SHOULDERS"],"equipment":"BARBELL","tags":["hang snatch - below knees"],"media":[{"id":"hang-snatch-below-knees-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hang_Snatch_-_Below_Knees/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hang-snatch-below-knees-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hang_Snatch_-_Below_Knees/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Rumpf, Waden, Unterarme, Po, Rücken, Oberschenkelvorderseite, Schultern.","instructions":null}},{"id":"ex-hanging-bar-good-morning","slug":"hanging-bar-good-morning","name":"Hanging Bar Good Morning","description":"Barbell exercise for the hamstrings, with core, glutes, back assisting.","instructions":["Begin with a bar on a rack at about the same height as your stomach. Suspend the bar using chains or suspension straps.","Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your traps. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.","Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight.","Slowly lower the weight back to the starting position, where it is supported by the chains."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["ABS_CORE","GLUTES","BACK"],"equipment":"BARBELL","tags":["hanging bar good morning"],"media":[{"id":"hanging-bar-good-morning-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Bar_Good_Morning/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hanging-bar-good-morning-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Bar_Good_Morning/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Rumpf, Po, Rücken.","instructions":null}},{"id":"ex-hanging-pike","slug":"hanging-pike","name":"Hanging Pike","description":"Bodyweight exercise for the core.","instructions":["Hang from a chin-up bar with your legs and feet together using an overhand grip (palms facing away from you) that is slightly wider than shoulder width. Tip: You may use wrist wraps in order to facilitate holding on to the bar.","Now bend your knees at a 90 degree angle and bring the upper legs forward so that the calves are perpendicular to the floor while the thighs remain parallel to it. This will be your starting position.","Pull your legs up as you exhale until you almost touch your shins with the bar above you. Tip: Try to straighten your legs as much as possible while at the top.","Lower your legs as slowly as possible until you reach the starting position. Tip: Avoid swinging and using momentum at all times.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["hanging pike"],"media":[{"id":"hanging-pike-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Pike/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hanging-pike-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Pike/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-head-tilts","slug":"head-tilts","name":"Head tilts","description":"Bodyweight exercise for the back.","instructions":["Starting position:","Sit or stand with your back straight.","Steps:","Tilt your head to one side and hold for a bit.","Return your head to neutral position and hold for a bit.","Tilt your head to the other side and hold for a bit.","Return your head to neutral position yet again and hold for a bit.","Repeat."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["head tilts","kopf neigen"],"media":[{"id":"head-tilts-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1018/5bbd3879-b6fc-4aaa-9e8e-33ae9a688112.png","caption":"Head tilts","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Kopf neigen","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Ausgangsposition:","Sitzen oder stehen Sie mit geradem Rücken.","Schritte:","Neigen Sie den Kopf zu einer Seite und halten Sie ihn ein wenig.","Bringen Sie den Kopf in die neutrale Position zurück und halten Sie ihn kurz.","Neigen Sie den Kopf auf die andere Seite und halten Sie ihn kurz.","Bringen Sie den Kopf wieder in die neutrale Position und halten Sie ihn ein wenig.","Wiederholen Sie die Übung."]}},{"id":"ex-head-turns","slug":"head-turns","name":"Head turns","description":"Bodyweight exercise for the shoulders.","instructions":["Starting position:","Sit or stand with your back straight and shoulders down.","Steps:","Sit or stand up straight, shoulders dropped.","Turn your head to the side as far as possible. Stop when you hit a barrier and hold for 5 seconds.","Return to center position and repeat, changing sides."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["head turns","kopf drehen"],"media":[{"id":"head-turns-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1007/757846d3-78e4-4068-bbca-62e567372c94.png","caption":"Head turns","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Kopf drehen","description":"Übung (Körpergewicht) für die Schultern.","instructions":["Ausgangsposition:","Sitzen oder stehen Sie mit geradem Rücken und Schultern nach unten.","Schritte:","Setzen oder stellen Sie sich gerade hin, die Schultern sind gesenkt.","Drehen Sie Ihren Kopf so weit wie möglich zur Seite. Halten Sie an, wenn Sie auf ein Hindernis stoßen, und bleiben Sie 5 Sekunden lang stehen.","Kehren Sie in die Mittelposition zurück und wiederholen Sie den Vorgang, wobei Sie die Seite wechseln."]}},{"id":"ex-heaving-snatch-balance","slug":"heaving-snatch-balance","name":"Heaving Snatch Balance","description":"Barbell exercise for the quadriceps, with core, forearms, glutes, hamstrings, shoulders, triceps assisting.","instructions":["This drill helps you learn the snatch. Begin by holding a light weight across the back of the shoulders. Your feet should be slightly wider than hip width apart with the feet turned out, the same position that you would perform a squat with.","Begin by dipping with the knees slightly, and popping back up to briefly unload the bar. Drive yourself underneath the bar, elevating it overhead as you descend into a full squat.","Return to a standing position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["ABS_CORE","FOREARMS","GLUTES","HAMSTRINGS","SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["heaving snatch balance"],"media":[{"id":"heaving-snatch-balance-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Heaving_Snatch_Balance/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"heaving-snatch-balance-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Heaving_Snatch_Balance/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Rumpf, Unterarme, Po, Oberschenkelrückseite, Schultern, Trizeps.","instructions":null}},{"id":"ex-heavy-bag-thrust","slug":"heavy-bag-thrust","name":"Heavy Bag Thrust","description":"Accessory exercise for the chest, with core, shoulders, triceps assisting.","instructions":["Utilize a heavy bag for this exercise. Assume an upright stance next to the bag, with your feet staggered, fairly wide apart. Place your hand on the bag at about chest height. This will be your starting position.","Begin by twisting at the waist, pushing the bag forward as hard as possible. Perform this move quickly, pushing the bag away from your body.","Receive the bag as it swings back by reversing these steps."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["ABS_CORE","SHOULDERS","TRICEPS"],"equipment":"OTHER","tags":["heavy bag thrust"],"media":[{"id":"heavy-bag-thrust-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Heavy_Bag_Thrust/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"heavy-bag-thrust-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Heavy_Bag_Thrust/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Brust, unterstützt von Rumpf, Schultern, Trizeps.","instructions":null}},{"id":"ex-heel-touches","slug":"heel-touches","name":"Heel Touches","description":"Bodyweight exercise for the core.","instructions":["Starting Position:","Lie on your back on an exercise mat.","Bend your knees, keeping your feet flat on the floor and hip-width apart.","Place your arms along your sides, palms facing inward, just off the floor.","Engage Core:","Lift your head, shoulders, and upper back slightly off the ground.","Keep your neck neutral and chin slightly tucked.","Perform the Movement:"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["heel touches","fersenberührungen"],"media":[],"source":"wger","de":{"name":"Fersenberührungen","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Startposition:","Lege dich auf dem Rücken auf eine Trainingsmatte.","Beuge deine Knie und halte deine Füße flach auf dem Boden, hüftbreit auseinander.","Lege deine Arme seitlich an deinen Körper, die Handflächen nach innen gerichtet, knapp über dem Boden.","Rumpf anspannen:","Hebe deinen Kopf, deine Schultern und deinen oberen Rücken leicht vom Boden ab.","Halte deinen Nacken neutral und das Kinn leicht eingezogen.","Bewegung ausführen:"]}},{"id":"ex-high-cable-cross-tricep-extention-nb","slug":"high-cable-cross-tricep-extention-nb","name":"High-Cable Cross Tricep Extention - NB","description":"Cable exercise for the triceps.","instructions":["The high-cable cross tricep extension is an isolation exercise for targeting the triceps,","particularly the long head. It utilizes cables and handles grasped with opposite hands, allowing for a unique pressing motion that can be effective for building tricep strength. Unlike exercises that use a straight bar or rope, this variation can be more comfortable on your wrists and elbows"],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["high-cable cross tricep extention - nb","trizepsstrecken über kreuz am hohen kabelzug"],"media":[{"id":"high-cable-cross-tricep-extention-nb-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1298/ec4b83ec-5a8f-4303-9050-99ec4389bc2a.png","caption":"High-Cable Cross Tricep Extention - NB","attribution":"wger.de · JackSparrow","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Trizepsstrecken über Kreuz am hohen Kabelzug","description":"Übung (Kabelzug) für den Trizeps.","instructions":["Das Trizepsstrecken über Kreuz am hohen Kabelzug ist eine Isolationsübung, um gezielt den Trizeps zu trainieren,","besonders den langen Kopf. Dabei werden Kabel und Griffe mit den jeweils gegenüberliegenden Händen gefasst, was eine besondere Drückbewegung ermöglicht, die wirksam für den Aufbau der Trizepskraft sein kann. Anders als bei Übungen mit gerader Stange oder Seil ist diese Variante oft angenehmer für deine Handgelenke und Ellbogen."]}},{"id":"ex-high-cable-lateral-raise","slug":"high-cable-lateral-raise","name":"High-Cable Lateral Raise","description":"Cable exercise for the shoulders, with back, chest assisting.","instructions":["Stand next to a cable machine with the pulley set to waist height.","Grab the opposite-side handle with the hand farthest from the","pulley, keeping your palm facing in.","Keep your core engaged, chest lifted, and shoulders relaxed. Maintain a slight bend in the elbow throughout the lift.","Lift your arm out to the side until your elbow reaches shoulder height, keeping your wrist aligned with your elbow.","Briefly pause at the top, then slowly lower the handle back to your side with control. Repeat for the desired reps."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK","CHEST"],"equipment":"CABLE","tags":["high-cable lateral raise","seitheben am hohen kabelzug"],"media":[],"source":"wger","de":{"name":"Seitheben am hohen Kabelzug","description":"Übung (Kabelzug) für die Schultern, unterstützt von Rücken, Brust.","instructions":["Stelle dich neben eine Kabelzugmaschine, mit der Rolle auf Hüfthöhe eingestellt.","Greife den Griff der gegenüberliegenden Seite mit der Hand, die am weitesten von der Rolle entfernt ist, und halte deine Handfläche nach innen.","Halte deinen Rumpf angespannt, die Brust aufgerichtet und die Schultern entspannt. Behalte während des gesamten Hebens eine leichte Beugung im Ellenbogen bei.","Hebe deinen Arm zur Seite an, bis dein Ellenbogen Schulterhöhe erreicht, und halte dein Handgelenk auf einer Linie mit deinem Ellenbogen.","Halte am obersten Punkt kurz inne und senke den Griff dann langsam und kontrolliert wieder zu deiner Seite. Wiederhole für die gewünschte Anzahl an Wiederholungen."]}},{"id":"ex-high-plank","slug":"high-plank","name":"High plank","description":"Bodyweight exercise for the core, with shoulders, triceps assisting.","instructions":["Starting position:","Get into the high plank position:your hands and toes should be touching the ground, your back, arms and legs should be straight.To get to this position, you can lie down on your stomach, place your hands facing down next to your head, and lifting your arms up until they are straight.","Steps:","Maintain the starting position for the entire duration of the exercise."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BODYWEIGHT","tags":["high plank","hohe planke"],"media":[],"source":"wger","de":{"name":"Hohe Planke","description":"Übung (Körpergewicht) für den Rumpf, unterstützt von Schultern, Trizeps.","instructions":["Ausgangsposition:","Nehmen Sie die hohe Planke ein:Ihre Hände und Zehen sollten den Boden berühren, Ihr Rücken, Ihre Arme und Beine sollten gerade sein.Um in diese Position zu gelangen, können Sie sich auf den Bauch legen, die Hände mit dem Gesicht nach unten neben den Kopf legen und die Arme anheben, bis sie gerade sind.","Die Schritte:","Behalten Sie die Ausgangsposition während der gesamten Dauer der Übung bei."]}},{"id":"ex-high-pulley-pullover","slug":"high-pulley-pullover","name":"High-pulley pullover","description":"Cable exercise for the back, with chest assisting.","instructions":["Stand facing the machine, feet slightly apart, gripping the bar with an overhand grip, arms extended, hands shoulder-width apart.","Keeping your back fixed and your abdominal muscles contracted, inhale and bring the bar down to your thighs while keeping your arms extended (or your elbows slightly bent).","Exhale at the end of the movement."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["CHEST"],"equipment":"CABLE","tags":["high-pulley pullover","pullover am hohen kabelzug"],"media":[{"id":"high-pulley-pullover-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1137/42f22229-c0a0-4bfc-aca6-66fe5e1ab10d.PNG","caption":"High-pulley pullover","attribution":"wger.de · Franpol","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Pullover am hohen Kabelzug","description":"Übung (Kabelzug) für den Rücken, unterstützt von Brust.","instructions":["Stehend, mit dem Gesicht zum Gerät, die Füße leicht auseinander, die Stange im Obergriff gefasst, die Arme gestreckt, die Hände schulterbreit auseinander.","Bei fixiertem Rücken und angespannter Bauchmuskulatur einatmen und die Stange bis zu den Oberschenkeln führen, während du die Arme gestreckt hältst (oder die Ellbogen leicht gebeugt).","Am Ende der Bewegung ausatmen."]}},{"id":"ex-hindu-pushups","slug":"hindu-pushups","name":"Hindu Pushups","description":"Bodyweight exercise for the shoulders, with chest, triceps assisting.","instructions":["Exercise to strengthen the shoulders and pectorals. Its name is due to the fact that it begins in the Yoga position \"Dog Facing Down\", passing to \"Cobra\" but without resting the legs or torso on the ground to finally end with a normal flexion. The exercise can also be performed backwards (back to the starting position). As a variation, after doing the push-up, the hip can be raised to return to downward facing dog."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CHEST","TRICEPS"],"equipment":"BODYWEIGHT","tags":["hindu pushups","hindu-liegestütze"],"media":[{"id":"hindu-pushups-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1080/c4bf7ba1-6058-4d14-928f-7187885d5d57.webp","caption":"Hindu Pushups","attribution":"wger.de · Imobard","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Hindu-Liegestütze","description":"Übung (Körpergewicht) für die Schultern, unterstützt von Brust, Trizeps.","instructions":["Übung zur Kräftigung der Schultern und der Brustmuskulatur. Ihr Name rührt daher, dass sie in der Yoga-Position \"herabschauender Hund\" beginnt, in die \"Kobra\" übergeht, jedoch ohne die Beine oder den Oberkörper auf dem Boden abzulegen, um schließlich mit einem normalen Liegestütz zu enden. Die Übung kann auch rückwärts ausgeführt werden (zurück in die Ausgangsposition). Als Variation kann nach dem Liegestütz die Hüfte angehoben werden, um in den herabschauenden Hund zurückzukehren."]}},{"id":"ex-hindu-squats","slug":"hindu-squats","name":"Hindu Squats","description":"Bodyweight exercise for the quadriceps, with glutes assisting.","instructions":["Start with your feet shoulder width apart and arms slightly behind your back.","As you descend towards the floor, raise your heels off the ground, while keeping your back as vertical  as possible.","Upon attaining the bottom position, touch the hands to the heels.","Then stand up ending with the heels on the ground, arms extended in front of the chest then rowing into the start position."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES"],"equipment":"BODYWEIGHT","tags":["hindu squats","hindu-kniebeugen"],"media":[],"source":"wger","de":{"name":"Hindu-Kniebeugen","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Po.","instructions":["Beginne mit schulterbreit aufgestellten Füßen und den Armen leicht hinter dem Rücken.","Während du dich zum Boden absenkst, hebe die Fersen vom Boden ab und halte den Rücken dabei so senkrecht wie möglich.","Wenn du die unterste Position erreichst, berühre mit den Händen die Fersen.","Richte dich anschließend wieder auf, sodass du am Ende mit den Fersen auf dem Boden stehst und die Arme vor der Brust gestreckt hast, und ziehe sie dann in die Ausgangsposition zurück."]}},{"id":"ex-hip-bridge","slug":"hip-bridge","name":"Hip Bridge","description":"Bodyweight exercise for the glutes, with core assisting.","instructions":["Get into bridge position, balance yourself on heels and start extending legs unilaterally.","Keep hip extended as much as possible."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["ABS_CORE"],"equipment":"BODYWEIGHT","tags":["hip bridge","hüftbrücke"],"media":[],"source":"wger","de":{"name":"Hüftbrücke","description":"Übung (Körpergewicht) für den Po, unterstützt von Rumpf.","instructions":["Gehe in die Brückenposition, balanciere dich auf den Fersen und beginne, die Beine einseitig zu strecken.","Halte die Hüfte so weit wie möglich gestreckt."]}},{"id":"ex-hip-circles-prone","slug":"hip-circles-prone","name":"Hip Circles (prone)","description":"Bodyweight exercise for the glutes, with quadriceps assisting.","instructions":["Position yourself on your hands and knees on the ground. Maintaining good posture, raise one bent knee off of the ground. This will be your starting position.","Keeping the knee in a bent position, rotate the femur in an arc, attempting to make a big circle with your knee.","Perform this slowly for a number of repetitions, and repeat on the other side."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["QUADRICEPS"],"equipment":"BODYWEIGHT","tags":["hip circles (prone)"],"media":[{"id":"hip-circles-prone-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hip_Circles_prone/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hip-circles-prone-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hip_Circles_prone/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelvorderseite.","instructions":null}},{"id":"ex-hip-extension-with-bands","slug":"hip-extension-with-bands","name":"Hip Extension with Bands","description":"Resistance band exercise for the glutes, with hamstrings assisting.","instructions":["Secure one end of the band to the lower portion of a post and attach the other to one ankle.","Facing the attachment point of the band, hold on to the column to stabilize yourself.","Keeping your head and your chest up, move the resisted leg back as far as you can while keeping the knee straight.","Return the leg to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["HAMSTRINGS"],"equipment":"BAND","tags":["hip extension with bands"],"media":[{"id":"hip-extension-with-bands-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hip_Extension_with_Bands/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hip-extension-with-bands-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hip_Extension_with_Bands/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Widerstandsband) für den Po, unterstützt von Oberschenkelrückseite.","instructions":null}},{"id":"ex-hip-flexion-with-band","slug":"hip-flexion-with-band","name":"Hip Flexion with Band","description":"Resistance band exercise for the quadriceps.","instructions":["Secure one end of the band to the lower portion of a post and attach the other to one ankle.","Face away from the attachment point of the band.","Keeping your head and your chest up, raise your knee up to 90 degrees and pause.","Return the leg to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"BAND","tags":["hip flexion with band"],"media":[{"id":"hip-flexion-with-band-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hip_Flexion_with_Band/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hip-flexion-with-band-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hip_Flexion_with_Band/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Widerstandsband) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-hip-hinge","slug":"hip-hinge","name":"Hip hinge","description":"Barbell exercise for the hamstrings, with glutes, calves, quadriceps, core assisting.","instructions":["Hip Hinge Exercise Description","The hip hinge is a fundamental movement pattern that involves bending at the hips while keeping the spine neutral. It is commonly used in exercises like deadlifts, kettlebell swings, and good mornings. To perform a hip hinge:","Starting Position: Stand with your feet hip-width apart and a slight bend in your knees.","Hinge at the Hips: Push your hips back while maintaining a straight back. Your torso should lean forward, and your chest should stay up.","Lowering Phase: Continue to hinge until your torso is nearly parallel to the ground, or until you feel a stretch in your hamstrings.","Return to Standing: Drive through your heels and thrust your hips forward to return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","CALVES","QUADRICEPS","ABS_CORE"],"equipment":"BARBELL","tags":["hip hinge"],"media":[],"source":"wger","de":{"name":"Hip Hinge","description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Po, Waden, Oberschenkelvorderseite, Rumpf.","instructions":["Beschreibung der Übung Hip Hinge","Der Hip Hinge ist ein grundlegendes Bewegungsmuster, bei dem du dich in den Hüften beugst, während die Wirbelsäule neutral bleibt. Er wird häufig bei Übungen wie Kreuzheben, Kettlebell-Swings und Good Mornings eingesetzt. So führst du einen Hip Hinge aus:","Ausgangsposition: Stelle dich hüftbreit hin und beuge die Knie leicht.","Beuge in den Hüften: Schiebe deine Hüften nach hinten, während du den Rücken gerade hältst. Dein Oberkörper neigt sich nach vorn, und dein Brustkorb bleibt aufgerichtet.","Absenkphase: Beuge dich weiter, bis dein Oberkörper nahezu parallel zum Boden ist oder bis du eine Dehnung in der hinteren Oberschenkelmuskulatur spürst.","Zurück in den Stand: Drücke dich über die Fersen ab und schiebe deine Hüften nach vorn, um in die Ausgangsposition zurückzukehren."]}},{"id":"ex-hip-lift-with-band","slug":"hip-lift-with-band","name":"Hip Lift with Band","description":"Resistance band exercise for the glutes, with calves, hamstrings assisting.","instructions":["After choosing a suitable band, lay down in the middle of the rack, after securing the band on either side of you. If your rack doesn't have pegs, the band can be secured using heavy dumbbells or similar objects, just ensure they won't move.","Adjust your position so that the band is directly over your hips. Bend your knees and place your feet flat on the floor. Your hands can be on the floor or holding the band in position.","Keeping your shoulders on the ground, drive through your heels to raise your hips, pushing into the band as high as you can.","Pause at the top of the motion, and return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["CALVES","HAMSTRINGS"],"equipment":"BAND","tags":["hip lift with band"],"media":[{"id":"hip-lift-with-band-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hip_Lift_with_Band/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hip-lift-with-band-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hip_Lift_with_Band/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Widerstandsband) für den Po, unterstützt von Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-hip-raise-lying","slug":"hip-raise-lying","name":"Hip Raise, Lying","description":"Bodyweight exercise for the glutes, with hamstrings assisting.","instructions":["Lying down on your back, with your feet flat on the floor. Raise your hips up evenly as high as you can and hold for as long as you can."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["hip raise, lying","hüftheben in rückenlage"],"media":[],"source":"wger","de":{"name":"Hüftheben in Rückenlage","description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelrückseite.","instructions":["Lege dich auf den Rücken, die Füße flach auf dem Boden. Hebe deine Hüfte gleichmäßig so hoch wie möglich an und halte die Position so lange wie möglich."]}},{"id":"ex-hip-thrust","slug":"hip-thrust","name":"Hip Thrust","description":"Barbell exercise for the glutes.","instructions":["The bar should go directly on your upper thigh, directly below your crotch. Your feet should be directly under your knees. Push your hips up so that you form a straight line from your knees to your shoulders. Use a pad for comfort."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["hip thrust","beckenheben"],"media":[],"source":"wger","de":{"name":"Beckenheben","description":"Übung (Langhantel) für den Po.","instructions":["Setze dich auf den Boden mit einer Bank hinter dir, beuge die Knie, sodass deine Füße flach auf dem Boden stehen, und halte eine Langhantel, die unterhalb deiner Hüfte aufliegt. Wenn du eine gepolsterte Stange hast oder etwas, das du zwischen Stange und Körper schieben kannst, trägt das viel dazu bei, die Übung angenehmer zu machen."]}},{"id":"ex-horizontal-shoulder-flexion-stretch","slug":"horizontal-shoulder-flexion-stretch","name":"Horizontal Shoulder Flexion Stretch","description":"Bodyweight exercise for the chest, with shoulders assisting.","instructions":["Raise your arm out to the side, placing your hand on a wall or doorway beside you at shoulder height","Turn your body away from your arm to stretch the chest, as far as is comfortable"],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS"],"equipment":"BODYWEIGHT","tags":["horizontal shoulder flexion stretch","dehnung der horizontalen schulterflexion"],"media":[],"source":"wger","de":{"name":"Dehnung der horizontalen Schulterflexion","description":"Übung (Körpergewicht) für die Brust, unterstützt von Schultern.","instructions":["Hebe deinen Arm zur Seite an und lege deine Hand auf Schulterhöhe an eine Wand oder einen Türrahmen neben dir","Drehe deinen Körper von deinem Arm weg, um die Brust zu dehnen, so weit es angenehm ist"]}},{"id":"ex-horse-stance-side-splits","slug":"horse-stance-side-splits","name":"Horse Stance (Side Splits)","description":"Bodyweight exercise for the glutes.","instructions":["Stand as for a squat, with your feet wide and your toes pointed slightly outwards.","Gently squat into a deep, wide squat - your hips should be below your knees.","Hold for 3 to 5 seconds.","Come up under control, and repeat as needed."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["horse stance (side splits)","reiterstellung (seitspagat)"],"media":[],"source":"wger","de":{"name":"Reiterstellung (Seitspagat)","description":"Übung (Körpergewicht) für den Po.","instructions":["Stelle dich wie für eine Kniebeuge hin, mit weit auseinanderstehenden Füßen und leicht nach außen gedrehten Fußspitzen.","Gehe sanft in eine tiefe, breite Kniebeuge – deine Hüften sollten unter deinen Knien sein.","Halte 3 bis 5 Sekunden.","Komme kontrolliert wieder hoch und wiederhole nach Bedarf."]}},{"id":"ex-hug-a-ball","slug":"hug-a-ball","name":"Hug A Ball","description":"Accessory exercise for the back, with calves, glutes assisting.","instructions":["Seat yourself on the floor.","Straddle an exercise ball between both legs and lower your hips down toward the floor.","Hug your arms around the ball to support your body. Adjust your legs so that your feet are flat on the floor and your knees line up over your ankles. Keep a good grip on the ball so it doesn't roll away from you and send you back onto your buttocks."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["CALVES","GLUTES"],"equipment":"OTHER","tags":["hug a ball"],"media":[{"id":"hug-a-ball-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hug_A_Ball/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hug-a-ball-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hug_A_Ball/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Waden, Po.","instructions":null}},{"id":"ex-hurdle-hops","slug":"hurdle-hops","name":"Hurdle Hops","description":"Accessory exercise for the hamstrings, with glutes, quadriceps, calves assisting.","instructions":["Set up a row of hurdles or other small barriers, placing them a few feet apart.","Stand in front of the first hurdle with your feet shoulder width apart. This will be your starting position.","Begin by jumping with both feet over the first hurdle, swinging both arms as you jump.","Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next hurdle. Continue until you have jumped over all of the hurdles."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","QUADRICEPS","CALVES"],"equipment":"OTHER","tags":["hurdle hops"],"media":[{"id":"hurdle-hops-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hurdle_Hops/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hurdle-hops-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hurdle_Hops/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelrückseite, unterstützt von Po, Oberschenkelvorderseite, Waden.","instructions":null}},{"id":"ex-hyper-y-w-combo","slug":"hyper-y-w-combo","name":"Hyper Y W Combo","description":"Bodyweight exercise for the back.","instructions":["Use a glute-ham raise or a","stability ball for this exercise and a light weight plate in each hand.","Raise your torso to form a straight line with your legs and raise the","arms outward slightly beyond a 90-degree angle into a W position to hit","the rotator cuff muscles, and then lower back to the starting position.","Then raise up again with arms","in a Y position to activate the lower traps."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["hyper y w combo","hyper y-w-kombination"],"media":[],"source":"wger","de":{"name":"Hyper Y-W-Kombination","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Nutze einen Glute-Ham-Raise oder einen","Gymnastikball für diese Übung und eine leichte Gewichtsscheibe in jeder Hand.","Hebe deinen Oberkörper an, sodass er eine gerade Linie mit deinen Beinen bildet, und hebe die","Arme leicht über einen 90-Grad-Winkel hinaus nach außen in eine W-Position, um","die Muskeln der Rotatorenmanschette anzusprechen, und senke dann wieder in die Ausgangsposition ab.","Hebe dich dann erneut an, mit den Armen","in einer Y-Position, um den unteren Trapezius zu aktivieren."]}},{"id":"ex-hyperextensions-with-no-hyperextension-bench","slug":"hyperextensions-with-no-hyperextension-bench","name":"Hyperextensions With No Hyperextension Bench","description":"Bodyweight exercise for the back, with glutes, hamstrings assisting.","instructions":["With someone holding down your legs, slide yourself down to the edge a flat bench until your hips hang off the end of the bench. Tip: Your entire upper body should be hanging down towards the floor. Also, you will be in the same position as if you were on a hyperextension bench but the range of motion will be shorter due to the height of the flat bench vs. that of the hyperextension bench.","With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.","Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you almost touch the floor or you feel a nice stretch on the hamstrings (whichever comes first). Tip: Never round the back as you perform this exercise.","Slowly raise your torso back to the initial position as you exhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["GLUTES","HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["hyperextensions with no hyperextension bench"],"media":[{"id":"hyperextensions-with-no-hyperextension-bench-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hyperextensions_With_No_Hyperextension_Bench/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"hyperextensions-with-no-hyperextension-bench-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hyperextensions_With_No_Hyperextension_Bench/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rücken, unterstützt von Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-ice-cream-maker","slug":"ice-cream-maker","name":"Ice cream maker","description":"Bodyweight exercise for the back, with core assisting.","instructions":["From the final phase of a pull-up, we push ourselves back with our shoulders until we reach the front lever position. From there, we pull ourselves back up to the starting position."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["ABS_CORE"],"equipment":"BODYWEIGHT","tags":["ice cream maker","ice scream maker"],"media":[],"source":"wger","de":{"name":"Ice Scream Maker","description":"Übung (Körpergewicht) für den Rücken, unterstützt von Rumpf.","instructions":["Aus der Endphase eines Klimmzugs drücken wir uns mit den Schultern zurück, bis wir die Front-Lever-Position erreichen. Von dort ziehen wir uns zurück in die Ausgangsposition hoch."]}},{"id":"ex-iliotibial-tract-smr","slug":"iliotibial-tract-smr","name":"Iliotibial Tract-SMR","description":"Foam roller exercise for the glutes.","instructions":["Lay on your side, with the bottom leg placed onto a foam roller between the hip and the knee. The other leg can be crossed in front of you.","Place as much of your weight as is tolerable onto your bottom leg; there is no need to keep your bottom leg in contact with the ground. Be sure to relax the muscles of the leg you are stretching.","Roll your leg over the foam from you hip to your knee, pausing for 10-30 seconds at points of tension. Repeat with the opposite leg."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":[],"equipment":"FOAM_ROLLER","tags":["iliotibial tract-smr"],"media":[{"id":"iliotibial-tract-smr-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Iliotibial_Tract-SMR/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"iliotibial-tract-smr-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Iliotibial_Tract-SMR/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Faszienrolle) für den Po.","instructions":null}},{"id":"ex-inchworm","slug":"inchworm","name":"Inchworm","description":"Bodyweight exercise for the hamstrings.","instructions":["Stand with your feet close together. Keeping your legs straight, stretch down and put your hands on the floor directly in front of you. This will be your starting position.","Begin by walking your hands forward slowly, alternating your left and your right. As you do so, bend only at the hip, keeping your legs straight.","Keep going until your body is parallel to the ground in a pushup position.","Now, keep your hands in place and slowly take short steps with your feet, moving only a few inches at a time.","Continue walking until your feet are by hour hands, keeping your legs straight as you do so."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["inchworm"],"media":[{"id":"inchworm-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Inchworm/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"inchworm-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Inchworm/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelrückseite.","instructions":null}},{"id":"ex-incline-barbell-triceps-extension","slug":"incline-barbell-triceps-extension","name":"Incline Barbell Triceps Extension","description":"Barbell exercise for the triceps, with forearms assisting.","instructions":["Hold a barbell with an overhand grip (palms down) that is a little closer together than shoulder width.","Lie back on an incline bench set at any angle between 45-75-degrees.","Bring the bar overhead with your arms extended and elbows in. The arms should be in line with the torso above the head. This will be your starting position.","Now lower the bar in a semicircular motion behind your head until your forearms touch your biceps. Inhale as you perform this movement. Tip: Keep your upper arms stationary and close to your head at all times. Only the forearms should move.","Return to the starting position as you breathe out and you contract the triceps. Hold the contraction for a second.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"BARBELL","tags":["incline barbell triceps extension"],"media":[{"id":"incline-barbell-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Barbell_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"incline-barbell-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Barbell_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Trizeps, unterstützt von Unterarme.","instructions":null}},{"id":"ex-incline-bench-pull","slug":"incline-bench-pull","name":"Incline Bench Pull","description":"Barbell exercise for the back, with shoulders assisting.","instructions":["Grab a dumbbell in each hand and lie face down on an incline bench that is set to an incline that is approximately 30 degrees.","Let the arms hang to your sides fully extended as they point to the floor.","Turn the wrists until your hands have a pronated (palms down) grip.","Now flare the elbows out. This will be your starting position.","As you breathe out, start to pull the dumbbells up as if you are doing a reverse bench press. You will do this by bending at the elbows and bringing the upper arms up as you let the forearms hang. Continue this motion until the upper arms are at the same level as your back. Tip: The elbows will come out to the side and your upper arms and torso should make the letter \"T\" at the top of the movement. Hold the contraction at the top for a second.","Slowly go back down to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["SHOULDERS"],"equipment":"BARBELL","tags":["incline bench pull"],"media":[{"id":"incline-bench-pull-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Bench_Pull/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"incline-bench-pull-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Bench_Pull/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Schultern.","instructions":null}},{"id":"ex-incline-bench-reverse-fly","slug":"incline-bench-reverse-fly","name":"Incline Bench Reverse Fly","description":"Dumbbell exercise for the shoulders, with back assisting.","instructions":["The incline dumbbell reverse fly is an upper-body exercise targeting the posterior or rear deltoids, as well as the postural muscles of the upper back. Because it targets such small muscles, this exercise is usually performed with light weight for high reps, such as 10-15 reps per set or more."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"DUMBBELL","tags":["incline bench reverse fly","reverse fly auf der schrägbank"],"media":[{"id":"incline-bench-reverse-fly-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/828/2e959dab-f39b-4c7c-9063-eb43064ab5eb.png","caption":"Incline Bench Reverse Fly","attribution":"wger.de · cshep442","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Reverse Fly auf der Schrägbank","description":"Übung (Kurzhantel) für die Schultern, unterstützt von Rücken.","instructions":["Der Reverse Fly mit Kurzhanteln auf der Schrägbank ist eine Übung für den Oberkörper, die die hinteren Deltamuskeln sowie die Haltemuskulatur des oberen Rückens beansprucht. Da sie so kleine Muskeln anspricht, wird diese Übung üblicherweise mit leichtem Gewicht und vielen Wiederholungen ausgeführt, etwa 10-15 Wiederholungen pro Satz oder mehr."]}},{"id":"ex-incline-cable-chest-press","slug":"incline-cable-chest-press","name":"Incline Cable Chest Press","description":"Cable exercise for the chest, with shoulders, triceps assisting.","instructions":["Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.","Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.","After pausing at full extension, return to the starting position, keeping tension on the cables."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"CABLE","tags":["incline cable chest press","brustdrücken am kabelzug auf der schrägbank"],"media":[{"id":"incline-cable-chest-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Cable_Chest_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"incline-cable-chest-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Cable_Chest_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Brustdrücken am Kabelzug auf der Schrägbank","description":"Übung (Kabelzug) für die Brust, unterstützt von Schultern, Trizeps.","instructions":["Einarmiges Brustdrücken am Kabelzug. Nutze den anderen Arm, um den Körper abzustützen, damit du dich auf die Kraft beim Drücken konzentrieren kannst und nicht auf das Ausbalancieren des Körpers. Beginne mit der Hand so nah wie möglich an der Brust und drücke dann gegen das Kabel in einem leichten Schrägwinkel, wobei du zur Mitte deiner Brust hin zielst."]}},{"id":"ex-incline-cable-flye","slug":"incline-cable-flye","name":"Incline Cable Flye","description":"Cable exercise for the chest, with shoulders assisting.","instructions":["To get yourself into the starting position, set the pulleys at the floor level (lowest level possible on the machine that is below your torso).","Place an incline bench (set at 45 degrees) in between the pulleys, select a weight on each one and grab a pulley on each hand.","With a handle on each hand, lie on the incline bench and bring your hands together at arms length in front of your face. This will be your starting position.","With a slight bend of your elbows (in order to prevent stress at the biceps tendon), lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary. The movement should only occur at the shoulder joint.","Return your arms back to the starting position as you squeeze your chest muscles and exhale. Hold the contracted position for a second. Tip: Make sure to use the same arc of motion used to lower the weights.","Repeat the movement for the prescribed amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS"],"equipment":"CABLE","tags":["incline cable flye"],"media":[{"id":"incline-cable-flye-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Cable_Flye/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"incline-cable-flye-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Cable_Flye/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Brust, unterstützt von Schultern.","instructions":null}},{"id":"ex-incline-crunches","slug":"incline-crunches","name":"Incline Crunches","description":"Bodyweight exercise for the core.","instructions":["Lay down on your back on a inclined bench, feet are on one end of the bench. Ask a partner or use some other help (barbell, etc.) to keep them fixed, your hands are behind your head. From this position move your upper body up till your head or elbows touch your knees. Do this movement by rolling up your back."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["incline crunches","crunches an schrägbank"],"media":[{"id":"incline-crunches-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/56/Decline-crunch-1.png","caption":"Incline Crunches","attribution":"wger.de · Everkinetic","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Crunches an Schrägbank","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Der Ablauf der Übung ist im Prinzip wie bei den normalen Crunches, nur legst du dich auf eine Schrägbank oder eine andere geeignete Fläche. Stelle sicher, dass du nicht rutschen kannst indem du die Beine über den Rand anwikelst oder sonstwo festhalten kannst. Halte die Hände hinter dem Nacken verschränkt. Aus dieser Position führe den Oberkörper so weit nach oben, bis Kopf oder Ellenbogen die Knie berühren.","Es ist wichtig, dass dieser Vorgang mit einer rollenden Bewegung durchgeführt wird: die Wirbelsäule sollte sich Wirbel für Wirbel von der Matte lösen. Ein Hohlkreuz ist stets zu vermeiden."]}},{"id":"ex-incline-db-y-raise","slug":"incline-db-y-raise","name":"Incline DB Y-Raise","description":"Dumbbell exercise for the shoulders, with back assisting.","instructions":["Set","an incline bench to a 45-degree angle and sit facing the bench, chest","against the pad, with a dumbbell in each hand, palms facing each other.","Position your feet firmly on the ground for stability and let your arms hang down naturally with a slight bend in your elbows.","Engage your core and keep your back straight throughout the movement.","Raise your arms forward and out to form a Y shape, keeping the movement controlled and your elbows slightly bent.","Lift until your arms are roughly parallel to the floor and in line with your ears.","Pause"],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"DUMBBELL","tags":["incline db y-raise","y-raise mit kurzhanteln auf der schrägbank"],"media":[],"source":"wger","de":{"name":"Y-Raise mit Kurzhanteln auf der Schrägbank","description":"Übung (Kurzhantel) für die Schultern, unterstützt von Rücken.","instructions":["Stelle","eine Schrägbank auf einen 45-Grad-Winkel ein und setze dich mit dem Gesicht","zur Bank, die Brust gegen das Polster, mit einer Kurzhantel in jeder Hand, die Handflächen einander zugewandt.","Stelle deine Füße fest auf den Boden, um Stabilität zu haben, und lass deine Arme natürlich nach unten hängen, mit einer leichten Beugung in den Ellenbogen.","Spanne deinen Rumpf an und halte deinen Rücken während der gesamten Bewegung gerade.","Hebe deine Arme nach vorne und außen an, sodass sie eine Y-Form bilden, und halte die Bewegung kontrolliert sowie die Ellenbogen leicht gebeugt.","Hebe an, bis deine Arme etwa parallel zum Boden und auf einer Linie mit deinen Ohren sind.","Halte"]}},{"id":"ex-incline-dumbbell-bench-with-palms-facing-in","slug":"incline-dumbbell-bench-with-palms-facing-in","name":"Incline Dumbbell Bench With Palms Facing In","description":"Dumbbell exercise for the chest, with shoulders, triceps assisting.","instructions":["Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.","By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.","Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.","Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.","As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the dumbbells back in your thighs and then on the floor. This is the safest manner to dispose of the dumbbells."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"DUMBBELL","tags":["incline dumbbell bench with palms facing in"],"media":[{"id":"incline-dumbbell-bench-with-palms-facing-in-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Bench_With_Palms_Facing_In/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"incline-dumbbell-bench-with-palms-facing-in-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Bench_With_Palms_Facing_In/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-incline-dumbbell-flyes-with-a-twist","slug":"incline-dumbbell-flyes-with-a-twist","name":"Incline Dumbbell Flyes - With A Twist","description":"Dumbbell exercise for the chest, with shoulders assisting.","instructions":["Hold a dumbbell in each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.","Extend your arms above you with a slight bend at the elbows.","Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.","As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.","As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS"],"equipment":"DUMBBELL","tags":["incline dumbbell flyes - with a twist"],"media":[{"id":"incline-dumbbell-flyes-with-a-twist-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Flyes_-_With_A_Twist/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"incline-dumbbell-flyes-with-a-twist-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Flyes_-_With_A_Twist/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Brust, unterstützt von Schultern.","instructions":null}},{"id":"ex-incline-dumbbell-row","slug":"incline-dumbbell-row","name":"Incline Dumbbell Row","description":"Dumbbell exercise for the back.","instructions":["Using a neutral grip, lean into an incline bench.","Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.","Retract the shoulder blades and flex the elbows to row the dumbbells to your side.","Pause at the top of the motion, and then return to the starting position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["incline dumbbell row","rudern kh auf schrägbank"],"media":[],"source":"wger","de":{"name":"Rudern KH Auf Schrägbank","description":"Übung (Kurzhantel) für den Rücken.","instructions":["Lehnen Sie sich mit einem neutralen Griff in eine Schrägbank.","Nehmen Sie eine Hantel mit neutralem Griff in jede Hand und beginnen Sie mit geraden Armen. Dies wird Ihre Startposition sein.","Ziehen Sie die Schulterblätter zurück und beugen Sie die Ellbogen, um die Hanteln zu Ihnen zu rudern.","Halten Sie am oberen Rand der Bewegung an und kehren Sie dann in die Ausgangsposition zurück."]}},{"id":"ex-incline-hammer-curls","slug":"incline-hammer-curls","name":"Incline Hammer Curls","description":"Dumbbell exercise for the biceps.","instructions":["Seat yourself on an incline bench with a dumbbell in each hand. You should pressed firmly against he back with your feet together. Allow the dumbbells to hang straight down at your side, holding them with a neutral grip. This will be your starting position.","Initiate the movement by flexing at the elbow, attempting to keep the upper arm stationary.","Continue to the top of the movement and pause, then slowly return to the start position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["incline hammer curls"],"media":[{"id":"incline-hammer-curls-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Hammer_Curls/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"incline-hammer-curls-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Hammer_Curls/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps.","instructions":null}},{"id":"ex-incline-inner-biceps-curl","slug":"incline-inner-biceps-curl","name":"Incline Inner Biceps Curl","description":"Dumbbell exercise for the biceps.","instructions":["Hold a dumbbell in each hand and lie back on an incline bench.","The dumbbells should be at arm's length hanging at your sides and your palms should be facing out. This will be your starting position.","Now as you exhale curl the weight outward and up while keeping your forearms in line with your side deltoids. Continue the curl until the dumbbells are at shoulder height and to the sides of your deltoids. Tip: The end of the movement should look similar to a double biceps pose.","After a second contraction at the top of the movement, start to inhale and slowly lower the weights back to the starting position using the same path used to bring them up.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["incline inner biceps curl"],"media":[{"id":"incline-inner-biceps-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Inner_Biceps_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"incline-inner-biceps-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Inner_Biceps_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps.","instructions":null}},{"id":"ex-incline-ohp-db","slug":"incline-ohp-db","name":"Incline OHP DB","description":"Dumbbell exercise for the shoulders, with triceps assisting.","instructions":["Sit on a bench with 45° incline","Ellbows 45° out","Move dumbbells down until upper arms are parallel to shoulders","Move dumbbells up, meeting overhead"],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"DUMBBELL","tags":["incline ohp db","schrägbank-schulterdrücken mit kurzhanteln"],"media":[],"source":"wger","de":{"name":"Schrägbank-Schulterdrücken mit Kurzhanteln","description":"Übung (Kurzhantel) für die Schultern, unterstützt von Trizeps.","instructions":["Setze dich auf eine Bank mit 45° Neigung","Ellbogen 45° nach außen","Senke die Kurzhanteln ab, bis die Oberarme parallel zu den Schultern sind","Bewege die Kurzhanteln nach oben, bis sie sich über dem Kopf treffen"]}},{"id":"ex-incline-plank-with-alternate-floor-touch","slug":"incline-plank-with-alternate-floor-touch","name":"Incline Plank With Alternate Floor Touch","description":"Bodyweight exercise for the core.","instructions":["Perform the plank with legs elevated, feet on a gymball. Once stabilised, slowly move one foot sideways off the ball, then make it touch the floor, then come back to starting position. Alternate with the other foot.","This is a core exercise."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["incline plank with alternate floor touch","negativ plank mit abwechselnden fuß-kontakt"],"media":[],"source":"wger","de":{"name":"Negativ Plank Mit Abwechselnden Fuß-Kontakt","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Führen Sie die Planke mit erhobenen Beinen und Füßen auf einem Gymball durch. Sobald Sie sich stabilisiert haben, bewegen Sie langsam einen Fuß seitlich vom Ball weg, lassen Sie ihn den Boden berühren und kehren Sie dann in die Ausgangsposition zurück. Wechseln Sie mit dem anderen Fuß.","Dies ist eine Core-Übung."]}},{"id":"ex-incline-push-up","slug":"incline-push-up","name":"Incline Push-Up","description":"Bodyweight exercise for the chest, with shoulders, triceps assisting.","instructions":["Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width.","Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms.","Push body up until arms are extended. Repeat."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BODYWEIGHT","tags":["incline push-up"],"media":[{"id":"incline-push-up-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Push-Up/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"incline-push-up-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Push-Up/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-incline-push-up-close-grip","slug":"incline-push-up-close-grip","name":"Incline Push-Up Close-Grip","description":"Bodyweight exercise for the triceps, with chest, shoulders assisting.","instructions":["Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.","Place your hands next to one another on the bar.","Position your feet back from the bar with arms and body straight. This will be your starting position.","Keeping your body straight, lower your chest to the bar by bending the arms.","Return to the starting position by extending the elbows, pressing yourself back up."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"BODYWEIGHT","tags":["incline push-up close-grip"],"media":[{"id":"incline-push-up-close-grip-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Push-Up_Close-Grip/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"incline-push-up-close-grip-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Push-Up_Close-Grip/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-incline-push-up-depth-jump","slug":"incline-push-up-depth-jump","name":"Incline Push-Up Depth Jump","description":"Accessory exercise for the chest, with shoulders, triceps assisting.","instructions":["For this drill you will need a box about 12 inches high, and two thick mats or aerobics steps.","Place the steps just outside of your shoulders, and place your feet on top of the box so that you are in an incline pushup position, your hands just inside the steps. This will be your starting position.","Begin by bending at the elbows to lower your body, quickly reversing position to push your body off of the ground. As you leave the ground, move your hands onto the steps, bending your elbows to absorb the impact.","Repeat the motion to return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"OTHER","tags":["incline push-up depth jump"],"media":[{"id":"incline-push-up-depth-jump-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Push-Up_Depth_Jump/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"incline-push-up-depth-jump-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Push-Up_Depth_Jump/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-incline-push-up-medium","slug":"incline-push-up-medium","name":"Incline Push-Up Medium","description":"Bodyweight exercise for the chest, with core, shoulders, triceps assisting.","instructions":["Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.","Place your hands on the bar, with your hands about shoulder width apart.","Position your feet back from the bar with arms and body straight. This will be your starting position.","Keeping your body straight, lower your chest to the bar by bending the arms.","Return to the starting position by extending the elbows, pressing yourself back up."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["ABS_CORE","SHOULDERS","TRICEPS"],"equipment":"BODYWEIGHT","tags":["incline push-up medium"],"media":[{"id":"incline-push-up-medium-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Push-Up_Medium/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"incline-push-up-medium-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Push-Up_Medium/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Brust, unterstützt von Rumpf, Schultern, Trizeps.","instructions":null}},{"id":"ex-incline-push-up-reverse-grip","slug":"incline-push-up-reverse-grip","name":"Incline Push-Up Reverse Grip","description":"Bodyweight exercise for the chest, with core, shoulders, triceps assisting.","instructions":["Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.","Place your hands on the bar palms up, with your hands about shoulder width apart.","Position your feet back from the bar with arms and body straight. This will be your starting position.","Keeping your body straight, lower your chest to the bar by bending the arms.","Return to the starting position by extending the elbows, pressing yourself back up."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["ABS_CORE","SHOULDERS","TRICEPS"],"equipment":"BODYWEIGHT","tags":["incline push-up reverse grip"],"media":[{"id":"incline-push-up-reverse-grip-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Push-Up_Reverse_Grip/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"incline-push-up-reverse-grip-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Push-Up_Reverse_Grip/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Brust, unterstützt von Rumpf, Schultern, Trizeps.","instructions":null}},{"id":"ex-incline-push-up-wide","slug":"incline-push-up-wide","name":"Incline Push-Up Wide","description":"Bodyweight exercise for the chest, with core, shoulders, triceps assisting.","instructions":["Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.","Place your hands on the bar, with your hands wider than shoulder width.","Position your feet back from the bar with arms and body straight. Your arms should be perpendicular to the body. This will be your starting position.","Keeping your body straight, lower your chest to the bar by bending the arms.","Return to the starting position by extending the elbows, pressing yourself back up."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["ABS_CORE","SHOULDERS","TRICEPS"],"equipment":"BODYWEIGHT","tags":["incline push-up wide"],"media":[{"id":"incline-push-up-wide-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Push-Up_Wide/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"incline-push-up-wide-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Push-Up_Wide/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Brust, unterstützt von Rumpf, Schultern, Trizeps.","instructions":null}},{"id":"ex-incline-shoulder-press-up","slug":"incline-shoulder-press-up","name":"Incline Shoulder Press Up","description":"Bodyweight exercise for the shoulders, with chest assisting.","instructions":["Place your hands on the bench in a press up position","Push your chest away from the bench to separate your shoulder blades","Keeping your elbows straight, lower your chest towards the bench so your shoulder blades move closer together","Push your chest away from the bench again"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CHEST"],"equipment":"BODYWEIGHT","tags":["incline shoulder press up","schulterdrücken auf der bank (scapular push-up)"],"media":[],"source":"wger","de":{"name":"Schulterdrücken auf der Bank (Scapular Push-up)","description":"Übung (Körpergewicht) für die Schultern, unterstützt von Brust.","instructions":["Lege deine Hände auf der Bank in einer Liegestützposition ab.","Drücke deine Brust von der Bank weg, um die Schulterblätter auseinanderzuführen.","Halte die Ellbogen gestreckt und senke deine Brust Richtung Bank, sodass sich die Schulterblätter wieder annähern.","Drücke deine Brust erneut von der Bank weg."]}},{"id":"ex-incline-static-hold","slug":"incline-static-hold","name":"Incline Static Hold","description":"Dumbbell exercise for the chest.","instructions":["Execution","Hold Position:","Lower the dumbbells a few inches above your chest — about the midpoint of a normal incline press.","This is where your upper chest is under maximum tension.","Static Hold:","Hold the position for 20–45 seconds while keeping the chest tight.","Breathe slowly but stay tense — do not relax your chest or shoulders.","End the set:"],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["incline static hold","statisches halten auf der schrägbank"],"media":[],"source":"wger","de":{"name":"Statisches Halten auf der Schrägbank","description":"Übung (Kurzhantel) für die Brust.","instructions":["Ausführung","Halteposition:","Senke die Kurzhanteln bis wenige Zentimeter über deine Brust — etwa auf den Mittelpunkt eines normalen Schrägbankdrückens.","Hier steht deine obere Brust unter maximaler Spannung.","Statisches Halten:","Halte die Position für 20–45 Sekunden und halte dabei die Brust angespannt.","Atme langsam, bleibe aber unter Spannung — entspanne weder deine Brust noch deine Schultern.","Satz beenden:"]}},{"id":"ex-intermediate-groin-stretch","slug":"intermediate-groin-stretch","name":"Intermediate Groin Stretch","description":"Accessory exercise for the hamstrings.","instructions":["Lie on your back with your legs extended. Loop a belt, rope, or band around one of your feet, and swing that leg as far to the side as you can. This will be your starting position.","Pull gently on the belt to create tension in your groin and hamstring muscles. Hold for 10-20 seconds, and repeat on the other side."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["intermediate groin stretch"],"media":[{"id":"intermediate-groin-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Intermediate_Groin_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"intermediate-groin-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Intermediate_Groin_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelrückseite.","instructions":null}},{"id":"ex-intermediate-hip-flexor-and-quad-stretch","slug":"intermediate-hip-flexor-and-quad-stretch","name":"Intermediate Hip Flexor and Quad Stretch","description":"Accessory exercise for the quadriceps.","instructions":["Lie face down on the floor, with a rope, belt, or band looped around one foot.","Flex the knee and extend the hip of the leg to be stretched, using both hands to pull on the belt. Your knee and your hip should come off of the floor, creating tension in the hip flexors and quadriceps. Hold the stretch for 10-20 seconds, and repeat on the other leg."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["intermediate hip flexor and quad stretch"],"media":[{"id":"intermediate-hip-flexor-and-quad-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Intermediate_Hip_Flexor_and_Quad_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"intermediate-hip-flexor-and-quad-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Intermediate_Hip_Flexor_and_Quad_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-internal-rotation-with-band","slug":"internal-rotation-with-band","name":"Internal Rotation with Band","description":"Resistance band exercise for the shoulders.","instructions":["Choke the band around a post. The band should be at the same height as your elbow. Stand with your right side to the band a couple of feet away.","Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.","With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching away from your torso. This will be your starting position.","Execute the movement by rotating your arm in a forehand motion, keeping your elbow in place.","Continue as far as you are able, pause, and then return to the starting position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"BAND","tags":["internal rotation with band"],"media":[{"id":"internal-rotation-with-band-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Internal_Rotation_with_Band/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"internal-rotation-with-band-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Internal_Rotation_with_Band/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Widerstandsband) für die Schultern.","instructions":null}},{"id":"ex-inverted-row","slug":"inverted-row","name":"Inverted Row","description":"Equipment-free exercise for the back.","instructions":["Position a bar in a rack to about waist height. You can also use a smith machine.","Take a wider than shoulder width grip on the bar and position yourself hanging underneath the bar. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.","Begin by flexing the elbow, pulling your chest towards the bar. Retract your shoulder blades as you perform the movement.","Pause at the top of the motion, and return yourself to the start position.","Repeat for the desired number of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"NONE","tags":["inverted row","inverted rows (umgekehrtes rudern)"],"media":[{"id":"inverted-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Inverted_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"inverted-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Inverted_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Inverted Rows (umgekehrtes Rudern)","description":"Übung (ohne Geräte) für den Rücken.","instructions":["Halte deinen Körper gerade, ziehe die Schulterblätter zusammen und ziehe deine","Brust zur Stange für ein effektives Training von Rücken und Oberkörper."]}},{"id":"ex-inverted-row-with-straps","slug":"inverted-row-with-straps","name":"Inverted Row with Straps","description":"Accessory exercise for the back, with biceps assisting.","instructions":["Hang a rope or suspension straps from a rack or other stable object. Grasp the ends and position yourself in a supine position hanging from the ropes. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.","Begin by flexing the elbow, pulling your chest to your hands. Retract your shoulder blades as you perform the movement.","Pause at the top of the motion, and return yourself to the start position.","Repeat for the desired number of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"OTHER","tags":["inverted row with straps"],"media":[{"id":"inverted-row-with-straps-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Inverted_Row_with_Straps/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"inverted-row-with-straps-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Inverted_Row_with_Straps/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-iron-cross","slug":"iron-cross","name":"Iron Cross","description":"Dumbbell exercise for the shoulders, with chest, glutes, hamstrings, back, quadriceps assisting.","instructions":[],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CHEST","GLUTES","HAMSTRINGS","BACK","QUADRICEPS"],"equipment":"DUMBBELL","tags":["iron cross"],"media":[{"id":"iron-cross-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Iron_Cross/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"iron-cross-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Iron_Cross/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern, unterstützt von Brust, Po, Oberschenkelrückseite, Rücken, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-iron-crosses-stretch","slug":"iron-crosses-stretch","name":"Iron Crosses (stretch)","description":"Equipment-free exercise for the quadriceps.","instructions":["Lie face down on the floor, with your arms extended out to your side, palms pressed to the floor. This will be your starting position.","To begin, flex one knee and bring that leg across the back of your body, attempting to touch it to the ground near the opposite hand.","Promptly return the leg to the starting postion, and quickly repeat with the other leg. Continue alternating for 10-20 repetitions."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"NONE","tags":["iron crosses (stretch)"],"media":[{"id":"iron-crosses-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Iron_Crosses_stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"iron-crosses-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Iron_Crosses_stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-isometria-alle-parallele","slug":"isometria-alle-parallele","name":"Isometria alle parallele","description":"Bodyweight exercise for the chest, with back assisting.","instructions":["The parallel bars isometric hold is a static upper-body exercise performed on dip bars (parallel bars). Instead of moving up and down like in a traditional dip, you hold a fixed position under tension."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["BACK"],"equipment":"BODYWEIGHT","tags":["isometria alle parallele","isometrisches halten am barren"],"media":[],"source":"wger","de":{"name":"Isometrisches Halten am Barren","description":"Übung (Körpergewicht) für die Brust, unterstützt von Rücken.","instructions":["Das isometrische Halten am Barren ist eine statische Oberkörperübung, die an Dip-Stangen (Parallelbarren) ausgeführt wird. Anstatt dich wie bei einem klassischen Dip auf und ab zu bewegen, hältst du unter Spannung eine feste Position."]}},{"id":"ex-isometric-chest-squeezes","slug":"isometric-chest-squeezes","name":"Isometric Chest Squeezes","description":"Bodyweight exercise for the chest, with shoulders, triceps assisting.","instructions":["While either seating or standing, bend your arms at a 90-degree angle and place the palms of your hands together in front of your chest. Tip: Your hands should be open with the palms together and fingers facing forward (perpendicular to your torso).","Push both hands against each other as you contract your chest. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.","Hold for the recommended number of seconds.","Now release the tension slowly.","Rest for the recommended amount of time and repeat."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BODYWEIGHT","tags":["isometric chest squeezes"],"media":[{"id":"isometric-chest-squeezes-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Isometric_Chest_Squeezes/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"isometric-chest-squeezes-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Isometric_Chest_Squeezes/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-isometric-neck-exercise-front-and-back","slug":"isometric-neck-exercise-front-and-back","name":"Isometric Neck Exercise - Front And Back","description":"Bodyweight exercise for the shoulders.","instructions":["With your head and neck in a neutral position (normal position with head erect facing forward), place both of your hands on the front side of your head.","Now gently push forward as you contract the neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.","Hold for the recommended number of seconds.","Now release the tension slowly.","Rest for the recommended amount of time and repeat with your hands placed on the back side of your head."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["isometric neck exercise - front and back"],"media":[{"id":"isometric-neck-exercise-front-and-back-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Isometric_Neck_Exercise_-_Front_And_Back/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"isometric-neck-exercise-front-and-back-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Isometric_Neck_Exercise_-_Front_And_Back/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Schultern.","instructions":null}},{"id":"ex-isometric-neck-exercise-sides","slug":"isometric-neck-exercise-sides","name":"Isometric Neck Exercise - Sides","description":"Bodyweight exercise for the shoulders.","instructions":["With your head and neck in a neutral position (normal position with head erect facing forward), place your left hand on the left side of your head.","Now gently push towards the left as you contract the left neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.","Hold for the recommended number of seconds.","Now release the tension slowly.","Rest for the recommended amount of time and repeat with your right hand placed on the right side of your head."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["isometric neck exercise - sides"],"media":[{"id":"isometric-neck-exercise-sides-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Isometric_Neck_Exercise_-_Sides/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"isometric-neck-exercise-sides-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Isometric_Neck_Exercise_-_Sides/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Schultern.","instructions":null}},{"id":"ex-isometric-squat-to-failure","slug":"isometric-squat-to-failure","name":"Isometric Squat to Failure","description":"Bodyweight exercise for the glutes, with quadriceps assisting.","instructions":["sometric Squat to Failure: A Strength Training Technique","Definition","The isometric squat to failure is a variation of the squat exercise where you hold a static squat position at a specific angle, maintaining the position until your muscles can no longer sustain the contraction."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["QUADRICEPS"],"equipment":"BODYWEIGHT","tags":["isometric squat to failure","isometrische kniebeuge bis zum muskelversagen"],"media":[{"id":"isometric-squat-to-failure-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1733/4ef77069-beb2-4504-a4f3-b181d5f35212.png","caption":"Isometric Squat to Failure","attribution":"wger.de · Tierrasverdes","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Isometrische Kniebeuge bis zum Muskelversagen","description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelvorderseite.","instructions":["Isometrische Kniebeuge bis zum Muskelversagen: eine Krafttrainingstechnik","Definition","Die isometrische Kniebeuge bis zum Muskelversagen ist eine Variante der Kniebeuge, bei der du eine statische Hocke in einem bestimmten Winkel hältst und die Position so lange beibehältst, bis deine Muskeln die Kontraktion nicht mehr aufrechterhalten können."]}},{"id":"ex-isometric-wipers","slug":"isometric-wipers","name":"Isometric Wipers","description":"Bodyweight exercise for the chest, with core, shoulders, triceps assisting.","instructions":["Assume a push-up position, supporting your weight on your hands and toes while keeping your body straight. Your hands should be just outside of shoulder width. This will be your starting position.","Begin by shifting your body weight as far to one side as possible, allowing the elbow on that side to flex as you lower your body.","Reverse the motion by extending the flexed arm, pushing yourself up and then dropping to the other side.","Repeat for the desired number of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["ABS_CORE","SHOULDERS","TRICEPS"],"equipment":"BODYWEIGHT","tags":["isometric wipers"],"media":[{"id":"isometric-wipers-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Isometric_Wipers/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"isometric-wipers-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Isometric_Wipers/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Isometric Wipers","description":"Übung (Körpergewicht) für die Brust, unterstützt von Rumpf, Schultern, Trizeps.","instructions":["Nehmen Sie die Liegestütze-Position ein, wobei die Hände etwas breiter als die Schulterbreite sind.","Das Körpergewicht so weit wie möglich zur Seite verlagern, damit sich der Ellbogen auf dieser Seite beugen kann.","Kehren Sie die Bewegung um und bewegen Sie sich vollständig auf die andere Seite.","Kehren Sie in die Ausgangsposition zurück und wiederholen Sie den Vorgang für die gewünschte Anzahl von Wiederholungen."]}},{"id":"ex-it-band-and-glute-stretch","slug":"it-band-and-glute-stretch","name":"IT Band and Glute Stretch","description":"Accessory exercise for the glutes.","instructions":["Loop a belt, rope, or band around one of your feet, and swing that leg across your body to the opposite side, keeping the leg extended as you lay on the ground. This will be your starting position.","Keeping your foot off of the floor, pull on the belt, using the tension to pull the toes up. Hold for 10-20 seconds, and repeat on the other side."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["it band and glute stretch"],"media":[{"id":"it-band-and-glute-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/IT_Band_and_Glute_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"it-band-and-glute-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/IT_Band_and_Glute_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Po.","instructions":null}},{"id":"ex-janda-sit-up","slug":"janda-sit-up","name":"Janda Sit-Up","description":"Bodyweight exercise for the core.","instructions":["Position your body on the floor in the basic sit-up position; knees to a ninety degree angle with feet flat on the floor and arms either crossed over your chest or to the sides. This will be your starting position.","As you strongly tighten your glutes and hamstrings, fill your lungs with air and in a slow (three to six second count) ascent, slowly exhale. Tip: It is important to tighten the glutes and hamstrings as this will cause the hip flexors to be inactivated in a process called reciprocal inhibition, which basically means that opposite muscles to the contracted ones will relax.","As you inhale, slowly go back in a controlled manner to the starting position.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["janda sit-up"],"media":[{"id":"janda-sit-up-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Janda_Sit-Up/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"janda-sit-up-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Janda_Sit-Up/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-jefferson-squats","slug":"jefferson-squats","name":"Jefferson Squats","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings, back assisting.","instructions":["Place a barbell on the floor.","Stand in the middle of the bar length wise.","Bend down by bending at the knees and keeping your back straight and grasp the front of the bar with your right hand. Your palm should be in (neutral grip) facing the left side.","Grasp the rear of the bar with your left hand. The palm of your hand should be in neutral grip alignment (palms facing the right side). Tip: Ensure that your grip is even on the bar. Your torso should be positioned right in the middle of the bar and the distance between your torso and your right hand (which should be at the front) should be the same as the distance between your torso and your left hand (which should be to your back).","Now stand straight up with the weight. Tip: Your feet should be shoulder width apart and your toes slightly pointed out.","Squat down by bending at the knees and keeping your back straight until your upper thighs are parallel with the floor. Tip: Keep your back as vertical as possible with the floor and your head up. Also remember to not let your knees go past your toes. Inhale during this portion of the movement.","Now drive yourself back up to the starting position by pushing with the feet . Tip: Keep the bar hanging at arm's length and your elbows locked with a slight bend. The arms only serve as hooks. Avoid doing any lifting with them. Do the lifting with your thighs; not your arms."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","BACK"],"equipment":"BARBELL","tags":["jefferson squats"],"media":[{"id":"jefferson-squats-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jefferson_Squats/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"jefferson-squats-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jefferson_Squats/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-jerk","slug":"jerk","name":"Jerk","description":"Barbell exercise for the shoulders, with glutes, quadriceps, triceps assisting.","instructions":["Olympic lift jerk","Hold bar in front on shoulders like push press","Bend and extend knees pushing bar up while diving under the bar","Catch bar overhead with straight arms using lunge","Move feet parallel while holding bar in lockout"],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["GLUTES","QUADRICEPS","TRICEPS"],"equipment":"BARBELL","tags":["jerk","jerk (stoßen)"],"media":[],"source":"wger","de":{"name":"Jerk (Stoßen)","description":"Übung (Langhantel) für die Schultern, unterstützt von Po, Oberschenkelvorderseite, Trizeps.","instructions":["Olympisches Stoßen","Halte die Stange vorne auf den Schultern wie beim Push Press","Beuge und strecke die Knie, um die Stange nach oben zu drücken, während du dich unter die Stange tauchst","Fange die Stange mit gestreckten Armen über dem Kopf in einem Ausfallschritt auf","Bringe die Füße parallel, während du die Stange im Lockout hältst"]}},{"id":"ex-jerk-balance","slug":"jerk-balance","name":"Jerk Balance","description":"Barbell exercise for the shoulders, with glutes, hamstrings, quadriceps, triceps assisting.","instructions":["This drill helps you learn to drive yourself low enough during the jerk and corrects those who move backward during the movement. Begin with the bar racked in the jerk position, with the shoulders forward, torso upright, and the feet split slightly apart.","Initiate the movement as you would a normal jerk, dipping at the knees while keeping your torso vertical, and driving back up forcefully, using momentum and not your arms to elevate the weight.","Keep the rear foot in place, using it to drive your body forward into a full split as you jerk the weight. Recover by standing up with the weight overhead."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["GLUTES","HAMSTRINGS","QUADRICEPS","TRICEPS"],"equipment":"BARBELL","tags":["jerk balance"],"media":[{"id":"jerk-balance-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jerk_Balance/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"jerk-balance-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jerk_Balance/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Schultern, unterstützt von Po, Oberschenkelrückseite, Oberschenkelvorderseite, Trizeps.","instructions":null}},{"id":"ex-jerk-dip-squat","slug":"jerk-dip-squat","name":"Jerk Dip Squat","description":"Barbell exercise for the quadriceps, with core, calves assisting.","instructions":["This movement strengthens the dip portion of the jerk. Begin with the bar racked in the jerk position, with the shoulders forward to create a shelf and the bar lightly contacting the throat. The feet should be directly under the hips, with the feet turned out as is comfortable.","Keeping the torso vertical, dip by flexing the knees, allowing them to travel forward and without moving the hips to the rear. The dip should not be excessive. Return the weight to the starting position by driving forcefully though the feet."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["ABS_CORE","CALVES"],"equipment":"BARBELL","tags":["jerk dip squat"],"media":[{"id":"jerk-dip-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jerk_Dip_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"jerk-dip-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jerk_Dip_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Rumpf, Waden.","instructions":null}},{"id":"ex-jm-press","slug":"jm-press","name":"JM Press","description":"Barbell exercise for the triceps, with chest, shoulders assisting.","instructions":["Start the exercise the same way you would a close grip bench press. You will lie on a flat bench while holding a barbell at arms length (fully extended) with the elbows in. However, instead of having the arms perpendicular to the torso, make sure the bar is set in a direct line above the upper chest. This will be your starting position.","Now beginning from a fully extended position lower the bar down as if performing a lying triceps extension. Inhale as you perform this movement. When you reach the half way point, let the bar roll back about one inch by moving the upper arms towards your legs until they are perpendicular to the torso. Tip: Keep the bend at the elbows constant as you bring the upper arms forward.","As you exhale, press the bar back up by using the triceps to perform a close grip bench press.","Now go back to the starting position and start over.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"BARBELL","tags":["jm press"],"media":[{"id":"jm-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/JM_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"jm-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/JM_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"JM Press","description":"Übung (Langhantel) für den Trizeps, unterstützt von Brust, Schultern.","instructions":["Beim JM Press bleiben deine Schultern unbewegt, während du das Gewicht allein durch die Beugung und Streckung der Ellbogen mit der Kraft deines Trizeps bewegst. So erhältst du alle Vorteile der besten Trizeps-Kräftigungsübungen, ohne das empfindliche Schultergelenk zu überlasten. Eine klassische Win-win-Situation!"]}},{"id":"ex-jumping-jacks","slug":"jumping-jacks","name":"Jumping Jacks","description":"Bodyweight exercise for the quadriceps.","instructions":["A jumping jack or star jump, also called side-straddle hop in the US military, is a physical jumping exercise performed by jumping to a position with the legs spread wide and the hands going overhead, sometimes in a clap, and then returning to a position with the feet together and the arms at the sides"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["jumping jacks","hampelmann"],"media":[{"id":"jumping-jacks-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/320/6c9124b6-3551-47a8-9c22-20141c8b9c53.png","caption":"Jumping Jacks","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Hampelmann","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite.","instructions":["Sprungübung mit abwechselnd Füße schulterbreit und zusammen, entsprechend Hände auf Oberschenkel und über dem Kopf zusammen klatschen."]}},{"id":"ex-kettlebell-arnold-press","slug":"kettlebell-arnold-press","name":"Kettlebell Arnold Press","description":"Kettlebell exercise for the shoulders, with triceps assisting.","instructions":["Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you raise the kettlebell towards your shoulder. The palm should be facing inward.","Looking straight ahead, press the kettlebell out and overhead, rotating your wrist so that your palm faces forward at the top of the motion.","Return the kettlebell to the starting position, with the palm facing in."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"KETTLEBELL","tags":["kettlebell arnold press"],"media":[{"id":"kettlebell-arnold-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Arnold_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kettlebell-arnold-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Arnold_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-kettlebell-dead-clean","slug":"kettlebell-dead-clean","name":"Kettlebell Dead Clean","description":"Kettlebell exercise for the hamstrings, with calves, glutes, back, quadriceps assisting.","instructions":["Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead.","Clean the kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.","Lower the kettlebell, keeping the hamstrings loaded by keeping your back straight and your butt out."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","GLUTES","BACK","QUADRICEPS"],"equipment":"KETTLEBELL","tags":["kettlebell dead clean"],"media":[{"id":"kettlebell-dead-clean-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Dead_Clean/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kettlebell-dead-clean-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Dead_Clean/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Oberschenkelrückseite, unterstützt von Waden, Po, Rücken, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-kettlebell-deadlifts","slug":"kettlebell-deadlifts","name":"Kettlebell deadlifts","description":"Kettlebell exercise for the hamstrings, with glutes, quadriceps, back assisting.","instructions":["Starting position:","Stand hip-width apart, with your kettlebell centered between your ankles. Your back should be straight, your head facing forward.","Steps:","Hinge at the hips and slightly bend at the knees to put your hands on the kettlebell handles. Your back should be straight as you perform the movement.","Grab the kettlebell handles, with your hands pushing in opposite directions as if to pull the handle apart.","While contacting your abs and glutes, stand straight up.","Hinge at the hips again to bring the kettlebell back down, similarly to step 1.","Repeat from step 3."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","QUADRICEPS","BACK"],"equipment":"KETTLEBELL","tags":["kettlebell deadlifts","kettlebell kreuzheben"],"media":[{"id":"kettlebell-deadlifts-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1003/772d6e47-3865-4944-9255-7435d0b06782.png","caption":"Kettlebell deadlifts","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Kettlebell Kreuzheben","description":"Übung (Kettlebell) für die Oberschenkelrückseite, unterstützt von Po, Oberschenkelvorderseite, Rücken.","instructions":["Ausgangsposition:","Stellen Sie sich hüftbreit auseinander, die Kettlebell befindet sich in der Mitte zwischen Ihren Knöcheln. Der Rücken sollte gerade sein, der Kopf nach vorne zeigen.","Schritte:","Beugen Sie sich in der Hüfte und gehen Sie leicht in die Knie, um die Hände auf die Kettlebell-Griffe zu legen. Der Rücken sollte gerade sein, während Sie die Bewegung ausführen.","Greifen Sie die Kettlebell-Griffe und drücken Sie mit den Händen in entgegengesetzte Richtungen, als ob Sie die Griffe auseinanderziehen wollten.","Während Sie Ihre Bauch- und Gesäßmuskeln anspannen, richten Sie sich auf.","Beugen Sie sich wieder in die Hüfte, um die Kettlebell wieder nach unten zu bringen, ähnlich wie in Schritt 1.","Wiederholen Sie den Vorgang ab Schritt 3."]}},{"id":"ex-kettlebell-figure-8","slug":"kettlebell-figure-8","name":"Kettlebell Figure 8","description":"Kettlebell exercise for the core, with hamstrings, shoulders assisting.","instructions":["Place one kettlebell between your legs and take a wider than shoulder width stance. Bend over by pushing your butt out and keeping your back flat.","Pick up a kettlebell and pass it to your other hand between your legs. The receiving hand should reach from behind the legs. Go back and forth for several repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["HAMSTRINGS","SHOULDERS"],"equipment":"KETTLEBELL","tags":["kettlebell figure 8"],"media":[{"id":"kettlebell-figure-8-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Figure_8/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kettlebell-figure-8-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Figure_8/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für den Rumpf, unterstützt von Oberschenkelrückseite, Schultern.","instructions":null}},{"id":"ex-kettlebell-halo","slug":"kettlebell-halo","name":"Kettlebell Halo","description":"Kettlebell exercise for the shoulders, with back, core, triceps assisting.","instructions":["Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.","Keeping your elbows close to your head, move the kettlebell up past one ear and around behind your head.","Continue the circle past the opposite ear and back down to the starting position in front of your chest, letting the bell pass close to your body throughout.","Complete the prescribed number of circles in one direction, then repeat the same number in the opposite direction.","Move slowly and keep your head, hips and lower back still. If your lower back arches or the bell drifts far from your head, use a lighter weight."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK","ABS_CORE","TRICEPS"],"equipment":"KETTLEBELL","tags":["kettlebell halo"],"media":[],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Rücken, Rumpf, Trizeps.","instructions":null}},{"id":"ex-kettlebell-halo-with-overhead-extension","slug":"kettlebell-halo-with-overhead-extension","name":"Kettlebell Halo with Overhead Extension","description":"Kettlebell exercise for the shoulders, with back, core assisting.","instructions":["Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.","Keeping your elbows close to your head, move the kettlebell up past one ear and around until it sits behind your head. Pause here.","From this position, extend your elbows to press the kettlebell up and overhead until your arms are straight, keeping your upper arms alongside your head.","Bend your elbows to lower the kettlebell back to the pause position behind your head, under control.","Continue the circle past the opposite ear and back down to the starting position in front of your chest to complete one repetition.","Alternate the direction of the circle on each repetition. Keep your head, hips and lower back still throughout; if your lower back arches or you cannot reach the overhead position without leaning back, use a lighter weight or perform the halo and the extension as separate exercises."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK","ABS_CORE"],"equipment":"KETTLEBELL","tags":["kettlebell halo with overhead extension"],"media":[],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Rücken, Rumpf.","instructions":null}},{"id":"ex-kettlebell-hang-clean","slug":"kettlebell-hang-clean","name":"Kettlebell Hang Clean","description":"Kettlebell exercise for the hamstrings, with calves, glutes, back, shoulders assisting.","instructions":["Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead.","Clean kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.","Lower kettlebell to a hanging position between your legs while keeping the hamstrings loaded. Keep your head up at all times."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","GLUTES","BACK","SHOULDERS"],"equipment":"KETTLEBELL","tags":["kettlebell hang clean"],"media":[{"id":"kettlebell-hang-clean-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Hang_Clean/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kettlebell-hang-clean-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Hang_Clean/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Oberschenkelrückseite, unterstützt von Waden, Po, Rücken, Schultern.","instructions":null}},{"id":"ex-kettlebell-one-legged-deadlift","slug":"kettlebell-one-legged-deadlift","name":"Kettlebell One-Legged Deadlift","description":"Kettlebell exercise for the hamstrings, with glutes, back assisting.","instructions":["Hold a kettlebell by the handle in one hand. Stand on one leg, on the same side that you hold the kettlebell.","Keeping that knee slightly bent, perform a stiff legged deadlift by bending at the hip, extending your free leg behind you for balance.","Continue lowering the kettlebell until you are parallel to the ground, and then return to the upright position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","BACK"],"equipment":"KETTLEBELL","tags":["kettlebell one-legged deadlift","einbeiniges kreuzheben mit kettlebell"],"media":[{"id":"kettlebell-one-legged-deadlift-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_One-Legged_Deadlift/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kettlebell-one-legged-deadlift-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_One-Legged_Deadlift/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Einbeiniges Kreuzheben mit Kettlebell","description":"Übung (Kettlebell) für die Oberschenkelrückseite, unterstützt von Po, Rücken.","instructions":["Bei dieser Übung hältst du eine Kettlebell in einer Hand und stehst auf einem Bein, während du dich nach vorne beugst, um die Kettlebell zum Boden zu führen. Sie trainiert die hintere Oberschenkelmuskulatur, die Gesäßmuskulatur und den unteren Rücken und verbessert zugleich Gleichgewicht und Stabilität."]}},{"id":"ex-kettlebell-overhead-triceps-extension","slug":"kettlebell-overhead-triceps-extension","name":"Kettlebell Overhead Triceps Extension","description":"Kettlebell exercise for the triceps, with shoulders, core assisting.","instructions":["Stand with your feet hip-width apart, holding a kettlebell by the horns with both hands. Press it overhead until your arms are extended, with the bell hanging behind your hands.","Brace your abdominals and keep your upper arms vertical and close to your head. This is your starting position.","Bend at the elbows to lower the kettlebell behind your head, going as far as your shoulder mobility allows without your elbows flaring outward.","Extend your elbows to press the kettlebell back to the starting position, keeping your upper arms still throughout.","Keep your ribcage down and avoid arching your lower back as you extend."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["SHOULDERS","ABS_CORE"],"equipment":"KETTLEBELL","tags":["kettlebell overhead triceps extension"],"media":[],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für den Trizeps, unterstützt von Schultern, Rumpf.","instructions":null}},{"id":"ex-kettlebell-pass-between-the-legs","slug":"kettlebell-pass-between-the-legs","name":"Kettlebell Pass Between The Legs","description":"Kettlebell exercise for the core, with glutes, hamstrings, shoulders assisting.","instructions":["Place one kettlebell between your legs and take a comfortable stance. Bend over by pushing your butt out and keeping your back flat.","Pick up a kettlebell and pass it to your other hand between your legs, in the fashion of a \"W\". Go back and forth for several repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["GLUTES","HAMSTRINGS","SHOULDERS"],"equipment":"KETTLEBELL","tags":["kettlebell pass between the legs"],"media":[{"id":"kettlebell-pass-between-the-legs-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Pass_Between_The_Legs/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kettlebell-pass-between-the-legs-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Pass_Between_The_Legs/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für den Rumpf, unterstützt von Po, Oberschenkelrückseite, Schultern.","instructions":null}},{"id":"ex-kettlebell-pirate-ships","slug":"kettlebell-pirate-ships","name":"Kettlebell Pirate Ships","description":"Kettlebell exercise for the shoulders, with core assisting.","instructions":["With a wide stance, hold a kettlebell with both hands. Allow it to hang at waist level with your arms extended. This will be your starting position.","Initiate the movement by turning to one side, swinging the kettlebell to head height. Briefly pause at the top of the motion.","Allow the bell to drop as you rotate to the opposite side, again raising the kettlebell to head height.","Repeat for the desired amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["ABS_CORE"],"equipment":"KETTLEBELL","tags":["kettlebell pirate ships"],"media":[{"id":"kettlebell-pirate-ships-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Pirate_Ships/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kettlebell-pirate-ships-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Pirate_Ships/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Rumpf.","instructions":null}},{"id":"ex-kettlebell-pistol-squat","slug":"kettlebell-pistol-squat","name":"Kettlebell Pistol Squat","description":"Kettlebell exercise for the quadriceps, with calves, glutes, hamstrings, shoulders assisting.","instructions":["Pick up a kettlebell with two hands and hold it by the horns. Hold one leg off of the floor and squat down on the other.","Squat down by flexing the knee and sitting back with the hips, holding the kettlebell up in front of you.","Hold the bottom position for a second and then reverse the motion, driving through the heel and keeping your head and chest up.","Lower yourself again and repeat."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","SHOULDERS"],"equipment":"KETTLEBELL","tags":["kettlebell pistol squat"],"media":[{"id":"kettlebell-pistol-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Pistol_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kettlebell-pistol-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Pistol_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Schultern.","instructions":null}},{"id":"ex-kettlebell-seated-press","slug":"kettlebell-seated-press","name":"Kettlebell Seated Press","description":"Kettlebell exercise for the shoulders, with triceps assisting.","instructions":["Sit on the floor and spread your legs out comfortably.","Clean one kettlebell to your shoulder.","Press the kettlebell up and out until it is locked out overhead. Return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"KETTLEBELL","tags":["kettlebell seated press"],"media":[{"id":"kettlebell-seated-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Seated_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kettlebell-seated-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Seated_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-kettlebell-seesaw-press","slug":"kettlebell-seesaw-press","name":"Kettlebell Seesaw Press","description":"Kettlebell exercise for the shoulders, with triceps assisting.","instructions":["Clean two kettlebells two your shoulders.","Press one kettlebell.","Lower the kettlebell and immediately press the other kettlebell. Make sure to do the same amount of reps on both sides."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"KETTLEBELL","tags":["kettlebell seesaw press"],"media":[{"id":"kettlebell-seesaw-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Seesaw_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kettlebell-seesaw-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Seesaw_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-kettlebell-sumo-deadlift","slug":"kettlebell-sumo-deadlift","name":"kettlebell sumo deadlift","description":"Kettlebell exercise for the hamstrings, with glutes, quadriceps assisting.","instructions":["Place your feet wider than shoulder-width apart, pointing your toes outward.","Keep your back straight, shoulders back, and chest up.","The knees must follow the same direction as the toes and not move forward.","When going up, it is advisable to contract your glutes to maximize the effectiveness of the exercise.."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","QUADRICEPS"],"equipment":"KETTLEBELL","tags":["kettlebell sumo deadlift","sumo-kreuzheben mit kettlebell"],"media":[{"id":"kettlebell-sumo-deadlift-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1612/3dc33f57-2786-4305-8b91-e011d7055923.jpg","caption":"kettlebell sumo deadlift","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Sumo-Kreuzheben mit Kettlebell","description":"Übung (Kettlebell) für die Oberschenkelrückseite, unterstützt von Po, Oberschenkelvorderseite.","instructions":["Stelle deine Füße weiter als schulterbreit auseinander und zeige mit den Zehen nach außen.","Halte deinen Rücken gerade, die Schultern zurück und den Brustkorb aufgerichtet.","Die Knie müssen in dieselbe Richtung wie die Zehen zeigen und dürfen sich nicht nach vorn bewegen.","Beim Hochkommen ist es ratsam, deine Gesäßmuskulatur anzuspannen, um die Wirksamkeit der Übung zu maximieren."]}},{"id":"ex-kettlebell-sumo-high-pull","slug":"kettlebell-sumo-high-pull","name":"Kettlebell Sumo High Pull","description":"Kettlebell exercise for the back, with quadriceps, glutes, hamstrings, shoulders assisting.","instructions":["Place a kettlebell on the ground between your feet. Position your feet in a wide stance, and grasp the kettlebell with two hands. Set your hips back as far as possible, with your knees bent. Keep your chest and head up. This will be your starting position.","Begin by extending the hips and knees, simultaneously pulling the kettlebell to your shoulders, raising your elbows as you do so. Reverse the motion to return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["QUADRICEPS","GLUTES","HAMSTRINGS","SHOULDERS"],"equipment":"KETTLEBELL","tags":["kettlebell sumo high pull"],"media":[{"id":"kettlebell-sumo-high-pull-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Sumo_High_Pull/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kettlebell-sumo-high-pull-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Sumo_High_Pull/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Kettlebell Sumo High Pull","description":"Übung (Kettlebell) für den Rücken, unterstützt von Oberschenkelvorderseite, Po, Oberschenkelrückseite, Schultern.","instructions":["Eine Verbundübung, die Elemente des Sumo-Kreuzhebens und des High Pull kombiniert. Sie beansprucht die hintere Kette, insbesondere die Gesäßmuskulatur, die hintere Oberschenkelmuskulatur und den oberen Rücken. Der Sumo-Stand erhöht die Hüftbeteiligung, während der High Pull ein explosives Element hinzufügt und so die Entwicklung von Kraft fördert.","Stehe aufrecht über einer Kettlebell, die Füße weiter als schulterbreit und die Fußspitzen leicht nach außen gedreht.","Halte deinen Rumpf während der gesamten Übung angespannt und die Wirbelsäule neutral.","Beuge die Hüfte nach hinten und strecke die Arme, um die Kettlebell mit einem doppelten Obergriff zu greifen.","Während deine Unterschenkel nahezu senkrecht zum Boden stehen, strecke die Hüfte, um die Kettlebell mit hohen Ellbogen anzuheben und sie dabei nah am Körper zu halten.","Sobald die Kettlebell die Schulterhöhe erreicht hat, senke sie wieder in die Ausgangsposition ab."]}},{"id":"ex-kettlebell-thruster","slug":"kettlebell-thruster","name":"Kettlebell Thruster","description":"Kettlebell exercise for the shoulders, with quadriceps, triceps assisting.","instructions":["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so. This will be your starting position.","Begin to squat by flexing your hips and knees, lowering your hips between your legs. Maintain an upright, straight back as you descend as low as you can.","At the bottom, reverse direction and squat by extending your knees and hips, driving through your heels. As you do so, press both kettlebells overhead by extending your arms straight up, using the momentum from the squat to help drive the weights upward.","As you begin the next repetition, return the weights to the shoulders."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["QUADRICEPS","TRICEPS"],"equipment":"KETTLEBELL","tags":["kettlebell thruster"],"media":[{"id":"kettlebell-thruster-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Thruster/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kettlebell-thruster-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Thruster/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Oberschenkelvorderseite, Trizeps.","instructions":null}},{"id":"ex-kettlebell-turkish-get-up-lunge-style","slug":"kettlebell-turkish-get-up-lunge-style","name":"Kettlebell Turkish Get-Up (Lunge style)","description":"Kettlebell exercise for the shoulders, with core, hamstrings, quadriceps, triceps assisting.","instructions":["Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.","Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position. Using your free hand, push yourself to a seated position, then progressing to one knee.","While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["ABS_CORE","HAMSTRINGS","QUADRICEPS","TRICEPS"],"equipment":"KETTLEBELL","tags":["kettlebell turkish get-up (lunge style)"],"media":[{"id":"kettlebell-turkish-get-up-lunge-style-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Turkish_Get-Up_Lunge_style/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kettlebell-turkish-get-up-lunge-style-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Turkish_Get-Up_Lunge_style/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Rumpf, Oberschenkelrückseite, Oberschenkelvorderseite, Trizeps.","instructions":null}},{"id":"ex-kettlebell-turkish-get-up-squat-style","slug":"kettlebell-turkish-get-up-squat-style","name":"Kettlebell Turkish Get-Up (Squat style)","description":"Kettlebell exercise for the shoulders, with core, calves, hamstrings, quadriceps, triceps assisting.","instructions":["Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.","Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position.","Using your free hand, push yourself to a seated position, then progressing to your feet. While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["ABS_CORE","CALVES","HAMSTRINGS","QUADRICEPS","TRICEPS"],"equipment":"KETTLEBELL","tags":["kettlebell turkish get-up (squat style)"],"media":[{"id":"kettlebell-turkish-get-up-squat-style-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Turkish_Get-Up_Squat_style/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kettlebell-turkish-get-up-squat-style-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Turkish_Get-Up_Squat_style/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Rumpf, Waden, Oberschenkelrückseite, Oberschenkelvorderseite, Trizeps.","instructions":null}},{"id":"ex-kettlebell-windmill","slug":"kettlebell-windmill","name":"Kettlebell Windmill","description":"Kettlebell exercise for the core, with glutes, hamstrings, shoulders, triceps assisting.","instructions":["Place a kettlebell in front of your lead foot and clean and press it overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward. Press it overhead by extending the elbow.","Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell. Bending at the hip to one side, sticking your butt out, slowly lean until you can touch the floor with your free hand. Keep your eyes on the kettlebell that you hold over your head at all times.","Pause for a second after reaching the ground and reverse the motion back to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["GLUTES","HAMSTRINGS","SHOULDERS","TRICEPS"],"equipment":"KETTLEBELL","tags":["kettlebell windmill"],"media":[{"id":"kettlebell-windmill-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Windmill/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kettlebell-windmill-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Windmill/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für den Rumpf, unterstützt von Po, Oberschenkelrückseite, Schultern, Trizeps.","instructions":null}},{"id":"ex-kipping-muscle-up","slug":"kipping-muscle-up","name":"Kipping Muscle Up","description":"Accessory exercise for the back, with core, biceps, forearms, shoulders, triceps assisting.","instructions":["Grip the rings using a false grip, with the base of your palms on top of the rings.","Begin with a movement swinging your legs backward slightly.","Counter that movement by swinging your legs forward and up, jerking your chin and chest back, pulling yourself up with both arms as you do so. As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.","Maintaining control and stability, extend through the elbow to complete the motion.","Use care when lowering yourself to the ground."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["ABS_CORE","BICEPS","FOREARMS","SHOULDERS","TRICEPS"],"equipment":"OTHER","tags":["kipping muscle up"],"media":[{"id":"kipping-muscle-up-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kipping_Muscle_Up/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kipping-muscle-up-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kipping_Muscle_Up/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Rumpf, Bizeps, Unterarme, Schultern, Trizeps.","instructions":null}},{"id":"ex-knee-across-the-body","slug":"knee-across-the-body","name":"Knee Across The Body","description":"Equipment-free exercise for the glutes, with back assisting.","instructions":["Lie down on the floor with your right leg straight. Bend your left leg and lower it across your body, holding the knee down toward the floor with your right hand. (The knee doesn't need to touch the floor if you're tight.)","Place your left arm comfortably beside you and turn your head to the left. Imagine you have a weight tied to your tailbone. let your tailbone fall back toward the floor as your chest reaches in the opposite direction to stretch your lower back. Switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["BACK"],"equipment":"NONE","tags":["knee across the body"],"media":[{"id":"knee-across-the-body-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Knee_Across_The_Body/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"knee-across-the-body-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Knee_Across_The_Body/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Po, unterstützt von Rücken.","instructions":null}},{"id":"ex-knee-circles","slug":"knee-circles","name":"Knee Circles","description":"Bodyweight exercise for the calves, with hamstrings, quadriceps assisting.","instructions":["Stand with your legs together and hands by your waist.","Now move your knees in a circular motion as you breathe normally.","Repeat for the recommended amount of repetitions."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":["HAMSTRINGS","QUADRICEPS"],"equipment":"BODYWEIGHT","tags":["knee circles"],"media":[{"id":"knee-circles-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Knee_Circles/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"knee-circles-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Knee_Circles/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Waden, unterstützt von Oberschenkelrückseite, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-knee-push-ups","slug":"knee-push-ups","name":"knee push-ups","description":"Bodyweight exercise for the shoulders, with chest, triceps assisting.","instructions":["Start by kneeling on the floor, keeping your knees together. Place your hands on the floor in front of you, slightly wider than shoulder-width apart.","Make sure your body forms a straight line from head to knees. Hands should be positioned below shoulders.","Lower your torso towards the ground, bending your elbows while keeping your trunk stable. Keep your knees in contact with the floor.","Push through your hands to return to the starting position. Be sure to maintain contraction of chest, shoulder and arm muscles at the top of the movement.","Perform the desired number of repetitions, controlling the movement and maintaining good form."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CHEST","TRICEPS"],"equipment":"BODYWEIGHT","tags":["knee push-ups","liegestütze auf den knien"],"media":[],"source":"wger","de":{"name":"Liegestütze auf den Knien","description":"Übung (Körpergewicht) für die Schultern, unterstützt von Brust, Trizeps.","instructions":["Knie dich zunächst auf den Boden und halte die Knie zusammen. Stütze deine Hände vor dir auf dem Boden ab, etwas weiter als schulterbreit auseinander.","Achte darauf, dass dein Körper eine gerade Linie von Kopf bis Knie bildet. Die Hände sollten sich unter den Schultern befinden.","Senke deinen Oberkörper Richtung Boden, indem du die Ellbogen beugst, während du den Rumpf stabil hältst. Halte die Knie in Kontakt mit dem Boden.","Drücke dich über die Hände in die Ausgangsposition zurück. Achte darauf, am höchsten Punkt der Bewegung die Spannung in Brust-, Schulter- und Armmuskulatur zu halten.","Führe die gewünschte Anzahl an Wiederholungen aus, kontrolliere die Bewegung und behalte eine saubere Ausführung bei."]}},{"id":"ex-knee-tuck-jump","slug":"knee-tuck-jump","name":"Knee Tuck Jump","description":"Bodyweight exercise for the hamstrings, with glutes, quadriceps, calves assisting.","instructions":["Begin in a comfortable standing position with your knees slightly bent. Hold your hands in front of you, palms down with your fingertips together at chest height. This will be your starting position.","Rapidly dip down into a quarter squat and immediately explode upward. Drive the knees towards the chest, attempting to touch them to the palms of the hands.","Jump as high as you can, raising your knees up, and then ensure a good land be re-extending your legs, absorbing impact through be allowing the knees to rebend."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","QUADRICEPS","CALVES"],"equipment":"BODYWEIGHT","tags":["knee tuck jump"],"media":[{"id":"knee-tuck-jump-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Knee_Tuck_Jump/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"knee-tuck-jump-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Knee_Tuck_Jump/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelrückseite, unterstützt von Po, Oberschenkelvorderseite, Waden.","instructions":null}},{"id":"ex-kneeling-arm-drill","slug":"kneeling-arm-drill","name":"Kneeling Arm Drill","description":"Equipment-free exercise for the shoulders, with core assisting.","instructions":["This drill helps increase arm efficiency during the run. Begin kneeling, left foot in front, right knee down. Apply pressure through the front heel to keep your glutes and hamstrings activated.","Begin by blocking the arms in long, pendulum like swings. Close the arm angle, blocking with the arms as you would when jogging, progressing to a run and finally a sprint.","As soon as your hands pass the hip, accelerate them forward during the sprinting motion to move them as quickly as possible.","Switch knees and repeat."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["ABS_CORE"],"equipment":"NONE","tags":["kneeling arm drill"],"media":[{"id":"kneeling-arm-drill-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Arm_Drill/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kneeling-arm-drill-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Arm_Drill/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Schultern, unterstützt von Rumpf.","instructions":null}},{"id":"ex-kneeling-cable-crunch-with-alternating-oblique-twists","slug":"kneeling-cable-crunch-with-alternating-oblique-twists","name":"Kneeling Cable Crunch With Alternating Oblique Twists","description":"Cable exercise for the core.","instructions":["Connect a rope attachment to a high pulley cable and position a mat on the floor in front of it.","Grab the rope with both hands and kneel approximately two feet back from the tower.","Position the rope behind your head with your hands by your ears.","Keep your hands in the same place, contract your abs and pull downward on the rope in a crunching movement until your elbows reach your knees.","Pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.","Repeat the same downward movement until you're halfway down, at which time you'll begin rotating one of your elbows to the opposite knee.","Again, pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.","Repeat the same movement as before, but alternate the other elbow to the opposite knee.","Continue this series of movements to failure."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["kneeling cable crunch with alternating oblique twists"],"media":[{"id":"kneeling-cable-crunch-with-alternating-oblique-twists-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kneeling-cable-crunch-with-alternating-oblique-twists-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rumpf.","instructions":null}},{"id":"ex-kneeling-cable-triceps-extension","slug":"kneeling-cable-triceps-extension","name":"Kneeling Cable Triceps Extension","description":"Cable exercise for the triceps.","instructions":["Place a bench sideways in front of a high pulley machine.","Hold a straight bar attachment above your head with your hands about 6 inches apart with your palms facing down.","Face away from the machine and kneel.","Place your head and the back of your upper arms on the bench. Your elbows should be bent with the forearms pointing towards the high pulley. This will be your starting position.","While keeping your upper arms close to your head at all times with the elbows in, press the bar out in a semicircular motion until the elbows are locked and your arms are parallel to the floor. Contract the triceps hard and keep this position for a second. Exhale as you perform this movement.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["kneeling cable triceps extension"],"media":[{"id":"kneeling-cable-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Cable_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kneeling-cable-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Cable_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Trizeps.","instructions":null}},{"id":"ex-kneeling-high-pulley-row","slug":"kneeling-high-pulley-row","name":"Kneeling High Pulley Row","description":"Cable exercise for the back, with biceps assisting.","instructions":["Select the appropriate weight using a pulley that is above your head. Attach a rope to the cable and kneel a couple of feet away, holding the rope out in front of you with both arms extended. This will be your starting position.","Initiate the movement by flexing the elbows and fully retracting your shoulders, pulling the rope toward your upper chest with your elbows out.","After pausing briefly, slowly return to the starting position."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"CABLE","tags":["kneeling high pulley row"],"media":[{"id":"kneeling-high-pulley-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_High_Pulley_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kneeling-high-pulley-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_High_Pulley_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-kneeling-jump-squat","slug":"kneeling-jump-squat","name":"Kneeling Jump Squat","description":"Barbell exercise for the glutes, with calves, hamstrings, quadriceps assisting.","instructions":["Begin kneeling on the floor with a barbell racked across the back of your shoulders, or you can use your body weight for this exercise. This can be done inside of a power rack to make unracking easier.","Sit back with your hips until your glutes touch your feet, keeping your head and chest up.","Explode up with your hips, generating enough power to land with your feet flat on the floor.","Continue with the squat by driving through your heels and extending the knees to come to a standing position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["CALVES","HAMSTRINGS","QUADRICEPS"],"equipment":"BARBELL","tags":["kneeling jump squat"],"media":[{"id":"kneeling-jump-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Jump_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kneeling-jump-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Jump_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Po, unterstützt von Waden, Oberschenkelrückseite, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-kneeling-kickbacks","slug":"kneeling-kickbacks","name":"Kneeling kickbacks","description":"Bodyweight exercise for the glutes, with hamstrings assisting.","instructions":["Starting position:","Get down on all fours.","Steps:","Push one foot back until fully extended, concentrating on the gluteus muscles.","Stay for one second, then return to the initial position.","Repeat, alternating feet."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["kneeling kickbacks","kniende rückschläge"],"media":[{"id":"kneeling-kickbacks-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/990/de20457c-914a-45c9-8cf9-0ad9739759a1.png","caption":"Kneeling kickbacks","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Kniende Rückschläge","description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelrückseite.","instructions":["Ausgangsposition:","Gehen Sie auf alle Viere.","Schritte:","Drücken Sie einen Fuß nach hinten, bis er ganz gestreckt ist, und konzentrieren Sie sich dabei auf die Gesäßmuskeln.","Verweilen Sie eine Sekunde lang und kehren Sie dann in die Ausgangsposition zurück.","Wiederholen Sie den Vorgang, indem Sie die Füße abwechseln."]}},{"id":"ex-kneeling-single-arm-high-pulley-row","slug":"kneeling-single-arm-high-pulley-row","name":"Kneeling Single-Arm High Pulley Row","description":"Cable exercise for the back, with biceps assisting.","instructions":["Attach a single handle to a high pulley and make your weight selection.","Kneel in front of the cable tower, taking the cable with one hand with your arm extended. This will be your starting position.","Starting with your palm facing forward, pull the weight down to your torso by flexing the elbow and retract the shoulder blade. As you do so, rotate the wrist so that at the completion of the movement, your palm is now facing you.","After a brief pause, return to the starting position."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"CABLE","tags":["kneeling single-arm high pulley row"],"media":[{"id":"kneeling-single-arm-high-pulley-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Single-Arm_High_Pulley_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kneeling-single-arm-high-pulley-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Single-Arm_High_Pulley_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-kneeling-squat","slug":"kneeling-squat","name":"Kneeling Squat","description":"Barbell exercise for the glutes, with core, hamstrings, back assisting.","instructions":["Set the bar to the proper height in a power rack. Kneel behind the bar; it may be beneficial to put a mat down to pad your knees. Slide under the bar, racking it across the back of your shoulders. Your shoulder blades should be retracted and the bar tight across your back. Unrack the weight.","With your head looking forward, sit back with your butt until you touch your calves.","Reverse the motion, returning the torso to an upright position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["ABS_CORE","HAMSTRINGS","BACK"],"equipment":"BARBELL","tags":["kneeling squat"],"media":[{"id":"kneeling-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"kneeling-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Po, unterstützt von Rumpf, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-kneeling-superman","slug":"kneeling-superman","name":"Kneeling Superman","description":"Bodyweight exercise for the hamstrings, with back, core assisting.","instructions":["Push one foot back until leg fully extended, concentrating on the having the foot high and pushed back as if pulled.","Extend arm forward with focus having the shoulder high up.","Unilateral and static hold."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["BACK","ABS_CORE"],"equipment":"BODYWEIGHT","tags":["kneeling superman","kniender superman"],"media":[],"source":"wger","de":{"name":"Kniender Superman","description":"Übung (Körpergewicht) für die Oberschenkelrückseite, unterstützt von Rücken, Rumpf.","instructions":["Schiebe einen Fuß nach hinten, bis das Bein vollständig gestreckt ist, und konzentriere dich darauf, den Fuß hoch und nach hinten geschoben zu halten, als würde er gezogen.","Strecke den Arm nach vorne und achte darauf, die Schulter hoch oben zu halten.","Einseitig und statisch gehalten."]}},{"id":"ex-kreis-press-db","slug":"kreis-press-db","name":"Kreis Press DB","description":"Dumbbell exercise for the shoulders, with biceps, chest, core, triceps assisting.","instructions":["Sit on a bench with 45° incline","Hold dumbbells overhead","Move dumbbells down as if doing overhead press","Rotate dumbbells palms facing up and extend your arms in front of your body","Move hands together until dumbbells meet, keep arms extended","Reverse the motion until dumbbells are overhead again","This is one repetition"],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BICEPS","CHEST","ABS_CORE","TRICEPS"],"equipment":"DUMBBELL","tags":["kreis press db","kreis-press mit kurzhanteln"],"media":[],"source":"wger","de":{"name":"Kreis-Press mit Kurzhanteln","description":"Übung (Kurzhantel) für die Schultern, unterstützt von Bizeps, Brust, Rumpf, Trizeps.","instructions":["Setze dich auf eine Bank mit 45° Neigung","Halte die Kurzhanteln über dem Kopf","Senke die Kurzhanteln ab, als würdest du Schulterdrücken machen","Drehe die Kurzhanteln so, dass die Handflächen nach oben zeigen, und strecke die Arme vor deinem Körper aus","Führe die Hände zusammen, bis sich die Kurzhanteln berühren, und halte die Arme gestreckt","Kehre die Bewegung um, bis die Kurzhanteln wieder über dem Kopf sind","Das ist eine Wiederholung"]}},{"id":"ex-l-hold","slug":"l-hold","name":"L Hold","description":"Bodyweight exercise for the core.","instructions":["Hold the L position for as long as possible"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["l hold","l sit"],"media":[],"source":"wger","de":{"name":"L Sit","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Hänge dich an eine Klimmzugstange und hebe die Beine gerade an bis du einen 90° Winkel zwischen Beine und Oberkörper hast (L-Form). Halte die Position."]}},{"id":"ex-l-sit","slug":"l-sit","name":"L-sit","description":"Bodyweight exercise for the back, with chest, core, quadriceps, triceps assisting.","instructions":["Sit on the ground with your legs together and your arms by your sides. Push your body off the ground using your hands, maintaining the same sitting position so that your legs are straight and your feet do not touch the floor.","Hold for as long as required."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["CHEST","ABS_CORE","QUADRICEPS","TRICEPS"],"equipment":"BODYWEIGHT","tags":["l-sit"],"media":[],"source":"wger","de":{"name":"L-Sit","description":"Übung (Körpergewicht) für den Rücken, unterstützt von Brust, Rumpf, Oberschenkelvorderseite, Trizeps.","instructions":["Setze dich auf den Boden mit geschlossenen Beinen und den Armen an den Seiten. Drücke deinen Körper mithilfe der Hände vom Boden ab und halte dabei dieselbe Sitzposition, sodass deine Beine gerade sind und deine Füße den Boden nicht berühren.","Halte die Position so lange wie nötig."]}},{"id":"ex-landmine-180s","slug":"landmine-180s","name":"Landmine 180's","description":"Barbell exercise for the core, with glutes, back, shoulders assisting.","instructions":["Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.","Raise the bar from the floor, taking it to shoulder height with both hands with your arms extended in front of you. Adopt a wide stance. This will be your starting position.","Perform the movement by rotating the trunk and hips as you swing the weight all the way down to one side. Keep your arms extended throughout the exercise.","Reverse the motion to swing the weight all the way to the opposite side.","Continue alternating the movement until the set is complete."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["GLUTES","BACK","SHOULDERS"],"equipment":"BARBELL","tags":["landmine 180's"],"media":[{"id":"landmine-180s-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Landmine_180s/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"landmine-180s-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Landmine_180s/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rumpf, unterstützt von Po, Rücken, Schultern.","instructions":null}},{"id":"ex-landmine-linear-jammer","slug":"landmine-linear-jammer","name":"Landmine Linear Jammer","description":"Barbell exercise for the shoulders, with core, calves, chest, hamstrings, quadriceps, triceps assisting.","instructions":["Position a bar into landmine or, lacking one, securely anchor it in a corner. Load the bar to an appropriate weight and position the handle attachment on the bar.","Raise the bar from the floor, taking the handles to your shoulders. This will be your starting position.","In an athletic stance, squat by flexing your hips and setting your hips back, keeping your arms flexed.","Reverse the motion by powerfully extending through the hips, knees, and ankles, while also extending the elbows to straighten the arms. This movement should be done explosively, coming out of the squat to full extension as powerfully as possible.","Return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["ABS_CORE","CALVES","CHEST","HAMSTRINGS","QUADRICEPS","TRICEPS"],"equipment":"BARBELL","tags":["landmine linear jammer"],"media":[{"id":"landmine-linear-jammer-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Landmine_Linear_Jammer/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"landmine-linear-jammer-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Landmine_Linear_Jammer/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Schultern, unterstützt von Rumpf, Waden, Brust, Oberschenkelrückseite, Oberschenkelvorderseite, Trizeps.","instructions":null}},{"id":"ex-landmine-rotation","slug":"landmine-rotation","name":"Landmine Rotation","description":"Barbell exercise for the core, with shoulders assisting.","instructions":["Start with landmine barbell straight up by using your shoulders to push it up above you. Then, from that position, bring it your side to target your abdominals and return to starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["SHOULDERS"],"equipment":"BARBELL","tags":["landmine rotation","landmine-rotation"],"media":[],"source":"wger","de":{"name":"Landmine-Rotation","description":"Übung (Langhantel) für den Rumpf, unterstützt von Schultern.","instructions":["Beginne mit der Landmine-Langhantel gerade nach oben, indem du sie mit deinen Schultern über dich drückst. Führe sie dann aus dieser Position seitlich nach unten, um deine Bauchmuskulatur zu beanspruchen, und kehre in die Ausgangsposition zurück."]}},{"id":"ex-landmine-squat-to-press","slug":"landmine-squat-to-press","name":"Landmine Squat to Press","description":"Barbell exercise for the shoulders, with glutes, quadriceps, hamstrings, core assisting.","instructions":["Bar Position: Anchor one end of a barbell in a landmine attachment or a secure corner.","Stance: Stand facing the barbell with feet slightly wider than shoulder-width. Turn your toes out 10–35 degrees to allow for better pelvic movement and depth.","Grip: Cup the free end of the barbell with both hands (fingers interlaced or overlapping) and hold it at mid-chest level, just below the collarbone.","Descent: Brace your core and sit back into a squat, keeping your chest up and weight on your heels.","Depth: Lower until your thighs are at least parallel to the floor. A good reference is when your elbows touch the tops of your thighs or just inside your knees.","Posture: Ensure your back remains flat and your spine neutral throughout the movement.","Drive: Powerfully drive through your heels to stand up. Use the momentum from your legs to \"thrust\" the weight upward.","Extension: In one fluid motion, press the bar overhead until your arms are fully extended. At the top, your biceps should be near your ears."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["GLUTES","QUADRICEPS","HAMSTRINGS","ABS_CORE"],"equipment":"BARBELL","tags":["landmine squat to press","landmine kniebeuge mit überkopfdrücken"],"media":[],"source":"wger","de":{"name":"Landmine Kniebeuge mit Überkopfdrücken","description":"Übung (Langhantel) für die Schultern, unterstützt von Po, Oberschenkelvorderseite, Oberschenkelrückseite, Rumpf.","instructions":["Position der Stange: Verankere ein Ende einer Langhantel in einer Landmine-Vorrichtung oder einer sicheren Ecke.","Stand: Stelle dich mit dem Gesicht zur Langhantel, die Füße etwas mehr als schulterbreit auseinander. Drehe deine Fußspitzen 10–35 Grad nach außen, um eine bessere Beckenbewegung und Tiefe zu ermöglichen.","Griff: Umfasse das freie Ende der Langhantel mit beiden Händen (Finger ineinander verschränkt oder übereinander) und halte sie auf Höhe der mittleren Brust, knapp unter dem Schlüsselbein.","Abwärtsbewegung: Spanne deinen Rumpf an und setze dich in eine Kniebeuge zurück, wobei du die Brust aufgerichtet hältst und das Gewicht auf den Fersen lastet.","Tiefe: Senke dich, bis deine Oberschenkel mindestens parallel zum Boden sind. Ein guter Anhaltspunkt ist, wenn deine Ellenbogen die Oberseite deiner Oberschenkel oder die Innenseite deiner Knie berühren.","Haltung: Achte darauf, dass dein Rücken flach und deine Wirbelsäule während der gesamten Bewegung neutral bleibt.","Antrieb: Drücke dich kraftvoll über die Fersen nach oben. Nutze den Schwung aus deinen Beinen, um das Gewicht nach oben zu „stoßen“.","Streckung: Drücke die Stange in einer fließenden Bewegung über den Kopf, bis deine Arme vollständig gestreckt sind. Am obersten Punkt sollten deine Bizeps nahe an deinen Ohren sein."]}},{"id":"ex-lat-pull-down-straight-back","slug":"lat-pull-down-straight-back","name":"Lat Pull Down (Straight Back)","description":"Bodyweight exercise for the back.","instructions":["The lat pull down is an exercise used to build the muscles of the back. While the exercise will primarily target the lats, you will also notice a fair amount of bicep and middle back activation."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["lat pull down (straight back)","latzug"],"media":[],"source":"wger","de":{"name":"Latzug","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Der Latzug ist eine Übung zum Aufbau der Rückenmuskulatur. Während die Übung in erster Linie den Latissimus beansprucht, wirst du auch eine deutliche Aktivierung des Bizeps und der mittleren Rückenmuskulatur bemerken."]}},{"id":"ex-lat-pulldown-cross-body-single-arm","slug":"lat-pulldown-cross-body-single-arm","name":"Lat Pulldown - Cross Body Single Arm","description":"Cable exercise for the back.","instructions":["Sit at lat pulldown machine with body at a diagonal angle so that only one leg is under the pad. Pull the cable down with the opposite arm. this will force the cable to across your body while pulling down. Emphasises the stretch of the lat."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["lat pulldown - cross body single arm","latzug einarmig über kreuz"],"media":[],"source":"wger","de":{"name":"Latzug einarmig über Kreuz","description":"Übung (Kabelzug) für den Rücken.","instructions":["Setze dich an die Latzug-Maschine, wobei dein Körper diagonal ausgerichtet ist, sodass nur ein Bein unter dem Polster liegt. Ziehe das Kabel mit dem gegenüberliegenden Arm nach unten. Dadurch wird das Kabel beim Ziehen über deinen Körper geführt. Das betont die Dehnung des Latissimus."]}},{"id":"ex-lateral-bound","slug":"lateral-bound","name":"Lateral Bound","description":"Bodyweight exercise for the quadriceps, with glutes, calves, hamstrings assisting.","instructions":["Assume a half squat position facing 90 degrees from your direction of travel. This will be your starting position.","Allow your lead leg to do a countermovement inward as you shift your weight to the outside leg.","Immediately push off and extend, attempting to bound to the side as far as possible.","Upon landing, immediately push off in the opposite direction, returning to your original start position.","Continue back and forth for several repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","CALVES","HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["lateral bound"],"media":[{"id":"lateral-bound-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lateral_Bound/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lateral-bound-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lateral_Bound/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Po, Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-lateral-box-jump","slug":"lateral-box-jump","name":"Lateral Box Jump","description":"Accessory exercise for the quadriceps, with glutes, calves, hamstrings assisting.","instructions":["Assume a comfortable standing position, with a short box positioned next to you. This will be your starting position.","Quickly dip into a quarter squat to initiate the stretch reflex, and immediately reverse direction to jump up and to the side.","Bring your knees high enough to ensure your feet have good clearance over the box.","Land on the center of the box, using your legs to absorb the impact.","Carefully jump down to the other side of the box, and continue going back and forth for several repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","CALVES","HAMSTRINGS"],"equipment":"OTHER","tags":["lateral box jump"],"media":[{"id":"lateral-box-jump-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lateral_Box_Jump/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lateral-box-jump-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lateral_Box_Jump/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite, unterstützt von Po, Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-lateral-cone-hops","slug":"lateral-cone-hops","name":"Lateral Cone Hops","description":"Accessory exercise for the quadriceps, with glutes, calves, hamstrings assisting.","instructions":["Position a number of cones in a row several feet apart.","Stand next to the end of the cones, facing 90 degrees to the direction of travel. This will be your starting position.","Begin the jump by dipping with the knees to initiate a stretch reflex, and immediately reverse direction to push off the ground, jumping up and sideways over the cone.","Use your legs to absorb impact upon landing, and rebound into the next jump, continuing down the row of cones."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","CALVES","HAMSTRINGS"],"equipment":"OTHER","tags":["lateral cone hops"],"media":[{"id":"lateral-cone-hops-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lateral_Cone_Hops/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lateral-cone-hops-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lateral_Cone_Hops/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite, unterstützt von Po, Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-lateral-raise-with-bands","slug":"lateral-raise-with-bands","name":"Lateral Raise - With Bands","description":"Resistance band exercise for the shoulders.","instructions":["To begin, stand on an exercise band so that tension begins at arm's length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on the sides of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.","Use your side shoulders to lift the handles to the sides as you exhale. Continue to lift the handles until they are slightly above parallel. Tip: As you lift the handles, slightly tilt the hand as if you were pouring water and keep your arms extended. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"BAND","tags":["lateral raise - with bands"],"media":[{"id":"lateral-raise-with-bands-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lateral_Raise_-_With_Bands/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lateral-raise-with-bands-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lateral_Raise_-_With_Bands/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Widerstandsband) für die Schultern.","instructions":null}},{"id":"ex-lateral-raises","slug":"lateral-raises","name":"Lateral Raises","description":"Dumbbell exercise for the shoulders.","instructions":["This exercise works the deltoid muscle of the shoulder. The movement starts with the arms straight, and the hands holding weights at the sides or in front of the body. Body is in a slight forward-leaning position with hips and knees bent a little. Arms are kept straight or slightly bent, and raised through an arc of movement in the coronal plane that terminates when the hands are at approximately shoulder height. Weights are lowered to the starting position, completing one rep. When using a cable machine the individual stands with the coronal plane in line with the pulley, which is at or near the ground.[9] The exercise can be completed one shoulder at a time (with the other hand used to stabilize the body against the weight moved), or with both hands simultaneously if two parallel pulleys are available."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["lateral raises","seitheben"],"media":[{"id":"lateral-raises-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/148/lateral-dumbbell-raises-large-2.png","caption":"Lateral Raises","attribution":"wger.de · Everkinetic","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Seitheben","description":"Übung (Kurzhantel) für die Schultern.","instructions":["Aufrechter Stand, Kopf nach vorne gerichtet, eine Kurzhantel in jeder Hand.","Handflächen nach innen, in Richtung des Körpers, gerichtet.","Hebe die Hanteln seitlich nach oben, ohne Schwung zu holen. Atme aus. Die Ellenbogen sind leicht gebeugt. Hebe die Kurzhanteln soweit, bis die Arme parallel zum Boden sind.","Am obersten Punkt sollten deine Handflächen nach unten zeigen.","Am höchsten Punkt hältst du für 1-2 Sekunden inne und ziehst deine Schulterblätter zusammen.","Führe die Hanteln langsam wieder nach unten in die Ausgangsposition und atme ein."]}},{"id":"ex-lateral-rows-on-cable-one-armed","slug":"lateral-rows-on-cable-one-armed","name":"Lateral Rows on Cable, One Armed","description":"Cable exercise for the shoulders.","instructions":["Set cable at waist height, start with arm across your belly and move han over and out too other side, one arm at the time."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["lateral rows on cable, one armed","seitheben am kabel, einarmig"],"media":[{"id":"lateral-rows-on-cable-one-armed-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/349/9d969203-9cb6-4d47-9c31-fef53bfe1de5.png","caption":"Lateral Rows on Cable, One Armed","attribution":"wger.de · philip","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Seitheben am Kabel, Einarmig","description":"Übung (Kabelzug) für die Schultern.","instructions":["Stelle dich aufrecht neben einem Kabelzug und halte dich mit der einen Hand fest, mit der anderen nimmst du den Kabelgriff. Hebe nun den Arm mit dem Gewicht seitlich, strecke ihn aber nicht aus. Bewege während der Übung nur diesen Arm, schwinge nicht mit und drehe deinen Rumpf auch nicht mit. Auf dem höchsten Punkt machst du 1sek. Pause und gehst dann langsam runter. Wenn deine Hand kurz vor deinem Körper ist, bringst du das Gewicht wieder rauf."]}},{"id":"ex-lateral-to-front-raises","slug":"lateral-to-front-raises","name":"Lateral-to-Front Raises","description":"Dumbbell exercise for the shoulders, with back assisting.","instructions":["-(1) Perform a lateral raise, pausing at the top of the lift (2).","-Instead of lowering the weight, bring it to the front of your body so that you appear to be at the top position of a front raise.  You will do this by using a Pec Fly motion, maintaining straight arms. (3)","-Now lower the weight to your quadriceps, or, in other words, lower the dumbbells as though you are completing a Front Raise repetition. (4)","-Reverse the motion:  Perform a front raise (5), at the apex of the lift use a Reverse Fly motion to position the weights at the top of a Lateral Raise (6), and finally, lower the weights until your palms are essentially touching the sides of your thighs (7).  THIS IS ONE REP.","(1) l  front view(2) -l-  FV  (3) l-  side view   (4) l  SV/FV   (5) l-  SV (6) -l-  FV  (7)  l  FV/SV"],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"DUMBBELL","tags":["lateral-to-front raises","seitheben zum frontheben"],"media":[],"source":"wger","de":{"name":"Seitheben zum Frontheben","description":"Übung (Kurzhantel) für die Schultern, unterstützt von Rücken.","instructions":["-(1) Führe ein Seitheben aus und halte am höchsten Punkt der Bewegung kurz inne (2).","-Anstatt das Gewicht abzusenken, führe es vor deinen Körper, sodass du dich scheinbar in der oberen Position eines Fronthebens befindest. Dies erreichst du mit einer Pec-Fly-Bewegung bei gestreckten Armen. (3)","-Senke nun das Gewicht zu deinen Oberschenkeln ab, mit anderen Worten, senke die Kurzhanteln so, als würdest du eine Frontheben-Wiederholung abschließen. (4)","-Kehre die Bewegung um: Führe ein Frontheben aus (5), nutze am höchsten Punkt der Bewegung eine umgekehrte Fly-Bewegung, um die Gewichte in die obere Position eines Seithebens zu bringen (6), und senke schließlich die Gewichte ab, bis deine Handflächen praktisch die Außenseiten deiner Oberschenkel berühren (7). DAS IST EINE WIEDERHOLUNG.","(1) l Frontansicht (2) -l- FA (3) l- Seitenansicht (4) l SA/FA (5) l- SA (6) -l- FA (7) l FA/SA"]}},{"id":"ex-lateral-walk","slug":"lateral-walk","name":"Lateral Walk","description":"Bodyweight exercise for the glutes.","instructions":["Lateral walks, also known as side steps or squat walks, are a type of exercise where you move sideways in a squatting position. They can be performed with or without resistance bands. These exercises strengthen the hip abductors, glutes, and other stabilizing muscles."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["lateral walk","seitwärtsgehen (lateral walk)"],"media":[],"source":"wger","de":{"name":"Seitwärtsgehen (Lateral Walk)","description":"Übung (Körpergewicht) für den Po.","instructions":["Seitwärtsgehen, auch als Side Steps oder Squat Walks bekannt, ist eine Übung, bei der du dich in einer Hockposition seitwärts bewegst. Sie kann mit oder ohne Widerstandsbänder ausgeführt werden. Diese Übungen kräftigen die Hüftabduktoren, die Gesäßmuskulatur und weitere stabilisierende Muskeln."]}},{"id":"ex-latissimus-dorsi-smr","slug":"latissimus-dorsi-smr","name":"Latissimus Dorsi-SMR","description":"Foam roller exercise for the back.","instructions":["While lying on the floor, place a foam roll under your back and to one side, just behind your arm pit. This will be your starting position.","Keep the arm of the side being stretched behind and to the side of you as you shift your weight onto your lats, keeping your upper body off of the ground. Hold for 10-30 seconds, and switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"FOAM_ROLLER","tags":["latissimus dorsi-smr"],"media":[{"id":"latissimus-dorsi-smr-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Latissimus_Dorsi-SMR/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"latissimus-dorsi-smr-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Latissimus_Dorsi-SMR/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Faszienrolle) für den Rücken.","instructions":null}},{"id":"ex-leg-curl","slug":"leg-curl","name":"Leg Curl","description":"Bodyweight exercise for the hamstrings, with glutes assisting.","instructions":["The leg curl, also known as the hamstring curl, is an isolation exercise that targets the hamstring muscles. The exercise involves flexing the lower leg against resistance towards the buttocks. Other exercises that can be used to strengthen the hamstrings are the glute-ham raise and the deadlift."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES"],"equipment":"BODYWEIGHT","tags":["leg curl","beinbeuger"],"media":[{"id":"leg-curl-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/364/b318dde9-f5f2-489f-940a-cd864affb9e3.png","caption":"Leg Curl","attribution":"wger.de · Franpol","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Beinbeuger","description":"Übung (Körpergewicht) für die Oberschenkelrückseite, unterstützt von Po.","instructions":["Der Beinbeuger, auch als Hamstring-Curl bekannt, ist eine Isolationsübung, die auf die hintere Oberschenkelmuskulatur abzielt. Bei der Übung wird der Unterschenkel gegen Widerstand in Richtung Gesäß gebeugt. Weitere Übungen, mit denen sich die hintere Oberschenkelmuskulatur stärken lässt, sind das Glute-Ham-Raise und das Kreuzheben."]}},{"id":"ex-leg-curls-laying","slug":"leg-curls-laying","name":"Leg Curls (laying)","description":"Bodyweight exercise for the hamstrings.","instructions":["Lay on a bench and put your calves behind the leg holder (better if they are hold on around the lower calves). Hold a grip on the bars to make sure the body is firmly in place. Bend your legs bringing the weight up, go slowly back. During the exercise the body should not move, all work is done by the legs."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["leg curls (laying)","beinbeuger liegend"],"media":[{"id":"leg-curls-laying-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/154/lying-leg-curl-machine-large-1.png","caption":"Leg Curls (laying)","attribution":"wger.de · Everkinetic","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Beinbeuger Liegend","description":"Übung (Körpergewicht) für die Oberschenkelrückseite.","instructions":["Lege dich auf dem Bauch auf die Bank und klemme die Beine unter der Halterung (eher im unteren Wadenbereich ansetzen). Halte dich fest und bringe nun das Gewicht nach oben, in dem du die Beinbizeps zusammenziehst, gehe langsam wieder nach unten. Während der Übung muss der Körper fest bleiben."]}},{"id":"ex-leg-lift","slug":"leg-lift","name":"Leg Lift","description":"Bodyweight exercise for the glutes, with hamstrings assisting.","instructions":["While standing up straight with both feet next to each other at around shoulder width, grab a sturdy surface such as the sides of a squat rack or the top of a chair to brace yourself and keep balance.","With or without an ankle weight, lift one leg behind you as if performing a leg curl but standing up while keeping the other leg straight. Breathe out as you perform this movement.","Slowly bring the raised leg back to the floor as you breathe in.","Repeat for the recommended amount of repetitions.","Repeat the movement with the opposite leg."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["leg lift"],"media":[{"id":"leg-lift-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Lift/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"leg-lift-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Lift/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelrückseite.","instructions":null}},{"id":"ex-leg-over-floor-press","slug":"leg-over-floor-press","name":"Leg-Over Floor Press","description":"Kettlebell exercise for the chest, with shoulders, triceps assisting.","instructions":["Lie on the floor with one kettlebell in place on your chest, holding it by the handle. Extend leg on working side over leg on non-working side.Your free arm can be extended out to your side for support.","Press the kettlebll into a locked out position.","Lower the weight until the elbow touches the ground, keeping the kettlebell above the elbow. Repeat for the desired number of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"KETTLEBELL","tags":["leg-over floor press"],"media":[{"id":"leg-over-floor-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg-Over_Floor_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"leg-over-floor-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg-Over_Floor_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-leg-presses-narrow","slug":"leg-presses-narrow","name":"Leg Presses (narrow)","description":"Bodyweight exercise for the quadriceps, with glutes assisting.","instructions":["The exercise is very similar to the wide leg press:","Sit on the machine and put your feet on the platform so far apart  that you could just put another foot in between them. The feet are parallel and point up.","Lower the weight so much, that the knees form a right angle. Push immediately the platform up again, without any pause. When in the lower position, the knees point a bit outwards and the movement should be always fluid."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES"],"equipment":"BODYWEIGHT","tags":["leg presses (narrow)","beinpresse eng"],"media":[{"id":"leg-presses-narrow-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/373/60e2aa21-1910-40d3-9fed-babfee06dd48.png","caption":"Leg Presses (narrow)","attribution":"wger.de · Franpol","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Beinpresse Eng","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Po.","instructions":["In die Maschine setzten und die Füße auf die Auflage stellen. Dabei sollte etwa so viel Platz dazwischen bleiben, dass noch ein Fuß dazwischen Platz hätte. Die Füße sind wie beim normalen Bankdrücken etwas nach außen gedreht.","Der Bewegungsablauf ist wie bei bei der breite Beinpresse: das Gewicht wird so weit abgesenkt, dass die Knie einen rechten Winkel machen. Ohne Pause wird dann das Gewicht nach oben gedrückt. Die Knie zeigen etwas nach außen und werden nie ganz ausgestreckt, die Bewegung bleibt immer flüssig, also weder oben noch unten irgendwelche Pausen einlegen!"]}},{"id":"ex-leg-presses-wide","slug":"leg-presses-wide","name":"Leg Presses (wide)","description":"Bodyweight exercise for the quadriceps, with glutes assisting.","instructions":["Sit on the machine and put your feet on the platform, a bit more than shoulder wide. The feet are turned outwards by a few degrees.","Lower the weight so much, that the knees form a right angle. Push immediately the platform up again, without any pause. When in the lower position, the knees point a bit outwards and the movement should be always fluid."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES"],"equipment":"BODYWEIGHT","tags":["leg presses (wide)","beinpresse (weit)"],"media":[],"source":"wger","de":{"name":"Beinpresse (weit)","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Po.","instructions":["Setze dich an die Maschine und stelle die Füße etwas mehr als schulterbreit auf die Plattform. Die Füße sind ein paar Grad nach außen gedreht.","Senke das Gewicht so weit ab, dass die Knie einen rechten Winkel bilden. Drücke die Plattform sofort wieder nach oben, ohne Pause. In der unteren Position zeigen die Knie etwas nach außen, und die Bewegung sollte stets flüssig sein."]}},{"id":"ex-leg-raise","slug":"leg-raise","name":"Leg Raise","description":"Bodyweight exercise for the core.","instructions":["The leg raise is a strength training exercise which targets the iliopsoas (the anterior hip flexors). Because the abdominal muscles are used isometrically to stabilize the body during the motion, leg raises are also often used to strengthen the rectus abdominis muscle and the internal and external oblique muscles."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["leg raise","beine heben"],"media":[],"source":"wger","de":{"name":"Beine heben","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Ausgangsposition:","Lege Dich auf den Rücken, Füße zusammen, Arme an den Seiten.","Schritte:","Beuge die Knie und strecke sie dann gerade nach oben.","Halte die Beine gerade und senke sie gemeinsam ab, ohne den Boden zu berühren. Je tiefer, desto intensiver ist die Übung.","Hebe beide Beine zusammen an, so dass sie wieder gerade nach oben zeigen.","Wiederholen ab Schritt 2."]}},{"id":"ex-leg-raises-standing","slug":"leg-raises-standing","name":"Leg Raises, Standing","description":"Bodyweight exercise for the core, with chest assisting.","instructions":["Put your forearms on the pads on the leg raise machine, the body is hanging freely. Lift now your legs with a fast movement as high as you can, make a short pause of 1sec at the top, and bring them down again. Make sure that during the exercise your body does not swing, only the legs should move."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["CHEST"],"equipment":"BODYWEIGHT","tags":["leg raises, standing","beinheben aufrecht"],"media":[],"source":"wger","de":{"name":"Beinheben Aufrecht","description":"Übung (Körpergewicht) für den Rumpf, unterstützt von Brust.","instructions":["Stelle dich mit den Unterarmen fest auf die Polster der Beinhebemaschine, der Körper hängt frei nach unten. Hebe nun die Beine so weit wie möglich nach oben, wobei an der höchsten Stelle eine kurze Pause eingelegt wird. Bringe sie dann langsam und kontrolliert wieder nach unten. Während der Übung darf der Körper nicht mitschwingen, nur die Beine sollten sich hier bewegen."]}},{"id":"ex-leg-wheel","slug":"leg-wheel","name":"Leg Wheel","description":"Bodyweight exercise for the core.","instructions":["Lay on the back and lift legs in perpendicular fashion, keeping the knees together.","Start making small circles in one direction with both of your knees with very small range of motion, focusing on abs and keeping your back in contact with the floor."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["leg wheel","beinkreisen"],"media":[],"source":"wger","de":{"name":"Beinkreisen","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Lege dich auf den Rücken und hebe die Beine senkrecht nach oben, wobei du die Knie zusammenhältst.","Beginne, mit beiden Knien kleine Kreise in eine Richtung zu beschreiben, mit sehr geringem Bewegungsumfang, konzentriere dich auf die Bauchmuskulatur und halte deinen Rücken in Kontakt mit dem Boden."]}},{"id":"ex-leverage-deadlift","slug":"leverage-deadlift","name":"Leverage Deadlift","description":"Machine exercise for the quadriceps, with glutes, hamstrings assisting.","instructions":["Load the pins to an appropriate weight. Position yourself directly between the handles. Grasp the bottom handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up. This will be your starting position.","Return the weight to the starting position."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","HAMSTRINGS"],"equipment":"MACHINE","tags":["leverage deadlift"],"media":[{"id":"leverage-deadlift-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Deadlift/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"leverage-deadlift-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Deadlift/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Oberschenkelvorderseite, unterstützt von Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-leverage-decline-chest-press","slug":"leverage-decline-chest-press","name":"Leverage Decline Chest Press","description":"Machine exercise for the chest, with shoulders, triceps assisting.","instructions":["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.","Press the handles forward by extending through the elbow.","After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"MACHINE","tags":["leverage decline chest press"],"media":[{"id":"leverage-decline-chest-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Decline_Chest_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"leverage-decline-chest-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Decline_Chest_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-leverage-iso-row","slug":"leverage-iso-row","name":"Leverage Iso Row","description":"Machine exercise for the back, with biceps assisting.","instructions":["Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.","Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.","Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"MACHINE","tags":["leverage iso row"],"media":[{"id":"leverage-iso-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Iso_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"leverage-iso-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Iso_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-leverage-shrug","slug":"leverage-shrug","name":"Leverage Shrug","description":"Machine exercise for the back, with forearms assisting.","instructions":["Load the pins to an appropriate weight. Position yourself directly between the handles.","Grasp the top handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up.","Drive through the floor with your heels, extending your hips and knees as you rise to a standing position. Keep your arms straight throughout the movement, finishing with your shoulders back. This will be your starting position.","Raise the weight by shrugging the shoulders towards your ears, moving straight up and down.","Pause at the top of the motion, and then return the weight to the starting position."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["FOREARMS"],"equipment":"MACHINE","tags":["leverage shrug"],"media":[{"id":"leverage-shrug-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Shrug/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"leverage-shrug-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Shrug/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für den Rücken, unterstützt von Unterarme.","instructions":null}},{"id":"ex-linear-3-part-start-technique","slug":"linear-3-part-start-technique","name":"Linear 3-Part Start Technique","description":"Equipment-free exercise for the hamstrings, with calves, quadriceps assisting.","instructions":["This drill helps you accelerate as quickly as possible into a sprint from a dead stop. It helps to use a line to start from. Begin with two feet on the line. Place your left foot with the toe next to your right ankle. Place your right foot 4-6 inches behind the left.","Place your right hand onto the line, and thing bring your nose close to your left knee.","Squat down as you lean foward, your head being lower than your hips and your weight loaded onto the left leg. This will be your starting position.","Take your left hand up so that it is parallel to the ground, pointing behind you, and explode out when ready."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","QUADRICEPS"],"equipment":"NONE","tags":["linear 3-part start technique"],"media":[{"id":"linear-3-part-start-technique-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Linear_3-Part_Start_Technique/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"linear-3-part-start-technique-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Linear_3-Part_Start_Technique/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelrückseite, unterstützt von Waden, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-linear-acceleration-wall-drill","slug":"linear-acceleration-wall-drill","name":"Linear Acceleration Wall Drill","description":"Equipment-free exercise for the hamstrings, with calves, glutes, quadriceps assisting.","instructions":["Lean at around 45 degrees against a wall. Your feet should be together, glutes contracted.","Begin by lifting your right knee quickly, pausing, and then driving it straight down into the ground.","Switch legs, raising the opposite knee, and then attacking the ground straight down.","Repeat once more with your right leg, and as soon as the right foot strikes the ground hammer them out rapidly, alternating left and right as fast as you can."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","GLUTES","QUADRICEPS"],"equipment":"NONE","tags":["linear acceleration wall drill"],"media":[{"id":"linear-acceleration-wall-drill-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Linear_Acceleration_Wall_Drill/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"linear-acceleration-wall-drill-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Linear_Acceleration_Wall_Drill/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelrückseite, unterstützt von Waden, Po, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-linear-depth-jump","slug":"linear-depth-jump","name":"Linear Depth Jump","description":"Accessory exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["You will need two boxes or benches spaced a few feet away from each other. Begin by standing on one box facing towards the other platform.","To initiate the movement, gently drop down to the ground between your platforms, allowing the knees and hips to flex.","Reverse the motion by exploding, extending through the hips, knees, and ankles to jump onto the other platform.","Land softly, asborbing the impact through the legs."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"OTHER","tags":["linear depth jump"],"media":[{"id":"linear-depth-jump-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Linear_Depth_Jump/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"linear-depth-jump-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Linear_Depth_Jump/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-london-bridges","slug":"london-bridges","name":"London Bridges","description":"Accessory exercise for the back, with biceps, forearms assisting.","instructions":["Attach a climbing rope to a high beam or cross member. Below it, ensure that the smith machine bar is locked in place with the safeties and cannot move. Alternatively, a secure box could also be utilized.","Stand on the bar, using the rope to balance yourself. This will be your starting position.","Keeping your body straight, lean back and lower your body by slowly going hand over hand with the rope. Continue until you are perpendicular to the ground.","Keeping your body straight, reverse the motion, going hand over hand back to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","FOREARMS"],"equipment":"OTHER","tags":["london bridges"],"media":[{"id":"london-bridges-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/London_Bridges/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"london-bridges-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/London_Bridges/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Bizeps, Unterarme.","instructions":null}},{"id":"ex-long-pulley-low-row","slug":"long-pulley-low-row","name":"Long-Pulley (low Row)","description":"Cable exercise for the back, with biceps assisting.","instructions":["Sit down, put your feet on the supporting points and grab the bar with a wide grip. Pull the weight with a rapid movement towards your belly button, not upper. Keep your arms and elbows during the movement close to your body. Your shoulders are pulled together. Let the weight slowly down till your arms are completely stretched."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"CABLE","tags":["long-pulley (low row)","long-pulley"],"media":[{"id":"long-pulley-low-row-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/394/5e0c015f-9e4c-4034-beea-b0afbf15d0bd.png","caption":"Long-Pulley (low Row)","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Long-Pulley","description":"Übung (Kabelzug) für den Rücken, unterstützt von Bizeps.","instructions":["Setze dich hin, stelle die Füße auf die Stützstellen ab und greife die Stange mit breitem Griff. Ziehe nun die Hände auf den Nabel, nicht höher. Dabei sollten die Arme nahe am Körper bleiben und die Schultern so weit wie möglich zusammengezogen werden. Lasse langsam und kontrolliert das Gewicht wieder nach vorne bis die Arme vollständig ausgestreckt sind."]}},{"id":"ex-long-pulley-narrow","slug":"long-pulley-narrow","name":"Long-Pulley, Narrow","description":"Cable exercise for the back, with biceps assisting.","instructions":["The exercise is the same as the regular long pulley, but with a narrow grip:","Sit down, put your feet on the supporting points and grab the bar with a wide grip. Pull the weight with a rapid movement towards your belly button, not upper. Keep your arms and elbows during the movement close to your body. Your shoulders are pulled together. Let the weight slowly down till your arms are completely stretched."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"CABLE","tags":["long-pulley, narrow","long-pulley (eng)"],"media":[],"source":"wger","de":{"name":"Long-Pulley (eng)","description":"Übung (Kabelzug) für den Rücken, unterstützt von Bizeps.","instructions":["Der Bewegungsablauf ist wie der vom Long-Pulley mit breitem Griff.","Setze dich hin, stelle die Füße auf die Stützstellen ab und greife die Stange. Ziehe nun die Hände auf den Nabel, nicht höher. Dabei sollten die Arme nahe am Körper bleiben und die Schultern so weit wie möglich zusammengezogen werden. Lasse langsam und kontrolliert das Gewicht wieder nach vorne bis die Arme vollständig ausgestreckt sind."]}},{"id":"ex-looking-at-ceiling","slug":"looking-at-ceiling","name":"Looking At Ceiling","description":"Equipment-free exercise for the quadriceps.","instructions":["Kneel on the floor, holding your heels with both hands.","Lift your buttocks up and forward while bringing your head back to look up at the ceiling, to give an arch in your back."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"NONE","tags":["looking at ceiling"],"media":[{"id":"looking-at-ceiling-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Looking_At_Ceiling/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"looking-at-ceiling-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Looking_At_Ceiling/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-low-box-squat-wide-stance","slug":"low-box-squat-wide-stance","name":"Low Box Squat - Wide Stance","description":"Barbell exercise for the glutes, with quadriceps assisting.","instructions":["Unrack the bar and set your stance wide, beyond your hips.  Push your hips back and sit down to a box that takes you below parallel.  Sit completely down, do not touch and go.  Then explosively stand up.  Stay tight in your upper back and torso throughout the movement."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["QUADRICEPS"],"equipment":"BARBELL","tags":["low box squat - wide stance","box squat mit weitem stand"],"media":[],"source":"wger","de":{"name":"Box Squat mit weitem Stand","description":"Übung (Langhantel) für den Po, unterstützt von Oberschenkelvorderseite.","instructions":["Nimm die Stange aus der Ablage und nimm einen weiten Stand ein, breiter als deine Hüfte. Schiebe die Hüfte nach hinten und setze dich auf eine Box, die dich unter die Parallele bringt. Setze dich vollständig hin, kein Touch-and-go. Stehe dann explosiv auf. Bleibe während der gesamten Bewegung im oberen Rücken und Oberkörper fest angespannt."]}},{"id":"ex-low-cable-cross-over-nb","slug":"low-cable-cross-over-nb","name":"Low-Cable Cross-Over - NB","description":"Cable exercise for the chest, with shoulders assisting.","instructions":["The low-cable cross-over is an isolation movement that uses a cable stack to target the upper portion of the pectoral muscles. It is common in upper-body and chest-focused muscle-building workouts, often in combination with presses or flyes from other angles to target all portions of the chest."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS"],"equipment":"CABLE","tags":["low-cable cross-over - nb","low-cable cross-over am kabelzug"],"media":[{"id":"low-cable-cross-over-nb-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1296/c42782fe-337a-44f4-9079-7f6dedab4885.png","caption":"Low-Cable Cross-Over - NB","attribution":"wger.de · JackSparrow","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Low-Cable Cross-Over am Kabelzug","description":"Übung (Kabelzug) für die Brust, unterstützt von Schultern.","instructions":["Der Low-Cable Cross-Over ist eine Isolationsübung, die den Kabelzug nutzt, um den oberen Teil der Brustmuskulatur gezielt zu beanspruchen. Sie kommt häufig in Oberkörper- und brustorientierten Muskelaufbau-Workouts vor, oft in Kombination mit Drück- oder Flyes-Übungen aus anderen Winkeln, um alle Bereiche der Brust zu treffen."]}},{"id":"ex-low-cable-crossover","slug":"low-cable-crossover","name":"Low Cable Crossover","description":"Cable exercise for the chest, with shoulders assisting.","instructions":["To move into the starting position, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand.","Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and your arms straight. This will be your starting position.","With a slight bend in your arms, draw your hands upward and toward the midline of your body. Your hands should come together in front of your chest, palms facing up.","Return your arms back to the starting position after a brief pause."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS"],"equipment":"CABLE","tags":["low cable crossover"],"media":[{"id":"low-cable-crossover-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Low_Cable_Crossover/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"low-cable-crossover-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Low_Cable_Crossover/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Brust, unterstützt von Schultern.","instructions":null}},{"id":"ex-low-cable-triceps-extension","slug":"low-cable-triceps-extension","name":"Low Cable Triceps Extension","description":"Cable exercise for the triceps.","instructions":["Select the desired weight and lay down face up on the bench of a seated row machine that has a rope attached to it. Your head should be pointing towards the attachment.","Grab the outside of the rope ends with your palms facing each other (neutral grip).","Position your elbows so that they are bent at a 90 degree angle and your upper arms are perpendicular (90 degree angle) to your torso. Tip: Keep the elbows in and make sure that the upper arms point to the ceiling while your forearms point towards the pulley above your head. This will be your starting position.","As you breathe out, extend your lower arms until they are straight and vertical. The upper arms and elbows remain stationary throughout the movement. Only the forearms should move. Contract the triceps hard for a second.","As you breathe in slowly return to the starting position.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["low cable triceps extension"],"media":[{"id":"low-cable-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Low_Cable_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"low-cable-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Low_Cable_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Trizeps.","instructions":null}},{"id":"ex-low-pulley-cable-fly","slug":"low-pulley-cable-fly","name":"Low Pulley Cable Fly","description":"Cable exercise for the chest, with shoulders assisting.","instructions":["Adjust the cable machine: Set the pulley to the lowest setting possible.","Choose your handles: You can use neutral grip handles (palms facing each other) or straight handles depending on your preference. Neutral grip might be easier on your wrists.","Stand with proper form: Stand with your feet shoulder-width apart, knees slightly bent, and core engaged. Maintain a slight arch in your lower back throughout the exercise.","Grip the handles: Grab the handles with your chosen grip and step back a small step or two until there's slight tension on the cables.","Initiate the movement: Keep your elbows slightly bent throughout the exercise. Imagine you're giving someone a big hug. Squeeze your chest muscles as you bring your hands together in front of your chest.","Control the movement: Focus on squeezing your chest muscles rather than using your arms to pull the handles.","Peak contraction: Briefly hold the squeeze at the top of the movement with your hands together at chest level.","Return slowly: Slowly release the tension and return the handles back down to the starting position with your arms slightly extended but not locked out."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS"],"equipment":"CABLE","tags":["low pulley cable fly","kabel-fly am unteren kabelzug"],"media":[],"source":"wger","de":{"name":"Kabel-Fly am unteren Kabelzug","description":"Übung (Kabelzug) für die Brust, unterstützt von Schultern.","instructions":["Stelle die Kabelmaschine ein: Setze den Kabelzug auf die niedrigstmögliche Position.","Wähle deine Griffe: Du kannst Griffe mit neutralem Griff (Handflächen zueinander) oder gerade Griffe verwenden, je nach Vorliebe. Ein neutraler Griff ist möglicherweise schonender für deine Handgelenke.","Stelle dich in der richtigen Haltung hin: Stelle dich mit schulterbreit aufgestellten Füßen hin, die Knie leicht gebeugt und die Rumpfmuskulatur angespannt. Halte während der gesamten Übung eine leichte Wölbung im unteren Rücken.","Greife die Griffe: Greife die Griffe mit deinem gewählten Griff und gehe ein bis zwei kleine Schritte zurück, bis eine leichte Spannung auf den Kabeln liegt.","Leite die Bewegung ein: Halte deine Ellbogen während der gesamten Übung leicht gebeugt. Stelle dir vor, du würdest jemanden fest umarmen. Spanne deine Brustmuskeln an, während du deine Hände vor deiner Brust zusammenführst.","Kontrolliere die Bewegung: Konzentriere dich darauf, deine Brustmuskeln anzuspannen, statt mit deinen Armen die Griffe zu ziehen.","Maximale Kontraktion: Halte die Anspannung kurz am oberen Punkt der Bewegung, mit deinen Händen zusammen auf Brusthöhe.","Kehre langsam zurück: Löse langsam die Spannung und führe die Griffe wieder nach unten in die Ausgangsposition, mit leicht gestreckten, aber nicht durchgedrückten Armen."]}},{"id":"ex-low-pulley-row-to-neck","slug":"low-pulley-row-to-neck","name":"Low Pulley Row To Neck","description":"Cable exercise for the shoulders, with biceps, back assisting.","instructions":["Sit on a low pulley row machine with a rope attachment.","Grab the ends of the rope using a palms-down grip and sit with your back straight and your knees slightly bent. Tip: Keep your back almost completely vertical and your arms fully extended in front of you. This will be your starting position.","While keeping your torso stationary, lift your elbows and start bending them as you pull the rope towards your neck while exhaling. Throughout the movement your upper arms should remain parallel to the floor. Tip: Continue this motion until your hands are almost next to your ears (the forearms will not be parallel to the floor at the end of the movement as they will be angled a bit upwards) and your elbows are out away from your sides.","After holding for a second or so at the contracted position, come back slowly to the starting position as you inhale. Tip: Again, during no part of the movement should the torso move.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BICEPS","BACK"],"equipment":"CABLE","tags":["low pulley row to neck"],"media":[{"id":"low-pulley-row-to-neck-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Low_Pulley_Row_To_Neck/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"low-pulley-row-to-neck-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Low_Pulley_Row_To_Neck/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Schultern, unterstützt von Bizeps, Rücken.","instructions":null}},{"id":"ex-lower-back-curl","slug":"lower-back-curl","name":"Lower Back Curl","description":"Bodyweight exercise for the core.","instructions":["Lie on your stomach with your arms out to your sides. This will be your starting position.","Using your lower back muscles, extend your spine lifting your chest off of the ground. Do not use your arms to push yourself up. Keep your head up during the movement. Repeat for 10-20 repetitions."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["lower back curl"],"media":[{"id":"lower-back-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lower_Back_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lower-back-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lower_Back_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-lower-back-extensions","slug":"lower-back-extensions","name":"Lower Back Extensions","description":"Bodyweight exercise for the back.","instructions":["Engage the muscles","Lift your bottom slightly","Controlled movement","Slow movement","Don't use momentum","Keep your upper body straight"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["lower back extensions","rückenstrecker (unterer rücken)"],"media":[{"id":"lower-back-extensions-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1348/a3769120-2445-49f2-97d3-afc1238bfc2a.webp","caption":"Lower Back Extensions","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Rückenstrecker (unterer Rücken)","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Muskulatur anspannen","Hintern ein wenig anheben","Kontrollierte Bewegung","Langsame Bewegung","Kein Schwung holen","Oberkörper gerade halten"]}},{"id":"ex-lower-back-smr","slug":"lower-back-smr","name":"Lower Back-SMR","description":"Foam roller exercise for the back.","instructions":["In a seated position, place a foam roll under your lower back. Cross your arms in front of you and protract your shoulders. This will be your starting position.","Raise your hips off of the floor and lean back, keeping your weight on your lower back. Now shift your weight slightly to one side, keeping your weight off of the spine and on the muscles to the side of it. Roll over your lower back, holding points of tension for 10-30 seconds. Repeat on the other side."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"FOAM_ROLLER","tags":["lower back-smr"],"media":[{"id":"lower-back-smr-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lower_Back-SMR/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lower-back-smr-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lower_Back-SMR/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Faszienrolle) für den Rücken.","instructions":null}},{"id":"ex-lunge-pass-through","slug":"lunge-pass-through","name":"Lunge Pass Through","description":"Kettlebell exercise for the hamstrings, with calves, glutes, quadriceps assisting.","instructions":["Stand with your torso upright holding a kettlebell in your right hand. This will be your starting position.","Step forward with your left foot and lower your upper body down by flexing the hip and the knee, keeping the torso upright. Lower your back knee until it nearly touches the ground.","As you lunge, pass the kettlebell under your front leg to your opposite hand.","Pressing through the heel of your foot, return to the starting position.","Repeat the movement for the recommended amount of repetitions, alternating legs."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","GLUTES","QUADRICEPS"],"equipment":"KETTLEBELL","tags":["lunge pass through"],"media":[{"id":"lunge-pass-through-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lunge_Pass_Through/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lunge-pass-through-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lunge_Pass_Through/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Oberschenkelrückseite, unterstützt von Waden, Po, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-lunge-sprint","slug":"lunge-sprint","name":"Lunge Sprint","description":"Machine exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Adjust a bar in a Smith machine to an appropriate height. Position yourself under the bar, racking it across the back of your shoulders. Unrack the bar, and then split your feet, moving one foot forward and one foot back. This will be your starting position.","Lower your back knee nearly to the ground, flexing the knees and lowering your hips as you do so.","At the bottom of the descent, immediately reverse direction. Explosively drive through the heel of your front foot with light pressure from your back foot. Jump up and reverse the position of your legs.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"MACHINE","tags":["lunge sprint"],"media":[{"id":"lunge-sprint-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lunge_Sprint/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lunge-sprint-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lunge_Sprint/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-lunges","slug":"lunges","name":"Lunges","description":"Bodyweight exercise for the glutes, with quadriceps, hamstrings assisting.","instructions":["Starting position:","Stand with back straight.","Steps:","Take a large step forward with your left leg.","Bring your pelvis down until you almost touch the floor with your right knee.","Bring your pelvis back up.","Return to the starting position by stepping back.","Repeat, switching legs each time."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["QUADRICEPS","HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["lunges","ausfallschritte"],"media":[{"id":"lunges-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/984/5c7ffe68-e7b2-47f3-a22a-f9cc28640432.png","caption":"Lunges","attribution":"wger.de · Franpol","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Ausfallschritte","description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelvorderseite, Oberschenkelrückseite.","instructions":["Ausgangsposition:","Mit geradem Rücken stehen.","Schritte:","Machen Sie mit dem linken Bein einen großen Schritt nach vorn.","Senken Sie Ihr Becken, bis Sie mit dem rechten Knie fast den Boden berühren.","Bringen Sie Ihr Becken wieder nach oben.","Kehren Sie in die Ausgangsposition zurück, indem Sie einen Schritt zurücktreten.","Wiederholen Sie den Vorgang und wechseln Sie dabei jedes Mal die Beine."]}},{"id":"ex-lying-bent-leg-groin","slug":"lying-bent-leg-groin","name":"Lying Bent Leg Groin","description":"Accessory exercise for the quadriceps.","instructions":["Lie on your back with your knees bent and the soles of the feet pressed together. Have your partner hold your knees. This will be your starting position.","Attempt to squeeze your knees together, while your partner prevents any movement from occurring.","After 10-20 seconds, relax your muscles as your partner gently pushes your knees towards the floor. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["lying bent leg groin"],"media":[{"id":"lying-bent-leg-groin-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Bent_Leg_Groin/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-bent-leg-groin-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Bent_Leg_Groin/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-lying-cable-curl","slug":"lying-cable-curl","name":"Lying Cable Curl","description":"Cable exercise for the biceps.","instructions":["Grab a straight bar or E-Z bar attachment that is attached to the low pulley with both hands, using an underhand (palms facing up) shoulder-width grip.","Lie flat on your back on top of an exercise mat in front of the weight stack with your feet flat against the frame of the pulley machine and your legs straight.","With your arms extended and your elbows close to your body slightly bend your arms. This will be your starting position.","While keeping your upper arms stationary and the elbows close to your body, curl the bar up slowly toward your chest as you breathe out and you squeeze the biceps.","After a second squeeze at the top of the movement, slowly return to the starting position.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["lying cable curl"],"media":[{"id":"lying-cable-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Cable_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-cable-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Cable_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Bizeps.","instructions":null}},{"id":"ex-lying-cambered-barbell-row","slug":"lying-cambered-barbell-row","name":"Lying Cambered Barbell Row","description":"Barbell exercise for the back, with biceps assisting.","instructions":["Place a cambered bar underneath an exercise bench.","Lie face down on the exercise bench and grab the bar using a palms down (pronated grip) that is wider than shoulder width. This will be your starting position.","As you exhale row the bar up as you keep the elbows close to your body to either your chest, in order to target the upper mid back, or to your stomach if targeting the lats is your goal.","After a second hold at the top, lower back down to the starting position slowly as you inhale."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"BARBELL","tags":["lying cambered barbell row"],"media":[{"id":"lying-cambered-barbell-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Cambered_Barbell_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-cambered-barbell-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Cambered_Barbell_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-lying-close-grip-bar-curl-on-high-pulley","slug":"lying-close-grip-bar-curl-on-high-pulley","name":"Lying Close-Grip Bar Curl On High Pulley","description":"Cable exercise for the biceps.","instructions":["Place a flat bench in front of a high pulley or lat pulldown machine.","Hold the straight bar attachment using an underhand grip (palms up) that is about shoulder width.","Lie on your back with your head over the end of the bench.","Now extend your arms straight above your shoulders. Your torso and your arms should make a 90-degree angle and the elbows should be in. This will be your starting position.","As you breathe out, curl the bar down in a semicircular motion until it touches your chin. Squeeze the biceps for a second at the top contracted position. Tip: As you execute this motion only the forearms should move. At no time should the upper arms be moving at all. They are to remain perpendicular throughout the movement.","Return to starting position slowly.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["lying close-grip bar curl on high pulley"],"media":[{"id":"lying-close-grip-bar-curl-on-high-pulley-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Close-Grip_Bar_Curl_On_High_Pulley/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-close-grip-bar-curl-on-high-pulley-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Close-Grip_Bar_Curl_On_High_Pulley/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Bizeps.","instructions":null}},{"id":"ex-lying-close-grip-barbell-triceps-extension-behind-the-head","slug":"lying-close-grip-barbell-triceps-extension-behind-the-head","name":"Lying Close-Grip Barbell Triceps Extension Behind The Head","description":"Barbell exercise for the triceps.","instructions":["While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head close to the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.","Extend your arms in front of you and slowly bring the bar back in a semi circular motion (while keeping the arms extended) to a position over your head. At the end of this step your arms should be overhead and parallel to the floor. This will be your starting position. Tip: Keep your elbows in at all times.","As you inhale, lower the bar by bending at the elbows and while keeping the upper arm stationary. Keep lowering the bar until your forearms are perpendicular to the floor.","As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion until the lower arms are also parallel to the floor. Contract the triceps hard at the top of the movement for a second. Tip: Again, only the forearms should move. The upper arms should remain stationary at all times.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["lying close-grip barbell triceps extension behind the head"],"media":[{"id":"lying-close-grip-barbell-triceps-extension-behind-the-head-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-close-grip-barbell-triceps-extension-behind-the-head-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Trizeps.","instructions":null}},{"id":"ex-lying-close-grip-barbell-triceps-press-to-chin","slug":"lying-close-grip-barbell-triceps-press-to-chin","name":"Lying Close-Grip Barbell Triceps Press To Chin","description":"EZ-bar exercise for the triceps.","instructions":["While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head off the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.","Extend your arms in front of you as you hold the barbell over your chest. The arms should be perpendicular to your torso (90-degree angle). This will be your starting position.","As you inhale, lower the bar in a semi-circular motion by bending at the elbows and while keeping the upper arm stationary and elbows in. Keep lowering the bar until it lightly touches your chin.","As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion. Contract the triceps hard at the top of the movement for a second. Tip: Again, only the forearms should move. The upper arms should remain stationary at all times.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"EZ_BAR","tags":["lying close-grip barbell triceps press to chin"],"media":[{"id":"lying-close-grip-barbell-triceps-press-to-chin-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Close-Grip_Barbell_Triceps_Press_To_Chin/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-close-grip-barbell-triceps-press-to-chin-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Close-Grip_Barbell_Triceps_Press_To_Chin/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (SZ-Stange) für den Trizeps.","instructions":null}},{"id":"ex-lying-crossover","slug":"lying-crossover","name":"Lying Crossover","description":"Bodyweight exercise for the glutes.","instructions":["Lie on your back with your legs extended.","Cross one leg over your body with the knee bent, attempting to touch the knee to the ground. Your partner should kneel beside you, holding your shoulder down with one hand and controlling the crossed leg with the other. this will be your starting position.","Attempt to raise the bent knee off of the ground as your partner prevents any actual movement.","After 10-20 seconds, relax the leg as your partner gently presses the knee towards the floor. Repeat with the other side."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["lying crossover"],"media":[{"id":"lying-crossover-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Crossover/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-crossover-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Crossover/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Po.","instructions":null}},{"id":"ex-lying-face-down-plate-neck-resistance","slug":"lying-face-down-plate-neck-resistance","name":"Lying Face Down Plate Neck Resistance","description":"Accessory exercise for the shoulders.","instructions":["Lie face down with your whole body straight on a flat bench while holding a weight plate behind your head. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the upper chest, neck and face to be off the bench. This will be your starting position.","While keeping the plate secure on the back of your head slowly lower your head (as in saying \"yes\") as you breathe in.","Raise your head back up to the starting position in a semi-circular motion as you breathe out. Hold the contraction for a second.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["lying face down plate neck resistance"],"media":[{"id":"lying-face-down-plate-neck-resistance-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Face_Down_Plate_Neck_Resistance/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-face-down-plate-neck-resistance-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Face_Down_Plate_Neck_Resistance/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Schultern.","instructions":null}},{"id":"ex-lying-face-up-plate-neck-resistance","slug":"lying-face-up-plate-neck-resistance","name":"Lying Face Up Plate Neck Resistance","description":"Accessory exercise for the shoulders.","instructions":["Lie face up with your whole body straight on a flat bench while holding a weight plate on top of your forehead. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the traps, neck and head to be off the bench. This will be your starting position.","While keeping the plate secure on your forehead slowly lower your head back in a semi-circular motion as you breathe in.","Raise your head back up to the starting position in a semi-circular motion as you breathe out. Hold the contraction for a second.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["lying face up plate neck resistance"],"media":[{"id":"lying-face-up-plate-neck-resistance-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Face_Up_Plate_Neck_Resistance/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-face-up-plate-neck-resistance-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Face_Up_Plate_Neck_Resistance/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Schultern.","instructions":null}},{"id":"ex-lying-glute","slug":"lying-glute","name":"Lying Glute","description":"Bodyweight exercise for the glutes.","instructions":["Lie on your back with your partner kneeling beside you.","Flex the hip of one leg, raising it off of the floor. Rotate the leg so the foot is over the opposite hip, the lower leg perpendicular to your body. Your partner should hold the knee and ankle in place. This will be your starting position.","Attempt to push your leg towards your partner, who should be preventing any actual movement of the leg.","After 10-20 seconds, completely relax as your partner gently pushes the ankle and knee towards your chest. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["lying glute"],"media":[{"id":"lying-glute-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Glute/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-glute-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Glute/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Po.","instructions":null}},{"id":"ex-lying-hamstring","slug":"lying-hamstring","name":"Lying Hamstring","description":"Accessory exercise for the hamstrings, with calves assisting.","instructions":["Lie on your back with your legs extended. Your partner should be kneeling beside you. Raise one leg up towards the ceiling and have your partner hold the ankle. Your partner can use their shoulder to brace your leg if necessary. This will be your starting position.","With your partner holding your leg in place, attempt to flex the knee, contracting the hamstrings for 10-20 seconds.","Then relax your leg, allowing your partner to gently push the leg towards your head. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching. Switch sides once complete."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES"],"equipment":"OTHER","tags":["lying hamstring"],"media":[{"id":"lying-hamstring-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Hamstring/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-hamstring-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Hamstring/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelrückseite, unterstützt von Waden.","instructions":null}},{"id":"ex-lying-high-bench-barbell-curl","slug":"lying-high-bench-barbell-curl","name":"Lying High Bench Barbell Curl","description":"Barbell exercise for the biceps.","instructions":["Lie face forward on a tall flat bench while holding a barbell with a supinated grip (palms facing up). Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Your upper body should be positioned in a way that the upper chest is over the end of the bench and the barbell is hanging in front of you with the arms extended and perpendicular to the floor. This will be your starting position.","While keeping the elbows in and the upper arms stationary, curl the weight up in a semi-circular motion as you contract the biceps and exhale. Hold at the top of the movement for a second.","As you inhale, slowly go back to the starting position. Tip: Maintain full control of the weight at all times and avoid any swinging. Remember, only the forearms should move throughout the movement.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["lying high bench barbell curl"],"media":[{"id":"lying-high-bench-barbell-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_High_Bench_Barbell_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-high-bench-barbell-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_High_Bench_Barbell_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Bizeps.","instructions":null}},{"id":"ex-lying-machine-squat","slug":"lying-machine-squat","name":"Lying Machine Squat","description":"Machine exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Adjust the leg machine to a height that will allow you to get inside it with your knees bent and the thighs slightly below parallel.","Once you select the weight, position yourself inside the machine face up with the knees bent and thighs slightly below parallel to the platform. Make sure that the knees do not go past the toes. The angle created between the hamstrings and the calves should be one that is slightly less than 90 degrees (since your starting position requires you to start slightly below parallel). Your back and your head should be resting on the machine while your shoulders are pressed under the shoulder pads.","Place your hands by the handles and position your feet slightly pointing out at a shoulder width position. This will be your starting position.","While pressing with the balls of the feet as you breathe out, make your whole body erect as you squeeze the quads. Hold the contracted position for a second. Tip: Since you are starting below parallel, you can opt to use your hands to help you up by pressing on your thighs only on the first repetition.","Slowly squat down as you inhale but instead of going all the way down to the starting position, just stop once your thighs are parallel to the platform. The angle between your hamstrings and calves should be a 90-degree angle.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"MACHINE","tags":["lying machine squat"],"media":[{"id":"lying-machine-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Machine_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-machine-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Machine_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-lying-one-arm-lateral-raise","slug":"lying-one-arm-lateral-raise","name":"Lying One-Arm Lateral Raise","description":"Dumbbell exercise for the shoulders.","instructions":["While holding a dumbbell in one hand, lay with your chest down on a flat bench. The other hand can be used to hold to the leg of the bench for stability.","Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position.","Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhale. Tip: Maintain your arm perpendicular to the torso while keeping your arm extended throughout the movement. Also, keep the contraction at the top for a second.","Slowly lower the dumbbell to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["lying one-arm lateral raise"],"media":[{"id":"lying-one-arm-lateral-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_One-Arm_Lateral_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-one-arm-lateral-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_One-Arm_Lateral_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern.","instructions":null}},{"id":"ex-lying-prone-quadriceps","slug":"lying-prone-quadriceps","name":"Lying Prone Quadriceps","description":"Bodyweight exercise for the quadriceps.","instructions":["Lay face down on the floor with your partner kneeling beside you. Flex one knee and raise that leg off the ground, attempting to touch your glutes with your foot. Your partner should hold the knee and ankle. This will be your starting position.","Attempt to extend your knee while your partner prevents any actual movement.","After 10-20 seconds, relax your muscles as your partner gently pushes the foot towards your glutes, further stretching the quadriceps and hip flexors.","After 10-20 seconds, switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["lying prone quadriceps"],"media":[{"id":"lying-prone-quadriceps-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Prone_Quadriceps/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-prone-quadriceps-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Prone_Quadriceps/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-lying-rear-delt-raise","slug":"lying-rear-delt-raise","name":"Lying Rear Delt Raise","description":"Dumbbell exercise for the shoulders.","instructions":["While holding a dumbbell in each hand, lay with your chest down on a flat bench.","Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position.","Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms perpendicular to the torso while keeping them extended throughout the movement. Also, keep the contraction at the top for a second.","Slowly lower the dumbbells to the starting position as you inhale.","Repeat for the recommended amount of repetitions and then switch to the other arm."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["lying rear delt raise"],"media":[{"id":"lying-rear-delt-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Rear_Delt_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-rear-delt-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Rear_Delt_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern.","instructions":null}},{"id":"ex-lying-rotator-cuff-exercise","slug":"lying-rotator-cuff-exercise","name":"Lying Rotator Cuff Exercise","description":"Dumbbell exercise for the shoulders.","instructions":["This is an excercise for problems with the rotator cuff. Primary  Infraspinatus, secondary Teres Minor.","Lying on side. Keep elbow on waist and in 90 dgr angle. Rotate towards stomach. Add weight as fit."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["lying rotator cuff exercise","rotatorenmanschette im liegen"],"media":[],"source":"wger","de":{"name":"Rotatorenmanschette im Liegen","description":"Übung (Kurzhantel) für die Schultern.","instructions":["Dies ist eine Übung bei Problemen mit der Rotatorenmanschette. Primär wird der Infraspinatus beansprucht, sekundär der Teres minor.","Lege dich auf die Seite. Halte den Ellbogen an der Taille und in einem 90°-Winkel. Rotiere in Richtung Bauch. Füge nach Belieben Gewicht hinzu."]}},{"id":"ex-lying-supine-dumbbell-curl","slug":"lying-supine-dumbbell-curl","name":"Lying Supine Dumbbell Curl","description":"Dumbbell exercise for the biceps.","instructions":["Lie down on a flat bench face up while holding a dumbbell in each arm on top of your thighs.","Bring the dumbbells to the sides with the arms extended and the palms of the hands facing your thighs (neutral grip).","While keeping the arms close to your torso and elbows in, slowly lower your arms (as you keep them extended with a slight bend at the elbows) as far down towards the floor as you can go. Once you cannot go down any further, lock your upper arms in that position and that will be your starting position.","As you breathe out, slowly begin to curl the weights up as you simultaneously rotate your wrists so that the palms of the hands face up. Continue curling the weight until your biceps are fully contracted and squeeze hard at the top position for a second. Tip: Only the forearms should move. Upper arms should remain stationary and elbows should stay in throughout the movement.","Return back to the starting position very slowly."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["lying supine dumbbell curl"],"media":[{"id":"lying-supine-dumbbell-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Supine_Dumbbell_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-supine-dumbbell-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Supine_Dumbbell_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps.","instructions":null}},{"id":"ex-lying-t-bar-row","slug":"lying-t-bar-row","name":"Lying T-Bar Row","description":"Machine exercise for the back, with biceps assisting.","instructions":["Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad. Tip: In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper chest at the top of the pad.","Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of your back you want to emphasize.","Lift the bar off the rack and extend your arms in front of you. This will be your starting position.","As you exhale slowly pull the weight up and squeeze your back at the top of the movement. Tip: Keep the upper arms as close to the torso as possible throughout the movement in order to better engage the back muscles. Also, do not lift your body off of the pad at any time and refrain from using the biceps to lift the weight.","After a second contraction at the top of the movement, as you inhale, slowly go back down to the starting position.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"MACHINE","tags":["lying t-bar row"],"media":[{"id":"lying-t-bar-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_T-Bar_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-t-bar-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_T-Bar_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-lying-triceps-extensions","slug":"lying-triceps-extensions","name":"Lying Triceps Extensions","description":"Barbell exercise for the triceps.","instructions":["Starting position for this","practical triceps exercise is lying on a standard bench holding a barbell or two dumbbells in both hands with an overhand grip, hands at shoulder width apart.","Begin with arms over your upper","chest and elbows bent back at about a 45-degree angle.","First bend at the elbows and","then allow the upper arm to drop back, bringing the barbell/dumbbells behind your","head and down toward the floor. In terms of upper arm position, the barbell/dumbbells should never be fully above your head, but instead behind it, to","ensure that you’re targeting the triceps."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["lying triceps extensions","liegendes trizepsstrecken"],"media":[],"source":"wger","de":{"name":"Liegendes Trizepsstrecken","description":"Übung (Langhantel) für den Trizeps.","instructions":["Die Ausgangsposition für diese","praktische Trizepsübung ist liegend auf einer normalen Bank, mit einer Langhantel oder zwei Kurzhanteln in beiden Händen im Obergriff, die Hände schulterbreit auseinander.","Beginne mit den Armen über deiner oberen","Brust und den Ellbogen in einem Winkel von etwa 45 Grad nach hinten gebeugt.","Beuge zuerst die Ellbogen und","lasse dann den Oberarm nach hinten sinken, sodass die Langhantel/Kurzhanteln hinter deinen","Kopf und nach unten Richtung Boden kommen. Was die Oberarmposition betrifft, sollte sich die Langhantel/sollten sich die Kurzhanteln nie vollständig über deinem Kopf befinden, sondern hinter ihm, um","sicherzustellen, dass du den Trizeps ansprichst."]}},{"id":"ex-lying-triceps-kickback","slug":"lying-triceps-kickback","name":"Lying Triceps Kickback","description":"Dumbbell exercise for the triceps.","instructions":["Set the bench to an 60deg angle. Stand still and rest your upper body on the inclined bench, ensuring a nearly straight line of your entire body. Squeeze your shoulder blades together, so that your elbows are located behind your torso with your upper arms nearly parallel to the floor. Lift the dumbbells until your arms form a straight line. Slowly lower the dumbbells back to the initial position. Initial position corresponds to an rectangular position of upper and lower arms."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["lying triceps kickback","liegender trizeps-kickback"],"media":[],"source":"wger","de":{"name":"Liegender Trizeps-Kickback","description":"Übung (Kurzhantel) für den Trizeps.","instructions":["Stelle die Bank auf einen Winkel von 60 Grad ein. Stehe still und lege deinen Oberkörper auf die geneigte Bank, sodass dein gesamter Körper eine nahezu gerade Linie bildet. Ziehe die Schulterblätter zusammen, sodass sich deine Ellbogen hinter deinem Oberkörper befinden und deine Oberarme nahezu parallel zum Boden sind. Hebe die Kurzhanteln an, bis deine Arme eine gerade Linie bilden. Senke die Kurzhanteln langsam wieder in die Ausgangsposition ab. Die Ausgangsposition entspricht einer rechtwinkligen Position von Ober- und Unterarm."]}},{"id":"ex-lying-triceps-press","slug":"lying-triceps-press","name":"Lying Triceps Press","description":"EZ-bar exercise for the triceps.","instructions":["Lie on a flat bench with either an e-z bar (my preference) or a straight bar placed on the floor behind your head and your feet on the floor.","Grab the bar behind you, using a medium overhand (pronated) grip, and raise the bar in front of you at arms length. Tip: The arms should be perpendicular to the torso and the floor. The elbows should be tucked in. This is the starting position.","As you breathe in, slowly lower the weight until the bar lightly touches your forehead while keeping the upper arms and elbows stationary.","At that point, use the triceps to bring the weight back up to the starting position as you breathe out.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"EZ_BAR","tags":["lying triceps press"],"media":[{"id":"lying-triceps-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Triceps_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"lying-triceps-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Triceps_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (SZ-Stange) für den Trizeps.","instructions":null}},{"id":"ex-machine-bench-press","slug":"machine-bench-press","name":"Machine Bench Press","description":"Machine exercise for the chest, with shoulders, triceps assisting.","instructions":["Sit down on the Chest Press Machine and select the weight.","Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms.","Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the starting position.","Now bring the handles back towards you as you breathe in.","Push the handles away from you as you flex your pecs and you breathe out. Hold the contraction for a second before going back to the starting position.","Repeat for the recommended amount of reps.","When finished step on the lever again and slowly get the handles back to their original place."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"MACHINE","tags":["machine bench press"],"media":[{"id":"machine-bench-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Bench_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"machine-bench-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Bench_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-machine-bicep-curl","slug":"machine-bicep-curl","name":"Machine Bicep Curl","description":"Machine exercise for the biceps.","instructions":["Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.","Perform the movement by flexing the elbow, pulling your lower arm towards your upper arm.","Pause at the top of the movement, and then slowly return the weight to the starting position.","Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["machine bicep curl","bizepscurl-maschine"],"media":[{"id":"machine-bicep-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Bicep_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"machine-bicep-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Bicep_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Bizepscurl-Maschine","description":"Übung (Maschine) für den Bizeps.","instructions":["Die Bizepscurl-Maschine ist darauf ausgelegt, die Bizepsmuskulatur zu isolieren und einen kontrollierten Bewegungsumfang zu ermöglichen. Setze dich an die Maschine, den Rücken gegen das Polster gelehnt, und stelle den Sitz so ein, dass deine Arme mit den Griffen oder Polstern der Maschine ausgerichtet sind. Greife die Griffe fest, halte deine Ellbogen fixiert und curle die Griffe nach oben, indem du deinen Bizeps anspannst. Senke die Griffe langsam in die Startposition ab und behalte während der gesamten Bewegung die Kontrolle."]}},{"id":"ex-machine-glute-extension","slug":"machine-glute-extension","name":"Machine glute extension","description":"Machine exercise for the glutes.","instructions":["A GHD hip extension is one of the best exercises for the glutes. While the exercise mainly targets the glutes, it is also excellent for the lower back, the calves and the hamstrings."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["machine glute extension","gesäßstrecken an der maschine"],"media":[],"source":"wger","de":{"name":"Gesäßstrecken an der Maschine","description":"Übung (Maschine) für den Po.","instructions":["Eine Hüftstreckung am GHD ist eine der besten Übungen für die Gesäßmuskulatur. Obwohl die Übung sich hauptsächlich auf die Gesäßmuskulatur konzentriert, ist sie auch hervorragend für die Lendengegend, die Waden und die hintere Oberschenkelmuskulatur."]}},{"id":"ex-machine-hip-abduction","slug":"machine-hip-abduction","name":"Machine Hip Abduction","description":"Machine exercise for the glutes.","instructions":["Technique and Execution","Starting Position","Seated Positioning: Sit in the machine with back against the pad","Leg Placement: Inner thighs against the machine's padded resistance points","Adjust Machine: Set seat position to align your hip joint with the machine's pivot point","Movement Technique","Start with legs together or slightly pressed against the inner pads","Slowly push legs outward, spreading them apart"],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["machine hip abduction","hüftabduktion an der maschine"],"media":[{"id":"machine-hip-abduction-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1748/923a3ff7-c269-49bd-9f03-697151a40f06.jpg","caption":"Machine Hip Abduction","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Hüftabduktion an der Maschine","description":"Übung (Maschine) für den Po.","instructions":["Technik und Ausführung","Ausgangsposition","Sitzposition: Setze dich in die Maschine, den Rücken am Polster","Beinplatzierung: Die Innenseiten der Oberschenkel liegen an den gepolsterten Widerstandspunkten der Maschine an","Maschine einstellen: Stelle die Sitzposition so ein, dass dein Hüftgelenk auf einer Linie mit dem Drehpunkt der Maschine liegt","Bewegungstechnik","Beginne mit geschlossenen Beinen oder leicht gegen die inneren Polster gedrückt","Drücke die Beine langsam nach außen und spreize sie auseinander"]}},{"id":"ex-machine-triceps-extension","slug":"machine-triceps-extension","name":"Machine Triceps Extension","description":"Machine exercise for the triceps.","instructions":["Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.","Perform the movement by extending the elbow, pulling your lower arm away from your upper arm.","Pause at the completion of the movement, and then slowly return the weight to the starting position.","Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["machine triceps extension"],"media":[{"id":"machine-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"machine-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für den Trizeps.","instructions":null}},{"id":"ex-marching-high-knees","slug":"marching-high-knees","name":"Marching High Knees","description":"Bodyweight exercise for the quadriceps, with calves, glutes, core assisting.","instructions":["A low-impact cardio and mobility exercise that strengthens the hip flexors and improves balance.","​Movement: Stand tall and lift one knee toward your chest as high as comfortable.","​Arms: Swing the opposite arm forward as you lift your knee, similar to a walking motion.","​Core: Keep your abs engaged to maintain an upright posture.","​Pace: Perform the movement with control, alternating legs rhythmically."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","ABS_CORE"],"equipment":"BODYWEIGHT","tags":["marching high knees","knieheben im stand"],"media":[{"id":"marching-high-knees-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1965/03c08a42-dedb-4a46-8d15-acaf497a35a2.png","caption":"Marching High Knees","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Knieheben im Stand","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Rumpf.","instructions":["Eine gelenkschonende Cardio- und Mobilitätsübung, die die Hüftbeuger stärkt und das Gleichgewicht verbessert.","Bewegung: Stehe aufrecht und hebe ein Knie so weit wie angenehm zur Brust.","Arme: Schwinge den gegenüberliegenden Arm nach vorne, während du das Knie hebst, ähnlich wie beim Gehen.","Rumpf: Halte deine Bauchmuskulatur angespannt, um eine aufrechte Haltung zu bewahren.","Tempo: Führe die Bewegung kontrolliert aus und wechsle die Beine rhythmisch ab."]}},{"id":"ex-medicine-ball-chest-pass","slug":"medicine-ball-chest-pass","name":"Medicine Ball Chest Pass","description":"Accessory exercise for the chest, with shoulders, triceps assisting.","instructions":["You will need a partner for this exercise. Lacking one, this movement can be performed against a wall.","Begin facing your partner holding the medicine ball at your torso with both hands.","Pull the ball to your chest, and reverse the motion by extending through the elbows. For sports applications, you can take a step as you throw.","Your partner should catch the ball, and throw it back to you.","Receive the throw with both hands at chest height."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"OTHER","tags":["medicine ball chest pass"],"media":[{"id":"medicine-ball-chest-pass-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Medicine_Ball_Chest_Pass/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"medicine-ball-chest-pass-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Medicine_Ball_Chest_Pass/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-medicine-ball-full-twist","slug":"medicine-ball-full-twist","name":"Medicine Ball Full Twist","description":"Accessory exercise for the core, with shoulders assisting.","instructions":["For this exercise you will need a medicine ball and a partner. Stand back to back with your partner, spaced 2-3 feet apart. This will be your starting position.","Hold the ball in front of the trunk. Open the hips and turn the shoulders at the same time as your partner.","For full rotation, you and your partner should twist in the same direction, i.e. counter-clockwise.","Pass the ball to your partner, and both of you can now twist in the opposite direction to repeat the procedure."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["SHOULDERS"],"equipment":"OTHER","tags":["medicine ball full twist"],"media":[{"id":"medicine-ball-full-twist-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Medicine_Ball_Full_Twist/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"medicine-ball-full-twist-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Medicine_Ball_Full_Twist/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rumpf, unterstützt von Schultern.","instructions":null}},{"id":"ex-medicine-ball-scoop-throw","slug":"medicine-ball-scoop-throw","name":"Medicine Ball Scoop Throw","description":"Accessory exercise for the shoulders, with core, hamstrings, quadriceps assisting.","instructions":["Assume a semisquat stance with a medicine ball in your hands. Your arms should hang so the ball is near your feet.","Begin by thrusting the hips forward as you extend through the legs, jumping up.","As you do, swing your arms up and over your head, keeping them extended, releasing the ball at the peak of your movement. The goal is to throw the ball the greatest distance behind you."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["ABS_CORE","HAMSTRINGS","QUADRICEPS"],"equipment":"OTHER","tags":["medicine ball scoop throw"],"media":[{"id":"medicine-ball-scoop-throw-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Medicine_Ball_Scoop_Throw/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"medicine-ball-scoop-throw-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Medicine_Ball_Scoop_Throw/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Schultern, unterstützt von Rumpf, Oberschenkelrückseite, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-mentzer-pulldown","slug":"mentzer-pulldown","name":"Mentzer Pulldown","description":"Cable exercise for the biceps, with back assisting.","instructions":["Close grip front facing Pull down, while focusing on Biceps, Increases activation of biceps over the whole range, Avoid activating Lats."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["BACK"],"equipment":"CABLE","tags":["mentzer pulldown","mentzer-latzug"],"media":[{"id":"mentzer-pulldown-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1971/729af526-19a0-4d3d-a258-196c7575d139.jpg","caption":"Mentzer Pulldown","attribution":"wger.de · Athlean-X","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Mentzer-Latzug","description":"Übung (Kabelzug) für den Bizeps, unterstützt von Rücken.","instructions":["Latzug mit engem Griff zur Vorderseite, mit Fokus auf den Bizeps. Erhöht die Aktivierung des Bizeps über den gesamten Bewegungsumfang. Vermeide es, den Latissimus zu aktivieren."]}},{"id":"ex-middle-back-shrug","slug":"middle-back-shrug","name":"Middle Back Shrug","description":"Dumbbell exercise for the back.","instructions":["Lie facedown on an incline bench while holding a dumbbell in each hand. Your arms should be fully extended hanging down and pointing towards the floor. The palms of your hands should be facing each other. This will be your starting position.","As you exhale, squeeze your shoulder blades together and hold the contraction for a full second. Tip: This movement is just like the reverse action of a hug, or trying to perform rear laterals as if you had no arms.","As you inhale go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["middle back shrug"],"media":[{"id":"middle-back-shrug-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Middle_Back_Shrug/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"middle-back-shrug-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Middle_Back_Shrug/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Rücken.","instructions":null}},{"id":"ex-middle-back-stretch","slug":"middle-back-stretch","name":"Middle Back Stretch","description":"Equipment-free exercise for the back, with core assisting.","instructions":["Stand so your feet are shoulder width apart and your hands are on your hips.","Twist at your waist until you feel a stretch. Hold for 10 to 15 seconds, then twist to the other side."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["ABS_CORE"],"equipment":"NONE","tags":["middle back stretch"],"media":[{"id":"middle-back-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Middle_Back_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"middle-back-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Middle_Back_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Rücken, unterstützt von Rumpf.","instructions":null}},{"id":"ex-military-press-mit-sz-bar","slug":"military-press-mit-sz-bar","name":"Military Press mit SZ-Bar","description":"EZ-bar exercise for the shoulders, with back, triceps assisting.","instructions":["On an SZ-bar grip your hands on the outside of each bend and stand with your arms straight down, palms facing your legs. Pull the bar (bending your arms at the elbow) to your chest, and the push the bar above your head (arms as straight as possible). Return the bar to your chest by dropping your arms at the elbows. Return the bar to it's origional position (stand with your arms straight down, palms facing your legs.)"],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK","TRICEPS"],"equipment":"EZ_BAR","tags":["military press mit sz-bar","military press mit sz-stange"],"media":[{"id":"military-press-mit-sz-bar-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/418/fa2a2207-43cb-4dc0-bc2a-039e32544790.png","caption":"Military Press mit SZ-Bar","attribution":"wger.de · Franpol","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Military Press mit SZ-Stange","description":"Übung (SZ-Stange) für die Schultern, unterstützt von Rücken, Trizeps.","instructions":["Greife bei einer SZ-Stange mit den Händen jeweils an der Außenseite der Biegungen und stehe mit gerade nach unten hängenden Armen, die Handflächen zu den Beinen gerichtet. Ziehe die Stange (indem du die Arme im Ellenbogen beugst) zur Brust und drücke die Stange dann über den Kopf (Arme so gerade wie möglich). Führe die Stange zurück zur Brust, indem du die Arme im Ellenbogen absenkst. Bringe die Stange in ihre Ausgangsposition zurück (stehe mit gerade nach unten hängenden Armen, die Handflächen zu den Beinen gerichtet)."]}},{"id":"ex-mixed-grip-chin","slug":"mixed-grip-chin","name":"Mixed Grip Chin","description":"Accessory exercise for the back, with biceps assisting.","instructions":["Using a spacing that is just about 1 inch wider than shoulder width, grab a pull-up bar with the palms of one hand facing forward and the palms of the other hand facing towards you. This will be your starting position.","Now start to pull yourself up as you exhale. Tip: With the arm that has the palms facing up concentrate on using the back muscles in order to perform the movement. The elbow of that arm should remain close to the torso. With the other arm that has the palms facing forward, the elbows will be away but in line with the torso. You will concentrate on using the lats to pull your body up.","After a second contraction at the top, start to slowly come down as you inhale.","Repeat for the recommended amount of repetitions.","On the following set, switch grips; so if you had the right hand with the palms facing you and the left one with the palms facing forward, on the next set you will have the palms facing forward for the right hand and facing you for the left."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"OTHER","tags":["mixed grip chin"],"media":[{"id":"mixed-grip-chin-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Mixed_Grip_Chin/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"mixed-grip-chin-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Mixed_Grip_Chin/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-monster-walk","slug":"monster-walk","name":"Monster Walk","description":"Resistance band exercise for the glutes.","instructions":["Place a band around both ankles and another around both knees. There should be enough tension that they are tight when your feet are shoulder width apart.","To begin, take short steps forward alternating your left and right foot.","After several steps, do just the opposite and walk backward to where you started."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":[],"equipment":"BAND","tags":["monster walk"],"media":[{"id":"monster-walk-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Monster_Walk/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"monster-walk-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Monster_Walk/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Widerstandsband) für den Po.","instructions":null}},{"id":"ex-mountain-climbers","slug":"mountain-climbers","name":"Mountain Climbers","description":"Equipment-free exercise for the quadriceps, with chest, hamstrings, shoulders assisting.","instructions":["Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position.","Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CHEST","HAMSTRINGS","SHOULDERS"],"equipment":"NONE","tags":["mountain climbers","bergsteiger"],"media":[{"id":"mountain-climbers-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Mountain_Climbers/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"mountain-climbers-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Mountain_Climbers/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Bergsteiger","description":"Übung (ohne Geräte) für die Oberschenkelvorderseite, unterstützt von Brust, Oberschenkelrückseite, Schultern.","instructions":["Ausgangsposition:","Beginnen Sie in der aufrechten Liegestützposition, auch bekannt als die hohe Plank-Position.Die Hände sollten sich direkt unter den Schultern befinden.Halten Sie Ihren Kopf in einer Linie mit dem Rücken und schauen Sie zum Boden.Die Füße sollten etwa hüftbreit auseinander stehen.","Die Schritte:","Bewegen Sie ein Knie in Richtung Körpermitte zu den Ellbogen und lassen Sie das andere Bein gestreckt.","In einer schnellen, hüpfenden Bewegung strecken Sie das gebeugte Bein aus und ziehen das andere Knie zum Körper.","Wiederholen Sie Schritt 2 im Wechsel mit dem anderen Bein.","Anmerkungen:","Während der gesamten Übung sollte Ihr Rücken so gerade wie möglich bleiben - vermeiden Sie einen Buckel oder einen durchhängenden Rücken."]}},{"id":"ex-moving-claw-series","slug":"moving-claw-series","name":"Moving Claw Series","description":"Equipment-free exercise for the hamstrings, with calves, quadriceps assisting.","instructions":["This move helps prepare your running form to help you excel at sprinting. As you run, be sure to flex the knee, aiming to kick your glutes as the hip extends.","Reload the quad as the leg moves back forward, attacking the ground on the next step.","Ensure that as you run, you block with the arms, punching through in a rapid 1-2 motion."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","QUADRICEPS"],"equipment":"NONE","tags":["moving claw series"],"media":[{"id":"moving-claw-series-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Moving_Claw_Series/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"moving-claw-series-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Moving_Claw_Series/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelrückseite, unterstützt von Waden, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-muscle-snatch","slug":"muscle-snatch","name":"Muscle Snatch","description":"Barbell exercise for the hamstrings, with glutes, back, quadriceps, shoulders, triceps assisting.","instructions":["Begin with a loaded barbell held at the mid thigh position with a wide grip. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.","Begin the pull by driving through the front of the heels, raising the bar. Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body.","Continue raising the bar to the overhead position, without rebending the knees."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","BACK","QUADRICEPS","SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["muscle snatch"],"media":[{"id":"muscle-snatch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Muscle_Snatch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"muscle-snatch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Muscle_Snatch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Po, Rücken, Oberschenkelvorderseite, Schultern, Trizeps.","instructions":null}},{"id":"ex-muscle-up","slug":"muscle-up","name":"Muscle Up","description":"Accessory exercise for the back, with core, biceps, forearms, shoulders, triceps assisting.","instructions":["Grip the rings using a false grip, with the base of your palms on top of the rings. Initiate a pull up by pulling the elbows down to your side, flexing the elbows.","As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.","Maintaining control and stability, extend through the elbow to complete the motion.","Use care when lowering yourself to the ground."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["ABS_CORE","BICEPS","FOREARMS","SHOULDERS","TRICEPS"],"equipment":"OTHER","tags":["muscle up","muscle-up"],"media":[{"id":"muscle-up-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Muscle_Up/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"muscle-up-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Muscle_Up/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Muscle-up","description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Rumpf, Bizeps, Unterarme, Schultern, Trizeps.","instructions":["Der Körper wird dann explosiv durch die Arme in einem kraftvollen Klimmzug nach oben gezogen, mit größerer Geschwindigkeit als bei einem normalen Klimmzug. Wenn die Stange sich der oberen Brust nähert, werden die Handgelenke rasch gebeugt, um die Unterarme über die Stange zu bringen. Der Körper wird nach vorne gelehnt und die Ellbogen werden durch Aktivierung des Trizeps gestreckt. Die Bewegung gilt als abgeschlossen, wenn die Stange auf Höhe der Taille ist und die Arme vollständig gestreckt sind.","Zum Absteigen werden die Arme im Ellbogen gebeugt und der Körper zum Boden abgesenkt, und die Übung kann wiederholt werden.","Da es sich um eine relativ fortgeschrittene Übung handelt, werden Muscle-ups in der Regel zunächst mit einem unterstützenden Kip erlernt. Die Beine schwingen (Kip) nach oben und liefern Schwung, um die explosive Aufwärtskraft zu unterstützen, die nötig ist, um über die Stange aufzusteigen. Fortgeschrittenere Athleten können eine strikte Variante des Muscle-ups ausführen, die langsam und ohne jeglichen Kip durchgeführt wird. Diese Variante beginnt aus einem ruhigen Dead Hang und nutzt isometrische Muskelkontraktion, um langsam und kontrolliert über die Stange aufzusteigen."]}},{"id":"ex-narrow-stance-hack-squats","slug":"narrow-stance-hack-squats","name":"Narrow Stance Hack Squats","description":"Machine exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.","Position your legs in the platform using a less than shoulder width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.","Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).","Now straighten your legs without locking the knees. This will be your starting position.","Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement.","Begin to raise the unit as you exhale by pushing the floor with mainly with the heels of your feet as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"MACHINE","tags":["narrow stance hack squats"],"media":[{"id":"narrow-stance-hack-squats-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Narrow_Stance_Hack_Squats/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"narrow-stance-hack-squats-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Narrow_Stance_Hack_Squats/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-narrow-stance-leg-press","slug":"narrow-stance-leg-press","name":"Narrow Stance Leg Press","description":"Machine exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a less-than-shoulder-width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.","Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.","As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.","Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.","Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"MACHINE","tags":["narrow stance leg press"],"media":[{"id":"narrow-stance-leg-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Narrow_Stance_Leg_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"narrow-stance-leg-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Narrow_Stance_Leg_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-narrow-stance-squats","slug":"narrow-stance-squats","name":"Narrow Stance Squats","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings, back assisting.","instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a less-than-shoulder-width narrow stance with the toes slightly pointed out. Feet should be around 3-6 inches apart. Keep your head up at all times (looking down will get you off balance) and maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","BACK"],"equipment":"BARBELL","tags":["narrow stance squats"],"media":[{"id":"narrow-stance-squats-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Narrow_Stance_Squats/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"narrow-stance-squats-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Narrow_Stance_Squats/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-natural-glute-ham-raise","slug":"natural-glute-ham-raise","name":"Natural Glute Ham Raise","description":"Bodyweight exercise for the hamstrings, with calves, glutes, back assisting.","instructions":["Using the leg pad of a lat pulldown machine or a preacher bench, position yourself so that your ankles are under the pads, knees on the seat, and you are facing away from the machine. You should be upright and maintaining good posture.","This will be your starting position. Lower yourself under control until your knees are almost completely straight.","Remaining in control, raise yourself back up to the starting position.","If you are unable to complete a rep, use a band, a partner, or push off of a box to aid in completing a repetition."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","GLUTES","BACK"],"equipment":"BODYWEIGHT","tags":["natural glute ham raise"],"media":[{"id":"natural-glute-ham-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Natural_Glute_Ham_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"natural-glute-ham-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Natural_Glute_Ham_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelrückseite, unterstützt von Waden, Po, Rücken.","instructions":null}},{"id":"ex-neck-half-circles","slug":"neck-half-circles","name":"Neck half circles","description":"Bodyweight exercise for the back.","instructions":["Starting position:","Start sitting or standing. Lean your head against one of your shoulders, but don't push.","Steps:","In one slower fluid motion and with your head relaxed and not pushing in any direction:","bring your head down toward your chest.","then lean back aganst your other shoulder.","then back toward the chest again.4.and finally toward the starting position.","Keep repeating this."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["neck half circles","nacken-halbkreise"],"media":[],"source":"wger","de":{"name":"Nacken-Halbkreise","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Ausgangsposition:","Beginnen Sie im Sitzen oder Stehen. Lehnen Sie Ihren Kopf gegen eine Ihrer Schultern, aber drücken Sie nicht.","Schritte:","Führen Sie eine langsame, fließende Bewegung aus, wobei Ihr Kopf entspannt ist und in keine Richtung drückt:","Bringen Sie den Kopf nach unten zur Brust.","lehnen Sie sich dann gegen die andere Schulter zurück","dann wieder zurück zur Brust","und schließlich zurück in die Ausgangsposition."]}},{"id":"ex-neck-press","slug":"neck-press","name":"Neck Press","description":"Barbell exercise for the chest, with shoulders, triceps assisting.","instructions":["Lie back on a flat bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your neck.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["neck press"],"media":[{"id":"neck-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Neck_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"neck-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Neck_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-neck-smr","slug":"neck-smr","name":"Neck-SMR","description":"Accessory exercise for the shoulders.","instructions":["Using a muscle roller or a rolling pin, place the roller behind your head and against your neck. Make sure that you do not place the roller directly against the spine, but turned slightly so that the roller is pressed against the muscles to either side of the spine. This will be your starting position.","Starting at the top of your neck, slowly roll down the muscles of your neck, pausing at points of tension for 10-30 seconds."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["neck-smr"],"media":[{"id":"neck-smr-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Neck-SMR/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"neck-smr-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Neck-SMR/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Schultern.","instructions":null}},{"id":"ex-negative-crunches","slug":"negative-crunches","name":"Negative Crunches","description":"Bodyweight exercise for the core.","instructions":["Sit yourself on the decline bench and fix your legs. Cross your arms over the chest and bring with a rolling movement your upper body up, go now without a pause and with a slow movement down again. Don't let your head move during the exercise."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["negative crunches","crunches an negativbank"],"media":[{"id":"negative-crunches-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/93/Decline-crunch-1.png","caption":"Negative Crunches","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Crunches an Negativbank","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Setze dich auf die Negativbank und fixiere deine Beine. Kreuze deine Arme über die Brust und bringe den Oberkörper nach oben, den Kopf dabei nicht nach vorn kippen. Gehe langsam wieder runter."]}},{"id":"ex-neutral-grip-chest-pulldown","slug":"neutral-grip-chest-pulldown","name":"Neutral-grip chest pulldown","description":"Cable exercise for the biceps, with back, chest assisting.","instructions":["The lat pulldown is an important exercise for strengthening the back and improving posture, which can contribute to a healthier life. To perform this exercise correctly and avoid injury, it is important to follow a few key steps:","Position yourself in front of the cable machine with your knees slightly bent and your feet on the floor.","Grip the cable handle with your palms facing each other and your hands shoulder-width apart.","Pull the handle down until it touches or comes close to your chest, holding the position for one or two seconds.","Slowly raise the handle back to the starting position, making sure to keep your arms and hands straight and your back straight throughout the movement."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["BACK","CHEST"],"equipment":"CABLE","tags":["neutral-grip chest pulldown","latzug zur brust mit neutralem griff"],"media":[{"id":"neutral-grip-chest-pulldown-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1136/5778a8e9-c606-4843-89c8-9d9469eeb6e4.PNG","caption":"Neutral-grip chest pulldown","attribution":"wger.de · Franpol","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Latzug zur Brust mit neutralem Griff","description":"Übung (Kabelzug) für den Bizeps, unterstützt von Rücken, Brust.","instructions":["Der Latzug zur Brust ist eine wichtige Übung, um den Rücken zu kräftigen und die Haltung zu verbessern, was zu einem gesünderen Leben beitragen kann. Um diese Übung korrekt auszuführen und Verletzungen zu vermeiden, ist es wichtig, einige zentrale Schritte zu befolgen:","Stelle dich vor die Kabelzugmaschine, die Knie leicht gebeugt und die Füße auf dem Boden.","Greife den Griff des Kabelzugs mit den Handflächen zueinander und den Händen schulterbreit auseinander.","Ziehe den Griff nach unten, bis er die Brust berührt oder sich ihr nähert, und halte die Position ein bis zwei Sekunden.","Führe den Griff langsam wieder in die Ausgangsposition nach oben und achte darauf, Arme und Hände gerade und den Rücken während der gesamten Bewegung gerade zu halten."]}},{"id":"ex-neutral-grip-pull-ups-or-trx-rows","slug":"neutral-grip-pull-ups-or-trx-rows","name":"Neutral-grip pull-ups or TRX rows","description":"Bodyweight exercise for the back, with biceps assisting.","instructions":["Pull-Up: Vertical Pull — Focuses more on the Lats (back width).","TRX Row: Horizontal Pull — Focuses more on the Rhomboids/Traps (mid-back thickness and posture)."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"BODYWEIGHT","tags":["neutral-grip pull-ups or trx rows","klimmzüge im neutralen griff oder trx-rudern"],"media":[{"id":"neutral-grip-pull-ups-or-trx-rows-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1738/0529acdf-ede8-42a2-a3e5-8d0c57b7a0e1.jpg","caption":"Neutral-grip pull-ups or TRX rows","attribution":"wger.de · 54str","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Klimmzüge im neutralen Griff oder TRX-Rudern","description":"Übung (Körpergewicht) für den Rücken, unterstützt von Bizeps.","instructions":["Klimmzug: Vertikaler Zug – beansprucht vor allem den Latissimus (Rückenbreite).","TRX-Rudern: Horizontaler Zug – beansprucht vor allem Rhomboiden/Trapezmuskel (Dicke der Rückenmitte und Haltung)."]}},{"id":"ex-no-leg-drive-dumbbell-chest-press","slug":"no-leg-drive-dumbbell-chest-press","name":"No Leg Drive Dumbbell Chest Press","description":"Dumbbell exercise for the chest, with shoulders, triceps assisting.","instructions":["Set up for a normal Dumbbell chest press but lift your leg ups straight or put them on another bench to remove the leg drive."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"DUMBBELL","tags":["no leg drive dumbbell chest press","kurzhantel-brustdrücken ohne beineinsatz"],"media":[],"source":"wger","de":{"name":"Kurzhantel-Brustdrücken ohne Beineinsatz","description":"Übung (Kurzhantel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":["Bereite dich wie für ein normales Kurzhantel-Brustdrücken vor, aber hebe die Beine gestreckt an oder lege sie auf eine andere Bank, um den Beineinsatz auszuschalten."]}},{"id":"ex-no-push-up-burpees","slug":"no-push-up-burpees","name":"No push-up burpees","description":"Bodyweight exercise for the chest.","instructions":["Starting position:","Stand straight, feet hip-width apart.","Steps:","Squat low and support yourself on the floor with your hands between the knees and in front of your feet, your back straight.","Keeping your hands on the floor, jump your legs backward into high plank position.","Jump your feet forward to return to the squat position.","Jump up.","Repeat."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["no push-up burpees","keine liegestütz-burpees"],"media":[],"source":"wger","de":{"name":"Keine Liegestütz-Burpees","description":"Übung (Körpergewicht) für die Brust.","instructions":["Ausgangsposition:","Gerade stehen, Füße hüftbreit auseinander.","Schritte:","Gehen Sie in die Hocke und stützen Sie sich mit den Händen zwischen den Knien und vor den Füßen mit geradem Rücken auf dem Boden ab.","Lassen Sie die Hände auf dem Boden und springen Sie mit den Beinen nach hinten in eine hohe Plank-Position.","Springen Sie mit den Füßen nach vorne, um wieder in die Hocke zu gehen.","Springen Sie hoch.","Wiederholen Sie dies."]}},{"id":"ex-oblique-crunches","slug":"oblique-crunches","name":"Oblique Crunches","description":"Bodyweight exercise for the core.","instructions":["Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put one hand beside your head and the other to the side against the floor.","Make sure your feet are elevated and resting on a flat surface.","Now lift the shoulder in which your hand is touching your head.","Simply elevate your shoulder and body upward until you touch your knee. For example, if you have your right hand besides your head, then you want to elevate your body upwards until your right elbow touches your left knee. The same variation can be applied doing the inverse and using your left elbow to touch your right knee.","After your knee touches your elbow, lower your body until you have reached the starting position.","Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (upward) part of the exercise.","Continue alternating in this manner until all of the recommended repetitions for each side have been completed."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["oblique crunches"],"media":[{"id":"oblique-crunches-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Oblique_Crunches/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"oblique-crunches-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Oblique_Crunches/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-oblique-crunches-on-the-floor","slug":"oblique-crunches-on-the-floor","name":"Oblique Crunches - On The Floor","description":"Bodyweight exercise for the core.","instructions":["Start out by lying on your right side with your legs lying on top of each other. Make sure your knees are bent a little bit.","Place your left hand behind your head.","Once you are in this set position, begin by moving your left elbow up as you would perform a normal crunch except this time the main emphasis is on your obliques.","Crunch as high as you can, hold the contraction for a second and then slowly drop back down into the starting position.","Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (elevation) part of the exercise."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["oblique crunches - on the floor"],"media":[{"id":"oblique-crunches-on-the-floor-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Oblique_Crunches_-_On_The_Floor/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"oblique-crunches-on-the-floor-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Oblique_Crunches_-_On_The_Floor/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-olympic-squat","slug":"olympic-squat","name":"Olympic Squat","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Begin with a barbell supported on top of the traps. The chest should be up, and the head facing forward. Adopt a hip width stance with the feet turned out as needed.","Descend by flexing the knees, refraining from moving the hips back as much as possible. This requires that the knees travel forward; ensure that they stay aligned with the feet. The goal is to keep the torso as upright as possible. Continue all the way down, keeping the weight on the front of the heel.","At the moment the upper legs contact the lower, reverse the motion, driving the weight upward."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"BARBELL","tags":["olympic squat"],"media":[{"id":"olympic-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Olympic_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"olympic-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Olympic_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-on-your-back-quad-stretch","slug":"on-your-back-quad-stretch","name":"On-Your-Back Quad Stretch","description":"Accessory exercise for the quadriceps.","instructions":["Lie on a flat bench or step, and hang one leg and arm over the side.","Bend the knee and hold the top of the foot. As you do this, be careful not to arch your lower back.","Pull the belly button to the spine to stay in neutral. Press your foot down and into your hand. To add the hip stretch, lift the hip of the leg you're holding up toward the ceiling.","Switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["on-your-back quad stretch"],"media":[{"id":"on-your-back-quad-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/On-Your-Back_Quad_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"on-your-back-quad-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/On-Your-Back_Quad_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-on-your-side-quad-stretch","slug":"on-your-side-quad-stretch","name":"On Your Side Quad Stretch","description":"Equipment-free exercise for the quadriceps.","instructions":["Start off by lying on your right side, with your right knee bent at a 90-degree angle resting on the floor in front of you (this stabilizes the torso).","Bend your left knee behind you and hold your left foot with your left hand. To stretch your hip flexor, press your left hip forward as you push your left foot back into your hand. Switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"NONE","tags":["on your side quad stretch"],"media":[{"id":"on-your-side-quad-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/On_Your_Side_Quad_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"on-your-side-quad-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/On_Your_Side_Quad_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-one-arm-against-wall","slug":"one-arm-against-wall","name":"One Arm Against Wall","description":"Equipment-free exercise for the back.","instructions":["From a standing position, place a bent arm against a wall or doorway.","Slowly lean toward your arm until you feel a stretch in your lats."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"NONE","tags":["one arm against wall"],"media":[{"id":"one-arm-against-wall-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Against_Wall/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-against-wall-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Against_Wall/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Rücken.","instructions":null}},{"id":"ex-one-arm-chin-up","slug":"one-arm-chin-up","name":"One Arm Chin-Up","description":"Accessory exercise for the back, with biceps, forearms assisting.","instructions":["For this exercise, start out by placing a towel around a chin up bar.","Grab the chin-up bar with your palm facing you. One hand will be grabbing the chin-up bar and the other will be grabbing the towel.","Bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.v","Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.","Repeat this motion for the prescribed amount of repetitions.","Switch arms and repeat the movement."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","FOREARMS"],"equipment":"OTHER","tags":["one arm chin-up"],"media":[{"id":"one-arm-chin-up-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Chin-Up/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-chin-up-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Chin-Up/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Bizeps, Unterarme.","instructions":null}},{"id":"ex-one-arm-dumbbell-bench-press","slug":"one-arm-dumbbell-bench-press","name":"One Arm Dumbbell Bench Press","description":"Dumbbell exercise for the chest, with shoulders, triceps assisting.","instructions":["Lie down on a flat bench with a dumbbell in one hand on top of your thigh.","By using your thigh to help you get the dumbbell up, clean the dumbbell up so that you can hold it in front of you at shoulder width. Use the hand you are not lifting with to help position the dumbbell over you properly.","Once at shoulder width, rotate your wrist forward so that the palm of your hand is facing away from you. This will be your starting position.","Bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbell at all times. Tip: Use the hand that you are not lifting with to help keep the dumbbell balance as you may struggle a bit at first. Only use your non-lifting hand if it is needed. Otherwise, keep it resting to the side.","As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions of your training program.","Switch arms and repeat the movement."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"DUMBBELL","tags":["one arm dumbbell bench press"],"media":[{"id":"one-arm-dumbbell-bench-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Dumbbell_Bench_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-dumbbell-bench-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Dumbbell_Bench_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-one-arm-dumbbell-preacher-curl","slug":"one-arm-dumbbell-preacher-curl","name":"One Arm Dumbbell Preacher Curl","description":"Dumbbell exercise for the biceps.","instructions":["Grab a dumbbell with the right arm and place the upper arm on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.","As you breathe in, slowly lower the dumbbell until your upper arm is extended and the biceps is fully stretched.","As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbell is at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.","Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.","Switch arms and repeat the movement."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["one arm dumbbell preacher curl"],"media":[{"id":"one-arm-dumbbell-preacher-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Dumbbell_Preacher_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-dumbbell-preacher-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Dumbbell_Preacher_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps.","instructions":null}},{"id":"ex-one-arm-flat-bench-dumbbell-flye","slug":"one-arm-flat-bench-dumbbell-flye","name":"One-Arm Flat Bench Dumbbell Flye","description":"Dumbbell exercise for the chest.","instructions":["Lie down on a flat bench with a dumbbell in one hand resting on top of your thigh. The palm of your hand with the dumbbell in it should be at a neutral grip.","By using your thighs to help you get the dumbbell up, clean the dumbbell so that you can hold it in front of you with your lifting arm being fully extended. Remember to maintain a neutral grip with this exercise. Your non lifting hand should be to the side holding the flat bench for better support. This will be your starting position.","Your arm with the weight should have a slight bend on your elbow in order to prevent stress at the biceps tendon. Begin by lowering your arm with the weight in it out in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, your lifting arm should remain stationary; the movement should only occur at the shoulder joint.","Return your lifting arm back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.","Switch arms and repeat the exercise."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["one-arm flat bench dumbbell flye"],"media":[{"id":"one-arm-flat-bench-dumbbell-flye-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Flat_Bench_Dumbbell_Flye/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-flat-bench-dumbbell-flye-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Flat_Bench_Dumbbell_Flye/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Brust.","instructions":null}},{"id":"ex-one-arm-floor-press","slug":"one-arm-floor-press","name":"One Arm Floor Press","description":"Barbell exercise for the triceps, with chest, shoulders assisting.","instructions":["Lie down on a flat surface with your back pressing against the floor or an exercise mat. Make sure your knees are bent.","Have a partner hand you the bar on one hand. When starting, your arm should be just about fully extended, similar to the starting position of a barbell bench press. However, this time your grip will be neutral (palms facing your torso).","Make sure the hand you are not using to lift the weight is placed by your side.","Begin the exercise by lowering the barbell until your elbow touches the ground. Make sure to breathe in as this is the eccentric (lowering part of the exercise).","Then start lifting the barbell back up to the original starting position. Remember to breathe out during the concentric (lifting part of the exercise).","Repeat until you have performed your recommended repetitions.","Switch arms and repeat the movement."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"BARBELL","tags":["one arm floor press"],"media":[{"id":"one-arm-floor-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Floor_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-floor-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Floor_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-one-arm-heavy-row","slug":"one-arm-heavy-row","name":"One-Arm Heavy Row","description":"Dumbbell exercise for the back.","instructions":["Execution","Rowing phase (concentric):","Pull the dumbbell toward your lower chest or waist, leading with your elbow.","Keep your torso stable — avoid twisting or rotating your shoulders.","Pause at the top and squeeze your lats."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["one-arm heavy row","schweres einarmiges rudern"],"media":[],"source":"wger","de":{"name":"Schweres einarmiges Rudern","description":"Übung (Kurzhantel) für den Rücken.","instructions":["Ausführung","Ruderphase (konzentrisch):","Ziehe die Kurzhantel zu deiner unteren Brust oder Taille, wobei du mit dem Ellenbogen führst.","Halte deinen Oberkörper stabil — vermeide ein Verdrehen oder Rotieren der Schultern.","Halte oben inne und drücke deinen Latissimus zusammen."]}},{"id":"ex-one-arm-high-pulley-cable-side-bends","slug":"one-arm-high-pulley-cable-side-bends","name":"One-Arm High-Pulley Cable Side Bends","description":"Cable exercise for the core.","instructions":["Connect a standard handle to a tower. Move cable to highest pulley position.","Stand with side to cable. With one hand, reach up and grab handle with underhand grip.","Pull down cable until elbow touches your side and the handle is by your shoulder.","Position feet hip-width apart. Place free hand on hip to help gauge pivot point.","Keep arm in static position. Contract oblique to bring the weight down in a side crunch.","Once you reach maximum contraction, slowly release the weight to the starting position. The weight stack should never be unloaded in a resting position. The aim is constant tension during the set.","Repeat to failure.","Then, reposition and repeat the same series of movements on the opposite side."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["one-arm high-pulley cable side bends"],"media":[{"id":"one-arm-high-pulley-cable-side-bends-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_High-Pulley_Cable_Side_Bends/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-high-pulley-cable-side-bends-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_High-Pulley_Cable_Side_Bends/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rumpf.","instructions":null}},{"id":"ex-one-arm-incline-lateral-raise","slug":"one-arm-incline-lateral-raise","name":"One-Arm Incline Lateral Raise","description":"Dumbbell exercise for the shoulders.","instructions":["Lie down sideways on an incline bench press with a dumbbell in the hand. Make sure the shoulder is pressing against the incline bench and the arm is lying across your body with the palm around your navel.","Hold a dumbbell in your uppermost arm while keeping it extended in front of you parallel to the floor. This is your starting position.","While keeping the dumbbell parallel to the floor at all times, perform a lateral raise. Your arm should travel straight up until it is pointing at the ceiling. Tip: Exhale as you perform this movement. Hold the dumbbell in the position and feel the contraction in the shoulders for a second.","While inhaling lower the weight across your body back into the starting position.","Repeat the movement for the prescribed amount of repetitions.","Switch arms and repeat the movement."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["one-arm incline lateral raise"],"media":[{"id":"one-arm-incline-lateral-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Incline_Lateral_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-incline-lateral-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Incline_Lateral_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern.","instructions":null}},{"id":"ex-one-arm-kettlebell-clean","slug":"one-arm-kettlebell-clean","name":"One-Arm Kettlebell Clean","description":"Kettlebell exercise for the hamstrings, with glutes, back, shoulders assisting.","instructions":["Place a kettlebell between your feet. As you bend down to grab the kettlebell, push your butt back and keep your eyes looking forward.","Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.","Return the weight to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","BACK","SHOULDERS"],"equipment":"KETTLEBELL","tags":["one-arm kettlebell clean"],"media":[{"id":"one-arm-kettlebell-clean-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Clean/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-kettlebell-clean-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Clean/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Oberschenkelrückseite, unterstützt von Po, Rücken, Schultern.","instructions":null}},{"id":"ex-one-arm-kettlebell-clean-and-jerk","slug":"one-arm-kettlebell-clean-and-jerk","name":"One-Arm Kettlebell Clean and Jerk","description":"Kettlebell exercise for the shoulders.","instructions":["Hold a kettlebell by the handle.","Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward.","Dip your body by bending the knees, keeping your torso upright.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body's momentum to move the weight.","Receive the weight overhead by returning to a squat position underneath the weight.","Keeping the weight overhead, return to a standing position. Lower the weight to the floor to perform the next repetition."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"KETTLEBELL","tags":["one-arm kettlebell clean and jerk"],"media":[{"id":"one-arm-kettlebell-clean-and-jerk-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Clean_and_Jerk/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-kettlebell-clean-and-jerk-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Clean_and_Jerk/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern.","instructions":null}},{"id":"ex-one-arm-kettlebell-floor-press","slug":"one-arm-kettlebell-floor-press","name":"One-Arm Kettlebell Floor Press","description":"Kettlebell exercise for the chest, with triceps assisting.","instructions":["Lie on the floor holding a kettlebell with one hand, with your upper arm supported by the floor. The palm should be facing in.","Press the kettlebell straight up toward the ceiling, rotating your wrist.","Lower the kettlebell back to the starting position and repeat."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["TRICEPS"],"equipment":"KETTLEBELL","tags":["one-arm kettlebell floor press"],"media":[{"id":"one-arm-kettlebell-floor-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Floor_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-kettlebell-floor-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Floor_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Brust, unterstützt von Trizeps.","instructions":null}},{"id":"ex-one-arm-kettlebell-jerk","slug":"one-arm-kettlebell-jerk","name":"One-Arm Kettlebell Jerk","description":"Kettlebell exercise for the shoulders, with calves, quadriceps, triceps assisting.","instructions":["Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.","Dip your body by bending the knees, keeping your torso upright.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body's momentum to move the weight. Receive the weight overhead by returning to a squat position underneath the weight. Keeping the weight overhead, return to a standing position.","Lower the weight to perform the next repetition."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CALVES","QUADRICEPS","TRICEPS"],"equipment":"KETTLEBELL","tags":["one-arm kettlebell jerk"],"media":[{"id":"one-arm-kettlebell-jerk-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Jerk/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-kettlebell-jerk-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Jerk/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Waden, Oberschenkelvorderseite, Trizeps.","instructions":null}},{"id":"ex-one-arm-kettlebell-military-press-to-the-side","slug":"one-arm-kettlebell-military-press-to-the-side","name":"One-Arm Kettlebell Military Press To The Side","description":"Kettlebell exercise for the shoulders, with triceps assisting.","instructions":["Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces inward. This will be your starting position.","Look at the kettlebell and press it up and out until it is locked out overhead.","Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"KETTLEBELL","tags":["one-arm kettlebell military press to the side"],"media":[{"id":"one-arm-kettlebell-military-press-to-the-side-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Military_Press_To_The_Side/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-kettlebell-military-press-to-the-side-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Military_Press_To_The_Side/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-one-arm-kettlebell-para-press","slug":"one-arm-kettlebell-para-press","name":"One-Arm Kettlebell Para Press","description":"Kettlebell exercise for the shoulders, with triceps assisting.","instructions":["Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.","Hold the kettlebell with the elbow out to the side, and press it up and out until it is locked out overhead.","Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"KETTLEBELL","tags":["one-arm kettlebell para press"],"media":[{"id":"one-arm-kettlebell-para-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Para_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-kettlebell-para-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Para_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-one-arm-kettlebell-push-press","slug":"one-arm-kettlebell-push-press","name":"One-Arm Kettlebell Push Press","description":"Kettlebell exercise for the shoulders, with calves, quadriceps, triceps assisting.","instructions":["Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.","Dip your body by bending the knees, keeping your torso upright.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body's momentum to move the weight. Lower the weight to perform the next repetition."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CALVES","QUADRICEPS","TRICEPS"],"equipment":"KETTLEBELL","tags":["one-arm kettlebell push press"],"media":[{"id":"one-arm-kettlebell-push-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Push_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-kettlebell-push-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Push_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Waden, Oberschenkelvorderseite, Trizeps.","instructions":null}},{"id":"ex-one-arm-kettlebell-row","slug":"one-arm-kettlebell-row","name":"One-Arm Kettlebell Row","description":"Kettlebell exercise for the back, with biceps assisting.","instructions":["Place a kettlebell in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position. Grab the kettlebell and pull it to your stomach, retracting your shoulder blade and flexing the elbow. Keep your back straight. Lower and repeat."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"KETTLEBELL","tags":["one-arm kettlebell row"],"media":[{"id":"one-arm-kettlebell-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-kettlebell-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-one-arm-kettlebell-snatch","slug":"one-arm-kettlebell-snatch","name":"One-Arm Kettlebell Snatch","description":"Kettlebell exercise for the shoulders, with calves, glutes, hamstrings, back, triceps assisting.","instructions":["Place a kettlebell between your feet. Bend your knees and push your butt back to get in the proper starting position.","Look straight ahead and swing the kettlebell back between your legs.","Immediately reverse the direction and drive through with your hips and knees, accelerating the kettlebell upward. As the kettlebell rises to your shoulder rotate your hand and punch straight up, using momentum to receive the weight locked out overhead."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","BACK","TRICEPS"],"equipment":"KETTLEBELL","tags":["one-arm kettlebell snatch"],"media":[{"id":"one-arm-kettlebell-snatch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Snatch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-kettlebell-snatch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Snatch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Waden, Po, Oberschenkelrückseite, Rücken, Trizeps.","instructions":null}},{"id":"ex-one-arm-kettlebell-split-jerk","slug":"one-arm-kettlebell-split-jerk","name":"One-Arm Kettlebell Split Jerk","description":"Kettlebell exercise for the shoulders, with glutes, hamstrings, quadriceps, triceps assisting.","instructions":["Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.","Dip your body by bending the knees, keeping your torso upright.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body's momentum to move the weight.","Receive the weight overhead by returning to a squat position underneath the weight, positioning one leg in front of you and one leg behind you.","Keeping the weight overhead, return to a standing position and bring your feet together. Lower the weight to perform the next repetition."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["GLUTES","HAMSTRINGS","QUADRICEPS","TRICEPS"],"equipment":"KETTLEBELL","tags":["one-arm kettlebell split jerk"],"media":[{"id":"one-arm-kettlebell-split-jerk-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Split_Jerk/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-kettlebell-split-jerk-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Split_Jerk/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Po, Oberschenkelrückseite, Oberschenkelvorderseite, Trizeps.","instructions":null}},{"id":"ex-one-arm-kettlebell-split-snatch","slug":"one-arm-kettlebell-split-snatch","name":"One-Arm Kettlebell Split Snatch","description":"Kettlebell exercise for the shoulders, with hamstrings, quadriceps assisting.","instructions":["Hold a kettlebell in one hand by the handle.","Squat towards the floor, and then reverse the motion, extending the hips, knees, and finally the ankles, to raise the kettlebell overhead.","After fully extending the body, descend into a lunge position to receive the weights overhead, one leg forward and one leg back. Ensure you drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.","Return to a standing position, holding the weight overhead, and bring the feet together. Lower the weight to return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["HAMSTRINGS","QUADRICEPS"],"equipment":"KETTLEBELL","tags":["one-arm kettlebell split snatch"],"media":[{"id":"one-arm-kettlebell-split-snatch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Split_Snatch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-kettlebell-split-snatch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Split_Snatch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Oberschenkelrückseite, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-one-arm-kettlebell-swings","slug":"one-arm-kettlebell-swings","name":"One-Arm Kettlebell Swings","description":"Kettlebell exercise for the hamstrings, with calves, glutes, back, shoulders assisting.","instructions":[],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","GLUTES","BACK","SHOULDERS"],"equipment":"KETTLEBELL","tags":["one-arm kettlebell swings"],"media":[{"id":"one-arm-kettlebell-swings-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Swings/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-kettlebell-swings-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Swings/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Oberschenkelrückseite, unterstützt von Waden, Po, Rücken, Schultern.","instructions":null}},{"id":"ex-one-arm-lat-pulldown","slug":"one-arm-lat-pulldown","name":"One Arm Lat Pulldown","description":"Cable exercise for the back, with biceps assisting.","instructions":["Select an appropriate weight and adjust the knee pad to help keep you down. Grasp the handle with a pronated grip. This will be your starting position.","Pull the handle down, squeezing your elbow to your side as you flex the elbow.","Pause at the bottom of the motion, and then slowly return the handle to the starting position.","For multiple repetitions, avoid completely returning the weight to keep tension on the muscles being worked."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"CABLE","tags":["one arm lat pulldown"],"media":[{"id":"one-arm-lat-pulldown-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Lat_Pulldown/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-lat-pulldown-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Lat_Pulldown/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-one-arm-long-bar-row","slug":"one-arm-long-bar-row","name":"One-Arm Long Bar Row","description":"Barbell exercise for the back, with biceps assisting.","instructions":["Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.","Stand next to the bar, and take a grip with one hand close to the collar. Using your hips and legs, rise to a standing position.","Assume a bent-knee stance with your hips back and your chest up. Your arm should be extended. This will be your starting position.","Pull the weight to your side by retracting the shoulder and flexing the elbow. Do not jerk the weight or cheat during the movement.","After a brief pause, return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"BARBELL","tags":["one-arm long bar row"],"media":[{"id":"one-arm-long-bar-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Long_Bar_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-long-bar-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Long_Bar_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-one-arm-medicine-ball-slam","slug":"one-arm-medicine-ball-slam","name":"One-Arm Medicine Ball Slam","description":"Accessory exercise for the core, with back, shoulders assisting.","instructions":["Start in a standing position with a staggered, athletic stance. Hold a medicine ball in one hand, on the same side as your back leg. This will be your starting position.","Begin by winding the arm, raising the medicine ball above your head. As you do so, extend through the hips, knees, and ankles to load up for the slam.","At peak extension, flex the shoulders, spine, and hips to throw the ball hard into the ground directly in front of you.","Catch the ball on the bounce and continue for the desired number of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["BACK","SHOULDERS"],"equipment":"OTHER","tags":["one-arm medicine ball slam"],"media":[{"id":"one-arm-medicine-ball-slam-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Medicine_Ball_Slam/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-medicine-ball-slam-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Medicine_Ball_Slam/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rumpf, unterstützt von Rücken, Schultern.","instructions":null}},{"id":"ex-one-arm-open-palm-kettlebell-clean","slug":"one-arm-open-palm-kettlebell-clean","name":"One-Arm Open Palm Kettlebell Clean","description":"Kettlebell exercise for the hamstrings, with forearms, glutes, back, quadriceps, shoulders assisting.","instructions":["Place one kettlebell between your feet.","Grab the handle with one hand and raise the kettlebell rapidly, let it flip so that the ball of the kettlebell lands in the palm of your hand.","Throw the kettlebell out in front of you and catch the handle with one hand.","Take the kettlebell to the floor and repeat. Make sure to work both arms."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["FOREARMS","GLUTES","BACK","QUADRICEPS","SHOULDERS"],"equipment":"KETTLEBELL","tags":["one-arm open palm kettlebell clean"],"media":[{"id":"one-arm-open-palm-kettlebell-clean-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Open_Palm_Kettlebell_Clean/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-open-palm-kettlebell-clean-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Open_Palm_Kettlebell_Clean/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Oberschenkelrückseite, unterstützt von Unterarme, Po, Rücken, Oberschenkelvorderseite, Schultern.","instructions":null}},{"id":"ex-one-arm-overhead-kettlebell-squats","slug":"one-arm-overhead-kettlebell-squats","name":"One-Arm Overhead Kettlebell Squats","description":"Kettlebell exercise for the quadriceps, with calves, glutes, hamstrings, shoulders assisting.","instructions":["Clean and press a kettlebell with one arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so. Press the weight overhead by extending through the elbow.This will be your starting position.","Looking straight ahead and keeping a kettlebell locked out above you, flex the knees and hips and lower your torso between your legs, keeping your head and chest up.","Pause at the bottom position for a second before rising back to the top, driving through the heels of your feet."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","SHOULDERS"],"equipment":"KETTLEBELL","tags":["one-arm overhead kettlebell squats"],"media":[{"id":"one-arm-overhead-kettlebell-squats-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Overhead_Kettlebell_Squats/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-overhead-kettlebell-squats-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Overhead_Kettlebell_Squats/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Schultern.","instructions":null}},{"id":"ex-one-arm-pronated-dumbbell-triceps-extension","slug":"one-arm-pronated-dumbbell-triceps-extension","name":"One Arm Pronated Dumbbell Triceps Extension","description":"Dumbbell exercise for the triceps.","instructions":["Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your feet as a pronated grip is required to perform this exercise.","Place your non lifting hand on your bicep for support.","Slowly begin to lower the dumbbell down as you breathe in.","Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise).","Repeat until you have performed your set repetitions.","Switch arms and repeat the movement."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["one arm pronated dumbbell triceps extension"],"media":[{"id":"one-arm-pronated-dumbbell-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Pronated_Dumbbell_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-pronated-dumbbell-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Pronated_Dumbbell_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Trizeps.","instructions":null}},{"id":"ex-one-arm-side-deadlift","slug":"one-arm-side-deadlift","name":"One-Arm Side Deadlift","description":"Barbell exercise for the quadriceps, with core, calves, glutes, hamstrings, back assisting.","instructions":["Stand to the side of a barbell next to its center. Bend your knees and lower your body until you are able to reach the barbell.","Grasp the bar as if you were grabbing a briefcase (palms facing you since the bar is sideways). You may need a wrist wrap if you are using a significant amount of weight. This is your starting position.","Use your legs to help lift the barbell up while exhaling. Your arms should extend fully as bring the barbell up until you are in a standing position.","Slowly bring the barbell back down while inhaling. Tip: Make sure to bend your knees while lowering the weight to avoid any injury from occurring.","Repeat for the recommended amount of repetitions.","Switch arms and repeat the movement."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["ABS_CORE","CALVES","GLUTES","HAMSTRINGS","BACK"],"equipment":"BARBELL","tags":["one-arm side deadlift"],"media":[{"id":"one-arm-side-deadlift-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Side_Deadlift/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-side-deadlift-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Side_Deadlift/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Rumpf, Waden, Po, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-one-arm-side-laterals","slug":"one-arm-side-laterals","name":"One-Arm Side Laterals","description":"Dumbbell exercise for the shoulders.","instructions":["Pick a dumbbell and place it in one of your hands. Your non lifting hand should be used to grab something steady such as an incline bench press. Lean towards your lifting arm and away from the hand that is gripping the incline bench as this will allow you to keep your balance.","Stand with a straight torso and have the dumbbell by your side at arm's length with the palm of the hand facing you. This will be your starting position.","While maintaining the torso stationary (no swinging), lift the dumbbell to your side with a slight bend on the elbow and your hand slightly tilted forward as if pouring water in a glass. Continue to go up until you arm is parallel to the floor. Exhale as you execute this movement and pause for a second at the top.","Lower the dumbbell back down slowly to the starting position as you inhale.","Repeat for the recommended amount of repetitions.","Switch arms and repeat the exercise."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["one-arm side laterals"],"media":[{"id":"one-arm-side-laterals-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Side_Laterals/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-side-laterals-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Side_Laterals/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern.","instructions":null}},{"id":"ex-one-arm-supinated-dumbbell-triceps-extension","slug":"one-arm-supinated-dumbbell-triceps-extension","name":"One Arm Supinated Dumbbell Triceps Extension","description":"Dumbbell exercise for the triceps.","instructions":["Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your face as a supinated grip is required to perform this exercise.","Place your non lifting hand on your bicep for support.","Slowly begin to lower the dumbbell down as you breathe in.","Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise).","Repeat until you have performed your set repetitions.","Switch arms and repeat the movement.","Switch arms again and repeat the movement."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["one arm supinated dumbbell triceps extension"],"media":[{"id":"one-arm-supinated-dumbbell-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Supinated_Dumbbell_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-arm-supinated-dumbbell-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Supinated_Dumbbell_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Trizeps.","instructions":null}},{"id":"ex-one-half-locust","slug":"one-half-locust","name":"One Half Locust","description":"Equipment-free exercise for the quadriceps, with core, biceps, chest assisting.","instructions":["Lie facedown on the floor.","Put your left hand under your left hipbone to pad your hip and pubic bone.","Bend your right knee so you can hold the foot in your right hand.","Lift the foot in the air and simultaneously lift your shoulders off the floor. This also stretches the right hip flexor and the chest and shoulders. Switch sides. If it doesn't bother your back, you can try it with both arms and legs at the same time."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["ABS_CORE","BICEPS","CHEST"],"equipment":"NONE","tags":["one half locust"],"media":[{"id":"one-half-locust-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Half_Locust/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-half-locust-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Half_Locust/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelvorderseite, unterstützt von Rumpf, Bizeps, Brust.","instructions":null}},{"id":"ex-one-handed-kettlebell-curls","slug":"one-handed-kettlebell-curls","name":"one-handed kettlebell curls","description":"Kettlebell exercise for the biceps.","instructions":["Standing with the kettlebell in one hand and bent at the elbow, start from a fully extended position until your hand reaches shoulder height. To perform the movement correctly, try not to push with your back or body."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"KETTLEBELL","tags":["one-handed kettlebell curls","einarmige kettlebell-curls"],"media":[{"id":"one-handed-kettlebell-curls-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/975/41d9267a-99bc-4e94-b1c4-0e39fe7a968f.png","caption":"one-handed kettlebell curls","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Einarmige Kettlebell-Curls","description":"Übung (Kettlebell) für den Bizeps.","instructions":["Stehe mit der Kettlebell in einer Hand und im Ellbogen angewinkelt. Beginne aus einer vollständig gestreckten Position, bis deine Hand die Schulterhöhe erreicht. Um die Bewegung korrekt auszuführen, versuche nicht, mit dem Rücken oder dem Körper Schwung zu holen."]}},{"id":"ex-one-knee-to-chest","slug":"one-knee-to-chest","name":"One Knee To Chest","description":"Equipment-free exercise for the glutes, with hamstrings, back assisting.","instructions":["Start off by lying on the floor.","Extend one leg straight and pull the other knee to your chest. Hold under the knee joint to protect the kneecap.","Gently tug that knee toward your nose.","Switch sides. This stretches the buttocks and lower back of the bent leg and the hip flexor of the straight leg."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["HAMSTRINGS","BACK"],"equipment":"NONE","tags":["one knee to chest"],"media":[{"id":"one-knee-to-chest-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Knee_To_Chest/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-knee-to-chest-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Knee_To_Chest/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Po, unterstützt von Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-one-leg-barbell-squat","slug":"one-leg-barbell-squat","name":"One Leg Barbell Squat","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Start by standing about 2 to 3 feet in front of a flat bench with your back facing the bench. Have a barbell in front of you on the floor. Tip: Your feet should be shoulder width apart from each other.","Bend the knees and use a pronated grip with your hands being wider than shoulder width apart from each other to lift the barbell up until you can rest it on your chest.","Then lift the barbell over your head and rest it on the base of your neck. Move one foot back so that your toe is resting on the flat bench. Your other foot should be stationary in front of you. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. Tip: Make sure your back is straight and chest is out while performing this exercise.","As you inhale, slowly lower your leg until your thigh is parallel to the floor. At this point, your knee should be over your toes. Your chest should be directly above the middle of your thigh.","Leading with the chest and hips and contracting the quadriceps, elevate your leg back to the starting position as you exhale.","Repeat for the recommended amount of repetitions.","Switch legs and repeat the movement."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"BARBELL","tags":["one leg barbell squat"],"media":[{"id":"one-leg-barbell-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Leg_Barbell_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-leg-barbell-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Leg_Barbell_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-one-legged-cable-kickback","slug":"one-legged-cable-kickback","name":"One-Legged Cable Kickback","description":"Cable exercise for the glutes, with hamstrings assisting.","instructions":["Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle.","Face the weight stack from a distance of about two feet, grasping the steel frame for support.","While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly \"kick\" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out. Tip: At full extension, squeeze your glutes for a second in order to achieve a peak contraction.","Now slowly bring your working leg forward, resisting the pull of the cable until you reach the starting position.","Repeat for the recommended amount of repetitions.","Switch legs and repeat the movement for the other side."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["HAMSTRINGS"],"equipment":"CABLE","tags":["one-legged cable kickback"],"media":[{"id":"one-legged-cable-kickback-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Legged_Cable_Kickback/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"one-legged-cable-kickback-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Legged_Cable_Kickback/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Po, unterstützt von Oberschenkelrückseite.","instructions":null}},{"id":"ex-open-book","slug":"open-book","name":"Open Book","description":"Bodyweight exercise for the back.","instructions":["Basic exercise","Focus: enhances thoracic mobility and","spinal segmentation while opening the shoulders and chest.","**Position:**kneeling on the floor with your right side facing a wall. Hips are square and stable, with the right knee down and the left foot forward. Lengthen your spine and align your head comfortably.","Begin with your arms relaxed and open in front of your chest, palms","facing each other and hands apart.","Inhale","to initiate the movement, allowing your left arm —the one farther from"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["open book","buch aufschlagen (open book)"],"media":[],"source":"wger","de":{"name":"Buch aufschlagen (Open Book)","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Grundübung","Fokus: verbessert die Beweglichkeit der Brustwirbelsäule und","die segmentale Bewegung der Wirbelsäule, während Schultern und Brustkorb geöffnet werden.","Position: Knie auf dem Boden, mit der rechten Seite zu einer Wand gewandt. Das Becken ist gerade und stabil, das rechte Knie unten und der linke Fuß nach vorne. Strecke deine Wirbelsäule und richte deinen Kopf bequem aus.","Beginne mit entspannten, vor der Brust geöffneten Armen, die Handflächen einander zugewandt und die Hände auseinander.","Einatmen,","um die Bewegung einzuleiten, und lasse deinen linken Arm – den weiter","von der Wand entfernten – nach außen und hinten öffnen. Leite die Drehung"]}},{"id":"ex-open-palm-kettlebell-clean","slug":"open-palm-kettlebell-clean","name":"Open Palm Kettlebell Clean","description":"Kettlebell exercise for the hamstrings, with glutes, back, quadriceps, shoulders assisting.","instructions":["Place one kettlebell between your feet. Clean the kettlebell by extending through the legs and hips as you raise the kettlebell towards your shoulders.","Release the kettlebell as it comes up, and let it flip so that the ball of the kettlebell lands in the palms of your hands.","Release the kettlebell out in front of you and catch the handle with both hands. Lower the kettlebell to the starting position and repeat."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","BACK","QUADRICEPS","SHOULDERS"],"equipment":"KETTLEBELL","tags":["open palm kettlebell clean"],"media":[{"id":"open-palm-kettlebell-clean-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Open_Palm_Kettlebell_Clean/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"open-palm-kettlebell-clean-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Open_Palm_Kettlebell_Clean/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Oberschenkelrückseite, unterstützt von Po, Rücken, Oberschenkelvorderseite, Schultern.","instructions":null}},{"id":"ex-otis-up","slug":"otis-up","name":"Otis-Up","description":"Accessory exercise for the core, with chest, shoulders, triceps assisting.","instructions":["Secure your feet and lay back on the floor. Your knees should be bent. Hold a weight with both hands to your chest. This will be your starting position.","Initiate the movement by flexing the hips and spine to raise your torso up from the ground.","As you move up, press the weight up so that it is above your head at the top of the movement.","Return the weight to your chest as you reverse the sit-up motion, ensuring not to go all the way down to the floor."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["CHEST","SHOULDERS","TRICEPS"],"equipment":"OTHER","tags":["otis-up"],"media":[{"id":"otis-up-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Otis-Up/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"otis-up-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Otis-Up/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rumpf, unterstützt von Brust, Schultern, Trizeps.","instructions":null}},{"id":"ex-overhead-lat","slug":"overhead-lat","name":"Overhead Lat","description":"Accessory exercise for the back, with triceps assisting.","instructions":["Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your tricep and wrist. This will be your starting position.","Attempt to pull your upper arm to your side as your partner prevents you from doing actually doing so.","After 10-20 seconds, relax the arm and allow your partner to further stretch the lat by applying gentle pressure to the tricep. Hold for 10-20 seconds, and then switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["TRICEPS"],"equipment":"OTHER","tags":["overhead lat"],"media":[{"id":"overhead-lat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Lat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"overhead-lat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Lat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Trizeps.","instructions":null}},{"id":"ex-overhead-slam","slug":"overhead-slam","name":"Overhead Slam","description":"Accessory exercise for the back.","instructions":["Hold a medine ball with both hands and stand with your feet at shoulder width. This will be your starting position.","Initiate the countermovement by raising the ball above your head and fully extending your body.","Reverse the motion, slamming the ball into the ground directly in front of you as hard as you can.","Receive the ball with both hands on the bounce and repeat the movement."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["overhead slam"],"media":[{"id":"overhead-slam-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Slam/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"overhead-slam-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Slam/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken.","instructions":null}},{"id":"ex-overhead-squat","slug":"overhead-squat","name":"Overhead Squat","description":"Barbell exercise for the quadriceps, with core, calves, glutes, hamstrings, back, shoulders, triceps assisting.","instructions":["Start out by having a barbell in front of you on the floor. Your feet should be wider than shoulder width apart from each other.","Bend the knees and use a pronated grip (palms facing you) to grab the barbell. Your hands should be at a wider than shoulder width apart from each other before lifting. Once you are positioned, lift the barbell up until you can rest it on your chest.","Move the barbell over and slightly behind your head and make sure your arms are fully extended. Keep your head up at all times and also maintain a straight back. Retract your shoulder blades. This is your starting position.","Slowly lower the weight by bending your knees until your thighs are parallel to the ground while inhaling. Tip: Keep your back straight while performing this exercise to avoid any injuries and your arms should remain extended and over your head at all times.","Now use your feet and legs to help bring the weight back up to the starting position while exhaling.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["ABS_CORE","CALVES","GLUTES","HAMSTRINGS","BACK","SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["overhead squat","überkopfkniebeuge"],"media":[{"id":"overhead-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"overhead-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Überkopfkniebeuge","description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Rumpf, Waden, Po, Oberschenkelrückseite, Rücken, Schultern, Trizeps.","instructions":["Die Langhantel wird über dem Kopf im breiten Reißgriff gehalten; es ist jedoch auch möglich, einen engeren Griff zu verwenden, sofern es das Gleichgewicht zulässt."]}},{"id":"ex-overhead-stretch","slug":"overhead-stretch","name":"Overhead Stretch","description":"Equipment-free exercise for the core, with chest, forearms, back, triceps assisting.","instructions":["Standing straight up, lace your fingers together and open your palms to the ceiling. Keep your shoulders down as you extend your arms up.","To create a full torso stretch, pull your tailbone down and stabilize your torso as you do this. Stretch the muscles on both the front and the back of the torso."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["CHEST","FOREARMS","BACK","TRICEPS"],"equipment":"NONE","tags":["overhead stretch"],"media":[{"id":"overhead-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"overhead-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Rumpf, unterstützt von Brust, Unterarme, Rücken, Trizeps.","instructions":null}},{"id":"ex-pallof-press","slug":"pallof-press","name":"Pallof Press","description":"Cable exercise for the core, with chest, shoulders, triceps assisting.","instructions":["Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.","With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable.","With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.","Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.","Hold the repetition for several seconds before returning to the starting position.","At the conclusion of the set, repeat facing the other direction."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["CHEST","SHOULDERS","TRICEPS"],"equipment":"CABLE","tags":["pallof press"],"media":[{"id":"pallof-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pallof_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"pallof-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pallof_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Pallof Press","description":"Übung (Kabelzug) für den Rumpf, unterstützt von Brust, Schultern, Trizeps.","instructions":["Der Pallof Press ist eine Anti-Rotations-Übung, die die größeren und kleineren Muskeln rund um die Wirbelsäule trainiert, der Rotation zu widerstehen.","Stelle dich parallel zum Kabelzug oder zum Befestigungspunkt des","Widerstandsbands und greife mit beiden Händen den Griff oder das Band.","Achte darauf, dass dein Oberkörper nach vorne zeigt, führe die Hände zur Mitte deiner Brust und drücke sie langsam nach vorne aus.","Führe die Hände langsam zur Brust zurück und wiederhole die Bewegung."]}},{"id":"ex-pallof-press-with-rotation","slug":"pallof-press-with-rotation","name":"Pallof Press With Rotation","description":"Cable exercise for the core, with chest, shoulders, triceps assisting.","instructions":["Connect a standard handle to a tower, and position the cable to shoulder height.","With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable. Align outstretched arm with cable.","With your feet positioned hip-width apart, pull the cable into your chest and grab the handle with your other hand. Both hands should be on the handle at this time.","Facing forward, press the cable away from your chest. You core should be tight and engaged.","Keeping your hips straight, twist your torso away from the pulley until you get a full quarter rotation.","Maintain your rigid stance and straight arms. Return to the neutral position in a slow and controlled manner. Your arms should be extended in front of you.","With the side tension still engaging your core, bring your hands to your chest and immediately press outward to a fully extended position. This constitutes one rep.","Repeat to failure.","Then, reposition and repeat the same series of movements on the opposite side."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["CHEST","SHOULDERS","TRICEPS"],"equipment":"CABLE","tags":["pallof press with rotation"],"media":[{"id":"pallof-press-with-rotation-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pallof_Press_With_Rotation/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"pallof-press-with-rotation-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pallof_Press_With_Rotation/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rumpf, unterstützt von Brust, Schultern, Trizeps.","instructions":null}},{"id":"ex-palms-down-dumbbell-wrist-curl-over-a-bench","slug":"palms-down-dumbbell-wrist-curl-over-a-bench","name":"Palms-Down Dumbbell Wrist Curl Over A Bench","description":"Dumbbell exercise for the forearms.","instructions":["Start out by placing two dumbbells on one side of a flat bench.","Kneel down on both of your knees so that your body is facing the flat bench.","Use your arms to grab both of the dumbbells with a pronated grip (palms facing down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["palms-down dumbbell wrist curl over a bench"],"media":[{"id":"palms-down-dumbbell-wrist-curl-over-a-bench-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"palms-down-dumbbell-wrist-curl-over-a-bench-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Unterarme.","instructions":null}},{"id":"ex-palms-down-wrist-curl-over-a-bench","slug":"palms-down-wrist-curl-over-a-bench","name":"Palms-Down Wrist Curl Over A Bench","description":"Barbell exercise for the forearms.","instructions":["Start out by placing a barbell on one side of a flat bench.","Kneel down on both of your knees so that your body is facing the flat bench.","Use your arms to grab the barbell with a pronated grip (palms down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["palms-down wrist curl over a bench"],"media":[{"id":"palms-down-wrist-curl-over-a-bench-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Down_Wrist_Curl_Over_A_Bench/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"palms-down-wrist-curl-over-a-bench-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Down_Wrist_Curl_Over_A_Bench/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Unterarme.","instructions":null}},{"id":"ex-palms-up-dumbbell-wrist-curl-over-a-bench","slug":"palms-up-dumbbell-wrist-curl-over-a-bench","name":"Palms-Up Dumbbell Wrist Curl Over A Bench","description":"Dumbbell exercise for the forearms.","instructions":["Start out by placing two dumbbells on one side of a flat bench.","Kneel down on both of your knees so that your body is facing the flat bench.","Use your arms to grab both of the dumbbells with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["palms-up dumbbell wrist curl over a bench"],"media":[{"id":"palms-up-dumbbell-wrist-curl-over-a-bench-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"palms-up-dumbbell-wrist-curl-over-a-bench-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Unterarme.","instructions":null}},{"id":"ex-parallel-bar-dip","slug":"parallel-bar-dip","name":"Parallel Bar Dip","description":"Accessory exercise for the triceps, with chest, shoulders assisting.","instructions":["Stand between a set of parallel bars. Place a hand on each bar, and then take a small jump to help you get into the starting position with your arms locked out.","Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent.","Reverse the motion by extending the elbow, pushing yourself back up into the starting position.","Repeat for the desired number of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"OTHER","tags":["parallel bar dip"],"media":[{"id":"parallel-bar-dip-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Parallel_Bar_Dip/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"parallel-bar-dip-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Parallel_Bar_Dip/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-parallel-bar-hold","slug":"parallel-bar-hold","name":"Parallel Bar Hold","description":"Bodyweight exercise for the shoulders, with chest, triceps, back, core assisting.","instructions":["Stand between a set of parallel bars.","Place your hands, knuckles outwards, on the bars.","Push down on your hands to lift yourself off the floor.","Hold yourself in this position with your arms straight for the required time."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CHEST","TRICEPS","BACK","ABS_CORE"],"equipment":"BODYWEIGHT","tags":["parallel bar hold","halten am barren"],"media":[],"source":"wger","de":{"name":"Halten am Barren","description":"Übung (Körpergewicht) für die Schultern, unterstützt von Brust, Trizeps, Rücken, Rumpf.","instructions":["Stelle dich zwischen einen Barren.","Lege deine Hände mit den Knöcheln nach außen auf die Holme.","Drücke dich mit den Händen nach unten ab, um dich vom Boden hochzustemmen.","Halte dich mit gestreckten Armen für die vorgegebene Zeit in dieser Position."]}},{"id":"ex-patadas-traseras","slug":"patadas-traseras","name":"Patadas traseras","description":"Dumbbell exercise for the triceps.","instructions":["The dumbbell kickback is a popular strength training exercise that targets the triceps muscles in the back of your upper arms. It helps strengthen and tone the triceps, contributing to overall arm strength and aesthetics.","Among the exercises that work the arm muscles, kickback and its variations are very effective. You can easily apply these exercises with dumbbells, cables or resistance bands."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["patadas traseras","kickbacks (trizepsdrücken nach hinten)"],"media":[],"source":"wger","de":{"name":"Kickbacks (Trizepsdrücken nach hinten)","description":"Übung (Kurzhantel) für den Trizeps.","instructions":["Der Kurzhantel-Kickback ist eine beliebte Krafttrainingsübung, die den Trizeps auf der Rückseite deiner Oberarme anspricht. Sie hilft, den Trizeps zu kräftigen und zu straffen und trägt so zur allgemeinen Armkraft und Ästhetik bei.","Unter den Übungen, die die Armmuskulatur beanspruchen, sind der Kickback und seine Varianten sehr effektiv. Du kannst diese Übungen problemlos mit Kurzhanteln, Kabelzügen oder Widerstandsbändern ausführen."]}},{"id":"ex-pause-hack-squats","slug":"pause-hack-squats","name":"Pause Hack Squats","description":"Bodyweight exercise for the quadriceps, with hamstrings, calves, glutes assisting.","instructions":["Hack Squats but with a 1-2s pause at the bottom of the movement. This makes sure that there is no more elastic energy stored in the muscles."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["HAMSTRINGS","CALVES","GLUTES"],"equipment":"BODYWEIGHT","tags":["pause hack squats","hack squats mit pause"],"media":[],"source":"wger","de":{"name":"Hack Squats mit Pause","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Oberschenkelrückseite, Waden, Po.","instructions":["Hack Squats, aber mit einer Pause von 1-2 Sekunden am unteren Ende der Bewegung. Dadurch wird sichergestellt, dass keine elastische Energie mehr in den Muskeln gespeichert ist."]}},{"id":"ex-paused-squats","slug":"paused-squats","name":"Paused Squats","description":"Barbell exercise for the quadriceps, with hamstrings, glutes assisting.","instructions":["Use the same technic as your normal squat. Except that you make a pause at the bottom of the squat for about 1-2 seconds, in other words a bit longer than your normal squat."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["HAMSTRINGS","GLUTES"],"equipment":"BARBELL","tags":["paused squats","pausiertes kniebeugen"],"media":[],"source":"wger","de":{"name":"Pausiertes Kniebeugen","description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Oberschenkelrückseite, Po.","instructions":["Benutze die selbe technik wie beim normalen Kniebeugen, ausserd am untersten Punkt eine Pause von 1-2 Sekunden einbauen (oder einfach länger wie bei der normalen Kniebeuge)."]}},{"id":"ex-pec-deck-rear-delt-fly","slug":"pec-deck-rear-delt-fly","name":"Pec deck rear delt fly","description":"Bodyweight exercise for the shoulders.","instructions":["Seated rear delt fly on pec deck machine (facing the machine and extending arms backwards, the hands should be at the height of the shoulders)"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["pec deck rear delt fly","reverse butterfly für die hintere schulter"],"media":[],"source":"wger","de":{"name":"Reverse Butterfly für die hintere Schulter","description":"Übung (Körpergewicht) für die Schultern.","instructions":["Sitzendes Reverse Butterfly für die hintere Schulter an der Butterfly-Maschine (zur Maschine gewandt und die Arme nach hinten streckend; die Hände sollten sich auf Schulterhöhe befinden)."]}},{"id":"ex-pelvic-tilt-into-bridge","slug":"pelvic-tilt-into-bridge","name":"Pelvic Tilt Into Bridge","description":"Equipment-free exercise for the back.","instructions":["Lie down with your feet on the floor, heels directly under your knees.","Lift only your tailbone to the ceiling to stretch your lower back. (Don't lift the entire spine yet.) Pull in your stomach.","To go into a bridge, lift the entire spine except the neck."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"NONE","tags":["pelvic tilt into bridge"],"media":[{"id":"pelvic-tilt-into-bridge-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pelvic_Tilt_Into_Bridge/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"pelvic-tilt-into-bridge-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pelvic_Tilt_Into_Bridge/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Rücken.","instructions":null}},{"id":"ex-pendulum-squat","slug":"pendulum-squat","name":"Pendulum Squat","description":"Bodyweight exercise for the quadriceps, with hamstrings, glutes assisting.","instructions":["Place your feet in the middle of the plate at about shoulder width. Tense your torso. Keep your neck relaxed."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["HAMSTRINGS","GLUTES"],"equipment":"BODYWEIGHT","tags":["pendulum squat","pendelkniebeube"],"media":[],"source":"wger","de":{"name":"Pendelkniebeube","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Oberschenkelrückseite, Po.","instructions":["Platziere die Füße in der Mitte der Platte und ca. schulterbreit. Spanne den Bauch an. Entspanne den Nacken während der gesamten Übung."]}},{"id":"ex-peroneals-smr","slug":"peroneals-smr","name":"Peroneals-SMR","description":"Foam roller exercise for the calves.","instructions":["Lay on your side, supporting your weight on your forearm and on a foam roller placed on the outside of your lower leg. Your upper leg can either be on top of your lower leg, or you can cross it in front of you. This will be your starting position.","Raise your hips off of the ground and begin to roll from below the knee to above the ankle on the side of your leg, pausing at points of tension for 10-30 seconds. Repeat on the other leg."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"FOAM_ROLLER","tags":["peroneals-smr"],"media":[{"id":"peroneals-smr-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Peroneals-SMR/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"peroneals-smr-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Peroneals-SMR/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Faszienrolle) für die Waden.","instructions":null}},{"id":"ex-peroneals-stretch","slug":"peroneals-stretch","name":"Peroneals Stretch","description":"Accessory exercise for the calves.","instructions":["In a seated position, loop a belt, rope, or band around one foot. This will be your starting position.","With the leg extended and the heel off of the ground, pull on the belt so that the foot is inverted, with the inside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["peroneals stretch"],"media":[{"id":"peroneals-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Peroneals_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"peroneals-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Peroneals_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Waden.","instructions":null}},{"id":"ex-perpendicular-unilateral-landmine-row","slug":"perpendicular-unilateral-landmine-row","name":"Perpendicular Unilateral Landmine Row","description":"Barbell exercise for the shoulders, with back assisting.","instructions":["Using a landmine attachment with the barbell running at 90 degrees to either side, hinge slightly at the hips and grip the barbell by the plate sleeve. Raise the barbell to chest height, with your upper arm parallel to the floor at the top of the movement."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"BARBELL","tags":["perpendicular unilateral landmine row","einarmiges landmine-rudern (senkrecht)"],"media":[],"source":"wger","de":{"name":"Einarmiges Landmine-Rudern (senkrecht)","description":"Übung (Langhantel) für die Schultern, unterstützt von Rücken.","instructions":["Verwende einen Landmine-Aufsatz, wobei die Langhantel in einem Winkel von 90 Grad zur Seite zeigt. Beuge dich leicht in den Hüften und greife die Langhantel an der Hülse der Gewichtsscheibe. Hebe die Langhantel auf Brusthöhe an, sodass dein Oberarm am höchsten Punkt der Bewegung parallel zum Boden ist."]}},{"id":"ex-physioball-hip-bridge","slug":"physioball-hip-bridge","name":"Physioball Hip Bridge","description":"Accessory exercise for the glutes, with hamstrings assisting.","instructions":["Lay on a ball so that your upper back is on the ball with your hips unsupported. Both feet should be flat on the floor, hip width apart or wider. This will be your starting position.","Begin by extending the hips using your glutes and hamstrings, raising your hips upward as you bridge.","Pause at the top of the motion and return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["HAMSTRINGS"],"equipment":"OTHER","tags":["physioball hip bridge"],"media":[{"id":"physioball-hip-bridge-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Physioball_Hip_Bridge/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"physioball-hip-bridge-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Physioball_Hip_Bridge/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Po, unterstützt von Oberschenkelrückseite.","instructions":null}},{"id":"ex-pike-push-ups","slug":"pike-push-ups","name":"Pike Push Ups","description":"Bodyweight exercise for the chest, with triceps assisting.","instructions":["Push Up performed from a pike position (optional to have feet elevated)."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["TRICEPS"],"equipment":"BODYWEIGHT","tags":["pike push ups","hecht-liegestütze"],"media":[{"id":"pike-push-ups-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/454/447f3c17-405f-46e0-b138-65c2a8caaab0.png","caption":"Pike Push Ups","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Hecht-Liegestütze","description":"Übung (Körpergewicht) für die Brust, unterstützt von Trizeps.","instructions":["Starre Position:","Der nach unten gerichtete Hund:Ihr Körper sollte eine V-Form bilden, mit geradem Rücken, Armen und Beinen. Ihre Hüften sollten in der Luft sein.Sie können diese Position erreichen, indem Sie die Hände aus einem hohen Plankenstand nach hinten führen.","Die Schritte:","Beugen Sie die Ellbogen zur Seite, halten Sie Rücken und Beine gerade und bringen Sie den Kopf näher zum Boden.","Strecken Sie die Arme aus, drücken Sie die Hüfte wieder nach oben und halten Sie Rücken und Beine gerade.","Wiederholen Sie den Vorgang."]}},{"id":"ex-pin-bench-press-bb","slug":"pin-bench-press-bb","name":"Pin Bench Press BB","description":"Barbell exercise for the chest, with triceps assisting.","instructions":["Set security pins to about the height of your sticking point","Lower the bar, rest on the pins for 1s while holding tension","Move bar up with maximum force"],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["TRICEPS"],"equipment":"BARBELL","tags":["pin bench press bb","pin bench press"],"media":[],"source":"wger","de":{"name":"Pin Bench Press","description":"Übung (Langhantel) für die Brust, unterstützt von Trizeps.","instructions":["Stelle die Sicherheitsablagen ungefähr auf die Höhe deines Sticking Points ein","Senke die Stange ab, lasse sie 1 s auf den Ablagen ruhen und halte dabei die Spannung","Bewege die Stange mit maximaler Kraft nach oben"]}},{"id":"ex-pin-presses","slug":"pin-presses","name":"Pin Presses","description":"Barbell exercise for the triceps, with chest, forearms, back, shoulders assisting.","instructions":["Pin presses remove the eccentric phase of the bench press, developing starting strength. They also allow you to train a desired range of motion.","The bench should be set up in a power rack. Set the pins to the desired point in your range of motion, whether it just be lockout or an inch off of your chest. The bar should be moved to the pins and prepared for lifting.","Begin by lying on the bench, with the bar directly above the contact point during your regular bench. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.","You can take a standard bench grip, or shoulder width to focus on the triceps. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.","Drive the bar up with as much force as possible. The elbows should be tucked in until lockout.","Return the bar to the pins, pausing before beginning the next repetition."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","FOREARMS","BACK","SHOULDERS"],"equipment":"BARBELL","tags":["pin presses"],"media":[{"id":"pin-presses-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pin_Presses/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"pin-presses-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pin_Presses/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Trizeps, unterstützt von Brust, Unterarme, Rücken, Schultern.","instructions":null}},{"id":"ex-piriformis-smr","slug":"piriformis-smr","name":"Piriformis-SMR","description":"Foam roller exercise for the glutes.","instructions":["Sit with your buttocks on top of a foam roll. Bend your knees, and then cross one leg so that the ankle is over the knee. This will be your starting position.","Shift your weight to the side of the crossed leg, rolling over the buttocks until you feel tension in your upper glute. You may assist the stretch by using one hand to pull the bent knee towards your chest. Hold this position for 10-30 seconds, and then switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":[],"equipment":"FOAM_ROLLER","tags":["piriformis-smr"],"media":[{"id":"piriformis-smr-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Piriformis-SMR/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"piriformis-smr-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Piriformis-SMR/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Faszienrolle) für den Po.","instructions":null}},{"id":"ex-pistol-squat","slug":"pistol-squat","name":"Pistol Squat","description":"Bodyweight exercise for the hamstrings, with glutes, shoulders, biceps assisting.","instructions":["Stand with feet hip-width apart, toes pointed forward, and chest tall.","Extend your leg straight out; extend both arms in front of you, at shoulder level. Brace your core and look straight ahead.","Slowly squat down.","(optional) pause at the bottom.","Keep your (free) leg and arms extended for the whole duration."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","SHOULDERS","BICEPS"],"equipment":"BODYWEIGHT","tags":["pistol squat","einbeinige kniebeuge"],"media":[{"id":"pistol-squat-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/456/3b681e59-377b-40db-9113-ca5873ce084b.jpg","caption":"Pistol Squat","attribution":"wger.de · wakanda90","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Einbeinige Kniebeuge","description":"Übung (Körpergewicht) für die Oberschenkelrückseite, unterstützt von Po, Schultern, Bizeps.","instructions":["Ein Bein nach hinten auf einem Stuhl oder Bank ablegen, mit dem anderen Bein eine Kniebeuge machen. Gewicht optional mit Langhantel auf Rücken, Kurzhantel in den Armen oder Kugelhantel in Brusthöhe."]}},{"id":"ex-plank","slug":"plank","name":"Plank","description":"Bodyweight exercise for the core.","instructions":["Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.","Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["plank"],"media":[{"id":"plank-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plank/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"plank-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plank/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Plank","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Mit dem Bauch auf den Boden legen und den Körper mit Unterarmen und Zehen abstützen. Beine, Rücken und Kopf sollten eine gerade Linie bilden."]}},{"id":"ex-plank-reach","slug":"plank-reach","name":"Plank Reach","description":"Bodyweight exercise for the core, with shoulders assisting.","instructions":["Position your body in plank position, keeping your eyes on the ground. Raise one arm in front of you and return it. Repeat with the other arm. Raise and return slowly while keeping your body as still as possible."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["SHOULDERS"],"equipment":"BODYWEIGHT","tags":["plank reach","unterarmstütz mit armheben"],"media":[],"source":"wger","de":{"name":"Unterarmstütz mit Armheben","description":"Übung (Körpergewicht) für den Rumpf, unterstützt von Schultern.","instructions":["Bringe deinen Körper in die Planken-Position. Halte den Blick auf den Boden gerichtet und hebe abwechselnd deine Arme langsam nach vorne und zurück. Versuche dabei deinen Körper so ruhig wie möglich zu halten."]}},{"id":"ex-plate-pinch","slug":"plate-pinch","name":"Plate Pinch","description":"Accessory exercise for the forearms.","instructions":["Grab two wide-rimmed plates and put them together with the smooth sides facing outward","Use your fingers to grip the outside part of the plate and your thumb for the other side thus holding both plates together. This is the starting position.","Squeeze the plate with your fingers and thumb. Hold this position for as long as you can.","Repeat for the recommended amount of sets prescribed in your program.","Switch arms and repeat the movements."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["plate pinch"],"media":[{"id":"plate-pinch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plate_Pinch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"plate-pinch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plate_Pinch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Unterarme.","instructions":null}},{"id":"ex-plate-twist","slug":"plate-twist","name":"Plate Twist","description":"Accessory exercise for the core.","instructions":["Lie down on the floor or an exercise mat with your legs fully extended and your upper body upright. Grab the plate by its sides with both hands out in front of your abdominals with your arms slightly bent.","Slowly cross your legs near your ankles and lift them up off the ground. Your knees should also be bent slightly. Note: Move your upper body back slightly to help keep you balanced turning this exercise. This is the starting position.","Move the plate to the left side and touch the floor with it. Breathe out as you perform that movement.","Come back to the starting position as you breathe in and then repeat the movement but this time to the right side of the body. Tip: Use a slow controlled movement at all times. Jerking motions can injure the back.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["plate twist"],"media":[{"id":"plate-twist-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plate_Twist/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"plate-twist-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plate_Twist/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rumpf.","instructions":null}},{"id":"ex-platform-hamstring-slides","slug":"platform-hamstring-slides","name":"Platform Hamstring Slides","description":"Accessory exercise for the hamstrings, with glutes assisting.","instructions":["For this movement a wooden floor or similar is needed. Lay on your back with your legs extended. Place a gym towel or a light weight underneath your heel. This will be your starting position.","Begin the movement by flexing the knee, keeping your other leg straight.","Continue bringing the heel closer to you, sliding it on the floor.","At full knee flexion, reverse the movement to return to the starting position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES"],"equipment":"OTHER","tags":["platform hamstring slides"],"media":[{"id":"platform-hamstring-slides-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Platform_Hamstring_Slides/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"platform-hamstring-slides-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Platform_Hamstring_Slides/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelrückseite, unterstützt von Po.","instructions":null}},{"id":"ex-plie-dumbbell-squat","slug":"plie-dumbbell-squat","name":"Plie Dumbbell Squat","description":"Dumbbell exercise for the quadriceps, with core, calves, glutes, hamstrings assisting.","instructions":["Hold a dumbbell at the base with both hands and stand straight up. Move your legs so that they are wider than shoulder width apart from each other with your knees slightly bent.","Your toes should be facing out. Note: Your arms should be stationary while performing the exercise. This is the starting position.","Slowly bend the knees and lower your legs until your thighs are parallel to the floor. Make sure to inhale as this is the eccentric part of the exercise.","Press mainly with the heel of the foot to bring the body back to the starting position while exhaling.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["ABS_CORE","CALVES","GLUTES","HAMSTRINGS"],"equipment":"DUMBBELL","tags":["plie dumbbell squat"],"media":[{"id":"plie-dumbbell-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plie_Dumbbell_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"plie-dumbbell-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plie_Dumbbell_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Oberschenkelvorderseite, unterstützt von Rumpf, Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-plyo-kettlebell-pushups","slug":"plyo-kettlebell-pushups","name":"Plyo Kettlebell Pushups","description":"Kettlebell exercise for the chest, with shoulders, triceps assisting.","instructions":["Place a kettlebell on the floor. Place yourself in a pushup position, on your toes with one hand on the ground and one hand holding the kettlebell, with your elbows extended. This will be your starting position.","Begin by lowering yourself as low as you can, keeping your back straight.","Quickly and forcefully reverse direction, pushing yourself up to the other side of the kettlebell, switching hands as you do so. Continue the movement by descending and repeating the movement back and forth."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"KETTLEBELL","tags":["plyo kettlebell pushups"],"media":[{"id":"plyo-kettlebell-pushups-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plyo_Kettlebell_Pushups/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"plyo-kettlebell-pushups-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plyo_Kettlebell_Pushups/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-plyo-push-up","slug":"plyo-push-up","name":"Plyo Push-up","description":"Bodyweight exercise for the chest, with shoulders, triceps assisting.","instructions":["Move into a prone position on the floor, supporting your weight on your hands and toes.","Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.","Descend by flexing at the elbow, lowering your chest towards the ground.","At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible. Attempt to push your upper body up until your hands leave the ground.","Return to the starting position and repeat the exercise.","For added difficulty, add claps into the movement while you are air borne."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BODYWEIGHT","tags":["plyo push-up"],"media":[{"id":"plyo-push-up-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plyo_Push-up/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"plyo-push-up-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plyo_Push-up/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-posterior-tibialis-stretch","slug":"posterior-tibialis-stretch","name":"Posterior Tibialis Stretch","description":"Accessory exercise for the calves.","instructions":["In a seated position, loop a belt, rope, or band around one foot. This will be your starting position.","With the leg extended and the heel off of the ground, pull on the belt so that the foot is everted, with the outside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["posterior tibialis stretch"],"media":[{"id":"posterior-tibialis-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Posterior_Tibialis_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"posterior-tibialis-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Posterior_Tibialis_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Waden.","instructions":null}},{"id":"ex-power-clean","slug":"power-clean","name":"Power Clean","description":"Barbell exercise for the hamstrings, with calves, forearms, glutes, back, quadriceps, shoulders, triceps assisting.","instructions":["Stand with your feet slightly wider than shoulder width apart and toes pointing out slightly.","Squat down and grasp bar with a closed, pronated grip. Your hands should be slightly wider than shoulder width apart outside knees with elbows fully extended.","Place the bar about 1 inch in front of your shins and over the balls of your feet.","Your back should be flat or slightly arched, your chest held up and out and your shoulder blades should be retracted.","Keep your head in a neutral position (in line with vertebral column and not tilted or rotated) with your eyes focused straight ahead. Inhale during this phase.","Lift the bar from the floor by forcefully extending the hips and the knees as you exhale. Tip: The upper torso should maintain the same angle. Do not bend at the waist yet and do not let the hips rise before the shoulders (this would have the effect of pushing the glutes in the air and stretching the hamstrings.","Keep elbows fully extended with the head in a neutral position and the shoulders over the bar.","As the bar raises keep it as close to the shins as possible.","As the bar passes the knees, thrust your hips forward and slightly bend the knees to avoid locking them. Tip: At this point your thighs should be against the bar.","Keep the back flat or slightly arched, elbows fully extended and your head neutral. Tip: You will hold your breath until the next phase.","Inhale and then forcefully and quickly extend your hips and knees and stand on your toes.","Keep the bar as close to your body as possible. Tip: Your back should be flat with the elbows pointed out to the sides and your head in a neutral position. Also, keep your shoulders over the bar and arms straight as long as possible.","When your lower body joints are fully extended, shrug the shoulders upward rapidly without letting the elbows flex yet. Exhale during this portion of the movement.","As the shoulders reach their highest elevation flex your elbows to begin pulling your body under the bar.","Continue to pull the arms as high and as long as possible. Tip: Due to the explosive nature of this phase, your torso will be erect or with an arched back, your head will be tilted back slightly and your feet may lose contact with the floor.","After the lower body has fully extended and the bar reaches near maximal height, pull your body under the bar and rotate the arms around and under the bar.","Simultaneously, flex the hips and knees into a quarter squat position.","Once the arms are under the bar, inhale and then lift your elbows to position the upper arms parallel to the floor. Rack the bar across the front of your collar bones and front shoulder muscles.","Catch the bar with an erect and tight torso, a neutral head position and flat feet. Exhale during this movement.","Stand up by extending the hips and knees to a fully erect position.","Lower the bar by gradually reducing the muscular tension of the arms to allow a controlled descent of the bar to the thighs. Inhale during this movement.","Simultaneously flex the hips and knees to cushion the impact of the bar on the thighs.","Squat down with the elbows fully extended until the bar touches the floor.","Start over at Phase 1 and repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","FOREARMS","GLUTES","BACK","QUADRICEPS","SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["power clean","umsetzen"],"media":[{"id":"power-clean-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Clean/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"power-clean-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Clean/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Umsetzen","description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Waden, Unterarme, Po, Rücken, Oberschenkelvorderseite, Schultern, Trizeps.","instructions":null}},{"id":"ex-power-clean-from-blocks","slug":"power-clean-from-blocks","name":"Power Clean from Blocks","description":"Barbell exercise for the hamstrings, with quadriceps assisting.","instructions":["With a barbell on boxes of the desired height, take a grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. As the bar approaches the mid-thigh position, begin extending through the hips.","In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight. At the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.","As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, pull yourself under the bar far enough that it can be racked onto the shoulders, rotating your elbows under the bar as you do so. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position, and complete the repetition by returning the weight to the boxes."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["QUADRICEPS"],"equipment":"BARBELL","tags":["power clean from blocks"],"media":[{"id":"power-clean-from-blocks-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Clean_from_Blocks/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"power-clean-from-blocks-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Clean_from_Blocks/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Oberschenkelvorderseite.","instructions":null}},{"id":"ex-power-jerk","slug":"power-jerk","name":"Power Jerk","description":"Barbell exercise for the quadriceps, with core, calves, glutes, hamstrings, shoulders, triceps assisting.","instructions":["Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.","Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.","At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be moved to a slightly wider stance, with the knees partially bent.","Receive the bar with the arms locked out overhead.","Return to a standing position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["ABS_CORE","CALVES","GLUTES","HAMSTRINGS","SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["power jerk"],"media":[{"id":"power-jerk-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Jerk/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"power-jerk-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Jerk/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Rumpf, Waden, Po, Oberschenkelrückseite, Schultern, Trizeps.","instructions":null}},{"id":"ex-power-partials","slug":"power-partials","name":"Power Partials","description":"Dumbbell exercise for the shoulders.","instructions":["Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.","The palms of the hands should be facing your torso. Your feet should be about shoulder width apart. This will be your starting position.","Keeping your arms straight and the torso stationary, lift the weights out to your sides until they are about shoulder level height while exhaling.","Feel the contraction for a second and begin to lower the weights back down to the starting position while inhaling. Tip: Keep the palms facing down with the little finger slightly higher while lifting and lowering the weights as it will concentrate the stress on your shoulders mainly.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["power partials"],"media":[{"id":"power-partials-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Partials/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"power-partials-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Partials/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern.","instructions":null}},{"id":"ex-power-snatch","slug":"power-snatch","name":"Power Snatch","description":"Barbell exercise for the hamstrings, with calves, glutes, back, quadriceps, shoulders, triceps assisting.","instructions":["Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.","Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.","Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, a slightly wider position, pull yourself below the bar as you elevate the bar overhead. The bar should be received in a partial squat. Continue raising the bar to the overhead position, receiving the bar locked out overhead.","Return to a standing position with the weight over head."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","GLUTES","BACK","QUADRICEPS","SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["power snatch"],"media":[{"id":"power-snatch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Snatch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"power-snatch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Snatch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Waden, Po, Rücken, Oberschenkelvorderseite, Schultern, Trizeps.","instructions":null}},{"id":"ex-power-snatch-from-blocks","slug":"power-snatch-from-blocks","name":"Power Snatch from Blocks","description":"Barbell exercise for the quadriceps, with calves, forearms, glutes, hamstrings, back, shoulders, triceps assisting.","instructions":["Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position.","Begin the first pull by driving through the front of the heels, raising the bar from the boxes.","Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar above a full squat and with the arms fully extended overhead.","Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position. Carefully return the weight to the boxes."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","FOREARMS","GLUTES","HAMSTRINGS","BACK","SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["power snatch from blocks"],"media":[{"id":"power-snatch-from-blocks-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Snatch_from_Blocks/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"power-snatch-from-blocks-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Snatch_from_Blocks/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Unterarme, Po, Oberschenkelrückseite, Rücken, Schultern, Trizeps.","instructions":null}},{"id":"ex-preacher-curl-internally-rotated","slug":"preacher-curl-internally-rotated","name":"Preacher Curl - Internally Rotated","description":"Dumbbell exercise for the biceps.","instructions":["Single arm curl that can be done using a dumbbell and a preacher bench, or a preacher curl machine. Turn body towards the weight"],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["preacher curl - internally rotated","scott-curl mit innenrotation"],"media":[],"source":"wger","de":{"name":"Scott-Curl mit Innenrotation","description":"Übung (Kurzhantel) für den Bizeps.","instructions":["Einarmiger Curl, der mit einer Kurzhantel und einer Scott-Bank oder an einer Scott-Curl-Maschine ausgeführt werden kann. Drehe den Körper zum Gewicht hin."]}},{"id":"ex-preacher-curls","slug":"preacher-curls","name":"Preacher Curls","description":"EZ-bar exercise for the biceps.","instructions":["Place the EZ curl bar on the rest handles in front of the preacher bench. Lean over the bench and grab the EZ curl bar with palms up. Sit down on the preacher bench seat so your upper arms rest on top of the pad and your chest is pressed against the pad. Lower the weight until your elbows are extended and arms are straight. Bring the weights back up to the starting point by contracting biceps. Repeat"],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"EZ_BAR","tags":["preacher curls","kh an scottmaschine"],"media":[{"id":"preacher-curls-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/193/Preacher-curl-3-1.png","caption":"Preacher Curls","attribution":"wger.de · Everkinetic","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"KH an Scottmaschine","description":"Übung (SZ-Stange) für den Bizeps.","instructions":["Setze dich vor der Scottmaschine, stelle die Höhe so ein, dass die Achselhöhlen auf die Oberkante liegen. Die Oberarme liegen parallel auf der Fläche und bleiben während der Übung auch so. Ziehe die Hanteln so weit wie möglich hoch und bringe sie ohne Pause wieder runter. Strecke dabei die Arme ganz aus."]}},{"id":"ex-preacher-hammer-dumbbell-curl","slug":"preacher-hammer-dumbbell-curl","name":"Preacher Hammer Dumbbell Curl","description":"Dumbbell exercise for the biceps, with forearms assisting.","instructions":["Place the upper part of both arms on top of the preacher bench as you hold a dumbbell in each hand with the palms facing each other (neutral grip).","As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched.","As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbells are at shoulder height.","Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"DUMBBELL","tags":["preacher hammer dumbbell curl"],"media":[{"id":"preacher-hammer-dumbbell-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Hammer_Dumbbell_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"preacher-hammer-dumbbell-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Hammer_Dumbbell_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps, unterstützt von Unterarme.","instructions":null}},{"id":"ex-press-sit-up","slug":"press-sit-up","name":"Press Sit-Up","description":"Barbell exercise for the core, with chest, shoulders, triceps assisting.","instructions":["To begin, lie down on a bench with a barbell resting on your chest. Position your legs so they are secure on the extension of the abdominal bench. This is the starting position.","While inhaling, tighten your abdominals and glutes. Simultaneously curl your torso as you do when performing a sit-up and press the barbell to an overhead position while exhaling. Tip: Use your arms to push the barbell out as you perform this exercise while still focusing on the abdominal muscles.","Lower your upper body back down to the starting position while bringing the barbell back down to your torso. Remember to breathe in while lowering the body.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["CHEST","SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["press sit-up"],"media":[{"id":"press-sit-up-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Press_Sit-Up/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"press-sit-up-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Press_Sit-Up/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rumpf, unterstützt von Brust, Schultern, Trizeps.","instructions":null}},{"id":"ex-prone-manual-hamstring","slug":"prone-manual-hamstring","name":"Prone Manual Hamstring","description":"Equipment-free exercise for the hamstrings.","instructions":["You will need a partner for this exercise. Lay face down with your legs straight. Your assistant will place their hand on your heel.","To begin, flex the knee to curl your leg up. Your partner should provide resistance, starting light and increasing the pressure as the movement is completed. Communicate with your partner to monitor appropriate resistance levels.","Pause at the top, returning the leg to the starting position as your partner provides resistance going the other direction."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":[],"equipment":"NONE","tags":["prone manual hamstring"],"media":[{"id":"prone-manual-hamstring-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Prone_Manual_Hamstring/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"prone-manual-hamstring-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Prone_Manual_Hamstring/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelrückseite.","instructions":null}},{"id":"ex-prone-scapular-retraction-arms-at-side","slug":"prone-scapular-retraction-arms-at-side","name":"Prone Scapular Retraction - Arms at Side","description":"Bodyweight exercise for the back.","instructions":["Lying on stomach with head on towel.","Stretch arms straight out to your sides.","Slowly lift your arms, pulling your shoulderblades together, hold for 3 seconds."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["prone scapular retraction - arms at side","schulterblatt-retraktion in bauchlage – arme seitlich"],"media":[],"source":"wger","de":{"name":"Schulterblatt-Retraktion in Bauchlage – Arme seitlich","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Lege dich auf den Bauch mit dem Kopf auf einem Handtuch.","Strecke die Arme gerade zur Seite aus.","Hebe langsam deine Arme an, ziehe dabei die Schulterblätter zusammen und halte 3 Sekunden lang."]}},{"id":"ex-pseudo-planche-push-up","slug":"pseudo-planche-push-up","name":"Pseudo Planche Push-up","description":"Bodyweight exercise for the shoulders, with chest assisting.","instructions":["You should have the shoulder line in front of your wrists an perform a push-up, maintaining the shoulder in the same position"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CHEST"],"equipment":"BODYWEIGHT","tags":["pseudo planche push-up","pseudo-planche-liegestütz"],"media":[],"source":"wger","de":{"name":"Pseudo-Planche-Liegestütz","description":"Übung (Körpergewicht) für die Schultern, unterstützt von Brust.","instructions":["Du solltest die Schulterlinie vor deinen Handgelenken haben und einen Liegestütz ausführen, während du die Schulter in derselben Position hältst."]}},{"id":"ex-pull-through","slug":"pull-through","name":"Pull Through","description":"Cable exercise for the glutes, with hamstrings, back assisting.","instructions":["Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart.","Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders; all of the motion should originate through the hips."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["HAMSTRINGS","BACK"],"equipment":"CABLE","tags":["pull through"],"media":[{"id":"pull-through-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pull_Through/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"pull-through-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pull_Through/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Po, unterstützt von Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-pull-ups","slug":"pull-ups","name":"Pull-ups","description":"Bodyweight exercise for the back, with shoulders, biceps assisting.","instructions":["Grab the pull up bar with a wide grip, the body is hanging freely. Keep your chest out and pull yourself up till your chin reaches the bar or it touches your neck, if you want to pull behind you. Go with a slow and controlled movement down, always keeping the chest out."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["SHOULDERS","BICEPS"],"equipment":"BODYWEIGHT","tags":["pull-ups","klimmzüge"],"media":[{"id":"pull-ups-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/475/b0554016-16fd-4dbe-be47-a2a17d16ae0e.jpg","caption":"Pull-ups","attribution":"wger.de · Imobard","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Klimmzüge","description":"Übung (Körpergewicht) für den Rücken, unterstützt von Schultern, Bizeps.","instructions":["Greife die Klimmzugstange mit breitem Griff, der Körper hängt zunächst frei nach unten. Ziehe nun die Brust raus und bringe den Körper nach oben, bis dein Kinn über der Stange liegt (oder der Nacken sie berührt, wenn du nach hinten gezogen hast), gehe nun langsam nach unten und wiederhole."]}},{"id":"ex-pull-ups-wide-grip","slug":"pull-ups-wide-grip","name":"Pull-Ups (Wide Grip)","description":"Bodyweight exercise for the back.","instructions":["Execution","Pulling phase (concentric):","Drive your elbows down and slightly back, pulling your chest toward the bar.","Focus on leading with your chest, not your chin.","Keep your shoulders depressed (avoid shrugging).","Top position:","Chin should clear the bar (or at least reach bar level).","Pause for a brief squeeze in your lats."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["pull-ups (wide grip)","klimmzüge (weiter griff)"],"media":[],"source":"wger","de":{"name":"Klimmzüge (weiter Griff)","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Ausführung","Zugphase (konzentrisch):","Ziehe deine Ellenbogen nach unten und leicht nach hinten und ziehe deine Brust zur Stange.","Konzentriere dich darauf, mit der Brust zu führen, nicht mit dem Kinn.","Halte deine Schultern nach unten gedrückt (vermeide ein Hochziehen).","Obere Position:","Das Kinn sollte über die Stange kommen (oder zumindest Stangenhöhe erreichen).","Halte kurz inne für ein Zusammendrücken des Latissimus."]}},{"id":"ex-pullup-on-fingerboard","slug":"pullup-on-fingerboard","name":"Pullup on fingerboard","description":"Bodyweight exercise for the biceps, with back assisting.","instructions":["Pullup on a choosen edge of a fingerboard / hangboard"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["BACK"],"equipment":"BODYWEIGHT","tags":["pullup on fingerboard","klimmzug an leiste"],"media":[],"source":"wger","de":{"name":"Klimmzug an Leiste","description":"Übung (Körpergewicht) für den Bizeps, unterstützt von Rücken.","instructions":["Klimmzüge an einer gewählten Leiste eines Fingerboards / Hangboards"]}},{"id":"ex-push-ohp","slug":"push-ohp","name":"Push OHP","description":"Barbell exercise for the shoulders, with glutes, quadriceps, triceps assisting.","instructions":["Rest bar in front on your shoulders","Bend knees while keeping upper body straight","Extend legs pushing the bar overhead with force"],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["GLUTES","QUADRICEPS","TRICEPS"],"equipment":"BARBELL","tags":["push ohp","push press"],"media":[],"source":"wger","de":{"name":"Push Press","description":"Übung (Langhantel) für die Schultern, unterstützt von Po, Oberschenkelvorderseite, Trizeps.","instructions":["Lege die Stange vorne auf deinen Schultern ab","Beuge die Knie, während du den Oberkörper aufrecht hältst","Strecke die Beine und drücke die Stange mit Schwung über deinen Kopf"]}},{"id":"ex-push-press","slug":"push-press","name":"Push Press","description":"Barbell exercise for the shoulders, with quadriceps, triceps assisting.","instructions":[],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["QUADRICEPS","TRICEPS"],"equipment":"BARBELL","tags":["push press"],"media":[{"id":"push-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"push-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Push Press","description":"Übung (Langhantel) für die Schultern, unterstützt von Oberschenkelvorderseite, Trizeps.","instructions":["Bringe deine Kurzhanteln im Cleanen auf deine Schultern, die Handflächen zeigen nach innen. Atme ein und spanne deinen Rumpf an. (Bild 1) Gehe in die Knie und nutze deine Beine, um die Kurzhanteln (Bild 2) über den Kopf zu drücken. Senke sie kontrolliert und in langsamem Tempo wieder zu deinen Schultern ab und wiederhole."]}},{"id":"ex-push-press-behind-the-neck","slug":"push-press-behind-the-neck","name":"Push Press - Behind the Neck","description":"Barbell exercise for the shoulders, with calves, quadriceps, triceps assisting.","instructions":["Standing with the weight racked on the back of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, moving the bar in a vertical path.","Using the momentum generated, finish pressing the weight overhead be extending through the arms.","Return to the starting position, using your legs to absorb the impact."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CALVES","QUADRICEPS","TRICEPS"],"equipment":"BARBELL","tags":["push press - behind the neck"],"media":[{"id":"push-press-behind-the-neck-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push_Press_-_Behind_the_Neck/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"push-press-behind-the-neck-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push_Press_-_Behind_the_Neck/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Schultern, unterstützt von Waden, Oberschenkelvorderseite, Trizeps.","instructions":null}},{"id":"ex-push-up-rotations","slug":"push-up-rotations","name":"Push-up rotations","description":"Bodyweight exercise for the chest, with triceps, shoulders, core assisting.","instructions":["Starting position:","Get into the starting push-up position, with your hands and toes touching the ground and back, arms and legs straight. To get to this position, you can lie down on your stomach, place your hands facing down next to your head, and lifting your arms up until they are straight.","Steps:","Perform a standard push-up:","1.a Bend arms until chest almost touches the ground, making sure the back is straight.1.b Use your arms to lift yourself back up to starting position.","Rotate your body to the side so that the back is straight, the bottom hand supporting the body is fully extended, and only the bottom hand and foot touch the floor.","Repeat, changing sides at step 2 each time."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["TRICEPS","SHOULDERS","ABS_CORE"],"equipment":"BODYWEIGHT","tags":["push-up rotations","liegestütz-drehungen"],"media":[],"source":"wger","de":{"name":"Liegestütz-Drehungen","description":"Übung (Körpergewicht) für die Brust, unterstützt von Trizeps, Schultern, Rumpf.","instructions":["Ausgangsposition:","Begeben Sie sich in die Ausgangsposition für Liegestütze, wobei Hände und Zehen den Boden berühren und Arme und Beine gerade sind. Um diese Position zu erreichen, können Sie sich auf den Bauch legen, die Hände nach unten neben den Kopf legen und die Arme nach oben heben, bis sie gerade sind.","Die Schritte:","Führen Sie einen normalen Liegestütz durch:","1.a Beugen Sie die Arme, bis die Brust fast den Boden berührt, und achten Sie darauf, dass der Rücken gerade ist.1.b Heben Sie sich mit den Armen wieder in die Ausgangsposition.","Drehen Sie Ihren Körper zur Seite, so dass der Rücken gerade ist, die untere Hand, die den Körper stützt, vollständig gestreckt ist und nur die untere Hand und der Fuß den Boden berühren.","Wiederholen Sie den Vorgang, wobei Sie bei Schritt 2 jedes Mal die Seite wechseln."]}},{"id":"ex-push-up-to-side-plank","slug":"push-up-to-side-plank","name":"Push Up to Side Plank","description":"Bodyweight exercise for the chest, with core, shoulders, triceps assisting.","instructions":["Get into pushup position on the toes with your hands just outside of shoulder width.","Perform a pushup by allowing the elbows to flex. As you descend, keep your body straight.","Do one pushup and as you come up, shift your weight on the left side of the body, twist to the side while bringing the right arm up towards the ceiling in a side plank.","Lower the arm back to the floor for another pushup and then twist to the other side.","Repeat the series, alternating each side, for 10 or more reps."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["ABS_CORE","SHOULDERS","TRICEPS"],"equipment":"BODYWEIGHT","tags":["push up to side plank"],"media":[{"id":"push-up-to-side-plank-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push_Up_to_Side_Plank/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"push-up-to-side-plank-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push_Up_to_Side_Plank/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Brust, unterstützt von Rumpf, Schultern, Trizeps.","instructions":null}},{"id":"ex-push-up-wide","slug":"push-up-wide","name":"Push-Up Wide","description":"Bodyweight exercise for the chest, with core, shoulders, triceps assisting.","instructions":["With your hands wide apart, support your body on your toes and hands in a plank position. Your elbows should be extended and your body straight. Do not allow your hips to sag. This will be your starting position.","To begin, allow the elbows to flex, lowering your chest to the floor as you inhale.","Using your pectoral muscles, press your upper body back up to the starting position by extending the elbows. Exhale as you perform this step.","After pausing at the contracted position, repeat the movement for the prescribed amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["ABS_CORE","SHOULDERS","TRICEPS"],"equipment":"BODYWEIGHT","tags":["push-up wide","breiter liegestütz"],"media":[{"id":"push-up-wide-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push-Up_Wide/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"push-up-wide-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push-Up_Wide/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Breiter Liegestütz","description":"Übung (Körpergewicht) für die Brust, unterstützt von Rumpf, Schultern, Trizeps.","instructions":["Eine Variante des Liegestützes mit weiterer Handposition, um die äußere Brustmuskulatur und die Schultern stärker zu beanspruchen.","Aufbau: Setze die Hände weiter als schulterbreit auf dem Boden auf.","Absenken: Senke dich ab, bis deine Brust den Boden fast berührt, und halte dabei deinen Rumpf angespannt.","Drücken: Drücke dich über die Handflächen wieder in die Ausgangsposition.","Haltung: Lass dein unteres Rücken nicht durchhängen; halte eine gerade Linie von Kopf bis Fersen."]}},{"id":"ex-push-ups-close-triceps-position","slug":"push-ups-close-triceps-position","name":"Push-Ups - Close Triceps Position","description":"Bodyweight exercise for the triceps, with chest, shoulders assisting.","instructions":["Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms' length.","Lower yourself until your chest almost touches the floor as you inhale.","Using your triceps and some of your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"BODYWEIGHT","tags":["push-ups - close triceps position"],"media":[{"id":"push-ups-close-triceps-position-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push-Ups_-_Close_Triceps_Position/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"push-ups-close-triceps-position-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push-Ups_-_Close_Triceps_Position/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-push-ups-decline","slug":"push-ups-decline","name":"Push-Ups | Decline","description":"Bodyweight exercise for the chest, with shoulders, triceps assisting.","instructions":["Decline push-ups are another modified version of the traditional push-up that target the upper body muscles in a different way. To perform a decline push-up, elevate your feet on an elevated surface, such as a bench, chair, or step, while placing your hands on the ground in a push-up position. Lower your body towards the ground while maintaining a straight line from your shoulders to your ankles, and then push back up to the starting position.","Unlike the inclined push-up, the decline push-up places more emphasis on the shoulders and triceps, while still engaging the chest muscles to a lesser extent. By elevating your feet, you increase the difficulty of the exercise by placing more weight on your upper body, forcing your shoulders and triceps to work harder to push your body back up. The decline push-up can be a great way to challenge your upper body strength and improve your ability to perform other push-up variations. As with any exercise, be sure to use proper form and start with a height that is appropriate for your strength and fitness level."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BODYWEIGHT","tags":["push-ups | decline","liegestütze | abfallend (decline)"],"media":[{"id":"push-ups-decline-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1112/81f40bee-4adf-4317-8476-1a87706e3031.png","caption":"Push-Ups | Decline","attribution":"wger.de · anon1337","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Liegestütze | abfallend (Decline)","description":"Übung (Körpergewicht) für die Brust, unterstützt von Schultern, Trizeps.","instructions":["Abfallende Liegestütze sind eine weitere abgewandelte Version des klassischen Liegestützes, die die Oberkörpermuskulatur auf andere Weise trainiert. Um einen abfallenden Liegestütz auszuführen, stellst du deine Füße auf eine erhöhte Fläche wie eine Bank, einen Stuhl oder eine Stufe und setzt deine Hände in der Liegestützposition auf den Boden. Senke deinen Körper zum Boden, während du eine gerade Linie von den Schultern bis zu den Knöcheln hältst, und drücke dich dann wieder in die Ausgangsposition hoch.","Anders als der Incline-Liegestütz legt der abfallende Liegestütz mehr Betonung auf die Schultern und den Trizeps, während die Brustmuskulatur weiterhin in geringerem Maße beansprucht wird. Indem du deine Füße erhöhst, steigerst du die Schwierigkeit der Übung, weil mehr Gewicht auf deinem Oberkörper lastet und deine Schultern und dein Trizeps härter arbeiten müssen, um deinen Körper wieder hochzudrücken. Der abfallende Liegestütz kann eine großartige Möglichkeit sein, deine Oberkörperkraft herauszufordern und deine Fähigkeit zu verbessern, andere Liegestützvarianten auszuführen. Achte wie bei jeder Übung auf eine saubere Ausführung und beginne mit einer Höhe, die zu deiner Kraft und deinem Fitnesslevel passt."]}},{"id":"ex-push-ups-incline","slug":"push-ups-incline","name":"Push-Ups | Incline","description":"Bodyweight exercise for the chest, with triceps assisting.","instructions":["Inclined push-ups primarily target the chest muscles (pectoralis major and minor), but also work the triceps, shoulders, and core to a lesser extent. Because the upper body is elevated, the incline push-up places less emphasis on the triceps compared to regular push-ups, which may be beneficial for individuals looking to specifically target their chest muscles."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["TRICEPS"],"equipment":"BODYWEIGHT","tags":["push-ups | incline","liegestütze | erhöht (incline)"],"media":[],"source":"wger","de":{"name":"Liegestütze | erhöht (Incline)","description":"Übung (Körpergewicht) für die Brust, unterstützt von Trizeps.","instructions":["Erhöhte Liegestütze trainieren vor allem die Brustmuskulatur (großer und kleiner Brustmuskel), beanspruchen aber in geringerem Maße auch den Trizeps, die Schultern und den Rumpf. Da der Oberkörper erhöht ist, belastet der Incline-Liegestütz den Trizeps weniger als der normale Liegestütz, was für alle von Vorteil sein kann, die gezielt ihre Brustmuskulatur ansprechen möchten."]}},{"id":"ex-push-ups-parallettes","slug":"push-ups-parallettes","name":"Push-Ups | Parallettes","description":"Bodyweight exercise for the chest, with shoulders, triceps assisting.","instructions":["Parallettes push-ups are a variation of the traditional push-up that are performed with the hands on parallel bars, known as parallettes. To perform a parallettes push-up, assume a push-up position with your hands on the parallettes and your feet on the ground. Lower your body towards the ground while keeping your elbows close to your sides, and then push back up to the starting position.","Parallettes push-ups place more emphasis on the chest and shoulders compared to traditional push-ups, as they allow for a greater range of motion in the shoulder joint. This increased range of motion can also help to improve shoulder stability and mobility. Additionally, parallettes push-ups engage the core muscles more than traditional push-ups, as the instability of the parallettes requires greater activation of the core muscles to maintain proper form.","The added challenge of balancing on the parallettes also requires greater upper body strength and control, making parallettes push-ups a more advanced variation of the traditional push-up. They can be a great way to challenge yourself and add variety to your upper body workout routine. As always, be sure to use proper form and start with a level that is appropriate for your strength and fitness level."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BODYWEIGHT","tags":["push-ups | parallettes","liegestütze | parallettes"],"media":[],"source":"wger","de":{"name":"Liegestütze | Parallettes","description":"Übung (Körpergewicht) für die Brust, unterstützt von Schultern, Trizeps.","instructions":["Parallettes-Liegestütze sind eine Variante des klassischen Liegestützes, die mit den Händen auf parallelen Stangen, den sogenannten Parallettes, ausgeführt wird. Um einen Parallettes-Liegestütz auszuführen, nimmst du eine Liegestützposition ein, die Hände auf den Parallettes und die Füße auf dem Boden. Senke deinen Körper zum Boden, während du die Ellbogen nah am Körper hältst, und drücke dich dann wieder in die Ausgangsposition hoch.","Parallettes-Liegestütze legen im Vergleich zu klassischen Liegestützen mehr Betonung auf Brust und Schultern, da sie einen größeren Bewegungsumfang im Schultergelenk ermöglichen. Dieser größere Bewegungsumfang kann auch helfen, die Stabilität und Beweglichkeit der Schulter zu verbessern. Außerdem beanspruchen Parallettes-Liegestütze die Rumpfmuskulatur stärker als klassische Liegestütze, da die Instabilität der Parallettes eine stärkere Aktivierung des Rumpfes erfordert, um die saubere Ausführung zu halten.","Die zusätzliche Herausforderung, auf den Parallettes zu balancieren, erfordert außerdem mehr Kraft und Kontrolle im Oberkörper, wodurch Parallettes-Liegestütze eine fortgeschrittenere Variante des klassischen Liegestützes sind. Sie können eine großartige Möglichkeit sein, dich selbst herauszufordern und Abwechslung in dein Oberkörpertraining zu bringen. Achte wie immer auf eine saubere Ausführung und beginne mit einem Niveau, das zu deiner Kraft und deinem Fitnesslevel passt."]}},{"id":"ex-push-ups-with-feet-elevated","slug":"push-ups-with-feet-elevated","name":"Push-Ups With Feet Elevated","description":"Bodyweight exercise for the chest, with shoulders, triceps assisting.","instructions":["Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.","Place your toes on top of a flat bench. This will allow your body to be elevated. Note: The higher the elevation of the flat bench, the higher the resistance of the exercise is.","Lower yourself until your chest almost touches the floor as you inhale.","Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BODYWEIGHT","tags":["push-ups with feet elevated"],"media":[{"id":"push-ups-with-feet-elevated-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push-Ups_With_Feet_Elevated/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"push-ups-with-feet-elevated-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push-Ups_With_Feet_Elevated/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-push-ups-with-feet-on-an-exercise-ball","slug":"push-ups-with-feet-on-an-exercise-ball","name":"Push-Ups With Feet On An Exercise Ball","description":"Accessory exercise for the chest, with shoulders, triceps assisting.","instructions":["Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.","Place your toes on top of an exercise ball. This will allow your body to be elevated.","Lower yourself until your chest almost touches the floor as you inhale.","Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"OTHER","tags":["push-ups with feet on an exercise ball"],"media":[{"id":"push-ups-with-feet-on-an-exercise-ball-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push-Ups_With_Feet_On_An_Exercise_Ball/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"push-ups-with-feet-on-an-exercise-ball-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push-Ups_With_Feet_On_An_Exercise_Ball/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-pushups-close-and-wide-hand-positions","slug":"pushups-close-and-wide-hand-positions","name":"Pushups (Close and Wide Hand Positions)","description":"Bodyweight exercise for the chest, with shoulders, triceps assisting.","instructions":["Lie on the floor face down and body straight with your toes on the floor and the hands wider than shoulder width for a wide hand position and closer than shoulder width for a close hand position. Make sure you are holding your torso up at arms length.","Lower yourself until your chest almost touches the floor as you inhale.","Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BODYWEIGHT","tags":["pushups (close and wide hand positions)"],"media":[{"id":"pushups-close-and-wide-hand-positions-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pushups_Close_and_Wide_Hand_Positions/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"pushups-close-and-wide-hand-positions-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pushups_Close_and_Wide_Hand_Positions/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-pyramid","slug":"pyramid","name":"Pyramid","description":"Accessory exercise for the back, with shoulders assisting.","instructions":["Start off by rolling your torso forward onto the ball so your hips rest on top of the ball and become the highest point of your body.","Rest your hands and feet on the floor. Your arms and legs can be slightly bent or straight, depending on the size of the ball, your flexibility, and the length of your limbs. This also helps develop stabilizing strength in your torso and shoulders."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["SHOULDERS"],"equipment":"OTHER","tags":["pyramid"],"media":[{"id":"pyramid-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pyramid/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"pyramid-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pyramid/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Schultern.","instructions":null}},{"id":"ex-quad-stretch","slug":"quad-stretch","name":"Quad Stretch","description":"Accessory exercise for the quadriceps.","instructions":["Lay on your side. Loop a belt, rope, or band around your top foot. Flex the knee and extend your hip, attempting to touch your glutes with your foot, and holding the belt with your hands. This will be your starting position.","With the belt being held over the shoulder or overhead, gently pull to increase the stretch in the quadriceps. Hold for 10-20 seconds, and then switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["quad stretch"],"media":[{"id":"quad-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Quad_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"quad-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Quad_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-quadriceps-smr","slug":"quadriceps-smr","name":"Quadriceps-SMR","description":"Foam roller exercise for the quadriceps.","instructions":["Lay facedown on the floor with your weight supported by your hands or forearms. Place a foam roll underneath one leg on the quadriceps, and keep the foot off of the ground. Make sure to relax the leg as much as possible. This will be your starting position.","Shifting as much weight onto the leg to be stretched as is tolerable, roll over the foam from above the knee to below the hip, holding points of tension for 10-30 seconds. Switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"FOAM_ROLLER","tags":["quadriceps-smr"],"media":[{"id":"quadriceps-smr-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Quadriceps-SMR/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"quadriceps-smr-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Quadriceps-SMR/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Faszienrolle) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-quadriceps-stretch","slug":"quadriceps-stretch","name":"Quadriceps Stretch","description":"Bodyweight exercise for the quadriceps.","instructions":["Stand on one leg (hold onto a wall if necessary). Use your hand to grasp the ankle of your other leg and gently pull your heel toward your buttocks. Make sure your knees stay close together and that you push your pelvis slightly forward (avoid arching your back)."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["quadriceps stretch","quadrizeps-dehnung"],"media":[],"source":"wger","de":{"name":"Quadrizeps-Dehnung","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite.","instructions":["Stelle dich auf ein Bein (halte dich ggf. an einer Wand fest). Greife mit der Hand den Fußknöchel des anderen Beins und ziehe die Ferse sanft zum Gesäß. Achte darauf, dass die Knie eng beieinander bleiben und du das Becken leicht nach vorne schiebst (Hohlkreuz vermeiden)."]}},{"id":"ex-quadriped-arm-and-leg-raise","slug":"quadriped-arm-and-leg-raise","name":"Quadriped Arm and Leg Raise","description":"Bodyweight exercise for the shoulders, with glutes, chest, back assisting.","instructions":["In this exercise, the back muscles and the muscles of the back of the leg and back of the arm are activated by lifting the crossed arm and leg at the same time in the crawling position. It also improves balance and proprioception. The movement is done symmetrically.","Get into a crawling posture.2. Draw your abdomen in, then raise your right leg and left arm.3. You should keep your abdomen in for 8 seconds.4. After 8 seconds, slowly lower your arm and leg.5. Then release your muscle."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["GLUTES","CHEST","BACK"],"equipment":"BODYWEIGHT","tags":["quadriped arm and leg raise","arm- und beinheben im vierfüßlerstand"],"media":[{"id":"quadriped-arm-and-leg-raise-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/957/0fd94587-6021-4763-856e-7227f5fcba2a.png","caption":"Quadriped Arm and Leg Raise","attribution":"wger.de · utkb","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Arm- und Beinheben im Vierfüßlerstand","description":"Übung (Körpergewicht) für die Schultern, unterstützt von Po, Brust, Rücken.","instructions":["Bei dieser Übung werden die Rückenmuskulatur sowie die Muskeln der Beinrückseite und der Armrückseite aktiviert, indem du im Vierfüßlerstand gleichzeitig den diagonal gegenüberliegenden Arm und das Bein anhebst. Sie verbessert außerdem das Gleichgewicht und die Propriozeption. Die Bewegung wird symmetrisch ausgeführt.","Begib dich in den Vierfüßlerstand.2. Ziehe den Bauch ein und hebe dann dein rechtes Bein und deinen linken Arm an.3. Halte den Bauch 8 Sekunden lang eingezogen.4. Senke nach 8 Sekunden langsam deinen Arm und dein Bein.5. Entspanne anschließend deine Muskeln."]}},{"id":"ex-quadruped-hip-abduction","slug":"quadruped-hip-abduction","name":"Quadruped Hip Abduction","description":"Resistance band exercise for the calves.","instructions":["Distribute your body weight evenly on all knees and arms.","Keep the torso stable, with the abdomen engaged and the lumbar spine","straight without twisting the back (imagine: a glass on your lower back","won't fall off). Raise one leg outwards without twisting it.","Pay attention to the right angle at the hips and knees. Always train both sides of the body.","To increase resistance, a resistance band can be used."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"BAND","tags":["quadruped hip abduction","hüftabduktion im vierfüßlerstand"],"media":[],"source":"wger","de":{"name":"Hüftabduktion im Vierfüßlerstand","description":"Übung (Widerstandsband) für die Waden.","instructions":["Verteile dein Körpergewicht gleichmäßig auf alle Knie und Arme.","Halte den Oberkörper stabil, die Bauchmuskulatur angespannt und die Lendenwirbelsäule","gerade, ohne den Rücken zu verdrehen (Vorstellung: ein Glas auf deinem unteren Rücken","würde nicht herunterfallen). Hebe ein Bein nach außen, ohne es zu verdrehen.","Achte auf den rechten Winkel an Hüfte und Knie. Trainiere immer beide Körperseiten.","Um den Widerstand zu erhöhen, kannst du ein Widerstandsband verwenden."]}},{"id":"ex-quick-leap","slug":"quick-leap","name":"Quick Leap","description":"Accessory exercise for the quadriceps, with calves, hamstrings assisting.","instructions":["You will need a box for this exerise.","Begin facing the box standing 1-2 feet from its edge.","By utilizing your hips, hop onto the box, landing on both legs. Ensure that you land with your legs bent and your feet flat.","Immediately upon landing, fully extend through the entire body and swing your arms overhead to explode off of the box. Use your legs to absorb the impact of landing."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","HAMSTRINGS"],"equipment":"OTHER","tags":["quick leap"],"media":[{"id":"quick-leap-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Quick_Leap/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"quick-leap-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Quick_Leap/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite, unterstützt von Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-rack-delivery","slug":"rack-delivery","name":"Rack Delivery","description":"Barbell exercise for the shoulders, with forearms, back assisting.","instructions":["This drill teaches the delivery of the barbell to the rack position on the shoulders. Begin holding a bar in the scarecrow position, with the upper arms parallel to the floor, and the forearms hanging down. Use a hook grip, with your fingers wrapped over your thumbs.","Begin by rotating the elbows around the bar, delivering the bar to the shoulders. As your elbows come forward, relax your grip. The shoulders should be protracted, providing a shelf for the bar, which should lightly contact the throat.","It is important that the bar stay close to the body at all times, as with a heavier load any distance will result in an unwanted collision. As the movement becomes smoother, speed and load can be increased before progressing further."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["FOREARMS","BACK"],"equipment":"BARBELL","tags":["rack delivery"],"media":[{"id":"rack-delivery-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rack_Delivery/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"rack-delivery-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rack_Delivery/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Schultern, unterstützt von Unterarme, Rücken.","instructions":null}},{"id":"ex-rack-pull-with-bands","slug":"rack-pull-with-bands","name":"Rack Pull with Bands","description":"Barbell exercise for the back, with forearms, glutes, hamstrings, quadriceps assisting.","instructions":["Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Attach bands to the base of the rack, or secure them with dumbbells. Attach the other end to the bar. You may need to choke the bands to provide tension.","Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.","With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement. Return the weight to the pins and repeat."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["FOREARMS","GLUTES","HAMSTRINGS","QUADRICEPS"],"equipment":"BARBELL","tags":["rack pull with bands"],"media":[{"id":"rack-pull-with-bands-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rack_Pull_with_Bands/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"rack-pull-with-bands-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rack_Pull_with_Bands/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Unterarme, Po, Oberschenkelrückseite, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-rack-pulls","slug":"rack-pulls","name":"Rack Pulls","description":"Barbell exercise for the back, with forearms, glutes, hamstrings assisting.","instructions":["Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.","With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement.","Return the weight to the pins and repeat."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["FOREARMS","GLUTES","HAMSTRINGS"],"equipment":"BARBELL","tags":["rack pulls"],"media":[{"id":"rack-pulls-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rack_Pulls/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"rack-pulls-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rack_Pulls/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Unterarme, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-reach-ups","slug":"reach-ups","name":"Reach ups","description":"Bodyweight exercise for the core.","instructions":["To perform this exercise, lie on your back with your arms extended overhead. Then, contract your abdominals and lift your torso off the floor while reaching your arms toward the ceiling to \"reach\" as high as possible. Slowly return to the starting position, controlling the movement. Reach ups strengthen the abdominal muscles and improve the flexibility of the spine. They can be incorporated into a variety of training routines to work on core strength and stability."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["reach ups","reach-ups"],"media":[],"source":"wger","de":{"name":"Reach-ups","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Um diese Übung auszuführen, lege dich auf den Rücken, die Arme über dem Kopf gestreckt. Spanne dann deine Bauchmuskeln an und hebe deinen Oberkörper vom Boden, indem du die Arme zur Decke streckst, um so hoch wie möglich zu \"reichen\". Kehre langsam und kontrolliert in die Ausgangsposition zurück. Die Reach-ups stärken die Bauchmuskeln und verbessern die Beweglichkeit der Wirbelsäule. Sie lassen sich in vielfältige Trainingsroutinen einbauen, um Kraft und Stabilität des Rumpfes zu trainieren."]}},{"id":"ex-rear-foot-elevated-hip-flexor-stretch","slug":"rear-foot-elevated-hip-flexor-stretch","name":"Rear-foot-elevated Hip Flexor Stretch","description":"Bodyweight exercise for the quadriceps.","instructions":["Rear-foot-elevated Hip Flexor Stretch","Part of: Limber 11","Source: Joe DeFranco","Prescription: 5-10 reps each side","Type: dynamic","Includes dynamic movement plus 3s hold."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["rear-foot-elevated hip flexor stretch","hüftbeuger-dehnung mit erhöhtem hinterem fuß"],"media":[],"source":"wger","de":{"name":"Hüftbeuger-Dehnung mit erhöhtem hinterem Fuß","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite.","instructions":["Hüftbeuger-Dehnung mit erhöhtem hinterem Fuß","Teil von: Limber 11","Quelle: Joe DeFranco","Vorgabe: 5-10 Wiederholungen pro Seite","Art: dynamisch","Umfasst eine dynamische Bewegung plus 3s Halten."]}},{"id":"ex-rear-leg-raises","slug":"rear-leg-raises","name":"Rear Leg Raises","description":"Bodyweight exercise for the quadriceps.","instructions":["Place yourself on your hands knees on an exercise mat. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.","Extend one leg up and behind you. The knee and hip should both extend. Repeat for 5-10 repetitions, and then switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["rear leg raises"],"media":[{"id":"rear-leg-raises-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rear_Leg_Raises/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"rear-leg-raises-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rear_Leg_Raises/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-return-push-from-stance","slug":"return-push-from-stance","name":"Return Push from Stance","description":"Accessory exercise for the shoulders, with chest, triceps assisting.","instructions":["You will need a partner for this drill.","Begin in an athletic 2 or 3 point stance.","At the signal, move into a position to receive the pass from your partner.","Catch the medicine ball with both hands and immediately throw it back to your partner.","You can modify this drill by running different routes."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CHEST","TRICEPS"],"equipment":"OTHER","tags":["return push from stance"],"media":[{"id":"return-push-from-stance-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Return_Push_from_Stance/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"return-push-from-stance-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Return_Push_from_Stance/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Schultern, unterstützt von Brust, Trizeps.","instructions":null}},{"id":"ex-reverse-band-bench-press","slug":"reverse-band-bench-press","name":"Reverse Band Bench Press","description":"Barbell exercise for the triceps, with chest, forearms, back, shoulders assisting.","instructions":["Position a bench inside a power rack, with the bar set to the correct height. Begin by anchoring bands either to band pegs or to the top of the rack. Ensure that you will be position properly under the bands. Attach the other end to the barbell.","Lie on the bench, tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.","Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.","Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","FOREARMS","BACK","SHOULDERS"],"equipment":"BARBELL","tags":["reverse band bench press"],"media":[{"id":"reverse-band-bench-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Band_Bench_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"reverse-band-bench-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Band_Bench_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Trizeps, unterstützt von Brust, Unterarme, Rücken, Schultern.","instructions":null}},{"id":"ex-reverse-band-box-squat","slug":"reverse-band-box-squat","name":"Reverse Band Box Squat","description":"Barbell exercise for the quadriceps, with glutes, calves, forearms, hamstrings, back assisting.","instructions":["Begin in a power rack with a box at the appropriate height behind you. Set up the bands either on band pegs or attached to the top of the rack, ensuring they will be directly above the bar during the squat. Attach the other end to the bar.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.","Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barbell to the rack."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","CALVES","FOREARMS","HAMSTRINGS","BACK"],"equipment":"BARBELL","tags":["reverse band box squat"],"media":[{"id":"reverse-band-box-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Band_Box_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"reverse-band-box-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Band_Box_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Po, Waden, Unterarme, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-reverse-band-deadlift","slug":"reverse-band-deadlift","name":"Reverse Band Deadlift","description":"Barbell exercise for the back, with glutes, quadriceps, calves, hamstrings assisting.","instructions":["Set the bar up in a power rack. Attach bands to the top of the rack, using either bands pegs or the frame itself. Attach the other end of the bands to the bar.","Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.","With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.","After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["GLUTES","QUADRICEPS","CALVES","HAMSTRINGS"],"equipment":"BARBELL","tags":["reverse band deadlift"],"media":[{"id":"reverse-band-deadlift-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Band_Deadlift/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"reverse-band-deadlift-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Band_Deadlift/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Po, Oberschenkelvorderseite, Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-reverse-band-power-squat","slug":"reverse-band-power-squat","name":"Reverse Band Power Squat","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings, back assisting.","instructions":["Begin in a power rack with the pins and bar set at the appropriate height. After loading the bar, attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end of the bands to the bar.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings.","Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.","Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","BACK"],"equipment":"BARBELL","tags":["reverse band power squat"],"media":[{"id":"reverse-band-power-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Band_Power_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"reverse-band-power-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Band_Power_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-reverse-band-sumo-deadlift","slug":"reverse-band-sumo-deadlift","name":"Reverse Band Sumo Deadlift","description":"Barbell exercise for the hamstrings, with glutes, quadriceps, calves, forearms, back assisting.","instructions":["Begin with a bar loaded on the floor inside of a power rack. Attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end to the barbell.","Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.","Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.","As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.","Return the weight to the ground by bending at the hips and controlling the weight on the way down."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","QUADRICEPS","CALVES","FOREARMS","BACK"],"equipment":"BARBELL","tags":["reverse band sumo deadlift"],"media":[{"id":"reverse-band-sumo-deadlift-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Band_Sumo_Deadlift/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"reverse-band-sumo-deadlift-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Band_Sumo_Deadlift/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Po, Oberschenkelvorderseite, Waden, Unterarme, Rücken.","instructions":null}},{"id":"ex-reverse-barbell-curl","slug":"reverse-barbell-curl","name":"Reverse Barbell Curl","description":"Barbell exercise for the biceps, with forearms assisting.","instructions":["Stand up with your torso upright while holding a barbell at shoulder width with the elbows close to the torso. The palm of your hands should be facing down (pronated grip). This will be your starting position.","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"BARBELL","tags":["reverse barbell curl"],"media":[{"id":"reverse-barbell-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Barbell_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"reverse-barbell-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Barbell_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Bizeps, unterstützt von Unterarme.","instructions":null}},{"id":"ex-reverse-barbell-preacher-curls","slug":"reverse-barbell-preacher-curls","name":"Reverse Barbell Preacher Curls","description":"EZ-bar exercise for the biceps, with forearms assisting.","instructions":["Grab an EZ-bar using a shoulder width and palms down (pronated) grip.","Now place the upper part of both arms on top of the preacher bench and have your arms extended. This will be your starting position.","As you exhale, use the biceps to curl the weight up until your biceps are fully contracted and the barbell is at shoulder height. Squeeze the biceps hard for a second at the contracted position.","As you breathe in, slowly lower the barbell until your upper arms are extended and the biceps is fully stretched.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"EZ_BAR","tags":["reverse barbell preacher curls"],"media":[{"id":"reverse-barbell-preacher-curls-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Barbell_Preacher_Curls/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"reverse-barbell-preacher-curls-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Barbell_Preacher_Curls/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (SZ-Stange) für den Bizeps, unterstützt von Unterarme.","instructions":null}},{"id":"ex-reverse-cable-curl","slug":"reverse-cable-curl","name":"Reverse Cable Curl","description":"Cable exercise for the biceps, with forearms assisting.","instructions":["Stand up with your torso upright while holding a bar attachment that is attached to a low pulley using a pronated (palms down) and shoulder width grip. Make sure also that you keep the elbows close to the torso. This will be your starting position.","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"CABLE","tags":["reverse cable curl"],"media":[{"id":"reverse-cable-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Cable_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"reverse-cable-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Cable_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Bizeps, unterstützt von Unterarme.","instructions":null}},{"id":"ex-reverse-curl","slug":"reverse-curl","name":"Reverse Curl","description":"Barbell exercise for the biceps.","instructions":["The reverse-grip barbell curl is a variation on the biceps curl where the palms face downward. The switch from an underhand to an overhand grip brings the forearm and brachialis muscles more into the exercise."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["reverse curl","reverse curls"],"media":[],"source":"wger","de":{"name":"Reverse Curls","description":"Übung (Langhantel) für den Bizeps.","instructions":["Bewegungablauf ist wie bei normalen Langhantel Curls für den Bizeps, nur die Handstellung ist reverse, also die Handflächen zeigen nach hinten.","Halte die Hantel mit etwa schulterbreitem Griff, die Arme sind ausgestreckt. Beuge die Arme und brige die Hantel mit einer schnellen Bewegung nach oben. Ohne Pause wird das Gewicht nun kontrolliert nach unten gebracht. Beachte, dass die Bewegung nach oben schneller ist als nach unten.","Während des Bewegungablaufs sollte der Körper nicht mitschwingen. Die Ellenbogen bleiben dabei immer an der Stelle."]}},{"id":"ex-reverse-fly-standing","slug":"reverse-fly-standing","name":"Reverse Fly Standing","description":"Cable exercise for the shoulders, with back assisting.","instructions":["Stand with a good posture holding a cable in each hand opposite the machine","Starting with the hands in front of your chest pull the arms out to","your side into the shape of a T with the elbows nearly straight","Slowly release the arms forward to the start","Repeat with the arms moving into the shape of a Y","Repeat with the arms in the shape of a W","Repeat with the arms in the shape of an L by your side"],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"CABLE","tags":["reverse fly standing","reverse fly im stehen"],"media":[],"source":"wger","de":{"name":"Reverse Fly im Stehen","description":"Übung (Kabelzug) für die Schultern, unterstützt von Rücken.","instructions":["Stehe mit guter Haltung und halte in jeder Hand ein Kabel gegenüber der Maschine","Beginne mit den Händen vor deiner Brust und ziehe die Arme zur Seite","in die Form eines T, wobei die Ellbogen nahezu gestreckt sind","Führe die Arme langsam wieder nach vorn in die Ausgangsposition","Wiederhole es, indem du die Arme in die Form eines Y bewegst","Wiederhole es mit den Armen in der Form eines W","Wiederhole es mit den Armen in der Form eines L seitlich am Körper"]}},{"id":"ex-reverse-flyes","slug":"reverse-flyes","name":"Reverse Flyes","description":"Dumbbell exercise for the shoulders.","instructions":["To begin, lie down on an incline bench with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing each other (neutral grip).","Extend the arms in front of you so that they are perpendicular to the angle of the bench. The legs should be stationary while applying pressure with the ball of your toes. This is the starting position.","Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion while exhaling. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.","The arms should be elevated until they are parallel to the floor.","Feel the contraction and slowly lower the weights back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["reverse flyes"],"media":[{"id":"reverse-flyes-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Flyes/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"reverse-flyes-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Flyes/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern.","instructions":null}},{"id":"ex-reverse-flyes-with-external-rotation","slug":"reverse-flyes-with-external-rotation","name":"Reverse Flyes With External Rotation","description":"Dumbbell exercise for the shoulders.","instructions":["To begin, lie down on an incline bench set at a 30-degree angle with the chest and stomach pressing against the incline.","Have the dumbbells in each hand with the palms facing down to the floor. Your arms should be in front of you so that they are perpendicular to the angle of the bench. Tip: Your elbows should have a slight bend. The legs should be stationary while applying pressure with the ball of your toes (your heels should not be touching the floor). This is the starting position.","Maintaining the slight bend of the elbows, move the weights out and away from each other in an arc motion while exhaling.","As you lift the weight, your wrist should externally rotate by 90-degrees so that you go from a palms down (pronated) grip to a palms facing each other (neutral) grip. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.","The arms should be elevated until they are level with the head.","Feel the contraction and slowly lower the weights back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["reverse flyes with external rotation"],"media":[{"id":"reverse-flyes-with-external-rotation-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Flyes_With_External_Rotation/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"reverse-flyes-with-external-rotation-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Flyes_With_External_Rotation/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern.","instructions":null}},{"id":"ex-reverse-grip-bent-over-rows","slug":"reverse-grip-bent-over-rows","name":"Reverse Grip Bent-Over Rows","description":"Barbell exercise for the back, with biceps, shoulders assisting.","instructions":["Stand erect while holding a barbell with a supinated grip (palms facing up).","Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.","Slowly lower the weight again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","SHOULDERS"],"equipment":"BARBELL","tags":["reverse grip bent-over rows"],"media":[{"id":"reverse-grip-bent-over-rows-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Grip_Bent-Over_Rows/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"reverse-grip-bent-over-rows-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Grip_Bent-Over_Rows/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Bizeps, Schultern.","instructions":null}},{"id":"ex-reverse-hyperextension","slug":"reverse-hyperextension","name":"Reverse Hyperextension","description":"Machine exercise for the hamstrings, with calves, glutes assisting.","instructions":["Place your feet between the pads after loading an appropriate weight. Lay on the top pad, allowing your hips to hang off the back, while grasping the handles to hold your position.","To begin the movement, flex the hips, pulling the legs forward.","Reverse the motion by extending the hips, kicking the leg back. It is very important not to over-extend the hip on this movement, stopping short of your full range of motion.","Return by again flexing the hip, pulling the carriage forward as far as you can.","Repeat for the desired number of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","GLUTES"],"equipment":"MACHINE","tags":["reverse hyperextension","umgekehrte hyperextension"],"media":[{"id":"reverse-hyperextension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Hyperextension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"reverse-hyperextension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Hyperextension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Umgekehrte Hyperextension","description":"Übung (Maschine) für die Oberschenkelrückseite, unterstützt von Waden, Po.","instructions":["Lege dich mit dem Gesicht nach unten auf eine Bank, sodass deine Beine über die Kante hinausragen.","Beuge deine Hüften, sodass deine Oberschenkel senkrecht stehen, und beuge gleichzeitig die Knie, sodass deine Unterschenkel waagerecht bleiben.","Strecke deine Beine, sodass sie nicht mehr gebeugt sind und deine Fußspitzen waagerecht nach hinten zeigen.","Kehre in die Ausgangsposition zurück und wiederhole die Bewegung."]}},{"id":"ex-reverse-lunges","slug":"reverse-lunges","name":"Reverse lunges","description":"Bodyweight exercise for the glutes, with quadriceps, hamstrings assisting.","instructions":["Starting position:","Stand straight, feet hip-width apart.","Steps:","Step backward with one leg so it can bend comfortably to a 90 degree angle.","Slowly bend both knees to form 90 degree angles.","Return to the starting position.","Repeat, alternating legs."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["QUADRICEPS","HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["reverse lunges","umgekehrte ausfallschritte"],"media":[{"id":"reverse-lunges-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/999/d0931eb3-8db0-4049-bb08-aa4036072056.jfif","caption":"Reverse lunges","attribution":"wger.de · philip","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Umgekehrte Ausfallschritte","description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelvorderseite, Oberschenkelrückseite.","instructions":["Ausgangsposition:","Gerade stehen, Füße hüftbreit auseinander.","Schritte:","Treten Sie mit einem Bein nach hinten, so dass Sie es bequem bis zu einem Winkel von 90 Grad beugen können.","Beugen Sie langsam beide Knie, um einen 90-Grad-Winkel zu bilden.","Kehren Sie in die Ausgangsposition zurück.","Wiederholen, dabei die Beine abwechseln."]}},{"id":"ex-reverse-plate-curls","slug":"reverse-plate-curls","name":"Reverse Plate Curls","description":"Accessory exercise for the biceps, with forearms assisting.","instructions":["Start by standing straight with a weighted plate held by both hands and arms fully extended. Use a pronated grip (palms facing down) and make sure your fingers grab the rough side of the plate while your thumb grabs the smooth side. Note: For the best results, grab the weighted plate at an 11:00 and 1:00 o'clock position.","Your feet should be shoulder width apart from each other and the weighted plate should be near the groin area. This is the starting position.","Slowly lift the plate up while keeping the elbows in and the upper arms stationary until your biceps and forearms touch while exhaling. The plate should be evenly aligned with your torso at this point.","Feel the contraction for a second and begin to lower the weight back down to the starting position while inhaling","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"OTHER","tags":["reverse plate curls"],"media":[{"id":"reverse-plate-curls-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Plate_Curls/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"reverse-plate-curls-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Plate_Curls/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Bizeps, unterstützt von Unterarme.","instructions":null}},{"id":"ex-reverse-triceps-bench-press","slug":"reverse-triceps-bench-press","name":"Reverse Triceps Bench Press","description":"Barbell exercise for the triceps, with chest, shoulders assisting.","instructions":["Lie back on a flat bench. Using a close, supinated grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked extended in front of you and perpendicular to the floor. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"BARBELL","tags":["reverse triceps bench press"],"media":[{"id":"reverse-triceps-bench-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Triceps_Bench_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"reverse-triceps-bench-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Triceps_Bench_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-reverse-wood-chops","slug":"reverse-wood-chops","name":"Reverse Wood Chops","description":"Bodyweight exercise for the glutes, with back, shoulders, biceps, core, quadriceps assisting.","instructions":["Attach a looping resistance band to a rack below knee height","Grip the other end of the band like holding a baseball bat with both hands","Stretch the band facing it","Start with your hands at the side of your hips, knees bent","Rotate your hips while moving your hands towards over the top of your opposite shoulder","Imagine the motion as striking a baseball with a bat"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["BACK","SHOULDERS","BICEPS","ABS_CORE","QUADRICEPS"],"equipment":"BODYWEIGHT","tags":["reverse wood chops","umgekehrte holzhacker"],"media":[],"source":"wger","de":{"name":"Umgekehrte Holzhacker","description":"Übung (Körpergewicht) für den Po, unterstützt von Rücken, Schultern, Bizeps, Rumpf, Oberschenkelvorderseite.","instructions":["Befestige ein geschlossenes Widerstandsband unterhalb der Kniehöhe an einem Rack","Greife das andere Ende des Bandes mit beiden Händen wie einen Baseballschläger","Spanne das Band vor, indem du dich ihm zuwendest","Beginne mit deinen Händen seitlich an deiner Hüfte, die Knie gebeugt","Rotiere deine Hüften, während du deine Hände nach oben über deine gegenüberliegende Schulter führst","Stelle dir die Bewegung vor, als würdest du einen Baseball mit einem Schläger schlagen"]}},{"id":"ex-rhomboids-smr","slug":"rhomboids-smr","name":"Rhomboids-SMR","description":"Foam roller exercise for the back.","instructions":["Lay down with your back on the floor. Place a foam roll underneath your upper back, and cross your arms in front of you, protracting your shoulders. This will be your starting position.","Raise your hips off of the ground, placing your weight onto the foam roll. Shift your weight to one side at a time, rolling over your middle and upper back. Pause at points of tension for 10-30 seconds."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"FOAM_ROLLER","tags":["rhomboids-smr"],"media":[{"id":"rhomboids-smr-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rhomboids-SMR/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"rhomboids-smr-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rhomboids-SMR/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Faszienrolle) für den Rücken.","instructions":null}},{"id":"ex-ring-dips","slug":"ring-dips","name":"Ring Dips","description":"Accessory exercise for the triceps, with chest, shoulders assisting.","instructions":["Grip a ring in each hand, and then take a small jump to help you get into the starting position with your arms locked out.","Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent.","Reverse the motion by extending the elbow, pushing yourself back up into the starting position.","Repeat for the desired number of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"OTHER","tags":["ring dips"],"media":[{"id":"ring-dips-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ring_Dips/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"ring-dips-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ring_Dips/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-ring-support-hold","slug":"ring-support-hold","name":"Ring Support Hold","description":"Bodyweight exercise for the chest.","instructions":["Hold yourself in a support position on gymnastic rings with arms straight at sides. Focus on keeping rings turned out slightly and maintaining hollow body position. This is an isometric hold for chest, shoulders, and triceps."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["ring support hold","stützhalt an den ringen"],"media":[],"source":"wger","de":{"name":"Stützhalt an den Ringen","description":"Übung (Körpergewicht) für die Brust.","instructions":["Halte dich in einer Stützposition auf Turnringen, die Arme gestreckt an den Seiten. Achte darauf, die Ringe leicht nach außen gedreht zu halten und eine Hollow-Body-Position einzunehmen. Dies ist ein isometrischer Halt für Brust, Schultern und Trizeps."]}},{"id":"ex-rocket-jump","slug":"rocket-jump","name":"Rocket Jump","description":"Bodyweight exercise for the quadriceps, with calves, hamstrings assisting.","instructions":["Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.","To initiate the move, squat down halfway and explode back up as high as possible.","Fully extend your entire body, reaching overhead as far as possible. As you land, absorb your impact through the legs."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["rocket jump"],"media":[{"id":"rocket-jump-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rocket_Jump/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"rocket-jump-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rocket_Jump/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-rocking-standing-calf-raise","slug":"rocking-standing-calf-raise","name":"Rocking Standing Calf Raise","description":"Barbell exercise for the calves.","instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place it on the back of your shoulders (slightly below the neck).","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance. Also maintain a straight back and keep the knees with a slight bend; never locked. This will be your starting position.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending (other than the slight initial bend we created during positioning) at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Now lift your toes by contracting the tibia muscles in the front of the calves as you breathe out.","Hold for a second and bring them back down as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["rocking standing calf raise"],"media":[{"id":"rocking-standing-calf-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rocking_Standing_Calf_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"rocking-standing-calf-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rocking_Standing_Calf_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Waden.","instructions":null}},{"id":"ex-rocky-pull-ups-pulldowns","slug":"rocky-pull-ups-pulldowns","name":"Rocky Pull-Ups/Pulldowns","description":"Accessory exercise for the back, with biceps, shoulders assisting.","instructions":["Grab the pull-up bar with the palms facing forward using a wide grip.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.","Now repeat the same movements as described above except this time your torso will remain straight as you go up and the bar will touch the back of the neck instead of the upper chest. Tip: Use the head to lean forward slightly as it will help you properly execute this portion of the exercise.","Once you have lowered yourself back down to the starting position, repeat the exercise for the prescribed amount of repetitions in your program."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","SHOULDERS"],"equipment":"OTHER","tags":["rocky pull-ups/pulldowns"],"media":[{"id":"rocky-pull-ups-pulldowns-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rocky_Pull-Ups_Pulldowns/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"rocky-pull-ups-pulldowns-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rocky_Pull-Ups_Pulldowns/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Bizeps, Schultern.","instructions":null}},{"id":"ex-roman-chair-crunch","slug":"roman-chair-crunch","name":"Roman Chair Crunch","description":"Bodyweight exercise for the core.","instructions":["Crunches on roman chair. Keep your torso straight, abs tight, and don't come up all the way vertical or lie flat to keep constant tension on your abs."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["roman chair crunch","beinheben am roman chair"],"media":[],"source":"wger","de":{"name":"Beinheben am Roman Chair","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Stütze dich mit dem Unterarmen ab und hänge im Gerät. Ziehe die Knie Richtung Brust und lasse sie wieder kontrolliert zum Boden zurück."]}},{"id":"ex-romanian-deadlift-from-deficit","slug":"romanian-deadlift-from-deficit","name":"Romanian Deadlift from Deficit","description":"Barbell exercise for the hamstrings, with forearms, glutes, back assisting.","instructions":["Begin standing while holding a bar at arm's length in front of you. You can stand on a raised platform to increase the range of motion.","Begin by flexing the knees slightly, and then flex at the hip, moving your butt back as far as possible, lowering the torso as far as flexibility allows. The back should remain in absolute extension at all times, and the bar should remain in contact with the legs. If done properly, there should be heavy tension felt in the hamstrings.","Reverse the motion to return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["FOREARMS","GLUTES","BACK"],"equipment":"BARBELL","tags":["romanian deadlift from deficit"],"media":[{"id":"romanian-deadlift-from-deficit-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift_from_Deficit/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"romanian-deadlift-from-deficit-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift_from_Deficit/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Unterarme, Po, Rücken.","instructions":null}},{"id":"ex-rope-climb","slug":"rope-climb","name":"Rope Climb","description":"Accessory exercise for the back, with biceps, forearms, shoulders assisting.","instructions":["Grab the rope with both hands above your head. Pull down on the rope as you take a small jump.","Wrap the rope around one leg, using your feet to pinch the rope. Reach up as high as possible with your arms, gripping the rope tightly.","Release the rope from your feet as you pull yourself up with your arms, bringing your knees towards your chest.","Resecure your feet on the rope, and then stand up to take another high hold on the rope. Continue until you reach the top of the rope.","To lower yourself, loosen the grip of your feet on the rope as you slide down using a hand over hand motion."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","FOREARMS","SHOULDERS"],"equipment":"OTHER","tags":["rope climb"],"media":[{"id":"rope-climb-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Climb/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"rope-climb-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Climb/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Bizeps, Unterarme, Schultern.","instructions":null}},{"id":"ex-rope-crunch","slug":"rope-crunch","name":"Rope Crunch","description":"Cable exercise for the core.","instructions":["Kneel 1-2 feet in front of a cable system with a rope attached.","After selecting an appropriate weight, grasp the rope with both hands reaching overhead. Your torso should be upright in the starting position.","To begin, flex at the spine, attempting to bring your rib cage to your legs as you pull the cable down.","Pause at the bottom of the motion, and then slowly return to the starting position.","These can be done with twists or to the side to hit the obliques."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["rope crunch"],"media":[{"id":"rope-crunch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Crunch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"rope-crunch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Crunch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rumpf.","instructions":null}},{"id":"ex-rope-pullover-row","slug":"rope-pullover-row","name":"Rope Pullover/row","description":"Cable exercise for the back.","instructions":["Set up bench in front of cable row machine. Lean over bench to do a row/pullover with rope that targets lats. See picture."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["rope pullover/row","seilzug-pullover/rudern"],"media":[{"id":"rope-pullover-row-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1634/9a4704d3-1b25-43e3-b244-3885f4d3db87.png","caption":"Rope Pullover/row","attribution":"wger.de · Rottekongen","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Seilzug-Pullover/Rudern","description":"Übung (Kabelzug) für den Rücken.","instructions":["Stelle eine Bank vor die Kabelzug-Rudermaschine. Beuge dich über die Bank, um mit dem Seil ein Rudern/einen Pullover auszuführen, das den Latissimus beansprucht. Siehe Bild."]}},{"id":"ex-rope-straight-arm-pulldown","slug":"rope-straight-arm-pulldown","name":"Rope Straight-Arm Pulldown","description":"Cable exercise for the back.","instructions":["Attach a rope to a high pulley and make your weight selection. Stand a couple feet back from the pulley with your feet staggered and take the rope with both hands. Lean forward from the hip, keeping your back straight, with your arms extended up in front of you. This will be your starting position.","Keeping your arms straight, extend the shoulder to pull the rope down to your thighs.","Pause at the bottom of the motion, squeezing your lats.","Return to the starting position without allowing the weight to fully rest on the stack."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["rope straight-arm pulldown"],"media":[{"id":"rope-straight-arm-pulldown-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Straight-Arm_Pulldown/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"rope-straight-arm-pulldown-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Straight-Arm_Pulldown/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rücken.","instructions":null}},{"id":"ex-rotary-torso-machine","slug":"rotary-torso-machine","name":"Rotary Torso Machine","description":"Machine exercise for the core.","instructions":["Slow and Steady","Not too much weight"],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["rotary torso machine","bauch-twist gerät","torso-rotation-maschine"],"media":[],"source":"wger","de":{"name":"Torso-Rotation-Maschine","description":"Übung (Maschine) für den Rumpf.","instructions":["Langsam und stätig","Nicht zu viel Gewicht nutzen"]}},{"id":"ex-round-the-world-shoulder-stretch","slug":"round-the-world-shoulder-stretch","name":"Round The World Shoulder Stretch","description":"Accessory exercise for the shoulders, with biceps, chest assisting.","instructions":["Stand up straight with your legs together, holding a bodybar or broomstick.","Hold the pole behind your hips with a wider than shoulder width grip. Your palms should be down and your thumbs facing out.","Slowly lift your arms up behind your head. Don't force it if it gets hard to lift further."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BICEPS","CHEST"],"equipment":"OTHER","tags":["round the world shoulder stretch"],"media":[{"id":"round-the-world-shoulder-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Round_The_World_Shoulder_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"round-the-world-shoulder-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Round_The_World_Shoulder_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Schultern, unterstützt von Bizeps, Brust.","instructions":null}},{"id":"ex-row","slug":"row","name":"Row","description":"Barbell exercise for the back, with quadriceps assisting.","instructions":["In strength training, rowing (or a row, usually preceded by a qualifying adjective — for instance a seated row) is an exercise where the purpose is to strengthen the muscles that draw the rower's arms toward the body (latissimus dorsi) as well as those that retract the scapulae (trapezius and rhomboids) and those that support the spine (erector spinae). When done on a rowing machine, rowing also exercises muscles that extend and support the legs (quadriceps and thigh muscles). In all cases, the abdominal and lower back muscles must be used in order to support the body and prevent back injury."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["QUADRICEPS"],"equipment":"BARBELL","tags":["row","rudern"],"media":[],"source":"wger","de":{"name":"Rudern","description":"Übung (Langhantel) für den Rücken, unterstützt von Oberschenkelvorderseite.","instructions":["Im Krafttraining ist das Rudern (engl. \"row\", meist mit einem näher bestimmenden Adjektiv versehen, zum Beispiel sitzendes Rudern) eine Übung, deren Zweck es ist, die Muskeln zu stärken, die die Arme zum Körper ziehen (Latissimus), sowie jene, die die Schulterblätter zurückziehen (Trapezmuskel und Rhomboiden), und jene, die die Wirbelsäule stützen (Rückenstrecker). Wird das Rudern an einer Rudermaschine ausgeführt, trainiert es zusätzlich die Muskeln, die die Beine strecken und stützen (vordere Oberschenkelmuskulatur und Oberschenkelmuskeln). In allen Fällen müssen die Bauch- und unteren Rückenmuskeln eingesetzt werden, um den Körper zu stützen und Rückenverletzungen zu vermeiden."]}},{"id":"ex-rowing-seated-narrow-grip","slug":"rowing-seated-narrow-grip","name":"Rowing seated, narrow grip","description":"Bodyweight exercise for the back.","instructions":["Tighten muscles","Controlled movement","Slow movement","Keep upper body upright","Do not lean back","Pull toward chest"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["rowing seated, narrow grip","rudern sitzend, eng"],"media":[{"id":"rowing-seated-narrow-grip-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/512/b938437e-ff00-4679-9036-acb41bb28bbd.png","caption":"Rowing seated, narrow grip","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Rudern Sitzend, Eng","description":"Übung (Körpergewicht) für den Rücken.","instructions":["beim Einatmen den Haltegriff zum Schwertfortsatz des Brustbeins führen. während der Rücken aufgerichtet und die Ellbogen so weit wie möglich nach hinten gezogen werden"]}},{"id":"ex-rowing-t-bar","slug":"rowing-t-bar","name":"Rowing, T-bar","description":"Bodyweight exercise for the back, with shoulders, biceps assisting.","instructions":["The execution of this exercise is very similar to the regular bent over rowing, only that the bar is fixed here.","Grab the barbell with a wide grip (slightly more than shoulder wide) and lean forward. Your upper body is not quite parallel to the floor, but forms a slight angle. The chest's out during the whole exercise. Pull now the barbell with a fast movement towards your belly button, not further up. Go slowly down to the initial position. Don't swing with your body and keep your arms next to your body."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["SHOULDERS","BICEPS"],"equipment":"BODYWEIGHT","tags":["rowing, t-bar","t-bar rudern (breit)"],"media":[{"id":"rowing-t-bar-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/106/T-bar-row-1.png","caption":"Rowing, T-bar","attribution":"wger.de · Everkinetic","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"T-Bar Rudern (breit)","description":"Übung (Körpergewicht) für den Rücken, unterstützt von Schultern, Bizeps.","instructions":["Die Ausführung ist sehr ähnlich wie beim freien vorgebeugtem Rudern, nur ist hier die Stange fest.","Stelle dich auf das Gerät in die entsprechende Stelle und greife die Gewichtsstange mit mittelbreitem Griff. Gehe etwas in die Knie, bringe die Brust raus und führe den Oberkörper nach vorne. Hebe das Gewicht und ziehe es in Richtung Bauchnabel hoch (Ellenbogen am Körper lassen). Lasse es dann langsam wieder runter und spüre die Dehnung in den Kreuzmuskeln."]}},{"id":"ex-rowing-with-trx-band","slug":"rowing-with-trx-band","name":"Rowing with TRX band","description":"Bodyweight exercise for the back, with biceps assisting.","instructions":["Rowing with resistance bands - Bodyweight Exercise"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"BODYWEIGHT","tags":["rowing with trx band","trx rudern"],"media":[],"source":"wger","de":{"name":"TRX Rudern","description":"Übung (Körpergewicht) für den Rücken, unterstützt von Bizeps.","instructions":["Rudern mit Schlingentrainer - Körpergewichtsübung"]}},{"id":"ex-rubber-band-glute-kickback","slug":"rubber-band-glute-kickback","name":"rubber band glute kickback","description":"Resistance band exercise for the glutes.","instructions":["A rubber band glute kickback is an exercise performed on hands and knees, where you anchor a resistance band to your foot and kick your heel back and up, squeezing your glute at the top of the movement, while maintaining a stable core and flat back to target and strengthen the gluteal muscles."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":[],"equipment":"BAND","tags":["rubber band glute kickback","glute kickback mit widerstandsband"],"media":[{"id":"rubber-band-glute-kickback-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1613/a851fe9d-771f-44da-82f0-799e02ae3fd1.jpg","caption":"rubber band glute kickback","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Glute Kickback mit Widerstandsband","description":"Übung (Widerstandsband) für den Po.","instructions":["Der Glute Kickback mit Widerstandsband ist eine Übung, die im Vierfüßlerstand ausgeführt wird. Dabei befestigst du ein Widerstandsband an deinem Fuß und drückst deine Ferse nach hinten und oben, wobei du am höchsten Punkt der Bewegung deine Gesäßmuskulatur anspannst. Gleichzeitig hältst du den Rumpf stabil und den Rücken gerade, um gezielt die Gesäßmuskulatur zu beanspruchen und zu stärken."]}},{"id":"ex-runners-stretch","slug":"runners-stretch","name":"Runner's Stretch","description":"Equipment-free exercise for the hamstrings, with calves assisting.","instructions":["It's easiest to get into this stretch if you start standing up, put one leg behind you, and slowly lower your torso down to the floor.","Keep the front heel on the floor (if it lifts up, scoot your other leg further back).","Place your hands on either side of your front leg. To get more out of this stretch, push your butt up toward the ceiling, and then gradually lower it back toward the floor. You'll Stretch the hip flexor of the back leg and the hamstring and buttocks of the front."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES"],"equipment":"NONE","tags":["runner's stretch"],"media":[{"id":"runners-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Runners_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"runners-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Runners_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelrückseite, unterstützt von Waden.","instructions":null}},{"id":"ex-russian-twist","slug":"russian-twist","name":"Russian Twist","description":"Bodyweight exercise for the core, with back assisting.","instructions":["Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.","Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.","Twist your torso to the right side until your arms are parallel with the floor while breathing out.","Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["BACK"],"equipment":"BODYWEIGHT","tags":["russian twist"],"media":[{"id":"russian-twist-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Russian_Twist/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"russian-twist-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Russian_Twist/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Russian Twist","description":"Übung (Körpergewicht) für den Rumpf, unterstützt von Rücken.","instructions":["Halte eine Kurzhantel, eine Hantelscheibe oder etwas anderes Schweres mit beiden Händen, aber achte darauf, dass es nicht zu schwer ist und du die Form halten kannst.","Lehne dich in einem Winkel von 45 Grad zum Boden zurück. Für eine zusätzliche Herausforderung hebst du die Füße vom Boden ab.","Drehe deine Arme zu einer Seite auf Brusthöhe, berühre für eine kleine zusätzliche Herausforderung den Boden und mache dann dasselbe zur anderen Seite. Wenn du nach beiden Seiten wieder in der Ausgangsposition bist, zählt das als 1 Wiederholung."]}},{"id":"ex-scapular-pull-up","slug":"scapular-pull-up","name":"Scapular Pull-Up","description":"Equipment-free exercise for the back.","instructions":["Take a pronated grip on a pull-up bar.","From a hanging position, raise yourself a few inches without using your arms. Do this by depressing your shoulder girdle in a reverse shrugging motion.","Pause at the completion of the movement, and then slowly return to the starting position before performing more repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"NONE","tags":["scapular pull-up"],"media":[{"id":"scapular-pull-up-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Scapular_Pull-Up/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"scapular-pull-up-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Scapular_Pull-Up/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Rücken.","instructions":null}},{"id":"ex-scissor-kick","slug":"scissor-kick","name":"Scissor Kick","description":"Bodyweight exercise for the core.","instructions":["To begin, lie down with your back pressed against the floor or on an exercise mat (optional). Your arms should be fully extended to the sides with your palms facing down. Note: The arms should be stationary the entire time.","With a slight bend at the knees, lift your legs up so that your heels are about 6 inches off the ground. This is the starting position.","Now lift your left leg up to about a 45 degree angle while your right leg is lowered until the heel is about 2-3 inches from the ground.","Switch movements by raising your right leg up and lowering your left leg. Remember to breathe while performing this exercise.","Repeat for the recommended amount of repetitions."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["scissor kick"],"media":[{"id":"scissor-kick-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Scissor_Kick/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"scissor-kick-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Scissor_Kick/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-scissors","slug":"scissors","name":"Scissors","description":"Bodyweight exercise for the core.","instructions":["Scissors is an abdominal exercise that strengthens the transverse abdominals, helping flatten your belly and strengthen your entire core. Scissors is not only a core strength move, but it is also a great stretch for your hamstrings and your lower back. Everyone is looking for new ways to work the core, to flatten the belly and to improve flexibility. If you learn how to do Scissors you will get everything rolled together in one move."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["scissors","schere"],"media":[],"source":"wger","de":{"name":"Schere","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Die Schere ist eine Bauchübung, die den queren Bauchmuskel (Transversus abdominis) stärkt und so hilft, den Bauch zu straffen und den gesamten Rumpf zu kräftigen. Die Schere ist nicht nur eine Kraftübung für den Rumpf, sondern auch eine hervorragende Dehnung für deine hintere Oberschenkelmuskulatur und deinen unteren Rücken. Jeder sucht nach neuen Wegen, den Rumpf zu trainieren, den Bauch zu straffen und die Beweglichkeit zu verbessern. Wenn du lernst, die Schere auszuführen, bekommst du all das in einer einzigen Übung vereint."]}},{"id":"ex-scissors-jump","slug":"scissors-jump","name":"Scissors Jump","description":"Bodyweight exercise for the quadriceps, with glutes, hamstrings assisting.","instructions":["Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.","Ensure that the front knee is over the midline of the foot. Extending through both legs, jump as high as possible, swinging your arms to gain lift.","As you jump as high as you can, switch the position of your legs, moving your front leg to the back and the rear leg to the front.","As you land, absorb the impact through the legs by adopting the lunge position, and repeat."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["scissors jump"],"media":[{"id":"scissors-jump-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Scissors_Jump/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"scissors-jump-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Scissors_Jump/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-scorpion-kick","slug":"scorpion-kick","name":"Scorpion Kick","description":"Bodyweight exercise for the back.","instructions":["Get into the push-up position with your shoulders directly above your hands and your feet hip-width apart.","Make sure that your body forms a straight line from your head to your heels.","Now pull your right knee towards your chest. While keeping your knee bent, lift your right leg as high as possible with your lower right leg pointing straight up.","Now rotate your hips so that your right foot swings over your left leg.","Continue to rotate and move your right foot towards the floor until you are forced to roll onto the outside of your left standing foot. Make sure that you do not rotate your upper body.","Now return to the starting position and repeat the exercise with your left leg."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["scorpion kick","skorpion-kick"],"media":[],"source":"wger","de":{"name":"Skorpion-Kick","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Geh in die Liegestützposition, deine Schultern befinden sich direkt über deinen Händen, deine Füße sind hüftbreit voneinander entfernt.","Achte darauf, dass dein Körper vom Kopf bis zu den Fersen eine gerade Linie bildet.","Nun zieh dein rechtes Knie Richtung Brust. Während das Knie gebeugt bleibt, hebst du dein rechtes Bein so weit wie möglich an, der rechte Unterschenkel zeigt gerade nach oben.","Drehe jetzt deine Hüfte, sodass dein rechter Fuß über dein linkes Bein schwingt. Rotiere weiter und bewege den rechten Fuß so weit Richtung Boden, bis du gezwungen bist, auf die Außenseite deines linken Standfußes zu rollen. Achte darauf, dass du den Oberkörper nicht mitdrehst.","Kehre nun in die Ausgangsposition zurück und wiederhole die Übung mit dem linken Bein."]}},{"id":"ex-seated-band-hamstring-curl","slug":"seated-band-hamstring-curl","name":"Seated Band Hamstring Curl","description":"Accessory exercise for the hamstrings.","instructions":["Secure a band close to the ground and place a bench a couple feet away from it.","Seat yourself on the bench and secure the band behind your ankles, beginning with your legs straight. This will be your starting position.","Flex the knees, bringing your feet towards the bench. You may need to lean back slightly to keep your feet from striking the floor.","Pause at the completion of the movement, and then slowly return to the starting position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["seated band hamstring curl"],"media":[{"id":"seated-band-hamstring-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Band_Hamstring_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-band-hamstring-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Band_Hamstring_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelrückseite.","instructions":null}},{"id":"ex-seated-barbell-military-press","slug":"seated-barbell-military-press","name":"Seated Barbell Military Press","description":"Barbell exercise for the shoulders, with triceps assisting.","instructions":["Sit on a Military Press Bench with a bar behind your head and either have a spotter give you the bar (better on the rotator cuff this way) or pick it up yourself carefully with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down.","Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.","Lower the bar down to the collarbone slowly as you inhale.","Lift the bar back up to the starting position as you exhale.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"BARBELL","tags":["seated barbell military press"],"media":[{"id":"seated-barbell-military-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Barbell_Military_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-barbell-military-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Barbell_Military_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-seated-barbell-twist","slug":"seated-barbell-twist","name":"Seated Barbell Twist","description":"Barbell exercise for the core.","instructions":["Start out by sitting at the end of a flat bench with a barbell placed on top of your thighs. Your feet should be shoulder width apart from each other.","Grip the bar with your palms facing down and make sure your hands are wider than shoulder width apart from each other. Begin to lift the barbell up over your head until your arms are fully extended.","Now lower the barbell behind your head until it is resting along the base of your neck. This is the starting position.","While keeping your feet and head stationary, move your waist from side to side so that your oblique muscles feel the contraction. Only move from side to side as far as your waist will allow you to go. Stretching or moving too far can cause an injury to occur. Tip: Use a slow and controlled motion.","Remember to breathe out while twisting your body to the side and in when moving back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["seated barbell twist"],"media":[{"id":"seated-barbell-twist-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Barbell_Twist/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-barbell-twist-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Barbell_Twist/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rumpf.","instructions":null}},{"id":"ex-seated-bench-press","slug":"seated-bench-press","name":"Seated Bench Press","description":"Bodyweight exercise for the chest.","instructions":["Set up the chest press machine so that the grips are aligned with your lower chest when you sit down. Make sure you're sitting with your back flat against the seat. Grab a handle in each hand, stick your chest out, and keep your head against the headrest. Breathe deeply and slowly push the handles forward until your arms are almost fully extended. Pause just before the lockout, then slowly return the handles to the starting position. Pause just before the handles come to a complete stop and perform another repetition."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["seated bench press","brustpresse im sitzen"],"media":[],"source":"wger","de":{"name":"Brustpresse im Sitzen","description":"Übung (Körpergewicht) für die Brust.","instructions":["Stelle die Brustpressmaschine so ein, dass die Griffe im Sitzen auf Höhe deiner unteren Brust sind. Achte darauf, dass dein Rücken flach an der Lehne anliegt. Greife in jede Hand einen Griff, schiebe die Brust heraus und halte den Kopf an der Kopfstütze. Atme tief ein und drücke die Griffe langsam nach vorne, bis deine Arme nahezu vollständig gestreckt sind. Halte kurz vor der vollständigen Streckung inne und führe die Griffe dann langsam in die Ausgangsposition zurück. Halte kurz inne, bevor die Griffe vollständig zur Ruhe kommen, und führe eine weitere Wiederholung aus."]}},{"id":"ex-seated-bent-over-one-arm-dumbbell-triceps-extension","slug":"seated-bent-over-one-arm-dumbbell-triceps-extension","name":"Seated Bent-Over One-Arm Dumbbell Triceps Extension","description":"Dumbbell exercise for the triceps.","instructions":["Sit down at the end of a flat bench with a dumbbell in one arm using a neutral grip (palms of the hand facing you).","Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up.","The upper arm with the dumbbell should be close to the torso and aligned with it (lifted up until it is parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights). Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.","Keeping the upper arm stationary, use the triceps to lift the weight as you exhale until the forearm is parallel to the floor and the whole arm is extended. Like many other arm exercises, only the forearm moves.","After a second contraction at the top, slowly lower the dumbbell back to the starting position as you inhale.","Repeat the movement for the prescribed amount of repetitions.","Switch arms and repeat the exercise."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["seated bent-over one-arm dumbbell triceps extension"],"media":[{"id":"seated-bent-over-one-arm-dumbbell-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-bent-over-one-arm-dumbbell-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Trizeps.","instructions":null}},{"id":"ex-seated-bent-over-two-arm-dumbbell-triceps-extension","slug":"seated-bent-over-two-arm-dumbbell-triceps-extension","name":"Seated Bent-Over Two-Arm Dumbbell Triceps Extension","description":"Dumbbell exercise for the triceps.","instructions":["Sit down at the end of a flat bench with a dumbbell in both arms using a neutral grip (palms of the hand facing you).","Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up.","The upper arms with the dumbbells should be close to the torso and aligned with it (lifted up until they are parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights). Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.","Keeping the upper arms stationary, use the triceps to lift the weight as you exhale until the forearms are parallel to the floor and the whole arm is extended. Like many other arm exercises, only the forearm moves.","After a second contraction at the top, slowly lower the dumbbells back to the starting position as you inhale.","Repeat the movement for the prescribed amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["seated bent-over two-arm dumbbell triceps extension"],"media":[{"id":"seated-bent-over-two-arm-dumbbell-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-bent-over-two-arm-dumbbell-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Trizeps.","instructions":null}},{"id":"ex-seated-biceps","slug":"seated-biceps","name":"Seated Biceps","description":"Bodyweight exercise for the biceps, with chest, shoulders assisting.","instructions":["Sit on the floor with your knees bent and your partner standing behind you. Extend your arms straight behind you with your palms facing each other. Your partner will hold your wrists for you. This will be the starting position.","Attempt to flex your elbows, while your partner prevents any actual movement.","After 10-20 seconds, relax your arms while your partner gently pulls your wrists up to stretch your biceps. Be sure to let your partner know when the stretch is appropriate to prevent injury or overstretching."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"BODYWEIGHT","tags":["seated biceps"],"media":[{"id":"seated-biceps-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Biceps/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-biceps-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Biceps/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Bizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-seated-cable-shoulder-press","slug":"seated-cable-shoulder-press","name":"Seated Cable Shoulder Press","description":"Cable exercise for the shoulders, with triceps assisting.","instructions":["Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 90 degrees to the body, with your head and chest up. The elbows should also be bent to about 90 degrees. This will be your starting position.","Begin by extending through the elbow, pressing the handles together above your head.","After pausing at the top, return the handles to the starting position. Ensure that you maintain tension on the cables.","You can also execute this movement with your back off the pad and alternate hands."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"CABLE","tags":["seated cable shoulder press"],"media":[{"id":"seated-cable-shoulder-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Shoulder_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-cable-shoulder-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Shoulder_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-seated-calf-stretch","slug":"seated-calf-stretch","name":"Seated Calf Stretch","description":"Equipment-free exercise for the calves, with hamstrings, back assisting.","instructions":["Sit up straight on an exercise mat.","Bend one knee and put that foot on the floor to stabilize the torso.","Straighten your other leg and flex your ankle.","Using a band, towel, or your hand if you can reach, pull the toes toward you. Hold for 10 to 20 seconds, then switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":["HAMSTRINGS","BACK"],"equipment":"NONE","tags":["seated calf stretch"],"media":[{"id":"seated-calf-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Calf_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-calf-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Calf_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Waden, unterstützt von Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-seated-close-grip-concentration-barbell-curl","slug":"seated-close-grip-concentration-barbell-curl","name":"Seated Close-Grip Concentration Barbell Curl","description":"Barbell exercise for the biceps.","instructions":["Sit down on a flat bench with a barbell or E-Z Bar in front of you in between your legs. Your legs should be spread with the knees bent and the feet on the floor.","Use your arms to pick the barbell up and place the back of your upper arms on top of your inner thighs (around three and a half inches away from the front of the knee). A supinated grip closer than shoulder width is needed to perform this exercise. Tip: Your arm should be extended at arms length and the barbell should be above the floor. This will be your starting position.","While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the barbell back to starting position as your breathe in. Tip: Avoid swinging motions at any time.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["seated close-grip concentration barbell curl"],"media":[{"id":"seated-close-grip-concentration-barbell-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Close-Grip_Concentration_Barbell_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-close-grip-concentration-barbell-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Close-Grip_Concentration_Barbell_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Bizeps.","instructions":null}},{"id":"ex-seated-corkscrew","slug":"seated-corkscrew","name":"Seated Corkscrew","description":"Bodyweight exercise for the core.","instructions":["do this abs and obliques exercise, start with your hands back behind your body","and bring your knees in and across, really trying to contract the obliques.","Then extend your legs back out to starting position and repeat toward the","opposite side of the abs.","Beginners","might find that they can’t even get through the first 45 seconds of this","challenging reverse crunches variation.  That’s ok because it gives you a","place to start and something to improve upon."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["seated corkscrew","sitzender korkenzieher"],"media":[],"source":"wger","de":{"name":"Sitzender Korkenzieher","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["diese Übung für Bauch- und seitliche Bauchmuskulatur auszuführen, beginne mit den Händen hinter deinem Körper","und ziehe deine Knie heran und quer hinüber, wobei du wirklich versuchst, die seitliche Bauchmuskulatur","anzuspannen. Strecke dann deine Beine wieder in die Ausgangsposition aus und wiederhole zur","gegenüberliegenden Seite der Bauchmuskulatur.","Anfänger","stellen vielleicht fest, dass sie nicht einmal die ersten 45 Sekunden dieser","anspruchsvollen Variante des umgekehrten Crunches durchhalten. Das ist in Ordnung, denn es gibt dir einen","Punkt, an dem du anfangen kannst, und etwas, woran du dich verbessern kannst."]}},{"id":"ex-seated-dumbbell-inner-biceps-curl","slug":"seated-dumbbell-inner-biceps-curl","name":"Seated Dumbbell Inner Biceps Curl","description":"Dumbbell exercise for the biceps.","instructions":["Sit on the end of a flat bench with a dumbbell in each hand being held at arms length. The elbows should be close to the torso.","Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position.","While holding the upper arms stationary, curl the dumbbells out and up, turning the palms out as you lift and keeping your forearms in line with your outer deltoids. Tips:","Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the dumbbells back to the starting position as your breathe in. Remember to rotate your arms as you lower the dumbbells so that you can switch back to a neutral grip.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["seated dumbbell inner biceps curl"],"media":[{"id":"seated-dumbbell-inner-biceps-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Dumbbell_Inner_Biceps_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-dumbbell-inner-biceps-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Dumbbell_Inner_Biceps_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps.","instructions":null}},{"id":"ex-seated-dumbbell-palms-down-wrist-curl","slug":"seated-dumbbell-palms-down-wrist-curl","name":"Seated Dumbbell Palms-Down Wrist Curl","description":"Dumbbell exercise for the forearms.","instructions":["Start out by placing two dumbbells on the floor in front of a flat bench.","Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor.","Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing down. Your wrists should be hanging over the edge of your thighs.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise. Tip: Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions.","When finished, simply lower the dumbbells to the floor."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["seated dumbbell palms-down wrist curl"],"media":[{"id":"seated-dumbbell-palms-down-wrist-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Dumbbell_Palms-Down_Wrist_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-dumbbell-palms-down-wrist-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Dumbbell_Palms-Down_Wrist_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Unterarme.","instructions":null}},{"id":"ex-seated-dumbbell-palms-up-wrist-curl","slug":"seated-dumbbell-palms-up-wrist-curl","name":"Seated Dumbbell Palms-Up Wrist Curl","description":"Dumbbell exercise for the forearms.","instructions":["Start out by placing two dumbbells on the floor in front of a flat bench.","Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor.","Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing up. Your wrists should be hanging over the edge of your thighs.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise. Tip: Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions.","When finished, simply lower the dumbbells to the floor."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["seated dumbbell palms-up wrist curl"],"media":[{"id":"seated-dumbbell-palms-up-wrist-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Dumbbell_Palms-Up_Wrist_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-dumbbell-palms-up-wrist-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Dumbbell_Palms-Up_Wrist_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Unterarme.","instructions":null}},{"id":"ex-seated-dumbbell-press","slug":"seated-dumbbell-press","name":"Seated Dumbbell Press","description":"Dumbbell exercise for the shoulders, with triceps assisting.","instructions":["Grab a couple of dumbbells and sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs.","Clean the dumbbells up one at a time by using your thighs to bring the dumbbells up to shoulder height at each side.","Rotate the wrists so that the palms of your hands are facing forward. This is your starting position.","As you exhale, push the dumbbells up until they touch at the top.","After a second pause, slowly come down back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"DUMBBELL","tags":["seated dumbbell press"],"media":[{"id":"seated-dumbbell-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Dumbbell_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-dumbbell-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Dumbbell_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-seated-figure-four","slug":"seated-figure-four","name":"seated figure four","description":"Bodyweight exercise for the glutes.","instructions":["Seat on  a bench. Feet flat on the ground. Place your left ankle over your right knee. Your right knee stays flat. Keep your back straight. Gently push your left knee down."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["seated figure four","figur-vier-dehnung im sitzen"],"media":[],"source":"wger","de":{"name":"Figur-Vier-Dehnung im Sitzen","description":"Übung (Körpergewicht) für den Po.","instructions":["Setze dich auf eine Bank. Die Füße flach auf dem Boden. Lege deinen linken Knöchel über dein rechtes Knie. Dein rechtes Knie bleibt flach. Halte deinen Rücken gerade. Drücke dein linkes Knie sanft nach unten."]}},{"id":"ex-seated-flat-bench-leg-pull-in","slug":"seated-flat-bench-leg-pull-in","name":"Seated Flat Bench Leg Pull-In","description":"Bodyweight exercise for the core.","instructions":["Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.","Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement.","After a second pause, go back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["seated flat bench leg pull-in"],"media":[{"id":"seated-flat-bench-leg-pull-in-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Flat_Bench_Leg_Pull-In/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-flat-bench-leg-pull-in-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Flat_Bench_Leg_Pull-In/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-seated-front-deltoid","slug":"seated-front-deltoid","name":"Seated Front Deltoid","description":"Bodyweight exercise for the shoulders, with chest assisting.","instructions":["Sit upright on the floor with your legs bent, your partner standing behind you. Stick your arms straight out to your sides, with your palms facing the ground. Attempt to move them as far behind you as possible, as your assistant holds your wrists. This will be your starting position.","Keeping your elbows straight, attempt to move your arms to the front, with your partner gently restraining you to prevent any actual movement for 10-20 seconds.","Now, relax your muscles and allow your partner to gently increase the stretch on the shoulders and chest. Hold for 10 to 20 seconds."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CHEST"],"equipment":"BODYWEIGHT","tags":["seated front deltoid"],"media":[{"id":"seated-front-deltoid-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Front_Deltoid/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-front-deltoid-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Front_Deltoid/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Schultern, unterstützt von Brust.","instructions":null}},{"id":"ex-seated-glute","slug":"seated-glute","name":"Seated Glute","description":"Bodyweight exercise for the glutes, with quadriceps assisting.","instructions":["In a seated position with your knees bent, cross one ankle over the opposite knee. Your partner will stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position.","Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso.","Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["QUADRICEPS"],"equipment":"BODYWEIGHT","tags":["seated glute"],"media":[{"id":"seated-glute-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Glute/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-glute-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Glute/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelvorderseite.","instructions":null}},{"id":"ex-seated-good-mornings","slug":"seated-good-mornings","name":"Seated Good Mornings","description":"Barbell exercise for the back, with glutes assisting.","instructions":["Set up a box in a power rack. The pins should be set at an appropriate height. Begin by stepping under the bar and placing it across the back of the shoulders, not on top of your traps. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders.","Remove the bar from the rack, creating a tight arch in your lower back. Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. This will be your starting position.","Keeping the bar tight, bend forward at the hips as much as possible. If you set the pins to what would be parallel, you not only have a safety if you fail, but know when to stop.","Pause just above the pins and reverse the motion until your torso it upright."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["GLUTES"],"equipment":"BARBELL","tags":["seated good mornings"],"media":[{"id":"seated-good-mornings-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Good_Mornings/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-good-mornings-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Good_Mornings/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Po.","instructions":null}},{"id":"ex-seated-hamstring","slug":"seated-hamstring","name":"Seated Hamstring","description":"Equipment-free exercise for the hamstrings, with calves assisting.","instructions":["In a seated position with your legs extended, have your partner stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position.","Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso.","Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES"],"equipment":"NONE","tags":["seated hamstring"],"media":[{"id":"seated-hamstring-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Hamstring/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-hamstring-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Hamstring/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelrückseite, unterstützt von Waden.","instructions":null}},{"id":"ex-seated-hamstring-and-calf-stretch","slug":"seated-hamstring-and-calf-stretch","name":"Seated Hamstring and Calf Stretch","description":"Accessory exercise for the hamstrings, with calves assisting.","instructions":["Loop a belt, rope, or band around one foot. Sit down with both legs extended . This will be your starting position.","Leaning forward slightly, pull on the belt to draw the toes of your foot back. Hold this position for 10-20 seconds and then repeat with the other leg."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES"],"equipment":"OTHER","tags":["seated hamstring and calf stretch"],"media":[{"id":"seated-hamstring-and-calf-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Hamstring_and_Calf_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-hamstring-and-calf-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Hamstring_and_Calf_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelrückseite, unterstützt von Waden.","instructions":null}},{"id":"ex-seated-head-harness-neck-resistance","slug":"seated-head-harness-neck-resistance","name":"Seated Head Harness Neck Resistance","description":"Accessory exercise for the shoulders.","instructions":["Place a neck strap on the floor at the end of a flat bench. Once you have selected the weights, sit at the end of the flat bench with your feet wider than shoulder width apart from each other. Your toes should be pointed out.","Slowly move your torso forward until it is almost parallel with the floor. Using both hands, securely position the neck strap around your head. Tip: Make sure the weights are still lying on the floor to prevent any strain on the neck. Now grab the weight with both hands while elevating your torso back until it is almost perpendicular to the floor. Note: Your head and torso needs to be slightly tilted forward to perform this exercise.","Now place both hands on top of your knees. This is the starting position.","Slowly lower your neck down until your chin touches the upper part of your chest while breathing in.","While exhaling, bring your neck back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["seated head harness neck resistance"],"media":[{"id":"seated-head-harness-neck-resistance-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Head_Harness_Neck_Resistance/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-head-harness-neck-resistance-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Head_Harness_Neck_Resistance/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Schultern.","instructions":null}},{"id":"ex-seated-hip-abduction","slug":"seated-hip-abduction","name":"Seated Hip Abduction","description":"Bodyweight exercise for the glutes.","instructions":["Starting Position:","Adjust the seat height so that your knees are aligned with the pivot point of the machine.","Sit with your back flat against the backrest, maintaining good posture.","Place the outside of your thighs against the machine's padded levers.","Position your feet flat on the footrests or platform of the machine.","Grasp the handles or sides of the seat for stability.","Ensure your spine is neutral and your core is slightly engaged.","Movement:"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["seated hip abduction","hüftabduktion sitzend"],"media":[],"source":"wger","de":{"name":"Hüftabduktion sitzend","description":"Übung (Körpergewicht) für den Po.","instructions":["Ausgangsposition:","Stelle die Sitzhöhe so ein, dass deine Knie auf einer Linie mit dem Drehpunkt der Maschine liegen.","Setze dich mit dem Rücken flach an die Rückenlehne und behalte eine gute Haltung bei.","Lege die Außenseite deiner Oberschenkel gegen die gepolsterten Hebel der Maschine.","Stelle deine Füße flach auf die Fußstützen oder die Plattform der Maschine.","Greife die Griffe oder die Seiten des Sitzes für mehr Stabilität.","Achte darauf, dass deine Wirbelsäule neutral ist und dein Rumpf leicht angespannt ist.","Bewegung:"]}},{"id":"ex-seated-hip-adduction","slug":"seated-hip-adduction","name":"Seated Hip Adduction","description":"Machine exercise for the glutes.","instructions":["Starting Position: Sit on the machine with your knees inward and against the pads. Pull the pin to release the pads. Grab the handles on the sides.b"],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["seated hip adduction","adduktoren-maschine"],"media":[{"id":"seated-hip-adduction-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/12/4a42cc6f-648d-40cc-a72a-c49dd47e1667.webp","caption":"Seated Hip Adduction","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Adduktoren-Maschine","description":"Übung (Maschine) für den Po.","instructions":["in eine aufrechte Position setzen, bei der die Beine hüftbreit geöffnet sind","den Rücken, die Knie und die Oberschenkelaußenseite an die jeweiligen Polster pressen","mit den Händen an den Griffen festhalten","die Oberschenkel bis zum Anschlagpunkt der Hebelarme auseinander drücken","danach die Beine wieder zusammen führen","das Gesäß nicht vom Sitz abheben","beim Auseinanderdrücken der Hebelarme aus- und beim Zusammenführen einatmen"]}},{"id":"ex-seated-leg-tucks","slug":"seated-leg-tucks","name":"Seated Leg Tucks","description":"Bodyweight exercise for the core.","instructions":["Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.","Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement.","After a second pause, go back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["seated leg tucks"],"media":[{"id":"seated-leg-tucks-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Leg_Tucks/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-leg-tucks-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Leg_Tucks/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-seated-one-arm-dumbbell-palms-down-wrist-curl","slug":"seated-one-arm-dumbbell-palms-down-wrist-curl","name":"Seated One-Arm Dumbbell Palms-Down Wrist Curl","description":"Dumbbell exercise for the forearms.","instructions":["Sit on a flat bench with a dumbbell in your right hand.","Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.","Lean forward and place your right forearm on top of your upper right thigh with your palm down. Tip: Make sure that the back of the wrist lies on top of your knees. This will be your starting position.","Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell. Inhale as you perform this movement.","Now curl the dumbbell as high as possible as you contract the forearms and as you exhale. Keep the contraction for a second before you lower again. Tip: The only movement should happen at the wrist.","Perform for the recommended amount of repetitions, switch arms and repeat the movement."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["seated one-arm dumbbell palms-down wrist curl"],"media":[{"id":"seated-one-arm-dumbbell-palms-down-wrist-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-one-arm-dumbbell-palms-down-wrist-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Unterarme.","instructions":null}},{"id":"ex-seated-one-arm-dumbbell-palms-up-wrist-curl","slug":"seated-one-arm-dumbbell-palms-up-wrist-curl","name":"Seated One-Arm Dumbbell Palms-Up Wrist Curl","description":"Dumbbell exercise for the forearms.","instructions":["Sit on a flat bench with a dumbbell in your right hand.","Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.","Lean forward and place your right forearm on top of your upper right thigh with your palm up. Tip: Make sure that the front of the wrist lies on top of your knees. This will be your starting position.","Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell. Inhale as you perform this movement.","Now curl the dumbbell as high as possible as you contract the forearms and as you exhale. Keep the contraction for a second before you lower again. Tip: The only movement should happen at the wrist.","Perform for the recommended amount of repetitions, switch arms and repeat the movement."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["seated one-arm dumbbell palms-up wrist curl"],"media":[{"id":"seated-one-arm-dumbbell-palms-up-wrist-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-one-arm-dumbbell-palms-up-wrist-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Unterarme.","instructions":null}},{"id":"ex-seated-overhead-stretch","slug":"seated-overhead-stretch","name":"Seated Overhead Stretch","description":"Equipment-free exercise for the core.","instructions":["Sit up straight on an exercise mat.","Touch the soles of your feet together with your feet six to eight inches in front of your hips.","Place one hand on the floor beside you and your other hand behind your head.","Lift your elbow to the ceiling as you incline your torso to the other side. Hold for 10 to 20 seconds, then switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"NONE","tags":["seated overhead stretch"],"media":[{"id":"seated-overhead-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Overhead_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-overhead-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Overhead_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Rumpf.","instructions":null}},{"id":"ex-seated-palm-up-barbell-wrist-curl","slug":"seated-palm-up-barbell-wrist-curl","name":"Seated Palm-Up Barbell Wrist Curl","description":"Barbell exercise for the forearms.","instructions":["Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.","Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.","Lean forward and place your forearms on top of your upper thighs with your palms up. Tip: Make sure that the front of the wrists lay on top of your knees. This will be your starting position.","Lower the bar as far as possible while inhaling and keeping a tight grip.","Now curl bar up as high as possible while flexing the forearms and exhaling. Hold the contraction at the top for a second and Tip: Only the wrist should move."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["seated palm-up barbell wrist curl"],"media":[{"id":"seated-palm-up-barbell-wrist-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Palm-Up_Barbell_Wrist_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-palm-up-barbell-wrist-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Palm-Up_Barbell_Wrist_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Unterarme.","instructions":null}},{"id":"ex-seated-palms-down-barbell-wrist-curl","slug":"seated-palms-down-barbell-wrist-curl","name":"Seated Palms-Down Barbell Wrist Curl","description":"Barbell exercise for the forearms.","instructions":["Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width.","Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.","Lean forward and place your forearms on top of your upper thighs with your palms down. Tip: Make sure that the back of the wrists lay on top of your knees. This will be your starting position.","Lower the bar as far as possible while inhaling and keeping a tight grip.","Now curl bar up as high as possible while flexing the forearms and exhaling. Hold the contraction at the top for a second and Tip: Only the wrist should move."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["seated palms-down barbell wrist curl"],"media":[{"id":"seated-palms-down-barbell-wrist-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Palms-Down_Barbell_Wrist_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-palms-down-barbell-wrist-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Palms-Down_Barbell_Wrist_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Unterarme.","instructions":null}},{"id":"ex-seated-piriformis-stretch","slug":"seated-piriformis-stretch","name":"Seated Piriformis Stretch","description":"Bodyweight exercise for the quadriceps.","instructions":["Seated Piriformis Stretch","Part of: Limber 11","Source: Joe DeFranco","Prescription: 20-30 sec each side","Type: static","Includes isometric hold."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["seated piriformis stretch","sitzende piriformis-dehnung"],"media":[],"source":"wger","de":{"name":"Sitzende Piriformis-Dehnung","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite.","instructions":["Sitzende Piriformis-Dehnung","Teil von: Limber 11","Quelle: Joe DeFranco","Vorgabe: 20-30 Sek pro Seite","Typ: statisch","Beinhaltet isometrisches Halten."]}},{"id":"ex-seated-row-machine","slug":"seated-row-machine","name":"Seated Row (Machine)","description":"Machine exercise for the back, with shoulders assisting.","instructions":["Keep your chest up and squeeze your shoulder blades at the end.","Don’t hunch forward or round your back during the pull."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["SHOULDERS"],"equipment":"MACHINE","tags":["seated row (machine)","rudern im sitzen (maschine)"],"media":[{"id":"seated-row-machine-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1725/f0ebd44e-b8e1-400c-b598-ca371f3a07af.png","caption":"Seated Row (Machine)","attribution":"wger.de · barry","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Rudern im Sitzen (Maschine)","description":"Übung (Maschine) für den Rücken, unterstützt von Schultern.","instructions":["Halte deinen Brustkorb aufrecht und ziehe am Ende die Schulterblätter zusammen.","Krümme dich nicht nach vorn und mache während des Zugs keinen runden Rücken."]}},{"id":"ex-seated-shoulder-extension-stretch","slug":"seated-shoulder-extension-stretch","name":"Seated Shoulder Extension Stretch","description":"Bodyweight exercise for the back, with chest assisting.","instructions":["Sit with your hands behind you, shoulder width apart.","Lock your elbows.","Scoot your feet and hips out forwards, lowering your shoulders down towards ground.","Go as far as possible to obtain a good stretch.","See the video: https://www.youtube.com/watch?v=ihUAbG0e8zw"],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["CHEST"],"equipment":"BODYWEIGHT","tags":["seated shoulder extension stretch","sitzende schulterextensions-dehnung"],"media":[],"source":"wger","de":{"name":"Sitzende Schulterextensions-Dehnung","description":"Übung (Körpergewicht) für den Rücken, unterstützt von Brust.","instructions":["Setze dich mit den Händen hinter dir hin, schulterbreit auseinander.","Strecke deine Ellenbogen durch.","Schiebe deine Füße und Hüften nach vorne und senke deine Schultern zum Boden ab.","Gehe so weit wie möglich, um eine gute Dehnung zu erreichen.","Siehe das Video: https://www.youtube.com/watch?v=ihUAbG0e8zw"]}},{"id":"ex-seated-side-lateral-raise","slug":"seated-side-lateral-raise","name":"Seated Side Lateral Raise","description":"Dumbbell exercise for the shoulders.","instructions":["Pick a couple of dumbbells and sit at the end of a flat bench with your feet firmly on the floor. Hold the dumbbells with your palms facing in and your arms straight down at your sides at arms' length. This will be your starting position.","While maintaining the torso stationary (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.","Lower the dumbbells back down slowly to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["seated side lateral raise"],"media":[{"id":"seated-side-lateral-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Side_Lateral_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-side-lateral-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Side_Lateral_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern.","instructions":null}},{"id":"ex-seated-triceps-press","slug":"seated-triceps-press","name":"Seated Triceps Press","description":"Dumbbell exercise for the triceps.","instructions":["Sit down on a back (better with back support). Take a dumbbell firmly with both hands and hold it with extended arms over your head. With your palms facing upward and holding the weight of the dumbbell, slowly lower the weight behind your head."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["seated triceps press","trizepsdrücken im sitzen"],"media":[],"source":"wger","de":{"name":"Trizepsdrücken im Sitzen","description":"Übung (Kurzhantel) für den Trizeps.","instructions":["Setze dich auf eine Bank (besser mit Rückenstütze). Nimm eine Kurzhantel fest mit beiden Händen und halte sie mit gestreckten Armen über deinem Kopf. Mit nach oben gerichteten Handflächen, die das Gewicht der Kurzhantel halten, senkst du das Gewicht langsam hinter deinen Kopf ab."]}},{"id":"ex-seated-two-arm-palms-up-low-pulley-wrist-curl","slug":"seated-two-arm-palms-up-low-pulley-wrist-curl","name":"Seated Two-Arm Palms-Up Low-Pulley Wrist Curl","description":"Cable exercise for the forearms.","instructions":["Put a bench in front of a low pulley machine that has a barbell or EZ Curl attachment on it.","Move the bench far enough away so that when you bring the handle to the top of your thighs tension is created on the cable due to the weight stack being moved up.","Now hold the handle with both hands, palms up, using a shoulder-width grip.","Step back and sit on the bench with your feet about shoulder width apart, firmly on the floor.","Lean forward and place the forearms on your thighs with the back of your wrists over your knees. This will be your starting position.","Lower the bar as far as possible, while inhaling and keeping a tight grip.","Now curl the bar up as high as possible while contracting the forearms. Tip: Only the wrist should move; not the forearms.","After a second contraction at the top go back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["seated two-arm palms-up low-pulley wrist curl"],"media":[{"id":"seated-two-arm-palms-up-low-pulley-wrist-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"seated-two-arm-palms-up-low-pulley-wrist-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Unterarme.","instructions":null}},{"id":"ex-seated-v-grip-row","slug":"seated-v-grip-row","name":"Seated V-Grip Row","description":"Cable exercise for the back, with shoulders, biceps, core, chest assisting.","instructions":["The Seated V-Grip Row is a compound pulling exercise performed on a cable machine using a close-grip \"V\" handle. While seated with your feet braced, you pull the handle toward your midsection, focusing on back thickness and mid-back development."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["SHOULDERS","BICEPS","ABS_CORE","CHEST"],"equipment":"CABLE","tags":["seated v-grip row","sitzendes rudern mit v-griff"],"media":[],"source":"wger","de":{"name":"Sitzendes Rudern mit V-Griff","description":"Übung (Kabelzug) für den Rücken, unterstützt von Schultern, Bizeps, Rumpf, Brust.","instructions":["Das sitzende Rudern mit V-Griff ist eine mehrgelenkige Zugübung, die am Kabelzug mit einem engen \"V\"-Griff ausgeführt wird. Während du sitzt und die Füße abstützt, ziehst du den Griff zu deiner Körpermitte und konzentrierst dich auf die Rückendicke und die Entwicklung des mittleren Rückens."]}},{"id":"ex-seated-w-curl","slug":"seated-w-curl","name":"Seated W Curl","description":"Dumbbell exercise for the biceps.","instructions":["Sit on bench with 60° incline","Hold dumbbells beside body near the ground, palms facing outwards, arms fully extended","Move dumbbells up using only biceps and without momentum"],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["seated w curl","sitzender w-curl"],"media":[{"id":"seated-w-curl-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1448/2184e68c-32b5-413f-a7c1-4a2d1bb98c35.png","caption":"Seated W Curl","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Sitzender W-Curl","description":"Übung (Kurzhantel) für den Bizeps.","instructions":["Setze dich auf eine Bank mit 60° Neigung","Halte die Kurzhanteln seitlich am Körper nahe am Boden, Handflächen nach außen, Arme vollständig gestreckt","Bewege die Kurzhanteln nur mit dem Bizeps und ohne Schwung nach oben"]}},{"id":"ex-see-saw-press-alternating-side-press","slug":"see-saw-press-alternating-side-press","name":"See-Saw Press (Alternating Side Press)","description":"Dumbbell exercise for the shoulders, with core, triceps assisting.","instructions":["Grab a dumbbell with each hand and stand up erect.","Clean (lift) the dumbbells to the chest/shoulder level and then rotate your wrists so that your palms are facing towards you as if you were getting ready to perform an Arnold Press. This will be your starting position.","Now start extending your left arm overhead as you rotate the wrist so that the palm of your hand faces forward as you go up. Your elbows should come out also as you lift the weight. Simultaneously, you will also be bending from your hip to your opposite side. Tip: If you perform the exercise correctly, is should look as if you are trying to reach for something overhead on the right hand side of your body, but with your left arm. Breathe out as you perform this movement.","Once you reach the top position breathe in. Then, with the weight fully extended overhead and you bent over to your right hand side, begin the movement to the left side.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["ABS_CORE","TRICEPS"],"equipment":"DUMBBELL","tags":["see-saw press (alternating side press)"],"media":[{"id":"see-saw-press-alternating-side-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/See-Saw_Press_Alternating_Side_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"see-saw-press-alternating-side-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/See-Saw_Press_Alternating_Side_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern, unterstützt von Rumpf, Trizeps.","instructions":null}},{"id":"ex-shinbox-ir-stretch","slug":"shinbox-ir-stretch","name":"Shinbox IR Stretch","description":"Bodyweight exercise for the glutes, with core assisting.","instructions":["Starting Position: Sit on the floor with both hips and knees bent at 90-degree angles.","Leg Placement:","Place one leg in front of you (external rotation) and the other leg out","to the side/behind you (internal rotation). The shins and knees should","remain flat on the ground.","The Movement:","Keeping your hips square, hinge your torso forward or tilt it laterally","(side-to-side) toward the front leg to deepen the stretch."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["ABS_CORE"],"equipment":"BODYWEIGHT","tags":["shinbox ir stretch","shinbox-innenrotations-dehnung"],"media":[],"source":"wger","de":{"name":"Shinbox-Innenrotations-Dehnung","description":"Übung (Körpergewicht) für den Po, unterstützt von Rumpf.","instructions":["Ausgangsposition: Setze dich auf den Boden, mit Hüften und Knien im 90-Grad-Winkel gebeugt.","Beinstellung:","Lege ein Bein vor dich (Außenrotation) und das andere Bein zur Seite","bzw. hinter dich (Innenrotation). Die Unterschenkel und Knie sollten","flach auf dem Boden bleiben.","Die Bewegung:","Halte deine Hüften gerade und beuge deinen Oberkörper nach vorne oder neige ihn seitlich","(von Seite zu Seite) in Richtung des vorderen Beins, um die Dehnung zu vertiefen."]}},{"id":"ex-shotgun-row","slug":"shotgun-row","name":"Shotgun Row","description":"Cable exercise for the back, with biceps assisting.","instructions":["Attach a single handle to a low cable.","After selecting the correct weight, stand a couple feet back with a wide-split stance. Your arm should be extended and your shoulder forward. This will be your starting position.","Perform the movement by retracting the shoulder and flexing the elbow. As you pull, supinate the wrist, turning the palm upward as you go.","After a brief pause, return to the starting position."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"CABLE","tags":["shotgun row"],"media":[{"id":"shotgun-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Shotgun_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"shotgun-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Shotgun_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Shotgun Row","description":"Übung (Kabelzug) für den Rücken, unterstützt von Bizeps.","instructions":["Befestige einen einzelnen Griff an einem niedrigen Kabelzug.","Stelle dich nach Auswahl des richtigen Gewichts ein paar Schritte zurück in einen weiten Ausfallschritt-Stand. Dein Arm sollte gestreckt und deine Schulter nach vorne gerichtet sein. Dies ist deine Ausgangsposition.","Führe die Bewegung aus, indem du die Schulter zurückziehst und den Ellenbogen beugst. Während du ziehst, supiniere das Handgelenk und drehe dabei die Handfläche nach oben.","Kehre nach einer kurzen Pause in die Ausgangsposition zurück."]}},{"id":"ex-shoulder-circles","slug":"shoulder-circles","name":"Shoulder Circles","description":"Equipment-free exercise for the shoulders, with back assisting.","instructions":["With shoulders relaxed and arms resting loosely at your sides (or in your lap if you're seated), gently roll your shoulders forward, up, back, and down.","Reverse direction. You can do this exercise alternating shoulders or both at the same time."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"NONE","tags":["shoulder circles"],"media":[{"id":"shoulder-circles-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Shoulder_Circles/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"shoulder-circles-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Shoulder_Circles/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Schultern, unterstützt von Rücken.","instructions":null}},{"id":"ex-shoulder-dislocates","slug":"shoulder-dislocates","name":"Shoulder dislocates","description":"Bodyweight exercise for the shoulders.","instructions":["Starting position:","Stand up with your back straight and a resistance band, towel, or broomstick handle in hand. With your hands straight in front of your body and the band between your hands, push your hands apart to both be at around 45 degrees from your body, thumbs facing down. If using a towel or broomstick handle instead, grab it with an overhand grip.","Steps:","Keeping your arms outstretched, rotate at the shoulders to bring your arms overhead and then down toward your glutes.","Rotate at the shoulders in the opposite direction — overhead and then toward your groin.","Repeat."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["shoulder dislocates","schulterdislokationen"],"media":[],"source":"wger","de":{"name":"Schulterdislokationen","description":"Übung (Körpergewicht) für die Schultern.","instructions":["Ausgangsposition:","Stelle dich mit geradem Rücken hin und nimm ein Widerstandsband, ein Handtuch oder einen Besenstiel in die Hände. Halte die Hände gerade vor deinem Körper, das Band zwischen den Händen, und schiebe deine Hände auseinander, sodass beide etwa 45 Grad von deinem Körper entfernt sind, die Daumen nach unten zeigend. Wenn du stattdessen ein Handtuch oder einen Besenstiel verwendest, greife es im Obergriff.","Ablauf:","Halte deine Arme gestreckt und rotiere in den Schultern, um deine Arme über den Kopf und dann nach unten in Richtung deiner Gesäßmuskulatur zu führen.","Rotiere in den Schultern in die entgegengesetzte Richtung – über den Kopf und dann in Richtung deiner Leiste.","Wiederhole."]}},{"id":"ex-shoulder-dumbbell-pendular-exercise","slug":"shoulder-dumbbell-pendular-exercise","name":"Shoulder Dumbbell Pendular Exercise","description":"Dumbbell exercise for the shoulders, with back, chest assisting.","instructions":["Lean forward to rest your hand on a chair or other object, holding a dumbbell in the other hand","Gently swing the dumbbell in a circular motion"],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK","CHEST"],"equipment":"DUMBBELL","tags":["shoulder dumbbell pendular exercise","pendelübung für die schulter mit kurzhantel"],"media":[],"source":"wger","de":{"name":"Pendelübung für die Schulter mit Kurzhantel","description":"Übung (Kurzhantel) für die Schultern, unterstützt von Rücken, Brust.","instructions":["Beuge dich nach vorne und stütze eine Hand auf einem Stuhl oder einem anderen Gegenstand ab, während du in der anderen Hand eine Kurzhantel hältst.","Schwinge die Kurzhantel sanft in kreisenden Bewegungen."]}},{"id":"ex-shoulder-press-barbell","slug":"shoulder-press-barbell","name":"Shoulder Press, Barbell","description":"Barbell exercise for the shoulders.","instructions":["Sit on a bench, the back rest should be almost vertical. Take a barbell with a shoulder wide grip and bring it up to chest height. Press the weight up, but don't stretch the arms completely. Go slowly down and repeat."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["shoulder press, barbell","schulterdrücken"],"media":[{"id":"shoulder-press-barbell-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/119/seated-barbell-shoulder-press-large-1.png","caption":"Shoulder Press, Barbell","attribution":"wger.de · Everkinetic","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Schulterdrücken","description":"Übung (Langhantel) für die Schultern.","instructions":["Schulterdrücken im Sitzen mit der Langhantel"]}},{"id":"ex-shoulder-press-on-multi-press","slug":"shoulder-press-on-multi-press","name":"Shoulder Press, on Multi Press","description":"Bodyweight exercise for the shoulders.","instructions":["The exercise is basically the same as with a free barbell:","Sit on a bench, the back rest should be almost vertical. Take a bar with a shoulder wide grip and bring it down to chest height. Press the weight up, but don't stretch the arms completely. Go slowly down and repeat."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["shoulder press, on multi press","frontdrücken mp"],"media":[],"source":"wger","de":{"name":"Frontdrücken MP","description":"Übung (Körpergewicht) für die Schultern.","instructions":["Selbe Durchführung wie mit der Langhantel. Setze dich auf eine Bank, stelle die Lehne fast Senkrecht ein. Greife die Stange etwas mehr als Schulterbreit und hebe sie auf Brusthöhe. Drücke sie nun nach oben, strecke die Arme aber nicht vollständig aus. Bringe das Gewicht langsam wieder runter, bis sie wie beim Bankdrücken die Brust kurz berührt."]}},{"id":"ex-shoulder-press-with-bands","slug":"shoulder-press-with-bands","name":"Shoulder Press - With Bands","description":"Resistance band exercise for the shoulders, with triceps assisting.","instructions":["To begin, stand on an exercise band so that tension begins at arm's length. Grasp the handles and lift them so that the hands are at shoulder height at each side.","Rotate the wrists so that the palms of your hands are facing forward. Your elbows should be bent, with the upper arms and forearms in line to the torso. This is your starting position.","As you exhale, lift the handles up until your arms are fully extended overhead."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"BAND","tags":["shoulder press - with bands"],"media":[{"id":"shoulder-press-with-bands-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Shoulder_Press_-_With_Bands/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"shoulder-press-with-bands-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Shoulder_Press_-_With_Bands/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Widerstandsband) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-shoulder-raise","slug":"shoulder-raise","name":"Shoulder Raise","description":"Equipment-free exercise for the shoulders, with back assisting.","instructions":["Relax your arms to your sides and raise your shoulders up toward your ears, then back down."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"NONE","tags":["shoulder raise"],"media":[{"id":"shoulder-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Shoulder_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"shoulder-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Shoulder_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Schultern, unterstützt von Rücken.","instructions":null}},{"id":"ex-shoulder-raise-side-and-front-db","slug":"shoulder-raise-side-and-front-db","name":"Shoulder Raise Side and Front DB","description":"Dumbbell exercise for the shoulders.","instructions":["Stand while holding dumbbells beside body","Keep arms almost fully extended","Without momentum raise dumbbells to the side of your body until shoulder height, palms facing down","Lower dumbbells beside body, palms facing inwards","Immediately raise dumbbells in front of your body until shoulder height, palms facing down","Down again","This is one repetition"],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["shoulder raise side and front db","seitheben und frontheben mit kurzhanteln"],"media":[],"source":"wger","de":{"name":"Seitheben und Frontheben mit Kurzhanteln","description":"Übung (Kurzhantel) für die Schultern.","instructions":["Stehe aufrecht und halte die Kurzhanteln seitlich am Körper","Halte die Arme nahezu vollständig gestreckt","Hebe die Kurzhanteln ohne Schwung seitlich bis auf Schulterhöhe an, Handflächen nach unten","Senke die Kurzhanteln seitlich am Körper ab, Handflächen nach innen","Hebe die Kurzhanteln sofort vor dem Körper bis auf Schulterhöhe an, Handflächen nach unten","Wieder absenken","Das ist eine Wiederholung"]}},{"id":"ex-shoulder-shrug","slug":"shoulder-shrug","name":"Shoulder Shrug","description":"Bodyweight exercise for the back.","instructions":["The shoulder shrug (usually called simply the shrug) is an exercise in weight training used to develop the upper trapezius muscle. The lifter stands erect, hands about shoulder width apart, and raises the shoulders as high as possible, and then lowers them, while not bending the elbows, or moving the body at all. The lifter may not have as large a range of motion as in a normal shrug done for active flexibility. It is usually considered good form if the slope of the shoulders is horizontal in the elevated position."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["shoulder shrug","schulterzucken"],"media":[{"id":"shoulder-shrug-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/570/68b4a33f-40f1-4dda-b56c-a2e20ed13903.jpg","caption":"Shoulder Shrug","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Schulterzucken","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Ausgangsposition:","Sitzen oder stehen Sie mit geradem Rücken.","Schritte:","Heben Sie die Schultern so weit wie möglich gerade nach oben und halten Sie sie 5 Sekunden lang.","Lassen Sie die Schultern wieder in eine entspannte Position sinken.","Wiederholen Sie die Übung."]}},{"id":"ex-shoulder-width-three-point-push-up","slug":"shoulder-width-three-point-push-up","name":"Shoulder width three-point push-up","description":"Bodyweight exercise for the chest, with shoulders, core, triceps assisting.","instructions":["Get into a push-up position with your shoulders directly above your hands and your feet hip-width apart. Draw your belly button in towards your spine and tighten your abdominal muscles. Lift your left foot about five centimetres off the floor. Point your toes straight down. Do not move your hips. Your body forms a straight line from your head to your heels throughout the exercise. Now bend your elbows, lower your chest to the floor and push yourself back up. Repeat the exercise on the other side."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","ABS_CORE","TRICEPS"],"equipment":"BODYWEIGHT","tags":["shoulder width three-point push-up","schulterbreite dreipunkt-liegestütze"],"media":[],"source":"wger","de":{"name":"Schulterbreite Dreipunkt-Liegestütze","description":"Übung (Körpergewicht) für die Brust, unterstützt von Schultern, Rumpf, Trizeps.","instructions":["Geh in die Liegestützposition, deine Schultern befinden sich direkt über den Händen, deine Füße sind hüftbreit voneinander entfernt. Zieh den Bauchnabel in Richtung Wirbelsäule und spann die Bauchmuskulatur an. Hebe deinen linken Fuß etwa fünf Zentimeter vom Boden an. Die Zehen zeigen gerade nach unten. Bewege dabei nicht deine Hüften. Dein Körper bildet während der ganzen Übung eine gerade Linie vom Kopf bis zu den Fersen. Nun beuge die Ellbogen, senke deinen Brustkorb bis zum Boden ab und drück dich wieder nach oben. Wiederhole die Übung auf der anderen Seite."]}},{"id":"ex-shrugs-barbells","slug":"shrugs-barbells","name":"Shrugs, Barbells","description":"Barbell exercise for the shoulders.","instructions":["Take a barbell and stand with a straight body, the arms are hanging freely in front of you. Lift from this position the shoulders as high as you can, but don't bend the arms during the movement. On the highest point, make a short pause of 1 or 2 seconds before returning slowly to the initial position.","When training with a higher weight, make sure that you still do the whole movement!"],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["shrugs, barbells","shrugs"],"media":[{"id":"shrugs-barbells-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/150/Barbell-shrugs-1.png","caption":"Shrugs, Barbells","attribution":"wger.de · Everkinetic","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Shrugs","description":"Übung (Langhantel) für die Schultern.","instructions":["Stelle dich mit geradem Oberkörper hin, die Hände hängen frei nach unten und halten die Langhantel. Hebe aus dieser Position die Schultern so weit nach oben, wie es geht, beuge aber die Arme während der Übung nicht. Am höchsten Punkt kannst du eine oder zwei Sekunden Pause machen bevor du langsam wieder runtergehst.","Bei größerem Gewicht, beachte immer, dass du immer noch die volle Bewegungsamplitude durchführen kannst."]}},{"id":"ex-shrugs-dumbbells","slug":"shrugs-dumbbells","name":"Shrugs, Dumbbells","description":"Dumbbell exercise for the shoulders.","instructions":["Stand with straight body, the hands are hanging freely on the side and hold each a dumbbell. Lift from this position the shoulders as high as you can, but don't bend the arms during the movement. On the highest point, make a short pause of 1 or 2 seconds before returning slowly to the initial position.","When training with a higher weight, make sure that you still do the whole movement!"],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["shrugs, dumbbells","shrugs"],"media":[{"id":"shrugs-dumbbells-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/151/Dumbbell-shrugs-2.png","caption":"Shrugs, Dumbbells","attribution":"wger.de · Everkinetic","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Shrugs","description":"Übung (Kurzhantel) für die Schultern.","instructions":["Stelle dich mit geradem Oberkörper hin, die Hände hängen frei nach unten und halten je eine Kurzhantel. Hebe aus dieser Position die Schultern so weit nach oben, wie es geht, beuge aber die Arme während der Übung nicht. Am höchsten Punkt kannst du eine oder zwei Sekunden Pause machen bevor du langsam wieder runtergehst.","Bei größerem Gewicht, beachte immer, dass du immer noch die volle Bewegungsamplitude durchführen kannst."]}},{"id":"ex-side-bend","slug":"side-bend","name":"Side bend","description":"Dumbbell exercise for the core.","instructions":["With a weight in one hand, extend that arm down and bend the other arm, resting your hand on your head. Now move the hand holding the weight by rotating your torso up and down."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["side bend","seitneigung"],"media":[{"id":"side-bend-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1188/43e714e4-b736-4f3a-8ab4-97821fdff86a.jpg","caption":"Side bend","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Seitneigung","description":"Übung (Kurzhantel) für den Rumpf.","instructions":["Mit einer Hantel in einer Hand streckst du den Arm nach unten und beugst den anderen Arm, wobei du die Hand an den Kopf legst. Nun führst du die Hand mit der Hantel nach oben und unten, während du den Oberkörper drehst."]}},{"id":"ex-side-dumbbell-trunk-flexion","slug":"side-dumbbell-trunk-flexion","name":"Side Dumbbell Trunk Flexion","description":"Dumbbell exercise for the core.","instructions":["AKA dumbbell side bends. Stand in line with the hips with slightly bent knees, maintain the natural curvature of the spine, hand stretched by the body, grip the barbell with one hand. Make slow and controlled torso side flexions till you reach the angle of approximately 45°."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["side dumbbell trunk flexion","seitliches oberkörperbeugen mit"],"media":[],"source":"wger","de":{"name":"Seitliches Oberkörperbeugen Mit","description":"Übung (Kurzhantel) für den Rumpf.","instructions":["Zielmuskeln: Schräger Bauchmuskel","Unterstützende Muskulatur: Gerader Bauchmuskel"]}},{"id":"ex-side-hop-sprint","slug":"side-hop-sprint","name":"Side Hop-Sprint","description":"Accessory exercise for the quadriceps, with glutes, calves, hamstrings assisting.","instructions":["Stand to the side of a cone or hurdle.","Begin this drill by hopping sideways over the obstacle, rebounding out of your landing to hop back to where you started.","Hop for a prescribed number or repetitions as quickly as possible, and finish this drill by sprinting a short distance upon landing the last hop."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","CALVES","HAMSTRINGS"],"equipment":"OTHER","tags":["side hop-sprint"],"media":[{"id":"side-hop-sprint-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Hop-Sprint/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"side-hop-sprint-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Hop-Sprint/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite, unterstützt von Po, Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-side-laterals-to-front-raise","slug":"side-laterals-to-front-raise","name":"Side Laterals to Front Raise","description":"Dumbbell exercise for the shoulders, with back assisting.","instructions":["In a standing position, hold a pair of dumbbells at your side. This will be your starting position.","Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating.","At the top of the exercise move the weights out in front of you, keeping your arms extended.","Lower the weights with a controlled motion.","On the next repetition, raise the weights in front of you to shoulder height before moving the weights laterally to your sides.","Lower the weights to the starting position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"DUMBBELL","tags":["side laterals to front raise"],"media":[{"id":"side-laterals-to-front-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Laterals_to_Front_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"side-laterals-to-front-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Laterals_to_Front_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern, unterstützt von Rücken.","instructions":null}},{"id":"ex-side-laying-interior-rotation","slug":"side-laying-interior-rotation","name":"Side-laying interior rotation","description":"Barbell exercise for the back.","instructions":["Laying on your side and using the arm closest to the bench, maintain a 90 degree bend at the elbow and allow the weight to fall towards the ground past the bench as low as comfortable. Bring the weight up using only rotation of the shoulder to the opposing shoulder."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["side-laying interior rotation","innenrotation in seitenlage"],"media":[{"id":"side-laying-interior-rotation-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1582/5094fe30-eea2-4269-b0de-4b8a20558fd7.png","caption":"Side-laying interior rotation","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Innenrotation in Seitenlage","description":"Übung (Langhantel) für den Rücken.","instructions":["Lege dich auf die Seite und verwende den Arm, der der Bank am nächsten ist. Halte einen 90-Grad-Winkel im Ellbogen und lasse das Gewicht an der Bank vorbei so weit wie angenehm möglich in Richtung Boden sinken. Hebe das Gewicht wieder an, indem du nur die Schulter in Richtung der gegenüberliegenden Schulter rotierst."]}},{"id":"ex-side-leg-raises","slug":"side-leg-raises","name":"Side Leg Raises","description":"Bodyweight exercise for the quadriceps.","instructions":["Stand next to a chair, which you may hold onto as a support. Stand on one leg. This will be your starting position.","Keeping your leg straight, raise it as far out to the side as possible, and swing it back down, allowing it to cross the opposite leg.","Repeat this swinging motion 5-10 times, increasing the range of motion as you do so."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["side leg raises"],"media":[{"id":"side-leg-raises-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Leg_Raises/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"side-leg-raises-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Leg_Raises/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelvorderseite.","instructions":null}},{"id":"ex-side-lying-external-rotation","slug":"side-lying-external-rotation","name":"Side-lying External Rotation","description":"Bodyweight exercise for the shoulders.","instructions":["With a weight in one hand, lie on your side opposite the weight. Keep your knees slightly bent. Hold your elbow against your side, and extend your upper arm straight ahead of you. While continuing to hold your elbow against your side, rotate your upper arm 90 degrees upwards.","It is helpful to place a towel under your armpit to help with the form on this exercise. Placing a support under your head for the duration of the exercise is also a good idea."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["side-lying external rotation","außenrotation in seitenlage"],"media":[],"source":"wger","de":{"name":"Außenrotation in Seitenlage","description":"Übung (Körpergewicht) für die Schultern.","instructions":["Halte ein Gewicht in einer Hand und lege dich auf die dem Gewicht entgegengesetzte Seite. Halte die Knie leicht gebeugt. Halte deinen Ellbogen an der Körperseite und strecke deinen Oberarm gerade nach vorne aus. Während du den Ellbogen weiterhin an der Körperseite hältst, rotiere deinen Unterarm 90 Grad nach oben.","Es ist hilfreich, ein Handtuch unter die Achsel zu legen, um die Ausführung dieser Übung zu erleichtern. Eine Unterlage unter dem Kopf während der gesamten Übung ist ebenfalls eine gute Idee."]}},{"id":"ex-side-lying-floor-stretch","slug":"side-lying-floor-stretch","name":"Side-Lying Floor Stretch","description":"Equipment-free exercise for the back.","instructions":["First lie on your left side, bending your left knee in front of you to stabilize your torso (use your abdominal muscles as well to hold you upright).","Straighten your right leg and rest the right foot on the floor behind your left. Straighten your right arm over your head and gently pull on your right wrist to stretch the entire right side of the body. Switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"NONE","tags":["side-lying floor stretch"],"media":[{"id":"side-lying-floor-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side-Lying_Floor_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"side-lying-floor-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side-Lying_Floor_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Rücken.","instructions":null}},{"id":"ex-side-lying-groin-stretch","slug":"side-lying-groin-stretch","name":"Side Lying Groin Stretch","description":"Equipment-free exercise for the quadriceps, with hamstrings assisting.","instructions":["Start off by lying on your right side and bend your right knee in front of you to stabilize the torso.","Rest your head on your right hand or shoulder. Lift your left leg upward and hold it by the back of the knee (easier) or the foot (harder).","Pull your left knee in toward your left shoulder and simultaneously press your foot or knee down to the floor. To intensify this stretch, straighten your left leg. Switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["HAMSTRINGS"],"equipment":"NONE","tags":["side lying groin stretch"],"media":[{"id":"side-lying-groin-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lying_Groin_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"side-lying-groin-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lying_Groin_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelvorderseite, unterstützt von Oberschenkelrückseite.","instructions":null}},{"id":"ex-side-lying-hip-abduction","slug":"side-lying-hip-abduction","name":"Side Lying Hip Abduction","description":"Bodyweight exercise for the quadriceps.","instructions":["Begin by lying down on your side with your top leg straight and your bottom leg bent for support.","Lift your top leg off the ground","(optional) - Hold position at the top","Resources:","40 seconds YouTube video: https://www.youtube.com/watch?v=g9FtnmsIYgI"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["side lying hip abduction","hüftabduktion in seitenlage"],"media":[],"source":"wger","de":{"name":"Hüftabduktion in Seitenlage","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite.","instructions":["Lege dich zunächst auf die Seite, das obere Bein ist gestreckt und das untere Bein zur Stabilisierung angewinkelt.","Hebe dein oberes Bein vom Boden ab.","(optional) - Halte die Position oben.","Quellen:","40-sekündiges YouTube-Video: https://www.youtube.com/watch?v=g9FtnmsIYgI"]}},{"id":"ex-side-slides-squats","slug":"side-slides-squats","name":"Side Slides + Squats","description":"Bodyweight exercise for the quadriceps, with calves, glutes assisting.","instructions":["With feet a little wider than shoulder-width apart and staying low to mimic a defensive position, you should step with their lead leg and push off with their plant leg.","After three slides, rotate your body for 180 degree on the guiding (/outer) leg and do a squat. Continue."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES"],"equipment":"BODYWEIGHT","tags":["side slides + squats","seitliche slides + kniebeugen"],"media":[],"source":"wger","de":{"name":"Seitliche Slides + Kniebeugen","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Waden, Po.","instructions":["Mit den Füßen etwas weiter als schulterbreit auseinander und in einer tiefen, defensiven Haltung trittst du mit dem führenden Bein zur Seite und stößt dich mit dem Standbein ab.","Nach drei Slides drehst du deinen Körper um 180 Grad auf dem führenden (äußeren) Bein und machst eine Kniebeuge. Fahre fort."]}},{"id":"ex-side-standing-long-jump","slug":"side-standing-long-jump","name":"Side Standing Long Jump","description":"Equipment-free exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Begin standing with your feet hip width apart in an athletic stance. Your head and chest should be up, knees and hips slightly bent. This will be your starting position.","Leaning to your right, extend through your hips, knees, and ankles to jump into the air. Block with the arms to lead the movement, jumping as far to your right as you can.","Land facing the same direction with your feet hip width apart, absorbing the impact through your lower body."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"NONE","tags":["side standing long jump"],"media":[{"id":"side-standing-long-jump-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Standing_Long_Jump/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"side-standing-long-jump-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Standing_Long_Jump/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-side-straight-arm-pulldown-cable","slug":"side-straight-arm-pulldown-cable","name":"Side Straight-Arm Pulldown (Cable)","description":"Cable exercise for the back.","instructions":["Keep your torso still, pulling the handle down along your side using the outer lat.","Don’t twist your body or rotate your torso to cheat the rep."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["side straight-arm pulldown (cable)","seitlicher überzug mit gestrecktem arm am kabelzug"],"media":[],"source":"wger","de":{"name":"Seitlicher Überzug mit gestrecktem Arm am Kabelzug","description":"Übung (Kabelzug) für den Rücken.","instructions":["Halte deinen Oberkörper ruhig und ziehe den Griff seitlich an deinem Körper entlang nach unten, indem du den äußeren Teil des Latissimus einsetzt.","Verdrehe deinen Körper nicht und rotiere nicht den Oberkörper, um die Wiederholung zu erleichtern."]}},{"id":"ex-side-to-side-box-shuffle","slug":"side-to-side-box-shuffle","name":"Side to Side Box Shuffle","description":"Accessory exercise for the quadriceps, with glutes, calves, hamstrings assisting.","instructions":["Stand to one side of the box with your left foot resting on the middle of it.","To begin, jump up and over to the other side of the box, landing with your right foot on top of the box and your left foot on the floor. Swing your arms to aid your movement.","Continue shuffling back and forth across the box."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","CALVES","HAMSTRINGS"],"equipment":"OTHER","tags":["side to side box shuffle"],"media":[{"id":"side-to-side-box-shuffle-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_to_Side_Box_Shuffle/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"side-to-side-box-shuffle-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_to_Side_Box_Shuffle/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite, unterstützt von Po, Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-side-to-side-chins","slug":"side-to-side-chins","name":"Side To Side Chins","description":"Accessory exercise for the back, with biceps, forearms, shoulders assisting.","instructions":["Grab the pull-up bar with the palms facing forward using a wide grip.","As you have both arms extended in front of you holding the bar at a wide grip, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","Pull your torso up while leaning to the left hand side until the bar almost touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space (no swinging) and only the arms should move. The forearms should do no other work other than hold the bar.","After a second of contraction, inhale as you go back to the starting position.","Now, pull your torso up while leaning to the right hand side until the bar almost touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second of contraction, inhale as you go back to the starting position.","Repeat steps 3-6 until you have performed the prescribed amount of repetitions for each side."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","FOREARMS","SHOULDERS"],"equipment":"OTHER","tags":["side to side chins"],"media":[{"id":"side-to-side-chins-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_To_Side_Chins/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"side-to-side-chins-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_To_Side_Chins/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Bizeps, Unterarme, Schultern.","instructions":null}},{"id":"ex-side-to-side-push-ups","slug":"side-to-side-push-ups","name":"Side to Side Push Ups","description":"Bodyweight exercise for the shoulders, with core, chest, triceps assisting.","instructions":["-start in push up position","-lean the body weight to the right side, and complete a push up with the chest over the right hand","-come back to the centered position","-on rep 2, lean to the left side"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["ABS_CORE","CHEST","TRICEPS"],"equipment":"BODYWEIGHT","tags":["side to side push ups","liegestütze seitlich"],"media":[],"source":"wger","de":{"name":"Liegestütze seitlich","description":"Übung (Körpergewicht) für die Schultern, unterstützt von Rumpf, Brust, Trizeps.","instructions":["-Beginne in der Liegestützposition","-Verlagere das Körpergewicht auf die rechte Seite und führe einen Liegestütz aus, bei dem die Brust über der rechten Hand ist","-Kehre in die mittige Position zurück","-Verlagere bei Wiederholung 2 das Gewicht auf die linke Seite"]}},{"id":"ex-side-wrist-pull","slug":"side-wrist-pull","name":"Side Wrist Pull","description":"Equipment-free exercise for the shoulders, with forearms, back assisting.","instructions":["This stretch works best standing. Cross your left arm over the midline of your body and hold the left wrist in your right hand down at the level of your hips. Start the stretch with a bent left arm.","Slowly straighten, pull, and lift it up to shoulder height, as pictured. Feel this stretch originate in your back, not your shoulders, and don't pull too hard on the shoulders joint. Switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["FOREARMS","BACK"],"equipment":"NONE","tags":["side wrist pull"],"media":[{"id":"side-wrist-pull-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Wrist_Pull/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"side-wrist-pull-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Wrist_Pull/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Schultern, unterstützt von Unterarme, Rücken.","instructions":null}},{"id":"ex-single-arm-cable-crossover","slug":"single-arm-cable-crossover","name":"Single-Arm Cable Crossover","description":"Cable exercise for the chest.","instructions":["Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.","Step forward in front of both pulleys with your arms extended in front of you, bringing your hands together. Your head and chest should be up as you lean forward, while your feet should be staggered. This will be your starting position.","Keeping your left arm in place, allow your right arm to extend out to the side, maintaining a slight bend at the elbow. The right arm should be perpendicular to the body at approximately shoulder level.","Return your arm back to the starting position by pulling your hand back to the midline of the body.","Hold for a second at the starting position and repeat the movement on the opposite side. Continue alternating back and forth for the prescribed number of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["single-arm cable crossover"],"media":[{"id":"single-arm-cable-crossover-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Arm_Cable_Crossover/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"single-arm-cable-crossover-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Arm_Cable_Crossover/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Brust.","instructions":null}},{"id":"ex-single-arm-cable-row-w-rotation-floor","slug":"single-arm-cable-row-w-rotation-floor","name":"Single-Arm Cable Row /w Rotation (floor)","description":"Cable exercise for the back.","instructions":["Go into a one-legged kneeling position and grab the cable from the lowest position.","Rotate the upper torso to get into the starting position and bend the upper torso a little bit sidewise.","Place the unused hand on the knee.","Pull the cable while rotating the upper torso."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["single-arm cable row /w rotation (floor)","rudern am kabelzug mit rotation"],"media":[],"source":"wger","de":{"name":"Rudern am Kabelzug mit Rotation","description":"Übung (Kabelzug) für den Rücken.","instructions":["Knie dich einbeinig auf den Boden und greife den Kabelzug von unten.","Rotiere den Oberkörper leicht um die Startposition zu erreichen und biege deinen Oberkörper seitlich hin.","Lege die unbenutze Hand auf dem Knie ab.","Zieh am Kabel und rotiere dabei den Oberkörper."]}},{"id":"ex-single-arm-linear-jammer","slug":"single-arm-linear-jammer","name":"Single-Arm Linear Jammer","description":"Barbell exercise for the shoulders, with chest, triceps assisting.","instructions":["Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.","Raise the bar from the floor, taking it to your shoulders with one or both hands. Adopt a wide stance. This will be your starting position.","Perform the movement by extending the elbow, pressing the weight up. Move explosively, extending the hips and knees fully to produce maximal force.","Return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CHEST","TRICEPS"],"equipment":"BARBELL","tags":["single-arm linear jammer"],"media":[{"id":"single-arm-linear-jammer-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Arm_Linear_Jammer/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"single-arm-linear-jammer-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Arm_Linear_Jammer/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Schultern, unterstützt von Brust, Trizeps.","instructions":null}},{"id":"ex-single-arm-preacher-curl","slug":"single-arm-preacher-curl","name":"Single-arm Preacher Curl","description":"Dumbbell exercise for the biceps.","instructions":["Sit on the preacher curl bench and perform a bicep curl with a dumbbell in one hand. Your other hand can be at rest, or beneath your curling arm's elbow."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["single-arm preacher curl","einarmiger scott-curl"],"media":[],"source":"wger","de":{"name":"Einarmiger Scott-Curl","description":"Übung (Kurzhantel) für den Bizeps.","instructions":["Setze dich an die Scott-Curl-Bank und führe mit einer Kurzhantel in einer Hand einen Bizeps-Curl aus. Deine andere Hand kann ruhen oder den Ellbogen deines Curl-Arms abstützen."]}},{"id":"ex-single-arm-push-up","slug":"single-arm-push-up","name":"Single-Arm Push-Up","description":"Bodyweight exercise for the chest, with shoulders, triceps assisting.","instructions":["Begin laying prone on the ground. Move yourself into a position supporting your weight on your toes and one arm. Your working arm should be placed directly under the shoulder, fully extended. Your legs should be extended, and for this movement you may need a wider base, placing your feet further apart than in a normal push-up.","Maintain good posture, and place your free hand behind your back. This will be your starting position.","Lower yourself by allowing the elbow to flex until you touch the ground.","Descend slowly, and reverse direction be extending the arm to return to the starting position."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BODYWEIGHT","tags":["single-arm push-up"],"media":[{"id":"single-arm-push-up-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Arm_Push-Up/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"single-arm-push-up-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Arm_Push-Up/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-single-arm-row","slug":"single-arm-row","name":"Single arm row","description":"Cable exercise for the back.","instructions":["Sitting on the ground, use a high cable in a single grip, to do lat pulldowns with a focus on a long stretch in the lats."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["single arm row","einarmiges rudern"],"media":[{"id":"single-arm-row-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1637/a1fbe83a-a3e5-49f6-a2c2-5d5b533c2be8.png","caption":"Single arm row","attribution":"wger.de · Rottekongen","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Einarmiges Rudern","description":"Übung (Kabelzug) für den Rücken.","instructions":["Setze dich auf den Boden und benutze einen hohen Kabelzug mit Einzelgriff, um Latzüge auszuführen, wobei du auf eine lange Dehnung im Latissimus achtest."]}},{"id":"ex-single-cone-sprint-drill","slug":"single-cone-sprint-drill","name":"Single-Cone Sprint Drill","description":"Accessory exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["This drill teaches quick foot action. You need a single cone. Begin standing next to the cone with one arm back and one arm forward.","Chop the feet as quickly as possible, blocking with the arms. Circle the cone, keep your knees up, with violent foot action.","Rest after three trips around the cone."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"OTHER","tags":["single-cone sprint drill"],"media":[{"id":"single-cone-sprint-drill-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Cone_Sprint_Drill/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"single-cone-sprint-drill-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Cone_Sprint_Drill/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-single-dumbbell-raise","slug":"single-dumbbell-raise","name":"Single Dumbbell Raise","description":"Dumbbell exercise for the shoulders, with forearms, back assisting.","instructions":["With a wide stance, hold a dumbell with both hands, grasping the head of the dumbbell instead of the handle. Your arms should be extended and hanging at the waist. This will be your starting position.","Raise the weight until it is above shoulder level, keeping your arms extended. Your torso and hips should remain stationary throughout the movement.","Return to the starting position and repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["FOREARMS","BACK"],"equipment":"DUMBBELL","tags":["single dumbbell raise"],"media":[{"id":"single-dumbbell-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Dumbbell_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"single-dumbbell-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Dumbbell_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern, unterstützt von Unterarme, Rücken.","instructions":null}},{"id":"ex-single-leg-butt-kick","slug":"single-leg-butt-kick","name":"Single Leg Butt Kick","description":"Bodyweight exercise for the quadriceps, with calves, hamstrings assisting.","instructions":["Begin by standing on one leg, with the bent knee raised. This will be your start position.","Using a countermovement jump, take off upward by extending the hip, knee, and ankle of the grounded leg.","Immediately flex the knee and attempt to touch your butt with the heel of your jumping leg.","Return the leg to a partially bent position underneath the hips and land. Your opposite leg should stay in relatively the same position throughout the drill."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["single leg butt kick"],"media":[{"id":"single-leg-butt-kick-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Leg_Butt_Kick/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"single-leg-butt-kick-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Leg_Butt_Kick/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-single-leg-deadlift-with-dumbbell","slug":"single-leg-deadlift-with-dumbbell","name":"Single-Leg Deadlift with Dumbbell","description":"Dumbbell exercise for the hamstrings, with glutes assisting.","instructions":["Starting Position: Stand upright with a slight bend in your knees, holding a dumbbell in one or both hands. Shift your weight onto your supporting leg (e.g., your right leg) and lift your non-supporting foot slightly off the floor.","The Hinge: Keeping your back flat and core engaged, hinge at your hips, pushing your glutes backward. As your torso lowers, extend your non-supporting leg straight back behind you for balance, keeping your hips square to the floor. The dumbbell(s) should lower toward the ground along the line of your supporting leg.","Range of Motion: Continue lowering your torso until it is nearly parallel to the floor, or you feel an intense stretch in your supporting hamstring, ensuring your back remains neutral throughout the movement.","Return to Start: Pause at the bottom, then contract your glutes and hamstrings to slowly raise your torso back to the starting position. Your non-supporting leg should return in line with the supporting one.","Switch Sides: After completing your desired number of repetitions on one side, switch your weight and repeat the movement on the other leg."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES"],"equipment":"DUMBBELL","tags":["single-leg deadlift with dumbbell","einbeiniges kreuzheben mit kurzhantel"],"media":[{"id":"single-leg-deadlift-with-dumbbell-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1736/aa724cc5-c485-4f3e-9d2a-0c6ae4baefbe.png","caption":"Single-Leg Deadlift with Dumbbell","attribution":"wger.de · Tierrasverdes","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Einbeiniges Kreuzheben mit Kurzhantel","description":"Übung (Kurzhantel) für die Oberschenkelrückseite, unterstützt von Po.","instructions":["Ausgangsposition: Stelle dich aufrecht mit leicht gebeugten Knien hin und halte eine Kurzhantel in einer oder beiden Händen. Verlagere dein Gewicht auf dein Standbein (z. B. dein rechtes Bein) und hebe deinen anderen Fuß leicht vom Boden ab.","Die Hüftbeuge: Halte deinen Rücken flach und deinen Rumpf angespannt und beuge dich aus der Hüfte, indem du dein Gesäß nach hinten schiebst. Während sich dein Oberkörper senkt, streckst du dein freies Bein gerade nach hinten aus, um das Gleichgewicht zu halten, und hältst dabei deine Hüften parallel zum Boden. Die Kurzhantel(n) sollte(n) entlang deines Standbeins zum Boden hin absinken.","Bewegungsumfang: Senke deinen Oberkörper weiter ab, bis er nahezu parallel zum Boden ist oder du eine intensive Dehnung in der hinteren Oberschenkelmuskulatur deines Standbeins spürst, und achte darauf, dass dein Rücken während der gesamten Bewegung neutral bleibt.","Rückkehr zur Ausgangsposition: Halte am tiefsten Punkt kurz inne, spanne dann deine Gesäß- und hintere Oberschenkelmuskulatur an, um deinen Oberkörper langsam wieder in die Ausgangsposition anzuheben. Dein freies Bein sollte wieder auf eine Linie mit dem Standbein zurückkehren.","Seite wechseln: Nachdem du die gewünschte Anzahl an Wiederholungen auf einer Seite absolviert hast, verlagere dein Gewicht und wiederhole die Bewegung mit dem anderen Bein."]}},{"id":"ex-single-leg-glute-bridge","slug":"single-leg-glute-bridge","name":"Single Leg Glute Bridge","description":"Bodyweight exercise for the glutes, with hamstrings assisting.","instructions":["Lay on the floor with your feet flat and knees bent.","Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.","Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.","Extend as far as possible, pause and then return to the starting position."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["single leg glute bridge"],"media":[{"id":"single-leg-glute-bridge-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Leg_Glute_Bridge/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"single-leg-glute-bridge-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Leg_Glute_Bridge/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelrückseite.","instructions":null}},{"id":"ex-single-leg-hamstring-stretch","slug":"single-leg-hamstring-stretch","name":"Single Leg Hamstring Stretch","description":"Bodyweight exercise for the hamstrings.","instructions":["Sit on the ground with one leg straight out in front of you and the other leg bent in toward you. Reach forward with both hands, trying to touch the toes of your straight leg."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["single leg hamstring stretch","einbeiniges dehnen der hinteren oberschenkelmuskulatur"],"media":[],"source":"wger","de":{"name":"Einbeiniges Dehnen der hinteren Oberschenkelmuskulatur","description":"Übung (Körpergewicht) für die Oberschenkelrückseite.","instructions":["Setze dich auf den Boden, ein Bein gerade nach vorne ausgestreckt und das andere zu dir herangebeugt. Strecke beide Hände nach vorne und versuche, die Zehen deines gestreckten Beins zu berühren."]}},{"id":"ex-single-leg-high-box-squat","slug":"single-leg-high-box-squat","name":"Single-Leg High Box Squat","description":"Accessory exercise for the quadriceps, with glutes, hamstrings assisting.","instructions":["Position a box in a rack. Secure a band or rope in place above the box.","Standing in front of it, step onto the box to a full standing position, letting your other leg remain unsupported. Hold onto the band for balance",". Continue stepping up and down on the same leg before switching to the opposite side."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","HAMSTRINGS"],"equipment":"OTHER","tags":["single-leg high box squat"],"media":[{"id":"single-leg-high-box-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Leg_High_Box_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"single-leg-high-box-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Leg_High_Box_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite, unterstützt von Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-single-leg-hop-progression","slug":"single-leg-hop-progression","name":"Single-Leg Hop Progression","description":"Accessory exercise for the quadriceps, with glutes, calves, hamstrings assisting.","instructions":["Arrange a line of cones in front of you. Assume a relaxed standing position, balanced on one leg. Raise the knee of your opposite leg. This will be your starting position.","Hop forward, jumping and landing with the same leg over the cone.","Use a countermovement jump to hop from cone to cone.","At the end, turn around and go back on the other leg."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","CALVES","HAMSTRINGS"],"equipment":"OTHER","tags":["single-leg hop progression"],"media":[{"id":"single-leg-hop-progression-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Leg_Hop_Progression/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"single-leg-hop-progression-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Leg_Hop_Progression/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite, unterstützt von Po, Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-single-leg-lateral-hop","slug":"single-leg-lateral-hop","name":"Single-Leg Lateral Hop","description":"Accessory exercise for the quadriceps, with glutes, calves, hamstrings assisting.","instructions":["Stand to the side of a cone or hurdle. To get into the start position, stand on one leg with your knee slightly bent.","To begin, execute a counterjump to hop sideways over the cone.","Land on your jumping leg, and immediately rebound out of it by jumping back to the start position.","Continue hopping back and forth."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","CALVES","HAMSTRINGS"],"equipment":"OTHER","tags":["single-leg lateral hop"],"media":[{"id":"single-leg-lateral-hop-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Leg_Lateral_Hop/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"single-leg-lateral-hop-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Leg_Lateral_Hop/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite, unterstützt von Po, Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-single-leg-leg-extension","slug":"single-leg-leg-extension","name":"Single-Leg Leg Extension","description":"Machine exercise for the quadriceps.","instructions":["Seat yourself in the machine and adjust it so that you are positioned properly. The pad should be against the lower part of the shin but not in contact with the ankle. Adjust the seat so that the pivot point is in line with your knee. Select a weight appropriate for your abilities.","Maintaining good posture, fully extend one leg, pausing at the top of the motion.","Return to the starting position without letting the weight stop, keeping tension on the muscle.","Repeat for the desired number of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["single-leg leg extension","beinstrecker einbeinig"],"media":[{"id":"single-leg-leg-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Leg_Leg_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"single-leg-leg-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Leg_Leg_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Beinstrecker Einbeinig","description":"Übung (Maschine) für die Oberschenkelvorderseite.","instructions":["Der Bewegungsablauf ist wie beim beidbeinigem Beinstrecker:","Setze dich in die Beinstreckermaschine. Der Rücken soll einen festen Halt haben, stelle die Maschine so ein, dass du fest sitzt. In der Anfangsposition sind die Beine entwas nach hinten angewinkelt. Drücke das Gewicht nach oben bis die Beine nahezu vollständig ausgestreckt sind. Gehe langsam und kontrolliert wieder runter."]}},{"id":"ex-single-leg-lunge-with-kettlebell","slug":"single-leg-lunge-with-kettlebell","name":"Single-Leg Lunge with Kettlebell:","description":"Kettlebell exercise for the calves, with glutes, quadriceps assisting.","instructions":["How to do a single-leg kettlebell lunge","Preparation: Stand with your feet together. Hold the kettlebell with both hands by the handle, keeping it close to your chest, or hold it with one hand (on the same side as the working leg).","Step and Lower: Take a large step forward (or backward, which is safer for your knees) with one leg, lowering your hips until both knees form a 90-degree angle.","Focus: Shift your weight onto your front (or bent) leg, keeping your back straight and your torso upright.","Return: Push off with your front leg to return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":["GLUTES","QUADRICEPS"],"equipment":"KETTLEBELL","tags":["single-leg lunge with kettlebell:","einbeiniger ausfallschritt mit kettlebell"],"media":[{"id":"single-leg-lunge-with-kettlebell-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1734/782e2fbb-1267-476d-a817-14f3b83e0564.png","caption":"Single-Leg Lunge with Kettlebell:","attribution":"wger.de · Tierrasverdes","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Einbeiniger Ausfallschritt mit Kettlebell","description":"Übung (Kettlebell) für die Waden, unterstützt von Po, Oberschenkelvorderseite.","instructions":["So führst du einen einbeinigen Ausfallschritt mit Kettlebell aus","Vorbereitung: Stelle dich mit geschlossenen Füßen hin. Halte die Kettlebell mit beiden Händen am Griff dicht an deiner Brust oder halte sie mit einer Hand (auf der gleichen Seite wie das arbeitende Bein).","Schritt und Absenken: Mache mit einem Bein einen großen Schritt nach vorne (oder nach hinten, was schonender für deine Knie ist) und senke deine Hüften ab, bis beide Knie einen 90-Grad-Winkel bilden.","Fokus: Verlagere dein Gewicht auf dein vorderes (oder gebeugtes) Bein, halte deinen Rücken gerade und deinen Oberkörper aufrecht.","Rückkehr: Drücke dich mit deinem vorderen Bein ab, um in die Ausgangsposition zurückzukehren."]}},{"id":"ex-single-leg-push-off","slug":"single-leg-push-off","name":"Single Leg Push-off","description":"Accessory exercise for the quadriceps, with calves, hamstrings assisting.","instructions":["Stand on the ground with one foot resting on the box, heel close to the edge.","Push off with your foot on top of the box, trying to gain as much height as possible by extending through the hip and knee.","Land with the same foot on top of the box, returning your other foot back to the start position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","HAMSTRINGS"],"equipment":"OTHER","tags":["single leg push-off"],"media":[{"id":"single-leg-push-off-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Leg_Push-off/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"single-leg-push-off-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Leg_Push-off/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite, unterstützt von Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-single-leg-rdl","slug":"single-leg-rdl","name":"Single Leg RDL","description":"Bodyweight exercise for the hamstrings, with glutes assisting.","instructions":["Stand upright and hold weights in both hands if using loads.","Brace your core and lift one leg off the ground.","Keep your back straight, hinge at the hips while lowering your torso forward, ensuring you don’t rotate your hips.","Lower until you feel a stretch in your standing leg's hamstring, then return to standing position. Repeat on both sides."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES"],"equipment":"BODYWEIGHT","tags":["single leg rdl","einbeiniges kreuzheben mit gestreckten beinen (single leg rdl)"],"media":[],"source":"wger","de":{"name":"Einbeiniges Kreuzheben mit gestreckten Beinen (Single Leg RDL)","description":"Übung (Körpergewicht) für die Oberschenkelrückseite, unterstützt von Po.","instructions":["Stehe aufrecht und halte bei Verwendung von Gewichten in beiden Händen eine Last.","Spanne deinen Rumpf an und hebe ein Bein vom Boden ab.","Halte deinen Rücken gerade, beuge dich in der Hüfte und senke deinen Oberkörper nach vorne, wobei du darauf achtest, deine Hüfte nicht zu verdrehen.","Senke dich ab, bis du eine Dehnung in der hinteren Oberschenkelmuskulatur deines Standbeins spürst, und kehre dann in die aufrechte Position zurück. Wiederhole es auf beiden Seiten."]}},{"id":"ex-single-leg-side-glute-press","slug":"single-leg-side-glute-press","name":"Single-leg side glute press","description":"Bodyweight exercise for the calves, with glutes, quadriceps assisting.","instructions":["The Single-Leg Side Glute Press is a leg press machine variation where you angle your body sideways on the pad, placing one foot high and slightly angled to press the weight, powerfully targeting the outer glute (gluteus medius/minimus) and hamstrings for balanced leg development and stability, requiring focus on pushing through the heel and maintaining control without locking out.","How to Perform:","Setup: Sit in the leg press machine, rotate your body to one hip, placing one foot high on the platform at about a 45-degree angle with toes pointed slightly out/forward.","Positioning: Keep your hip, knee, and ankle aligned, and ensure your lower back stays on the pad.","Descent: Slowly lower the weight, allowing your knee to bend deeply (near 90 degrees), feeling a stretch in your glute and hamstring.","Press: Drive through your heel (not your toes) to press the weight back up, squeezing your glutes and hamstrings, stopping just before your leg fully extends.","Control: Avoid bouncing and don't let your lower back lift off the pad; maintain tension throughout the movement."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":["GLUTES","QUADRICEPS"],"equipment":"BODYWEIGHT","tags":["single-leg side glute press","einbeinige seitliche gesäßpresse"],"media":[{"id":"single-leg-side-glute-press-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1735/43bca7d9-2333-43f3-8554-2d0b39fa2a07.png","caption":"Single-leg side glute press","attribution":"wger.de · Tierrasverdes","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Einbeinige seitliche Gesäßpresse","description":"Übung (Körpergewicht) für die Waden, unterstützt von Po, Oberschenkelvorderseite.","instructions":["Die einbeinige seitliche Gesäßpresse ist eine Variante an der Beinpresse, bei der du deinen Körper seitlich auf das Polster drehst und einen Fuß hoch und leicht angewinkelt aufsetzt, um das Gewicht zu drücken. Sie beansprucht kraftvoll die äußere Gesäßmuskulatur (Gluteus medius/minimus) und die hintere Oberschenkelmuskulatur und sorgt für eine ausgewogene Beinentwicklung und Stabilität. Dabei kommt es darauf an, über die Ferse zu drücken und die Kontrolle zu behalten, ohne das Bein durchzustrecken.","So führst du sie aus:","Aufbau: Setze dich in die Beinpresse, drehe deinen Körper auf eine Hüftseite und platziere einen Fuß hoch auf der Plattform in einem Winkel von etwa 45 Grad, mit den Zehen leicht nach außen/vorne zeigend.","Positionierung: Halte Hüfte, Knie und Fußgelenk in einer Linie und achte darauf, dass dein unterer Rücken am Polster bleibt.","Absenken: Senke das Gewicht langsam ab und lass dein Knie tief beugen (fast 90 Grad), sodass du eine Dehnung in deiner Gesäß- und hinteren Oberschenkelmuskulatur spürst.","Drücken: Drücke über deine Ferse (nicht über die Zehen), um das Gewicht wieder nach oben zu pressen, spanne dabei deine Gesäß- und hintere Oberschenkelmuskulatur an und stoppe kurz bevor dein Bein vollständig gestreckt ist.","Kontrolle: Vermeide ruckartige Bewegungen und lass deinen unteren Rücken nicht vom Polster abheben; halte die Spannung während der gesamten Bewegung aufrecht."]}},{"id":"ex-single-leg-stride-jump","slug":"single-leg-stride-jump","name":"Single-Leg Stride Jump","description":"Accessory exercise for the quadriceps, with glutes, calves, hamstrings assisting.","instructions":["Stand to the side of a box with your inside foot on top of it, close to the edge.","Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward.","Land in the same position that you started, using your inside leg to decelerate the impact."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","CALVES","HAMSTRINGS"],"equipment":"OTHER","tags":["single-leg stride jump"],"media":[{"id":"single-leg-stride-jump-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Leg_Stride_Jump/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"single-leg-stride-jump-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Leg_Stride_Jump/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite, unterstützt von Po, Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-sit-up-elbow-thrust","slug":"sit-up-elbow-thrust","name":"Sit Up Elbow Thrust","description":"Bodyweight exercise for the core.","instructions":["This","is a top down rotation movement, and it’s a bit more","explosive, too.","Lying with knees bent and feet on the floor, sit up and then drive your left elbow across your entire body toward the right, then come back","to center and then finally lower yourself down. Then hit the other side."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["sit up elbow thrust","sit-ups (ellenbogen zum knie)"],"media":[{"id":"sit-up-elbow-thrust-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1479/0305d98e-0887-4c0c-8992-7c220814efc2.webp","caption":"Sit Up Elbow Thrust","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Sit-Ups (Ellenbogen zum Knie)","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Füße fixieren","Muskulatur anspannen","Kein Schwung holen","Kontrollierte Bewegung","Langsame Durchführung","Gleichmäßig atmen"]}},{"id":"ex-sit-ups","slug":"sit-ups","name":"Sit-ups","description":"Bodyweight exercise for the core.","instructions":["Sit on a mat, your calves are resting on a bench, the knees make a right angle. Hold your hands behind your neck. Go now up with a rolling movement of your back, you should feel how the individual vertebrae lose contact with the mat. At the highest point, contract your abs as much as you can and hold there for 2 sec. Go now down, unrolling your back."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["sit-ups","sit ups"],"media":[],"source":"wger","de":{"name":"Sit Ups","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Lege dich auf eine Matte, die Knie sind rechtwiklig angewinkelt und die Fersen liegen auf eine Bank. Die Hände sind hinter dem Nacken. Das Hochgehen wird mit einer rollenden Bewegung durchgeführt: die Wirbelsäule sollte sich Wirbel für Wirbel von der Matte lösen. Ein Hohlkreuz ist stets zu vermeiden. Auf der höchsten Stelle sollten die Muskeln etwa 2 sek. maximal angespannt werden bevor die rollende Bewegung in der Gegenrichtung durchgeführt wird."]}},{"id":"ex-sitting-calf-raises","slug":"sitting-calf-raises","name":"Sitting Calf Raises","description":"Bodyweight exercise for the calves.","instructions":["Sit on a bench for calf raises and check that the feet are half free and that you can completely stretch the calf muscles down. Pull your calves up, going as far (up) as you can. Make at the highest point a short pause of 1 or 2 seconds and go down."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["sitting calf raises","wadenheben sitzend"],"media":[],"source":"wger","de":{"name":"Wadenheben Sitzend","description":"Übung (Körpergewicht) für die Waden.","instructions":["Setze dich auf die Bank und stelle die Fußspitzen so auf den Rand, dass du die Waden komplett nach unten austrecken kannst. Ziehe nun die Wadenmuskeln zusammen und gehe so hoch es geht. Mache auf dem höchsten Punkt eine kurze Pause (1-2 sek.) und gehe dann runter."]}},{"id":"ex-skullcrusher-dumbbells","slug":"skullcrusher-dumbbells","name":"Skullcrusher Dumbbells","description":"Dumbbell exercise for the triceps.","instructions":["Hold the dumbbells and lay down on a flat bench in such a way that around 1/4 of your head is over the edge. Stretch arms straight up and then lean dumbbells away from your toes to a 10-20 degree angle. Keep upper arm at this angle throughout exercise. Dumbbell shall not be amed at your head, but away over your head. This will maximise gain from exercise with load on triceps all the time.","Pay attention to your elbows and arms: only the triceps are doing the work, the rest of the arms should not move."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["skullcrusher dumbbells","frenchpress"],"media":[],"source":"wger","de":{"name":"Frenchpress","description":"Übung (Kurzhantel) für den Trizeps.","instructions":["Nehme die Hanteln in die Hand, lege dich auf eine Bank und stelle dich so hin, dass ca. 1/4 des Kopfes nicht mehr auf der Bank liegt. Strecke die Arme aus und lasse nun mit einem Bogen die Gewichte runter. Wenn die Hanteln knapp über die Stirn sind, drücke sie wieder nach oben.","Es ist wichtig die Ellenbogen während der ganzen Übung wenig zu bewegen, damit die Trizeps die Arbeit machen."]}},{"id":"ex-skydiver-with-arms-in-t-position","slug":"skydiver-with-arms-in-t-position","name":"Skydiver with arms in T-position","description":"Bodyweight exercise for the back.","instructions":["Lie on your stomach with your legs more than shoulder-width apart and your feet up. Your arms are stretched out to the side and form a T with your upper body, your palms are on the floor. Now raise your upper body, arms and legs as high as you can while keeping your body under tension. Turn your thumbs towards the ceiling and pull your shoulder blades together. While keeping your upper body and all limbs in the air, bring your legs together and then spread them again, keeping them constantly in the air. For the remaining repetitions, only move your legs open and closed."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["skydiver with arms in t-position","fallschirmspringer in t-position"],"media":[],"source":"wger","de":{"name":"Fallschirmspringer in T-Position","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Leg dich auf deinen Bauch, deine Beine sind mehr als schulterbreit gespreizt, die Füße aufgestellt. Deine Arme sind zur Seite ausgestreckt und bilden mit deinem Oberkörper ein T, deine Handflächen liegen auf dem Boden. Hebe nun unter Körperspannung deinen Oberkörper mitsamt Armen und deine Beine so weit an, wie du kannst. Dreh dabei die Daumen Richtung Decke und zieh deine Schulterblätter zusammen. Während du den Oberkörper und alle Gliedmaßen in der Luft hältst, bring deine Beine zusammen und spreiz sie dann wieder, dabei hältst du sie stetig in der Luft. Bei den weiteren Wiederholungen bewegst du nur noch die Beine auf und zu."]}},{"id":"ex-sled-overhead-backward-walk","slug":"sled-overhead-backward-walk","name":"Sled Overhead Backward Walk","description":"Accessory exercise for the shoulders, with calves, back, quadriceps assisting.","instructions":["Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight.","Face the sled, backing up until there is some tension in the line. Hold your hands directly above your head with your elbows extended. This will be your starting position.","Walk backwards, keeping your arms raised above your head. Avoid jerky movements."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CALVES","BACK","QUADRICEPS"],"equipment":"OTHER","tags":["sled overhead backward walk"],"media":[{"id":"sled-overhead-backward-walk-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sled_Overhead_Backward_Walk/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"sled-overhead-backward-walk-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sled_Overhead_Backward_Walk/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Schultern, unterstützt von Waden, Rücken, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-sled-overhead-triceps-extension","slug":"sled-overhead-triceps-extension","name":"Sled Overhead Triceps Extension","description":"Accessory exercise for the triceps.","instructions":["Attach dual handles to a sled using a chain or rope. Load the sled to an appropriate load.","Facing away from the sled, step away until there is tension in the line. Raise your hands above your head, keeping them together, palms facing each other. Your elbows should be pointed upward with the elbows flexed. This will be your starting position.","Extend through the elbow to straighten the arm. Ensure that your upper arm stays in position to isolate the triceps.","Upon full extension, step forward to take the slack out of the line. You may keep your feet staggered for more stability."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["sled overhead triceps extension"],"media":[{"id":"sled-overhead-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sled_Overhead_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"sled-overhead-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sled_Overhead_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Trizeps.","instructions":null}},{"id":"ex-sled-reverse-flye","slug":"sled-reverse-flye","name":"Sled Reverse Flye","description":"Accessory exercise for the shoulders.","instructions":["Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight.","Face the sled, backing up until there is some tension in the line. Take both handles at arms length at about waist level. Bend the knees slightly and keep your chest and head up. This will be your starting position.","Without flexing the elbow, pull the handles upward and apart, performing a reverse fly with some external rotation. Your palms should be facing forward as you do this.","Return to the starting position, taking a couple steps back to take the slack out of the line."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["sled reverse flye"],"media":[{"id":"sled-reverse-flye-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sled_Reverse_Flye/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"sled-reverse-flye-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sled_Reverse_Flye/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Schultern.","instructions":null}},{"id":"ex-sled-row","slug":"sled-row","name":"Sled Row","description":"Accessory exercise for the back, with biceps assisting.","instructions":["Attach dual handles to a sled connected by a rope or chain. Load the sled to an appropriate weight. Face the sled, backing up until there is some tension in the line.","With a handle in each hand, bend the knees slightly, keep your head and chest up, and begin with your arms extended.","To initiate the movement, flex the elbow as you retract your shoulder blades, pulling the sled towards you.","Take a step or two back to get tension in the line and repeat."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"OTHER","tags":["sled row"],"media":[{"id":"sled-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sled_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"sled-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sled_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-sledgehammer-swings","slug":"sledgehammer-swings","name":"Sledgehammer Swings","description":"Accessory exercise for the core, with calves, forearms, back, shoulders assisting.","instructions":["You will need a tire and a sledgehammer for this exercise. Stand in front of the tire about two feet away from it with a staggered stance. Grip the sledgehammer.","If you are right handed, your left hand should be at the bottom of the handle, and your right hand should be choking up closer to the head.","As you bring the sledge up, your right hand slides toward the head; as you swing down, your right hand will slide down to join your left hand. Slam it down as hard as you can against the tire. Control the bounce of the hammer off of the tire.","Repeat on the other side."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["CALVES","FOREARMS","BACK","SHOULDERS"],"equipment":"OTHER","tags":["sledgehammer swings"],"media":[{"id":"sledgehammer-swings-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sledgehammer_Swings/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"sledgehammer-swings-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sledgehammer_Swings/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rumpf, unterstützt von Waden, Unterarme, Rücken, Schultern.","instructions":null}},{"id":"ex-sliding-lateral-lunge","slug":"sliding-lateral-lunge","name":"Sliding Lateral Lunge","description":"Barbell exercise for the hamstrings, with glutes, quadriceps, calves, core assisting.","instructions":["Stand upright with your feet hip-width apart, holding a kettlebell close to your chest in goblet position. Place one foot on a slider, gliding disc, or towel. Keep your chest tall and core engaged. Slowly slide the foot outward to the side while bending the opposite knee, lowering your hips into a lateral lunge. Keep the working leg’s knee aligned with the toes and avoid letting it collapse inward. The non-working leg remains straight and slides smoothly along the floor. Push through the heel of the bent leg to return to the starting position while maintaining control of the kettlebell."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","QUADRICEPS","CALVES","ABS_CORE"],"equipment":"BARBELL","tags":["sliding lateral lunge","seitlicher ausfallschritt mit slider"],"media":[{"id":"sliding-lateral-lunge-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1604/7695428e-bfed-4021-b987-498d93153995.png","caption":"Sliding Lateral Lunge","attribution":"wger.de · RiccaBaro","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Seitlicher Ausfallschritt mit Slider","description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Po, Oberschenkelvorderseite, Waden, Rumpf.","instructions":["Stelle dich aufrecht hin, mit den Füßen hüftbreit auseinander, und halte eine Kettlebell in der Goblet-Position nah an deiner Brust. Stelle einen Fuß auf einen Slider, eine Gleitscheibe oder ein Handtuch. Halte deinen Brustkorb aufrecht und den Rumpf angespannt. Gleite den Fuß langsam zur Seite nach außen, während du das gegenüberliegende Knie beugst und deine Hüften in einen seitlichen Ausfallschritt absenkst. Halte das Knie des arbeitenden Beins in einer Linie mit den Zehen und lass es nicht nach innen einknicken. Das nicht arbeitende Bein bleibt gestreckt und gleitet sanft über den Boden. Drücke dich über die Ferse des gebeugten Beins ab, um in die Ausgangsposition zurückzukehren, während du die Kontrolle über die Kettlebell behältst."]}},{"id":"ex-sloper-hanging","slug":"sloper-hanging","name":"Sloper hanging","description":"Bodyweight exercise for the biceps.","instructions":["Hanging on sloper holds of a fingerboard for a amount of seconds"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["sloper hanging","sloper hängen"],"media":[{"id":"sloper-hanging-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/804/6f4b8bd9-fa05-49de-870b-1f79b595ce89.png","caption":"Sloper hanging","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Sloper hängen","description":"Übung (Körpergewicht) für den Bizeps.","instructions":["Mit ausgestreckten Armen an Slopern des Fingerboards hängen für eine Anzahl an Sekunden"]}},{"id":"ex-slow-squat","slug":"slow-squat","name":"Slow Squat","description":"Bodyweight exercise for the quadriceps, with hamstrings, glutes, core assisting.","instructions":["​A tempo-based squat that uses controlled movement to increase muscle tension and improve lower-body stability.","​Lower: Descend slowly for 3 seconds.","​Pause: Hold at the bottom for 1 second.","​Stand: Return to the starting position at a normal pace.","Form: Keep your chest up and weight in your heels."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["HAMSTRINGS","GLUTES","ABS_CORE"],"equipment":"BODYWEIGHT","tags":["slow squat","langsame kniebeuge"],"media":[{"id":"slow-squat-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1963/db285682-1ab3-4be0-ae00-5117ecce1ee6.png","caption":"Slow Squat","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Langsame Kniebeuge","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Oberschenkelrückseite, Po, Rumpf.","instructions":["Eine tempobasierte Kniebeuge, die durch eine kontrollierte Bewegung die Muskelspannung erhöht und die Stabilität des Unterkörpers verbessert.","Absenken: Senke dich 3 Sekunden lang langsam ab.","Pause: Halte unten 1 Sekunde lang inne.","Aufstehen: Kehre in normalem Tempo in die Ausgangsposition zurück.","Haltung: Halte deine Brust aufrecht und das Gewicht auf den Fersen."]}},{"id":"ex-smith-incline-shoulder-raise","slug":"smith-incline-shoulder-raise","name":"Smith Incline Shoulder Raise","description":"Smith machine exercise for the shoulders, with chest assisting.","instructions":["Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your shoulders are aligned right under the barbell.","Using a shoulder width pronated (palms forward) grip, lift the bar from the rack and hold it straight over you with a slight bend at the elbows. This will be your starting position.","As you breathe out, lift the bar up until your arms are fully extended. Note: The contraction should be felt around the shoulders.","After a second pause, bring the bar back down to the starting position as you breathe in.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CHEST"],"equipment":"SMITH_MACHINE","tags":["smith incline shoulder raise"],"media":[{"id":"smith-incline-shoulder-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Incline_Shoulder_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"smith-incline-shoulder-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Incline_Shoulder_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Multipresse) für die Schultern, unterstützt von Brust.","instructions":null}},{"id":"ex-smith-machine-behind-the-back-shrug","slug":"smith-machine-behind-the-back-shrug","name":"Smith Machine Behind the Back Shrug","description":"Smith machine exercise for the back, with shoulders assisting.","instructions":["With the bar at thigh level, load an appropriate weight.","Stand with the bar behind you, taking a shoulder-width, pronated grip on the bar and unhook the weight. You should be standing up straight with your head and chest up and your arms extended. This will be your starting position.","Initiate the movement by shrugging your shoulders straight up. Do not flex the arms or wrist during the movement.","After a brief pause return the weight to the starting position.","Repeat for the desired number of repetitions before engaging the hooks to rack the weight."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["SHOULDERS"],"equipment":"SMITH_MACHINE","tags":["smith machine behind the back shrug"],"media":[{"id":"smith-machine-behind-the-back-shrug-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Behind_the_Back_Shrug/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"smith-machine-behind-the-back-shrug-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Behind_the_Back_Shrug/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Multipresse) für den Rücken, unterstützt von Schultern.","instructions":null}},{"id":"ex-smith-machine-bench-press","slug":"smith-machine-bench-press","name":"Smith Machine Bench Press","description":"Smith machine exercise for the chest, with shoulders, triceps assisting.","instructions":["Place a flat bench underneath the smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, lock the bar back in the rack."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"SMITH_MACHINE","tags":["smith machine bench press","bankdrücken an der multipresse"],"media":[{"id":"smith-machine-bench-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Bench_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"smith-machine-bench-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Bench_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Bankdrücken an der Multipresse","description":"Übung (Multipresse) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-smith-machine-bent-over-row","slug":"smith-machine-bent-over-row","name":"Smith Machine Bent Over Row","description":"Smith machine exercise for the back, with biceps, shoulders assisting.","instructions":["Set the barbell attached to the smith machine to a height that is about 2 inches below your knees.","Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up.","Now grasp the barbell using an overhand (pronated) grip and unlock it from the smith machine rack. Then let it hang directly in front of you as your arms hang extended perpendicular to the floor and your torso. This is your starting position.","While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.","Slowly lower the weight again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","SHOULDERS"],"equipment":"SMITH_MACHINE","tags":["smith machine bent over row"],"media":[{"id":"smith-machine-bent-over-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Bent_Over_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"smith-machine-bent-over-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Bent_Over_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Multipresse) für den Rücken, unterstützt von Bizeps, Schultern.","instructions":null}},{"id":"ex-smith-machine-calf-raise","slug":"smith-machine-calf-raise","name":"Smith Machine Calf Raise","description":"Smith machine exercise for the calves.","instructions":["Place a block or weight plate below the bar on the Smith machine. Set the bar to a position that best matches your height. Once the correct height is chosen and the bar is loaded, step onto the plates with the balls of your feet and place the bar on the back of your shoulders.","Take the bar with both hands facing forward. Rotate the bar to unrack it. This will be your starting position.","Raise your heels as high as possible by pushing off of the balls of your feet, flexing your calf at the top of the contraction. Your knees should remain extended. Hold the contracted position for a second before you start to go back down.","Return slowly to the starting position as you breathe in while lowering your heels.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"SMITH_MACHINE","tags":["smith machine calf raise","wadenheben an der multipresse"],"media":[{"id":"smith-machine-calf-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Calf_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"smith-machine-calf-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Calf_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Wadenheben an der Multipresse","description":"Übung (Multipresse) für die Waden.","instructions":null}},{"id":"ex-smith-machine-close-grip-bench-press","slug":"smith-machine-close-grip-bench-press","name":"Smith Machine Close-Grip Bench Press","description":"Smith machine exercise for the triceps, with chest, shoulders assisting.","instructions":["Place a flat bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a close and pronated grip (palms facing forward) that is around shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, lock the bar back in the rack."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"SMITH_MACHINE","tags":["smith machine close-grip bench press","enges bankdrücken an der multipresse"],"media":[{"id":"smith-machine-close-grip-bench-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Close-Grip_Bench_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"smith-machine-close-grip-bench-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Close-Grip_Bench_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Enges Bankdrücken an der Multipresse","description":"Übung (Multipresse) für den Trizeps, unterstützt von Brust, Schultern.","instructions":["Führe an der Multipresse ein normales Bankdrücken aus, aber halte deine Hände etwa schulterbreit an der Stange und halte die Ellbogen nah am Körper."]}},{"id":"ex-smith-machine-decline-press","slug":"smith-machine-decline-press","name":"Smith Machine Decline Press","description":"Smith machine exercise for the chest, with shoulders, triceps assisting.","instructions":["Position a decline bench in the rack so that the bar will be above your chest. Load an appropriate weight and take your place on the bench.","Rotate the bar to unhook it from the rack and fully extend your arms. Your back should be slightly arched and your shoulder blades retracted. This will be your starting position.","Begin the movement by flexing your arms, lowering the bar to your chest.","Pause briefly, and then extend your arms to push the weight back to the starting position.","After completing the desired number of repetitions, rotate the bar to rack the weight."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"SMITH_MACHINE","tags":["smith machine decline press"],"media":[{"id":"smith-machine-decline-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Decline_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"smith-machine-decline-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Decline_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Multipresse) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-smith-machine-hang-power-clean","slug":"smith-machine-hang-power-clean","name":"Smith Machine Hang Power Clean","description":"Smith machine exercise for the hamstrings, with glutes, back, quadriceps, shoulders assisting.","instructions":["Position the bar at knee height and load it to an appropriate weight.","Take a pronated grip on the bar outside of shoulder width and unhook the bar from the machine. Your arms should be fully extended with your head and chest up. Your elbows should be pointed out with your shoulders back and down. Your hips should be back, loading the tension into the hamstrings. This will be your starting position.","Initate the movement by forcefully extending the hips and knees, accelerating into the bar. Ensure that you keep your arms straight during this part of the motion.","Upon full extension, rebend the hips and knees to lower your receiving position.","Allow the arms to flex at this point, rotating the elbows around the bar to receive it on your shoulders.","Extend through the hips and knees to come to a standing position with the bar racked on your shoulders to complete the movement."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","BACK","QUADRICEPS","SHOULDERS"],"equipment":"SMITH_MACHINE","tags":["smith machine hang power clean"],"media":[{"id":"smith-machine-hang-power-clean-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Hang_Power_Clean/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"smith-machine-hang-power-clean-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Hang_Power_Clean/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Multipresse) für die Oberschenkelrückseite, unterstützt von Po, Rücken, Oberschenkelvorderseite, Schultern.","instructions":null}},{"id":"ex-smith-machine-hip-raise","slug":"smith-machine-hip-raise","name":"Smith Machine Hip Raise","description":"Smith machine exercise for the core.","instructions":["Position a bench in the rack and load the bar to an appropriate weight. Lie down on the bench, placing the bottom of your feet against the bar. Unlock the bar and extend your legs. You may need to use your hands to assist you. For added stability grasp the sides of the Smith Machine. This will be your starting position.","Initiate the movement by rotating your pelvis, flexing your spine to raise your hips off of the bench. Maintain a slight bend in the knees throughout the motion.","After a brief pause, return the hips to the bench.","Repeat for the desired number of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"SMITH_MACHINE","tags":["smith machine hip raise"],"media":[{"id":"smith-machine-hip-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Hip_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"smith-machine-hip-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Hip_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Multipresse) für den Rumpf.","instructions":null}},{"id":"ex-smith-machine-incline-bench-press","slug":"smith-machine-incline-bench-press","name":"Smith Machine Incline Bench Press","description":"Smith machine exercise for the chest, with shoulders, triceps assisting.","instructions":["Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your upper chest is aligned with the barbell. Using a pronated grip (palms facing forward) that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your upper chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"SMITH_MACHINE","tags":["smith machine incline bench press","schrägbankdrücken an der multipresse"],"media":[{"id":"smith-machine-incline-bench-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Incline_Bench_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"smith-machine-incline-bench-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Incline_Bench_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Schrägbankdrücken an der Multipresse","description":"Übung (Multipresse) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-smith-machine-leg-press","slug":"smith-machine-leg-press","name":"Smith Machine Leg Press","description":"Smith machine exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Position a Smith machine bar a couple feet off of the ground. Ensure that it is resting on the safeties. After loading the bar to an appropriate weight, lie underneath the bar. Place the middle of your feet on the bar, tucking your knees to your chest. This will be your starting position.","Begin the movement by driving through your feet to move the bar upward, extending the hips and knees. Do not lock out your knees.","At the top of the motion, pause briefly before returning to the starting position."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"SMITH_MACHINE","tags":["smith machine leg press"],"media":[{"id":"smith-machine-leg-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Leg_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"smith-machine-leg-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Leg_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Multipresse) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-smith-machine-one-arm-upright-row","slug":"smith-machine-one-arm-upright-row","name":"Smith Machine One-Arm Upright Row","description":"Smith machine exercise for the shoulders, with biceps, back assisting.","instructions":["With the bar at thigh level, load an appropriate weight.","Take a wide grip on the bar and unhook the weight, removing your off hand from the bar. Your arm should be extended as you stand up straight with your head and chest up. This will be your starting position.","Begin the movement by flexing the elbow, raising the upper arm with the elbow pointed out. Continue until your upper arm is parallel to the floor.","After a brief pause, return the weight to the starting position.","Repeat for the desired number of repetitions before engaging the hooks to rack the weight."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BICEPS","BACK"],"equipment":"SMITH_MACHINE","tags":["smith machine one-arm upright row"],"media":[{"id":"smith-machine-one-arm-upright-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_One-Arm_Upright_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"smith-machine-one-arm-upright-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_One-Arm_Upright_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Multipresse) für die Schultern, unterstützt von Bizeps, Rücken.","instructions":null}},{"id":"ex-smith-machine-overhead-shoulder-press","slug":"smith-machine-overhead-shoulder-press","name":"Smith Machine Overhead Shoulder Press","description":"Smith machine exercise for the shoulders, with triceps assisting.","instructions":["To begin, place a flat bench (or preferably one with back support) underneath a smith machine. Position the barbell at a height so that when seated on the flat bench, the arms must be almost fully extended to reach the barbell.","Once you have the correct height, sit slightly in behind the barbell so that there is an imaginary straight line from the tip of your nose to the barbell. Your feet should be stationary. Grab the barbell with the palms facing forward, unlock it and lift it up so that your arms are fully extended. This is the starting position.","Slowly begin to lower the barbell until it is level with your chin while inhaling.","Then lift the barbell back to the starting position using your shoulders while exhaling.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"SMITH_MACHINE","tags":["smith machine overhead shoulder press","schulterdrücken an der multipresse"],"media":[{"id":"smith-machine-overhead-shoulder-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Overhead_Shoulder_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"smith-machine-overhead-shoulder-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Overhead_Shoulder_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Schulterdrücken an der Multipresse","description":"Übung (Multipresse) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-smith-machine-pistol-squat","slug":"smith-machine-pistol-squat","name":"Smith Machine Pistol Squat","description":"Smith machine exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["To begin, first set the bar to a position that best matches your height. Step under it and position the bar across the back of your shoulders.","Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs. 3","Move one foot forward about 12 inches in front of the bar. Extend the other leg out in front of you, holding it off the ground. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position.","Maintaining good posture, lower yourself by flexing the knee and hip, going down as far as flexibility allows.","Pause briefly at the bottom and then return to the starting position by driving through the heel of your foot, extending the knee and hip."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"SMITH_MACHINE","tags":["smith machine pistol squat"],"media":[{"id":"smith-machine-pistol-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Pistol_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"smith-machine-pistol-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Pistol_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Multipresse) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-smith-machine-reverse-calf-raises","slug":"smith-machine-reverse-calf-raises","name":"Smith Machine Reverse Calf Raises","description":"Smith machine exercise for the calves.","instructions":["Adjust the barbell on the smith machine to fit your height and align a raised platform right under the bar.","Stand on the platform with the heels of your feet secured on top of it with the balls of your feet extending off it. Position your toes facing forward with a shoulder width stance.","Now, place your shoulders under the barbell while maintaining the foot positioning described and push the barbell up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. This will be your starting position. Tip: The barbell on your back is only for balance purposes.","Raise the balls of your feet as you breathe out by extending your toes as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position for a second before you start to go back down.","Slowly go back down to the starting position as you breathe in by lowering the balls of your feet and toes.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"SMITH_MACHINE","tags":["smith machine reverse calf raises"],"media":[{"id":"smith-machine-reverse-calf-raises-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Reverse_Calf_Raises/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"smith-machine-reverse-calf-raises-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Reverse_Calf_Raises/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Multipresse) für die Waden.","instructions":null}},{"id":"ex-smith-machine-stiff-legged-deadlift","slug":"smith-machine-stiff-legged-deadlift","name":"Smith Machine Stiff-Legged Deadlift","description":"Smith machine exercise for the hamstrings, with glutes, back assisting.","instructions":["To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.","Lift the bar up by fully extending your arms while keeping your back straight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.","Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement","Start bringing your torso up straight again as soon as you feel the hamstrings stretch by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","BACK"],"equipment":"SMITH_MACHINE","tags":["smith machine stiff-legged deadlift"],"media":[{"id":"smith-machine-stiff-legged-deadlift-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Stiff-Legged_Deadlift/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"smith-machine-stiff-legged-deadlift-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Stiff-Legged_Deadlift/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Multipresse) für die Oberschenkelrückseite, unterstützt von Po, Rücken.","instructions":null}},{"id":"ex-smith-machine-upright-row","slug":"smith-machine-upright-row","name":"Smith Machine Upright Row","description":"Smith machine exercise for the back, with biceps, shoulders assisting.","instructions":["To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.","Lift the barbell up and fully extend your arms with your back straight. There should be a slight bend at the elbows. This is the starting position.","Use your side shoulders to lift the bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","SHOULDERS"],"equipment":"SMITH_MACHINE","tags":["smith machine upright row","aufrechtes rudern an der multipresse"],"media":[{"id":"smith-machine-upright-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Upright_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"smith-machine-upright-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Upright_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Aufrechtes Rudern an der Multipresse","description":"Übung (Multipresse) für den Rücken, unterstützt von Bizeps, Schultern.","instructions":null}},{"id":"ex-smith-single-leg-split-squat","slug":"smith-single-leg-split-squat","name":"Smith Single-Leg Split Squat","description":"Smith machine exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["To begin, place a flat bench 2-3 feet behind the smith machine. Then, set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Position your legs by placing one foot slightly forward under the bar and extending your other leg back and place the top of your foot on the bench. This will be your starting position","Begin to slowly lower the bar by bending the knee as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calf becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knee should make an imaginary straight line with the toes that is perpendicular to the front. If your knee is past that imaginary line (if it is past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten your leg again and go back to the starting position.","Repeat for the recommended amount of repetitions.","Switch legs and repeat the movement."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"SMITH_MACHINE","tags":["smith single-leg split squat"],"media":[{"id":"smith-single-leg-split-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Single-Leg_Split_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"smith-single-leg-split-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Single-Leg_Split_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Multipresse) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-snatch","slug":"snatch","name":"Snatch","description":"Barbell exercise for the quadriceps, with biceps, glutes, hamstrings, back, shoulders, triceps assisting.","instructions":["Place your feet at a shoulder width stance with the barbell resting right above the connection between the toes and the rest of the foot.","With a palms facing down grip, bend at the knees and keeping the back flat grab the bar using a wider than shoulder width grip. Bring the hips down and make sure that your body drops as if you were going to sit on a chair. This will be your starting position.","Start pushing the floor as if it were a moving platform with your feet and simultaneously start lifting the barbell keeping it close to your legs.","As the bar reaches the middle of your thighs, push the floor with your legs and lift your body to a complete extension in an explosive motion.","Lift your shoulders back in a shrugging movement as you bring the bar up while lifting your elbows out to the side and keeping them above the bar for as long as possible.","Now in a very quick but powerful motion, you have to get your body under the barbell when it has reached a high enough point where it can be controlled and drop while locking your arms and holding the barbell overhead as you assume a squat position.","Finalize the movement by rising up out of the squat position to finish the lift. At the end of the lift both feet should be on line and the arms fully extended holding the barbell overhead."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["BICEPS","GLUTES","HAMSTRINGS","BACK","SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["snatch","reißen (snatch)"],"media":[{"id":"snatch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"snatch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Reißen (Snatch)","description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Bizeps, Po, Oberschenkelrückseite, Rücken, Schultern, Trizeps.","instructions":["Stelle dich mit hüftbreitem Stand und den Schienbeinen an der Stange auf. Greife die Stange im doppelten Schulterbreiten-Abstand und drücke, während du den unteren Rücken gerade hältst, die Fersen in den Boden, um die Stange anzuheben. Wenn sie über deinen Knien ist, streckst du explosiv die Hüfte und ziehst die Schultern hoch. Lass den Schwung das Gewicht über den Kopf tragen."]}},{"id":"ex-snatch-balance","slug":"snatch-balance","name":"Snatch Balance","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings, shoulders, triceps assisting.","instructions":["Begin with the feet in the pulling position, the bar racked across the back of the shoulders, and the hands placed in a wide snatch grip.","Pop the bar with an abrupt dip and drive of the knees, and aggressively drive under the bar, transitioning the feet into the receiving position.","Receive the bar locked out overhead near the bottom of the squat. The torso should remain vertical, lowering the hips between the legs.","Continue to descend to full depth, and return to a standing position. Carefully lower the weight."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["snatch balance"],"media":[{"id":"snatch-balance-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch_Balance/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"snatch-balance-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch_Balance/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Schultern, Trizeps.","instructions":null}},{"id":"ex-snatch-deadlift","slug":"snatch-deadlift","name":"Snatch Deadlift","description":"Barbell exercise for the hamstrings, with forearms, glutes, back, quadriceps assisting.","instructions":["The snatch deadlift strengthens the first pull of the snatch. Begin with a wide snatch grip with the barbell placed on the platform. The feet should be directly under the hips, with the feet turned out. Squat down to the bar, keeping the back in absolute extension with the head facing forward.","Initiate the movement by driving through the heels, raising the hips. The back angle should remain the same until the bar passes the knees.","At that point, drive your hips through the bar as you lay back. Return the bar to the platform by reversing the motion."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["FOREARMS","GLUTES","BACK","QUADRICEPS"],"equipment":"BARBELL","tags":["snatch deadlift"],"media":[{"id":"snatch-deadlift-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch_Deadlift/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"snatch-deadlift-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch_Deadlift/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Unterarme, Po, Rücken, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-snatch-from-blocks","slug":"snatch-from-blocks","name":"Snatch from Blocks","description":"Barbell exercise for the quadriceps, with calves, forearms, glutes, hamstrings, back, shoulders, triceps assisting.","instructions":["Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position.","Begin the first pull by driving through the front of the heels, raising the bar from the boxes.","Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar with your body as low as possible and the arms fully extended overhead.","Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position. Carefully return the weight to the boxes."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","FOREARMS","GLUTES","HAMSTRINGS","BACK","SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["snatch from blocks"],"media":[{"id":"snatch-from-blocks-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch_from_Blocks/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"snatch-from-blocks-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch_from_Blocks/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Unterarme, Po, Oberschenkelrückseite, Rücken, Schultern, Trizeps.","instructions":null}},{"id":"ex-snatch-pull","slug":"snatch-pull","name":"Snatch Pull","description":"Barbell exercise for the hamstrings, with calves, glutes, back, quadriceps assisting.","instructions":["With a barbell on the floor close to the shins, take a wide snatch grip. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the pull. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward.","There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back. Full extension should be violent and abrupt, and ensure that you do not prolong the extension for longer than necessary."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","GLUTES","BACK","QUADRICEPS"],"equipment":"BARBELL","tags":["snatch pull"],"media":[{"id":"snatch-pull-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch_Pull/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"snatch-pull-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch_Pull/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Waden, Po, Rücken, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-snatch-shrug","slug":"snatch-shrug","name":"Snatch Shrug","description":"Barbell exercise for the back, with forearms, shoulders assisting.","instructions":["Begin with a wide grip, with the bar hanging at the mid thigh position. You can use a hook or overhand grip. Your back should be straight and inclined slightly forward.","Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a snatch, avoid overloading to the point that the execution slows down."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["FOREARMS","SHOULDERS"],"equipment":"BARBELL","tags":["snatch shrug"],"media":[{"id":"snatch-shrug-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch_Shrug/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"snatch-shrug-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch_Shrug/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Unterarme, Schultern.","instructions":null}},{"id":"ex-speed-band-overhead-triceps","slug":"speed-band-overhead-triceps","name":"Speed Band Overhead Triceps","description":"Resistance band exercise for the triceps.","instructions":["For this exercise anchor a band to the ground. We used an incline bench and anchored the band to the base, standing over the bench. Alternatively, this could be performed standing on the band.","To begin, pull the band behind your head, holding it with a pronated grip and your elbows up. This will be your starting position.","To perform the movement, extend through the elbow to to straighten your arms, ensuring that you keep your upper arm in place.","Pause, and then return to the starting position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"BAND","tags":["speed band overhead triceps"],"media":[{"id":"speed-band-overhead-triceps-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Speed_Band_Overhead_Triceps/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"speed-band-overhead-triceps-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Speed_Band_Overhead_Triceps/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Widerstandsband) für den Trizeps.","instructions":null}},{"id":"ex-speed-box-squat","slug":"speed-box-squat","name":"Speed Box Squat","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Attach bands to the bar that are securely anchored near the ground. You may need to choke the bands to get adequate tension.","Use a box of an appropriate height for this exercise. Load the bar to a weight that still requires effort, but isn't so heavy that speed is compromised. Typically, that will be between 50-70% of your one rep max.","Position the bar on your upper back, shoulder blades retracted, back arched and everything tight head to toe. This will be the starting position.","Unrack the bar and position yourself in front of the box. Sit back with your hips until you are seated on the box, ensuring that you descend under control and don't crash onto the surface.","Pause briefly, and explode off of the box, extending through the hips and knees."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"BARBELL","tags":["speed box squat"],"media":[{"id":"speed-box-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Speed_Box_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"speed-box-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Speed_Box_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-speed-squats","slug":"speed-squats","name":"Speed Squats","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings, back assisting.","instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as fast as possible without involving momentum as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position. Note: You should perform these exercises as fast as possible but without breaking perfect form and without involving momentum.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","BACK"],"equipment":"BARBELL","tags":["speed squats"],"media":[{"id":"speed-squats-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Speed_Squats/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"speed-squats-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Speed_Squats/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-spell-caster","slug":"spell-caster","name":"Spell Caster","description":"Dumbbell exercise for the core, with glutes, shoulders assisting.","instructions":["Hold a dumbbell in each hand with a pronated grip. Your feet should be wide with your hips and knees extended. This will be your starting position.","Begin the movement by pulling both of the dumbbells to one side next to your hip, rotating your torso.","Keeping your arms straight and the dumbbells parallel to the ground, rotate your torso to swing the weights to your opposite side.","Continue alternating, rotating from one side to the other until the set is complete."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["GLUTES","SHOULDERS"],"equipment":"DUMBBELL","tags":["spell caster"],"media":[{"id":"spell-caster-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Spell_Caster/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"spell-caster-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Spell_Caster/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Rumpf, unterstützt von Po, Schultern.","instructions":null}},{"id":"ex-spider-crawl","slug":"spider-crawl","name":"Spider Crawl","description":"Bodyweight exercise for the core, with chest, shoulders, triceps assisting.","instructions":["Begin in a prone position on the floor. Support your weight on your hands and toes, with your feet together and your body straight. Your arms should be bent to 90 degrees. This will be your starting position.","Initiate the movement by raising one foot off of the ground. Externally rotate the leg and bring the knee toward your elbow, as far forward as possible.","Return this leg to the starting position and repeat on the opposite side."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["CHEST","SHOULDERS","TRICEPS"],"equipment":"BODYWEIGHT","tags":["spider crawl"],"media":[{"id":"spider-crawl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Spider_Crawl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"spider-crawl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Spider_Crawl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf, unterstützt von Brust, Schultern, Trizeps.","instructions":null}},{"id":"ex-spider-curl","slug":"spider-curl","name":"Spider Curl","description":"EZ-bar exercise for the biceps.","instructions":["Start out by setting the bar on the part of the preacher bench that you would normally sit on. Make sure to align the barbell properly so that it is balanced and will not fall off.","Move to the front side of the preacher bench (the part where the arms usually lay) and position yourself to lay at a 45 degree slant with your torso and stomach pressed against the front side of the preacher bench.","Make sure that your feet (especially the toes) are well positioned on the floor and place your upper arms on top of the pad located on the inside part of the preacher bench.","Use your arms to grab the barbell with a supinated grip (palms facing up) at about shoulder width apart or slightly closer from each other.","Slowly begin to lift the barbell upwards and exhale. Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the barbell back to the starting position as your breathe in. .","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"EZ_BAR","tags":["spider curl"],"media":[{"id":"spider-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Spider_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"spider-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Spider_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Spider Curl","description":"Übung (SZ-Stange) für den Bizeps.","instructions":["Um das Beste aus Kurzhantel-Spider-Curls herauszuholen, brauchst du eine","verstellbare Hantelbank, die auf eine 45-Grad-Neigung eingestellt ist. Diese geneigte Position","lässt deine Arme frei hängen und bringt sie in eine gestreckte Ausgangsposition","mit den Ellbogen leicht vor dem Oberkörper, was der Schlüssel ist, um","durchgehend eine niedrigschwellige isometrische Spannung im gesamten Bewegungsablauf aufrechtzuerhalten.","Lege dich mit dem Gesicht nach unten auf eine verstellbare","Hantelbank, sodass deine Brust vollständig aufliegt, und halte ein Paar Kurzhanteln.","Halte den Kopf in einer neutralen Position"]}},{"id":"ex-split-clean","slug":"split-clean","name":"Split Clean","description":"Barbell exercise for the quadriceps, with calves, forearms, glutes, hamstrings, back, shoulders assisting.","instructions":["With a barbell on the floor close to the shins, take an overhand grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.","As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so.","Receive the bar with the feet split, aggressively moving one foot forward and one foot back. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Bring the feet together as you stand up."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","FOREARMS","GLUTES","HAMSTRINGS","BACK","SHOULDERS"],"equipment":"BARBELL","tags":["split clean"],"media":[{"id":"split-clean-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Clean/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"split-clean-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Clean/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Unterarme, Po, Oberschenkelrückseite, Rücken, Schultern.","instructions":null}},{"id":"ex-split-jerk","slug":"split-jerk","name":"Split Jerk","description":"Barbell exercise for the quadriceps, with glutes, hamstrings, shoulders, triceps assisting.","instructions":["Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward.","Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible.","In the brief moment the feet are not actively driving against the platform, the athlete's effort to push the bar up will drive them down. The feet should be moved to a split stance, one foot forward, one foot back, with the knees partially bent. Receive the bar with the arms locked out overhead.","Return to a standing position, bringing the feet together."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","HAMSTRINGS","SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["split jerk"],"media":[{"id":"split-jerk-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Jerk/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"split-jerk-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Jerk/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Po, Oberschenkelrückseite, Schultern, Trizeps.","instructions":null}},{"id":"ex-split-jump","slug":"split-jump","name":"Split Jump","description":"Bodyweight exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.","Ensure that the front knee is over the midline of the foot.","Extending through both legs, jump as high as possible, swinging your arms to gain lift.","As you jump, bring your feet together, and move them back to their initial positions as you land.","Absorb the impact by reverting back to the starting position."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["split jump"],"media":[{"id":"split-jump-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Jump/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"split-jump-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Jump/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-split-snatch","slug":"split-snatch","name":"Split Snatch","description":"Barbell exercise for the hamstrings, with calves, forearms, glutes, back, quadriceps, shoulders, triceps assisting.","instructions":["Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.","Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.","Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move forcefully to a split position, one foot forward one foot back. Receive the bar with your body as low as possible and the arms fully extended overhead.","Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position, bringing your feet together.","Carefully return the weight to floor."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","FOREARMS","GLUTES","BACK","QUADRICEPS","SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["split snatch"],"media":[{"id":"split-snatch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Snatch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"split-snatch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Snatch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Waden, Unterarme, Po, Rücken, Oberschenkelvorderseite, Schultern, Trizeps.","instructions":null}},{"id":"ex-split-squats","slug":"split-squats","name":"Split Squats","description":"Equipment-free exercise for the hamstrings, with calves, glutes, quadriceps assisting.","instructions":["Being in a standing position. Jump into a split leg position, with one leg forward and one leg back, flexing the knees and lowering your hips slightly as you do so.","As you descend, immediately reverse direction, standing back up and jumping, reversing the position of your legs. Repeat 5-10 times on each leg."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES","GLUTES","QUADRICEPS"],"equipment":"NONE","tags":["split squats"],"media":[{"id":"split-squats-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Squats/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"split-squats-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Squats/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelrückseite, unterstützt von Waden, Po, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-squat-jerk","slug":"squat-jerk","name":"Squat Jerk","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings, shoulders, triceps assisting.","instructions":["Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.","At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athlete's effort to push the bar up will drive them down. The feet should move forcefully to just outside the hips, turned out as necessary. Receive the bar with your body in a full squat and the arms fully extended overhead.","Keeping the bar aligned over the front of the heels, your head and chest up, drive throught heels of the feet to move to a standing position. Carefully return the weight to floor."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["squat jerk"],"media":[{"id":"squat-jerk-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Squat_Jerk/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"squat-jerk-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Squat_Jerk/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Schultern, Trizeps.","instructions":null}},{"id":"ex-squat-jumps","slug":"squat-jumps","name":"Squat Jumps","description":"Bodyweight exercise for the quadriceps.","instructions":["Jump wide, then close"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["squat jumps","tiefe hocksprünge"],"media":[],"source":"wger","de":{"name":"Tiefe Hocksprünge","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite.","instructions":["5 Sekunden parallel zum Boden mit den Oberschenkeln. Dann hoch springen und in Anfangsphase begeben. Arme verschränkt hinter dem Kopf die ganze Zeit."]}},{"id":"ex-squat-thrust","slug":"squat-thrust","name":"Squat Thrust","description":"Bodyweight exercise for the glutes, with quadriceps, core, calves assisting.","instructions":["The burpee, or squat thrust, is a full body exercise used in strength training and as an aerobic exercise. The basic movement is performed in four steps and known as a four-count burpee: Begin in a standing position. Move into a squat position with your hands on the ground. (count 1) Kick your feet back into a plank position, while keeping your arms extended. (count 2) Immediately return your feet into squat position. (count 3) Stand up from the squat position (count 4)"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["QUADRICEPS","ABS_CORE","CALVES"],"equipment":"BODYWEIGHT","tags":["squat thrust","hocksprung"],"media":[],"source":"wger","de":{"name":"Hocksprung","description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelvorderseite, Rumpf, Waden.","instructions":["Ausgangsposition:","Beginne in der hohen Plank-Position:Rücken, Arme und Beine sind gestreckt, die Hände sind schulterbreit auseinander.","Schritte:","Springe mit den Füßen zwischen den Armen nach vorne und halte den Rücken flach.","Lasse die Hände auf dem Boden und springe mit den Beinen zurück in die hohe Plank-Position.","Wiederhole die Übung."]}},{"id":"ex-squat-with-bands","slug":"squat-with-bands","name":"Squat with Bands","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings, back assisting.","instructions":["Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.","Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","BACK"],"equipment":"BARBELL","tags":["squat with bands"],"media":[{"id":"squat-with-bands-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Squat_with_Bands/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"squat-with-bands-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Squat_with_Bands/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-squat-with-chains","slug":"squat-with-chains","name":"Squat with Chains","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings, back assisting.","instructions":["To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.","Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","BACK"],"equipment":"BARBELL","tags":["squat with chains"],"media":[{"id":"squat-with-chains-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Squat_with_Chains/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"squat-with-chains-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Squat_with_Chains/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-squat-with-plate-movers","slug":"squat-with-plate-movers","name":"Squat with Plate Movers","description":"Barbell exercise for the quadriceps, with glutes, calves, hamstrings assisting.","instructions":["To begin, first set the bar on a rack to just below shoulder level. Position a weight plate on the ground a couple feet back from the rack. Once the bar is loaded, step under it and place the back of your shoulders across it.","Hold on to the bar with both hands and lift it off the rack by first pushing with your legs and at the same time straighten your torso.","Step away from the rack and adopt a wide stance with the toes slightly pointed out, with one foot on the weight plate. Keep your head up at all times. This will be your starting position.","Begin to slowly lower the bar by bending the knees and hips. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees.","Raise the bar as you exhale by pushing the floor with the heels of your feet as you extend the hips and knees.","At the top of the movement, side step, bringing your feet together on the opposite side of the plate.","Using your inside foot, push the weight plate, sliding it across the floor to where you were just standing.","Place your inside foot on the weight plate, adopting a wide stance for the next repetition."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","CALVES","HAMSTRINGS"],"equipment":"BARBELL","tags":["squat with plate movers"],"media":[{"id":"squat-with-plate-movers-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Squat_with_Plate_Movers/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"squat-with-plate-movers-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Squat_with_Plate_Movers/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Po, Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-squats","slug":"squats","name":"Squats","description":"Barbell exercise for the quadriceps, with glutes assisting.","instructions":["Place a barbell in a rack just below shoulder-height. Dip under the bar to put it behind the neck across the top of the back, and grip the bar with the hands wider than shoulder-width apart. Lift the chest up and squeeze the shoulder blades together to keep the straight back throughout the entire movement. Stand up to bring the bar off the rack and step backwards, then place the feet so that they are a little wider than shoulder-width apart. Sit back into hips and keep the back straight and the chest up, squatting down so the hips are below the knees. From the bottom of the squat, press feet into the ground and push hips forward to return to the top of the standing position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES"],"equipment":"BARBELL","tags":["squats","kniebeuge"],"media":[],"source":"wger","de":{"name":"Kniebeuge","description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Po.","instructions":["Stelle die Halterung der Langhantel auf so eine Höhe ein, dass du sie bequem raus- und wieder reinbringen kannst. Bereite dich vor:","die Stange ist etwas tiefer als Schulterhöhe","die Füße sind ziemlich auseinander und zeigen leicht nach außen","der Kopf ist im Nacken und schaut nach vorne/oben.","die Brust wird nach außen gebracht","Gehe nun langsam runter, bis der Oberschenkel einen rechten Winkel bildet, nicht tiefer. Die Knie zeigen leicht nach außen, dein Gesäß nach hinten. Mache eine kleine Pause und gehe mit so viel Energie wie du aufbringen kannst, wieder nach oben. Nach 2 Sekunden Pause gehe wieder runter."]}},{"id":"ex-squats-with-bands","slug":"squats-with-bands","name":"Squats - With Bands","description":"Resistance band exercise for the quadriceps, with calves, glutes, hamstrings, back assisting.","instructions":["To start out, make sure that the exercise band is at an even split between both the left and right side of the body. To do this, use your hands to grab both sides of the band and place both feet in the middle of the band. Your feet should be shoulder width apart from each other.","When holding the bands, they should be the same height on each side. You should be using a pronated grip (palms facing forward) and have the handles of the bands next to your face for this exercise. This is the starting position.","Slowly start to bend the knees and lower the legs so that your thighs are parallel to the floor while exhaling.","Use the heel of your feet to push your body up to the starting position as you exhale.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","BACK"],"equipment":"BAND","tags":["squats - with bands"],"media":[{"id":"squats-with-bands-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Squats_-_With_Bands/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"squats-with-bands-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Squats_-_With_Bands/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Widerstandsband) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-standing-adduction-cable","slug":"standing-adduction-cable","name":"Standing Adduction (Cable)","description":"Cable exercise for the quadriceps.","instructions":["Keep your hips square and still, pulling the cable across your opposing leg using only your inner thigh.","Don’t let your torso lean or twist — no side bending to help the rep."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["standing adduction (cable)","adduktion im stehen (kabelzug)"],"media":[],"source":"wger","de":{"name":"Adduktion im Stehen (Kabelzug)","description":"Übung (Kabelzug) für die Oberschenkelvorderseite.","instructions":["Halte deine Hüften gerade und ruhig und ziehe das Kabel nur mit deiner Oberschenkelinnenseite über dein gegenüberliegendes Bein.","Lass deinen Oberkörper nicht zur Seite neigen oder verdrehen – kein seitliches Beugen, um bei der Wiederholung nachzuhelfen."]}},{"id":"ex-standing-alternating-dumbbell-press","slug":"standing-alternating-dumbbell-press","name":"Standing Alternating Dumbbell Press","description":"Dumbbell exercise for the shoulders, with triceps assisting.","instructions":["Stand with a dumbbell in each hand. Raise the dumbbells to your shoulders with your palms facing forward and your elbows pointed out. This will be your starting position.","Extend one arm to press the dumbbell straight up, keeping your off hand in place. Do not lean or jerk the weight during the movement.","After a brief pause, return the weight to the starting position.","Repeat for the opposite side, continuing to alternate between arms."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"DUMBBELL","tags":["standing alternating dumbbell press"],"media":[{"id":"standing-alternating-dumbbell-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Alternating_Dumbbell_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-alternating-dumbbell-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Alternating_Dumbbell_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-standing-barbell-calf-raise","slug":"standing-barbell-calf-raise","name":"Standing Barbell Calf Raise","description":"Barbell exercise for the calves.","instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the bar on the back of your shoulders (slightly below the neck).","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. The knees should be kept with a slight bend; never locked. This will be your starting position. Tip: For better range of motion you may also place the ball of your feet on a wooden block but be careful as this option requires more balance and a sturdy block.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["standing barbell calf raise"],"media":[{"id":"standing-barbell-calf-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Barbell_Calf_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-barbell-calf-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Barbell_Calf_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Waden.","instructions":null}},{"id":"ex-standing-barbell-press-behind-neck","slug":"standing-barbell-press-behind-neck","name":"Standing Barbell Press Behind Neck","description":"Barbell exercise for the shoulders, with triceps assisting.","instructions":["This exercise is best performed inside a squat rack for easier pick up of the bar. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Your back should be kept straight while performing this exercise. This will be your starting position.","Elevate the barbell overhead by fully extending your arms while breathing out.","Hold the contraction for a second and lower the barbell back down to the starting position by inhaling.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"BARBELL","tags":["standing barbell press behind neck"],"media":[{"id":"standing-barbell-press-behind-neck-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Barbell_Press_Behind_Neck/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-barbell-press-behind-neck-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Barbell_Press_Behind_Neck/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-standing-bent-over-one-arm-dumbbell-triceps-extension","slug":"standing-bent-over-one-arm-dumbbell-triceps-extension","name":"Standing Bent-Over One-Arm Dumbbell Triceps Extension","description":"Dumbbell exercise for the triceps, with shoulders assisting.","instructions":["With a dumbbell in one hand and the palm facing your torso, bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up.","The upper arm should be close to the torso and parallel to the floor while the forearm is pointing towards the floor as the hand holds the weight. Tip: There should be a 90-degree angle between the forearm and the upper arm. This is your starting position.","Keeping the upper arms stationary, use the triceps to lift the weights as you exhale until the forearms are parallel to the floor and the whole arm is extended. Like many other arm exercises, only the forearm moves.","After a second contraction at the top, slowly lower the dumbbell back to the starting position as you inhale.","Repeat the movement for the prescribed amount of repetitions.","Switch arms and repeat the exercise."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["SHOULDERS"],"equipment":"DUMBBELL","tags":["standing bent-over one-arm dumbbell triceps extension"],"media":[{"id":"standing-bent-over-one-arm-dumbbell-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-bent-over-one-arm-dumbbell-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Trizeps, unterstützt von Schultern.","instructions":null}},{"id":"ex-standing-bent-over-two-arm-dumbbell-triceps-extension","slug":"standing-bent-over-two-arm-dumbbell-triceps-extension","name":"Standing Bent-Over Two-Arm Dumbbell Triceps Extension","description":"Dumbbell exercise for the triceps.","instructions":["With a dumbbell in each hand and the palms facing your torso, bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up. The upper arms should be close to the torso and parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights. Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.","Keeping the upper arms stationary, use the triceps to lift the weights as you exhale until the forearms are parallel to the floor and the whole arms are extended. Like many other arm exercises, only the forearm moves.","After a second contraction at the top, slowly lower the dumbbells back to their starting position as you inhale.","Repeat the movement for the prescribed amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["standing bent-over two-arm dumbbell triceps extension"],"media":[{"id":"standing-bent-over-two-arm-dumbbell-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-bent-over-two-arm-dumbbell-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Trizeps.","instructions":null}},{"id":"ex-standing-biceps-stretch","slug":"standing-biceps-stretch","name":"Standing Biceps Stretch","description":"Accessory exercise for the biceps, with chest, shoulders assisting.","instructions":["Clasp your hands behind your back with your palms together, straighten arms and then rotate them so your palms face downward.","Raise your arms up and hold until you feel a stretch in your biceps."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"OTHER","tags":["standing biceps stretch"],"media":[{"id":"standing-biceps-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Biceps_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-biceps-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Biceps_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Bizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-standing-bradford-press","slug":"standing-bradford-press","name":"Standing Bradford Press","description":"Barbell exercise for the shoulders, with triceps assisting.","instructions":["Place a loaded bar at shoulder level in a rack. With a pronated grip at shoulder width, begin with the bar racked across the front of your shoulders. This is your starting position.","Initiate the lift by extending the elbows to press the bar overhead. Avoid locking out the elbow as you move the weight behind your head.","Lower the bar down to the back of the head until your elbow forms a right angle.","Lift the bar back over your head by extending the elbows","Lower the bar down to the starting position.","Alternate in this manner until you complete the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"BARBELL","tags":["standing bradford press"],"media":[{"id":"standing-bradford-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Bradford_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-bradford-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Bradford_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-standing-cable-chest-press","slug":"standing-cable-chest-press","name":"Standing Cable Chest Press","description":"Cable exercise for the chest, with shoulders, triceps assisting.","instructions":["Position dual pulleys to chest height and select an appropriate weight. Stand a foot or two in front of the cables, holding one in each hand. You can stagger your stance for better stability.","Position the upper arm at a 90 degree angle with the shoulder blades together. This will be your starting position.","Keeping the rest of the body stationary, extend through the elbows to press the handles forward, drawing them together in front of you.","Pause at the top of the motion, and return to the starting position."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"CABLE","tags":["standing cable chest press"],"media":[{"id":"standing-cable-chest-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Cable_Chest_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-cable-chest-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Cable_Chest_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-standing-cable-lift","slug":"standing-cable-lift","name":"Standing Cable Lift","description":"Cable exercise for the core, with shoulders assisting.","instructions":["Connect a standard handle on a tower, and move the cable to the lowest pulley position.","With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.","With your feet positioned shoulder width apart, squat down and grab the handle with both hands. Your arms should still be fully extended.","In one motion, pull the handle up and across your body until your arms are in a fully-extended position above your head.","Keep your back straight and your arms close to your body as you pivot your back foot and straighten your legs to get a full range of motion.","Retract your arms and then your body. Return to the neutral position in a slow and controlled manner.","Repeat to failure.","Then, reposition and repeat the same series of movements on the opposite side."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["SHOULDERS"],"equipment":"CABLE","tags":["standing cable lift"],"media":[{"id":"standing-cable-lift-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Cable_Lift/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-cable-lift-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Cable_Lift/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rumpf, unterstützt von Schultern.","instructions":null}},{"id":"ex-standing-calf-stretch","slug":"standing-calf-stretch","name":"Standing Calf Stretch","description":"Bodyweight exercise for the calves.","instructions":["This stretch targets the gastrocnemius (the chief muscle of the calf of the leg, which flexes the knee and foot). It is easy to perform anywhere. All you need is a wall or a chair."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["standing calf stretch","stehende wadendehnung"],"media":[{"id":"standing-calf-stretch-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1239/5026373a-a7b4-4e26-a0aa-c46634205196.jpg","caption":"Standing Calf Stretch","attribution":"wger.de · erikocobra","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Stehende Wadendehnung","description":"Übung (Körpergewicht) für die Waden.","instructions":["Diese Dehnung zielt auf den Gastrocnemius ab (den wichtigsten Muskel der Wade, der Knie und Fuß beugt). Sie lässt sich überall leicht ausführen. Alles, was du brauchst, ist eine Wand oder ein Stuhl."]}},{"id":"ex-standing-concentration-curl","slug":"standing-concentration-curl","name":"Standing Concentration Curl","description":"Dumbbell exercise for the biceps, with forearms assisting.","instructions":["Taking a dumbbell in your working hand, lean forward. Allow your working arm to hang perpendicular to the ground with the elbow pointing out. This will be your starting position.","Flex the elbow to curl the weight, keeping the upper arm stationary. At the top of the repetition, flex the biceps and pause.","Lower the dumbbell back to the starting position.","Repeat the movement for the prescribed amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"DUMBBELL","tags":["standing concentration curl"],"media":[{"id":"standing-concentration-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Concentration_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-concentration-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Concentration_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps, unterstützt von Unterarme.","instructions":null}},{"id":"ex-standing-dumbbell-calf-raise","slug":"standing-dumbbell-calf-raise","name":"Standing Dumbbell Calf Raise","description":"Dumbbell exercise for the calves.","instructions":["Stand with your torso upright holding two dumbbells in your hands by your sides. Place the ball of the foot on a sturdy and stable wooden board (that is around 2-3 inches tall) while your heels extend off and touch the floor. This will be your starting position.","With the toes pointing either straight (to hit all parts equally), inwards (for emphasis on the outer head) or outwards (for emphasis on the inner head), raise the heels off the floor as you exhale by contracting the calves. Hold the top contraction for a second.","As you inhale, go back to the starting position by slowly lowering the heels.","Repeat for the recommended amount of times."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["standing dumbbell calf raise"],"media":[{"id":"standing-dumbbell-calf-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Calf_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-dumbbell-calf-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Calf_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Waden.","instructions":null}},{"id":"ex-standing-dumbbell-reverse-curl","slug":"standing-dumbbell-reverse-curl","name":"Standing Dumbbell Reverse Curl","description":"Dumbbell exercise for the biceps, with forearms assisting.","instructions":["To begin, stand straight with a dumbbell in each hand using a pronated grip (palms facing down). Your arms should be fully extended while your feet are shoulder width apart from each other. This is the starting position.","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the muscle.","Slowly begin to bring the dumbbells back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"DUMBBELL","tags":["standing dumbbell reverse curl"],"media":[{"id":"standing-dumbbell-reverse-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Reverse_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-dumbbell-reverse-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Reverse_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps, unterstützt von Unterarme.","instructions":null}},{"id":"ex-standing-dumbbell-straight-arm-front-delt-raise-above-head","slug":"standing-dumbbell-straight-arm-front-delt-raise-above-head","name":"Standing Dumbbell Straight-Arm Front Delt Raise Above Head","description":"Dumbbell exercise for the shoulders.","instructions":["Hold the dumbbells in front of your thighs, palms facing your thighs.","Keep your arms straight with a slight bend at the elbows but keep them locked. This will be your starting position.","Raise the dumbbells in a semicircular motion to arm's length overhead as you exhale.","Slowly return to the starting position using the same path as you inhale.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["standing dumbbell straight-arm front delt raise above head"],"media":[{"id":"standing-dumbbell-straight-arm-front-delt-raise-above-head-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-dumbbell-straight-arm-front-delt-raise-above-head-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern.","instructions":null}},{"id":"ex-standing-dumbbell-triceps-extension","slug":"standing-dumbbell-triceps-extension","name":"Standing Dumbbell Triceps Extension","description":"Dumbbell exercise for the triceps.","instructions":["To begin, stand up with a dumbbell held by both hands. Your feet should be about shoulder width apart from each other. Slowly use both hands to grab the dumbbell and lift it over your head until both arms are fully extended.","The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hands should be facing up towards the ceiling. This will be your starting position.","Keeping your upper arms close to your head with elbows in and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.","Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["standing dumbbell triceps extension"],"media":[{"id":"standing-dumbbell-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-dumbbell-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Trizeps.","instructions":null}},{"id":"ex-standing-dumbbell-upright-row","slug":"standing-dumbbell-upright-row","name":"Standing Dumbbell Upright Row","description":"Dumbbell exercise for the back, with biceps, shoulders assisting.","instructions":["Grasp a dumbbell in each hand with a pronated (palms forward) grip that is slightly less than shoulder width. The dumbbells should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.","Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be close to the body as you move it up and the elbows should drive the motion. Continue to lift them until they nearly touch your chin. Tip: Your elbows should drive the motion. As you lift the dumbbells, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the dumbbells back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","SHOULDERS"],"equipment":"DUMBBELL","tags":["standing dumbbell upright row"],"media":[{"id":"standing-dumbbell-upright-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Upright_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-dumbbell-upright-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Upright_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Rücken, unterstützt von Bizeps, Schultern.","instructions":null}},{"id":"ex-standing-front-barbell-raise-over-head","slug":"standing-front-barbell-raise-over-head","name":"Standing Front Barbell Raise Over Head","description":"Barbell exercise for the shoulders.","instructions":["To begin, stand straight with a barbell in your hands. You should grip the bar with palms facing down and a closer than shoulder width grip apart from each other.","Your feet should be shoulder width apart from each other. Your elbows should be slightly bent. This is the starting position.","Lift the barbell up until it is directly over your head while exhaling. Make sure to keep your elbows slightly bent when performing each repetition.","Once you feel the contraction, begin to lower the barbell back down to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["standing front barbell raise over head"],"media":[{"id":"standing-front-barbell-raise-over-head-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Front_Barbell_Raise_Over_Head/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-front-barbell-raise-over-head-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Front_Barbell_Raise_Over_Head/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Schultern.","instructions":null}},{"id":"ex-standing-hamstring-and-calf-stretch","slug":"standing-hamstring-and-calf-stretch","name":"Standing Hamstring and Calf Stretch","description":"Accessory exercise for the hamstrings.","instructions":["Being by looping a belt, band, or rope around one foot. While standing, place that foot forward.","Bend your back leg, while keeping the front one straight. Now raise the toes of your front foot off of the ground and lean forward.","Using the belt, pull on the top of the foot to increase the stretch in the calf. Hold for 10-20 seconds and repeat with the other foot."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["standing hamstring and calf stretch"],"media":[{"id":"standing-hamstring-and-calf-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Hamstring_and_Calf_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-hamstring-and-calf-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Hamstring_and_Calf_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelrückseite.","instructions":null}},{"id":"ex-standing-hip-circles","slug":"standing-hip-circles","name":"Standing Hip Circles","description":"Bodyweight exercise for the glutes, with quadriceps assisting.","instructions":["Begin standing on one leg, holding to a vertical support.","Raise the unsupported knee to 90 degrees. This will be your starting position.","Open the hip as far as possible, attempting to make a big circle with your knee.","Perform this movement slowly for a number of repetitions, and repeat on the other side."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["QUADRICEPS"],"equipment":"BODYWEIGHT","tags":["standing hip circles"],"media":[{"id":"standing-hip-circles-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Hip_Circles/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-hip-circles-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Hip_Circles/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelvorderseite.","instructions":null}},{"id":"ex-standing-inner-biceps-curl","slug":"standing-inner-biceps-curl","name":"Standing Inner-Biceps Curl","description":"Dumbbell exercise for the biceps.","instructions":["Stand up with a dumbbell in each hand being held at arms length. The elbows should be close to the torso. Your legs should be at about shoulder's width apart from each other.","Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position.","While holding the upper arms stationary, curl the weights out while contracting the biceps as you breathe out. Your wrist should turn so that when the weights are fully elevated you have supinated grip (palms facing up).","Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: Keep the forearms aligned with your outer deltoids.","Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the dumbbells back to the starting position as your breathe in. Remember to rotate the wrists as you lower the weight in order to switch back to a neutral grip.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["standing inner-biceps curl"],"media":[{"id":"standing-inner-biceps-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Inner-Biceps_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-inner-biceps-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Inner-Biceps_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps.","instructions":null}},{"id":"ex-standing-lateral-stretch","slug":"standing-lateral-stretch","name":"Standing Lateral Stretch","description":"Equipment-free exercise for the core.","instructions":["Take a slightly wider than hip distance stance with your knees slightly bent.","Place your right hand on your right hip to support the spine.","Raise your left arm in a vertical line and place your left hand behind your head. Keep it there as you incline your torso to the right.","Keep your weight evenly distributed between both legs (don't lean into your left hip). Switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"NONE","tags":["standing lateral stretch"],"media":[{"id":"standing-lateral-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Lateral_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-lateral-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Lateral_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Rumpf.","instructions":null}},{"id":"ex-standing-long-jump","slug":"standing-long-jump","name":"Standing Long Jump","description":"Bodyweight exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["This drill is best done in sand or other soft landing surface. Ensure that you are able to measure distance. Stand in a partial squat stance with feet shoulder width apart.","Utilizing a big arm swing and a countermovement of the legs, jump forward as far as you can.","Attempt to land with your feet out in front you, reaching as far as possible with your legs.","Measure the distance from your landing point to the starting point and track results."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["standing long jump"],"media":[{"id":"standing-long-jump-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Long_Jump/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-long-jump-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Long_Jump/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-standing-low-pulley-deltoid-raise","slug":"standing-low-pulley-deltoid-raise","name":"Standing Low-Pulley Deltoid Raise","description":"Cable exercise for the shoulders, with forearms assisting.","instructions":["Start by standing to the right side of a low pulley row. Use your left hand to come across the body and grab a single handle attached to the low pulley with a pronated grip (palms facing down). Rest your arm in front of you. Your right hand should grab the machine for better support and balance.","Make sure that your back is erect and your feet are shoulder width apart from each other. This is the starting position.","Begin to use the left hand and come across your body out until it is elevated to shoulder height while exhaling.","Feel the contraction at the top for a second and begin to slowly lower the handle back down to the original starting position while inhaling.","Repeat for the recommended amount of repetitions.","Switch arms and repeat the exercise."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["FOREARMS"],"equipment":"CABLE","tags":["standing low-pulley deltoid raise"],"media":[{"id":"standing-low-pulley-deltoid-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Low-Pulley_Deltoid_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-low-pulley-deltoid-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Low-Pulley_Deltoid_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für die Schultern, unterstützt von Unterarme.","instructions":null}},{"id":"ex-standing-low-pulley-one-arm-triceps-extension","slug":"standing-low-pulley-one-arm-triceps-extension","name":"Standing Low-Pulley One-Arm Triceps Extension","description":"Cable exercise for the triceps, with chest, shoulders assisting.","instructions":["Grab a single handle with your left arm next to the low pulley machine. Turn away from the machine keeping the handle to the side of your body with your arm fully extended. Now use both hands to elevate the single handle directly above the head with the palm facing forward. Keep your upper arm completely vertical (perpendicular to the floor) and put your right hand on your left elbow to help keep it steady. This is the starting position.","Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.","Go back to the starting position by using the triceps to raise the single handle. Breathe out as you perform this step.","Repeat for the recommended amount of repetitions.","Switch arms and repeat the exercise."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"CABLE","tags":["standing low-pulley one-arm triceps extension"],"media":[{"id":"standing-low-pulley-one-arm-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Low-Pulley_One-Arm_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-low-pulley-one-arm-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Low-Pulley_One-Arm_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-standing-military-press","slug":"standing-military-press","name":"Standing Military Press","description":"Barbell exercise for the shoulders, with triceps assisting.","instructions":["Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.","Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.","Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.","Lower the bar down to the collarbone slowly as you inhale.","Lift the bar back up to the starting position as you exhale.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"BARBELL","tags":["standing military press"],"media":[{"id":"standing-military-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Military_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-military-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Military_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-standing-olympic-plate-hand-squeeze","slug":"standing-olympic-plate-hand-squeeze","name":"Standing Olympic Plate Hand Squeeze","description":"Accessory exercise for the forearms, with biceps assisting.","instructions":["To begin, stand straight while holding a weight plate by the ridge at arm's length in each hand using a neutral grip (palms facing in). You feet should be shoulder width apart from each other. This will be your starting position.","Lower the plates until the fingers are nearly extended but can still hold weights. Inhale as you lower the plates.","Now raise the plates back to the starting position as you exhale by closing your hands.","Repeat for the recommended amount of repetitions prescribed in your program."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":["BICEPS"],"equipment":"OTHER","tags":["standing olympic plate hand squeeze"],"media":[{"id":"standing-olympic-plate-hand-squeeze-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Olympic_Plate_Hand_Squeeze/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-olympic-plate-hand-squeeze-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Olympic_Plate_Hand_Squeeze/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Unterarme, unterstützt von Bizeps.","instructions":null}},{"id":"ex-standing-one-arm-cable-curl","slug":"standing-one-arm-cable-curl","name":"Standing One-Arm Cable Curl","description":"Cable exercise for the biceps.","instructions":["Start out by grabbing single handle next to the low pulley machine. Make sure you are far enough from the machine so that your arm is supporting the weight.","Make sure that your upper arm is stationary, perpendicular to the floor with elbows in and palms facing forward. Your non lifting arm should be grabbing your waist. This will allow you to keep your balance.","Slowly begin to curl the single handle upwards while keeping the upper arm stationary until your forearm touches your bicep while exhaling. Tip: Only the forearm should move.","Hold the contraction position as you squeeze the bicep and then lower the single handle back down to the starting position as you inhale.","Repeat for the recommended amount of repetitions.","Switch arms while performing this exercise."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["standing one-arm cable curl"],"media":[{"id":"standing-one-arm-cable-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_One-Arm_Cable_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-one-arm-cable-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_One-Arm_Cable_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Bizeps.","instructions":null}},{"id":"ex-standing-one-arm-dumbbell-curl-over-incline-bench","slug":"standing-one-arm-dumbbell-curl-over-incline-bench","name":"Standing One-Arm Dumbbell Curl Over Incline Bench","description":"Dumbbell exercise for the biceps.","instructions":["Stand on the back side of an incline bench as if you were going to be a spotter for someone. Have a dumbbell in one hand and rest it across the incline bench with a supinated (palms up) grip.","Position your non lifting hand at the corner or side of the incline bench. The chest should be pressed against the top part of the incline and your feet should be pressed against the floor at a wide stance. This is the starting position.","While holding the upper arm stationary, curl the dumbbell upward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a second.","Slowly begin to bring the dumbbells back to starting position as your breathe in.","Repeat for the recommended amount of repetitions.","Switch arms while performing this exercise."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["standing one-arm dumbbell curl over incline bench"],"media":[{"id":"standing-one-arm-dumbbell-curl-over-incline-bench-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-one-arm-dumbbell-curl-over-incline-bench-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps.","instructions":null}},{"id":"ex-standing-one-arm-dumbbell-triceps-extension","slug":"standing-one-arm-dumbbell-triceps-extension","name":"Standing One-Arm Dumbbell Triceps Extension","description":"Dumbbell exercise for the triceps, with chest, shoulders assisting.","instructions":["To begin, stand up with a dumbbell held in one hand. Your feet should be about shoulder width apart from each other. Now fully extend the arm with the dumbbell over your head. Tip: The small finger of your hand should be facing the ceiling and the palm of your hand should be facing forward. The dumbbell should be above your head.","This will be your starting position.","Keeping your upper arm close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearm touch your bicep. Tip: The upper arm should remain stationary and only the forearm should move. Breathe in as you perform this step.","Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.","Repeat for the recommended amount of repetitions.","Switch arms and repeat the exercise."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"DUMBBELL","tags":["standing one-arm dumbbell triceps extension"],"media":[{"id":"standing-one-arm-dumbbell-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_One-Arm_Dumbbell_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-one-arm-dumbbell-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_One-Arm_Dumbbell_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-standing-overhead-barbell-triceps-extension","slug":"standing-overhead-barbell-triceps-extension","name":"Standing Overhead Barbell Triceps Extension","description":"Barbell exercise for the triceps, with shoulders assisting.","instructions":["To begin, stand up holding a barbell or e-z bar using a pronated grip (palms facing forward) with your hands closer than shoulder width apart from each other. Your feet should be about shoulder width apart.","Now elevate the barbell above your head until your arms are fully extended. Keep your elbows in. This will be your starting position.","Keeping your upper arms close to your head and elbows in, perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.","Go back to the starting position by using the triceps to raise the barbell. Breathe out as you perform this step.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["SHOULDERS"],"equipment":"BARBELL","tags":["standing overhead barbell triceps extension"],"media":[{"id":"standing-overhead-barbell-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Overhead_Barbell_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-overhead-barbell-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Overhead_Barbell_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Trizeps, unterstützt von Schultern.","instructions":null}},{"id":"ex-standing-palm-in-one-arm-dumbbell-press","slug":"standing-palm-in-one-arm-dumbbell-press","name":"Standing Palm-In One-Arm Dumbbell Press","description":"Dumbbell exercise for the shoulders, with triceps assisting.","instructions":["Start by having a dumbbell in one hand with your arm fully extended to the side using a neutral grip. Use your other arm to hold on to an incline bench to keep your balance.","Your feet should be shoulder width apart from each other. Now slowly lift the dumbbell up until you create a 90 degree angle with your arm. Note: Your forearm should be perpendicular to the floor. Continue to maintain a neutral grip throughout the entire exercise.","Slowly lift the dumbbell up until your arm is fully extended. This the starting position.","While inhaling lower the weight down until your arm is at a 90 degree angle again.","Feel the contraction for a second and then lift the weight back up towards the starting position while exhaling. Remember to hold on to the incline bench and keep your feet positioned to keep balance during the exercise.","Repeat for the recommended amount of repetitions.","Switch arms and repeat the exercise."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"DUMBBELL","tags":["standing palm-in one-arm dumbbell press"],"media":[{"id":"standing-palm-in-one-arm-dumbbell-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Palm-In_One-Arm_Dumbbell_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-palm-in-one-arm-dumbbell-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Palm-In_One-Arm_Dumbbell_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-standing-palms-in-dumbbell-press","slug":"standing-palms-in-dumbbell-press","name":"Standing Palms-In Dumbbell Press","description":"Dumbbell exercise for the shoulders, with triceps assisting.","instructions":["Start by having a dumbbell in each hand with your arm fully extended to the side using a neutral grip. Your feet should be shoulder width apart from each other. Now slowly lift the dumbbells up until you create a 90 degree angle with your arms. Note: Your forearms should be perpendicular to the floor. This the starting position.","Continue to maintain a neutral grip throughout the entire exercise. Slowly lift the dumbbells up until your arms are fully extended.","While inhaling lower the weights down until your arm is at a 90 degree angle again.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"DUMBBELL","tags":["standing palms-in dumbbell press"],"media":[{"id":"standing-palms-in-dumbbell-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Palms-In_Dumbbell_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-palms-in-dumbbell-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Palms-In_Dumbbell_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-standing-palms-up-barbell-behind-the-back-wrist-curl","slug":"standing-palms-up-barbell-behind-the-back-wrist-curl","name":"Standing Palms-Up Barbell Behind The Back Wrist Curl","description":"Barbell exercise for the forearms.","instructions":["Start by standing straight and holding a barbell behind your glutes at arm's length while using a pronated grip (palms will be facing back away from the glutes) and having your hands shoulder width apart from each other.","You should be looking straight forward while your feet are shoulder width apart from each other. This is the starting position.","While exhaling, slowly elevate the barbell up by curling your wrist in a semi-circular motion towards the ceiling. Note: Your wrist should be the only body part moving for this exercise.","Hold the contraction for a second and lower the barbell back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions.","When finished, lower the barbell down to the squat rack or the floor by bending the knees. Tip: It is easiest to either pick it up from a squat rack or have a partner hand it to you."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["standing palms-up barbell behind the back wrist curl"],"media":[{"id":"standing-palms-up-barbell-behind-the-back-wrist-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-palms-up-barbell-behind-the-back-wrist-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Unterarme.","instructions":null}},{"id":"ex-standing-pancake","slug":"standing-pancake","name":"Standing Pancake","description":"Bodyweight exercise for the hamstrings.","instructions":["Stand and open your legs as wide as possible into a straddle position. Then bend at the hips, pushing them back while keeping your back straight."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["standing pancake","stehender pancake"],"media":[],"source":"wger","de":{"name":"Stehender Pancake","description":"Übung (Körpergewicht) für die Oberschenkelrückseite.","instructions":["Stelle dich hin und öffne deine Beine so weit wie möglich in eine Grätsche. Beuge dich dann aus der Hüfte und schiebe sie nach hinten, während du den Rücken gerade hältst."]}},{"id":"ex-standing-pancake-good-morning","slug":"standing-pancake-good-morning","name":"Standing Pancake Good Morning","description":"Bodyweight exercise for the hamstrings.","instructions":["Stand with your feet wider than shoulder-width apart and toes pointed slightly outward. Place your hands on the back of your head. Hinge at your hips and lower your upper body towards the ground, keeping your back straight and chest open."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["standing pancake good morning","stehendes good morning mit weitem stand (pancake)"],"media":[],"source":"wger","de":{"name":"Stehendes Good Morning mit weitem Stand (Pancake)","description":"Übung (Körpergewicht) für die Oberschenkelrückseite.","instructions":["Stelle dich mit den Füßen mehr als schulterbreit auseinander und den Fußspitzen leicht nach außen. Lege deine Hände an den Hinterkopf. Beuge dich aus der Hüfte und senke deinen Oberkörper zum Boden, während du deinen Rücken gerade und die Brust offen hältst."]}},{"id":"ex-standing-pelvic-tilt","slug":"standing-pelvic-tilt","name":"Standing Pelvic Tilt","description":"Equipment-free exercise for the back, with glutes assisting.","instructions":["Start off with your feet hip-distance apart.","Bend your knees slightly to keep them soft and springy.","You may want to move your pelvis forward and backward and back few times before holding the tailbone forward in this stretch."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["GLUTES"],"equipment":"NONE","tags":["standing pelvic tilt"],"media":[{"id":"standing-pelvic-tilt-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Pelvic_Tilt/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-pelvic-tilt-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Pelvic_Tilt/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Rücken, unterstützt von Po.","instructions":null}},{"id":"ex-standing-rope-crunch","slug":"standing-rope-crunch","name":"Standing Rope Crunch","description":"Cable exercise for the core.","instructions":["Attach a rope to a high pulley and select an appropriate weight.","Stand with your back to the cable tower. Take the rope with both hands over your shoulders, holding it to your upper chest. This will be your starting position.","Perform the movement by flexing the spine, crunching the weight down as far as you can.","Hold the peak contraction for a moment before returning to the starting position."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["standing rope crunch"],"media":[{"id":"standing-rope-crunch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Rope_Crunch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-rope-crunch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Rope_Crunch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rumpf.","instructions":null}},{"id":"ex-standing-rope-forearm","slug":"standing-rope-forearm","name":"Standing Rope Forearm","description":"Bodyweight exercise for the biceps.","instructions":["Grab a wrist roller tool with both hands while standing with your feet about shoulder width apart. If your gym does not have a wrist roller tool, you can easily put one together. All you need is a 5 or 10 pound weight plate, a strong thin rope about 3 feet long and a 6-8 inch stick or bar. Securely fasten the rope to the middle of the bar/stick and tie the other end of the rope to the weight plate. To begin this exercise, grab the bar/stick with both hands using an overhand grip. Extend both arms straight out in front of you, parallel to the floor. Next, roll the weight up from the floor by rapidly twisting the bar/stick with your hands and wrists. Once the weight reaches the top, slowly lower the plate back to the floor by reversing the motion of your hands and wrists. Repeat (if you can!)."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["standing rope forearm","unterarmtraining mit rollstange im stehen"],"media":[],"source":"wger","de":{"name":"Unterarmtraining mit Rollstange im Stehen","description":"Übung (Körpergewicht) für den Bizeps.","instructions":["Greife eine Unterarmrolle mit beiden Händen, während du mit etwa schulterbreit auseinander stehenden Füßen stehst. Falls dein Fitnessstudio keine Unterarmrolle hat, kannst du ganz leicht selbst eine bauen. Alles, was du brauchst, ist eine Gewichtsscheibe mit 5 oder 10 Pfund, ein starkes, dünnes Seil von etwa 90 cm Länge und ein 15 bis 20 cm langer Stab oder eine Stange. Befestige das Seil sicher in der Mitte der Stange bzw. des Stabs und binde das andere Ende des Seils an die Gewichtsscheibe. Um diese Übung zu beginnen, greife die Stange bzw. den Stab mit beiden Händen im Obergriff. Strecke beide Arme gerade vor dir aus, parallel zum Boden. Rolle als Nächstes das Gewicht vom Boden hoch, indem du die Stange bzw. den Stab schnell mit deinen Händen und Handgelenken drehst. Sobald das Gewicht oben angekommen ist, senke die Scheibe langsam wieder zum Boden, indem du die Bewegung deiner Hände und Handgelenke umkehrst. Wiederhole (wenn du kannst!)."]}},{"id":"ex-standing-side-crunches","slug":"standing-side-crunches","name":"Standing Side Crunches","description":"Bodyweight exercise for the core.","instructions":["Standing side crunches are a dynamic exercise that targets the obliques while improving balance and stability. Stand upright with your feet shoulder-width apart and hands behind your head or holding a dumbbell in one hand. Lean your torso to one side, contracting your obliques, while bringing your elbow toward your hip (or crunching toward the weight if using a dumbbell). Return to the starting position and alternate sides or perform all repetitions on one side before switching."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["standing side crunches","stehende seitliche crunches"],"media":[],"source":"wger","de":{"name":"Stehende seitliche Crunches","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Stehende seitliche Crunches sind eine dynamische Übung, die die seitliche Bauchmuskulatur beansprucht und zugleich Gleichgewicht und Stabilität verbessert. Stelle dich aufrecht hin, die Füße schulterbreit auseinander und die Hände hinter dem Kopf oder mit einer Kurzhantel in einer Hand. Neige deinen Oberkörper zu einer Seite, spanne dabei deine seitliche Bauchmuskulatur an und führe deinen Ellbogen in Richtung deiner Hüfte (oder crunche in Richtung des Gewichts, wenn du eine Kurzhantel verwendest). Kehre in die Startposition zurück und wechsle die Seiten ab oder führe alle Wiederholungen auf einer Seite aus, bevor du wechselst."]}},{"id":"ex-standing-soleus-and-achilles-stretch","slug":"standing-soleus-and-achilles-stretch","name":"Standing Soleus And Achilles Stretch","description":"Equipment-free exercise for the calves.","instructions":["Stand with your feet hip-distance apart, one foot slightly in front of the other.","Bend both knees, keeping your back heel on the floor. Switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"CALVES","secondaryMuscleGroups":[],"equipment":"NONE","tags":["standing soleus and achilles stretch"],"media":[{"id":"standing-soleus-and-achilles-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Soleus_And_Achilles_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-soleus-and-achilles-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Soleus_And_Achilles_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Waden.","instructions":null}},{"id":"ex-standing-toe-touches","slug":"standing-toe-touches","name":"Standing Toe Touches","description":"Equipment-free exercise for the hamstrings, with calves assisting.","instructions":["Stand with some space in front and behind you.","Bend at the waist, keeping your legs straight, until you can relax and let your upper body hang down in front of you. Let your arms and hands hang down naturally. Hold for 10 to 20 seconds."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["CALVES"],"equipment":"NONE","tags":["standing toe touches"],"media":[{"id":"standing-toe-touches-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Toe_Touches/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-toe-touches-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Toe_Touches/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelrückseite, unterstützt von Waden.","instructions":null}},{"id":"ex-standing-towel-triceps-extension","slug":"standing-towel-triceps-extension","name":"Standing Towel Triceps Extension","description":"Bodyweight exercise for the triceps.","instructions":["To begin, stand up with both arms fully extended above the head holding one end of a towel with both hands. Your elbows should be in and the arms perpendicular to the floor with the palms facing each other while your feet should be shoulder width apart from each other. This is the starting position.","Now communicate with your partner so that he/she can grip the other side of the towel to apply resistance. Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.","Go back to the starting position by using the triceps to raise the towel. Breathe out as you perform this step.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["standing towel triceps extension"],"media":[{"id":"standing-towel-triceps-extension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Towel_Triceps_Extension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-towel-triceps-extension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Towel_Triceps_Extension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Trizeps.","instructions":null}},{"id":"ex-standing-two-arm-overhead-throw","slug":"standing-two-arm-overhead-throw","name":"Standing Two-Arm Overhead Throw","description":"Accessory exercise for the shoulders, with chest, back assisting.","instructions":["Stand with your feet shoulder width apart holding a medicine ball in both hands. To begin, reach the medicine ball deep behind your head as you bend the knees slightly and lean back.","Violently throw the ball forward, flexing at the hip and using your whole body to complete the movement.","The medicine ball can be thrown to a partner or to a wall, receiving it as it bounces back."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CHEST","BACK"],"equipment":"OTHER","tags":["standing two-arm overhead throw"],"media":[{"id":"standing-two-arm-overhead-throw-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Two-Arm_Overhead_Throw/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"standing-two-arm-overhead-throw-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Two-Arm_Overhead_Throw/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Schultern, unterstützt von Brust, Rücken.","instructions":null}},{"id":"ex-star-jump","slug":"star-jump","name":"Star Jump","description":"Bodyweight exercise for the quadriceps, with calves, glutes, hamstrings, shoulders assisting.","instructions":["Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.","To initiate the move, squat down halfway and explode back up as high as possible. Fully extend your entire body, spreading your legs and arms away from the body.","As you land, bring your limbs back in and absorb your impact through the legs."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","SHOULDERS"],"equipment":"BODYWEIGHT","tags":["star jump"],"media":[{"id":"star-jump-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Star_Jump/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"star-jump-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Star_Jump/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Schultern.","instructions":null}},{"id":"ex-step-up-with-knee-raise","slug":"step-up-with-knee-raise","name":"Step-up with Knee Raise","description":"Bodyweight exercise for the glutes, with hamstrings, quadriceps assisting.","instructions":["Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.","Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.","Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["HAMSTRINGS","QUADRICEPS"],"equipment":"BODYWEIGHT","tags":["step-up with knee raise"],"media":[{"id":"step-up-with-knee-raise-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Step-up_with_Knee_Raise/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"step-up-with-knee-raise-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Step-up_with_Knee_Raise/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelrückseite, Oberschenkelvorderseite.","instructions":null}},{"id":"ex-step-ups","slug":"step-ups","name":"Step-ups","description":"Bodyweight exercise for the glutes, with quadriceps, hamstrings, calves assisting.","instructions":["Starting position:","Stand facing a chair.","Steps:","Step up onto the chair.","Step off the chair.","Repeat."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["QUADRICEPS","HAMSTRINGS","CALVES"],"equipment":"BODYWEIGHT","tags":["step-ups","steigungen"],"media":[{"id":"step-ups-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/981/f9377a7e-eb58-4cca-b805-2d36863aeb03.png","caption":"Step-ups","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Steigungen","description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelvorderseite, Oberschenkelrückseite, Waden.","instructions":["Ausgangsposition:","Stellen Sie sich vor einen Stuhl.","Schritte:","Steigen Sie auf den Stuhl.","Steigen Sie vom Stuhl ab.","Wiederholen Sie"]}},{"id":"ex-stiff-leg-barbell-good-morning","slug":"stiff-leg-barbell-good-morning","name":"Stiff Leg Barbell Good Morning","description":"Barbell exercise for the back, with glutes, hamstrings assisting.","instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position.","Keeping your legs stationary, move your torso forward by bending at the hips while inhaling. Lower your torso until it is parallel with the floor.","Begin to raise the bar as you exhale by elevating your torso back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["GLUTES","HAMSTRINGS"],"equipment":"BARBELL","tags":["stiff leg barbell good morning"],"media":[{"id":"stiff-leg-barbell-good-morning-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff_Leg_Barbell_Good_Morning/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"stiff-leg-barbell-good-morning-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff_Leg_Barbell_Good_Morning/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-stiff-legged-barbell-deadlift","slug":"stiff-legged-barbell-deadlift","name":"Stiff-Legged Barbell Deadlift","description":"Barbell exercise for the hamstrings, with glutes, back assisting.","instructions":["Grasp a bar using an overhand grip (palms facing down). You may need some wrist wraps if using a significant amount of weight.","Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.","Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the hips while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Inhale as you perform this movement.","Start bringing your torso up straight again by extending your hips until you are back at the starting position. Exhale as you perform this movement.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","BACK"],"equipment":"BARBELL","tags":["stiff-legged barbell deadlift"],"media":[{"id":"stiff-legged-barbell-deadlift-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Barbell_Deadlift/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"stiff-legged-barbell-deadlift-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Barbell_Deadlift/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Po, Rücken.","instructions":null}},{"id":"ex-stiff-legged-dumbbell-deadlift","slug":"stiff-legged-dumbbell-deadlift","name":"Stiff-Legged Dumbbell Deadlift","description":"Dumbbell exercise for the hamstrings, with glutes, back assisting.","instructions":["Grasp a couple of dumbbells holding them by your side at arm's length.","Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.","Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement","Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","BACK"],"equipment":"DUMBBELL","tags":["stiff-legged dumbbell deadlift"],"media":[{"id":"stiff-legged-dumbbell-deadlift-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Dumbbell_Deadlift/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"stiff-legged-dumbbell-deadlift-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Dumbbell_Deadlift/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Oberschenkelrückseite, unterstützt von Po, Rücken.","instructions":null}},{"id":"ex-stomach-vacuum","slug":"stomach-vacuum","name":"Stomach Vacuum","description":"Bodyweight exercise for the core.","instructions":["To begin, stand straight with your feet shoulder width apart from each other. Place your hands on your hips. This is the starting position.","Now slowly inhale as much air as possible and then start to exhale as much as possible while bringing your stomach in as much as possible and hold this position. Try to visualize your navel touching your backbone.","One isometric contraction is around 20 seconds. During the 20 second hold, try to breathe normally. Then inhale and bring your stomach back to the starting position.","Once you have practiced this exercise, try to perform this exercise for longer than 20 seconds. Tip: You can work your way up to 40-60 seconds.","Repeat for the recommended amount of sets."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["stomach vacuum"],"media":[{"id":"stomach-vacuum-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stomach_Vacuum/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"stomach-vacuum-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stomach_Vacuum/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-straight-arm-dumbbell-pullover","slug":"straight-arm-dumbbell-pullover","name":"Straight-Arm Dumbbell Pullover","description":"Dumbbell exercise for the chest, with back, shoulders, triceps assisting.","instructions":["Place a dumbbell standing up on a flat bench.","Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.","Grasp the dumbbell with both hands and hold it straight over your chest at arms length. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position.\nCaution: Always ensure that the dumbbell used for this exercise is secure. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.","While keeping your arms straight, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.","At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.","Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["BACK","SHOULDERS","TRICEPS"],"equipment":"DUMBBELL","tags":["straight-arm dumbbell pullover"],"media":[{"id":"straight-arm-dumbbell-pullover-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Straight-Arm_Dumbbell_Pullover/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"straight-arm-dumbbell-pullover-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Straight-Arm_Dumbbell_Pullover/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Brust, unterstützt von Rücken, Schultern, Trizeps.","instructions":null}},{"id":"ex-straight-arm-pull-down-bar-attachment","slug":"straight-arm-pull-down-bar-attachment","name":"Straight-arm Pull Down (bar Attachment)","description":"Cable exercise for the back, with triceps assisting.","instructions":["Use the straight bar attachment on a high pulley. Grasp the two ends of the bar with your palms facing downward and your arms straight out in front of you. Pull your hands down towards your hips, while keeping your arms straight, then raise them back up to the starting position."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["TRICEPS"],"equipment":"CABLE","tags":["straight-arm pull down (bar attachment)","lat-ziehen mit gesteckten armen mit (stange)"],"media":[],"source":"wger","de":{"name":"Lat-Ziehen Mit Gesteckten Armen Mit (Stange)","description":"Übung (Kabelzug) für den Rücken, unterstützt von Trizeps.","instructions":["Verwenden Sie den Aufsatz für die gerade Stange. Fassen Sie die beiden Enden der Stange mit den Handflächen nach unten und den Armen gerade vor Ihnen. Ziehen Sie Ihre Hände nach unten in Richtung Ihrer Hüften, während Sie Ihre Arme gerade halten, und heben Sie sie dann wieder in die Ausgangsposition."]}},{"id":"ex-straight-bar-bench-mid-rows","slug":"straight-bar-bench-mid-rows","name":"Straight Bar Bench Mid Rows","description":"Barbell exercise for the back, with biceps assisting.","instructions":["Place a loaded barbell on the end of a bench. Standing on the bench behind the bar, take a medium, pronated grip. Stand with your hips back and chest up, maintaining a neutral spine. This will be your starting position.","Row the bar to your torso by retracting the shoulder blades and flexing the elbows. Use a controlled movement with no jerking.","After a brief pause, slowly return the bar to the starting position, ensuring to go all the way down."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"BARBELL","tags":["straight bar bench mid rows"],"media":[{"id":"straight-bar-bench-mid-rows-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Straight_Bar_Bench_Mid_Rows/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"straight-bar-bench-mid-rows-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Straight_Bar_Bench_Mid_Rows/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-straight-raises-on-incline-bench","slug":"straight-raises-on-incline-bench","name":"Straight Raises on Incline Bench","description":"Barbell exercise for the shoulders, with back assisting.","instructions":["Place a bar on the ground behind the head of an incline bench.","Lay on the bench face down. With a pronated grip, pick the barbell up from the floor, keeping your arms straight. Allow the bar to hang straight down. This will be your starting position.","To begin, raise the barbell out in front of your head while keeping your arms extended.","Return to the starting position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"BARBELL","tags":["straight raises on incline bench"],"media":[{"id":"straight-raises-on-incline-bench-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Straight_Raises_on_Incline_Bench/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"straight-raises-on-incline-bench-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Straight_Raises_on_Incline_Bench/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Schultern, unterstützt von Rücken.","instructions":null}},{"id":"ex-stride-jump-crossover","slug":"stride-jump-crossover","name":"Stride Jump Crossover","description":"Accessory exercise for the quadriceps, with glutes, calves, hamstrings assisting.","instructions":["Stand to the side of a box with your inside foot on top of it, close to the edge.","Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward.","Land in the opposite position that you started, on the opposite side of the box. The foot that was initially on the box will now be on the ground, with the opposite foot now on the box.","Repeat the movement, crossing back over to the other side."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","CALVES","HAMSTRINGS"],"equipment":"OTHER","tags":["stride jump crossover"],"media":[{"id":"stride-jump-crossover-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stride_Jump_Crossover/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"stride-jump-crossover-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stride_Jump_Crossover/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite, unterstützt von Po, Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-sumo-deadlift","slug":"sumo-deadlift","name":"Sumo Deadlift","description":"Barbell exercise for the hamstrings, with quadriceps, forearms, glutes, back assisting.","instructions":["Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.","Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.","As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.","Return the weight to the ground by bending at the hips and controlling the weight on the way down."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["QUADRICEPS","FOREARMS","GLUTES","BACK"],"equipment":"BARBELL","tags":["sumo deadlift","sumo kreuzheben"],"media":[{"id":"sumo-deadlift-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sumo_Deadlift/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"sumo-deadlift-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sumo_Deadlift/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Sumo Kreuzheben","description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Oberschenkelvorderseite, Unterarme, Po, Rücken.","instructions":["Muskulatur anspannen","Rücken aufrecht halten","Rücken gerade halten","Langsame Bewegung","Kontrollierte Bewegung","Nicht überdehnen"]}},{"id":"ex-sumo-deadlift-with-bands","slug":"sumo-deadlift-with-bands","name":"Sumo Deadlift with Bands","description":"Barbell exercise for the hamstrings, with quadriceps, forearms, glutes, back assisting.","instructions":["To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. Ensure that they under the back half of your foot, directly where you are driving into the floor.","Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip.","Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.","As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.","Return the weight to the ground by bending at the hips and controlling the weight on the way down."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["QUADRICEPS","FOREARMS","GLUTES","BACK"],"equipment":"BARBELL","tags":["sumo deadlift with bands"],"media":[{"id":"sumo-deadlift-with-bands-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sumo_Deadlift_with_Bands/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"sumo-deadlift-with-bands-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sumo_Deadlift_with_Bands/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Oberschenkelvorderseite, Unterarme, Po, Rücken.","instructions":null}},{"id":"ex-sumo-deadlift-with-chains","slug":"sumo-deadlift-with-chains","name":"Sumo Deadlift with Chains","description":"Barbell exercise for the hamstrings, with glutes, quadriceps, forearms, back assisting.","instructions":["You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift. Attempt to keep the ends of the chains away from the plates so you don't hit them when you lower the weight.","Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.","Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.","As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.","Return the weight to the ground by bending at the hips and controlling the weight on the way down."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","QUADRICEPS","FOREARMS","BACK"],"equipment":"BARBELL","tags":["sumo deadlift with chains"],"media":[{"id":"sumo-deadlift-with-chains-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sumo_Deadlift_with_Chains/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"sumo-deadlift-with-chains-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sumo_Deadlift_with_Chains/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Po, Oberschenkelvorderseite, Unterarme, Rücken.","instructions":null}},{"id":"ex-sumo-squats","slug":"sumo-squats","name":"Sumo Squats","description":"Bodyweight exercise for the glutes, with quadriceps assisting.","instructions":["Stand with your feet wider than your shoulders, with your toes pointed out at a 45 degree angle and barbell on your shoulder.","While keeping your back straight, descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself until your quadriceps and hamstrings are parallel to the floor.","Return to the starting position by pressing upwards and extending your legs while maintaining an equal distribution of weight on your forefoot and heel."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["QUADRICEPS"],"equipment":"BODYWEIGHT","tags":["sumo squats","sumo kniebeuge"],"media":[],"source":"wger","de":{"name":"Sumo Kniebeuge","description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelvorderseite.","instructions":["Variante der Kniebeuge: breiter Stand, Füße leicht nach außen","Optional mit Langhantel oder Kettlebell (Kugelhantel) vor der Brust"]}},{"id":"ex-superman","slug":"superman","name":"Superman","description":"Bodyweight exercise for the back, with glutes, hamstrings assisting.","instructions":["To begin, lie straight and face down on the floor or exercise mat. Your arms should be fully extended in front of you. This is the starting position.","Simultaneously raise your arms, legs, and chest off of the floor and hold this contraction for 2 seconds. Tip: Squeeze your lower back to get the best results from this exercise. Remember to exhale during this movement. Note: When holding the contracted position, you should look like superman when he is flying.","Slowly begin to lower your arms, legs and chest back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions prescribed in your program."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["GLUTES","HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["superman"],"media":[{"id":"superman-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Superman/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"superman-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Superman/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Superman","description":"Übung (Körpergewicht) für den Rücken, unterstützt von Po, Oberschenkelrückseite.","instructions":["Legen Sie sich flach auf den Bauch und strecken Sie die Arme vor sich auf den Boden, während Ihre Beine flach liegen. Heben Sie beide Arme und Beine gleichzeitig an, als ob Sie fliegen würden, und ziehen Sie den unteren Rücken zusammen. Stellen Sie sicher, dass Sie atmen und halten Sie die Bewegung, abhängig von Ihrer Fitness, mindestens zwei bis fünf Sekunden pro Wiederholung."]}},{"id":"ex-supine-chest-throw","slug":"supine-chest-throw","name":"Supine Chest Throw","description":"Accessory exercise for the triceps, with chest, shoulders assisting.","instructions":["This drill is great for chest passes when you lack a partner or a wall of sufficient strength. Lay on the ground on your back with your knees bent.","Begin with the ball on your chest, held with both hands on the bottom.","Explode up, extending through the elbow to throw the ball directly above you as high as possible.","Catch the ball with both hands as it comes down."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"OTHER","tags":["supine chest throw"],"media":[{"id":"supine-chest-throw-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Supine_Chest_Throw/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"supine-chest-throw-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Supine_Chest_Throw/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-supine-hip-abduction","slug":"supine-hip-abduction","name":"Supine Hip Abduction","description":"Dumbbell exercise for the glutes, with quadriceps assisting.","instructions":["Starting Position:","Lie on your back (supine) on a mat, with your legs extended and","relaxed. Arms can be placed alongside your body or out to the sides for","stability.","The Movement:","Slightly lift one leg off the floor (keeping it straight or with a","slight bend). Move it laterally outward, away from the other leg, as if","stepping over a small obstacle."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["QUADRICEPS"],"equipment":"DUMBBELL","tags":["supine hip abduction","hüftabduktion in rückenlage"],"media":[],"source":"wger","de":{"name":"Hüftabduktion in Rückenlage","description":"Übung (Kurzhantel) für den Po, unterstützt von Oberschenkelvorderseite.","instructions":["Ausgangsposition:","Lege dich auf den Rücken (Rückenlage) auf eine Matte, mit gestreckten und","entspannten Beinen. Die Arme kannst du seitlich am Körper oder zur Seite ausgestreckt","für mehr Stabilität ablegen.","Die Bewegung:","Hebe ein Bein leicht vom Boden ab (halte es gestreckt oder mit einer","leichten Beugung). Bewege es seitlich nach außen, weg vom anderen Bein, als würdest","du über ein kleines Hindernis steigen."]}},{"id":"ex-supine-one-arm-overhead-throw","slug":"supine-one-arm-overhead-throw","name":"Supine One-Arm Overhead Throw","description":"Accessory exercise for the core, with chest, back, shoulders assisting.","instructions":["Lay on the ground on your back with your knees bent. Hold the ball with one hand, extending the arm fully behind your head. This will be your starting position.","Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance.","The ball can be thrown to a partner or bounced off of a wall."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["CHEST","BACK","SHOULDERS"],"equipment":"OTHER","tags":["supine one-arm overhead throw"],"media":[{"id":"supine-one-arm-overhead-throw-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Supine_One-Arm_Overhead_Throw/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"supine-one-arm-overhead-throw-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Supine_One-Arm_Overhead_Throw/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rumpf, unterstützt von Brust, Rücken, Schultern.","instructions":null}},{"id":"ex-supine-two-arm-overhead-throw","slug":"supine-two-arm-overhead-throw","name":"Supine Two-Arm Overhead Throw","description":"Accessory exercise for the core, with chest, back, shoulders assisting.","instructions":["Lay on the ground on your back with your knees bent.","Hold the ball with both hands, extending the arms fully behind your head. This will be your starting position.","Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance.","The ball can be thrown to a partner or bounced off of a wall."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["CHEST","BACK","SHOULDERS"],"equipment":"OTHER","tags":["supine two-arm overhead throw"],"media":[{"id":"supine-two-arm-overhead-throw-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Supine_Two-Arm_Overhead_Throw/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"supine-two-arm-overhead-throw-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Supine_Two-Arm_Overhead_Throw/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rumpf, unterstützt von Brust, Rücken, Schultern.","instructions":null}},{"id":"ex-suspended-fallout","slug":"suspended-fallout","name":"Suspended Fallout","description":"Accessory exercise for the core, with chest, back, shoulders assisting.","instructions":["Adjust the straps so the handles are at an appropriate height, below waist level.","Begin standing and grasping the handles. Lean into the straps, moving to an incline push-up position. This will be your starting position.","Keeping your arms straight, lean further into the suspension straps, bringing your body closer to the ground, allowing your shoulders to extend, raising your arms up and over your head.","Maintain a neutral spine and keep the rest of your body straight, your shoulders being the only joints allowed to move.","Pause during the peak contraction, and then return to the starting position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["CHEST","BACK","SHOULDERS"],"equipment":"OTHER","tags":["suspended fallout"],"media":[{"id":"suspended-fallout-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Fallout/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"suspended-fallout-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Fallout/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rumpf, unterstützt von Brust, Rücken, Schultern.","instructions":null}},{"id":"ex-suspended-push-up","slug":"suspended-push-up","name":"Suspended Push-Up","description":"Accessory exercise for the chest, with shoulders, triceps assisting.","instructions":["Anchor your suspension straps securely to the top of a rack or other object.","Leaning into the straps, take a handle in each hand and move into a push-up plank position. You should be as close to parallel to the ground as you can manage with your arms fully extended, maintaining good posture.","Maintaining a straight, rigid torso, descend slowly by allowing the elbows to flex.","Continue until your elbows break 90 degrees, pausing before you extend to return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"OTHER","tags":["suspended push-up"],"media":[{"id":"suspended-push-up-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Push-Up/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"suspended-push-up-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Push-Up/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-suspended-reverse-crunch","slug":"suspended-reverse-crunch","name":"Suspended Reverse Crunch","description":"Accessory exercise for the core.","instructions":["Secure a set of suspension straps with the handles hanging about a foot off of the ground. Move yourself into a pushup plank position facing away from the rack.","Place your feet into the handles. You should maintain a straight posture, not allowing the hips to sag. This will be your starting position.","Begin the movement by flexing the knees and hips, drawing the knees to your torso. As you do so, anteriorly tilt your pelvis, allowing your spine to flex.","At the top of the controlled motion, return to the starting position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["suspended reverse crunch"],"media":[{"id":"suspended-reverse-crunch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Reverse_Crunch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"suspended-reverse-crunch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Reverse_Crunch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rumpf.","instructions":null}},{"id":"ex-suspended-row","slug":"suspended-row","name":"Suspended Row","description":"Accessory exercise for the back, with biceps assisting.","instructions":["Suspend your straps at around chest height. Take a handle in each hand and lean back. Keep your body erect and your head and chest up. Your arms should be fully extended. This will be your starting position.","Begin by flexing the elbow to initiate the movement. Protract your shoulder blades as you do so.","At the completion of the motion pause, and then return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"OTHER","tags":["suspended row"],"media":[{"id":"suspended-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"suspended-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-suspended-split-squat","slug":"suspended-split-squat","name":"Suspended Split Squat","description":"Accessory exercise for the quadriceps, with glutes, calves, hamstrings assisting.","instructions":["Suspend your straps so the handles are 18-30 inches from the floor.","Facing away from the setup, place your rear foot into the handle behind you. Keep your head looking forward and your chest up, with your knee slightly bent. This will be your starting position.","Descend by flexing the knee and hips, lowering yourself to the ground. Keep your weight on the heel of your foot and maintain your posture throughout the exercise.","At the bottom of the movement, reverse the motion, extending through the hip and knee to return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","CALVES","HAMSTRINGS"],"equipment":"OTHER","tags":["suspended split squat"],"media":[{"id":"suspended-split-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Split_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"suspended-split-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Split_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite, unterstützt von Po, Waden, Oberschenkelrückseite.","instructions":null}},{"id":"ex-svend-press","slug":"svend-press","name":"Svend Press","description":"Accessory exercise for the chest, with forearms, shoulders, triceps assisting.","instructions":["Begin in a standing position.","Press two lightweight plates together with your hands. Hold the plates together close to your chest to create an isometric contraction in your chest muscles. Your fingers should be pointed forward. This is your starting position.","Squeeze the plates between your palms and extend your arms directly out in front of you in a controlled motion.","Pause at the top of the motion, and then slowly return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["FOREARMS","SHOULDERS","TRICEPS"],"equipment":"OTHER","tags":["svend press"],"media":[{"id":"svend-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Svend_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"svend-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Svend_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Brust, unterstützt von Unterarme, Schultern, Trizeps.","instructions":null}},{"id":"ex-t-bar-row-with-handle","slug":"t-bar-row-with-handle","name":"T-Bar Row with Handle","description":"Barbell exercise for the back, with biceps assisting.","instructions":["Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.","Stand over the bar, and position a Double D row handle around the bar next to the collar. Using your hips and legs, rise to a standing position.","Assume a wide stance with your hips back and your chest up. Your arms should be extended. This will be your starting position.","Pull the weight to your upper abdomen by retracting the shoulder blades and flexing the elbows. Do not jerk the weight or cheat during the movement.","After a brief pause, return to the starting position."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"BARBELL","tags":["t-bar row with handle"],"media":[{"id":"t-bar-row-with-handle-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"t-bar-row-with-handle-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-tate-press","slug":"tate-press","name":"Tate Press","description":"Dumbbell exercise for the triceps, with chest, shoulders assisting.","instructions":["Lie down on a flat bench with a dumbbell in each hand on top of your thighs. The palms of your hand will be facing each other.","By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them in front of you at shoulder width. Note: when holding the dumbbells in front of you, make sure your arms are wider than shoulder width apart from each other using a pronated (palms forward) grip. Allow your elbows to point out. This is your starting position.","Keeping the upper arms stationary, slowly move the dumbbells in and down in a semi circular motion until they touch the upper chest while inhaling. Keep full control of the dumbbells at all times and do not move the upper arms nor rest the dumbbells on the chest.","As you breathe out, move the dumbbells up using your triceps and the same semi-circular motion but in reverse. Attempt to keep the dumbbells together as they move up. Lock your arms in the contracted position, hold for a second and then start coming down again slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions of your training program."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"DUMBBELL","tags":["tate press"],"media":[{"id":"tate-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tate_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"tate-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tate_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-the-straddle","slug":"the-straddle","name":"The Straddle","description":"Equipment-free exercise for the hamstrings, with quadriceps, calves assisting.","instructions":["Begin in a seated, upright position. Start by extending your legs in front of you in a V.","With your hands on the floor, lean forward as far as possible. Hold for 10 to 20 seconds."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["QUADRICEPS","CALVES"],"equipment":"NONE","tags":["the straddle"],"media":[{"id":"the-straddle-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/The_Straddle/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"the-straddle-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/The_Straddle/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelrückseite, unterstützt von Oberschenkelvorderseite, Waden.","instructions":null}},{"id":"ex-thigh-adductor","slug":"thigh-adductor","name":"Thigh Adductor","description":"Machine exercise for the quadriceps, with glutes, hamstrings assisting.","instructions":["To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.","Slowly press against the machine with your legs to move them towards each other while exhaling.","Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.","Repeat for the recommended amount of repetitions."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","HAMSTRINGS"],"equipment":"MACHINE","tags":["thigh adductor"],"media":[{"id":"thigh-adductor-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Thigh_Adductor/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"thigh-adductor-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Thigh_Adductor/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Maschine) für die Oberschenkelvorderseite, unterstützt von Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-toe-touch","slug":"toe-touch","name":"Toe Touch","description":"Bodyweight exercise for the hamstrings, with glutes, calves assisting.","instructions":["Stand with your feet closer together. Hinge at your hips and lower your upper body towards your toes. Reach your hands towards your feet, try to touch your toes, the ground, or as far down your legs as you can comfortably go."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","CALVES"],"equipment":"BODYWEIGHT","tags":["toe touch","zehenberührung"],"media":[],"source":"wger","de":{"name":"Zehenberührung","description":"Übung (Körpergewicht) für die Oberschenkelrückseite, unterstützt von Po, Waden.","instructions":["Stelle dich mit den Füßen enger zusammen hin. Beuge dich aus der Hüfte und senke deinen Oberkörper in Richtung deiner Zehen. Strecke deine Hände zu den Füßen und versuche, deine Zehen, den Boden oder so weit nach unten an deinen Beinen zu reichen, wie es dir angenehm möglich ist."]}},{"id":"ex-toe-touchers","slug":"toe-touchers","name":"Toe Touchers","description":"Bodyweight exercise for the core.","instructions":["To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.","Your legs should be touching each other. Slowly elevate your legs up in the air until they are almost perpendicular to the floor with a slight bend at the knees. Your feet should be parallel to the floor.","Move your arms so that they are fully extended at a 45 degree angle from the floor. This is the starting position.","While keeping your lower back pressed against the floor, slowly lift your torso and use your hands to try and touch your toes. Remember to exhale while perform this part of the exercise.","Slowly begin to lower your torso and arms back down to the starting position while inhaling. Remember to keep your arms straight out pointing towards your toes.","Repeat for the recommended amount of repetitions."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["toe touchers"],"media":[{"id":"toe-touchers-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Toe_Touchers/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"toe-touchers-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Toe_Touchers/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-torso-rotation","slug":"torso-rotation","name":"Torso Rotation","description":"Accessory exercise for the core.","instructions":["Stand upright holding an exercise ball with both hands. Extend your arms so the ball is straight out in front of you. This will be your starting position.","Rotate your torso to one side, keeping your eyes on the ball as you move. Now, rotate back to the opposite direction. Repeat for 10-20 repetitions."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["torso rotation","rumpfdrehung"],"media":[{"id":"torso-rotation-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Torso_Rotation/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"torso-rotation-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Torso_Rotation/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Rumpfdrehung","description":"Übung (Hilfsmittel) für den Rumpf.","instructions":["Rumpfdrehung im Stehen: Beanspruche deinen Rumpf und verbessere deine Beweglichkeit mit dieser dynamischen Übung im Stehen! Bei der Rumpfdrehung im Stehen drehst du deinen Oberkörper, während du Füße und Hüfte stabil hältst, deine schrägen Bauchmuskeln anspannst und deinen gesamten Oberkörper dehnst. Diese Bewegung hilft dabei: die Rumpfmuskulatur zu kräftigen, die Beweglichkeit von Wirbelsäule und Oberkörper zu erhöhen, die Haltung und das Gleichgewicht zu verbessern und die allgemeine sportliche Leistung zu steigern. Führe 3 Sätze mit je 10-15 Wiederholungen aus, indem du dich zu jeder Seite drehst, um die Vorteile dieser wirksamen und effizienten Übung zu spüren!"]}},{"id":"ex-torso-rotation-stretch","slug":"torso-rotation-stretch","name":"Torso rotation stretch","description":"Bodyweight exercise for the core, with chest assisting.","instructions":["The torso rotation stretch helps improve spinal mobility and relieves tension in the lower back and obliques. It can be performed standing or seated.","Standing Variation: Stand upright with your feet shoulder-width apart. Place your hands on your hips or extend your arms in front of you. Slowly rotate your torso to one side, keeping your hips stable. Hold for a few seconds, then rotate to the opposite side.","Seated Variation: Sit on a chair with your feet flat on the floor. Place one hand on the outside of your opposite thigh and gently twist your torso toward that side. Hold the stretch before switching sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["CHEST"],"equipment":"BODYWEIGHT","tags":["torso rotation stretch","rumpfrotations-dehnung"],"media":[],"source":"wger","de":{"name":"Rumpfrotations-Dehnung","description":"Übung (Körpergewicht) für den Rumpf, unterstützt von Brust.","instructions":["Die Rumpfrotations-Dehnung hilft, die Beweglichkeit der Wirbelsäule zu verbessern und Verspannungen im unteren Rücken und in der seitlichen Bauchmuskulatur zu lösen. Sie kann im Stehen oder im Sitzen ausgeführt werden.","Stehende Variante: Stehe aufrecht mit den Füßen schulterbreit auseinander. Lege die Hände auf die Hüften oder strecke die Arme vor dir aus. Drehe den Oberkörper langsam zu einer Seite und halte die Hüften stabil. Halte die Position für ein paar Sekunden und drehe dich dann zur anderen Seite.","Sitzende Variante: Setze dich auf einen Stuhl mit flach auf dem Boden stehenden Füßen. Lege eine Hand an die Außenseite des gegenüberliegenden Oberschenkels und drehe deinen Oberkörper sanft zu dieser Seite. Halte die Dehnung, bevor du die Seite wechselst."]}},{"id":"ex-towel-superman","slug":"towel-superman","name":"Towel Superman","description":"Bodyweight exercise for the back, with shoulders assisting.","instructions":["In this exercise, you lie flat on your stomach, hold a","towel with your arms extended in front of you, and pull it apart to","create tension. Then, you move it forward and back under your stomach.","This exercise targets the back and shoulder muscles as well as core","stability."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["SHOULDERS"],"equipment":"BODYWEIGHT","tags":["towel superman","handtuch-superman"],"media":[],"source":"wger","de":{"name":"Handtuch-Superman","description":"Übung (Körpergewicht) für den Rücken, unterstützt von Schultern.","instructions":["Bei dieser Übung liegst du flach auf dem Bauch, hältst ein","Handtuch mit vor dir ausgestreckten Armen und ziehst es auseinander, um","Spannung zu erzeugen. Dann bewegst du es nach vorne und zurück unter deinen Bauch.","Diese Übung trainiert die Rücken- und Schultermuskulatur sowie die","Rumpfstabilität."]}},{"id":"ex-trap-3-raise","slug":"trap-3-raise","name":"Trap-3 Raise","description":"Bodyweight exercise for the back.","instructions":["Hinge forwards and bend your knees slightly. Depress and retract the shoulder you will use. Rest the other hand on your knee.","Raise your hand about 15 degrees overhead, maintaining the position of your shoulder."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["trap-3 raise","trap-3-raise"],"media":[],"source":"wger","de":{"name":"Trap-3-Raise","description":"Übung (Körpergewicht) für den Rücken.","instructions":["Beuge dich aus der Hüfte nach vorne und beuge die Knie leicht. Senke und ziehe die Schulter zurück, die du verwenden wirst. Stütze die andere Hand auf dein Knie.","Hebe deine Hand etwa 15 Grad über Kopfhöhe an und halte dabei die Position deiner Schulter."]}},{"id":"ex-trap-bar-deadlift","slug":"trap-bar-deadlift","name":"Trap Bar Deadlift","description":"Accessory exercise for the quadriceps, with glutes, hamstrings assisting.","instructions":["For this exercise load a trap bar, also known as a hex bar, to an appropriate weight resting on the ground. Stand in the center of the apparatus and grasp both handles.","Lower your hips, look forward with your head and keep your chest up.","Begin the movement by driving through the heels and extend your hips and knees. Avoid rounding your back at all times.","At the completion of the movement, lower the weight back to the ground under control."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["GLUTES","HAMSTRINGS"],"equipment":"OTHER","tags":["trap bar deadlift"],"media":[{"id":"trap-bar-deadlift-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Trap_Bar_Deadlift/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"trap-bar-deadlift-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Trap_Bar_Deadlift/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite, unterstützt von Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-trap-bar-squat","slug":"trap-bar-squat","name":"Trap Bar Squat","description":"Bodyweight exercise for the quadriceps, with hamstrings assisting.","instructions":["A combination of squat and deadlift principles with the use of a hex/trap bar, easing stress on the lower back by better centering the weight."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["HAMSTRINGS"],"equipment":"BODYWEIGHT","tags":["trap bar squat","trap-bar-kniebeuge"],"media":[],"source":"wger","de":{"name":"Trap-Bar-Kniebeuge","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Oberschenkelrückseite.","instructions":["Eine Kombination aus den Prinzipien von Kniebeuge und Kreuzheben unter Verwendung einer Hex-/Trap-Bar, die den unteren Rücken entlastet, indem das Gewicht besser zentriert wird."]}},{"id":"ex-trap-press","slug":"trap-press","name":"Trap press","description":"Barbell exercise for the back.","instructions":["Laying flat with arm pointing straight upwards, elbow fully extended, use only your shoulder to raise the weight as high as comfortable and back to rest."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["trap press","trapez-press"],"media":[{"id":"trap-press-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1581/b71a6710-5798-4639-ac5a-22a2cdae2036.jpg","caption":"Trap press","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Trapez-Press","description":"Übung (Langhantel) für den Rücken.","instructions":["Lege dich flach hin, der Arm zeigt gerade nach oben und der Ellbogen ist vollständig gestreckt. Hebe das Gewicht nur mit der Schulter so weit wie angenehm möglich an und senke es wieder ab."]}},{"id":"ex-tricep-rope-pushdowns","slug":"tricep-rope-pushdowns","name":"Tricep Rope Pushdowns","description":"Cable exercise for the triceps, with back assisting.","instructions":["Setup: Stand facing the cable, feet shoulder-width apart, with a slight forward lean.","Grip: Hold the rope with palms facing each other and elbows tucked tight to your ribs.","Execution: Push the rope down until arms are fully straight, pulling the ends apart at the bottom.","Control: Keep upper arms still and return to the start with a slow, controlled motion."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["BACK"],"equipment":"CABLE","tags":["tricep rope pushdowns","trizepsdrücken am seil"],"media":[{"id":"tricep-rope-pushdowns-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1900/a8243245-8f8f-4e2b-93ca-694d416cb11d.png","caption":"Tricep Rope Pushdowns","attribution":"wger.de · nishant0712","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Trizepsdrücken am Seil","description":"Übung (Kabelzug) für den Trizeps, unterstützt von Rücken.","instructions":["Aufbau: Stelle dich mit dem Gesicht zum Kabelzug, die Füße schulterbreit, und lehne dich leicht nach vorne.","Griff: Halte das Seil mit zueinander zeigenden Handflächen und die Ellbogen eng an den Rippen.","Ausführung: Drücke das Seil nach unten, bis die Arme vollständig gestreckt sind, und ziehe die Enden unten auseinander.","Kontrolle: Halte die Oberarme ruhig und kehre langsam und kontrolliert zur Ausgangsposition zurück."]}},{"id":"ex-tricep-side-stretch","slug":"tricep-side-stretch","name":"Tricep Side Stretch","description":"Equipment-free exercise for the triceps, with shoulders assisting.","instructions":["Bring right arm across your body and over your left shoulder, holding your elbow with your left hand, until you feel a stretch in your tricep. Then repeat for your other arm."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["SHOULDERS"],"equipment":"NONE","tags":["tricep side stretch"],"media":[{"id":"tricep-side-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tricep_Side_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"tricep-side-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tricep_Side_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Trizeps, unterstützt von Schultern.","instructions":null}},{"id":"ex-triceps-extensions-on-cable","slug":"triceps-extensions-on-cable","name":"Triceps Extensions on Cable","description":"Cable exercise for the triceps.","instructions":["Grab the cable, stand with your feet shoulder wide, keep your back straight and lean forward a little. Push the bar down, making sure the elbows don't move during the exercise. Rotate your hands outwards at the very end and go back to the initial position without pause."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["triceps extensions on cable","trizeps seildrücken"],"media":[{"id":"triceps-extensions-on-cable-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/659/a60452f1-e2ea-43fe-baa6-c1a2208d060c.png","caption":"Triceps Extensions on Cable","attribution":"wger.de · Franpol","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Trizeps Seildrücken","description":"Übung (Kabelzug) für den Trizeps.","instructions":["Stelle dich mit schulterbreitem Stand vor dem Kabelzug, beuge den Rücken sehr leicht nach vorn und greife das Seil. Ziehe nun nach unten, wobei die Ellenbogen sich während der ganzen Übung nicht von der Stelle bewegen sollen. Wenn die Arme ausgestreckt sind, drehe die Hände nach außen. Gehe langsam zur Ausgansposition zurück."]}},{"id":"ex-triceps-on-machine","slug":"triceps-on-machine","name":"Triceps on Machine","description":"Machine exercise for the triceps.","instructions":["Sit down and hold the bar firmly with your hands. Now press the weight upwards (don't fully extend your arms) and lower it slowly again. As with other triceps exercises, it's important not to move your upper arms."],"category":"MACHINE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"MACHINE","tags":["triceps on machine","trizepsmaschine"],"media":[],"source":"wger","de":{"name":"Trizepsmaschine","description":"Übung (Maschine) für den Trizeps.","instructions":["Setze dich hin und greife die Stange fest mit den Händen. Drücke nun das Gewicht nach oben (Arme nicht ganz ausstrecken) und bringe es langsam wieder runter. Wie bei den anderen Trizepsübungen ist es wichtig, dass du die Oberarme nicht mitbewegst."]}},{"id":"ex-triceps-overhead-dumbbell","slug":"triceps-overhead-dumbbell","name":"Triceps Overhead (Dumbbell)","description":"Dumbbell exercise for the triceps.","instructions":["Keep the elbows fixed","Engage the muscles","Don't use momentum","Controlled movement","Slow movement","Don't overextend"],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["triceps overhead (dumbbell)","trizepsdrücken über kopf (kurzhantel)"],"media":[{"id":"triceps-overhead-dumbbell-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1336/ebf88217-df26-4ef7-94cb-f0c2220c6abe.webp","caption":"Triceps Overhead (Dumbbell)","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Trizepsdrücken über Kopf (Kurzhantel)","description":"Übung (Kurzhantel) für den Trizeps.","instructions":["Ellbogen fixieren","Muskulatur anspannen","Kein Schwung holen","Kontrollierte Bewegung","Langsame Bewegung","Nicht überdehnen"]}},{"id":"ex-triceps-overhead-extension-with-rope","slug":"triceps-overhead-extension-with-rope","name":"Triceps Overhead Extension with Rope","description":"Cable exercise for the triceps.","instructions":["Attach a rope to a low pulley. After selecting an appropriate weight, grasp the rope with both hands and face away from the cable.","Position your hands behind your head with your elbows point straight up. Your elbows should start out flexed, and you can stagger your stance and lean gently away from the machine to create greater stability. This will be your starting position.","To perform the movement, extend through the elbow while keeping the upper arm in position, raising your hands above your head.","Squeeze your triceps at the top of the movement, and slowly lower the weight back to the start position."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["triceps overhead extension with rope"],"media":[{"id":"triceps-overhead-extension-with-rope-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Overhead_Extension_with_Rope/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"triceps-overhead-extension-with-rope-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Overhead_Extension_with_Rope/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Trizeps.","instructions":null}},{"id":"ex-triceps-pushdown","slug":"triceps-pushdown","name":"Triceps Pushdown","description":"Cable exercise for the triceps.","instructions":["Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.","Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.","Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.","After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["triceps pushdown"],"media":[{"id":"triceps-pushdown-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"triceps-pushdown-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Trizeps.","instructions":null}},{"id":"ex-triceps-pushdown-v-bar-attachment","slug":"triceps-pushdown-v-bar-attachment","name":"Triceps Pushdown - V-Bar Attachment","description":"Cable exercise for the triceps.","instructions":["Attach a V-Bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.","Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. The thumbs should be higher than the small finger. This is your starting position.","Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.","After a second hold at the contracted position, bring the V-Bar slowly up to the starting point. Breathe in as you perform this step.","Repeat for the recommended amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"CABLE","tags":["triceps pushdown - v-bar attachment"],"media":[{"id":"triceps-pushdown-v-bar-attachment-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown_-_V-Bar_Attachment/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"triceps-pushdown-v-bar-attachment-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown_-_V-Bar_Attachment/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Trizeps.","instructions":null}},{"id":"ex-triceps-stretch","slug":"triceps-stretch","name":"Triceps Stretch","description":"Equipment-free exercise for the triceps, with back assisting.","instructions":["Reach your hand behind your head, grasp your elbow and gently pull. Hold for 10 to 20 seconds, then switch sides."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["BACK"],"equipment":"NONE","tags":["triceps stretch"],"media":[{"id":"triceps-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"triceps-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Trizeps, unterstützt von Rücken.","instructions":null}},{"id":"ex-trx-dips","slug":"trx-dips","name":"TRX dips","description":"Bodyweight exercise for the triceps, with chest assisting.","instructions":["Start with the hands on the suspension trainer and feet on the ground.","Your hands should be under your shoulders with the feet slightly in front.","Lower yourself by bringing the hips between the handles and flexing the elbows.","Extend the elbows to come back to the starting position and repeat."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST"],"equipment":"BODYWEIGHT","tags":["trx dips"],"media":[],"source":"wger","de":{"name":"TRX Dips","description":"Übung (Körpergewicht) für den Trizeps, unterstützt von Brust.","instructions":["Beginne mit den Händen am Schlingentrainer und den Füßen auf dem Boden.","Deine Hände sollten unter deinen Schultern sein, die Füße leicht nach vorne versetzt.","Senke dich ab, indem du die Hüfte zwischen die Griffe bringst und die Ellbogen beugst.","Strecke die Ellbogen, um in die Ausgangsposition zurückzukehren, und wiederhole."]}},{"id":"ex-trx-gorilla-biceps-curl","slug":"trx-gorilla-biceps-curl","name":"TRX gorilla biceps curl","description":"Bodyweight exercise for the biceps.","instructions":["We'll stand facing the TRX straps and grab them with our fists facing each other, facing forward, with our arms fully extended at about shoulder-width apart. We'll keep our body straight, backward, as in the previous exercises, since we'll be lifting our body toward the TRX straps by activating our biceps. Our body will be straight, with our feet flat on the floor. This time, we'll place our arms open to the sides and at chest height. The movement we'll perform is a contraction toward our chest. To achieve this, we'll bend our elbows so that, by activating our biceps, we can pull our body toward the straps."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["trx gorilla biceps curl","trx gorilla-bizeps-curl"],"media":[],"source":"wger","de":{"name":"TRX Gorilla-Bizeps-Curl","description":"Übung (Körpergewicht) für den Bizeps.","instructions":["Wir stellen uns mit Blick zu den TRX-Bändern und greifen sie mit den Fäusten zueinander gerichtet, nach vorne zeigend, mit vollständig gestreckten Armen etwa schulterbreit auseinander. Wir halten unseren Körper gerade, nach hinten geneigt, wie in den vorherigen Übungen, da wir unseren Körper durch die Aktivierung des Bizeps in Richtung der TRX-Bänder heben. Unser Körper ist gerade, mit flach auf dem Boden stehenden Füßen. Diesmal positionieren wir unsere Arme seitlich geöffnet und auf Brusthöhe. Die Bewegung, die wir ausführen, ist eine Kontraktion in Richtung unserer Brust. Um das zu erreichen, beugen wir unsere Ellbogen, sodass wir durch die Aktivierung des Bizeps unseren Körper zu den Bändern ziehen können."]}},{"id":"ex-trx-hammer-curl","slug":"trx-hammer-curl","name":"TRX hammer curl","description":"Bodyweight exercise for the biceps.","instructions":["Place the grips as if they were a continuation of the straps. We will position our arms stretched forward and our body leaning back, completely straight. The biceps muscles will activate as you bend your elbows to bring your body towards the straps. The contraction movement will end with a slight outward movement of the hands, due to the grip we are using."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["trx hammer curl","trx hammer-curl"],"media":[],"source":"wger","de":{"name":"TRX Hammer-Curl","description":"Übung (Körpergewicht) für den Bizeps.","instructions":["Positioniere die Griffe so, als wären sie eine Verlängerung der Bänder. Wir positionieren unsere Arme nach vorne gestreckt und unseren Körper nach hinten geneigt, vollkommen gerade. Die Bizepsmuskeln aktivieren sich, wenn du deine Ellbogen beugst, um deinen Körper in Richtung der Bänder zu ziehen. Die Kontraktionsbewegung endet mit einer leichten Auswärtsbewegung der Hände, bedingt durch den verwendeten Griff."]}},{"id":"ex-trx-obliques","slug":"trx-obliques","name":"TRX Obliques","description":"Bodyweight exercise for the core, with chest, shoulders assisting.","instructions":["Place your feet in the stirrups and assume a high plank with your hands directly beneath your shoulders.","Pull your knees to your right elbow, then push them back out and to the centre."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"BODYWEIGHT","tags":["trx obliques","trx bauchmuskeln seitlich"],"media":[],"source":"wger","de":{"name":"TRX Bauchmuskeln seitlich","description":"Übung (Körpergewicht) für den Rumpf, unterstützt von Brust, Schultern.","instructions":["Setze deine Füße in die Schlaufen und nimm einen hohen Liegestütz ein, mit deinen Händen direkt unter deinen Schultern.","Ziehe deine Knie zu deinem rechten Ellbogen, dann drücke sie wieder heraus und zur Mitte."]}},{"id":"ex-trx-roll-out","slug":"trx-roll-out","name":"TRX roll out","description":"Bodyweight exercise for the core, with chest assisting.","instructions":["Hold the handles in your hands, extend your arms and keep them parallel at chest height. The movement you need to perform is to open your arms in line with your shoulders while leaning your body forward. Try not to extend your shoulders beyond 90°, and keep your abdominal muscles and glutes contracted. Muscles involved: transverse abdominis, rectus abdominis and spinal erectors."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["CHEST"],"equipment":"BODYWEIGHT","tags":["trx roll out","trx roll-out"],"media":[],"source":"wger","de":{"name":"TRX Roll-out","description":"Übung (Körpergewicht) für den Rumpf, unterstützt von Brust.","instructions":["Halte die Griffe mit den Händen, strecke die Arme aus und halte sie parallel auf Brusthöhe. Die Bewegung, die du ausführen sollst, ist ein Öffnen der Arme in einer Linie mit den Schultern, während du den Körper nach vorne neigst. Versuche, keine Schulterstreckung über 90° hinaus auszuführen, und halte die Bauchmuskulatur und die Gesäßmuskulatur angespannt. Beteiligte Muskeln: Transversus, gerader Bauchmuskel und Rückenstrecker"]}},{"id":"ex-trx-single-arm-bicep-curl","slug":"trx-single-arm-bicep-curl","name":"Trx Single Arm Bicep Curl","description":"Bodyweight exercise for the biceps, with shoulders, back assisting.","instructions":["Step 1: Stand comfortably and grasp the handles of the suspension system. Step 2: Lean back resting your weight on one arm, keepng the spine neutral. Step 3: Slowly curl to pull your body weight to the up position. Supinate the arm and squeeze as you approach the end position. Step 4: Lower yourself back down and repeat."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["SHOULDERS","BACK"],"equipment":"BODYWEIGHT","tags":["trx single arm bicep curl","trx einarmiger bizeps-curl"],"media":[],"source":"wger","de":{"name":"TRX einarmiger Bizeps-Curl","description":"Übung (Körpergewicht) für den Bizeps, unterstützt von Schultern, Rücken.","instructions":["Schritt 1: Stelle dich bequem hin und greife die Griffe des Schlingentrainers. Schritt 2: Lehne dich zurück und stütze dein Gewicht auf einen Arm, wobei du die Wirbelsäule neutral hältst. Schritt 3: Führe langsam einen Curl aus, um dein Körpergewicht in die obere Position zu ziehen. Supiniere den Arm und spanne ihn an, während du dich der Endposition näherst. Schritt 4: Senke dich wieder ab und wiederhole."]}},{"id":"ex-trx-tricep-extension","slug":"trx-tricep-extension","name":"TRX Tricep Extension","description":"Bodyweight exercise for the triceps.","instructions":["Attach the TRX or other suspension system overhead, having the handles hanging at chest level or slightly lower. Experiment to see what height allows you to set up in the best way.","Stand in front of the handles and grab them with your palms facing down.","Engage your abs, squeeze your glutes, take a breath and lean forward, lifting your heels off the floor. Keep your elbows straight.","Take another breath and lower yourself slowly by bending your elbows.","Go down until your elbows are at a 90-degree angle (to the point where your wrists are above your elbows). Hold the position for a moment.","Extend your arms by engaging your triceps and bring yourself to the starting position as you exhale."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["trx tricep extension","trx trizepsstrecken"],"media":[],"source":"wger","de":{"name":"TRX Trizepsstrecken","description":"Übung (Körpergewicht) für den Trizeps.","instructions":["Befestige den TRX oder ein anderes Schlingensystem über Kopf, sodass die Griffe auf Brusthöhe oder etwas tiefer hängen. Probiere aus, welche Höhe dir den besten Aufbau ermöglicht.","Stelle dich vor die Griffe und greife sie mit den Handflächen nach unten.","Spanne deine Bauchmuskulatur an, drücke deine Gesäßmuskulatur zusammen, hole Luft und lehne dich nach vorne, wobei du die Fersen vom Boden abhebst. Halte deine Ellbogen gestreckt.","Hole erneut Luft und senke dich langsam ab, indem du deine Ellbogen beugst.","Gehe so weit nach unten, bis deine Ellbogen in einem 90-Grad-Winkel sind (bis zu dem Punkt, an dem deine Handgelenke über deinen Ellbogen sind). Halte die Position einen Moment.","Strecke deine Arme, indem du deinen Trizeps anspannst, und bringe dich in die Ausgangsposition zurück, während du ausatmest."]}},{"id":"ex-tuck-crunch","slug":"tuck-crunch","name":"Tuck Crunch","description":"Bodyweight exercise for the core.","instructions":["To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.","Your legs should be crossed by wrapping one ankle around the other. Slowly elevate your legs up in the air until your thighs are perpendicular to the floor with a slight bend at the knees. Note: Your knees and toes should be parallel to the floor as opposed to the thighs.","Move your arms from the floor and cross them so they are resting on your chest. This is the starting position.","While keeping your lower back pressed against the floor, slowly lift your torso. Remember to exhale while perform this part of the exercise.","Slowly begin to lower your torso back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["tuck crunch"],"media":[{"id":"tuck-crunch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tuck_Crunch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"tuck-crunch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tuck_Crunch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-tuck-l-sit","slug":"tuck-l-sit","name":"Tuck L-sit","description":"Bodyweight exercise for the core, with biceps, chest, quadriceps, back, triceps assisting.","instructions":["The tuck L-sit is a bodyweight hold where you support yourself on parallel bars, parallettes, or the floor with straight arms while pulling your knees toward your chest. Your hips stay lifted, your spine stays tall, and your feet hover off the ground. The goal is to keep your core tight, shoulders depressed, and arms locked out while maintaining the tucked position. It’s a core-intensive, shoulder-stabilizing static hold often used as a progression toward the full L-sit."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["BICEPS","CHEST","QUADRICEPS","BACK","TRICEPS"],"equipment":"BODYWEIGHT","tags":["tuck l-sit"],"media":[],"source":"wger","de":{"name":"Tuck L-Sit","description":"Übung (Körpergewicht) für den Rumpf, unterstützt von Bizeps, Brust, Oberschenkelvorderseite, Rücken, Trizeps.","instructions":["Der Tuck L-Sit ist ein Halt mit dem eigenen Körpergewicht, bei dem du dich auf Barren, Parallettes oder dem Boden mit gestreckten Armen abstützt, während du deine Knie zur Brust ziehst. Deine Hüfte bleibt angehoben, deine Wirbelsäule bleibt aufrecht, und deine Füße schweben über dem Boden. Ziel ist es, deine Rumpfmuskulatur angespannt, deine Schultern nach unten gedrückt und deine Arme durchgestreckt zu halten, während du die angezogene Position beibehältst. Es ist ein rumpfintensiver, schulterstabilisierender statischer Halt, der oft als Vorstufe zum vollständigen L-Sit genutzt wird."]}},{"id":"ex-two-arm-dumbbell-preacher-curl","slug":"two-arm-dumbbell-preacher-curl","name":"Two-Arm Dumbbell Preacher Curl","description":"Dumbbell exercise for the biceps.","instructions":["Grab a dumbbell with each arm and place the upper arms on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.","As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched.","As you exhale, use the biceps to curl the weights up until your biceps is fully contracted and the dumbbells are at shoulder height.","Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["two-arm dumbbell preacher curl"],"media":[{"id":"two-arm-dumbbell-preacher-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Two-Arm_Dumbbell_Preacher_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"two-arm-dumbbell-preacher-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Two-Arm_Dumbbell_Preacher_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps.","instructions":null}},{"id":"ex-two-arm-kettlebell-clean","slug":"two-arm-kettlebell-clean","name":"Two-Arm Kettlebell Clean","description":"Kettlebell exercise for the shoulders, with calves, glutes, hamstrings, back assisting.","instructions":["Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.","Clean the kettlebells to your shoulders by extending through the legs and hips as you raise the kettlebells towards your shoulders. Rotate your wrists as you do so.","Lower the kettlebells back to the starting position and repeat."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","BACK"],"equipment":"KETTLEBELL","tags":["two-arm kettlebell clean"],"media":[{"id":"two-arm-kettlebell-clean-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Two-Arm_Kettlebell_Clean/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"two-arm-kettlebell-clean-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Two-Arm_Kettlebell_Clean/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Waden, Po, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-two-arm-kettlebell-jerk","slug":"two-arm-kettlebell-jerk","name":"Two-Arm Kettlebell Jerk","description":"Kettlebell exercise for the shoulders, with calves, quadriceps, triceps assisting.","instructions":["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. Squat down a few inches and reverse the motion rapidly driving both kettlebells overhead. Immediately after the initial push, squat down again and get under the kettlebells. Once the kettlebells are locked out, stand upright to complete the exercise."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CALVES","QUADRICEPS","TRICEPS"],"equipment":"KETTLEBELL","tags":["two-arm kettlebell jerk"],"media":[{"id":"two-arm-kettlebell-jerk-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Two-Arm_Kettlebell_Jerk/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"two-arm-kettlebell-jerk-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Two-Arm_Kettlebell_Jerk/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Waden, Oberschenkelvorderseite, Trizeps.","instructions":null}},{"id":"ex-two-arm-kettlebell-military-press","slug":"two-arm-kettlebell-military-press","name":"Two-Arm Kettlebell Military Press","description":"Kettlebell exercise for the shoulders, with triceps assisting.","instructions":["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward.","Press the kettlebells up and out. As the kettlebells pass your head, lean into the weights so that the kettlebells are racked behind your head. Make sure to contract your lats, butt, and stomach for added stability."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["TRICEPS"],"equipment":"KETTLEBELL","tags":["two-arm kettlebell military press"],"media":[{"id":"two-arm-kettlebell-military-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Two-Arm_Kettlebell_Military_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"two-arm-kettlebell-military-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Two-Arm_Kettlebell_Military_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für die Schultern, unterstützt von Trizeps.","instructions":null}},{"id":"ex-two-arm-kettlebell-row","slug":"two-arm-kettlebell-row","name":"Two-Arm Kettlebell Row","description":"Kettlebell exercise for the back, with biceps assisting.","instructions":["Place two kettlebells in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position.","Grab both kettlebells and pull them to your stomach, retracting your shoulder blades and flexing the elbows. Keep your back straight. Lower and repeat."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"KETTLEBELL","tags":["two-arm kettlebell row"],"media":[{"id":"two-arm-kettlebell-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Two-Arm_Kettlebell_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"two-arm-kettlebell-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Two-Arm_Kettlebell_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kettlebell) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-typewriter-pull-ups","slug":"typewriter-pull-ups","name":"Typewriter Pull-ups","description":"Bodyweight exercise for the biceps, with back assisting.","instructions":["Hang from a pull-up bar with an overhand grip, slightly wider than shoulder-width. Pull yourself up until your chin is above the bar. At the top position, instead of going straight down, shift your body to one side by extending one arm while keeping the other arm bent. Move smoothly from one side to the other, like a typewriter motion, before lowering yourself back down. This exercise increases time under tension and strengthens the lats, biceps, and shoulders while building unilateral pulling strength."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["BACK"],"equipment":"BODYWEIGHT","tags":["typewriter pull-ups","typewriter-klimmzüge"],"media":[],"source":"wger","de":{"name":"Typewriter-Klimmzüge","description":"Übung (Körpergewicht) für den Bizeps, unterstützt von Rücken.","instructions":["Hänge dich mit einem Obergriff, etwas weiter als schulterbreit, an eine Klimmzugstange. Ziehe dich hoch, bis dein Kinn über der Stange ist. Verlagere am höchsten Punkt deinen Körper zu einer Seite, indem du einen Arm streckst, während der andere Arm gebeugt bleibt, anstatt direkt nach unten zu gehen. Bewege dich gleichmäßig von einer Seite zur anderen, ähnlich der Bewegung einer Schreibmaschine, bevor du dich wieder herablässt. Diese Übung erhöht die Zeit unter Spannung und stärkt Latissimus, Bizeps und Schultern, während sie einseitige Zugkraft aufbaut."]}},{"id":"ex-underhand-cable-pulldowns","slug":"underhand-cable-pulldowns","name":"Underhand Cable Pulldowns","description":"Cable exercise for the back, with biceps, shoulders assisting.","instructions":["Sit down on a pull-down machine with a wide bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the pull-down bar with the palms facing your torso (a supinated grip). Make sure that the hands are placed closer than the shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","As you breathe out, pull the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the fully contracted position and keep the elbows close to your body. The upper torso should remain stationary as your bring the bar to you and only the arms should move. The forearms should do no other work other than hold the bar.","After a second on the contracted position, while breathing in, slowly bring the bar back to the starting position when your arms are fully extended and the lats are fully stretched.","Repeat this motion for the prescribed amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","SHOULDERS"],"equipment":"CABLE","tags":["underhand cable pulldowns"],"media":[{"id":"underhand-cable-pulldowns-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Underhand_Cable_Pulldowns/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"underhand-cable-pulldowns-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Underhand_Cable_Pulldowns/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rücken, unterstützt von Bizeps, Schultern.","instructions":null}},{"id":"ex-underhand-lat-pull-down","slug":"underhand-lat-pull-down","name":"Underhand Lat Pull Down","description":"Bodyweight exercise for the back, with biceps assisting.","instructions":["Grip the pull-down bar with your palms facing you and your hands closer than shoulder-width apart. Lean back slightly and keep your back straight. Pull the bar down towards your chest, pulling your shoulders back slightly at the end of the motion."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"BODYWEIGHT","tags":["underhand lat pull down","latzug im untergriff"],"media":[],"source":"wger","de":{"name":"Latzug im Untergriff","description":"Übung (Körpergewicht) für den Rücken, unterstützt von Bizeps.","instructions":["Greife die Latzugstange so, dass deine Handflächen zu dir zeigen und deine Hände enger als schulterbreit sind. Lehne dich leicht zurück und halte den Rücken gerade. Ziehe die Stange zur Brust und ziehe am Ende der Bewegung die Schultern leicht nach hinten."]}},{"id":"ex-unilateral-cable-row","slug":"unilateral-cable-row","name":"Unilateral Cable row","description":"Cable exercise for the back, with chest assisting.","instructions":["Put a vertical seated bench in front of the cable row machine.position it so that you can focus on one side, and then do slow pulls focusing on the lateral muscles and ensuring tention in those muscles when in a stretched position."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["CHEST"],"equipment":"CABLE","tags":["unilateral cable row","einarmiges rudern am kabelzug"],"media":[{"id":"unilateral-cable-row-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1621/ca1bc68d-9c36-4dd3-8ec4-496c57b5c564.jpg","caption":"Unilateral Cable row","attribution":"wger.de · technofer","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Einarmiges Rudern am Kabelzug","description":"Übung (Kabelzug) für den Rücken, unterstützt von Brust.","instructions":["Stelle eine senkrechte Sitzbank vor die Kabelzug-Rudermaschine. Positioniere sie so, dass du dich auf eine Seite konzentrieren kannst, und führe dann langsame Züge aus, wobei du dich auf die seitliche Muskulatur konzentrierst und in der gedehnten Position für Spannung in diesen Muskeln sorgst."]}},{"id":"ex-unilateral-cross-body-cable-pull-down","slug":"unilateral-cross-body-cable-pull-down","name":"unilateral cross body cable pull down","description":"Cable exercise for the back, with shoulders assisting.","instructions":["on a cable rack place cable high, and with a straight arm pull that cable across you from high to low. focus on tension in back shoulder."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["SHOULDERS"],"equipment":"CABLE","tags":["unilateral cross body cable pull down","einarmiger cable pulldown über kreuz"],"media":[],"source":"wger","de":{"name":"Einarmiger Cable Pulldown über Kreuz","description":"Übung (Kabelzug) für den Rücken, unterstützt von Schultern.","instructions":["Stelle an einem Kabelturm den Kabelzug hoch ein und ziehe das Kabel mit gestrecktem Arm von oben nach unten quer über deinen Körper. Konzentriere dich auf die Spannung in der hinteren Schulter."]}},{"id":"ex-upper-back-leg-grab","slug":"upper-back-leg-grab","name":"Upper Back-Leg Grab","description":"Equipment-free exercise for the hamstrings, with back assisting.","instructions":["While seated, bend forward to hug your thighs from underneath with both arms.","Keep your knees together and your legs extended out as you bring your chest down to your knees. You can also stretch your middle back by pulling your back away from your knees as your hugging them."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["BACK"],"equipment":"NONE","tags":["upper back-leg grab"],"media":[{"id":"upper-back-leg-grab-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upper_Back-Leg_Grab/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"upper-back-leg-grab-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upper_Back-Leg_Grab/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Oberschenkelrückseite, unterstützt von Rücken.","instructions":null}},{"id":"ex-upper-back-stretch","slug":"upper-back-stretch","name":"Upper Back Stretch","description":"Equipment-free exercise for the back.","instructions":["Clasp fingers together with your thumbs pointing down, round your shoulders as you reach your hands forward."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BACK","secondaryMuscleGroups":[],"equipment":"NONE","tags":["upper back stretch"],"media":[{"id":"upper-back-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upper_Back_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"upper-back-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upper_Back_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Rücken.","instructions":null}},{"id":"ex-upright-barbell-row","slug":"upright-barbell-row","name":"Upright Barbell Row","description":"Barbell exercise for the shoulders, with back assisting.","instructions":["Grasp a barbell with an overhand grip that is slightly less than shoulder width. The bar should be resting on the top of your thighs with your arms extended and a slight bend in your elbows. Your back should also be straight. This will be your starting position.","Now exhale and use the sides of your shoulders to lift the bar, raising your elbows up and to the side. Keep the bar close to your body as you raise it. Continue to lift the bar until it nearly touches your chin. Tip: Your elbows should drive the motion, and should always be higher than your forearms. Remember to keep your torso stationary and pause for a second at the top of the movement.","Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"BARBELL","tags":["upright barbell row"],"media":[{"id":"upright-barbell-row-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upright_Barbell_Row/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"upright-barbell-row-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upright_Barbell_Row/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Schultern, unterstützt von Rücken.","instructions":null}},{"id":"ex-upright-row-on-multi-press","slug":"upright-row-on-multi-press","name":"Upright Row, on Multi Press","description":"Bodyweight exercise for the shoulders, with back, biceps assisting.","instructions":["The movements are basically the same as with an SZ-bar, but you use the bar on the multi press:","Stand straight, your feet are shoulder-width apart. Hold the bar with an overhand grip on your thighs, the arms are stretched. Lift the bar close to the body till your chin. The elbows point out so that at the highest point they form a V. Make here a short pause before going slowly down and repeating the movement."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK","BICEPS"],"equipment":"BODYWEIGHT","tags":["upright row, on multi press","rudern aufrecht mp"],"media":[{"id":"upright-row-on-multi-press-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/691/297d4ce1-7e9e-4adb-8f5c-7d54054be885.jpg","caption":"Upright Row, on Multi Press","attribution":"wger.de · anto.kreegyr","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Rudern Aufrecht MP","description":"Übung (Körpergewicht) für die Schultern, unterstützt von Rücken, Bizeps.","instructions":["Der Bewegungsablauf ist derselbe wie bei Ausführung mit einer ß-Stange.","Stelle dich gerade hin, die Füße etwa schulterbreit. Halte die Stange mit einem Obergriff vor den Oberschenkel, die Arme ausgestreckt. Ziehe dann die Stange dicht am Körper hoch, bis etwa zum Kinn. Die Ellenbogen zeigen nach oben, so, dass in der höchsten Position die Arme ein leichtes V machen. Mache nach Möglichkeit hier eine kurze Pause und gehe dann langsam wieder runter."]}},{"id":"ex-upright-row-sz-bar","slug":"upright-row-sz-bar","name":"Upright Row, SZ-bar","description":"EZ-bar exercise for the shoulders, with back, biceps assisting.","instructions":["Stand straight, your feet are shoulder-width apart. Hold the SZ-bar with an overhand grip on your thighs, the arms are stretched. Lift the bar close to the body till your chin. The elbows point out so that at the highest point they form a V. Make here a short pause before going slowly down and repeating the movement."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK","BICEPS"],"equipment":"EZ_BAR","tags":["upright row, sz-bar","rudern aufrecht ß-stange"],"media":[{"id":"upright-row-sz-bar-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/693/05c91bd2-7814-40b6-b2d1-51ae942b8321.png","caption":"Upright Row, SZ-bar","attribution":"wger.de","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Rudern Aufrecht ß-Stange","description":"Übung (SZ-Stange) für die Schultern, unterstützt von Rücken, Bizeps.","instructions":["Stelle dich gerade hin, die Füße etwa schulterbreit. Halte die ß-Stange mit einem Obergriff vor den Oberschenkel, die Arme ausgestreckt. Ziehe dann die Stange dicht am Körper hoch, bis etwa zum Kinn. Die Ellenbogen zeigen nach oben, so, dass in der höchsten Position die Arme ein leichtes V machen. Mache nach Möglichkeit hier eine kurze Pause und gehe dann langsam wieder runter."]}},{"id":"ex-upright-row-with-bands","slug":"upright-row-with-bands","name":"Upright Row - With Bands","description":"Resistance band exercise for the back, with shoulders assisting.","instructions":["To begin, stand on an exercise band so that tension begins at arm's length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.","Use your side shoulders to lift the handles as you exhale. The handles should be close to the body as you move them up. Continue to lift the handles until they nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the handles, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["SHOULDERS"],"equipment":"BAND","tags":["upright row - with bands"],"media":[{"id":"upright-row-with-bands-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upright_Row_-_With_Bands/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"upright-row-with-bands-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upright_Row_-_With_Bands/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Widerstandsband) für den Rücken, unterstützt von Schultern.","instructions":null}},{"id":"ex-upward-stretch","slug":"upward-stretch","name":"Upward Stretch","description":"Equipment-free exercise for the shoulders, with chest, back assisting.","instructions":["Extend both hands straight above your head, palms touching.","Slowly push your hands up and back, keeping your back straight."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["CHEST","BACK"],"equipment":"NONE","tags":["upward stretch"],"media":[{"id":"upward-stretch-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upward_Stretch/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"upward-stretch-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upward_Stretch/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für die Schultern, unterstützt von Brust, Rücken.","instructions":null}},{"id":"ex-v-bar-pulldown","slug":"v-bar-pulldown","name":"V-Bar Pulldown","description":"Cable exercise for the back, with biceps, shoulders assisting.","instructions":["Sit down on a pull-down machine with a V-Bar attached to the top pulley.","Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the V-bar with the palms facing each other (a neutral grip). Stick your chest out and lean yourself back slightly (around 30-degrees) in order to better engage the lats. This will be your starting position.","Using your lats, pull the bar down as you squeeze your shoulder blades. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion. Tip: Keep the torso stationary throughout the movement.","After a second hold on the contracted position, slowly bring the bar back to the starting position as you breathe in.","Repeat for the prescribed number of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","SHOULDERS"],"equipment":"CABLE","tags":["v-bar pulldown"],"media":[{"id":"v-bar-pulldown-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/V-Bar_Pulldown/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"v-bar-pulldown-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/V-Bar_Pulldown/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rücken, unterstützt von Bizeps, Schultern.","instructions":null}},{"id":"ex-v-bar-pullup","slug":"v-bar-pullup","name":"V-Bar Pullup","description":"Bodyweight exercise for the back, with biceps, shoulders assisting.","instructions":["Start by placing the middle of the V-bar in the middle of the pull-up bar (assuming that the pull-up station you are using does not have neutral grip handles). The V-Bar handles will be facing down so that you can hang from the pull-up bar through the use of the handles.","Once you securely place the V-bar, take a hold of the bar from each side and hang from it. Stick your chest out and lean yourself back slightly in order to better engage the lats. This will be your starting position.","Using your lats, pull your torso up while leaning your head back slightly so that you do not hit yourself with the chin-up bar. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion.","After a second hold on the contracted position, slowly lower your body back to the starting position as you breathe in.","Repeat for the prescribed number of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","SHOULDERS"],"equipment":"BODYWEIGHT","tags":["v-bar pullup"],"media":[{"id":"v-bar-pullup-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/V-Bar_Pullup/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"v-bar-pullup-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/V-Bar_Pullup/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rücken, unterstützt von Bizeps, Schultern.","instructions":null}},{"id":"ex-vertical-swing","slug":"vertical-swing","name":"Vertical Swing","description":"Dumbbell exercise for the hamstrings, with glutes, quadriceps, shoulders assisting.","instructions":["Allow the dumbbell to hang at arms length between your legs, holding it with both hands. Keep your back straight and your head up.","Swing the dumbbell between your legs, flexing at the hips and bending the knees slightly.","Powerfully reverse the motion by extending at the hips, knees, and ankles to propel yourself upward, swinging the dumbell over your head.","As you land, absorb the impact through your legs and draw the dumbbell to your torso before the next repetition."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["GLUTES","QUADRICEPS","SHOULDERS"],"equipment":"DUMBBELL","tags":["vertical swing"],"media":[{"id":"vertical-swing-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Vertical_Swing/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"vertical-swing-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Vertical_Swing/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für die Oberschenkelrückseite, unterstützt von Po, Oberschenkelvorderseite, Schultern.","instructions":null}},{"id":"ex-walking-bridge","slug":"walking-bridge","name":"walking bridge","description":"Bodyweight exercise for the core, with shoulders, biceps, glutes, back assisting.","instructions":["from a standing position with knees slightly bent and hands resting on the floor. From here, proceed forward with your hands keeping your buttocks contracted and without losing control of your lower back."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":["SHOULDERS","BICEPS","GLUTES","BACK"],"equipment":"BODYWEIGHT","tags":["walking bridge","wandernde brücke"],"media":[],"source":"wger","de":{"name":"Wandernde Brücke","description":"Übung (Körpergewicht) für den Rumpf, unterstützt von Schultern, Bizeps, Po, Rücken.","instructions":["Beginne aus dem Stand mit leicht gebeugten Knien und den Händen auf dem Boden. Bewege dich von hier aus mit den Händen nach vorne, während du die Gesäßmuskulatur angespannt hältst und nicht die Kontrolle über deinen unteren Rücken verlierst."]}},{"id":"ex-wall-drills","slug":"wall-drills","name":"Wall Drills","description":"Bodyweight exercise for the quadriceps, with calves assisting.","instructions":["Exercises for strengthening knee and leg musculature.","Lateral Wall Drills March - https://youtu.be/9RiTlJ6Mmek","Lateral Wall Drills OPEN - https://youtu.be/ADRlN8-Wfdg","Lateral Wall Drills CROSS - https://youtu.be/hGH2sj0Tzu4"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES"],"equipment":"BODYWEIGHT","tags":["wall drills","wand-drills"],"media":[],"source":"wger","de":{"name":"Wand-Drills","description":"Übung (Körpergewicht) für die Oberschenkelvorderseite, unterstützt von Waden.","instructions":["Übungen zur Stärkung der Knie- und Beinmuskulatur.","Lateral Wall Drills March - https://youtu.be/9RiTlJ6Mmek","Lateral Wall Drills OPEN - https://youtu.be/ADRlN8-Wfdg","Lateral Wall Drills CROSS - https://youtu.be/hGH2sj0Tzu4"]}},{"id":"ex-wall-handstand","slug":"wall-handstand","name":"Wall Handstand","description":"Bodyweight exercise for the shoulders.","instructions":["Handstand against a wall for support (chest facing wall)."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["wall handstand","handstand gegen die wand"],"media":[],"source":"wger","de":{"name":"Handstand Gegen Die Wand","description":"Übung (Körpergewicht) für die Schultern.","instructions":["Handstand gegen eine Wand zur Unterstützung (Brust zugewandte Wand)."]}},{"id":"ex-wall-sit","slug":"wall-sit","name":"Wall-sit","description":"Bodyweight exercise for the glutes, with quadriceps, calves, core assisting.","instructions":["The Wall Sit (or wall chair) is an isometric exercise that mainly involves the leg muscles, improving muscular endurance and stability. Here are the main and secondary muscles activated during the exercise."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["QUADRICEPS","CALVES","ABS_CORE"],"equipment":"BODYWEIGHT","tags":["wall-sit","wandsitz"],"media":[],"source":"wger","de":{"name":"Wandsitz","description":"Übung (Körpergewicht) für den Po, unterstützt von Oberschenkelvorderseite, Waden, Rumpf.","instructions":["Der Wandsitz (oder Wandstuhl) ist eine isometrische Übung, die vor allem die Beinmuskulatur beansprucht und die muskuläre Ausdauer sowie die Stabilität verbessert. Hier sind die wichtigsten und sekundären Muskeln, die während der Übung aktiviert werden."]}},{"id":"ex-wall-slides","slug":"wall-slides","name":"Wall Slides","description":"Bodyweight exercise for the biceps, with hamstrings, chest, back, triceps assisting.","instructions":["Stand with heels, shoulders, back of head, and hips touching the wall. Start with biceps straight out and elbows at a 90 degree angle. Straighten the arms while remaining againstthe wall without arching the back off of the wall, mimicking a shoulder press movement."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["HAMSTRINGS","CHEST","BACK","TRICEPS"],"equipment":"BODYWEIGHT","tags":["wall slides","wandgleiten"],"media":[],"source":"wger","de":{"name":"Wandgleiten","description":"Übung (Körpergewicht) für den Bizeps, unterstützt von Oberschenkelrückseite, Brust, Rücken, Trizeps.","instructions":["Stelle dich so hin, dass Fersen, Schultern, Hinterkopf und Hüfte die Wand berühren. Beginne mit den Oberarmen gerade zur Seite ausgestreckt und den Ellbogen in einem 90-Grad-Winkel. Strecke die Arme, während du an der Wand bleibst, ohne den Rücken von der Wand abzuheben, und ahme dabei die Bewegung eines Schulterdrückens nach."]}},{"id":"ex-weighted-ball-hyperextension","slug":"weighted-ball-hyperextension","name":"Weighted Ball Hyperextension","description":"Accessory exercise for the back, with glutes, hamstrings assisting.","instructions":["To begin, lie down on an exercise ball with your torso pressing against the ball and parallel to the floor. The ball of your feet should be pressed against the floor to help keep you balanced. Place a weighted plate under your chin or behind your neck. This is the starting position.","Slowly raise your torso up by bending at the waist and lower back. Remember to exhale during this movement.","Hold the contraction on your lower back for a second and lower your torso back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions prescribed in your program."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["GLUTES","HAMSTRINGS"],"equipment":"OTHER","tags":["weighted ball hyperextension"],"media":[{"id":"weighted-ball-hyperextension-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Ball_Hyperextension/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"weighted-ball-hyperextension-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Ball_Hyperextension/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-weighted-ball-side-bend","slug":"weighted-ball-side-bend","name":"Weighted Ball Side Bend","description":"Accessory exercise for the core.","instructions":["To begin, lie down on an exercise ball with your left side of the torso (waist, hips and shoulder) pressed against the ball.","Your feet should be on the floor while your legs are crossed and hanging from the ball. Hold a weighted plate with your right hand directly to the right side of your head. Tip: Make sure the smooth side of the plate is resting against your head.","Place your left arm across your torso so that your palm is on your obliques. There should be a right angle between your left forearm and upper arm. This is the starting position.","Raise the side of your torso up by laterally flexing at the waist while exhaling.","Hold the contraction for a second and slowly lower yourself back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions.","Switch sides and repeat the exercise."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["weighted ball side bend"],"media":[{"id":"weighted-ball-side-bend-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Ball_Side_Bend/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"weighted-ball-side-bend-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Ball_Side_Bend/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rumpf.","instructions":null}},{"id":"ex-weighted-bench-dip","slug":"weighted-bench-dip","name":"Weighted Bench Dip","description":"Accessory exercise for the triceps, with chest, shoulders assisting.","instructions":["For this exercise you will need to place a bench behind your back and another one in front of you. With the benches perpendicular to your body, hold on to one bench on its edge with the hands close to your body, separated at shoulder width. Your arms should be fully extended.","The legs will be extended forward on top of the other bench. Your legs should be parallel to the floor while your torso is to be perpendicular to the floor. Have your partner place the dumbbell on your lap. Note: This exercise is best performed with a partner as placing the weight on your lap can be challenging and cause injury without assistance. This will be your starting position.","Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.","Using your triceps to bring your torso up again, lift yourself back to the starting position while exhaling.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"TRICEPS","secondaryMuscleGroups":["CHEST","SHOULDERS"],"equipment":"OTHER","tags":["weighted bench dip"],"media":[{"id":"weighted-bench-dip-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Bench_Dip/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"weighted-bench-dip-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Bench_Dip/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Trizeps, unterstützt von Brust, Schultern.","instructions":null}},{"id":"ex-weighted-crunch","slug":"weighted-crunch","name":"Weighted Crunch","description":"Dumbbell exercise for the core.","instructions":["The Weighted Crunch is a variation of the classic crunch exercise that involves adding resistance (a weight) to increase the intensity of the abdominal work.","Lay down","(Optional) Bend your knees to add difficulty","(Optional) Bend your knees and let your feet rest on a bench or a box or something (90 degree angle on knees)","Lift your head and torso while bending your back forward (if you don't it's a sit-up and also involves some back muscles). The higher you go, the more you should feel your abs contracting.","Go back to starting position an repeat"],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["weighted crunch","crunch mit zusatzgewicht"],"media":[{"id":"weighted-crunch-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1648/63ae02d6-6dd9-4e9e-84da-d4905e78a33c.jpg","caption":"Weighted Crunch","attribution":"wger.de · AlucardEvil40","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Crunch mit Zusatzgewicht","description":"Übung (Kurzhantel) für den Rumpf.","instructions":["Der Crunch mit Zusatzgewicht ist eine Variante des klassischen Crunch, bei der ein Widerstand (ein Gewicht) hinzugefügt wird, um die Intensität der Bauchmuskelarbeit zu erhöhen.","Lege dich hin","(Optional) Beuge die Knie, um die Übung zu erschweren","(Optional) Beuge die Knie und lege deine Füße auf einer Bank, einer Box oder etwas Ähnlichem ab (90-Grad-Winkel in den Knien)","Hebe Kopf und Oberkörper an, während du den Rücken nach vorne rundest (tust du das nicht, ist es ein Sit-up und beansprucht auch einige Rückenmuskeln). Je höher du kommst, desto stärker solltest du das Anspannen deiner Bauchmuskulatur spüren.","Kehre in die Ausgangsposition zurück und wiederhole"]}},{"id":"ex-weighted-crunches","slug":"weighted-crunches","name":"Weighted Crunches","description":"Accessory exercise for the core.","instructions":["Lie flat on your back with your feet flat on the ground or resting on a bench with your knees bent at a 90 degree angle.","Hold a weight to your chest, or you may hold it extended above your torso. This will be your starting position.","Now, exhale and slowly begin to roll your shoulders off the floor. Your shoulders should come up off the floor about 4 inches while your lower back remains on the floor.","At the top of the movement, flex your abdominals and hold for a brief pause.","Then inhale and slowly lower yourself back down to the starting position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["weighted crunches"],"media":[{"id":"weighted-crunches-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Crunches/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"weighted-crunches-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Crunches/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rumpf.","instructions":null}},{"id":"ex-weighted-jump-squat","slug":"weighted-jump-squat","name":"Weighted Jump Squat","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings, back assisting.","instructions":["Position a lightly loaded barbell across the back of your shoulders. You could also use a weighted vest, sandbag, or other type of resistance for this exercise.","The weight should be light enough that it doesn't slow you down significantly. Your feet should be just outside of shoulder width with your head and chest up. This will be your starting position.","Using a countermovement, squat partially down and immediately reverse your direction to explode off of the ground, extending through your hips, knees, and ankles. Maintain good posture throughout the jump.","As you return to the ground, absorb the impact through your legs."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","BACK"],"equipment":"BARBELL","tags":["weighted jump squat"],"media":[{"id":"weighted-jump-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Jump_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"weighted-jump-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Jump_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-weighted-pull-ups","slug":"weighted-pull-ups","name":"Weighted Pull Ups","description":"Accessory exercise for the back, with biceps assisting.","instructions":["Attach a weight to a dip belt and secure it around your waist. Grab the pull-up bar with the palms of your hands facing forward. For a medium grip, your hands should be spaced at shoulder width. Both arms should be extended in front of you holding the bar at the chosen grip.","You'll want to bring your torso back about 30 degrees while creating a curvature in your lower back and sticking your chest out. This will be your starting position.","Now, exhale and pull your torso up until your head is above your hands. Concentrate on squeezing yourshoulder blades back and down as you reach the top contracted position.","After a brief moment at the top contracted position, inhale and slowly lower your torso back to the starting position with your arms extended and your lats fully stretched."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS"],"equipment":"OTHER","tags":["weighted pull ups"],"media":[{"id":"weighted-pull-ups-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Pull_Ups/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"weighted-pull-ups-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Pull_Ups/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rücken, unterstützt von Bizeps.","instructions":null}},{"id":"ex-weighted-push-ups","slug":"weighted-push-ups","name":"Weighted push-ups","description":"Bodyweight exercise for the chest, with triceps assisting.","instructions":["Setup: Begin in a standard plank position with a weight plate balanced securely on your upper back.","Alignment: Maintain a straight line from your head to your heels, engaging your core to prevent your back from sagging.","Execution: Lower your body until your chest nearly touches the floor, keeping your elbows at a forty-five degrees.","Ascent: Press through your palms to return to the starting position, fully extending your arms."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["TRICEPS"],"equipment":"BODYWEIGHT","tags":["weighted push-ups","liegestütze mit zusatzgewicht"],"media":[{"id":"weighted-push-ups-wger-0","mediaType":"IMAGE","url":"https://wger.de/media/exercise-images/1902/d0c3f170-543c-4be4-bc70-5c6dc606406c.png","caption":"Weighted push-ups","attribution":"wger.de · nishant0712","license":"CC-BY-SA 4.0"}],"source":"wger","de":{"name":"Liegestütze mit Zusatzgewicht","description":"Übung (Körpergewicht) für die Brust, unterstützt von Trizeps.","instructions":["Aufbau: Beginne in einer normalen Plank-Position mit einer Gewichtsscheibe, die sicher auf deinem oberen Rücken balanciert.","Ausrichtung: Halte eine gerade Linie vom Kopf bis zu den Fersen und spanne deinen Rumpf an, damit dein Rücken nicht durchhängt.","Ausführung: Senke deinen Körper, bis deine Brust den Boden fast berührt, und halte die Ellbogen in einem 45-Grad-Winkel.","Aufwärtsbewegung: Drücke dich über die Handflächen zurück in die Ausgangsposition und strecke die Arme vollständig durch."]}},{"id":"ex-weighted-sissy-squat","slug":"weighted-sissy-squat","name":"Weighted Sissy Squat","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Standing upright, with feet at shoulder width and toes raised, use one hand to hold onto the beams of a squat rack and the opposite arm to hold a plate on top of your chest. This is your starting position.","As you use one arm to hold yourself, bend at the knees and slowly lower your torso toward the ground by bringing your pelvis and knees forward. Inhale as you go down and stop when your upper and lower legs almost create a 90-degree angle. Hold the stretch position for a second.","After your one second hold, use your thigh muscles to bring your torso back up to the starting position. Exhale as you move up.","Repeat for the recommended amount of times."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"BARBELL","tags":["weighted sissy squat"],"media":[{"id":"weighted-sissy-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Sissy_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"weighted-sissy-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Sissy_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-weighted-sit-ups-with-bands","slug":"weighted-sit-ups-with-bands","name":"Weighted Sit-Ups - With Bands","description":"Accessory exercise for the core.","instructions":["Start out by strapping the bands around the base of the decline bench. Place the handles towards the inside of the decline bench so that when lying down, you can reach for both of them.","Position your legs through the decline machine until they are secured. Now reach for the exercise bands with both hands. Use a pronated (palms forward) grip to grasp the handles. Position them near your collar bone and rotate your wrist to a neutral grip (palms facing the torso). Note: Your arms should remain stationary throughout the exercise. This is the starting position.","Move your torso upward until your upper body is perpendicular to the floor while exhaling. Hold the contraction for a second and lower your upper body back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"OTHER","tags":["weighted sit-ups - with bands"],"media":[{"id":"weighted-sit-ups-with-bands-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Sit-Ups_-_With_Bands/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"weighted-sit-ups-with-bands-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Sit-Ups_-_With_Bands/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für den Rumpf.","instructions":null}},{"id":"ex-weighted-squat","slug":"weighted-squat","name":"Weighted Squat","description":"Accessory exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["Start by positioning two flat benches shoulder width apart from each other. Stand on top of them and wrap the weighted belt around your waist with the amount of weight you feel comfortable with. Make sure your toes are facing out.","Once you are standing straight up with the weight hanging in between your legs, position your arms so that they are fully extended to the side of your body. This is the starting position.","Begin by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that are perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to move the body back up by pushing the floor of the flat bench with the ball of your foot mainly as you straighten the legs again and go back to the starting position. Exhale as you perform this portion of the exercise.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"OTHER","tags":["weighted squat"],"media":[{"id":"weighted-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"weighted-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-wide-grip-barbell-bench-press","slug":"wide-grip-barbell-bench-press","name":"Wide-Grip Barbell Bench Press","description":"Barbell exercise for the chest, with shoulders, triceps assisting.","instructions":["Lie back on a flat bench with feet firm on the floor. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["wide-grip barbell bench press"],"media":[{"id":"wide-grip-barbell-bench-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Barbell_Bench_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"wide-grip-barbell-bench-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Barbell_Bench_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-wide-grip-decline-barbell-bench-press","slug":"wide-grip-decline-barbell-bench-press","name":"Wide-Grip Decline Barbell Bench Press","description":"Barbell exercise for the chest, with shoulders, triceps assisting.","instructions":["Lie back on a decline bench with the feet securely locked at the front of the bench. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your lower chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["wide-grip decline barbell bench press"],"media":[{"id":"wide-grip-decline-barbell-bench-press-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Decline_Barbell_Bench_Press/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"wide-grip-decline-barbell-bench-press-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Decline_Barbell_Bench_Press/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-wide-grip-decline-barbell-pullover","slug":"wide-grip-decline-barbell-pullover","name":"Wide-Grip Decline Barbell Pullover","description":"Barbell exercise for the chest, with shoulders, triceps assisting.","instructions":["Lie down on a decline bench with both legs securely locked in position. Reach for the barbell behind the head using a pronated grip (palms facing out). Make sure to grab the barbell wider than shoulder width apart for this exercise. Slowly lift the barbell up from the floor by using your arms.","When positioned properly, your arms should be fully extended and perpendicular to the floor. This is the starting position.","Begin by moving the barbell back down in a semicircular motion as if you were going to place it on the floor, but instead, stop when the arms are parallel to the floor. Tip: Keep the arms fully extended at all times. The movement should only happen at the shoulder joint. Inhale as you perform this portion of the movement.","Now bring the barbell up while exhaling until you are back at the starting position. Remember to keep full control of the barbell at all times.","Repeat the movement for the prescribed amount of repetitions of your training program.","When finished with your set, slowly lower the barbell back down until it is level with your head and release it."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"CHEST","secondaryMuscleGroups":["SHOULDERS","TRICEPS"],"equipment":"BARBELL","tags":["wide-grip decline barbell pullover"],"media":[{"id":"wide-grip-decline-barbell-pullover-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Decline_Barbell_Pullover/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"wide-grip-decline-barbell-pullover-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Decline_Barbell_Pullover/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Brust, unterstützt von Schultern, Trizeps.","instructions":null}},{"id":"ex-wide-grip-pulldown-behind-the-neck","slug":"wide-grip-pulldown-behind-the-neck","name":"Wide-Grip Pulldown Behind The Neck","description":"Cable exercise for the back, with biceps, shoulders assisting.","instructions":["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso and head forward. Think of an imaginary line from the center of the bar down to the back of your neck. This is your starting position.","As you breathe out, bring the bar down until it touches the back of your neck by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.","After a second on the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.","Repeat this motion for the prescribed amount of repetitions."],"category":"CABLE","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","SHOULDERS"],"equipment":"CABLE","tags":["wide-grip pulldown behind the neck"],"media":[{"id":"wide-grip-pulldown-behind-the-neck-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Pulldown_Behind_The_Neck/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"wide-grip-pulldown-behind-the-neck-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Pulldown_Behind_The_Neck/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kabelzug) für den Rücken, unterstützt von Bizeps, Schultern.","instructions":null}},{"id":"ex-wide-grip-rear-pull-up","slug":"wide-grip-rear-pull-up","name":"Wide-Grip Rear Pull-Up","description":"Bodyweight exercise for the back, with biceps, shoulders assisting.","instructions":["Grab the pull-up bar with the palms facing forward using a wide grip.","As you have both arms extended in front of you holding the bar, bring your torso forward and head so that there is an imaginary line from the pull-up bar to the back of your neck. This is your starting position.","Pull your torso up until the bar is near the back of your neck. To do this, draw the shoulders and upper arms down and back while slightly leaning your head forward. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.","Repeat this motion for the prescribed amount of repetitions."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"BACK","secondaryMuscleGroups":["BICEPS","SHOULDERS"],"equipment":"BODYWEIGHT","tags":["wide-grip rear pull-up"],"media":[{"id":"wide-grip-rear-pull-up-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Rear_Pull-Up/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"wide-grip-rear-pull-up-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Rear_Pull-Up/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rücken, unterstützt von Bizeps, Schultern.","instructions":null}},{"id":"ex-wide-grip-standing-barbell-curl","slug":"wide-grip-standing-barbell-curl","name":"Wide-Grip Standing Barbell Curl","description":"Barbell exercise for the biceps.","instructions":["Stand up with your torso upright while holding a barbell at the wide outer handle. The palm of your hands should be facing forward. The elbows should be close to the torso. This will be your starting position.","While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["wide-grip standing barbell curl"],"media":[{"id":"wide-grip-standing-barbell-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Standing_Barbell_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"wide-grip-standing-barbell-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Standing_Barbell_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für den Bizeps.","instructions":null}},{"id":"ex-wide-stance-barbell-squat","slug":"wide-stance-barbell-squat","name":"Wide Stance Barbell Squat","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings, back assisting.","instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a wider-than-shoulder-width stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance, and also maintain a straight back. This will be your starting position.","Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS","BACK"],"equipment":"BARBELL","tags":["wide stance barbell squat"],"media":[{"id":"wide-stance-barbell-squat-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide_Stance_Barbell_Squat/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"wide-stance-barbell-squat-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide_Stance_Barbell_Squat/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-wide-stance-stiff-legs","slug":"wide-stance-stiff-legs","name":"Wide Stance Stiff Legs","description":"Barbell exercise for the hamstrings, with quadriceps, glutes, back assisting.","instructions":["Begin with a barbell loaded on the floor. Adopt a wide stance, and then bend at the hips to grab the bar. Your hips should be as far back as possible, and your legs nearly straight. Keep your back straight, and your head and chest up. This will be your starting position.","Begin the movement be engaging the hips, driving them forward as you allow the arms to hang straight. Continue until you are standing straight up, and then slowly return the weight to the starting position. For successive reps, the weight need not touch the floor."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"HAMSTRINGS","secondaryMuscleGroups":["QUADRICEPS","GLUTES","BACK"],"equipment":"BARBELL","tags":["wide stance stiff legs"],"media":[{"id":"wide-stance-stiff-legs-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide_Stance_Stiff_Legs/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"wide-stance-stiff-legs-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide_Stance_Stiff_Legs/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelrückseite, unterstützt von Oberschenkelvorderseite, Po, Rücken.","instructions":null}},{"id":"ex-wind-sprints","slug":"wind-sprints","name":"Wind Sprints","description":"Bodyweight exercise for the core.","instructions":["Hang from a pull-up bar using a pronated grip. Your arms and legs should be extended. This will be your starting position.","Begin by quickly raising one knee as high as you can. Do not swing your body or your legs. 3","Immediately reverse the motion, returning that leg to the starting position. Simultaneously raise the opposite knee as high as possible.","Continue alternating between legs until the set is complete."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["wind sprints"],"media":[{"id":"wind-sprints-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wind_Sprints/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"wind-sprints-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wind_Sprints/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für den Rumpf.","instructions":null}},{"id":"ex-windmills","slug":"windmills","name":"Windmills","description":"Equipment-free exercise for the glutes, with hamstrings, back assisting.","instructions":["Lie on your back with your arms extended out to the sides and your legs straight. This will be your starting position.","Lift one leg and quickly cross it over your body, attempting to touch the ground near the opposite hand.","Return to the starting position, and repeat with the opposite leg. Continue to alternate for 10-20 repetitions."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"GLUTES","secondaryMuscleGroups":["HAMSTRINGS","BACK"],"equipment":"NONE","tags":["windmills"],"media":[{"id":"windmills-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Windmills/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"windmills-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Windmills/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (ohne Geräte) für den Po, unterstützt von Oberschenkelrückseite, Rücken.","instructions":null}},{"id":"ex-windshield-wipers","slug":"windshield-wipers","name":"Windshield Wipers","description":"Bodyweight exercise for the core.","instructions":["Hang from a pull-up bar, raise your legs to the ceiling. Move lower body from left to right with straight legs like a windshield wiper"],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"ABS_CORE","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["windshield wipers","scheibenwischer"],"media":[],"source":"wger","de":{"name":"Scheibenwischer","description":"Übung (Körpergewicht) für den Rumpf.","instructions":["Hänge dich an eine Klimmzugstange und hebe deine Beine zur Decke. Bewege deinen Unterkörper mit gestreckten Beinen von links nach rechts wie ein Scheibenwischer."]}},{"id":"ex-wrist-circles","slug":"wrist-circles","name":"Wrist Circles","description":"Bodyweight exercise for the forearms.","instructions":["Start by standing straight with your feet being shoulder width apart from each other. Elevate your arms to the side of you until they are fully extended and parallel to the floor at a height that is evenly aligned with your shoulders. Tip: Your torso and arms should form the letter \"T: Your palms should be facing down. This is the starting position.","Keeping your entire body stationary except for the wrists, begin to rotate both wrists forward in a circular motion. Tip: Pretend that you are trying to draw circles by using your hands as the brush. Breathe normally as you perform this exercise.","Repeat for the recommended amount of repetitions."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["wrist circles"],"media":[{"id":"wrist-circles-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wrist_Circles/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"wrist-circles-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wrist_Circles/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Körpergewicht) für die Unterarme.","instructions":null}},{"id":"ex-wrist-curl-dumbbells","slug":"wrist-curl-dumbbells","name":"Wrist curl, dumbbells","description":"Dumbbell exercise for the biceps.","instructions":["Sitting on a bench, grab the dumbbell with your palms facing up","and your hands shoulder-width apart. Rest your forearms on your thighs","and allow your wrists to hang over your knees.","Perform the movement by","curling your palms and wrists towards your face.","(optional/variable) Pause at the top.","Slowly return to the starting position."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"DUMBBELL","tags":["wrist curl, dumbbells","handgelenk-curl mit kurzhanteln"],"media":[],"source":"wger","de":{"name":"Handgelenk-Curl mit Kurzhanteln","description":"Übung (Kurzhantel) für den Bizeps.","instructions":["Setze dich auf eine Bank und greife die Kurzhantel mit den Handflächen nach oben","und schulterbreitem Handabstand. Lege deine Unterarme auf den Oberschenkeln ab","und lass die Handgelenke über die Knie hinaushängen.","Führe die Bewegung aus, indem du","Handflächen und Handgelenke in Richtung deines Gesichts einrollst.","(optional/variabel) Halte kurz oben inne.","Kehre langsam in die Ausgangsposition zurück."]}},{"id":"ex-wrist-roller","slug":"wrist-roller","name":"Wrist Roller","description":"Accessory exercise for the forearms, with shoulders assisting.","instructions":["To begin, stand straight up grabbing a wrist roller using a pronated grip (palms facing down). Your feet should be shoulder width apart.","Slowly lift both arms until they are fully extended and parallel to the floor in front of you. Note: Make sure the rope is not wrapped around the roller. Your entire body should be stationary except for the forearms. This is the starting position.","Rotate one wrist at a time in an upward motion to bring the weight up to the bar by rolling the rope around the roller.","Once the weight has reached the bar, slowly begin to lower the weight back down by rotating the wrist in a downward motion until the weight reaches the starting position.","Repeat for the prescribed amount of repetitions in your program."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":["SHOULDERS"],"equipment":"OTHER","tags":["wrist roller"],"media":[{"id":"wrist-roller-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wrist_Roller/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"wrist-roller-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wrist_Roller/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Hilfsmittel) für die Unterarme, unterstützt von Schultern.","instructions":null}},{"id":"ex-wrist-rotations-with-straight-bar","slug":"wrist-rotations-with-straight-bar","name":"Wrist Rotations with Straight Bar","description":"Barbell exercise for the forearms.","instructions":["Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width. This will be your starting position.","Alternating between each of your hands, perform the movement by extending the wrist as though you were rolling up a newspaper. Continue alternating back and forth until failure.","Reverse the motion by flexing the wrist, rolling the opposite direction. Continue the alternating motion until failure."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"FOREARMS","secondaryMuscleGroups":[],"equipment":"BARBELL","tags":["wrist rotations with straight bar"],"media":[{"id":"wrist-rotations-with-straight-bar-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wrist_Rotations_with_Straight_Bar/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"wrist-rotations-with-straight-bar-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wrist_Rotations_with_Straight_Bar/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Unterarme.","instructions":null}},{"id":"ex-wrist-stretch","slug":"wrist-stretch","name":"Wrist Stretch","description":"Bodyweight exercise for the biceps.","instructions":["Extend your right arm straight out in front of you, with your palm facing up (fingers pointing toward the floor). Using your left hand, gently pull the fingers of your right hand toward you until you feel a stretch in your forearm and biceps."],"category":"STRETCH","exerciseType":"STRETCHING","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":[],"equipment":"BODYWEIGHT","tags":["wrist stretch","handgelenks-dehnung"],"media":[],"source":"wger","de":{"name":"Handgelenks-Dehnung","description":"Übung (Körpergewicht) für den Bizeps.","instructions":["Strecke deinen rechten Arm vor dir aus, die Handfläche zeigt nach oben (Finger zeigen zum Boden). Ziehe mit der linken Hand die Finger der rechten Hand sanft zu dir heran, bis du ein Ziehen im Unterarm und Bizeps spürst."]}},{"id":"ex-yoga-exercise-cow-cat","slug":"yoga-exercise-cow-cat","name":"Yoga exercise: Cow-cat","description":"Bodyweight exercise for the shoulders, with back, core assisting.","instructions":["First get into the four-footed stance. The hands are underneath the shoulders. The fingers are fanned out wide and ensure a stable stance. It is best to rest your front body weight on your thumbs and index fingers. Now place your legs hip-width apart on the yoga mat. Your thighs should be vertically below your hips. Make sure that your weight is evenly distributed between your hands and knees. Your head is an extension of your spine and you are looking down at your mat. Your back is in a neutral position. Breathe in deeply and start with the cat. With the next exhalation, round your back vertebra by vertebra. Try to pull yourself as far as possible towards the ceiling. Pull your head towards your chest and tilt your pelvis. Now inhale deeply and move into the opposite position, cow pose. Bend your back down, pull your shoulders back slightly and lift your head as far as is comfortable for you. Your gaze is directed upwards. Breathe out consciously and switch back to the cat. With the next exhalation, switch back to cow. Repeat the exercise a few times and make sure that you are in the flow."],"category":"BODYWEIGHT","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK","ABS_CORE"],"equipment":"BODYWEIGHT","tags":["yoga exercise: cow-cat","yoga-übung: katze-kuh"],"media":[],"source":"wger","de":{"name":"Yoga-Übung: Katze-Kuh","description":"Übung (Körpergewicht) für die Schultern, unterstützt von Rücken, Rumpf.","instructions":["Gehe zuerst in den Vierfüßlerstand. Die Hände sind unter den Schultern. Die Finger sind weit gespreizt und sorgen für einen stabilen Stand. Am besten verlagerst du dein vorderes Körpergewicht auf deine Daumen und Zeigefinger. Setze nun deine Beine hüftbreit auf der Yogamatte ab. Deine Oberschenkel sollten senkrecht unter deinen Hüften sein. Achte darauf, dass dein Gewicht gleichmäßig zwischen deinen Händen und Knien verteilt ist. Dein Kopf ist eine Verlängerung deiner Wirbelsäule und du blickst nach unten auf deine Matte. Dein Rücken ist in einer neutralen Position. Atme tief ein und beginne mit der Katze. Mit der nächsten Ausatmung rundest du deinen Rücken Wirbel für Wirbel. Versuche, dich so weit wie möglich zur Decke zu ziehen. Ziehe deinen Kopf zur Brust und kippe dein Becken. Atme nun tief ein und gehe in die Gegenposition, die Kuh-Haltung. Beuge deinen Rücken nach unten, ziehe deine Schultern leicht zurück und hebe deinen Kopf so weit an, wie es für dich angenehm ist. Dein Blick ist nach oben gerichtet. Atme bewusst aus und wechsle zurück zur Katze. Mit der nächsten Ausatmung wechselst du zurück zur Kuh. Wiederhole die Übung einige Male und achte darauf, dass du im Fluss bist."]}},{"id":"ex-ytwl-exercise","slug":"ytwl-exercise","name":"YTWL Exercise","description":"Dumbbell exercise for the shoulders, with back assisting.","instructions":["Purpose: Improves shoulder stability, posture, and scapular (shoulder blade) control. Often used in physical therapy and warm-ups.","Starting Position:","Stand with feet shoulder-width apart. Hinge forward at the hips (like a","deadlift) keeping your back flat, or lie face down on an incline bench.","Keep your thumbs pointing up throughout.","Y (Arms up):","Extend both arms straight forward and upward at a 135-degree angle from","your body, forming a \"Y\". Squeeze your shoulder blades together at the"],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"SHOULDERS","secondaryMuscleGroups":["BACK"],"equipment":"DUMBBELL","tags":["ytwl exercise","ytwl-übung"],"media":[],"source":"wger","de":{"name":"YTWL-Übung","description":"Übung (Kurzhantel) für die Schultern, unterstützt von Rücken.","instructions":["Zweck: Verbessert die Schulterstabilität, die Haltung und die Kontrolle der Schulterblätter. Wird häufig in der Physiotherapie und beim Aufwärmen eingesetzt.","Ausgangsposition:","Stehe mit schulterbreit aufgestellten Füßen. Beuge dich aus der Hüfte nach vorne (wie beim","Kreuzheben) und halte deinen Rücken gerade, oder lege dich mit dem Gesicht nach unten auf eine Schrägbank.","Halte deine Daumen die ganze Zeit nach oben gerichtet.","Y (Arme nach oben):","Strecke beide Arme gerade nach vorne und oben in einem 135-Grad-Winkel zu","deinem Körper, sodass sie ein „Y“ bilden. Ziehe deine Schulterblätter am"]}},{"id":"ex-zercher-squats","slug":"zercher-squats","name":"Zercher Squats","description":"Barbell exercise for the quadriceps, with calves, glutes, hamstrings assisting.","instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. The correct height should be anywhere above the waist but below the chest. Once the correct height is chosen and the bar is loaded, lock your hands together and place the bar on top of your arms in between the forearm and upper arm.","Lift the bar up so that it is resting on top of your forearms. If you are holding the bar properly, it should look as if you have your arms crossed but with a bar running across them.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the ball of your foot mainly as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"COMPOUND","exerciseType":"STRENGTH","primaryMuscleGroup":"QUADRICEPS","secondaryMuscleGroups":["CALVES","GLUTES","HAMSTRINGS"],"equipment":"BARBELL","tags":["zercher squats"],"media":[{"id":"zercher-squats-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zercher_Squats/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"zercher-squats-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zercher_Squats/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Langhantel) für die Oberschenkelvorderseite, unterstützt von Waden, Po, Oberschenkelrückseite.","instructions":null}},{"id":"ex-zottman-curl","slug":"zottman-curl","name":"Zottman Curl","description":"Dumbbell exercise for the biceps, with forearms assisting.","instructions":["Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.","Make sure the palms of the hands are facing each other. This will be your starting position.","While holding the upper arm stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Your wrist should rotate so that you have a supinated (palms up) grip. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a second as you squeeze the biceps.","Now during the contracted position, rotate your wrist until you now have a pronated (palms facing down) grip with the thumb at a higher position than the pinky.","Slowly begin to bring the dumbbells back down using the pronated grip.","As the dumbbells close your thighs, start rotating the wrist so that you go back to a neutral (palms facing your body) grip.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"DUMBBELL","tags":["zottman curl","zottman-curl"],"media":[{"id":"zottman-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zottman_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"zottman-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zottman_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":"Zottman-Curl","description":"Übung (Kurzhantel) für den Bizeps, unterstützt von Unterarme.","instructions":["Curle die Gewichte mit nach vorne zeigenden Handflächen zu deinen Schultern. Drehe deine Hände so, dass deine Handflächen nach unten zeigen, und senke die Gewichte langsam wieder ab. Drehe schließlich deine Handflächen wieder nach vorne."]}},{"id":"ex-zottman-preacher-curl","slug":"zottman-preacher-curl","name":"Zottman Preacher Curl","description":"Dumbbell exercise for the biceps, with forearms assisting.","instructions":["Grab a dumbbell in each hand and place your upper arms on top of the preacher bench or the incline bench. The dumbbells should be held at shoulder height and the elbows should be flexed. Hold the dumbbells with the palms of your hands facing down. This will be your starting position.","As you breathe in, slowly lower the dumbbells keeping the palms down until your upper arm is extended and your biceps are fully stretched.","Now rotate your wrists once you are at the bottom of the movement so that the palms of the hands are facing up.","As you exhale, use your biceps to curl the weights up until they are fully contracted and the dumbbells are at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.","Squeeze the biceps hard for a second at the contracted position and rotate your wrists so that the palms are facing down again.","Repeat for the recommended amount of repetitions."],"category":"ISOLATION","exerciseType":"STRENGTH","primaryMuscleGroup":"BICEPS","secondaryMuscleGroups":["FOREARMS"],"equipment":"DUMBBELL","tags":["zottman preacher curl"],"media":[{"id":"zottman-preacher-curl-frame-0","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zottman_Preacher_Curl/0.jpg","caption":"Start position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"},{"id":"zottman-preacher-curl-frame-1","mediaType":"IMAGE","url":"https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zottman_Preacher_Curl/1.jpg","caption":"Finish position","attribution":"Free Exercise DB (Public Domain)","license":"Unlicense"}],"source":"free-exercise-db","de":{"name":null,"description":"Übung (Kurzhantel) für den Bizeps, unterstützt von Unterarme.","instructions":null}}];
